        free(input_buffer);
        return;
    }

    // Apply the transformation rules to the input buffer and write the result to the output file
    for (int i = 0; i < num_rules; i++) {
        TransformationRule *rule = &rule_list[i];
        if (rule->rule_type == 0) { // static rule
            void (*func)(void *) = rule->rule_func;
            func(input_buffer);
        } else { // dynamic rule
