#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <resolv.h>

struct log_entry {
    char *hostname;
    int user_id;
    long timestamp;
    struct in_addr ip_address;
};

void process_log(char *line) {
    // Split the line into fields using strtok()
    char *token = strtok(line, ",");
    while (token != NULL) {
        if (strcmp(token, "hostname") == 0) {
            struct log_entry *entry = malloc(sizeof(struct log_entry));
            entry->hostname = strdup(token);
            token = strtok(NULL, ",");
            entry->user_id = atoi(token);
            token = strtok(NULL, ",");
            entry->timestamp = atol(token);
            // Resolve the hostname to an IP address using getaddrinfo()
            struct addrinfo hints;
            memset(&hints, 0, sizeof(struct addrinfo));
            hints.ai_family = AF_INET;
            hints.ai_socktype = SOCK_STREAM;
            struct addrinfo *result;
            if (getaddrinfo(entry->hostname, NULL, &hints, &result) == 0) {
                entry->ip_address = ((struct sockaddr_in *)result->ai_addr)->sin_addr;
                freeaddrinfo(result);
            } else {
                // Handle DNS resolution error
                printf("DNS resolution failed for %s\n", entry->hostname);
            }
            // Free memory allocated for the hostname
            free(entry->hostname);
        }
        token = strtok(NULL, ",");
    }
}

int main() {
    FILE *file = fopen("log.txt", "r");
    char line[1024];
    while (fgets(line, 1024, file) != NULL) {
        process_log(line);
    }
    fclose(file);
    return 0;
}
