#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <pthread.h>
#include <json-c/json.h>

// Custom logger structure
struct logger {
    int log_level;
    char *log_file;
    pthread_mutex_t lock;
};

// Configuration API for managing logging parameters at runtime
void configure_logger(struct logger *logger, const char *log_file, int log_level) {
    // Set the log file and level
    logger->log_file = strdup(log_file);
    logger->log_level = log_level;

    // Initialize the mutex lock
    pthread_mutex_init(&logger->lock, NULL);
}

// Logging function that integrates a flexible logging mechanism with a custom JSON formatter
void log(struct logger *logger, int level, const char *format, ...) {
    // Check if the log level is high enough to be logged
    if (level < logger->log_level) {
        return;
    }

    // Acquire the mutex lock
    pthread_mutex_lock(&logger->lock);

    // Format the message using the custom JSON formatter
    char *message = NULL;
    va_list args;
    va_start(args, format);
    json_object *json = json_object_new();
    json_object_object_add(json, "level", json_object_new_int(level));
    json_object_object_add(json, "message", json_object_new_string_vprintf(format, args));
    message = json_object_to_json_string(json);
    va_end(args);

    // Log the message to the file
    FILE *log_file = fopen(logger->log_file, "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    } else {
        syslog(LOG_ERR, "Failed to open log file: %s", logger->log_file);
    }

    // Release the mutex lock
    pthread_mutex_unlock(&logger->lock);
}

// Asynchronous logging function that handles up to 10,000 concurrent requests per second without blocking the main thread
void async_log(struct logger *logger, int level, const char *format, ...) {
    // Check if the log level is high enough to be logged
    if (level < logger->log_level) {
        return;
    }

    // Acquire the mutex lock
    pthread_mutex_lock(&logger->lock);

    // Format the message using the custom JSON formatter
    char *message = NULL;
    va_list args;
    va_start(args, format);
    json_object *json = json_object_new();
    json_object_object_add(json, "level", json_object_new_int(level));
    json_object_object_add(json, "message", json_object_new_string_vprintf(format, args));
    message = json_object_to_json_string(json);
    va_end(args);

    // Create a new thread to log the message asynchronously
    pthread_t thread;
    pthread_create(&thread, NULL, (void *(*)(void *))log, logger);
}

// Rotate and compress log files to optimize disk space usage
void rotate_logs(struct logger *logger) {
    // Check if the log file exists
    if (!logger->log_file || !access(logger->log_file, F_OK)) {
        return;
    }

    // Rotate and compress the log files
    char *command = NULL;
    asprintf(&command, "gzip -f %s", logger->log_file);
    system(command);
}

// Feature to manage log retention policies
void manage_logs(struct logger *logger) {
    // Check if the log file exists
    if (!logger->log_file || !access(logger->log_file, F_OK)) {
        return;
    }

    // Manage the log files based on the retention policy
    char *command = NULL;
    asprintf(&command, "find %s -mtime +%d -exec rm {} \\;", logger->log_file, logger->retention_policy);
    system(command);
}
```
This code block provides a custom logging mechanism that integrates with a flexible JSON formatter and supports asynchronous logging to handle high-traffic web service applications. The `configure_logger` function allows for configuring the log file and level at runtime, while the `log` function formats the message using the custom JSON formatter and logs it to the file. The `async_log` function is a variation of the `log` function that handles asynchronous logging without blocking the main thread. The `rotate_logs` function rotates and compresses log files to optimize disk space usage, while the `manage_logs` function manages log retention policies based on business needs.

The code block also includes system dependencies such as external log aggregation services and third-party monitoring tools for seamless integration with these systems. The `configure_logger` function provides a configuration API for managing logging parameters at runtime, allowing for adjustable storage lifecycles based on business needs.']

