        // Implement the logic for calculating weaknesses based on environmental conditions
        // and the type of the Pokemon. This method should be extensible and modular,
        // allowing for easy updates and extensions without changing core code.
    }

    private List<String> defaultWeaknesses() {
        return List.of("Ground", "Rock");
    }
}
