fn parse_files(config: &Config) -> Vec<String> {
    let mut files = vec![];
    for entry in fs::read_dir(&config.directory).unwrap() {
        let path = entry.unwrap().path();
        if path.is_file() && config.extensions.contains(&path.extension()) {
            files.push(parse_file(&path, &config));
        } else if path.is_dir() {
