using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace MyCompany.MyProject
{
    public class SqlQueryBuilder
    {
        private readonly string _connectionString;
        private readonly List<string> _tables;
        private readonly Dictionary<string, object> _filterCriteria;
        private readonly bool _orderBy;
        private readonly int _pageSize;
        private readonly int _pageNumber;

        public SqlQueryBuilder(string connectionString, List<string> tables, Dictionary<string, object> filterCriteria, bool orderBy = false, int pageSize = 0, int pageNumber = 1)
        {
            _connectionString = connectionString;
            _tables = tables;
            _filterCriteria = filterCriteria;
            _orderBy = orderBy;
            _pageSize = pageSize;
            _pageNumber = pageNumber;
        }

        public async Task<IDataReader> ExecuteQueryAsync()
        {
            // Build the SQL query
            var sqlQuery = new StringBuilder();
            sqlQuery.Append("SELECT ");
            if (_orderBy)
            {
                sqlQuery.Append("TOP " + _pageSize * (_pageNumber - 1) + " ");
            }
            else
            {
                sqlQuery.Append("* ");
            }
            sqlQuery.Append("FROM ");
            sqlQuery.Append(string.Join(", ", _tables));
            if (_filterCriteria != null && _filterCriteria.Count > 0)
            {
                sqlQuery.Append(" WHERE ");
                var first = true;
                foreach (var filter in _filterCriteria)
                {
                    if (!first)
                    {
                        sqlQuery.Append(" AND ");
                    }
                    else
                    {
                        first = false;
                    }
                    sqlQuery.Append(filter.Key + " = @" + filter.Key);
                }
            }
            if (_orderBy)
            {
                sqlQuery.Append(" ORDER BY ");
                var first = true;
                foreach (var order in _filterCriteria)
                {
                    if (!first)
                    {
                        sqlQuery.Append(", ");
                    }
                    else
                    {
                        first = false;
                    }
                    sqlQuery.Append(order.Key);
                }
            }

            // Create a parameterized SQL command
            var command = new SqlCommand(sqlQuery.ToString(), new SqlConnection(_connectionString));
            foreach (var filter in _filterCriteria)
            {
                command.Parameters.AddWithValue("@" + filter.Key, filter.Value);
            }

            // Execute the query and return an IDataReader
            var reader = await command.ExecuteReaderAsync();
            return reader;
        }
    }
}
```
