public static string ParseConfigFile(string configFilePath)
{
    try
    {
        // Load the XML configuration file using XPath
        XmlDocument doc = new XmlDocument();
        doc.Load(configFilePath);

        // Find the first element with the specified name
        XmlNode node = doc.SelectSingleNode("//*[local-name()='" + elementName + "']");

        if (node != null)
        {
            // Dynamically create a new directory based on the element's attributes
            string dirPath = CreateDirectory(node);

            // Validate the directory path and set an environment variable if necessary
            if (!string.IsNullOrEmpty(dirPath))
            {
                Environment.SetEnvironmentVariable("DIR_PATH", dirPath, EnvironmentVariableTarget.Process);
            }
        }
        else
        {
            // Return a default directory path based on predefined logic
            string defaultDirPath = GetDefaultDirectoryPath();
            if (!string.IsNullOrEmpty(defaultDirPath))
            {
                return defaultDirPath;
            }
        }
    }
    catch (Exception ex)
    {
        // Log the error and return a default directory path
        Console.WriteLine("Error parsing XML configuration file: " + ex.Message);
        string defaultDirPath = GetDefaultDirectoryPath();
        if (!string.IsNullOrEmpty(defaultDirPath))
        {
            return defaultDirPath;
        }
    }
}

private static string CreateDirectory(XmlNode node)
{
    // Dynamically create a new directory based on the element's attributes
    string dirName = node.Attributes["name"].Value;
    string dirPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments), dirName);

    if (!Directory.Exists(dirPath))
    {
        Directory.CreateDirectory(dirPath);
    }

    return dirPath;
}

private static string GetDefaultDirectoryPath()
{
    // Return a default directory path based on predefined logic
    string defaultDirName = "My Documents";
    string defaultDirPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments), defaultDirName);

    if (!Directory.Exists(defaultDirPath))
    {
        Directory.CreateDirectory(defaultDirPath);
    }

    return defaultDirPath;
}
