        }
    } catch (Exception $e) {
        $db->rollBack();
        return json_encode(['message' => 'error', 'data' => ['Database error']]);
    }
    $db->commit();

    // Optimize the function for performance under heavy load, taking into account the number of requests per second and memory usage. Balance between caching and direct database access to minimize latency.
    if ($cache->has('user-accounts')) {
        $userAccounts = $cache->get('user-accounts');
    } else {
