        $cache->set('user-accounts', $userAccounts);
    }
    if ($operation === 'create') {
        $userAccounts[] = [
            'id' => $userAccountId,
            'name' => $request['name'],
            'email' => $request['email'],
            'password' => password_hash($request['password'], PASSWORD_DEFAULT),
        ];
    } elseif ($operation === 'update') {
        foreach ($userAccounts as &$userAccount) {
            if ($userAccount['id'] == $request['id']) {
