function extractGuidelines(document) {
  // Initialize an object to store the extracted guidelines
  const guidelines = {};

  // Iterate over each section in the document
  for (const section of document.sections) {
    // Check if the section contains any metadata tags
    if (section.metadata) {
      // Extract the type of guideline from the metadata
      const type = section.metadata.type;

      // Initialize an array to store the extracted text sections
      let guidelinesArray = [];

      // Check if the guidelines object already has a key for this type
      if (guidelines[type]) {
        // If it does, add the section to the existing array
        guidelines[type].push(section.text);
      } else {
        // If not, create a new array and add the section to it
        guidelinesArray = [section.text];
        guidelines[type] = guidelinesArray;
      }
    }
  }

  return guidelines;
}
```
