const { EventEmitter } = require('events');
const { MessageQueue } = require('message-queue');
const { PersistentStorage } = require('persistent-storage');

class ServiceManager extends EventEmitter {
  constructor() {
    super();
    this.instances = {};
    this.thresholds = {};
    this.messagingQueue = new MessageQueue();
    this.storage = new PersistentStorage();
  }

  startInstance(instanceId) {
    const instance = this.instances[instanceId];
    if (instance && instance.state === 'stopped') {
      instance.start();
      this.messagingQueue.sendMessage(`${instanceId}:started`);
      this.storage.logStateChange(instanceId, 'start');
    }
  }

  stopInstance(instanceId) {
    const instance = this.instances[instanceId];
    if (instance && instance.state === 'running') {
      instance.stop();
      this.messagingQueue.sendMessage(`${instanceId}:stopped`);
      this.storage.logStateChange(instanceId, 'stop');
    }
  }

  pauseInstance(instanceId) {
    const instance = this.instances[instanceId];
    if (instance && instance.state === 'running') {
      instance.pause();
      this.messagingQueue.sendMessage(`${instanceId}:paused`);
      this.storage.logStateChange(instanceId, 'pause');
    }
  }

  setThreshold(instanceId, threshold) {
    this.thresholds[instanceId] = threshold;
  }

  getInstanceStatus(instanceId) {
    const instance = this.instances[instanceId];
    if (instance) {
      return instance.state;
    } else {
      return 'unknown';
    }
  }
}

module.exports = ServiceManager;
