function fetchMatchingElements(rootElement, selector, callback = null, depthLimit = 5) {
  if (!rootElement || !selector) return [];

  // Handle edge cases
  if (depthLimit <= 0) return [];
  if (!document.readyState === "complete") return [];

  const matchingElements = [];

  // Recursively traverse the DOM tree starting from the root element
  function traverse(element, depth) {
    // Check if the current element matches the selector
    if (matchesSelector(element, selector)) {
      matchingElements.push(element);
    }

    // Check if the maximum depth limit has been reached
    if (depth >= depthLimit) return;

    // Recursively traverse the child elements
    element.childNodes.forEach((child) => {
      traverse(child, depth + 1);
    });
  }

  // Start traversing from the root element
  traverse(rootElement, 0);

  // Filter the matching elements using the callback function if provided
  if (callback) {
    matchingElements.filter((element) => callback(element));
  }

  return matchingElements;
}

// Utility function to check if an element matches a given selector
function matchesSelector(element, selector) {
