// Function to modify the file extension and name by appending a sequence of digits and a new file type
void update_filename(char* filename, char* new_extension) {
    // Get the length of the original filename
    int len = strlen(filename);

    // Allocate memory for the new filename
    char* new_filename = (char*)malloc(len + 10);

    // Copy the original filename to the new filename
    memcpy(new_filename, filename, len);

    // Append the sequence of digits and the new file type to the end of the filename
    sprintf(new_filename + len, "%d.%s", len, new_extension);

    // Free the memory allocated for the original filename
    free(filename);

    // Return the modified filename
    return new_filename;
}

// Function to load and execute multiple JavaScript files in a specified order
void load_and_execute_files(char** filenames, int num_filenames) {
    // Initialize an array to store the file handles
    FILE* files[num_filenames];

    // Loop through each filename and open the corresponding file
    for (int i = 0; i < num_filenames; i++) {
        // Open the file with read permissions
        files[i] = fopen(filenames[i], "r");

        // Check if the file was successfully opened
        if (files[i] == NULL) {
            // Handle the error by printing an error message and exiting the program
            printf("Error: unable to open file %s\n", filenames[i]);
            exit(1);
        }
    }

    // Loop through each filename and execute the corresponding JavaScript code
    for (int i = 0; i < num_filenames; i++) {
        // Read the contents of the file into a buffer
        char* buffer = (char*)malloc(1024);
        fread(buffer, 1024, 1, files[i]);

        // Execute the JavaScript code in the buffer
        eval(buffer);

        // Free the memory allocated for the buffer
        free(buffer);
    }

    // Close all of the opened files
    for (int i = 0; i < num_filenames; i++) {
        fclose(files[i]);
    }
}

