// Define a struct to store the metrics
struct Metrics {
    double average;
    double median;
    double variance;
};

// Define a function to process high-frequency sensor data streams for anomaly detection
void detectAnomalies(double* measurements, int numMeasurements, struct Metrics* metrics) {
    // Initialize the sliding window with the first measurement
    double* window = malloc(numMeasurements * sizeof(double));
    window[0] = measurements[0];

    // Initialize the metrics structure
    metrics->average = 0;
    metrics->median = 0;
    metrics->variance = 0;

    // Iterate over the remaining measurements in the sliding window
    for (int i = 1; i < numMeasurements; i++) {
        // Update the sliding window with the new measurement
        window[i] = measurements[i];

        // Calculate the average, median, and variance of the measurements in the window
        metrics->average += window[i];
        metrics->median += window[i];
        metrics->variance += pow(window[i], 2);

        // Update the maximum deviation from the median and timestamp of the anomalous measurement
        double maxDeviation = fabs(metrics->median - metrics->average);
        int anomalousTimestamp = i;

        // Iterate over the remaining measurements in the window to find the maximum deviation
        for (int j = i + 1; j < numMeasurements; j++) {
            double currentDeviation = fabs(metrics->median - metrics[j]);
            if (currentDeviation > maxDeviation) {
                maxDeviation = currentDeviation;
                anomalousTimestamp = j;
            }
        }

        // Update the metrics structure with the maximum deviation and timestamp of the anomalous measurement
        metrics->maxDeviation = maxDeviation;
        metrics->anomalousTimestamp = anomalousTimestamp;
    }

    // Free the memory allocated for the sliding window
    free(window);
}

