// Custom data structure to store theme settings
struct ThemeSettings {
    char* background;
    char* text_color;
};

// Function to read configuration file and parse key-value pairs
void readConfigFile(char* filename, struct ThemeSettings** settings) {
    // Open the configuration file for reading
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Error opening configuration file");
        return;
    }

    // Read each line of the file and parse key-value pairs
    char buffer[BUFSIZ];
    while (read(fd, buffer, BUFSIZ) > 0) {
        // Split the line into a key and value using the '=' character as a delimiter
        char* key = strtok(buffer, "=");
        char* value = strtok(NULL, "=");

        // Check if the key is valid and add it to the settings struct
        if (key != NULL && value != NULL) {
            // Add the key-value pair to the settings struct
            (*settings)[key] = value;
        } else {
            printf("Invalid key or value in configuration file\n");
        }
    }

    // Close the configuration file
    close(fd);
}

// Function to convert key-value pairs into a custom data structure
void parseSettings(struct ThemeSettings* settings) {
    // Allocate memory for the background and text color values
    char* background = malloc(sizeof(char) * 256);
    char* text_color = malloc(sizeof(char) * 256);

    // Check if memory allocation was successful
    if (background == NULL || text_color == NULL) {
        printf("Error allocating memory for theme settings\n");
        return;
    }

    // Set the background and text color values based on the key-value pairs
    strcpy(background, settings["background"]);
    strcpy(text_color, settings["text-color"]);

    // Create a custom data structure to store the theme settings
    struct ThemeSettings* theme = malloc(sizeof(struct ThemeSettings));
    if (theme == NULL) {
        printf("Error allocating memory for theme settings\n");
        return;
    }

    // Set the background and text color values in the custom data structure
    theme->background = background;
    theme->text_color = text_color;

    // Return the custom data structure
    return theme;
}

