public class LogProcessor
{
    private readonly SHA256 _sha256 = new SHA256Managed();
    private readonly List<string> _errorCodes = new List<string>();
    private readonly Dictionary<string, string> _hashes = new Dictionary<string, string>();

    public LogProcessor(IEnumerable<string> errorCodes)
    {
        foreach (var code in errorCodes)
        {
            _errorCodes.Add(code);
        }
    }

    public async Task ProcessLogFileAsync(string filePath, int batchSize = 1024)
    {
        using var stream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.ReadWrite);
        using var reader = new StreamReader(stream);

        string line;
        while ((line = await reader.ReadLineAsync()) != null)
        {
            if (_errorCodes.Contains(GetErrorCode(line)))
            {
                _hashes[line] = GetHash(line);
            }

            if (_hashes.Count >= batchSize)
            {
                await UploadBatchAsync(_hashes);
                _hashes.Clear();
            }
        }

        if (_hashes.Count > 0)
        {
            await UploadBatchAsync(_hashes);
        }
    }

    private string GetErrorCode(string line)
    {
        // Extract the error code from the log line
        return "ERROR_CODE";
    }

    private string GetHash(string line)
    {
        var hash = _sha256.ComputeHash(Encoding.UTF8.GetBytes(line));
        return BitConverter.ToString(hash).Replace("-", "");
    }

    private async Task UploadBatchAsync(Dictionary<string, string> batch)
    {
        // Integrate with an external logging service API to upload the hashed results asynchronously
        await Task.Run(() => { });
    }
}
```
