use std::env;
use std::error::Error;
use std::thread;
use std::time::Duration;

use tokio::runtime::Runtime;
use tokio::task::JoinHandle;

mod data_sources;
mod error_handling;
mod logging;
mod task_execution;

fn main() -> Result<(), Box<dyn Error>> {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        println!("Usage: {} <task-name>", args[0]);
        return Ok(());
    }

    let task_name = &args[1];

    match task_name.as_str() {
        "fetch_data" => fetch_data(),
        "process_data" => process_data(),
        _ => println!("Invalid task name: {}", task_name),
    }

    Ok(())
}

fn fetch_data() -> Result<(), Box<dyn Error>> {
    let mut runtime = Runtime::new()?;

    // Fetch data from external APIs and databases
    let api1_data = runtime.block_on(data_sources::fetch_api1())?;
    let db1_data = runtime.block_on(data_sources::fetch_db1())?;
    let api2_data = runtime.block_on(data_sources::fetch_api2())?;
    let db2_data = runtime.block_on(data_sources::fetch_db2())?;

    // Combine data from multiple sources
    let combined_data = vec![api1_data, db1_data, api2_data, db2_data];

    // Process the combined data
    runtime.block_on(task_execution::process_data(&combined_data))?;

    Ok(())
}

fn process_data() -> Result<(), Box<dyn Error>> {
    let mut runtime = Runtime::new()?;

    // Fetch data from external APIs and databases
    let api1_data = runtime.block_on(data_sources::fetch_api1())?;
    let db1_data = runtime.block_on(data_sources::fetch_db1())?;
    let api2_data = runtime.block_on(data_sources::fetch_api2())?;
    let db2_data = runtime.block_on(data_sources::fetch_db2())?;

    // Combine data from multiple sources
    let combined_data = vec![api1_data, db1_data, api2_data, db2_data];

    // Process the combined data
    runtime.block_on(task_execution::process_data(&combined_data))?;

    Ok(())
}
