import json
from typing import Dict, Any

class JSONDataHandler:
    def __init__(self):
        self.registry = {}

    def register_factory(self, name: str, factory: Callable[[], Any]) -> None:
        self.registry[name] = factory

    def create_instance(self, name: str) -> Any:
        return self.registry[name]()

class JSONSchemaVersionedDataHandler(JSONDataHandler):
    def __init__(self):
        super().__init__()
        self.schema_versions = {}

    def register_factory(self, name: str, factory: Callable[[], Any]) -> None:
        self.registry[name] = factory
        self.schema_versions[name] = 0

    def create_instance(self, name: str) -> Any:
        instance = super().create_instance(name)
        self.schema_versions[name] += 1
        return instance

    def get_schema_version(self, name: str) -> int:
        return self.schema_versions[name]

class JSONDataModel:
    def __init__(self):
        self.data = {}

    def to_json(self) -> str:
        return json.dumps(self.data)

    def from_json(self, json_string: str) -> None:
        self.data = json.loads(json_string)

class JSONDataModelFactory:
    def __init__(self):
        pass

    def create_model(self, data: Dict[str, Any]) -> JSONDataModel:
        model = JSONDataModel()
        model.data = data
        return model
