typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rxUeInformationTag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* populateNfapiPduList(int n) {
    // Check if the input is valid
    if (n <= 0) {
        return NULL;
    }

    // Create a linked list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T* current = NULL;
    for (int i = 0; i < n; i++) {
        // Allocate memory for the structure
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu == NULL) {
            // Memory allocation failed, clean up and return NULL
            freeLinkedList(head);
            return NULL;
        }

        // Initialize the structure fields
        pdu->rxUeInformationTag = RX_UE_INFORMATION_TAG_INIT;
        pdu->rnti = 0;
        pdu->crcIndicationRel8Tag = CRC_INDICATION_REL8_TAG_INIT;

        // Set a random CRCFLAG value
        pdu->crcIndicationRel8Tag.CRCFLAG = RAND_RANGE(0, 1);

        // Add the structure to the linked list
        if (head == NULL) {
            head = current = pdu;
        } else {
            current->next = pdu;
            current = pdu;
        }
    }

    return head;
}

void freeLinkedList(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
}
