#include <iostream>
#include <vector>
#include <random>
#include <algorithm>

namespace RandomNumberGenerator {
    class MersenneTwister {
        private:
            std::mt19937 mt;
            std::vector<int> dataset;

        public:
            MersenneTwister() : mt(std::random_device{}()) {}

            ~MersenneTwister() = default;

            void loadDataset(const std::vector<int>& data) {
                dataset = data;
            }

            int getLargestInteger() const {
                return *std::max_element(dataset.begin(), dataset.end());
            }
    };
}
