    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    // Read the next line from the file
    while ((read = getline(&line, &len, file)) != -1) {
        // Skip empty lines and lines with fewer than three measurements
        if (strlen(line) > 0 && strtok(line, " ") != NULL) {
            break;
        }
    }

    // If the line is empty or has fewer than three measurements, return NULL
    if (read == -1 || strlen(line) == 0) {
        free(line);
        return NULL;
    }

    // Parse the line into an array of doubles
    char *token = strtok(line, " ");
    int num_meas = 0;
    double *meas = malloc(sizeof(double) * (strlen(line) - 1));
    while (token != NULL) {
        meas[num_meas++] = atof(token);
        token = strtok(NULL, " ");
    }

    // Create a struct to store the data and return it
    struct Data *data = malloc(sizeof(struct Data));
    data->num_meas = num_meas;
    data->meas = meas;
    free(line);
    return data;
}

