```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <atomic>
#include <thread>

// Define a struct to represent a user profile
struct UserProfile {
    std::string name;
    std::string email;
    std::string phoneNumber;
};

// Define a class to manage the collection of user profiles
class ProfileManager {
public:
    // Constructor
    ProfileManager() : profiles_(), mutex_(), cacheSize_(0) {}

    // Destructor
    ~ProfileManager() = default;

    // Insert a new user profile into the collection
    void insert(const UserProfile& profile) {
        std::lock_guard<std::mutex> lock(mutex_);
        profiles_.push_back(profile);
    }

    // Retrieve a user profile from the collection by ID
    UserProfile retrieve(int id) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (const auto& profile : profiles_) {
            if (profile.id == id) {
                return profile;
            }
        }
        // Return an empty profile if the ID is not found
        UserProfile emptyProfile;
        return emptyProfile;
    }

    // Delete a user profile from the collection by ID
    void delete(int id) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto it = profiles_.begin(); it != profiles_.end(); ++it) {
            if ((*it).id == id) {
                profiles_.erase(it);
                break;
            }
        }
    }

    // Update a user profile in the collection by ID
    void update(int id, const UserProfile& newProfile) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto it = profiles_.begin(); it != profiles_.end(); ++it) {
            if ((*it).id == id) {
                (*it) = newProfile;
                break;
            }
        }
    }

private:
    // Vector to store the user profiles
    std::vector<UserProfile> profiles_;

    // Mutex to protect concurrent access to the profile collection
    std::mutex mutex_;

    // Cache size for the user profiles
    int cacheSize_;
};
```
