#define DECRYPTION_FAILURE "Failed to decrypt data using AES-CBC. Check key and IV."

// Function to generate a secure random salt
static void generate_salt(unsigned char *salt) {
    // Generate a cryptographically secure random salt
    if (RAND_bytes(salt, SALT_LEN) != 1) {
        printf("Failed to generate random salt. Check RAND_bytes() return value.\n");
        exit(EXIT_FAILURE);
    }
}

// Function to derive an encryption key from a password using PBKDF2 with SHA-256
static void derive_key(const unsigned char *password, size_t password_len, unsigned char *key) {
    // Define the PBKDF2 parameters
    const EVP_MD *md = EVP_sha256();
    int salt_len = SALT_LEN;
    unsigned int iter = NUM_PBKDF2_ITERATIONS;
    size_t key_len = KEY_LEN;

    // Generate a secure random salt
    unsigned char salt[SALT_LEN];
    generate_salt(salt);

    // Derive the encryption key using PBKDF2
    if (PKCS5_PBKDF2_HMAC(password, password_len, salt, salt_len, iter, md, key_len, key) != 1) {
        printf("Failed to derive encryption key. Check PKCS5_PBKDF2_HMAC() return value.\n");
        exit(EXIT_FAILURE);
    }
}

// Function to generate an initialization vector (IV) from a password using PBKDF2 with SHA-256
static void derive_iv(const unsigned char *password, size_t password_len, unsigned char *iv) {
    // Define the PBKDF2 parameters
    const EVP_MD *md = EVP_sha256();
    int salt_len = SALT_LEN;
    unsigned int iter = NUM_PBKDF2_ITERATIONS;
    size_t iv_len = IV_LEN;

    // Generate a secure random salt
    unsigned char salt[SALT_LEN];
    generate_salt(salt);

    // Derive the initialization vector using PBKDF2
    if (PKCS5_PBKDF2_HMAC(password, password_len, salt, salt_len, iter, md, iv_len, iv) != 1) {
        printf("Failed to derive initialization vector. Check PKCS5_PBKDF2_HMAC() return value.\n");
        exit(EXIT_FAILURE);
    }
}

// Function to encrypt data using AES-CBC with a derived key and IV
static void encrypt(const unsigned char *data, size_t data_len, const unsigned char *key, const unsigned char *iv) {
    // Define the AES-CBC parameters
    int block_size = BLOCK_SIZE;
    int num_blocks = (int)(data_len / block_size);
    int last_block_size = data_len % block_size;
    unsigned char *encrypted_data = malloc(num_blocks * block_size + last_block_size);

    // Encrypt the data using AES-CBC
    if (AES_cbc_encrypt(data, encrypted_data, num_blocks * block_size + last_block_size, key, iv, &block_size) != 1) {
        printf("Failed to encrypt data using AES-CBC. Check AES_cbc_encrypt() return value.\n");
        exit(EXIT_FAILURE);
    }

    // Free the encrypted data buffer
    free(encrypted_data);
}

// Function to decrypt data using AES-CBC with a derived key and IV
static void decrypt(const unsigned char *data, size_t data_len, const unsigned char *key, const unsigned char *iv) {
    // Define the AES-CBC parameters
    int block_size = BLOCK_SIZE;
    int num_blocks = (int)(data_len / block_size);
    int last_block_size = data_len % block_size;
    unsigned char *decrypted_data = malloc(num_blocks * block_size + last_block_size);

    // Decrypt the data using AES-CBC
    if (AES_cbc_encrypt(data, decrypted_data, num_blocks * block_size + last_block_size, key, iv, &block_size) != 1) {
        printf("Failed to decrypt data using AES-CBC. Check AES_cbc_decrypt() return value.\n");
        exit(EXIT_FAILURE);
    }

    // Free the decrypted data buffer
    free(decrypted_data);
}

// Function to initialize and manage an AES-256-CBC cipher for encrypting sensitive user data
void aes_cbc_init(const unsigned char *password, size_t password_len) {
    // Validate the password length
    if (password_len < 8 || password_len > MAX_PASSWORD_LEN) {
        printf("%s\n", INVALID_PASSWORD_LENGTH);
        exit(EXIT_FAILURE);
    }

    // Derive an encryption key and initialization vector from the password
    unsigned char key[KEY_LEN];
    derive_key(password, password_len, key);
    unsigned char iv[IV_LEN];
    derive_iv(password, password_len, iv);

    // Encrypt the data using AES-CBC
    encrypt(data, data_len, key, iv);

    // Decrypt the data using AES-CBC
    decrypt(encrypted_data, encrypted_data_len, key, iv);
}
