    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to dynamically allocate and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocateAndPopulateArray(int N) {
    // Check if N is a positive integer
    if (N <= 0) {
        printf("Error: Invalid input for N. Must be a positive integer.\n");
        return NULL;
    }

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T* arr = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    if (!arr) {
        printf("Error: Failed to allocate memory for the array of structures.\n");
        return NULL;
    }

    // Populate the array with random values for RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG
    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        arr[i].RX_UE_INFORMATION_TAG = rand() % 65536;
        arr[i].RNTI = rand() % 4294967296;
        arr[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        arr[i].CRCFLAG = (rand() % 2) == 0 ? true : false;
    }

    return arr;
}

// Define the function to serialize the populated structures into a binary format for storage or transmission
void serializeArray(NFAPI_CRC_INDICATION_PDU_T* arr, int N, char* buffer) {
