// Define the LOG_RECORD structure to store log entry metadata
typedef struct {
    time_t timestamp;
    uint32_t source_ip;
    uint32_t destination_ip;
    uint8_t protocol_type;
    uint16_t packet_size;
} LOG_RECORD;

// Define the linked list node structure to store valid log entries
typedef struct {
    LOG_RECORD record;
    struct node *next;
} NODE;

// Function to validate and process a single log entry
void process_log_entry(LOG_RECORD *record) {
    // Validate the timestamp, source IP, destination IP, protocol type, and packet size
    if (record->timestamp < 0 || record->source_ip == 0 || record->destination_ip == 0 || record->protocol_type > 255 || record->packet_size < 64 || record->packet_size > 1500) {
        // Handle invalid log entry by skipping it and moving on to the next one
        return;
    }

    // Validate the IP addresses are in a valid format
    if (inet_pton(AF_INET, record->source_ip, &record->source_ip) != 1 || inet_pton(AF_INET, record->destination_ip, &record->destination_ip) != 1) {
        // Handle invalid IP addresses by skipping the log entry and moving on to the next one
        return;
    }

    // Store the valid log entry in a linked list for further processing
    NODE *node = malloc(sizeof(NODE));
    node->record = *record;
    node->next = NULL;

    // Add the new node to the end of the linked list
    if (head == NULL) {
        head = node;
    } else {
        tail->next = node;
    }
    tail = node;
}

// Function to calculate and print the average packet size across all valid log entries
void calculate_average_packet_size() {
    // Initialize variables for calculating the average packet size
    uint64_t total_packet_size = 0;
    int count = 0;

    // Iterate through the linked list of valid log entries
    NODE *node = head;
    while (node != NULL) {
        // Add the current packet size to the total and increment the count
        total_packet_size += node->record.packet_size;
        count++;

        // Move on to the next node in the linked list
        node = node->next;
    }

    // Calculate the average packet size and print it
    printf("Average packet size: %f\n", (double)total_packet_size / count);
}

// Function to identify and print the top three most frequently occurring protocols used in the logs
void identify_protocols() {
    // Initialize a hash table to store the counts of each protocol type
    int *counts = calloc(256, sizeof(int));

    // Iterate through the linked list of valid log entries
    NODE *node = head;
    while (node != NULL) {
        // Increment the count for the current protocol type in the hash table
        counts[node->record.protocol_type]++;

        // Move on to the next node in the linked list
        node = node->next;
    }

    // Sort the hash table by value (count) and print the top three most frequently occurring protocols
    int *sorted_counts = malloc(256 * sizeof(int));
    memcpy(sorted_counts, counts, 256 * sizeof(int));
    qsort(sorted_counts, 256, sizeof(int), compare_ints);
    for (int i = 0; i < 3; i++) {
        printf("Protocol %d: %d\n", sorted_counts[i], counts[sorted_counts[i]]);
    }
}

// Function to determine the maximum difference in time between consecutive log entries, considering only those where the source and destination IPs are from the same subnet
void calculate_max_time_diff() {
    // Initialize variables for calculating the maximum time difference
    int64_t max_time_diff = 0;
    uint32_t prev_source_ip = 0;
    uint32_t prev_destination_ip = 0;

    // Iterate through the linked list of valid log entries
    NODE *node = head;
    while (node != NULL) {
        // Check if the current log entry is from the same subnet as the previous one
        if (prev_source_ip == node->record.source_ip && prev_destination_ip == node->record.destination_ip) {
            // Calculate the time difference between the two log entries and compare it to the maximum time difference
            int64_t time_diff = node->record.timestamp - prev_timestamp;
            if (time_diff > max_time_diff) {
                max_time_diff = time_diff;
            }
        }

        // Update the previous log entry information for the next iteration
        prev_source_ip = node->record.source_ip;
        prev_destination_ip = node->record.destination_ip;
        prev_timestamp = node->record.timestamp;

        // Move on to the next node in the linked list
        node = node->next;
    }

    // Print the maximum time difference
    printf("Maximum time difference: %ld\n", max_time_diff);
}

