// Define the condition variable for signaling changes in the list
static pthread_cond_t ue_info_cv = PTHREAD_COND_INITIALIZER;

// Function to add a new UE information structure to the list
void add_ue_info(int RX_UE_INFORMATION_TAG, int RNTI, char* PDUSessionStatusList_RRC_NAS_PDU) {
