    pthread_mutex_lock(&ue_info_lock);

    // Allocate memory for the new structure
    NFAPI_MESSAGE_T* new_entry = malloc(sizeof(NFAPI_MESSAGE_T));
    if (new_entry == NULL) {
        perror("malloc");
        exit(1);
