    // Initialize the fields of the new structure
    new_entry->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_entry->RNTI = RNTI;
    new_entry->PDUSessionStatusList_RRC_NAS_PDU = PDUSessionStatusList_RRC_NAS_PDU;

    // Add the new structure to the end of the list
    if (ue_info_list == NULL) {
        ue_info_list = new_entry;
