#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <assert.h>

// Define the structure for each record in the database
typedef struct {
    int key;
    long offset;
} Record;

// Define the hash map data structure
typedef struct {
    int *keys;
    long *offsets;
    Record **records;
    size_t capacity;
    pthread_mutex_t mutex;
} Database;

// Initialize a new database with the given capacity
Database* init_database(size_t capacity) {
    // Allocate memory for the keys, offsets, and records arrays
    int *keys = malloc(capacity * sizeof(int));
    long *offsets = malloc(capacity * sizeof(long));
    Record **records = malloc(capacity * sizeof(Record*));

    // Initialize all elements of the keys array to zero
    for (size_t i = 0; i < capacity; i++) {
        keys[i] = 0;
    }

    // Initialize all elements of the offsets array to zero
    for (size_t i = 0; i < capacity; i++) {
        offsets[i] = 0;
    }

    // Initialize all records to NULL
    for (size_t i = 0; i < capacity; i++) {
        records[i] = NULL;
    }

    // Create a new database object and populate it with the allocated arrays
    Database *db = malloc(sizeof(Database));
    db->keys = keys;
    db->offsets = offsets;
    db->records = records;
    db->capacity = capacity;

    // Initialize the mutex for thread-safe access to the database
    pthread_mutex_init(&db->mutex, NULL);

    return db;
}

// Add a new record to the database with the given key and value
void add_record(Database *db, int key, long value) {
    // Acquire the mutex for thread-safe access to the database
    pthread_mutex_lock(&db->mutex);

    // Check if the key already exists in the database
    if (key_exists(db, key)) {
        // If the key already exists, update the value and return
        update_record(db, key, value);
        pthread_mutex_unlock(&db->mutex);
        return;
    }

    // Find the first available slot in the keys array
    size_t i = 0;
    while (i < db->capacity && db->keys[i] != 0) {
        i++;
    }

    // If no slots are available, resize the database
    if (i == db->capacity) {
        resize_database(db);
        i = 0;
    }

    // Add the new record to the records array and update the hash map
    Record *record = malloc(sizeof(Record));
    record->key = key;
    record->offset = db->offsets[i];
    db->records[i] = record;
    db->keys[i] = key;
    db->offsets[i]++;

    // Release the mutex and return
    pthread_mutex_unlock(&db->mutex);
}

// Update a record in the database with the given key and value
void update_record(Database *db, int key, long value) {
    // Acquire the mutex for thread-safe access to the database
    pthread_mutex_lock(&db->mutex);

    // Find the index of the record in the keys array
    size_t i = 0;
    while (i < db->capacity && db->keys[i] != key) {
        i++;
    }

    // If the record does not exist, return
    if (i == db->capacity) {
        pthread_mutex_unlock(&db->mutex);
        return;
    }

    // Update the value of the record and release the mutex
    Record *record = db->records[i];
    record->value = value;
    pthread_mutex_unlock(&db->mutex);
}

// Delete a record from the database with the given key
void delete_record(Database *db, int key) {
    // Acquire the mutex for thread-safe access to the database
    pthread_mutex_lock(&db->mutex);

    // Find the index of the record in the keys array
    size_t i = 0;
    while (i < db->capacity && db->keys[i] != key) {
        i++;
    }

    // If the record does not exist, return
    if (i == db->capacity) {
        pthread_mutex_unlock(&db->mutex);
        return;
    }

    // Remove the record from the records array and update the hash map
    Record *record = db->records[i];
    free(record);
    db->keys[i] = 0;
    db->offsets[i]--;

    // Release the mutex and return
    pthread_mutex_unlock(&db->mutex);
}

// Retrieve a record from the database with the given key
Record* get_record(Database *db, int key) {
    // Acquire the mutex for thread-safe access to the database
    pthread_mutex_lock(&db->mutex);

    // Find the index of the record in the keys array
    size_t i = 0;
    while (i < db->capacity && db->keys[i] != key) {
        i++;
    }

    // If the record does not exist, return NULL
    if (i == db->capacity) {
        pthread_mutex_unlock(&db->mutex);
        return NULL;
    }

    // Return a copy of the record and release the mutex
    Record *record = malloc(sizeof(Record));
    memcpy(record, db->records[i], sizeof(Record));
    pthread_mutex_unlock(&db->mutex);
    return record;
}

// Check if a key exists in the database
int key_exists(Database *db, int key) {
    // Acquire the mutex for thread-safe access to the database
    pthread_mutex_lock(&db->mutex);

    // Find the index of the record in the keys array
    size_t i = 0;
    while (i < db->capacity && db->keys[i] != key) {
        i++;
    }

    // Release the mutex and return whether the record exists or not
    pthread_mutex_unlock(&db->mutex);
    return i < db->capacity;
}

// Resize the database to accommodate more records
void resize_database(Database *db) {
    // Allocate memory for the new keys, offsets, and records arrays
    int *new_keys = malloc((db->capacity + 1) * sizeof(int));
    long *new_offsets = malloc((db->capacity + 1) * sizeof(long));
    Record **new_records = malloc((db->capacity + 1) * sizeof(Record*));

    // Copy the existing keys, offsets, and records to the new arrays
    for (size_t i = 0; i < db->capacity; i++) {
        new_keys[i] = db->keys[i];
        new_offsets[i] = db->offsets[i];
        new_records[i] = db->records[i];
    }

    // Free the old arrays and update the database with the new ones
    free(db->keys);
    free(db->offsets);
    free(db->records);
    db->keys = new_keys;
    db->offsets = new_offsets;
    db->records = new_records;
    db->capacity++;
}

// Free the memory allocated by the database
void free_database(Database *db) {
    // Acquire the mutex for thread-safe access to the database
    pthread_mutex_lock(&db->mutex);

    // Free the keys, offsets, and records arrays
    free(db->keys);
    free(db->offsets);
    for (size_t i = 0; i < db->capacity; i++) {
        Record *record = db->records[i];
        if (record != NULL) {
            free(record);
        }
    }
    free(db->records);

    // Release the mutex and return
    pthread_mutex_unlock(&db->mutex);
}
