// Function to dynamically allocate memory for an array to store a list of integers read from a CSV file
int* read_csv(const char* filename, int* num_ints) {
  // Open the CSV file and check if it exists
  FILE* fp = fopen(filename, "r");
  if (fp == NULL) {
    printf("Error: File %s does not exist\n", filename);
    return NULL;
  }

  // Initialize variables to store the number of integers and the array of integers
  int num_lines = 0;
  int* ints = NULL;

