  char* line = NULL;
  size_t len = 0;
  ssize_t read;
  while ((read = getline(&line, &len, fp)) != -1) {
    // Skip empty lines or lines that start with a comment character (#)
    if (strlen(line) > 0 && line[0] != '#') {
      num_lines++;
    }
  }

  // Allocate memory for the integer array and read each line from the CSV file into it
  ints = malloc(num_lines * sizeof(int));
  rewind(fp);
  int i = 0;
  while ((read = getline(&line, &len, fp)) != -1) {
    // Skip empty lines or lines that start with a comment character (#)
    if (strlen(line) > 0 && line[0] != '#') {
      ints[i++] = atoi(line);
    }
  }

  // Close the CSV file and return the integer array
  fclose(fp);
  *num_ints = i;
  return ints;
}

