void print_largest_int(int* ints, int num_ints) {
  // Initialize variables to store the largest integer and its index
  int largest_int = INT_MIN;
  int largest_index = -1;

  // Iterate through the array of integers and find the largest one
  for (int i = 0; i < num_ints; i++) {
    if (ints[i] > largest_int) {
