#include <pthread.h>

// Define a data structure to store a data point
typedef struct {
    double value;
    char *string;
    float timestamp;
} data_point;

// Define a custom tree structure for efficient key-based lookups
typedef struct {
    data_point *data;
    int size;
} data_tree;

// Function to initialize the collection from an external data source
void init_collection(data_tree *tree) {
    // Allocate memory for the tree structure
    tree->data = (data_point *)malloc(sizeof(data_point) * 100);
    tree->size = 0;
}

// Function to add a new data point to the collection
void add_data_point(data_tree *tree, double value, char *string, float timestamp) {
    // Check if the tree is full and needs to be resized
    if (tree->size == 100) {
        // Resize the tree by doubling its size
        tree->data = (data_point *)realloc(tree->data, sizeof(data_point) * 200);
    }

    // Add the new data point to the end of the tree
    tree->data[tree->size].value = value;
    tree->data[tree->size].string = string;
    tree->data[tree->size].timestamp = timestamp;
    tree->size++;
}

// Function to retrieve a data point from the collection by its unique string identifier
data_point *get_data_point(data_tree *tree, char *string) {
    // Iterate through the tree and find the data point with the matching string
    for (int i = 0; i < tree->size; i++) {
        if (strcmp(tree->data[i].string, string) == 0) {
            return &tree->data[i];
        }
    }

    // If the data point is not found, return NULL
    return NULL;
}

// Function to remove outdated entries from the collection
void prune_collection(data_tree *tree) {
    // Iterate through the tree and find the oldest entry
    int oldest = 0;
    for (int i = 1; i < tree->size; i++) {
        if (tree->data[i].timestamp < tree->data[oldest].timestamp) {
            oldest = i;
        }
    }

    // Remove the oldest entry from the tree
    free(tree->data[oldest].string);
    memmove(&tree->data[oldest], &tree->data[oldest + 1], sizeof(data_point) * (tree->size - oldest - 1));
    tree->size--;
}

// Function to release unused memory blocks from the collection
void release_memory(data_tree *tree) {
    // Iterate through the tree and find any unused memory blocks
    for (int i = 0; i < tree->size; i++) {
        if (tree->data[i].string == NULL) {
            free(tree->data[i].value);
            memmove(&tree->data[i], &tree->data[i + 1], sizeof(data_point) * (tree->size - i - 1));
            tree->size--;
