// Function to handle concurrent read and write operations from multiple threads
void access_collection(data_tree *tree, int thread_id) {
    // Use a lock to prevent race conditions between threads
    pthread_mutex_lock(&tree->lock);

    // Perform the desired operation on the collection
    if (thread_id == 0) {
        add_data_point(tree, 1.23, "hello", 1645798400);
    } else if (thread_id == 1) {
        data_point *dp = get_data_point(tree, "hello");
        printf("Value: %f\n", dp->value);
    } else if (thread_id == 2) {
        prune_collection(tree);
    } else if (thread_id == 3) {
        release_memory(tree);
    }

    // Release the lock to allow other threads to access the collection
    pthread_mutex_unlock(&tree->lock);
}
