};

// Define a cache of pre-rendered bitmaps
struct BitmapCache {
    struct Bitmap** bitmaps;
    int size;
    int capacity;
};

// Initialize the cache with a given capacity
void init_cache(struct BitmapCache* cache, int capacity) {
    cache->bitmaps = malloc(sizeof(struct Bitmap*) * capacity);
    cache->size = 0;
    cache->capacity = capacity;
}

// Add a bitmap to the cache
void add_to_cache(struct BitmapCache* cache, struct Bitmap* bitmap) {
    if (cache->size < cache->capacity) {
        cache->bitmaps[cache->size++] = bitmap;
    } else {
        // Evict least recently used bitmap
        int lru = 0;
        for (int i = 1; i < cache->size; i++) {
            if (cache->bitmaps[i]->access_time < cache->bitmaps[lru]->access_time) {
                lru = i;
            }
        }
        free(cache->bitmaps[lru]);
        cache->bitmaps[lru] = bitmap;
    }
}

// Get a bitmap from the cache
struct Bitmap* get_from_cache(struct BitmapCache* cache, int index) {
    if (index < 0 || index >= cache->size) {
        return NULL;
    }
    struct Bitmap* bitmap = cache->bitmaps[index];
    bitmap->access_time = time(NULL);
    return bitmap;
}

