void parse_config(char* filename, struct ThemeSettings* settings) {
    // Open the configuration file
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: unable to open configuration file\n");
        return;
    }

    // Read each line of the file and parse the key-value pairs
    char line[1024];
    while (fgets(line, sizeof(line), fp) != NULL) {
        // Remove any leading or trailing whitespace
        char* token = strtok(line, " \t\n");
        if (token == NULL) {
            continue;
        }

        // Check if the key is a valid feature identifier
        if (strcmp(token, "background") == 0 || strcmp(token, "text-color") == 0) {
            token = strtok(NULL, " \t\n");
            if (token != NULL) {
                // Store the value in the corresponding struct field
                if (strcmp(token, "background") == 0) {
                    settings->background = strdup(token);
                } else if (strcmp(token, "text-color") == 0) {
                    settings->text_color = strdup(token);
                }
            }
        }
    }

    // Close the configuration file
    fclose(fp);
}

