    struct Bitmap* bitmap = malloc(sizeof(struct Bitmap));
    bitmap->width = 1024;
    bitmap->height = 768;
    bitmap->data = malloc(bitmap->width * bitmap->height * 3);

    // Fill the bitmap with a default color scheme
    for (int i = 0; i < bitmap->width * bitmap->height; i++) {
        bitmap->data[i * 3] = strtol(background, NULL, 16);
        bitmap->data[i * 3 + 1] = strtol(text_color, NULL, 16);
        bitmap->data[i * 3 + 2] = 0xFF;
    }

    return bitmap;
}

