// Define the configuration settings hash table
static config_setting_t** settings = NULL;

// Define the priority queue for updating settings based on their priority level
static priority_queue_node_t* priority_queue = NULL;

// Define the mutex for protecting concurrent access to the settings and priority queue
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize the configuration settings hash table and priority queue
void init_config(int num_settings) {
    // Allocate memory for the settings hash table
    settings = (config_setting_t**)malloc(num_settings * sizeof(config_setting_t*));
    memset(settings, 0, num_settings * sizeof(config_setting_t*));

    // Initialize the priority queue with a fixed size of 1024 nodes
    priority_queue = (priority_queue_node_t*)malloc(1024 * sizeof(priority_queue_node_t));
    memset(priority_queue, 0, 1024 * sizeof(priority_queue_node_t));
}

// Insert a new configuration setting into the hash table and priority queue
void insert_setting(char* key, void* value) {
    // Acquire the lock to protect concurrent access to the settings and priority queue
    pthread_mutex_lock(&lock);

    // Check if the setting already exists in the hash table
    int index = find_setting(key);
    if (index != -1) {
        // Update the existing setting with the new value
        settings[index]->value = value;
    } else {
