        // Release the lock to allow other threads to access the settings and priority queue
        pthread_mutex_unlock(&lock);
        return NULL;
    }
}

// Find a configuration setting in the hash table based on its key
int find_setting(char* key) {
    // Iterate over the hash table to find the setting with the matching key
    for (int i = 0; i < num_settings; i++) {
        if (strcmp(key, settings[i]->key) == 0) {
            return i;
        }
    }
    return -1;
}

// Insert a configuration setting into the priority queue based on its priority level
void insert_into_queue(config_setting_t* setting, int priority) {
    // Check if the priority queue is full and needs to be resized
    if (priority_queue->size == 1024) {
        // Resize the priority queue with a new size that is twice the current size
        priority_queue = (priority_queue_node_t*)realloc(priority_queue, 2 * 1024 * sizeof(priority_queue_node_t));
    }

    // Insert the setting into the priority queue at the appropriate position based on its priority level
    int index = find_position(priority);
    priority_queue[index].setting = setting;
    priority_queue[index].priority = priority;
}

// Delete a configuration setting from the priority queue based on its key
void delete_from_queue(char* key) {
    // Find the index of the setting in the priority queue
    int index = find_setting_in_queue(key);
    if (index != -1) {
        // Remove the setting from the priority queue
        memmove(&priority_queue[index], &priority_queue[index + 1], (1024 - index - 1) * sizeof(priority_queue_node_t));
    }
}

// Find a configuration setting in the priority queue based on its key
int find_setting_in_queue(char* key) {
    // Iterate over the priority queue to find the setting with the matching key
    for (int i = 0; i < 1024; i++) {
        if (strcmp(key, priority_queue[i].setting->key) == 0) {
            return i;
        }
    }
    return -1;
}

// Find the position in the priority queue where a new setting should be inserted based on its priority level
int find_position(int priority) {
    // Iterate over the priority queue to find the first position where the new setting should be inserted
    for (int i = 0; i < 1024; i++) {
        if (priority > priority_queue[i].priority) {
            return i;
        }
    }
    // If the new setting has the highest priority, insert it at the end of the queue
    return 1023;
}
