#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <errno.h>

// Global cache for frequently accessed product details
struct ProductCache {
    int id;
    float price;
};

// Temporary directory for overflow data
const char* temp_dir = "/tmp/overflow";

// Lock for protecting the global cache
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically allocate memory for a transaction line
struct TransactionLine* allocTransactionLine(const char* line) {
    struct TransactionLine* tl = malloc(sizeof(struct TransactionLine));
    if (tl == NULL) {
        perror("Failed to allocate memory for transaction line");
        return NULL;
    }
    // Parse the transaction line and populate the fields
    char* token = strtok(line, ",");
    while (token != NULL) {
        switch (tl->field_count++) {
            case 0: tl->timestamp = atoi(token); break;
            case 1: tl->product_id = atoi(token); break;
            case 2: tl->quantity = atoi(token); break;
            case 3: tl->price = atof(token); break;
        }
        token = strtok(NULL, ",");
    }
    return tl;
}

// Function to compute the average price of a transaction line
float getAveragePrice(struct TransactionLine* tl) {
    float sum = 0.0f;
    for (int i = 0; i < tl->quantity; i++) {
        sum += tl->price;
    }
    return sum / tl->quantity;
}

// Function to replace the last field of a transaction line with the average price
void updateTransactionLine(struct TransactionLine* tl) {
    pthread_mutex_lock(&cache_lock);
    struct ProductCache* pc = getProductCache(tl->product_id);
    if (pc == NULL) {
        perror("Failed to retrieve product cache");
        return;
    }
    tl->price = pc->price;
    pthread_mutex_unlock(&cache_lock);
}

// Function to manage the global cache for frequently accessed product details
struct ProductCache* getProductCache(int id) {
    struct ProductCache* pc = malloc(sizeof(struct ProductCache));
    if (pc == NULL) {
        perror("Failed to allocate memory for product cache");
        return NULL;
    }
    // Check if the product is already in the cache
    pthread_mutex_lock(&cache_lock);
    struct ProductCache* pc = getProductCache(id);
    if (pc != NULL) {
        pthread_mutex_unlock(&cache_lock);
        return pc;
    }
    // If not, add it to the cache and update the product details
    pc->id = id;
    pc->price = getProductPrice(id);
    pthread_mutex_unlock(&cache_lock);
    return pc;
}

