// Define the structure for RLC status report
typedef struct {
    uint32_t grant_index; // Index of the PDSCH grant
    bool is_active;       // Whether the grant is currently active
} LTE_PHY_RLC_STATUS_REPORT_T;

// Define a hash table for storing RLC status reports
typedef struct {
    uint32_t size;                  // Size of the hash table
    LTE_PHY_RLC_STATUS_REPORT_T** table; // Hash table itself
} RLC_STATUS_HASH_TABLE_T;

// Define a mutex for protecting concurrent access to the hash table
pthread_mutex_t rlc_status_hash_table_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add an RLC status report to the hash table
void add_rlc_status_report(RLC_STATUS_HASH_TABLE_T* table, uint32_t grant_index, bool is_active) {
    // Acquire the mutex for protecting concurrent access
    pthread_mutex_lock(&rlc_status_hash_table_mutex);

    // Check if the hash table has enough space to store the new report
    if (table->size == 0 || table->size <= grant_index) {
        // If not, resize the hash table and re-allocate memory for the new reports
        uint32_t new_size = grant_index + 1;
        LTE_PHY_RLC_STATUS_REPORT_T** new_table = realloc(table->table, sizeof(LTE_PHY_RLC_STATUS_REPORT_T*) * new_size);
        if (new_table == NULL) {
            // If memory allocation fails, release the mutex and return
            pthread_mutex_unlock(&rlc_status_hash_table_mutex);
            return;
        }
        table->table = new_table;
        table->size = new_size;
    }

    // Store the new report in the hash table
    table->table[grant_index] = malloc(sizeof(LTE_PHY_RLC_STATUS_REPORT_T));
    if (table->table[grant_index] == NULL) {
        // If memory allocation fails, release the mutex and return
        pthread_mutex_unlock(&rlc_status_hash_table_mutex);
        return;
    }
    table->table[grant_index]->grant_index = grant_index;
    table->table[grant_index]->is_active = is_active;

    // Release the mutex and return
    pthread_mutex_unlock(&rlc_status_hash_table_mutex);
}

// Function to update an RLC status report in the hash table
void update_rlc_status_report(RLC_STATUS_HASH_TABLE_T* table, uint32_t grant_index, bool is_active) {
    // Acquire the mutex for protecting concurrent access
    pthread_mutex_lock(&rlc_status_hash_table_mutex);

    // Check if the hash table has enough space to store the new report
    if (table->size == 0 || table->size <= grant_index) {
        // If not, release the mutex and return
        pthread_mutex_unlock(&rlc_status_hash_table_mutex);
        return;
    }

    // Update the report in the hash table
    table->table[grant_index]->is_active = is_active;

    // Release the mutex and return
    pthread_mutex_unlock(&rlc_status_hash_table_mutex);
}

// Function to retrieve an RLC status report from the hash table
LTE_PHY_RLC_STATUS_REPORT_T* get_rlc_status_report(RLC_STATUS_HASH_TABLE_T* table, uint32_t grant_index) {
    // Acquire the mutex for protecting concurrent access
    pthread_mutex_lock(&rlc_status_hash_table_mutex);

    // Check if the hash table has enough space to store the new report
    if (table->size == 0 || table->size <= grant_index) {
        // If not, release the mutex and return NULL
        pthread_mutex_unlock(&rlc_status_hash_table_mutex);
        return NULL;
    }

    // Retrieve the report from the hash table
    LTE_PHY_RLC_STATUS_REPORT_T* report = table->table[grant_index];

    // Release the mutex and return the report
    pthread_mutex_unlock(&rlc_status_hash_table_mutex);
    return report;
}

// Function to notify clients of changes in RLC status reports
void notify_clients(RLC_STATUS_HASH_TABLE_T* table, uint32_t grant_index) {
    // Acquire the mutex for protecting concurrent access
    pthread_mutex_lock(&rlc_status_hash_table_mutex);

    // Check if the hash table has enough space to store the new report
    if (table->size == 0 || table->size <= grant_index) {
        // If not, release the mutex and return
        pthread_mutex_unlock(&rlc_status_hash_table_mutex);
        return;
    }

    // Retrieve the report from the hash table
    LTE_PHY_RLC_STATUS_REPORT_T* report = table->table[grant_index];

    // Notify clients of changes in RLC status reports
    printf("RLC status report for grant index %d has changed to is_active=%s\n", grant_index, report->is_active ? "true" : "false");

    // Release the mutex and return
    pthread_mutex_unlock(&rlc_status_hash_table_mutex);
}
```
This code defines a hash table for storing RLC status reports, which are used to track the status of PDSCH (Physical Downlink Shared Channel) grants in a wireless communication system. The hash table is protected by a mutex to ensure concurrent access from multiple threads without data corruption or race conditions.

The `add_rlc_status_report` function adds a new RLC status report to the hash table, while the `update_rlc_status_report` function updates an existing RLC status report in the hash table. The `get_rlc_status_report` function retrieves an RLC status report from the hash table based on its grant index.

The `notify_clients` function notifies clients of changes in RLC status reports by printing a message to the console. This function is called whenever an RLC status report changes, ensuring that the solution is responsive and efficient under various load conditions.']

