#include <signal.h>
#include <errno.h>

#define MAX_LINE_LENGTH 1024
#define MAX_COMMANDS 32
#define MAX_FILES 64

// Struct to store information about each command
struct Command {
    char *command;
    int pid;
};

// Function to execute a single command and manage its resources
void exec_command(char *command) {
    // Fork a new process to run the command
    int pid = fork();

    if (pid == 0) {
        // Child process: Execute the command
        execl("/bin/sh", "sh", "-c", command, NULL);
        exit(1);
    } else if (pid > 0) {
        // Parent process: Wait for the command to finish and handle errors
        int status;
        waitpid(pid, &status, 0);
        if (WIFEXITED(status)) {
            if (WEXITSTATUS(status) != 0) {
                fprintf(stderr, "Command exited with error: %d\n", WEXITSTATUS(status));
            }
        } else if (WIFSIGNALED(status)) {
            fprintf(stderr, "Command terminated by signal: %d\n", WTERMSIG(status));
        }
    } else {
        // Error forking the process
        perror("fork");
    }
}

// Function to execute a sequence of commands and manage their resources
void exec_commands(char *commands) {
    char *token;
    int i = 0;

    while ((token = strsep(&commands, ";")) != NULL) {
        // Execute the current command
        exec_command(token);

        // Check for errors and handle them appropriately
        if (errno != 0) {
            perror("exec");
            exit(1);
        }
    }
}

// Function to read a file and process its contents
void process_file(char *filename) {
    FILE *fp;
    char line[MAX_LINE_LENGTH];
    int i = 0;

    // Open the file for reading
    fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("fopen");
        exit(1);
    }

    while (fgets(line, MAX_LINE_LENGTH, fp) != NULL) {
        // Process the current line
        char *token;
        int j = 0;

        while ((token = strsep(&line, ";")) != NULL) {
            if (j == 0) {
                // Execute the first command in the sequence
                exec_command(token);
            } else {
                // Wait for the previous command to finish before executing the next one
                int status;
                waitpid(i, &status, 0);
                if (WIFEXITED(status)) {
                    if (WEXITSTATUS(status) != 0) {
                        fprintf(stderr, "Command exited with error: %d\n", WEXITSTATUS(status));
                    }
                } else if (WIFSIGNALED(status)) {
                    fprintf(stderr, "Command terminated by signal: %d\n", WTERMSIG(status));
                }
            }

            // Execute the current command
            exec_command(token);

            // Check for errors and handle them appropriately
            if (errno != 0) {
                perror("exec");
                exit(1);
            }
        }

        i++;
    }
}

// Function to read a directory of files and process their contents
void process_directory(char *dirname) {
    DIR *dp;
    struct dirent *ep;

    // Open the directory for reading
    dp = opendir(dirname);
    if (dp == NULL) {
        perror("opendir");
        exit(1);
    }

    while ((ep = readdir(dp)) != NULL) {
        char *filename = ep->d_name;

        // Skip over non-text files and hidden files
        if (strlen(filename) > 4 && strcmp(filename + strlen(filename) - 4, ".txt") == 0 && filename[0] != '.') {
            process_file(dirname);
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <directory>\n", argv[0]);
        exit(1);
    }

    // Process the directory of files
    process_directory(argv[1]);

    return 0;
}
```
