void allocate_memory(int num_offsets, int num_keys, int num_records) {
    // Allocate memory for the offsets array
    long *offsets = (long *)malloc(num_offsets * sizeof(long));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offsets\n");
        return;
    }

    // Allocate memory for the keys array
    int *keys = (int *)malloc(num_keys * sizeof(int));
    if (!keys) {
        printf("Error: Failed to allocate memory for keys\n");
        free(offsets);
        return;
    }

    // Allocate memory for the records array
    Record *records = (Record *)malloc(num_records * sizeof(Record));
    if (!records) {
        printf("Error: Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize the offsets array with random values between -1500 and 1500
    srand(time(NULL));
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = rand() % 3000 - 1500;
    }

    // Initialize the keys array with random values between -1500 and 1500
    for (int i = 0; i < num_keys; i++) {
        keys[i] = rand() % 3000 - 1500;
    }

    // Initialize the records array with random values between -1500 and 1500
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 3000 - 1500;
    }

    // Log the start and end of the operation to a file
    FILE *log_file = fopen("memory_usage.log", "a");
