        fprintf(log_file, "Keys array size: %d\n", num_keys);
        fprintf(log_file, "Records array size: %d\n", num_records);
        fprintf(log_file, "Ending memory allocation\n");
        fclose(log_file);
    } else {
        printf("Error: Failed to open log file for writing\n");
    }
}
