// Custom logger structure
struct logger {
    int log_level;
    char *log_file;
    sem_t *log_lock;
};

// Initialize custom logger with default values
void init_logger(struct logger *logger) {
    logger->log_level = LOG_INFO;
    logger->log_file = "logs/app.log";
    logger->log_lock = sem_open("log_lock", O_CREAT, 0644, 1);
}

// Set log level for custom logger
void set_log_level(struct logger *logger, int log_level) {
    logger->log_level = log_level;
}

// Log message with custom logger
void log_message(struct logger *logger, char *message) {
    sem_wait(logger->log_lock);
    FILE *fp = fopen(logger->log_file, "a");
    if (fp == NULL) {
        perror("fopen");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char buf[1024];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "[%s] [%d] %s\n", buf, logger->log_level, message);
    fclose(fp);
    sem_post(logger->log_lock);
}

