#include <time.h>

// Define the struct for storing sensor information
struct sensor {
    int device_id;
    char location[10];
    bool active;
};

// Define the function to initialize and manage memory for sensors
void init_sensors(int num_sensors, int offline_threshold) {
    // Allocate memory for temperature, humidity, and sensor arrays
    double *temperature = (double *)malloc(num_sensors * sizeof(double));
    float *humidity = (float *)malloc(num_sensors * sizeof(float));
    struct sensor *sensors = (struct sensor *)malloc(num_sensors * sizeof(struct sensor));

    // Initialize the arrays with random values within a specified range
    srand(time(NULL));
    for (int i = 0; i < num_sensors; i++) {
        temperature[i] = rand() % 100;
        humidity[i] = rand() % 100;
        sensors[i].device_id = i + 1;
        sensors[i].location[0] = 'A' + (rand() % 26);
        sensors[i].active = true;
    }

    // Define a variable to track the number of active sensors
    int num_active = num_sensors;

    // Define a variable to store the offline duration threshold
    int offline_duration = offline_threshold;

    // Loop through each sensor and check if it has been offline for longer than the threshold
    for (int i = 0; i < num_sensors; i++) {
        if (!sensors[i].active) {
            int offline_time = time(NULL) - sensors[i].last_update;
            if (offline_time > offline_duration) {
                // Mark the sensor as inactive and update its status
                sensors[i].active = false;
                num_active--;
            }
        }
    }

    // Return pointers to the first elements of the temperature, humidity, and sensor arrays, along with the current count of active sensors and the offline duration threshold
    return (double *)temperature, (float *)humidity, (struct sensor *)sensors, num_active, offline_duration;
}

// Define a function to update the status of each sensor based on its offline duration
void update_sensor_status(int num_sensors, int offline_threshold) {
    // Loop through each sensor and check if it has been offline for longer than the threshold
    for (int i = 0; i < num_sensors; i++) {
        if (!sensors[i].active) {
            int offline_time = time(NULL) - sensors[i].last_update;
            if (offline_time > offline_duration) {
                // Mark the sensor as inactive and update its status
                sensors[i].active = false;
                num_active--;
            }
        }
    }
}

// Define a function to validate uniqueness of device IDs before insertion
void validate_device_id(int device_id) {
    // Loop through each sensor and check if the device ID already exists
    for (int i = 0; i < num_sensors; i++) {
        if (sensors[i].device_id == device_id) {
            // If a duplicate is detected, update the existing sensor record's active flag instead of creating a new one
            sensors[i].active = true;
            return;
        }
    }
}

// Define a function to generate random values within a specified range
int rand_range(int min, int max) {
    // Generate a random number between the minimum and maximum values
    return (rand() % (max - min + 1)) + min;
}
```
