    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu == NULL) {
        return NULL;
    }
    pdu->rx_ue_information = rx_ue_information;
    pdu->rnti = rnti;
