    }
    pthread_mutex_lock(&lock);
    pool_node_t *new_node = malloc(sizeof(pool_node_t));
    new_node->pdu = pdu;
    new_node->next = head;
    head = new_node;
    pthread_mutex_unlock(&lock);
}

// Function to remove a CRC indication PDU from the pool
void remove_crc_indication_pdu(RX_UE_INFORMATION_TAG rx_ue_information, RNTI rnti) {
    pthread_mutex_lock(&lock);
    pool_node_t *current = head;
    while (current != NULL) {
        if (current->pdu->rx_ue_information == rx_ue_information && current->pdu->rnti == rnti) {
            free_crc_indication_pdu(current->pdu);
            pool_node_t *next = current->next;
            free(current);
            head = next;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
