// Function to read configuration settings from a file and return a pointer to a config structure
struct config *read_config(char *file_name) {
    // Open the configuration file
    FILE *fp = fopen(file_name, "r");
    if (fp == NULL) {
        syslog(LOG_ERR, "Failed to open configuration file %s", file_name);
        return NULL;
    }

    // Read each line of the file and parse it as a key-value pair
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    struct config *config = malloc(sizeof(struct config));
    if (config == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for configuration");
        return NULL;
    }
    while ((read = getline(&line, &len, fp)) != -1) {
        // Skip empty lines and comments
        if (strlen(line) == 0 || line[0] == '#') {
            continue;
        }

        // Split the line into key and value using a space as delimiter
        char *key = strtok(line, " ");
        char *value = strtok(NULL, " ");
        if (key != NULL && value != NULL) {
            struct config_entry *config_entry = malloc(sizeof(struct config_entry));
            if (config_entry == NULL) {
                syslog(LOG_ERR, "Failed to allocate memory for configuration entry");
                return NULL;
            }
            config_entry->key = key;
            config_entry->value = value;
            config->count++;
        }
    }

    // Close the file and return the configuration structure
    fclose(fp);
    return config;
}

// Function to free a configuration structure
void free_config(struct config *config) {
    if (config != NULL) {
        for (int i = 0; i < config->count; i++) {
            struct config_entry *config_entry = &config->entries[i];
            free(config_entry->key);
            free(config_entry->value);
        }
        free(config);
    }
}

