    if (cache == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for theme bitmap cache");
        return NULL;
    }
    cache->size = size;
    cache->count = 0;
    cache->bitmaps = malloc(sizeof(struct theme_bitmap *) * size);
    if (cache->bitmaps == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for theme bitmap array");
        return NULL;
    }
    return cache;
}

// Function to free a theme bitmap cache structure
void free_theme_bitmap_cache(struct theme_bitmap_cache *cache) {
    if (cache != NULL) {
        for (int i = 0; i < cache->count; i++) {
            struct theme_bitmap *bitmap = cache->bitmaps[i];
            free(bitmap);
        }
        free(cache->bitmaps);
        free(cache);
    }
}

// Function to add a new bitmap to the cache and return its index
int add_bitmap_to_cache(struct theme_bitmap_cache *cache, struct theme_bitmap *bitmap) {
    if (cache->count == cache->size) {
        // Cache is full, need to evict an element
        int min_index = 0;
        for (int i = 1; i < cache->count; i++) {
            if (cache->bitmaps[i]->access_time < cache->bitmaps[min_index]->access_time) {
                min_index = i;
            }
        }
        struct theme_bitmap *evicted_bitmap = cache->bitmaps[min_index];
        free(evicted_bitmap);
        cache->bitmaps[min_index] = bitmap;
    } else {
        // Cache has space, simply add the new element
        cache->bitmaps[cache->count++] = bitmap;
    }
    return cache->count - 1;
}

// Function to get a bitmap from the cache by its index
struct theme_bitmap *get_bitmap_from_cache(struct theme_bitmap_cache *cache, int index) {
    if (index < 0 || index >= cache->count) {
        return NULL;
    }
    return cache->bitmaps[index];
}

