                int *new_array = realloc(array, sizeof(int) * capacity);
                if (new_array == NULL) {
                    syslog(LOG_ERR, "Failed to resize integer array");
                    return NULL;
                }
                array = new_array;
            }
        }
    }
    // Return the array of integers
    int *result = malloc(sizeof(int) * size);
    if (result == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for integer result");
        return NULL;
    }
    memcpy(result, array, sizeof(int) * size);
    free(array);
    return result;
}

