#include <pthread.h>
#include <time.h>

// Define the record structure
typedef struct {
    long offset;
    int key;
    int value;
} Record;

// Define the hash table structure
typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} HashTable;

// Initialize a new hash table with a given capacity
HashTable* init_hash_table(size_t capacity) {
    HashTable* ht = malloc(sizeof(HashTable));
    if (!ht) {
        perror("Failed to allocate memory for hash table");
        return NULL;
    }
    ht->records = calloc(capacity, sizeof(Record));
    if (!ht->records) {
        perror("Failed to allocate memory for record array");
        free(ht);
        return NULL;
    }
    ht->capacity = capacity;
    ht->size = 0;
    pthread_mutex_init(&ht->mutex, NULL);
    return ht;
}

// Insert a new record into the hash table
int insert(HashTable* ht, int key, int value) {
    if (!ht) {
        perror("Invalid hash table");
        return -1;
    }
    pthread_mutex_lock(&ht->mutex);
    // Generate a random offset for the record
    long offset = rand() % 1000000;
    Record* new_record = malloc(sizeof(Record));
    if (!new_record) {
        perror("Failed to allocate memory for new record");
        pthread_mutex_unlock(&ht->mutex);
        return -1;
    }
    new_record->offset = offset;
    new_record->key = key;
    new_record->value = value;
    // Check if the hash table is full and needs to be resized
    if (ht->size == ht->capacity) {
        HashTable* new_ht = realloc(ht, sizeof(HashTable) + (ht->capacity * 2));
        if (!new_ht) {
            perror("Failed to resize hash table");
            free(new_record);
            pthread_mutex_unlock(&ht->mutex);
            return -1;
        }
        ht = new_ht;
    }
    // Insert the record into the hash table
    size_t index = offset % ht->capacity;
    while (ht->records[index].key != 0) {
        index++;
        if (index == ht->capacity) {
            index = 0;
        }
    }
    ht->records[index] = *new_record;
    ht->size++;
    pthread_mutex_unlock(&ht->mutex);
    return 0;
}

// Delete a record from the hash table
int delete(HashTable* ht, int key) {
    if (!ht) {
        perror("Invalid hash table");
        return -1;
    }
    pthread_mutex_lock(&ht->mutex);
    // Find the index of the record to be deleted
    size_t index = 0;
    while (index < ht->capacity && ht->records[index].key != key) {
        index++;
    }
    if (index == ht->capacity) {
        pthread_mutex_unlock(&ht->mutex);
        return -1;
    }
    // Remove the record from the hash table
    Record* deleted_record = &ht->records[index];
    size_t i = index + 1;
    while (i < ht->capacity) {
        if (ht->records[i].key != 0) {
            ht->records[index] = ht->records[i];
            index++;
        }
        i++;
    }
    ht->size--;
    pthread_mutex_unlock(&ht->mutex);
    free(deleted_record);
    return 0;
}

// Traverse the hash table and print all records
void traverse(HashTable* ht) {
    if (!ht) {
        perror("Invalid hash table");
        return;
    }
    pthread_mutex_lock(&ht->mutex);
    for (size_t i = 0; i < ht->capacity; i++) {
        Record* record = &ht->records[i];
        if (record->key != 0) {
            printf("Record: offset=%ld, key=%d, value=%d\n", record->offset, record->key, record->value);
        }
    }
    pthread_mutex_unlock(&ht->mutex);
}

// Periodically evaluate and optimize memory usage
void optimize_memory() {
    // Implement your own optimization strategy here
}

int main() {
    srand(time(NULL));
    HashTable* ht = init_hash_table(1000);
    if (!ht) {
        perror("Failed to initialize hash table");
        return 1;
    }
    // Insert records into the hash table
    for (int i = 0; i < 1000; i++) {
        int key = rand() % 1000;
        int value = rand() % 1000;
        insert(ht, key, value);
    }
    // Delete a record from the hash table
    delete(ht, 500);
    // Traverse the hash table and print all records
    traverse(ht);
    // Periodically evaluate and optimize memory usage
    optimize_memory();
    return 0;
}
