    // Insert a new data point into the list and update its timestamp
    void insert_data_point(data_point *new_data_point) {
        // Create a new node for the data point
        data_point_node *new_node = malloc(sizeof(data_point_node));
        if (new_node == NULL) {
            printf("Error: Memory allocation failed\n");
            return;
        }

        // Set the timestamp of the new data point to the current system time
        new_data_point->timestamp = time(NULL);

        // Insert the new node into the list
        if (*dataset == NULL) {
            *dataset = new_node;
            new_node->prev = new_node->next = new_node;
        } else {
            data_point_node *last_node = (*dataset)->prev;
            last_node->next = new_node;
            new_node->prev = last_node;
            new_node->next = *dataset;
            (*dataset)->prev = new_node;
        }
    }

