        data_point_node *oldest_node = (*dataset)->prev;
        while (oldest_node != NULL && oldest_node->data_point->timestamp < time(NULL) - TIMESTAMP_THRESHOLD) {
            delete_data_point(oldest_node->data_point->id);
            oldest_node = (*dataset)->prev;
        }
    }

