    file_metadata->filesize = filesize;
    transformation_rules->rule_name = NULL;
    transformation_rules->rule_value = NULL;
    for (int i = 0; i < max_threads; i++) {
        struct thread_info *thread_info = (struct thread_info *)malloc(sizeof(struct thread_info));
        if (!thread_info) {
            fprintf(stderr, "Error: Failed to allocate memory for thread info\n");
            return 1;
        }
        thread_info->thread_id = threads[i];
        thread_info->thread_index = i;
        thread_info->file_metadata = file_metadata;
        thread_info->transformation_rules = transformation_rules;
        thread_info->semaphore = semaphore;
    }
    for (int i = 0; i < max_threads; i++) {
        pthread_create(&threads[i], NULL, thread_worker, (void *)&thread_info[i]);
    }
    for (int i = 0; i < max_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    // Close the file handle and free memory
    fclose(file_handle);
    free(file_metadata);
    free(transformation_rules);
    free(semaphore);
    free(thread_info);
    free(threads);

    return 0;
}

void *thread_worker(void *arg) {
    struct thread_info *thread_info = (struct thread_info *)arg;
    pthread_t thread_id = thread_info->thread_id;
    int thread_index = thread_info->thread_index;
    struct file_metadata *file_metadata = thread_info->file_metadata;
    struct transformation_rules *transformation_rules = thread_info->transformation_rules;
    sem_t *semaphore = thread_info->semaphore;

    // Parse the input file and generate an output file based on the given rules
    FILE *output_file = fopen(argv[2], "w+b");
    if (!output_file) {
        fprintf(stderr, "Error: Failed to open output file\n");
        return NULL;
    }
    size_t filesize = file_metadata->filesize;
    size_t offset = thread_index * (filesize / max_threads);
    size_t length = (thread_index == max_threads - 1) ? (filesize % max_threads) : (filesize / max_threads);
    fseek(file_handle, offset, SEEK_SET);
    char *buffer = (char *)malloc(length);
    if (!buffer) {
        fprintf(stderr, "Error: Failed to allocate memory for buffer\n");
        return NULL;
    }
    size_t bytes_read = fread(buffer, 1, length, file_handle);
    if (bytes_read != length) {
        fprintf(stderr, "Error: Failed to read input file\n");
        return NULL;
    }
    for (int i = 0; i < bytes_read; i++) {
        // Apply the transformation rules to each byte in the buffer
        if (transformation_rules->rule_name) {
            switch (transformation_rules->rule_value[i]) {
                case 'A':
                    buffer[i] = 'a';
                    break;
                case 'B':
                    buffer[i] = 'b';
                    break;
                default:
                    break;
            }
        }
    }
    // Write the transformed contents of the input file to the output file
    size_t bytes_written = fwrite(buffer, 1, length, output_file);
    if (bytes_written != length) {
        fprintf(stderr, "Error: Failed to write output file\n");
        return NULL;
    }
    free(buffer);
    fclose(output_file);

    // Log the transformation step and update the shared logging information structure
    if (enable_logging) {
        struct logging_info *logging_info = (struct logging_info *)malloc(sizeof(struct logging_info));
