#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a struct to represent a data point
struct data_point {
    double value;
    char* key;
};

// Define a struct to represent the dynamic data structure
struct dynamic_data {
    size_t num_elements;
    size_t max_size;
    size_t current_size;
    pthread_mutex_t mutex;
    double* values;
    char** keys;
    struct data_point* data_points;
};

// Initialize the dynamic data structure with a given maximum size
void init_dynamic_data(struct dynamic_data* dd, size_t max_size) {
    dd->num_elements = 0;
    dd->max_size = max_size;
    dd->current_size = 0;
    pthread_mutex_init(&dd->mutex, NULL);
    dd->values = (double*)malloc(sizeof(double) * max_size);
    dd->keys = (char**)malloc(sizeof(char*) * max_size);
    dd->data_points = (struct data_point*)malloc(sizeof(struct data_point) * max_size);
}

// Add a new entry to the dynamic data structure
void add_entry(struct dynamic_data* dd, double value, char* key) {
    pthread_mutex_lock(&dd->mutex);
    if (dd->current_size == dd->max_size) {
        // Reallocate memory to accommodate new entries
        size_t new_size = dd->max_size * 2;
        dd->values = (double*)realloc(dd->values, sizeof(double) * new_size);
        dd->keys = (char**)realloc(dd->keys, sizeof(char*) * new_size);
        dd->data_points = (struct data_point*)realloc(dd->data_points, sizeof(struct data_point) * new_size);
        dd->max_size = new_size;
    }
    // Add the new entry to the data structure
    dd->values[dd->current_size] = value;
    dd->keys[dd->current_size] = key;
    dd->data_points[dd->current_size].value = value;
    dd->data_points[dd->current_size].key = key;
    dd->num_elements++;
    dd->current_size++;
    pthread_mutex_unlock(&dd->mutex);
}

// Get the number of elements in the dynamic data structure
size_t get_num_elements(struct dynamic_data* dd) {
    return dd->num_elements;
}

// Get the value and key for a given index in the dynamic data structure
void get_entry(struct dynamic_data* dd, size_t index, double* value, char** key) {
    *value = dd->values[index];
    *key = dd->keys[index];
}

// Clean up the dynamic data structure and free all memory
void cleanup_dynamic_data(struct dynamic_data* dd) {
    pthread_mutex_destroy(&dd->mutex);
    free(dd->values);
    free(dd->keys);
    free(dd->data_points);
}
