#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
} record;

void setupSystem(int numRecords, int minValue, int maxValue) {
    // Allocate memory for the arrays
    long *offsets = malloc(numRecords * sizeof(long));
    int *keys = malloc(numRecords * sizeof(int));
    record *records = malloc(numRecords * sizeof(record));

    // Initialize the arrays with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        offsets[i] = rand() % (maxValue - minValue + 1) + minValue;
        keys[i] = rand() % (maxValue - minValue + 1) + minValue;
        records[i].key = keys[i];
        records[i].offset = offsets[i];
    }

    // Handle error checking and memory management
    if (!offsets || !keys || !records) {
        printf("Error: Failed to allocate memory for arrays\n");
        exit(1);
    }

    // Print the initialized arrays
    printf("Offsets:\n");
    for (int i = 0; i < numRecords; i++) {
        printf("%ld ", offsets[i]);
    }
    printf("\n");

    printf("Keys:\n");
    for (int i = 0; i < numRecords; i++) {
        printf("%d ", keys[i]);
    }
    printf("\n");

    printf("Records:\n");
    for (int i = 0; i < numRecords; i++) {
        printf("{%d, %ld} ", records[i].key, records[i].offset);
    }
    printf("\n");

    // Free the memory allocated for the arrays
    free(offsets);
    free(keys);
    free(records);
}
