    $record = getRecordById($id);
    if ($record) {
        updateRecord($record, $data);
        return $response->withStatus(200)->withJson(['message' => 'Resource updated successfully']);
    } else {
        return $response->withStatus(404)->withJson(['message' => 'Resource not found']);
    }
});

$router->delete('/resource/{id}', function ($request, $response) {
    // Delete a resource using the HTTP DELETE method
    $id = $request->getAttribute('id');
    $record = getRecordById($id);
    if ($record) {
        deleteRecord($record);
        return $response->withStatus(204)->withJson(['message' => 'Resource deleted successfully']);
    } else {
        return $response->withStatus(404)->withJson(['message' => 'Resource not found']);
    }
});

// Handle incoming HTTP requests and route them to the appropriate endpoints
$router->dispatch();
```
