use std::fs;
use std::path::Path;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Instant;

struct FileInfo {
    path: String,
    size: u64,
}

struct ParserState {
    file_info: Arc<Mutex<FileInfo>>,
    parser: LexerParser,
}

impl ParserState {
    fn new(file_info: Arc<Mutex<FileInfo>>) -> Self {
        Self {
            file_info,
            parser: LexerParser::new(),
        }
    }
}

fn parse_files(dir_path: &str, max_size: u64, extensions: Vec<String>) {
    let start = Instant::now();
    let mut file_infos = vec![];
    for entry in fs::read_dir(dir_path).unwrap() {
        let path = entry.unwrap().path();
        if !Path::is_file(&path) || extensions.iter().all(|ext| !path.ends_with(ext)) {
            continue;
        }
        let file_info = FileInfo {
            path: path.to_str().unwrap().to_string(),
            size: fs::metadata(&path).unwrap().len(),
        };
        if file_info.size > max_size {
            continue;
        }
        file_infos.push(file_info);
    }
    let num_threads = 4; // TODO: make this configurable via command-line option
    let mut parser_states: Vec<ParserState> = vec![];
    for _ in 0..num_threads {
        parser_states.push(ParserState::new(Arc::new(Mutex::new(FileInfo::default()))));
    }
    let (tx, rx) = std::sync::mpsc::channel();
    for file_info in file_infos {
        tx.send(file_info).unwrap();
    }
    drop(tx);
    for _ in 0..num_threads {
        let parser_state = Arc::new(Mutex::new(ParserState::default()));
        thread::spawn(move || {
            while let Ok(file_info) = rx.recv() {
                let mut file = fs::File::open(&file_info.path).unwrap();
                let mut buffer = String::new();
                file.read_to_string(&mut buffer).unwrap();
                let parser = LexerParser::new();
                let tokens = parser.parse(buffer);
                // TODO: process tokens and generate LLVM IR code
            }
        });
    }
    println!("Parsed {} files in {:?}", file_infos.len(), start.elapsed());
}
