#include <openssl/evp.h>
#include <openssl/err.h>
#include <string.h>
#include <stdlib.h>
#include <stdio.h>
#include <dirent.h>
#include <sys/stat.h>
#include <unistd.h>

// Define the supported cipher modes
#define CIPHER_MODES { "ECB", "EDE", "EDE3", "CFB" }

// Define the default theme directory
#define DEFAULT_THEME_DIR "/path/to/theme/directory"

// Function to initialize a new EVP_CIPHER structure for the selected cipher mode
EVP_CIPHER* init_cipher(const char* mode) {
  // Check if the specified cipher mode is supported
  if (!strcmp(mode, "ECB") || !strcmp(mode, "EDE") || !strcmp(mode, "EDE3") || !strcmp(mode, "CFB")) {
    return EVP_get_cipherbyname(mode);
  } else if (!strcmp(mode, "NULL")) {
    // Return a null cipher for testing purposes
    return NULL;
  } else {
    // Throw an error if the specified cipher mode is not supported
    fprintf(stderr, "Unsupported cipher mode: %s\n", mode);
    exit(1);
  }
}

// Function to parse PNG files from the cache root directory and initialize theme bitmaps
void init_theme_bitmaps() {
  // Get the current working directory
  char* cwd = getcwd(NULL, 0);

  // Check if a default theme directory is configured
  if (strcmp(DEFAULT_THEME_DIR, "") == 0) {
    // Set the default theme directory to the current working directory
    DEFAULT_THEME_DIR = cwd;
  }

  // Open the cache root directory
  DIR* dir = opendir(DEFAULT_THEME_DIR);

  // Check if the cache root directory exists
  if (dir == NULL) {
    fprintf(stderr, "Cache root directory does not exist: %s\n", DEFAULT_THEME_DIR);
    exit(1);
  }

  // Loop through each file in the cache root directory
  struct dirent* entry;
  while ((entry = readdir(dir)) != NULL) {
    // Check if the file is a PNG file
    if (strcmp(entry->d_name + strlen(entry->d_name) - 4, ".png") == 0) {
      // Initialize a new theme bitmap with the file path and cipher mode
      EVP_CIPHER* cipher = init_cipher("ECB");
      if (cipher != NULL) {
        char* file_path = malloc(strlen(DEFAULT_THEME_DIR) + strlen(entry->d_name) + 1);
        sprintf(file_path, "%s/%s", DEFAULT_THEME_DIR, entry->d_name);
        theme_bitmap_t* bitmap = init_theme_bitmap(file_path, cipher);
        if (bitmap != NULL) {
          // Add the theme bitmap to the cache
          add_to_cache(bitmap);
        } else {
          fprintf(stderr, "Failed to initialize theme bitmap: %s\n", file_path);
        }
      } else {
        fprintf(stderr, "Unsupported cipher mode: ECB\n");
      }
    }
  }

  // Close the cache root directory
  closedir(dir);
}

// Function to add a theme bitmap to the cache
void add_to_cache(theme_bitmap_t* bitmap) {
  // Check if the cache is full
  if (cache_full()) {
    // Recycle the oldest theme bitmap in the cache
    recycle_oldest_bitmap();
  }

  // Add the new theme bitmap to the cache
  cache[cache_size++] = bitmap;
}

// Function to check if the cache is full
int cache_full() {
  return cache_size == MAX_CACHE_SIZE;
}

// Function to recycle the oldest theme bitmap in the cache
void recycle_oldest_bitmap() {
  // Find the oldest theme bitmap in the cache
  int oldest = 0;
  for (int i = 1; i < cache_size; i++) {
    if (cache[i]->last_used < cache[oldest]->last_used) {
      oldest = i;
    }
  }

  // Set the oldest theme bitmap to null
  cache[oldest] = NULL;
}

// Function to initialize a new theme bitmap with the specified file path and cipher mode
theme_bitmap_t* init_theme_bitmap(const char* file_path, EVP_CIPHER* cipher) {
  // Check if the specified file exists
  struct stat sb;
  if (stat(file_path, &sb) == -1) {
    fprintf(stderr, "File does not exist: %s\n", file_path);
    return NULL;
  }

  // Check if the specified cipher mode is supported
  if (!strcmp(cipher->name(), "ECB") || !strcmp(cipher->name(), "EDE") || !strcmp(cipher->name(), "EDE3") || !strcmp(cipher->name(), "CFB")) {
    // Initialize a new theme bitmap with the file path and cipher mode
    theme_bitmap_t* bitmap = malloc(sizeof(theme_bitmap_t));
    bitmap->file_path = strdup(file_path);
    bitmap->cipher = cipher;
    bitmap->last_used = time(NULL);
    return bitmap;
  } else {
    // Throw an error if the specified cipher mode is not supported
    fprintf(stderr, "Unsupported cipher mode: %s\n", cipher->name());
    exit(1);
  }
}

// Function to get a theme bitmap from the cache by file path and cipher mode
theme_bitmap_t* get_from_cache(const char* file_path, EVP_CIPHER* cipher) {
  // Loop through each theme bitmap in the cache
  for (int i = 0; i < cache_size; i++) {
    // Check if the current theme bitmap matches the specified file path and cipher mode
    if (!strcmp(cache[i]->file_path, file_path) && !strcmp(cache[i]->cipher->name(), cipher->name())) {
      // Update the last used time for the theme bitmap
      cache[i]->last_used = time(NULL);
      return cache[i];
    }
  }

  // Return null if no matching theme bitmap is found in the cache
  return NULL;
}

// Function to set a theme bitmap to null in the cache by file path and cipher mode
void set_to_null(const char* file_path, EVP_CIPHER* cipher) {
  // Loop through each theme bitmap in the cache
  for (int i = 0; i < cache_size; i++) {
    // Check if the current theme bitmap matches the specified file path and cipher mode
    if (!strcmp(cache[i]->file_path, file_path) && !strcmp(cache[i]->cipher->name(), cipher->name())) {
      // Set the theme bitmap to null in the cache
      cache[i] = NULL;
      return;
    }
  }
}

// Function to get a pointer to an EVP_CIPHER structure representing the selected cipher mode
EVP_CIPHER* get_cipher(const char* mode) {
  // Initialize a new EVP_CIPHER structure for the specified cipher mode
  return init_cipher(mode);
}
```
