import com.thirdparty.imageprocessing.*;

public class BatchConvertImages {
    private static final String CONFIG_FILE = "config.json";

    public static int batchConvertImages(String imageDir, String pdfFile, String configFile) throws IOException {
        // Parse and apply configuration settings from JSON file
        Map<String, Object> settings = parseAndApplySettings(configFile);

        // Initialize image processing tool
        ImageProcessingTool tool = new ImageProcessingTool();

        // Iterate over images in directory
        File[] files = new File(imageDir).listFiles();
        for (File file : files) {
            if (!file.isDirectory()) {
                // Deserialize object from bytes
                Object obj = deserializeObjectFromBytes(file.getBytes());

                // Convert image to PDF using tool
                String pdfPath = settings.get("pdf_path").toString();
                int result = tool.convertImageToPDF(obj, pdfPath);

                if (result != 0) {
                    return result;
                }
            }
        }

        // Close image processing tool
        tool.close();

        return 0;
    }

    private static Map<String, Object> parseAndApplySettings(String configFile) throws IOException {
        // Read JSON file and validate structure
        JsonReader reader = new JsonReader(new FileReader(configFile));
        JsonObject json = (JsonObject) reader.read();

        if (!json.has("batch_size") || !json.has("pdf_path")) {
            throw new RuntimeException("Invalid configuration file");
        }

        // Apply settings to map
        Map<String, Object> settings = new HashMap<>();
        settings.put("batch_size", json.getInt("batch_size"));
        settings.put("pdf_path", json.getString("pdf_path"));

        return settings;
    }

    private static Object deserializeObjectFromBytes(byte[] bytes) {
        try (ByteArrayInputStream bais = new ByteArrayInputStream(bytes);
             ObjectInputStream ois = new ObjectInputStream(bais)) {
            return ois.readObject();
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("Failed to deserialize object", e);
        } finally {
            // Close resources to prevent memory leaks
            try {
                bais.close();
                ois.close();
            } catch (IOException e) {
                // Ignore
            }
        }
    }
}
```
