using System.Xml.Linq;

public class WebsiteManager
{
    private const string DefaultWebConfigTemplate = @"<?xml version=""1.0"" encoding=""utf-8""?>
<configuration>
  <system.webServer>
    <handlers>
      <add name=""aspNetCore"" path=""*"" verb=""*" modules=""AspNetCoreModuleV2"" resourceType=""Unspecified"" />
    </handlers>
    <aspNetCore processPath=""%LAUNCHER_PATH%"">
      <environmentVariables>
        <environmentVariable name=""ASPNETCORE_ENVIRONMENT"" value=""Development"" />
      </environmentVariables>
    </aspNetCore>
  </system.webServer>
</configuration>";

    private const string WebConfigSchema = @"<?xml version=""1.0"" encoding=""utf-8""?>
<xs:schema xmlns:xs=""http://www.w3.org/2001/XMLSchema"" elementFormDefault=""qualified"">
  <xs:element name=""configuration"">
    <xs:complexType>
      <xs:sequence>
        <xs:element name=""system.webServer"">
          <xs:complexType>
            <xs:sequence>
              <xs:element name=""handlers"" minOccurs=""0"" maxOccurs=""unbounded"">
                <xs:complexType>
                  <xs:sequence>
                    <xs:element name=""add"" type=""xs:string"" />
                  </xs:sequence>
                </xs:complexType>
              </xs:element>
              <xs:element name=""aspNetCore"" minOccurs=""0"">
                <xs:complexType>
                  <xs:sequence>
                    <xs:element name=""processPath"" type=""xs:string"" />
                    <xs:element name=""environmentVariables"" minOccurs=""0"">
                      <xs:complexType>
                        <xs:sequence>
                          <xs:element name=""environmentVariable"" type=""xs:string"" />
                        </xs:sequence>
                      </xs:complexType>
                    </xs:element>
                  </xs:sequence>
                </xs:complexType>
              </xs:element>
            </xs:sequence>
          </xs:complexType>
        </xs:element>
      </xs:sequence>
    </xs:complexType>
  </xs:element>
</xs:schema>";

    private const string WebConfigFile = "web.config";
    private const string LauncherPath = "%LAUNCHER_PATH%";
    private const int TimeoutMilliseconds = 10000; // 10 seconds
    private const int RetryCount = 3;
    private const int RetryDelayMilliseconds = 500; // 0.5 seconds

    public static void AddWebsite(string directoryPath, string siteName)
    {
        if (!Directory.Exists(directoryPath))
        {
            throw new DirectoryNotFoundException($"The specified directory '{directoryPath}' does not exist.");
        }

        if (IsLocked(directoryPath))
        {
            throw new IOException($"The specified directory '{directoryPath}' is locked by another process.");
        }

        var webConfigFile = Path.Combine(directoryPath, WebConfigFile);
        if (!File.Exists(webConfigFile))
        {
            GenerateDefaultWebConfig(directoryPath);
        }

        ValidateWebConfigSchema(webConfigFile);

        if (IsSiteRunning(siteName))
        {
            throw new InvalidOperationException($"A site with the name '{siteName}' is already running.");
        }

        StartSite(directoryPath, siteName);
    }

    private static bool IsLocked(string directoryPath)
    {
        try
        {
            using (var fileStream = File.Open(directoryPath, FileMode.Open, FileAccess.ReadWrite, FileShare.None))
            {
                return false;
            }
        }
        catch (IOException)
        {
            return true;
        }
    }

    private static void GenerateDefaultWebConfig(string directoryPath)
    {
        var webConfigFile = Path.Combine(directoryPath, WebConfigFile);
        using (var fileStream = File.Create(webConfigFile))
        {
            var xmlWriter = new XmlTextWriter(fileStream, Encoding.UTF8);
            xmlWriter.WriteRaw(DefaultWebConfigTemplate);
            xmlWriter.Close();
        }
    }

    private static void ValidateWebConfigSchema(string webConfigFile)
    {
        var xdoc = XDocument.Load(webConfigFile);
        var schemaSet = new XmlSchemaSet();
        schemaSet.Add("", WebConfigSchema);
        xdoc.Validate(schemaSet, (o, e) =>
        {
            throw new InvalidOperationException($"The web.config file at '{webConfigFile}' is not valid.", e);
        });
    }

    private static bool IsSiteRunning(string siteName)
    {
        var process = Process.GetProcessesByName(siteName).FirstOrDefault();
        return process != null && !process.HasExited;
    }

    private static void StartSite(string directoryPath, string siteName)
    {
        var launcherPath = Path.Combine(directoryPath, LauncherPath);
        var processStartInfo = new ProcessStartInfo(launcherPath)
        {
            UseShellExecute = false,
            CreateNoWindow = true,
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            WorkingDirectory = directoryPath
        };

        using (var process = new Process())
        {
            process.StartInfo = processStartInfo;
            process.EnableRaisingEvents = true;
            process.Exited += (sender, e) =>
            {
                Console.WriteLine($"The site '{siteName}' has exited.");
            };

            try
            {
                process.Start();
            }
            catch (Exception ex)
            {
                throw new InvalidOperationException($"Failed to start the site '{siteName}'.", ex);
            }
        }
    }
}
```
