struct database_config {
    char *host;
    int port;
    char *username;
    char *password;
    char *ssl_mode;
};

void load_and_validate_database_config(const char *filepath) {
    json_object *json = json_object_from_file(filepath);
    if (json == NULL) {
        log_error("Failed to parse JSON configuration file: %s", strerror(errno));
        return;
    }

    struct database_config config;
    memset(&config, 0, sizeof(struct database_config));

    json_object *host = json_object_object_get(json, "host");
    if (host == NULL) {
        log_error("Missing required field 'host' in JSON configuration file");
        goto cleanup;
    }
    config.host = strdup(json_object_get_string(host));

    json_object *port = json_object_object_get(json, "port");
    if (port == NULL) {
        log_error("Missing required field 'port' in JSON configuration file");
        goto cleanup;
    }
    config.port = json_object_get_int(port);
    if (config.port < 1 || config.port > 65535) {
        log_error("Invalid value for field 'port' in JSON configuration file");
        goto cleanup;
    }

    json_object *username = json_object_object_get(json, "username");
    if (username == NULL) {
        log_error("Missing required field 'username' in JSON configuration file");
        goto cleanup;
    }
    config.username = strdup(json_object_get_string(username));

    json_object *password = json_object_object_get(json, "password");
    if (password == NULL) {
        log_error("Missing required field 'password' in JSON configuration file");
        goto cleanup;
    }
    config.password = strdup(json_object_get_string(password));

    json_object *ssl_mode = json_object_object_get(json, "ssl_mode");
    if (ssl_mode == NULL) {
        log_error("Missing required field 'ssl_mode' in JSON configuration file");
        goto cleanup;
    }
    config.ssl_mode = strdup(json_object_get_string(ssl_mode));

    if (strcmp(config.ssl_mode, "enable") && strcmp(config.ssl_mode, "disable")) {
        log_error("Invalid value for field 'ssl_mode' in JSON configuration file");
        goto cleanup;
    }

    // Validate host is a valid IP address or domain name
    if (!validate_host(config.host)) {
        log_error("Invalid value for field 'host' in JSON configuration file");
        goto cleanup;
    }

    // Validate port is a positive integer within the range of 1 to 65535
    if (!validate_port(config.port)) {
        log_error("Invalid value for field 'port' in JSON configuration file");
        goto cleanup;
    }

    // Validate username and password are not empty strings
    if (strlen(config.username) == 0 || strlen(config.password) == 0) {
        log_error("Invalid value for fields 'username' or 'password' in JSON configuration file");
        goto cleanup;
    }

    // Validate ssl_mode is either 'enable' or 'disable'
    if (strcmp(config.ssl_mode, "enable") && strcmp(config.ssl_mode, "disable")) {
        log_error("Invalid value for field 'ssl_mode' in JSON configuration file");
        goto cleanup;
    }

    // Load essential fields immediately and defer others until needed
    load_essential_fields(&config);

cleanup:
    json_object_put(json);
}

