using System;
using System.Collections.Generic;
using System.IO;
using System.Threading.Tasks;
using System.Net.Http;
using Newtonsoft.Json;

public class ImageUploader
{
    private readonly HttpClient _httpClient;
    private readonly string _cloudStorageUrl;

    public ImageUploader(string cloudStorageUrl)
    {
        _httpClient = new HttpClient();
        _cloudStorageUrl = cloudStorageUrl;
    }

    public async Task<List<UploadStatus>> UploadImagesAsync(IEnumerable<string> imageFilenames)
    {
        var uploadTasks = new List<Task<UploadStatus>>();

        foreach (var filename in imageFilenames)
        {
            var filePath = Path.Combine(Directory.GetCurrentDirectory(), filename);
            var fileStream = File.OpenRead(filePath);

            var uploadRequest = new HttpRequestMessage(HttpMethod.Post, _cloudStorageUrl)
            {
                Content = new StreamContent(fileStream)
            };

            uploadTasks.Add(UploadImageAsync(uploadRequest));
        }

        await Task.WhenAll(uploadTasks);

        return uploadTasks.Select(task => task.Result).ToList();
    }

    private async Task<UploadStatus> UploadImageAsync(HttpRequestMessage request)
    {
        var response = await _httpClient.SendAsync(request);
        var content = await response.Content.ReadAsStringAsync();

        return JsonConvert.DeserializeObject<UploadStatus>(content);
    }
}

public class UploadStatus
{
    public string Filename { get; set; }
    public bool Success { get; set; }
    public string ErrorMessage { get; set; }
}
