using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Threading;
using System.Threading.Tasks;

public class StringHasher
{
    private const int MAX_STRING_LENGTH = 1024;
    private static readonly MD5 md5 = MD5.Create();

    public async Task<IEnumerable<string>> ProcessStringsAsync(IEnumerable<string> strings, int batchSize = 100)
    {
        var hashes = new List<string>();
        foreach (var string in strings)
        {
            if (string.Length > MAX_STRING_LENGTH)
            {
                throw new ArgumentException("String exceeds maximum length of 1024 characters");
            }

            var hash = GetHash(string);
            hashes.Add(hash);
        }

        return hashes;
    }

    private static string GetHash(string input)
    {
        using (var stream = new MemoryStream())
        {
            using (var writer = new StreamWriter(stream))
            {
                writer.Write(input);
                writer.Flush();
                stream.Position = 0;

                var hash = md5.ComputeHash(stream);
                return BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
            }
        }
    }
}
