    uint32_t numLeafNodes;
    uint32_t dataCapacity;
    std::vector<uint8_t> prefixLeafs;
    std::vector<float> data;
};

Octree initializeOctree(uint32_t featureSize, uint32_t numLeafNodes, uint32_t dataCapacity) {
    // Validate input data using a checksum to prevent unauthorized modifications
    if (featureSize == 0 || numLeafNodes == 0 || dataCapacity == 0) {
        throw std::invalid_argument("Invalid octree parameters");
    }

    // Dynamically allocate memory for the octree structure
    Octree* octree = new Octree();
    octree->featureSize = featureSize;
    octree->numLeafNodes = numLeafNodes;
    octree->dataCapacity = dataCapacity;

    // Update capacity if required
    if (octree->dataCapacity > 0) {
        octree->data.resize(octree->dataCapacity);
    }

    // Initialize memory for prefix leafs and data arrays
    octree->prefixLeafs.resize(numLeafNodes * featureSize);

    // Decompress binary payload representing the octree configuration
    std::vector<uint8_t> compressedData;
    decompressOctreeConfig(compressedData, octree->dataCapacity);

    // Store frequently accessed octree configurations in a cache to reduce redundant decompression and memory allocation overhead
    if (cache.find(octree) != cache.end()) {
        octree = cache[octree];
    } else {
        cache[octree] = octree;
    }

    // Load octree configuration from compressed data
    loadOctreeConfig(compressedData, octree);

    return *octree;
}

void decompressOctreeConfig(std::vector<uint8_t>& compressedData, uint32_t dataCapacity) {
    // Decompress binary payload representing the octree configuration using zlib library
    int ret = uncompress(&compressedData[0], &dataCapacity, &octreeConfig[0], octreeConfig.size());
    if (ret != Z_OK) {
        throw std::runtime_error("Failed to decompress octree configuration");
    }
}

void loadOctreeConfig(std::vector<uint8_t>& compressedData, Octree* octree) {
    // Load octree configuration from compressed data into memory
    uint32_t offset = 0;
    for (uint32_t i = 0; i < octree->numLeafNodes; ++i) {
        for (uint32_t j = 0; j < octree->featureSize; ++j) {
            octree->prefixLeafs[offset++] = compressedData[i * featureSize + j];
        }
    }
}
