    public class ArchiveReader
    {
        private readonly Dictionary<string, Func<Stream, object>> _deserializers = new Dictionary<string, Func<Stream, object>>();

        public ArchiveReader()
        {
            // Register deserialization functions for different compression formats
            _deserializers.Add("zip", stream => ZipFile.Read(stream));
            _deserializers.Add("gzip", stream => GZipStream.Read(stream));
            _deserializers.Add("tar.gz", stream => TarGzStream.Read(stream));
        }

        public object ReadArchive(string filePath, string compressionFormat)
