            // Open the archive file and read its metadata
            using (var fileStream = File.OpenRead(filePath))
            {
                var archiveMetadata = new ArchiveMetadata();
                archiveMetadata.CompressionFormat = compressionFormat;
                archiveMetadata.FileSize = fileStream.Length;

                // Deserialize the metadata into a data structure
                var deserializer = _deserializers[compressionFormat];
                var archiveData = deserializer(fileStream);

                // Verify the integrity of the archive data
                if (archiveMetadata.FileSize != archiveData.Length)
                {
                    throw new InvalidOperationException("Archive data is corrupted");
                }

                return archiveData;
            }
        }
    }
}
