#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define the record structure
typedef struct {
    int value;
    long *offset;
    int *key;
} record;

// Define the hash table for quick key-based lookups
typedef struct {
    int size;
    int count;
    record **records;
} hash_table;

// Define the linked list structure
typedef struct node {
    record *record;
    struct node *next;
} node;

// Define the memory management strategy
#define MEMORY_SIZE 1024*1024 // 1 MB
#define MEMORY_GROWTH_FACTOR 2
#define MEMORY_SHRINK_FACTOR 0.5

// Define the synchronization strategy
#define SYNCHRONIZATION_STRATEGY pthread_mutex_t mutex;

// Define the error handling mechanism
#define ERROR_HANDLING_MECHANISM perror("Error: ");

// Function to manage a dynamic collection of records in a multi-threaded environment
void *manage_records(void *args) {
    // Initialize the hash table and linked list
    hash_table *ht = (hash_table *)malloc(sizeof(hash_table));
    ht->size = MEMORY_SIZE;
    ht->count = 0;
    ht->records = (record **)malloc(ht->size * sizeof(record *));
    node *head = NULL;
    node *tail = NULL;

    // Initialize the memory management strategy
    long *memory_blocks = (long *)malloc(MEMORY_SIZE);
    int memory_block_count = 0;
    int memory_block_size = MEMORY_SIZE / MEMORY_GROWTH_FACTOR;

    // Initialize the synchronization strategy
    pthread_mutex_init(&mutex, NULL);

    // Loop until a termination signal is received
    while (1) {
        // Acquire the mutex lock
        pthread_mutex_lock(&mutex);

        // Check for memory allocation failures and handle them gracefully
        if (memory_block_count == MEMORY_SIZE) {
            ERROR_HANDLING_MECHANISM
            continue;
        }

        // Allocate a new memory block
        long *new_memory_block = (long *)malloc(memory_block_size);
        if (!new_memory_block) {
            ERROR_HANDLING_MECHANISM
            continue;
        }

        // Add the new memory block to the linked list
        node *new_node = (node *)malloc(sizeof(node));
        new_node->record = NULL;
        new_node->next = head;
        head = new_node;
        tail = head;

        // Increment the memory block count and size
        memory_block_count++;
        if (memory_block_size < MEMORY_SIZE) {
            memory_block_size *= MEMORY_GROWTH_FACTOR;
        }

        // Release the mutex lock
        pthread_mutex_unlock(&mutex);
    }

    // Clean up the resources
    free(ht->records);
    free(memory_blocks);
    pthread_mutex_destroy(&mutex);
}

// Function to insert a new record into the dynamic collection
void insert_record(int key, int value) {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Check if the hash table is full and needs to be resized
    if (ht->count == ht->size) {
        ERROR_HANDLING_MECHANISM
        return;
    }

    // Allocate a new record structure
    record *new_record = (record *)malloc(sizeof(record));
    if (!new_record) {
        ERROR_HANDLING_MECHANISM
        return;
    }

    // Initialize the record structure
    new_record->value = value;
    new_record->offset = NULL;
    new_record->key = key;

    // Add the new record to the hash table and linked list
    ht->records[ht->count] = new_record;
    node *new_node = (node *)malloc(sizeof(node));
    new_node->record = new_record;
    new_node->next = head;
    head = new_node;
    tail = head;

    // Increment the hash table count and release the mutex lock
    ht->count++;
    pthread_mutex_unlock(&mutex);
}

// Function to delete a record from the dynamic collection
void delete_record(int key) {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Check if the hash table is empty and handle it gracefully
    if (ht->count == 0) {
        ERROR_HANDLING_MECHANISM
        return;
    }

    // Find the record to be deleted in the hash table and linked list
    int index = -1;
    for (int i = 0; i < ht->count; i++) {
        if (ht->records[i]->key == key) {
            index = i;
            break;
        }
    }

    // Check if the record was found and handle it gracefully
    if (index == -1) {
        ERROR_HANDLING_MECHANISM
        return;
    }

    // Remove the record from the hash table and linked list
    node *node = head;
    while (node->next != NULL && node->next->record->key != key) {
        node = node->next;
    }
    if (node->next == NULL) {
        ERROR_HANDLING_MECHANISM
        return;
    }
    head = node->next;
    free(node);

    // Decrement the hash table count and release the mutex lock
    ht->count--;
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve a record from the dynamic collection
record *get_record(int key) {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Check if the hash table is empty and handle it gracefully
    if (ht->count == 0) {
        ERROR_HANDLING_MECHANISM
        return NULL;
    }

    // Find the record in the hash table and linked list
    int index = -1;
    for (int i = 0; i < ht->count; i++) {
        if (ht->records[i]->key == key) {
            index = i;
            break;
        }
    }

    // Check if the record was found and handle it gracefully
    if (index == -1) {
        ERROR_HANDLING_MECHANISM
        return NULL;
    }

    // Return the record from the hash table and linked list
    node *node = head;
    while (node->next != NULL && node->next->record->key != key) {
        node = node->next;
    }
    if (node->next == NULL) {
        ERROR_HANDLING_MECHANISM
        return NULL;
    }
    record *record = node->next->record;

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);

    // Return the record
    return record;
}

// Function to update a record in the dynamic collection
void update_record(int key, int value) {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Check if the hash table is empty and handle it gracefully
    if (ht->count == 0) {
        ERROR_HANDLING_MECHANISM
        return;
    }

    // Find the record to be updated in the hash table and linked list
    int index = -1;
    for (int i = 0; i < ht->count; i++) {
        if (ht->records[i]->key == key) {
            index = i;
            break;
        }
    }

    // Check if the record was found and handle it gracefully
    if (index == -1) {
        ERROR_HANDLING_MECHANISM
        return;
    }

    // Update the record in the hash table and linked list
    node *node = head;
    while (node->next != NULL && node->next->record->key != key) {
        node = node->next;
    }
    if (node->next == NULL) {
        ERROR_HANDLING_MECHANISM
        return;
    }
    record *record = node->next->record;
    record->value = value;

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);
}

// Function to traverse all records in the dynamic collection
void traverse_records() {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Check if the hash table is empty and handle it gracefully
    if (ht->count == 0) {
        ERROR_HANDLING_MECHANISM
        return;
    }

    // Traverse all records in the hash table and linked list
    node *node = head;
    while (node != NULL) {
        record *record = node->record;
        printf("%d: %d\n", record->key, record->value);
        node = node->next;
    }

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);
}

// Function to periodically check and release unused memory blocks
void check_and_release_memory() {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Check if any memory blocks are unused and handle it gracefully
    int unused_blocks = 0;
    for (int i = 0; i < memory_block_count; i++) {
        if (!memory_blocks[i]) {
            unused_blocks++;
        }
    }
    if (unused_blocks == 0) {
        ERROR_HANDLING_MECHANISM
        return;
    }

    // Release the unused memory blocks
    for (int i = 0; i < memory_block_count; i++) {
        if (!memory_blocks[i]) {
            free(memory_blocks[i]);
            memory_blocks[i] = NULL;
        }
    }

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);
}
