#include <assert.h>

// Define the record structure
typedef struct Record {
    int value;
    struct Record* next;
} Record;

// Define the hash table structure
typedef struct HashTable {
    int size;
    Record** buckets;
} HashTable;

// Define the memory pool structure
typedef struct MemoryPool {
    int size;
    void* data;
} MemoryPool;

// Define the dataset structure
typedef struct Dataset {
    int offset;
    int key;
    Record* record;
} Dataset;

// Function to initialize a new record with a random integer value within a specified range
Record* init_record(int min, int max) {
    Record* record = malloc(sizeof(Record));
    assert(record != NULL);
    record->value = rand() % (max - min + 1) + min;
    record->next = NULL;
    return record;
}

// Function to initialize a new hash table with a specified size
HashTable* init_hash_table(int size) {
    HashTable* hash_table = malloc(sizeof(HashTable));
    assert(hash_table != NULL);
    hash_table->size = size;
    hash_table->buckets = calloc(size, sizeof(Record*));
    assert(hash_table->buckets != NULL);
    return hash_table;
}

// Function to initialize a new memory pool with a specified size
MemoryPool* init_memory_pool(int size) {
    MemoryPool* memory_pool = malloc(sizeof(MemoryPool));
    assert(memory_pool != NULL);
    memory_pool->size = size;
    memory_pool->data = calloc(size, sizeof(Dataset));
    assert(memory_pool->data != NULL);
    return memory_pool;
}

// Function to insert a new record into the dataset
void insert_record(MemoryPool* memory_pool, int key, Record* record) {
    Dataset* dataset = (Dataset*)memory_pool->data + key;
    if (dataset->offset == 0) {
        dataset->offset = 1;
        dataset->key = key;
        dataset->record = record;
    } else {
        Record* current = dataset->record;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = record;
    }
}

// Function to delete a record from the dataset
void delete_record(MemoryPool* memory_pool, int key) {
    Dataset* dataset = (Dataset*)memory_pool->data + key;
    if (dataset->offset == 0) {
        return;
    } else {
        Record* current = dataset->record;
        while (current->next != NULL && current->next->key != key) {
            current = current->next;
        }
        if (current->next != NULL) {
            current->next = current->next->next;
        }
    }
}

// Function to search for a record in the dataset using a hash table
Record* search_record(HashTable* hash_table, int key) {
    Record* record = NULL;
    int bucket = key % hash_table->size;
    while (hash_table->buckets[bucket] != NULL && hash_table->buckets[bucket]->key != key) {
        bucket++;
        if (bucket == hash_table->size) {
            bucket = 0;
        }
    }
    if (hash_table->buckets[bucket] != NULL) {
        record = hash_table->buckets[bucket];
    }
    return record;
}

// Function to update the hash table with a new record
void update_hash_table(HashTable* hash_table, int key, Record* record) {
    int bucket = key % hash_table->size;
    while (hash_table->buckets[bucket] != NULL && hash_table->buckets[bucket]->key != key) {
        bucket++;
        if (bucket == hash_table->size) {
            bucket = 0;
        }
    }
    if (hash_table->buckets[bucket] == NULL) {
        hash_table->buckets[bucket] = record;
    } else {
        Record* current = hash_table->buckets[bucket];
        while (current->next != NULL && current->next->key != key) {
            current = current->next;
        }
        if (current->next == NULL) {
            current->next = record;
        }
    }
}

// Function to delete a record from the hash table
void delete_hash_table(HashTable* hash_table, int key) {
    int bucket = key % hash_table->size;
    while (hash_table->buckets[bucket] != NULL && hash_table->buckets[bucket]->key != key) {
        bucket++;
        if (bucket == hash_table->size) {
            bucket = 0;
        }
    }
    if (hash_table->buckets[bucket] != NULL) {
        Record* current = hash_table->buckets[bucket];
        while (current->next != NULL && current->next->key != key) {
            current = current->next;
        }
        if (current->next != NULL) {
            current->next = current->next->next;
        }
    }
}

// Function to insert a new record into the dataset using a thread-safe manner
void insert_record_thread_safe(MemoryPool* memory_pool, int key, Record* record) {
    pthread_mutex_lock(&memory_pool->mutex);
    insert_record(memory_pool, key, record);
    update_hash_table(memory_pool->hash_table, key, record);
