#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Log level priority array
int log_levels[5] = { 0, 1, 2, 3, 4 };

// Log entry structure
struct log_entry {
    time_t timestamp;
    int log_level;
    char* message;
    void* metadata;
};

// Thread-safe logging function
void log(int log_level, const char* message, void* metadata) {
    // Allocate memory for the log entry
    struct log_entry* entry = malloc(sizeof(struct log_entry));
    if (entry == NULL) {
        printf("Error: Failed to allocate memory for log entry\n");
        return;
    }

    // Initialize the log entry fields
    entry->timestamp = time(NULL);
    entry->log_level = log_level;
    entry->message = strdup(message);
    entry->metadata = metadata;

    // Add the log entry to the log list
    pthread_mutex_lock(&log_list_mutex);
    log_list = realloc(log_list, (num_logs + 1) * sizeof(struct log_entry));
    if (log_list == NULL) {
        printf("Error: Failed to allocate memory for log list\n");
        pthread_mutex_unlock(&log_list_mutex);
        return;
    }
    log_list[num_logs++] = entry;
    pthread_mutex_unlock(&log_list_mutex);
}

// Thread-safe log retrieval function
struct log_entry* get_log(int index) {
    if (index < 0 || index >= num_logs) {
        return NULL;
    }
    pthread_mutex_lock(&log_list_mutex);
    struct log_entry* entry = log_list[index];
    pthread_mutex_unlock(&log_list_mutex);
    return entry;
}

// Thread-safe log statistics retrieval function
int get_num_logs(void) {
