    for (int i = 0; i < this->num_logs; i++) {
        if (this->log_list[i]->log_level == log_level && this->log_list[i]->timestamp == timestamp) {
            num_logs++;
        }
    }
    pthread_mutex_unlock(&log_list_mutex);
    return num_logs;
}

