#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>

typedef struct {
    long *offsets;
    int *keys;
    record *records;
} container;

typedef struct {
    int value;
} record;

container* allocate_data_structures(int offset_size, int key_size, bool zero_initialize_offsets, bool zero_initialize_keys, bool randomize_record_values) {
    // Check for invalid input
    if (offset_size <= 0 || key_size <= 0) {
        return NULL;
    }

    // Allocate memory for the offsets array
    long *offsets = malloc(sizeof(long) * offset_size);
    if (!offsets) {
        free(offsets);
        return NULL;
    }

    // Initialize the offsets array with random values
    if (zero_initialize_offsets) {
        memset(offsets, 0, sizeof(long) * offset_size);
    } else {
        for (int i = 0; i < offset_size; i++) {
            offsets[i] = rand() % 1000000;
        }
    }

    // Allocate memory for the keys array
    int *keys = malloc(sizeof(int) * key_size);
    if (!keys) {
        free(offsets);
        return NULL;
    }

    // Initialize the keys array with random values
    if (zero_initialize_keys) {
        memset(keys, 0, sizeof(int) * key_size);
    } else {
        for (int i = 0; i < key_size; i++) {
            keys[i] = rand() % 1000000;
        }
    }

    // Allocate memory for the records array
    record *records = malloc(sizeof(record) * offset_size);
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize the records array with random values
    if (randomize_record_values) {
        for (int i = 0; i < offset_size; i++) {
            records[i].value = rand() % 1000000;
        }
    } else {
        memset(records, 0, sizeof(record) * offset_size);
    }

    // Create a container struct to hold the allocated data structures
    container *container = malloc(sizeof(container));
    if (!container) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    container->offsets = offsets;
    container->keys = keys;
    container->records = records;

    return container;
}
```
This function first checks for invalid input, such as a negative size or zero-sized arrays. If any of these conditions are met, it returns `NULL`.

Next, it allocates memory for the three arrays using `malloc()`. It then initializes the `offsets` array with random values if `zero_initialize_offsets` is set to `false`, and sets all elements to zero otherwise. Similarly, it initializes the `keys` array with random values if `zero_initialize_keys` is set to `false`, and sets all elements to zero otherwise.

The `records` array is initialized with random values if `randomize_record_values` is set to `true`, and set to all zeros otherwise.

Finally, it creates a `container` struct to hold the allocated data structures and returns a pointer to it. If any allocation fails, it frees the previously allocated memory and returns `NULL`.']

