    int* keys; // Array of unique integer values
    record* records; // Array of record structures
} container_t;

// Function to initialize and allocate memory for the container structure
container_t* init_container(int size, int disable_zero_init) {
    // Allocate memory for the offsets array
    long* offsets = (long*)malloc(size * sizeof(long));
    if (!offsets) {
        // Handle allocation failure by freeing any previously allocated memory and returning NULL
        printf("Failed to allocate memory for offsets\n");
        return NULL;
    }

    // Initialize the offsets array with zeroes if disable_zero_init is not set
    if (!disable_zero_init) {
        memset(offsets, 0, size * sizeof(long));
    }

    // Allocate memory for the keys array
    int* keys = (int*)malloc(size * sizeof(int));
    if (!keys) {
        // Handle allocation failure by freeing any previously allocated memory and returning NULL
        printf("Failed to allocate memory for keys\n");
        return NULL;
    }

    // Initialize the keys array with unique integer values within a given range
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        keys[i] = rand() % 100;
    }

    // Shuffle the keys array if a flag is set
    if (shuffle_keys) {
        shuffle(keys, size);
    }

    // Allocate memory for the records array
    record* records = (record*)malloc(size * sizeof(record));
    if (!records) {
        // Handle allocation failure by freeing any previously allocated memory and returning NULL
        printf("Failed to allocate memory for records\n");
        return NULL;
    }

    // Initialize the records array with random integer values within a specified range
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        records[i].value = rand() % 100;
    }

    // Create and return a container structure that holds all data
    container_t* container = malloc(sizeof(container_t));
    if (!container) {
        // Handle allocation failure by freeing any previously allocated memory and returning NULL
        printf("Failed to allocate memory for container\n");
        return NULL;
    }
    container->offsets = offsets;
    container->keys = keys;
    container->records = records;
    return container;
}

// Function to free the memory allocated by init_container()
void free_container(container_t* container) {
    // Free the memory allocated for the offsets array
    free(container->offsets);

    // Free the memory allocated for the keys array
    free(container->keys);

    // Free the memory allocated for the records array
    free(container->records);

    // Free the container structure itself
    free(container);
}

// Function to persist the container structure to disk
void persist_container(container_t* container, char* filename) {
    // Open a file stream for writing to disk
    FILE* fp = fopen(filename, "wb");
    if (!fp) {
        printf("Failed to open file %s for writing\n", filename);
        return;
    }

    // Write the container structure to disk in a single operation
    size_t bytes_written = fwrite(container, sizeof(container_t), 1, fp);
    if (bytes_written != 1) {
        printf("Failed to write container structure to file %s\n", filename);
        return;
    }

    // Close the file stream
    fclose(fp);
}

// Function to read the container structure from disk
container_t* read_container(char* filename) {
    // Open a file stream for reading from disk
    FILE* fp = fopen(filename, "rb");
    if (!fp) {
        printf("Failed to open file %s for reading\n", filename);
        return NULL;
    }

    // Read the container structure from disk in a single operation
    size_t bytes_read = fread(container, sizeof(container_t), 1, fp);
    if (bytes_read != 1) {
        printf("Failed to read container structure from file %s\n", filename);
        return NULL;
    }

    // Close the file stream
    fclose(fp);

    // Return the container structure that was read from disk
    return container;
}
```
This code defines a `container_t` structure to hold all data, and provides functions for initializing and freeing memory for this structure. It also includes functions for persisting the container structure to disk and reading it back in. The `init_container()` function allocates memory for the offsets array, keys array, and records array, and initializes them with zeroes or unique integer values within a given range. The `free_container()` function frees all memory allocated by `init_container()`. The `persist_container()` function writes the container structure to disk in a single operation using a file stream, and the `read_container()` function reads the container structure back from disk in a single operation using a file stream.

