// Define the function to initialize and manage the data points within a doubly linked list
void initDataPoints(DataPointList *list) {
    // Initialize the head and tail pointers of the list
    list->head = NULL;
    list->tail = NULL;
}

// Define the function to insert a new data point into the list
void insertDataPoint(DataPointList *list, DataPoint *data_point) {
    // Update the timestamp of the data point
    data_point->timestamp = time(NULL);

    // Insert the data point at the tail of the list
    if (list->tail == NULL) {
        list->head = data_point;
        list->tail = data_point;
    } else {
        list->tail->next = data_point;
        data_point->prev = list->tail;
        list->tail = data_point;
    }
}

// Define the function to delete a data point from the list
void deleteDataPoint(DataPointList *list, DataPoint *data_point) {
    // Check if the data point is the head of the list
    if (data_point == list->head) {
        list->head = data_point->next;
    }

    // Check if the data point is the tail of the list
    if (data_point == list->tail) {
        list->tail = data_point->prev;
    }

    // Remove the data point from the list
    if (data_point->next != NULL) {
        data_point->next->prev = data_point->prev;
    }

    if (data_point->prev != NULL) {
        data_point->prev->next = data_point->next;
    }
}

// Define the function to traverse the list and perform an operation on each data point
void traverseDataPoints(DataPointList *list, void (*operation)(DataPoint *)) {
    DataPoint *current = list->head;
    while (current != NULL) {
        operation(current);
        current = current->next;
    }
