    }
}

// Define the function to find a data point in the list by its unique integer identifier
DataPoint *findDataPointByIdentifier(DataPointList *list, int identifier) {
    DataPoint *current = list->head;
    while (current != NULL) {
        if (current->identifier == identifier) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

// Define the function to initialize and manage the custom key-based lookup table
void initKeyLookupTable(KeyLookupTable *table, size_t capacity) {
    // Initialize the keys and values arrays of the table
    table->keys = (int *)malloc(capacity * sizeof(int));
    table->values = (DataPoint **)malloc(capacity * sizeof(DataPoint *));
    table->capacity = capacity;
    table->count = 0;
}

// Define the function to insert a new key-value pair into the lookup table
void insertKeyValuePair(KeyLookupTable *table, int key, DataPoint *data_point) {
    // Check if the table is full
    if (table->count == table->capacity) {
        // Double the capacity of the table
        table->capacity *= 2;
        table->keys = (int *)realloc(table->keys, table->capacity * sizeof(int));
        table->values = (DataPoint **)realloc(table->values, table->capacity * sizeof(DataPoint *));
    }

    // Insert the key-value pair into the table
    table->keys[table->count] = key;
    table->values[table->count] = data_point;
    table->count++;
}

// Define the function to delete a key-value pair from the lookup table
void deleteKeyValuePair(KeyLookupTable *table, int key) {
    // Find the index of the key in the table
    size_t index = 0;
    while (index < table->count && table->keys[index] != key) {
        index++;
    }

    // Check if the key was found in the table
    if (index < table->count) {
        // Remove the key-value pair from the table
        for (size_t i = index; i < table->count - 1; i++) {
            table->keys[i] = table->keys[i + 1];
            table->values[i] = table->values[i + 1];
        }
        table->count--;
    }
}

// Define the function to find a data point in the lookup table by its unique integer identifier
DataPoint *findDataPointByKey(KeyLookupTable *table, int key) {
    // Find the index of the key in the table
    size_t index = 0;
    while (index < table->count && table->keys[index] != key) {
        index++;
    }

    // Check if the key was found in the table
    if (index < table->count) {
        return table->values[index];
    } else {
        return NULL;
    }
}

