struct time_interval {
    time_t start;
    time_t end;
};

void allocate_and_initialize_memory(size_t num_records, size_t *num_double_precision_floats, size_t *num_char_strings, size_t *num_time_intervals) {
    // Validate input parameters
    if (num_records == 0 || num_double_precision_floats == NULL || num_char_strings == NULL || num_time_intervals == NULL) {
        return;
    }

    // Allocate memory for double precision floating-point numbers
    *num_double_precision_floats = num_records * sizeof(double);
    double *doubles = malloc(*num_double_precision_floats);
    if (doubles == NULL) {
        // Handle memory allocation failure
        return;
    }

    // Initialize double precision floating-point numbers to 0.0
    memset(doubles, 0, *num_double_precision_floats);

    // Allocate memory for char strings
    *num_char_strings = num_records * sizeof(char) * MAX_STRING_LENGTH;
    char **strings = malloc(*num_char_strings);
    if (strings == NULL) {
        // Handle memory allocation failure
        free(doubles);
        return;
    }

    // Initialize char strings to empty string
    for (size_t i = 0; i < num_records; ++i) {
        strings[i] = "";
    }

    // Allocate memory for time intervals
    *num_time_intervals = num_records * sizeof(struct time_interval);
    struct time_interval *time_intervals = malloc(*num_time_intervals);
    if (time_intervals == NULL) {
        // Handle memory allocation failure
        free(doubles);
        free(strings);
        return;
    }

    // Initialize start and end timestamps to 0
    for (size_t i = 0; i < num_records; ++i) {
        time_intervals[i].start = 0;
        time_intervals[i].end = 0;
    }

    // Return pointers to allocated memory
    *num_double_precision_floats = doubles;
    *num_char_strings = strings;
    *num_time_intervals = time_intervals;
}
