            for (int i = 0; i < sizeof(buffer); i++) {
                if (buffer[i] == TEXT_COMMENT_CHARACTER) {
                    break;
                } else if (buffer[i] != '\n') {
                    line_count++;
                }
            }
        }

        // Log the file processing result
