        int key_value_pair_count = 0;
        char buffer[1024];
        while (read(fd, buffer, sizeof(buffer)) > 0) {
            for (int i = 0; i < sizeof(buffer); i++) {
                if (strncmp(buffer + i, JSON_KEY_VALUE_PAIR_SEPARATOR, strlen(JSON_KEY_VALUE_PAIR_SEPARATOR)) == 0) {
                    key_value_pair_count++;
                }
            }
        }

        // Log the file processing result
        log4j_log(filename, "Processed %d key-value pairs in JSON file", key_value_pair_count);
