        // Print usage information and exit
        printf("Usage: %s <file1> [<file2> ...]\n", argv[0]);
        return 0;
    }

    // Create a thread-safe queue for log entries
    log_queue_t* log_queue = (log_queue_t*) malloc(sizeof(log_queue_t));
    pthread_mutex_init(&log_queue->mutex, NULL);
    semaphore_init(&log_queue->semaphore, 0, LOG_BUFFER_SIZE);

    // Create a thread-safe queue for file processing contexts
    file_queue_t* file_queue = (file_queue_t*) malloc(sizeof(file_queue_t));
    pthread_mutex_init(&file_queue->mutex, NULL);
    semaphore_init(&file_queue->semaphore, 0, MAX_FILES);

    // Create a thread-safe queue for data sets
    data_set_queue_t* data_set_queue = (data_set_queue_t*) malloc(sizeof(data_set_queue_t));
    pthread_mutex_init(&data_set_queue->mutex, NULL);
    semaphore_init(&data_set_queue->semaphore, 0, MAX_DATA_SETS);

    // Create a pool of worker threads for file processing
    pthread_t* workers = (pthread_t*) malloc(sizeof(pthread_t) * NUM_THREADS);
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_create(&workers[i], NULL, process_file, file_queue);
    }

    // Create a pool of worker threads for data set processing
    pthread_t* data_set_workers = (pthread_t*) malloc(sizeof(pthread_t) * NUM_THREADS);
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_create(&data_set_workers[i], NULL, process_data_set, data_set_queue);
    }

    // Process each file in the command-line arguments
    for (int i = 1; i < argc; i++) {
        // Open the file and determine its type
        int fd = open(argv[i], O_RDONLY);
        char* filename = argv[i];
        int filetype = get_file_type(fd, filename);

        // Create a new file processing context and add it to the queue
        file_context_t* context = (file_context_t*) malloc(sizeof(file_context_t));
        context->fd = fd;
        context->filename = filename;
        context->filetype = filetype;
        context->data = NULL;
        semaphore_wait(&file_queue->semaphore);
        pthread_mutex_lock(&file_queue->mutex);
        file_queue->buffer[file_queue->size++] = context;
        pthread_mutex_unlock(&file_queue->mutex);
        semaphore_post(&file_queue->semaphore);
    }

    // Wait for all worker threads to finish processing files
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(workers[i], NULL);
    }

    // Wait for all data set workers to finish processing data sets
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(data_set_workers[i], NULL);
    }

    // Clean up the thread-safe queues and worker threads
    free(log_queue);
    free(file_queue);
    free(data_set_queue);
    free(workers);
    free(data_set_workers);

    return 0;
}

// Get the file type for a given file descriptor and filename
int get_file_type(int fd, char* filename) {
    // Check if the file is a text file
    if (strncmp(filename + strlen(filename) - strlen(TEXT_FILE_EXTENSION), TEXT_FILE_EXTENSION, strlen(TEXT_FILE_EXTENSION)) == 0) {
        return TEXT_FILE;
    } else if (strncmp(filename + strlen(filename) - strlen(CSV_FILE_EXTENSION), CSV_FILE_EXTENSION, strlen(CSV_FILE_EXTENSION)) == 0) {
        // Check if the file is a CSV file
        return CSV_FILE;
    } else if (strncmp(filename + strlen(filename) - strlen(JSON_FILE_EXTENSION), JSON_FILE_EXTENSION, strlen(JSON_FILE_EXTENSION)) == 0) {
        // Check if the file is a JSON file
        return JSON_FILE;
    } else {
        // Return an error if the file type cannot be determined
        log4j_error(filename, "Unsupported file type: %d", filetype);
        return -1;
    }
