    record_t *tail;
} linked_list_t;

// Define the structure for a hash table with chaining
typedef struct {
    int size;
    int capacity;
    linked_list_t **buckets;
} hash_table_t;

// Define the function to initialize the dataset
void init_dataset(hash_table_t *ht, int range) {
    // Initialize the hash table with a specified initial size and capacity
    ht->size = 0;
    ht->capacity = 16;
    ht->buckets = (linked_list_t **)malloc(sizeof(linked_list_t *) * ht->capacity);
    for (int i = 0; i < ht->capacity; i++) {
        ht->buckets[i] = NULL;
    }

    // Initialize each record's integer value with a random number within the specified range
    srand(time(NULL));
    for (int i = 0; i < ht->capacity; i++) {
        int key = rand() % range + 1;
        record_t *record = (record_t *)malloc(sizeof(record_t));
        record->value = key;
        record->next = NULL;
        linked_list_t *ll = (linked_list_t *)malloc(sizeof(linked_list_t));
        ll->head = record;
        ll->tail = record;
        ht->buckets[i] = ll;
    }
}

// Define the function to insert a new record into the dataset
void insert_record(hash_table_t *ht, int key) {
    // Acquire the semaphore to prevent concurrent access to the hash table
    sem_wait(&ht->sem);

    // Find the bucket for the given key and create a new linked list if necessary
    int index = key % ht->capacity;
    linked_list_t *ll = ht->buckets[index];
    if (ll == NULL) {
        ll = (linked_list_t *)malloc(sizeof(linked_list_t));
        ll->head = NULL;
        ll->tail = NULL;
        ht->buckets[index] = ll;
    }

    // Create a new record and add it to the linked list
    record_t *record = (record_t *)malloc(sizeof(record_t));
    record->value = key;
    record->next = NULL;
    if (ll->tail == NULL) {
        ll->head = record;
        ll->tail = record;
    } else {
        ll->tail->next = record;
        ll->tail = record;
    }

    // Release the semaphore and return
    sem_post(&ht->sem);
}

// Define the function to delete a record from the dataset
void delete_record(hash_table_t *ht, int key) {
    // Acquire the semaphore to prevent concurrent access to the hash table
    sem_wait(&ht->sem);

    // Find the bucket for the given key and remove the corresponding linked list if necessary
    int index = key % ht->capacity;
    linked_list_t *ll = ht->buckets[index];
    if (ll != NULL) {
        record_t *record = ll->head;
        while (record != NULL && record->value != key) {
            record = record->next;
        }
        if (record != NULL) {
            // Remove the record from the linked list and free its memory
            if (record == ll->head) {
                ll->head = record->next;
            } else {
                record_t *prev = record->prev;
                prev->next = record->next;
            }
            free(record);
        }
    }

    // Release the semaphore and return
    sem_post(&ht->sem);
}

// Define the function to search for a record in the dataset
void *search_record(hash_table_t *ht, int key) {
    // Acquire the semaphore to prevent concurrent access to the hash table
    sem_wait(&ht->sem);

    // Find the bucket for the given key and search for the corresponding record if necessary
    int index = key % ht->capacity;
    linked_list_t *ll = ht->buckets[index];
    if (ll != NULL) {
        record_t *record = ll->head;
        while (record != NULL && record->value != key) {
            record = record->next;
        }
        if (record != NULL) {
            // Return the found record and release the semaphore
            void *result = &record->value;
            sem_post(&ht->sem);
            return result;
        }
    }

    // Release the semaphore and return NULL if no record was found
    sem_post(&ht->sem);
    return NULL;
}

// Define the function to update a record in the dataset
void update_record(hash_table_t *ht, int key, int value) {
    // Acquire the semaphore to prevent concurrent access to the hash table
    sem_wait(&ht->sem);

    // Find the bucket for the given key and search for the corresponding record if necessary
    int index = key % ht->capacity;
    linked_list_t *ll = ht->buckets[index];
    if (ll != NULL) {
        record_t *record = ll->head;
        while (record != NULL && record->value != key) {
            record = record->next;
        }
        if (record != NULL) {
            // Update the record's value and release the semaphore
            record->value = value;
            sem_post(&ht->sem);
            return;
        }
    }

    // Release the semaphore and return NULL if no record was found
    sem_post(&ht->sem);
}

// Define the function to delete all records from the dataset
void clear_dataset(hash_table_t *ht) {
    // Acquire the semaphore to prevent concurrent access to the hash table
    sem_wait(&ht->sem);

    // Free all linked lists and reset the hash table
    for (int i = 0; i < ht->capacity; i++) {
        if (ht->buckets[i] != NULL) {
            free(ht->buckets[i]);
            ht->buckets[i] = NULL;
        }
    }
    ht->size = 0;

    // Release the semaphore and return
    sem_post(&ht->sem);
}
```
This implementation uses a hash table with chaining to store the records, which allows for efficient insertion, deletion, and traversal of the dataset. The hash table is protected by a semaphore to ensure thread-safe access to the data structures. The linked lists are used to store the records in each bucket, allowing for efficient insertion and deletion of records.

The `init_dataset` function initializes the hash table with a specified initial size and capacity, and sets the integer values of each record to random numbers within a specified range. The `insert_record` function inserts a new record into the dataset, creating a new linked list if necessary. The `delete_record` function deletes a record from the dataset, removing the corresponding linked list if necessary. The `search_record` function searches for a record in the dataset and returns its value if found, or NULL otherwise. The `update_record` function updates the value of a record in the dataset. The `clear_dataset` function deletes all records from the dataset.

The performance of this implementation can be optimized by using techniques such as caching, prefetching, and parallel processing to minimize cache misses and improve memory access patterns. Additionally, the hash table can be resized dynamically to maintain a balance between space efficiency and lookup speed."]

