#include <iostream>
#include <vector>
#include <map>
#include <string>
#include <fstream>
#include <mutex>
#include <thread>
#include <chrono>

using namespace std;

struct Record {
    int value;
    char status;
    long offset;
    int key;
};

class DataManager {
private:
    vector<Record> records;
    map<int, int> keys; // maps key to index in records vector
    mutex mtx;

public:
    void insert(const Record& record) {
        lock_guard<mutex> lock(mtx);
        if (keys.find(record.key) != keys.end()) {
            // update existing record instead of overwriting it
            int index = keys[record.key];
            records[index].value = record.value;
            records[index].status = record.status;
            records[index].offset = record.offset;
        } else {
            // insert new record
            records.push_back(record);
            keys[record.key] = records.size() - 1;
        }
    }

    void delete(int key) {
        lock_guard<mutex> lock(mtx);
        if (keys.find(key) != keys.end()) {
            int index = keys[key];
            records.erase(records.begin() + index);
            keys.erase(key);
        }
    }

    void lookup(int key, Record& record) {
        lock_guard<mutex> lock(mtx);
        if (keys.find(key) != keys.end()) {
            int index = keys[key];
            record = records[index];
        } else {
            // throw exception or return nullptr
        }
    }

    void exportRecords(const string& filename) {
        lock_guard<mutex> lock(mtx);
        ofstream outfile(filename, ios::binary | ios::out);
        for (auto& record : records) {
            outfile.write((char*)&record, sizeof(Record));
        }
    }

    void importRecords(const string& filename) {
        lock_guard<mutex> lock(mtx);
        ifstream infile(filename, ios::binary | ios::in);
        while (!infile.eof()) {
            Record record;
            infile.read((char*)&record, sizeof(Record));
            insert(record);
        }
    }
};
```
