function executeTests(moduleName, testCases, setupModule, teardownModule) {
  let passedCount = 0;
  let failedCount = 0;
  return new Promise((resolve, reject) => {
    for (const testCase of testCases) {
      const testLabel = testCase[0];
      const testFunction = testCase[1];
      console.log(`Running ${moduleName} - ${testLabel}`);
      setupModule().then(() => {
        return testFunction(testLabel, moduleInstance).catch((error) => {
          console.error(`Error running ${moduleName} - ${testLabel}:`, error);
          failedCount++;
        });
      }).finally(() => {
        teardownModule().then(() => {
          passedCount++;
        }).catch((error) => {
          console.error(`Error resetting ${moduleName}:`, error);
        });
      });
    }
    resolve({ passed: passedCount, failed: failedCount, allPassed: (failedCount === 0) });
  });
}
