// JavaScript code for loading and executing configuration files
function loadConfigFiles() {
  const configFiles = ["config1.json", "config2.json", "config3.json"];
  let loadedFiles = [];
  let executedFiles = [];

  // Load and execute configuration files in sequence
  for (let i = 0; i < configFiles.length; i++) {
    const filename = modifyFilename(configFiles[i]);
    try {
      const fileContent = fetch(filename).then((response) => response.json());
      loadedFiles.push(fileContent);
    } catch (error) {
      console.log(`Error loading ${filename}: ${error}`);
    }
  }

  // Execute configuration files in sequence
  for (let i = 0; i < loadedFiles.length; i++) {
    try {
      const fileContent = loadedFiles[i];
      executedFiles.push(fileContent);
    } catch (error) {
      console.log(`Error executing ${filename}: ${error}`);
    }
  }

  // Handle missing or corrupted files gracefully
  if (loadedFiles.length !== configFiles.length) {
    console.log("Missing or corrupted configuration file(s).");
  }

  return executedFiles;
}
