#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

// Define the data structures used in the function
typedef struct {
    int key;
    long offset;
} record_t;

typedef struct {
    int max_key;
    int num_records;
    record_t *records;
    long *offsets;
    int *keys;
    pthread_mutex_t lock;
    int cache_size;
    record_t *cache;
} analytics_engine_t;

// Define the hash function used for key-to-offset indexing
unsigned long hash(int key) {
    return key % 1000000007;
}

// Initialize the analytics engine with a specified maximum key limit and cache size
void init_analytics_engine(analytics_engine_t *engine, int max_key, int cache_size) {
    // Allocate memory for the offsets array
    engine->offsets = (long *)malloc(sizeof(long) * max_key);
    if (!engine->offsets) {
        perror("Failed to allocate memory for offsets");
        exit(1);
    }

    // Initialize all elements of the offsets array to zero using atomic operations
    for (int i = 0; i < max_key; i++) {
        engine->offsets[i] = 0;
    }

    // Allocate memory for the keys array and populate it with unique values between 1 and the specified maximum key limit
    engine->keys = (int *)malloc(sizeof(int) * max_key);
    if (!engine->keys) {
        perror("Failed to allocate memory for keys");
        exit(1);
    }
    srand(time(NULL));
    for (int i = 0; i < max_key; i++) {
        engine->keys[i] = rand() % max_key + 1;
    }

    // Allocate memory for the records array and populate it with random integer values within a specified range
    engine->records = (record_t *)malloc(sizeof(record_t) * max_key);
    if (!engine->records) {
        perror("Failed to allocate memory for records");
        exit(1);
    }
    for (int i = 0; i < max_key; i++) {
        engine->records[i].key = engine->keys[i];
        engine->records[i].offset = rand() % 1000000 + 1;
    }

    // Initialize the cache size and allocate memory for the cache array
    engine->cache_size = cache_size;
    engine->cache = (record_t *)malloc(sizeof(record_t) * cache_size);
    if (!engine->cache) {
        perror("Failed to allocate memory for cache");
        exit(1);
    }

    // Initialize the lock used for concurrency control
    pthread_mutex_init(&engine->lock, NULL);
}

// Lookup a record in the analytics engine using its key
record_t *lookup(analytics_engine_t *engine, int key) {
    // Use a hash function to map the key to an offset in the offsets array
    unsigned long offset = hash(key);

    // Check if the record is in the cache
    for (int i = 0; i < engine->cache_size; i++) {
        if (engine->cache[i].key == key) {
            return &engine->cache[i];
        }
    }

    // If the record is not in the cache, check if it exists in the offsets array
    if (engine->offsets[offset] != 0) {
        // If the offset is non-zero, use it to retrieve the record from the records array
        return &engine->records[engine->offsets[offset]];
    } else {
        // If the offset is zero, check if the key exists in the keys array
        for (int i = 0; i < engine->max_key; i++) {
            if (engine->keys[i] == key) {
                return &engine->records[i];
            }
        }
    }

    // If the record is not found, return NULL
    return NULL;
}

// Update a record in the analytics engine using its key and new value
void update(analytics_engine_t *engine, int key, long value) {
    // Use a hash function to map the key to an offset in the offsets array
    unsigned long offset = hash(key);

    // Check if the record is in the cache
    for (int i = 0; i < engine->cache_size; i++) {
        if (engine->cache[i].key == key) {
            engine->cache[i].offset = value;
            return;
        }
    }

    // If the record is not in the cache, check if it exists in the offsets array
    if (engine->offsets[offset] != 0) {
        // If the offset is non-zero, use it to retrieve the record from the records array and update its value
        engine->records[engine->offsets[offset]].offset = value;
        return;
    } else {
        // If the offset is zero, check if the key exists in the keys array
        for (int i = 0; i < engine->max_key; i++) {
            if (engine->keys[i] == key) {
                engine->records[i].offset = value;
                return;
            }
        }
    }
}

// Delete a record from the analytics engine using its key
void delete(analytics_engine_t *engine, int key) {
    // Use a hash function to map the key to an offset in the offsets array
    unsigned long offset = hash(key);

    // Check if the record is in the cache
    for (int i = 0; i < engine->cache_size; i++) {
        if (engine->cache[i].key == key) {
            engine->cache[i] = engine->cache[--engine->cache_size];
            return;
        }
    }

    // If the record is not in the cache, check if it exists in the offsets array
    if (engine->offsets[offset] != 0) {
        // If the offset is non-zero, use it to retrieve the record from the records array and delete it
        engine->records[engine->offsets[offset]] = engine->records[--engine->num_records];
        return;
    } else {
        // If the offset is zero, check if the key exists in the keys array
        for (int i = 0; i < engine->max_key; i++) {
            if (engine->keys[i] == key) {
                engine->records[i] = engine->records[--engine->num_records];
                return;
            }
        }
    }
}

// Free the memory allocated by the analytics engine
void free_analytics_engine(analytics_engine_t *engine) {
    // Free the offsets array, keys array, and records array
    free(engine->offsets);
    free(engine->keys);
    free(engine->records);

    // Free the cache array
    free(engine->cache);

    // Destroy the lock used for concurrency control
    pthread_mutex_destroy(&engine->lock);
}
