#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

// Define the maximum size limit for the final string
#define MAX_SIZE 1024

// Define the callback function pointer type
typedef int (*callback_func)(char, int);

// Define the external configuration file containing predefined thresholds and rules
extern const char *config_file;

// Function to process a large text file
char* process_text(const char *input, size_t max_size, callback_func func) {
    // Check for null inputs
    if (input == NULL || max_size <= 0 || func == NULL) {
        return NULL;
    }

    // Initialize the final string with a slash appended at the end
    char *final_str = malloc(max_size + 1);
    final_str[0] = '/';
    final_str[1] = '\0';

    // Read each line of the input file and process it using the callback function
    FILE *file = fopen(input, "r");
    if (file == NULL) {
        return NULL;
    }
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, file)) != -1) {
        // Check for empty lines and null inputs
        if (strlen(line) == 0 || line == NULL) {
            continue;
        }

        // Process the current line using the callback function
        char *current_str = malloc(max_size + 1);
        size_t current_len = 0;
        for (int i = 0; i < strlen(line); i++) {
            if (func(line[i], i) == 1) {
                current_str[current_len++] = line[i];
            }
        }
        current_str[current_len] = '\0';

        // Append the processed string to the final string
        if (strlen(final_str) + strlen(current_str) > max_size) {
            free(final_str);
            return NULL;
        }
        strcat(final_str, current_str);
        free(current_str);
    }
    fclose(file);

    // Return the final string with a slash appended at the end
    final_str[strlen(final_str)] = '/';
    return final_str;
}
