// Define the record structure
typedef struct {
    long offset;
    int key;
    int value;
} Record;

// Define the hash table data structure
typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} HashTable;

// Define the priority queue data structure
typedef struct {
    Record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} PriorityQueue;

// Function to initialize a hash table
void initHashTable(HashTable* ht) {
    // Allocate memory for the records array
    ht->records = (Record*)malloc(sizeof(Record) * 1024);
    if (!ht->records) {
        perror("Failed to allocate memory for hash table");
        exit(EXIT_FAILURE);
    }

    // Initialize the capacity and size of the hash table
    ht->capacity = 1024;
    ht->size = 0;

    // Initialize the mutex for concurrent access
    pthread_mutex_init(&ht->mutex, NULL);
}

// Function to insert a record into the hash table
void insertRecord(HashTable* ht, Record* rec) {
    // Acquire the lock on the hash table
    pthread_mutex_lock(&ht->mutex);

    // Check if the hash table is full
    if (ht->size == ht->capacity) {
        // Double the capacity of the hash table
        ht->capacity *= 2;

        // Reallocate memory for the records array
        Record* new_records = (Record*)realloc(ht->records, sizeof(Record) * ht->capacity);
        if (!new_records) {
            perror("Failed to reallocate memory for hash table");
            exit(EXIT_FAILURE);
        }

        // Update the records array and size of the hash table
        ht->records = new_records;
        ht->size++;
    }

    // Insert the record into the hash table
    ht->records[ht->size++] = *rec;

    // Release the lock on the hash table
    pthread_mutex_unlock(&ht->mutex);
}

// Function to delete a record from the hash table
void deleteRecord(HashTable* ht, Record* rec) {
    // Acquire the lock on the hash table
    pthread_mutex_lock(&ht->mutex);

    // Find the index of the record in the hash table
    size_t i = 0;
    while (i < ht->size && ht->records[i].key != rec->key) {
        i++;
    }

    // Check if the record was found in the hash table
    if (i == ht->size) {
        printf("Record not found in hash table\n");
        return;
    }

    // Delete the record from the hash table
    for (size_t j = i; j < ht->size - 1; j++) {
        ht->records[j] = ht->records[j + 1];
    }

    // Decrement the size of the hash table
    ht->size--;

    // Release the lock on the hash table
    pthread_mutex_unlock(&ht->mutex);
}

// Function to retrieve a record from the hash table
Record* getRecord(HashTable* ht, int key) {
    // Acquire the lock on the hash table
    pthread_mutex_lock(&ht->mutex);

    // Find the index of the record in the hash table
    size_t i = 0;
    while (i < ht->size && ht->records[i].key != key) {
        i++;
    }

    // Check if the record was found in the hash table
    if (i == ht->size) {
        printf("Record not found in hash table\n");
        return NULL;
    }

    // Return a pointer to the record
    Record* rec = &ht->records[i];

    // Release the lock on the hash table
    pthread_mutex_unlock(&ht->mutex);

    return rec;
}

