    // Initialize the pointers to the start of each data structure
    unsigned long* timestamps = (unsigned long*)mem;
    double* precision_values = (double*)(timestamps + num_timestamps);
    struct time_record* event_types = (struct time_record*)(precision_values + num_precision_values);

    // Initialize the timestamps array with current time in milliseconds
    for (int i = 0; i < num_timestamps; i++) {
        *(timestamps + i) = (unsigned long)time(NULL);
    }

    // Initialize the precision values array with random floating-point numbers between 0 and 1
