        *(event_types + i).precision = *(precision_values + rand() % num_precision_values);
        *(event_types + i).event_type = 1 + (rand() % 5);
    }
}

// Function to verify the integrity of the allocated memory and ensure the function adheres to the constraints while balancing efficiency, usability, and maintainability.
void verify_memory(int num_timestamps, int num_precision_values, int num_event_types) {
    // Calculate the total size of memory needed for all three data structures
    size_t total_size = (num_timestamps * sizeof(unsigned long)) + (num_precision_values * sizeof(double)) + (num_event_types * sizeof(struct time_record));

