const fs = require('fs');
const path = require('path');
const util = require('util');

// Load configuration files from disk
const loadConfigFiles = async () => {
  const configFiles = await fs.readdir(path.join(__dirname, 'config'));
  return Promise.all(configFiles.map((file) => {
    return fs.readFile(path.join(__dirname, 'config', file), 'utf8');
  }));
};

// Parse configuration files and extract metadata
const parseConfigFiles = (files) => {
  const configs = [];
  for (let i = 0; i < files.length; i++) {
    const file = files[i];
    const config = JSON.parse(file);
    if (!config.priority || !config.dependencies) {
      throw new Error(`Invalid configuration file: ${file}`);
    }
    configs.push({
      priority: config.priority,
      dependencies: config.dependencies,
      file: file,
    });
  }
  return configs;
};

// Load and execute configuration files in order of priority
const loadAndExecuteConfigFiles = async () => {
  const configs = await parseConfigFiles(await loadConfigFiles());
  for (let i = 0; i < configs.length; i++) {
    const config = configs[i];
    if (!config.dependencies || !config.file) {
      throw new Error(`Invalid configuration file: ${config.file}`);
    }
    // Load dependencies
    for (let j = 0; j < config.dependencies.length; j++) {
      const dependency = config.dependencies[j];
      if (!dependency || !dependency.file) {
        throw new Error(`Invalid configuration file: ${config.file}`);
      }
      await loadAndExecuteConfigFiles(dependency.file);
    }
    // Execute file
    try {
      const result = await util.promisify(require)(config.file);
      console.log(`Executed file: ${config.file}`);
    } catch (error) {
      console.error(`Error executing file: ${config.file}`, error);
    }
  }
};

// Main function to load and execute configuration files
const main = async () => {
  try {
    await loadAndExecuteConfigFiles();
  } catch (error) {
    console.error('Error loading and executing configuration files', error);
  }
};

main();
