void traverseGraph(GraphDatabase* db, int source_id, int target_id) {
    // Initialize a queue for BFS traversal
    Queue* queue = createQueue();

    // Add the source vertex to the queue
    enqueue(queue, source_id);

    // Loop until the queue is empty
    while (!isEmpty(queue)) {
        // Dequeue a vertex from the queue
        int vertex_id = dequeue(queue);

        // If the vertex has not been visited before, mark it as visited and add its neighbors to the queue
        if (vertex_id != -1) {
            Vertex* vertex = db->vertices[vertex_id];
            for (int i = 0; i < vertex->num_neighbors; i++) {
                int neighbor_id = vertex->neighbors[i];
                if (!visited[neighbor_id]) {
                    visited[neighbor_id] = true;
                    enqueue(queue, neighbor_id);
                }
            }
        }
    }
}

