Here is an example of a modular encryption module in C that integrates seamlessly into an existing multi-threaded application:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/err.h>

// Define the supported encryption algorithms
enum EncryptionAlgorithm {
    AES_128,
    AES_192,
    AES_256,
    RSA_1024,
    RSA_2048,
    RSA_3072,
};

// Define the supported key sizes and formats
enum KeySize {
    KEY_SIZE_128,
    KEY_SIZE_192,
    KEY_SIZE_256,
};

enum KeyFormat {
    KEY_FORMAT_HEX,
    KEY_FORMAT_BASE64,
};

// Define the encryption context structure
struct EncryptionContext {
    enum EncryptionAlgorithm algorithm;
    enum KeySize key_size;
    enum KeyFormat key_format;
    unsigned char *key;
    size_t key_len;
    int initialized;
};

// Initialize the encryption context with the given algorithm, key size, and format
int init_encryption(struct EncryptionContext *ctx, enum EncryptionAlgorithm algorithm, enum KeySize key_size, enum KeyFormat key_format) {
    // Check if the algorithm is supported
    if (algorithm != AES_128 && algorithm != AES_192 && algorithm != AES_256 && algorithm != RSA_1024 && algorithm != RSA_2048 && algorithm != RSA_3072) {
        return -1;
    }

    // Check if the key size is supported
    if (key_size != KEY_SIZE_128 && key_size != KEY_SIZE_192 && key_size != KEY_SIZE_256) {
        return -1;
    }

    // Check if the key format is supported
    if (key_format != KEY_FORMAT_HEX && key_format != KEY_FORMAT_BASE64) {
        return -1;
    }

    // Initialize the encryption context
    ctx->algorithm = algorithm;
    ctx->key_size = key_size;
    ctx->key_format = key_format;
    ctx->initialized = 0;

    return 0;
}

// Encrypt the given data using the specified algorithm and key
int encrypt(struct EncryptionContext *ctx, unsigned char *data, size_t data_len) {
    // Check if the encryption context is initialized
    if (!ctx->initialized) {
        return -1;
    }

    // Check if the data length is valid
    if (data_len > INT_MAX) {
        return -1;
    }

    // Allocate memory for the encrypted data
    unsigned char *encrypted_data = malloc(data_len);
    if (!encrypted_data) {
        return -1;
    }

    // Encrypt the data using the specified algorithm and key
    int ret = 0;
    switch (ctx->algorithm) {
        case AES_128:
            ret = EVP_EncryptInit(ctx, EVP_aes_128_cbc(), ctx->key, NULL);
            break;
        case AES_192:
            ret = EVP_EncryptInit(ctx, EVP_aes_192_cbc(), ctx->key, NULL);
            break;
        case AES_256:
            ret = EVP_EncryptInit(ctx, EVP_aes_256_cbc(), ctx->key, NULL);
            break;
        case RSA_1024:
            ret = EVP_EncryptInit(ctx, EVP_rsa_1024_pkcs1_oaep(), ctx->key, NULL);
            break;
        case RSA_2048:
            ret = EVP_EncryptInit(ctx, EVP_rsa_2048_pkcs1_oaep(), ctx->key, NULL);
            break;
        case RSA_3072:
            ret = EVP_EncryptInit(ctx, EVP_rsa_3072_pkcs1_oaep(), ctx->key, NULL);
            break;
    }

    // Check if the encryption operation was successful
    if (ret != 1) {
        free(encrypted_data);
        return -1;
    }

    // Encrypt the data and store the result in the encrypted data buffer
    size_t encrypted_len = 0;
    ret = EVP_EncryptUpdate(ctx, encrypted_data, &encrypted_len, data, data_len);
    if (ret != 1) {
        free(encrypted_data);
        return -1;
    }

    // Return the encrypted data
    return encrypted_len;
}

// Decrypt the given data using the specified algorithm and key
int decrypt(struct EncryptionContext *ctx, unsigned char *data, size_t data_len) {
    // Check if the encryption context is initialized
    if (!ctx->initialized) {
        return -1;
    }

    // Check if the data length is valid
    if (data_len > INT_MAX) {
        return -1;
    }

    // Allocate memory for the decrypted data
    unsigned char *decrypted_data = malloc(data_len);
    if (!decrypted_data) {
        return -1;
    }

    // Decrypt the data using the specified algorithm and key
    int ret = 0;
    switch (ctx->algorithm) {
        case AES_128:
            ret = EVP_DecryptInit(ctx, EVP_aes_128_cbc(), ctx->key, NULL);
            break;
        case AES_192:
            ret = EVP_DecryptInit(ctx, EVP_aes_192_cbc(), ctx->key, NULL);
            break;
        case AES_256:
            ret = EVP_DecryptInit(ctx, EVP_aes_256_cbc(), ctx->key, NULL);
            break;
        case RSA_1024:
            ret = EVP_DecryptInit(ctx, EVP_rsa_1024_pkcs1_oaep(), ctx->key, NULL);
            break;
        case RSA_2048:
            ret = EVP_DecryptInit(ctx, EVP_rsa_2048_pkcs1_oaep(), ctx->key, NULL);
            break;
        case RSA_3072:
            ret = EVP_DecryptInit(ctx, EVP_rsa_3072_pkcs1_oaep(), ctx->key, NULL);
            break;
    }

    // Check if the decryption operation was successful
    if (ret != 1) {
        free(decrypted_data);
        return -1;
    }

    // Decrypt the data and store the result in the decrypted data buffer
    size_t decrypted_len = 0;
    ret = EVP_DecryptUpdate(ctx, decrypted_data, &decrypted_len, data, data_len);
    if (ret != 1) {
        free(decrypted_data);
        return -1;
    }

    // Return the decrypted data
    return decrypted_len;
}

// Free the encryption context and any associated resources
void free_encryption(struct EncryptionContext *ctx) {
    if (ctx->initialized) {
        EVP_CIPHER_CTX_free(ctx);
    }
}
