        }
        int cipher = EVP_des_ede3_cbc();
        if (cipher == 0) {
            EVP_CIPHER_CTX_free(ctx);
            free(data);
            return ENCRYPTION_INITIALIZATION_FAILURE;
        }
    } else {
        // Unsupported encryption mode
        free(data);
        return -6;
    }

    // Load the resource bundle from the second file path using standard library functions
    FILE* resourceBundleFile = fopen(resourceBundleFilePath, "r");
    if (resourceBundleFile == NULL) {
        EVP_CIPHER_CTX_free(ctx);
        free(data);
        return RESOURCE_BUNDLE_LOADING_FAILURE;
    }
    int resourceBundleSize = 0;
    while (fgets(buffer, sizeof(buffer), resourceBundleFile) != NULL) {
        resourceBundleSize++;
    }
    fclose(resourceBundleFile);

    // Efficiently allocate memory for the bundle items, checking for errors and returning an appropriate error code if necessary
    int* resourceBundle = (int*)malloc(resourceBundleSize * sizeof(int));
    if (resourceBundle == NULL) {
        EVP_CIPHER_CTX_free(ctx);
        free(data);
