        }
        free(data);
    }
    if (errorCode == SUCCESS) {
        // Load the resource bundle items from the encrypted data file content
        int itemIndex = 0;
        while (itemIndex < resourceBundleSize) {
            char* itemBuffer = (char*)malloc(sizeof(char));
            if (itemBuffer == NULL) {
                errorCode = MEMORY_ALLOCATION_FAILURE;
                break;
            }
            int bytesRead = fread(itemBuffer, 1, sizeof(char), resourceBundleFile);
            if (bytesRead <= 0) {
                free(itemBuffer);
                errorCode = RESOURCE_BUNDLE_LOADING_FAILURE;
                break;
            }
            resourceBundle[itemIndex] = atoi(itemBuffer);
            itemIndex++;
        }
    }
    if (errorCode == SUCCESS) {
