#include <openssl/evp.h>
#include <openssl/err.h>

EVP_CIPHER* init_cipher(const char* mode, const char* key, int key_len) {
    EVP_CIPHER* cipher = NULL;
    int ret = 0;

    // Check if the provided mode is valid
    if (strcmp(mode, "ECB") == 0 || strcmp(mode, "EDE") == 0 || strcmp(mode, "EDE3") == 0 || strcmp(mode, "CFB") == 0) {
        // Create a new EVP_CIPHER structure based on the provided mode
        cipher = EVP_get_cipherbyname(mode);
    } else {
        // Handle invalid mode by returning NULL
        return NULL;
    }

    // Check if the key length is valid for the chosen cipher
    if (key_len != EVP_CIPHER_key_length(cipher)) {
        // Handle invalid key length by returning NULL
        return NULL;
    }

    // Initialize the cipher with the provided key
    ret = EVP_EncryptInit_ex(cipher, key, key_len);
    if (ret != 1) {
        // Handle initialization failure by returning NULL
        return NULL;
    }

    // Return a pointer to the initialized cipher structure
    return cipher;
}
```
This function takes in three parameters: `mode`, which is a string representing the desired cipher mode (e.g., "ECB", "EDE", "EDE3", or "CFB"), and `key` and `key_len`, which are the key and its length, respectively. The function first checks if the provided mode is valid by comparing it to a list of supported modes using `strcmp`. If the mode is not valid, the function returns `NULL`.

Next, the function checks if the provided key length is valid for the chosen cipher. It does this by calling `EVP_CIPHER_key_length` on the `cipher` structure and comparing it to the length of the provided key using `==`. If the key length is not valid, the function returns `NULL`.

If both checks pass, the function initializes the cipher with the provided key by calling `EVP_EncryptInit_ex` on the `cipher` structure and passing in the key as a string. If initialization fails, the function returns `NULL`.

Finally, the function returns a pointer to the initialized cipher structure.

Note that this implementation assumes that the provided mode is valid and the provided key length is valid for the chosen cipher. It also assumes that the caller has already checked the validity of the input parameters before calling this function.']

