// Define the structure for a MAC frame
typedef struct {
    // Header fields
    uint8_t dst_mac[6];
    uint8_t src_mac[6];
    uint16_t ethertype;

    // Payload fields
    uint8_t* payload;
    size_t payload_len;

    // Timestamp field
    struct timespec timestamp;
} MAC_FRAME_T;

// Define the configuration structure for the network interface
typedef struct {
    // Number of worker threads to use
    int num_threads;

    // Maximum number of concurrent instances of MAC_FRAME_T
    int max_instances;

    // Memory pool size (in bytes)
    size_t mempool_size;

    // Frame validation library handle
    void* frame_validation_lib;
} NETWORK_INTERFACE_CONFIG;

// Define the function to initialize the network interface configuration
int init_network_interface(NETWORK_INTERFACE_CONFIG* config) {
    // Check if the input parameters are valid
    if (config == NULL || config->num_threads < 1 || config->max_instances < 1 || config->mempool_size < sizeof(MAC_FRAME_T)) {
        return -1;
    }

    // Initialize the memory pool
    void* mempool = malloc(config->mempool_size);
    if (mempool == NULL) {
        fprintf(stderr, "Failed to allocate memory for the memory pool\n");
        return -2;
    }

    // Initialize the frame validation library handle
    config->frame_validation_lib = init_frame_validation_library();
    if (config->frame_validation_lib == NULL) {
        fprintf(stderr, "Failed to initialize the frame validation library\n");
        free(mempool);
        return -3;
    }

    // Initialize the worker threads
    pthread_t* worker_threads = malloc(config->num_threads * sizeof(pthread_t));
    if (worker_threads == NULL) {
        fprintf(stderr, "Failed to allocate memory for the worker threads\n");
        free(mempool);
        return -4;
    }

    // Initialize the semaphore for synchronizing access to the memory pool
    sem_t* mempool_sem = malloc(sizeof(sem_t));
    if (mempool_sem == NULL) {
        fprintf(stderr, "Failed to allocate memory for the semaphore\n");
        free(worker_threads);
        free(mempool);
        return -5;
    }

    // Initialize the mutex for synchronizing access to the frame validation library handle
    pthread_mutex_t* frame_validation_lib_mutex = malloc(sizeof(pthread_mutex_t));
    if (frame_validation_lib_mutex == NULL) {
        fprintf(stderr, "Failed to allocate memory for the mutex\n");
        free(mempool_sem);
        free(worker_threads);
        free(mempool);
        return -6;
    }

    // Initialize the condition variable for signaling thread termination
    pthread_cond_t* thread_termination_cv = malloc(sizeof(pthread_cond_t));
    if (thread_termination_cv == NULL) {
        fprintf(stderr, "Failed to allocate memory for the condition variable\n");
        free(frame_validation_lib_mutex);
        free(mempool_sem);
        free(worker_threads);
        free(mempool);
        return -7;
    }

    // Initialize the worker thread arguments
    WORKER_THREAD_ARGS* args = malloc(config->num_threads * sizeof(WORKER_THREAD_ARGS));
    if (args == NULL) {
        fprintf(stderr, "Failed to allocate memory for the worker thread arguments\n");
        free(thread_termination_cv);
        free(frame_validation_lib_mutex);
        free(mempool_sem);
        free(worker_threads);
        free(mempool);
        return -8;
    }

    // Initialize the worker thread arguments
    for (int i = 0; i < config->num_threads; i++) {
        args[i].config = config;
        args[i].mempool = mempool;
        args[i].mempool_sem = mempool_sem;
        args[i].frame_validation_lib_mutex = frame_validation_lib_mutex;
        args[i].thread_termination_cv = thread_termination_cv;
    }

    // Create the worker threads
    for (int i = 0; i < config->num_threads; i++) {
        if (pthread_create(&worker_threads[i], NULL, worker_thread, &args[i]) != 0) {
            fprintf(stderr, "Failed to create the worker thread\n");
            free(thread_termination_cv);
            free(frame_validation_lib_mutex);
            free(mempool_sem);
            free(worker_threads);
            free(mempool);
            return -9;
        }
    }

    // Wait for the worker threads to terminate
    for (int i = 0; i < config->num_threads; i++) {
        if (pthread_join(worker_threads[i], NULL) != 0) {
            fprintf(stderr, "Failed to join the worker thread\n");
            free(thread_termination_cv);
            free(frame_validation_lib_mutex);
            free(mempool_sem);
            free(worker_threads);
            free(mempool);
            return -10;
        }
    }

    // Clean up the resources
    free(thread_termination_cv);
    free(frame_validation_lib_mutex);
    free(mempool_sem);
    free(worker_threads);
    free(mempool);
    return 0;
}

// Define the worker thread function
void* worker_thread(void* args) {
    // Cast the input arguments to the correct type
    WORKER_THREAD_ARGS* thread_args = (WORKER_THREAD_ARGS*)args;

    // Initialize the memory pool semaphore
