#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

// Define the different record types
typedef struct {
    int integer;
} IntegerRecord;

typedef struct {
    float float_value;
    char string[10];
} StructRecord;

typedef struct {
    time_t timestamp;
} TimestampRecord;

// Define the linked list node structure
typedef struct Node {
    void* record; // Pointer to the record data
    struct Node* next; // Pointer to the next node in the list
} Node;

// Define the memory pool structure
typedef struct MemoryPool {
    size_t size; // Size of the memory pool
    char* buffer; // Buffer for the memory pool
    Node* head; // Head node of the linked list
} MemoryPool;

// Function to allocate a new record in the memory pool
void* allocateRecord(MemoryPool* pool, void* record) {
    // Check if there is enough space in the buffer
    if (pool->size - pool->buffer < sizeof(record)) {
        // If not, double the size of the buffer
        pool->size *= 2;
        pool->buffer = realloc(pool->buffer, pool->size);
    }

    // Allocate memory for the record in the buffer
    void* new_record = pool->buffer + (pool->head - pool->buffer);
    memcpy(new_record, record, sizeof(record));

    // Update the head node to point to the new record
    pool->head = new_record;

    return new_record;
}

// Function to deallocate a record in the memory pool
void deallocateRecord(MemoryPool* pool, void* record) {
    // Find the node containing the record
    Node* node = pool->head;
    while (node != NULL && node->record != record) {
        node = node->next;
    }

    // If the node is found, remove it from the list and free its memory
    if (node != NULL) {
        Node* prev_node = node->prev;
        Node* next_node = node->next;
        if (prev_node != NULL) {
            prev_node->next = next_node;
        } else {
            pool->head = next_node;
        }
        free(node);
    }
}

// Function to add a new record to the linked list
void addRecord(MemoryPool* pool, void* record) {
    // Allocate memory for the record in the memory pool
    void* new_record = allocateRecord(pool, record);

    // Create a new node for the record and add it to the linked list
    Node* new_node = malloc(sizeof(Node));
    new_node->record = new_record;
    new_node->next = pool->head;
    if (pool->head != NULL) {
        pool->head->prev = new_node;
    }
    pool->head = new_node;
}

// Function to update an existing record in the linked list
void updateRecord(MemoryPool* pool, void* record) {
    // Find the node containing the record
    Node* node = pool->head;
    while (node != NULL && node->record != record) {
        node = node->next;
    }

    // If the node is found, update its memory with the new record data
    if (node != NULL) {
        memcpy(node->record, record, sizeof(record));
    }
}

// Function to retrieve a record from the linked list by key
void* getRecord(MemoryPool* pool, int key) {
    // Find the node containing the record with the given key
    Node* node = pool->head;
    while (node != NULL && ((IntegerRecord*)node->record)->integer != key) {
        node = node->next;
