void removeRecord(MemoryPool* pool, int key) {
    // Find the node containing the record with the given key
    Node* node = pool->head;
    while (node != NULL && ((IntegerRecord*)node->record)->integer != key) {
        node = node->next;
    }

    // If the node is found, remove it from the linked list and free its memory
    if (node != NULL) {
        Node* prev_node = node->prev;
        Node* next_node = node->next;
        if (prev_node != NULL) {
            prev_node->next = next_node;
        } else {
            pool->head = next_node;
        }
        free(node);
    }
}

// Function to perform periodic garbage collection on the memory pool
void garbageCollect(MemoryPool* pool) {
    // Iterate through the linked list and remove unused records
    Node* node = pool->head;
    while (node != NULL) {
        if (node->record == NULL) {
            Node* next_node = node->next;
            free(node);
            node = next_node;
        } else {
            node = node->next;
        }
    }
}

