            deallocateRecord(pool, node->record);
            node = next_node;
        } else {
            node = node->next;
        }
    }
}

// Function to perform periodic data compression on the memory pool
void dataCompression(MemoryPool* pool) {
    // Iterate through the linked list and compress records using a dictionary-based approach
    Node* node = pool->head;
    while (node != NULL) {
        if (node->record == NULL) {
            Node* next_node = node->next;
            deallocateRecord(pool, node->record);
            node = next_node;
        } else {
