// Function to initialize the linked list with a specified initial capacity
result_t init_linked_list(int initial_capacity) {
    if (initial_capacity <= 0) {
        return (result_t){NULL, 0, 0, -1}; // Invalid input
    }

    node_t* head = NULL;
    int capacity = initial_capacity;
    file_record_t** records = malloc(sizeof(file_record_t*) * capacity);
    if (records == NULL) {
        return (result_t){NULL, 0, 0, -1}; // Memory allocation failed
    }

    for (int i = 0; i < capacity; i++) {
