void add_file_record(node_t* head, char* path, int line_count, int value) {
    node_t* current = head;
    while (current->next != NULL) {
        current = current->next;
    }

    file_record_t* new_record = malloc(sizeof(file_record_t));
    if (new_record == NULL) {
        return; // Memory allocation failed
    }

    new_record->path = path;
    new_record->line_count = line_count;
    new_record->value = value;
    current->next = malloc(sizeof(node_t));
    if (current->next == NULL) {
        return; // Memory allocation failed
    }

    current->next->record = new_record;
    current->next->next = NULL;
}

// Function to resize the linked list when necessary
void resize_linked_list(node_t* head, int new_capacity) {
    if (new_capacity <= 0) {
        return; // Invalid input
    }

    file_record_t** new_records = malloc(sizeof(file_record_t*) * new_capacity);
    if (new_records == NULL) {
        return; // Memory allocation failed
    }

    node_t* current = head;
    int i = 0;
    while (current != NULL) {
        new_records[i] = malloc(sizeof(file_record_t));
        if (new_records[i] == NULL) {
            return; // Memory allocation failed
        }

        memcpy(new_records[i], current->record, sizeof(file_record_t));
        i++;
        current = current->next;
    }

    free(head);
    head = malloc(sizeof(node_t));
    if (head == NULL) {
        return; // Memory allocation failed
    }

    head->record = new_records[0];
    head->next = NULL;
}

