// Function to handle concurrent access by multiple nodes and threads within a cluster without data races or deadlocks
void synchronize_access(node_t* head) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    node_t* current = head;
    while (current != NULL) {
        pthread_mutex_lock(&mutex);
        if (current->record == NULL) {
            pthread_cond_wait(&cond, &mutex);
        } else {
            // Process the record
            current->record = NULL;
            pthread_cond_signal(&cond);
        }
        pthread_mutex_unlock(&mutex);
    }
}

