    while (record != NULL) {
        switch (record->type) {
            case INTEGER:
                free(record->value);
                break;
            case STRUCT_WITH_INTEGER_FLOAT_AND_STRING:
                free(((struct StructWithIntegerFloatAndStringRecord*)record->value)->string);
                free(record->value);
                break;
            case TIMESTAMP:
                free(record->value);
                break;
        }
        record = record->next;
    }
}
