        return;
    }

    // Initialize the double precision floating point array with random values within a specified range
    srand(time(NULL));
    for (int i = 0; i < num_points; i++) {
        dp_arr[i] = rand() % 100;
    }

    // Allocate memory for the struct point array
    struct point* points_arr = (struct point*)malloc(num_points * sizeof(struct point));
    if (!points_arr) {
        printf("Error: Failed to allocate memory for struct point array\n");
        return;
    }

    // Initialize the struct point array with random coordinates within a specified range
    srand(time(NULL));
    for (int i = 0; i < num_points; i++) {
        points_arr[i].x = rand() % 100;
        points_arr[i].y = rand() % 100;
    }

