    if (!sessions_arr) {
        printf("Error: Failed to allocate memory for session array\n");
        return;
    }

    // Initialize the session array with random timestamps and struct point arrays
    srand(time(NULL));
    for (int i = 0; i < num_sessions; i++) {
        sessions_arr[i].timestamp = rand() % 100;
        sessions_arr[i].points = points_arr;
        sessions_arr[i].num_points = num_points;
    }

    // Create a linked list of sessions for efficient insertion, deletion, and traversal operations
    session_node_t* head = NULL;
    session_node_t* current = NULL;
    for (int i = 0; i < num_sessions; i++) {
        // Create a new node for the linked list
        session_node_t* new_node = (session_node_t*)malloc(sizeof(session_node_t));
        if (!new_node) {
            printf("Error: Failed to allocate memory for new node\n");
            return;
        }

        // Set the session and next pointers in the new node
        new_node->session = &sessions_arr[i];
        new_node->next = NULL;

        // If the linked list is empty, set the head pointer to the new node
        if (!head) {
            head = new_node;
        } else {
            current->next = new_node;
        }

        // Set the current pointer to the new node
        current = new_node;
    }

    // Periodically check and release unused memory blocks to optimize resource usage
    while (true) {
        // Check if any sessions have been deleted
        session_node_t* temp = head;
        while (temp != NULL) {
            if (!temp->session->points) {
                free(temp);
                break;
            }
            temp = temp->next;
        }

        // If no sessions have been deleted, exit the loop
        if (temp == NULL) {
            break;
        }
    }
}

// Function to manage memory usage efficiently for real-time data streams
void manage_memory(int num_points, int num_sessions) {
    // Periodically check and release unused memory blocks to optimize resource usage
    while (true) {
        // Check if any sessions have been deleted
        session_node_t* temp = head;
