// Function to dynamically allocate memory for an array of records, initialize values to random integers within a specified range, and manage memory for two separate arrays: one for long offset values and another for int keys. Each record structure should also include a pointer to its corresponding key and offset.
Record **allocate_records(int num_records, int min_value, int max_value) {
    // Allocate memory for the array of pointers to records
    Record **records = (Record **)malloc(num_records * sizeof(Record *));
    if (!records) {
        printf("Error: Failed to allocate memory for records\n");
        return NULL;
    }

    // Allocate memory for the array of long offset values and int keys
    long *offsets = (long *)malloc(num_records * sizeof(long));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offsets\n");
        free(records);
        return NULL;
    }
    int *keys = (int *)malloc(num_records * sizeof(int));
    if (!keys) {
        printf("Error: Failed to allocate memory for keys\n");
        free(offsets);
        free(records);
        return NULL;
    }

    // Initialize the values of each record to random integers within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        records[i] = (Record *)malloc(sizeof(Record));
        if (!records[i]) {
            printf("Error: Failed to allocate memory for record %d\n", i);
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }
        records[i]->value = rand() % (max_value - min_value + 1) + min_value;
        offsets[i] = i * sizeof(Record);
        keys[i] = i;
    }

    // Set the pointers to key and offset arrays for each record
    for (int i = 0; i < num_records; ++i) {
        records[i]->key = &keys[i];
        records[i]->offset = &offsets[i];
    }

    // Return a pointer to the array of pointers to records
    return records;
}

// Function to free memory for an array of records and its corresponding arrays: one for long offset values and another for int keys.
void free_records(Record **records, int num_records) {
    // Free the memory for each record
    for (int i = 0; i < num_records; ++i) {
        free(records[i]);
    }

    // Free the memory for the array of pointers to records
    free(records);
}
