pthread_mutex_t record_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate memory for a new record
Record* alloc_record() {
    Record* record = malloc(sizeof(Record));
    if (record == NULL) {
        printf("Error: Failed to allocate memory for record\n");
        return NULL;
    }
    // Initialize the value of the record to a random number within the specified range
    record->value = rand() % VALUE_RANGE + 1;
    return record;
}

// Function to deallocate memory for a record
void free_record(Record* record) {
    if (record != NULL) {
        free(record);
    }
}

// Function to update the value of a record
void update_record(Record* record, int new_value) {
    pthread_mutex_lock(&record_lock);
    record->value = new_value;
    pthread_mutex_unlock(&record_lock);
}

// Function to add a new record to the array
void add_record(Record* record) {
    // Check if the number of records exceeds the maximum threshold
    if (num_records >= MAX_RECORDS) {
        printf("Error: Maximum number of records exceeded\n");
        return;
    }
    pthread_mutex_lock(&record_lock);
    // Add the new record to the array
    records[num_records++] = record;
    pthread_mutex_unlock(&record_lock);
}

// Function to remove a record from the array
void remove_record(Record* record) {
    pthread_mutex_lock(&record_lock);
    // Find the index of the record in the array
    int i;
    for (i = 0; i < num_records; i++) {
        if (records[i] == record) {
            break;
        }
    }
    // If the record is found, remove it from the array
    if (i < num_records) {
        records[i] = records[--num_records];
    }
    pthread_mutex_unlock(&record_lock);
}

// Function to retrieve a record from the array by its index
Record* get_record(int index) {
    if (index < 0 || index >= num_records) {
        printf("Error: Invalid record index\n");
        return NULL;
    }
    pthread_mutex_lock(&record_lock);
    Record* record = records[index];
    pthread_mutex_unlock(&record_lock);
    return record;
}

// Function to retrieve the number of records in the array
int get_num_records() {
    int num_records;
    pthread_mutex_lock(&record_lock);
    num_records = this->num_records;
    pthread_mutex_unlock(&record_lock);
    return num_records;
}
