Here is an example of how you could implement the C function to dynamically allocate memory for two arrays: one for `long` offset values and another for `int` keys, as well as an array of `record` structures, where each structure contains a single `int` value. The function should also allocate memory for an array of pointers to `record` structures, which can be used to access individual records. Additionally, the function should handle error handling gracefully and ensure that all allocated memory is freed upon function exit.
```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

// Define a structure to represent a record
typedef struct {
    int value;
} record;

// Function to dynamically allocate memory for two arrays: one for long offset values and another for int keys, as well as an array of record structures, where each structure contains a single int value. The function should also allocate memory for an array of pointers to record structures, which can be used to access individual records. Additionally, the function should handle error handling gracefully and ensure that all allocated memory is freed upon function exit.
void *allocate_memory(int num_records) {
    // Allocate memory for two arrays: one for long offset values and another for int keys
    long *offset_values = (long *)malloc(num_records * sizeof(long));
    if (!offset_values) {
        printf("Error: Failed to allocate memory for offset values\n");
        return NULL;
    }
    int *key_values = (int *)malloc(num_records * sizeof(int));
    if (!key_values) {
        printf("Error: Failed to allocate memory for key values\n");
        free(offset_values);
        return NULL;
    }

    // Allocate memory for an array of pointers to record structures, where each structure contains a single int value.
    record **records = (record **)malloc(num_records * sizeof(record *));
    if (!records) {
        printf("Error: Failed to allocate memory for records\n");
        free(offset_values);
        free(key_values);
        return NULL;
    }

    // Initialize the record structures with random integer values within a specified range.
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i] = malloc(sizeof(record));
        if (!records[i]) {
            printf("Error: Failed to allocate memory for record %d\n", i);
            free(offset_values);
            free(key_values);
            free(records);
            return NULL;
        }
        records[i]->value = rand() % 100;
    }

    // Return a pointer to an array of pointers to record structures, which can be used to access individual records.
    return records;
}
