```csharp
using System;
using System.Data;
using System.Data.SqlClient;
using System.Collections.Generic;

public static IDataReader ExecuteParameterizedQuery(List<object> values, SqlConnection connection, string commandText) {
    try {
        // Create a new SQL command with the specified text and parameters.
        SqlCommand command = new SqlCommand(commandText, connection);
        foreach (var value in values) {
            command.Parameters.AddWithValue("@value", value);
        }

        // Execute the SQL command and return an IDataReader for the result set.
        return command.ExecuteReader();
    } catch (Exception ex) {
        Console.WriteLine("Error: " + ex.Message);
        return null;
    }
}
