// Define the record structure
typedef struct {
    int key;
    long offset;
} Record;

// Define the function to dynamically allocate memory for an array of records
Record** allocate_records(int num_records, int min_value, int max_value) {
    // Allocate memory for the array of pointers to records
    Record** records = (Record**)malloc(num_records * sizeof(Record*));
    if (!records) {
        printf("Error: Failed to allocate memory for records\n");
        return NULL;
    }

    // Initialize each record with a random integer value within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        int key = rand() % (max_value - min_value + 1) + min_value;
        long offset = rand() % (max_value - min_value + 1) + min_value;
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            printf("Error: Failed to allocate memory for record %d\n", i);
            return NULL;
        }
        records[i]->key = key;
        records[i]->offset = offset;
    }

    // Allocate memory for the arrays of long and int keys
    long* long_keys = (long*)malloc(num_records * sizeof(long));
    if (!long_keys) {
        printf("Error: Failed to allocate memory for long keys\n");
        return NULL;
    }
    int* int_keys = (int*)malloc(num_records * sizeof(int));
    if (!int_keys) {
        printf("Error: Failed to allocate memory for int keys\n");
        return NULL;
    }

    // Initialize the arrays of long and int keys with the corresponding values from the records
    for (int i = 0; i < num_records; i++) {
        long_keys[i] = records[i]->offset;
        int_keys[i] = records[i]->key;
    }

    // Free the memory allocated for the records
    free(records);

    return (Record**)malloc(num_records * sizeof(Record*));
}

