#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <assert.h>

// Custom hash table implementation for quick key-based lookups
struct HashTable {
    int size;
    struct Node **nodes;
};

struct Node {
    int key;
    void *value;
    struct Node *next;
};

void hash_table_init(struct HashTable *ht, int size) {
    ht->size = size;
    ht->nodes = malloc(sizeof(struct Node *) * size);
    memset(ht->nodes, 0, sizeof(struct Node *) * size);
}

void hash_table_destroy(struct HashTable *ht) {
    for (int i = 0; i < ht->size; i++) {
        struct Node *node = ht->nodes[i];
        while (node != NULL) {
            struct Node *next = node->next;
            free(node);
            node = next;
        }
    }
    free(ht->nodes);
}

void hash_table_insert(struct HashTable *ht, int key, void *value) {
    int index = key % ht->size;
    struct Node **head = &ht->nodes[index];
    while (*head != NULL && (*head)->key < key) {
        head = &(*head)->next;
    }
    if (*head == NULL || (*head)->key > key) {
        *head = malloc(sizeof(struct Node));
        (*head)->key = key;
        (*head)->value = value;
        (*head)->next = NULL;
    }
}

void *hash_table_get(struct HashTable *ht, int key) {
    int index = key % ht->size;
    struct Node *node = ht->nodes[index];
    while (node != NULL && node->key < key) {
        node = node->next;
    }
    if (node == NULL || node->key > key) {
        return NULL;
    }
    return node->value;
}

// Function to generate a random string of specified length using a given character set
char *generate_random_string(int length, const char *character_set) {
    char *str = malloc(length + 1);
