// Define the semaphore structure
typedef struct {
    int value;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} semaphore_t;

// Define the function prototypes
void init_semaphore(semaphore_t *sem, int initial_value);
int acquire_semaphore(semaphore_t *sem);
int release_semaphore(semaphore_t *sem);
int delete_semaphore(semaphore_t *sem);
void* handle_request(void *args);

// Define the global semaphore variable
semaphore_t sem;

// Initialize the semaphore with an initial value of 0
void init_semaphore(semaphore_t *sem, int initial_value) {
    sem->value = initial_value;
    pthread_mutex_init(&sem->mutex, NULL);
    pthread_cond_init(&sem->cond, NULL);
}

// Acquire the semaphore, decrementing its value by 1
int acquire_semaphore(semaphore_t *sem) {
    int ret = 0;
    pthread_mutex_lock(&sem->mutex);
    while (sem->value <= 0) {
        pthread_cond_wait(&sem->cond, &sem->mutex);
    }
    sem->value--;
    pthread_mutex_unlock(&sem->mutex);
    return ret;
}

// Release the semaphore, incrementing its value by 1
int release_semaphore(semaphore_t *sem) {
    int ret = 0;
    pthread_mutex_lock(&sem->mutex);
    sem->value++;
    pthread_cond_signal(&sem->cond);
    pthread_mutex_unlock(&sem->mutex);
    return ret;
}

// Delete the semaphore, freeing its resources
int delete_semaphore(semaphore_t *sem) {
    int ret = 0;
    pthread_mutex_destroy(&sem->mutex);
    pthread_cond_destroy(&sem->cond);
    return ret;
}

// Handle a request, acquiring and releasing the semaphore as needed
void* handle_request(void *args) {
    // Acquire the semaphore
    acquire_semaphore(&sem);

    // Perform the requested operation
    // ...

    // Release the semaphore
    release_semaphore(&sem);
}

// Main function for testing the semaphore
int main() {
    init_semaphore(&sem, 0);

    // Create and start threads to handle requests
    pthread_t threads[20];
    for (int i = 0; i < 20; i++) {
        pthread_create(&threads[i], NULL, handle_request, NULL);
    }

    // Wait for all threads to finish
    for (int i = 0; i < 20; i++) {
        pthread_join(threads[i], NULL);
    }

    // Delete the semaphore
    delete_semaphore(&sem);

    return 0;
}
