// Define the structures used to represent the data
typedef struct {
    long offset;
    short status;
} Offset;

typedef struct {
    int key;
    char status;
} Key;

typedef struct {
    long timestamp;
    int key;
    double value;
} Record;

typedef struct {
    Record* record;
    bool valid;
} NestedRecord;

// Define the memory pool for the records
#define RECORD_POOL_SIZE 1024
Offset recordPool[RECORD_POOL_SIZE];
int recordPoolIndex = 0;

// Define the mapping between keys and offsets
typedef struct {
    int key;
    long offset;
} KeyMapping;
KeyMapping* keyMappings = NULL;
size_t numKeyMappings = 0;

// Function to allocate a new record
Record* allocRecord(int key, double value) {
    // Check if there are any unused records in the pool
    if (recordPoolIndex < RECORD_POOL_SIZE) {
        Record* record = &recordPool[recordPoolIndex++];
        record->timestamp = time(NULL);
        record->key = key;
        record->value = value;
        return record;
    } else {
        // If the pool is full, allocate a new record dynamically
        Record* record = malloc(sizeof(Record));
        if (record == NULL) {
            printf("Error: Failed to allocate memory for record\n");
            return NULL;
        }
        record->timestamp = time(NULL);
        record->key = key;
        record->value = value;
        return record;
    }
}

// Function to deallocate a record
void freeRecord(Record* record) {
    // Check if the record is in the pool
    if (record >= &recordPool[0] && record < &recordPool[RECORD_POOL_SIZE]) {
        // If it's in the pool, mark it as unused
        record->status = 0;
    } else {
        // If it's not in the pool, free it dynamically
        free(record);
    }
}

// Function to allocate a new nested record
NestedRecord* allocNestedRecord(Record* record) {
    NestedRecord* nestedRecord = malloc(sizeof(NestedRecord));
    if (nestedRecord == NULL) {
        printf("Error: Failed to allocate memory for nested record\n");
        return NULL;
    }
    nestedRecord->record = record;
    nestedRecord->valid = true;
    return nestedRecord;
}

// Function to deallocate a nested record
void freeNestedRecord(NestedRecord* nestedRecord) {
    free(nestedRecord);
}

// Function to add a new key mapping
int addKeyMapping(int key, long offset) {
    // Check if there is enough space for the new mapping
    if (numKeyMappings >= RECORD_POOL_SIZE) {
        printf("Error: No more space for key mappings\n");
        return -1;
    }
    KeyMapping* mapping = &keyMappings[numKeyMappings++];
    mapping->key = key;
    mapping->offset = offset;
    return 0;
}

// Function to retrieve a record by key
Record* getRecordByKey(int key) {
    // Check if the key is in the mapping
    for (size_t i = 0; i < numKeyMappings; i++) {
        KeyMapping* mapping = &keyMappings[i];
        if (mapping->key == key) {
            return &recordPool[mapping->offset];
        }
    }
    // If the key is not in the mapping, allocate a new record and add it to the mapping
    Record* record = allocRecord(key, 0.0);
    if (record == NULL) {
        printf("Error: Failed to allocate memory for record\n");
        return NULL;
    }
    long offset = recordPoolIndex - 1;
    addKeyMapping(key, offset);
    return record;
}

// Function to update a record by key
int updateRecordByKey(int key, double value) {
    // Check if the key is in the mapping
    for (size_t i = 0; i < numKeyMappings; i++) {
        KeyMapping* mapping = &keyMappings[i];
        if (mapping->key == key) {
            Record* record = &recordPool[mapping->offset];
            record->value = value;
            return 0;
        }
    }
    // If the key is not in the mapping, allocate a new record and add it to the mapping
    Record* record = allocRecord(key, value);
    if (record == NULL) {
        printf("Error: Failed to allocate memory for record\n");
        return -1;
    }
    long offset = recordPoolIndex - 1;
    addKeyMapping(key, offset);
    return 0;
}

// Function to delete a record by key
int deleteRecordByKey(int key) {
    // Check if the key is in the mapping
    for (size_t i = 0; i < numKeyMappings; i++) {
        KeyMapping* mapping = &keyMappings[i];
        if (mapping->key == key) {
            Record* record = &recordPool[mapping->offset];
            freeRecord(record);
            // Remove the mapping from the list
            numKeyMappings--;
            for (size_t j = i; j < numKeyMappings; j++) {
                KeyMapping* mapping2 = &keyMappings[j];
                if (mapping2->offset > mapping->offset) {
                    mapping2->offset--;
                }
            }
            return 0;
        }
    }
    // If the key is not in the mapping, do nothing
    return -1;
}

// Function to retrieve a nested record by key
NestedRecord* getNestedRecordByKey(int key) {
    Record* record = getRecordByKey(key);
    if (record == NULL) {
        printf("Error: Failed to retrieve record for key %d\n", key);
        return NULL;
    }
    NestedRecord* nestedRecord = allocNestedRecord(record);
    if (nestedRecord == NULL) {
        printf("Error: Failed to allocate memory for nested record\n");
        return NULL;
    }
    return nestedRecord;
}

// Function to update a nested record by key
int updateNestedRecordByKey(int key, double value) {
    Record* record = getRecordByKey(key);
    if (record == NULL) {
        printf("Error: Failed to retrieve record for key %d\n", key);
        return -1;
    }
    record->value = value;
    return 0;
}

