    for (size_t i = 0; i < numKeyMappings; i++) {
        KeyMapping* mapping = &keyMappings[i];
        if (mapping->offset > record->offset) {
            mapping->offset--;
        }
    }
    return 0;
}

// Function to retrieve a nested record by offset
