#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>
#include <assert.h>

// Define the structure for sensor events
typedef struct {
    double temperature;
    char *sensor_id;
    int timestamp;
    float reliability;
} sensor_event;

// Define a linked list node to store sensor events
typedef struct node {
    sensor_event event;
    struct node *next;
} node;

// Define the collection of sensor events
typedef struct {
    node *head;
    node *tail;
    int size;
} sensor_events;

// Function to insert a new sensor event into the collection
void insert_event(sensor_events *events, const char *sensor_id, double temperature, int timestamp, float reliability) {
    // Create a new node for the event
    node *new_node = malloc(sizeof(node));
    assert(new_node != NULL);

    // Initialize the node with the given data
    new_node->event.sensor_id = sensor_id;
    new_node->event.temperature = temperature;
    new_node->event.timestamp = timestamp;
    new_node->event.reliability = reliability;

    // Add the node to the end of the linked list
    if (events->tail == NULL) {
        events->head = new_node;
        events->tail = new_node;
    } else {
        events->tail->next = new_node;
        events->tail = new_node;
    }

    // Increment the size of the collection
    events->size++;
}

// Function to delete a sensor event from the collection
void delete_event(sensor_events *events, const char *sensor_id) {
    // Find the node with the given sensor ID
    node *current = events->head;
    while (current != NULL && strcmp(current->event.sensor_id, sensor_id) != 0) {
        current = current->next;
    }

    // If the node was found, remove it from the linked list
    if (current != NULL) {
        // Update the head and tail pointers if necessary
        if (events->head == current) {
            events->head = current->next;
        }
        if (events->tail == current) {
            events->tail = current->prev;
        }

        // Free the node
        free(current);

        // Decrement the size of the collection
        events->size--;
