#define MAX_OFFSETS 1000000
#define MAX_MEMORY 50000000
#define MIN_VAL 0
#define MAX_VAL 100

typedef struct {
    int key;
    int value;
} record;

void init_data(int num_keys, long *offsets, int *keys, record **records) {
    // Validate input parameters
    if (num_keys < 0 || num_keys > MAX_OFFSETS) {
        fprintf(stderr, "Invalid number of keys: %d\n", num_keys);
        return;
    }

    // Allocate memory for offsets and keys
    long *offsets = malloc(num_keys * sizeof(long));
    int *keys = malloc(num_keys * sizeof(int));
    if (offsets == NULL || keys == NULL) {
        fprintf(stderr, "Failed to allocate memory for offsets and keys\n");
        return;
    }

    // Initialize offsets and keys
    for (int i = 0; i < num_keys; i++) {
        offsets[i] = i * sizeof(record);
        keys[i] = i;
    }

    // Allocate memory for records
    record **records = malloc(num_keys * sizeof(record*));
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize records
    for (int i = 0; i < num_keys; i++) {
        records[i] = malloc(sizeof(record));
        if (records[i] == NULL) {
            fprintf(stderr, "Failed to allocate memory for record %d\n", i);
            free(offsets);
            free(keys);
            free(records);
            return;
        }
        records[i]->key = keys[i];
        records[i]->value = rand() % (MAX_VAL - MIN_VAL + 1) + MIN_VAL;
    }

    // Lock memory for concurrent access
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // Set output parameters
    *offsets_out = offsets;
    *keys_out = keys;
    *records_out = records;

    // Unlock memory and return
    pthread_mutex_unlock(&mutex);
}

void free_data(long *offsets, int *keys, record **records) {
    // Lock memory for concurrent access
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // Free memory for offsets and keys
    free(offsets);
    free(keys);

    // Free memory for records
    for (int i = 0; i < num_keys; i++) {
        free(records[i]);
    }
    free(records);

    // Unlock memory and return
    pthread_mutex_unlock(&mutex);
}
