#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <errno.h>

// Define a structure to store the record information
typedef struct {
    int value;
} Record;

// Function to manage a sequence of shell commands in the background
int execute_commands(char *input) {
    // Split the input string into an array of commands using semicolons as delimiters
    char **commands = strsplit(input, ';');

    // Initialize an array of record structures to store the output values
    Record *records = (Record *)malloc(sizeof(Record) * sizeof(commands));

    // Loop through each command and execute it in a separate child process
    for (int i = 0; i < sizeof(commands); i++) {
        // Fork a new child process to execute the current command
        pid_t pid = fork();

        // If the fork was successful, execute the command in the child process
        if (pid > 0) {
            int status = execvp(commands[i], commands + i);

            // Check for errors and handle them appropriately
            if (status == -1) {
                perror("execvp");
                return 0;
            }
        } else if (pid == 0) {
            // If the fork was unsuccessful, exit the function with an error code
            fprintf(stderr, "fork failed: %s\n", strerror(errno));
            return 1;
        }
    }

    // Wait for all child processes to complete and retrieve their exit statuses
    int *statuses = (int *)malloc(sizeof(int) * sizeof(commands));
    waitpid(-1, statuses, WNOHANG);

    // Loop through each command and check its exit status
    for (int i = 0; i < sizeof(commands); i++) {
        if (statuses[i] != 0) {
            fprintf(stderr, "command %d failed with exit code %d\n", i + 1, statuses[i]);
            return 0;
        }
    }

    // Free the memory allocated for the record structures and return a success code
    free(records);
    free(statuses);
    return 1;
}
