    // Initialize variables
    $fileHashes = [];
    $errorLog = [];
    $concurrentFiles = 0;
    $totalFilesProcessed = 0;
    $startTime = time();

    // Validate input parameters
    if (!is_int($randomStringLength) || !is_string($characterSet) || !is_dir($directoryPath)) {
        throw new InvalidArgumentException("Invalid input parameter");
    }

    // Read all files within the specified directory synchronously
    $files = scandir($directoryPath);
    foreach ($files as $file) {
        if (is_file($file)) {
            $totalFilesProcessed++;
            $concurrentFiles++;

            // Validate file contents and process it into an array of hashes
            $fileContents = file_get_contents($file);
            if ($fileContents === false) {
                $errorLog[] = [
                    "type" => "FileAccessError",
                    "message" => "Failed to read file contents: {$file}",
                    "timestamp" => time()
                ];
                continue;
            }

            // Generate a random string identifier for each file
            $randomString = generateRandomString($randomStringLength, $characterSet);

            // Hash the file content using a configurable hash function
            $hash = hash("sha256", $fileContents);
            if ($hash === false) {
                $errorLog[] = [
                    "type" => "HashGenerationError",
                    "message" => "Failed to generate hash for file: {$file}",
                    "timestamp" => time()
                ];
                continue;
            }

            // Add the hash and random string identifier to the array of hashes
            $fileHashes[] = [
                "hash" => $hash,
                "randomString" => $randomString
            ];

            // Decrement the number of concurrent files being processed
            $concurrentFiles--;
        }
    }

    // Implement asynchronous processing of files
    while ($concurrentFiles > 0) {
        // Check if any files are queued for processing
        if (count($files) === 0) {
            break;
        }

        // Process the next file in the queue
        $file = array_shift($files);
        $concurrentFiles++;

        // Validate file contents and process it into an array of hashes
        $fileContents = file_get_contents($file);
        if ($fileContents === false) {
            $errorLog[] = [
                "type" => "FileAccessError",
                "message" => "Failed to read file contents: {$file}",
                "timestamp" => time()
            ];
            continue;
        }

        // Generate a random string identifier for each file
        $randomString = generateRandomString($randomStringLength, $characterSet);

        // Hash the file content using a configurable hash function
        $hash = hash("sha256", $fileContents);
        if ($hash === false) {
            $errorLog[] = [
                "type" => "HashGenerationError",
                "message" => "Failed to generate hash for file: {$file}",
                "timestamp" => time()
            ];
            continue;
        }

        // Add the hash and random string identifier to the array of hashes
        $fileHashes[] = [
            "hash" => $hash,
            "randomString" => $randomString
        ];

        // Decrement the number of concurrent files being processed
        $concurrentFiles--;
    }

    // Return an associative array containing:
    // - A random string identifier.
    // - An array of hashes for each processed file.
    // - An error log if any issues occur during processing, detailing the nature and timestamp of each error.
    return [
        "randomString" => generateRandomString($randomStringLength, $characterSet),
        "fileHashes" => $fileHashes,
        "errorLog" => $errorLog
    ];
}

// Generate a random string using the provided character set and length
function generateRandomString($length, $characterSet) {
    $randomString = "";
    for ($i = 0; $i < $length; $i++) {
        $randomString .= $characterSet[rand(0, strlen($characterSet) - 1)];
    }
    return $randomString;
}
