const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

function processFiles(directoryPath, fileNames, desiredStringLength, characterSet) {
  // Validate inputs
  if (!directoryPath || !fileNames || !desiredStringLength || !characterSet) {
    throw new Error('Invalid input parameters');
  }

  const files = [];
  for (const fileName of fileNames) {
    try {
      const fileContent = fs.readFileSync(path.join(directoryPath, fileName), 'utf8');
      files.push({ name: fileName, content: fileContent });
    } catch (err) {
      console.error(`Error reading file ${fileName}: ${err}`);
    }
  }

  // Generate random string
  const randomString = crypto.randomBytes(desiredStringLength).toString('hex');

  // Process files and combine content
  let combinedContent = '';
  for (const file of files) {
    try {
      const jsonContent = JSON.parse(file.content);
      combinedContent += JSON.stringify(jsonContent);
    } catch (err) {
      console.warn(`Error parsing JSON content from ${file.name}: ${err}`);
    }
  }

  // Combine random string and combined content
  const hashedCombinedObject = crypto.createHash('sha256').update(combinedContent + randomString).digest();

  return Promise.resolve({
    hashedCombinedObject,
    randomString,
  });
}
```
