// Custom realloc function for dynamic resizing of the record storage
void* custom_realloc(void* ptr, size_t size) {
    void* new_ptr = realloc(ptr, size);
    if (new_ptr == NULL) {
        // Handle memory allocation failure robustly
        printf("Error: Failed to allocate memory. Exiting.\n");
        exit(1);
    }
    return new_ptr;
}

// Struct for storing record data
typedef struct Record {
    long offset;
    int key;
    char status;
} Record;

// Function to initialize the dynamic record storage system
void init_record_storage(int* num_records, int* max_records) {
    // Allocate memory for the array of offsets and keys
    *num_records = 0;
    *max_records = 10;
    long* offsets = (long*)malloc(sizeof(long) * (*max_records));
    int* keys = (int*)malloc(sizeof(int) * (*max_records));
    if (offsets == NULL || keys == NULL) {
        // Handle memory allocation failure robustly
        printf("Error: Failed to allocate memory. Exiting.\n");
        exit(1);
    }
    memset(offsets, 0, sizeof(long) * (*max_records));
    memset(keys, 0, sizeof(int) * (*max_records));

    // Initialize the linked list structure for storing records
    Record* head = NULL;
    Record* tail = NULL;

    // Set all elements to their respective default values
    for (int i = 0; i < *max_records; i++) {
        offsets[i] = 0;
        keys[i] = 0;
        if (head == NULL) {
            head = tail = malloc(sizeof(Record));
        } else {
            tail->next = malloc(sizeof(Record));
            tail = tail->next;
        }
        tail->offset = offsets[i];
        tail->key = keys[i];
        tail->status = ' ';
    }

    // Set the head and tail pointers to the first record in the list
    *head_ptr = head;
    *tail_ptr = tail;
}

// Function to dynamically resize the record storage based on a predefined threshold condition
void resize_record_storage(int* num_records, int* max_records) {
    // Check if the number of records exceeds the current allocated size
    if (*num_records > *max_records) {
        // Reallocate memory for the array of offsets and keys
        long* new_offsets = (long*)custom_realloc(offsets, sizeof(long) * (*max_records));
        int* new_keys = (int*)custom_realloc(keys, sizeof(int) * (*max_records));
        if (new_offsets == NULL || new_keys == NULL) {
            // Handle memory allocation failure robustly
            printf("Error: Failed to allocate memory. Exiting.\n");
            exit(1);
        }
        offsets = new_offsets;
        keys = new_keys;

        // Update the maximum number of records and reallocate memory for the linked list structure
        *max_records *= 2;
        Record* new_head = NULL;
        Record* new_tail = NULL;
        for (int i = 0; i < *num_records; i++) {
            if (new_head == NULL) {
                new_head = malloc(sizeof(Record));
            } else {
                new_tail->next = malloc(sizeof(Record));
            }
            new_tail = new_tail->next;
            new_tail->offset = offsets[i];
            new_tail->key = keys[i];
            new_tail->status = ' ';
        }

        // Set the head and tail pointers to the first record in the list
        *head_ptr = new_head;
        *tail_ptr = new_tail;
    }
}

// Function to efficiently query records by key or offset
Record* get_record(int key) {
