#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <assert.h>
#include <pthread.h>

// Define the maximum memory limit for the cache
#define MAX_MEMORY 1024 * 1024 * 1024 // 1GB

// Define the maximum size of the queue
#define MAX_QUEUE 1024

// Define the structure for a node in the linked list
typedef struct Node {
    char* key;
    double value;
    struct Node* next;
} Node;

// Define the structure for the cache
typedef struct Cache {
    Node* head; // Pointer to the first node in the linked list
    int size; // Number of nodes in the linked list
    int count; // Number of unique keys in the cache
    pthread_mutex_t mutex; // Mutex for thread-safe operations
} Cache;

// Define the function to create a new node
Node* createNode(char* key, double value) {
    Node* node = malloc(sizeof(Node));
    assert(node != NULL);
    node->key = strdup(key);
    node->value = value;
    node->next = NULL;
    return node;
}

// Define the function to add a new node to the linked list
void addNode(Cache* cache, char* key, double value) {
    Node* node = createNode(key, value);
    pthread_mutex_lock(&cache->mutex);
    if (cache->head == NULL) {
        cache->head = node;
    } else {
        cache->head->next = node;
    }
    cache->size++;
    cache->count++;
    pthread_mutex_unlock(&cache->mutex);
}

// Define the function to remove a node from the linked list
void removeNode(Cache* cache, char* key) {
    Node* current = cache->head;
    while (current != NULL && strcmp(key, current->key) != 0) {
        current = current->next;
    }
    if (current == NULL) {
        return;
    }
    pthread_mutex_lock(&cache->mutex);
    Node* previous = current->previous;
    if (previous == NULL) {
        cache->head = current->next;
    } else {
        previous->next = current->next;
    }
    free(current->key);
    free(current);
    cache->size--;
    pthread_mutex_unlock(&cache->mutex);
}

// Define the function to update a node in the linked list
void updateNode(Cache* cache, char* key, double value) {
    Node* current = cache->head;
    while (current != NULL && strcmp(key, current->key) != 0) {
        current = current->next;
    }
    if (current == NULL) {
        return;
    }
    pthread_mutex_lock(&cache->mutex);
    current->value = value;
    pthread_mutex_unlock(&cache->mutex);
}

// Define the function to get a node from the linked list
Node* getNode(Cache* cache, char* key) {
    Node* current = cache->head;
    while (current != NULL && strcmp(key, current->key) != 0) {
        current = current->next;
    }
    if (current == NULL) {
        return NULL;
    }
    pthread_mutex_lock(&cache->mutex);
    Node* node = malloc(sizeof(Node));
    assert(node != NULL);
    node->key = strdup(current->key);
    node->value = current->value;
    node->next = NULL;
    pthread_mutex_unlock(&cache->mutex);
    return node;
}

// Define the function to add a key-value pair to the cache
void add(Cache* cache, char* key, double value) {
    if (cache->size >= MAX_MEMORY / sizeof(Node)) {
        // Evict least recently used item from the cache
        Node* node = cache->head;
        while (node != NULL && node->next != NULL) {
            node = node->next;
        }
        removeNode(cache, node->key);
    }
    addNode(cache, key, value);
}

// Define the function to update a key-value pair in the cache
void update(Cache* cache, char* key, double value) {
    if (getNode(cache, key) != NULL) {
        updateNode(cache, key, value);
    } else {
        add(cache, key, value);
    }
}

// Define the function to remove a key-value pair from the cache
void remove(Cache* cache, char* key) {
    if (getNode(cache, key) != NULL) {
        removeNode(cache, key);
    }
}

// Define the function to get a value for a given key in the cache
double get(Cache* cache, char* key) {
    Node* node = getNode(cache, key);
    if (node == NULL) {
        return -1;
    }
    return node->value;
}

// Define the function to clear the cache
void clear(Cache* cache) {
    pthread_mutex_lock(&cache->mutex);
    Node* current = cache->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->key);
        free(current);
        current = next;
    }
    cache->head = NULL;
    cache->size = 0;
    cache->count = 0;
    pthread_mutex_unlock(&cache->mutex);
}
```
This code implements a thread-safe, efficient caching system using a linked list and a hash table. The `add` function adds a new key-value pair to the cache, while the `update` function updates an existing key-value pair in the cache. The `remove` function removes a key-value pair from the cache, and the `get` function retrieves the value for a given key from the cache. The `clear` function clears the entire cache.

The code uses a mutex to ensure thread-safe operations, and it also implements a mechanism to evict least recently used items from the cache when the capacity is exceeded. It also optimizes memory usage by reusing memory blocks whenever possible.

The `add` function first checks if the total memory usage of the cache exceeds the maximum limit, and if so, it evicts the least recently used item from the cache before adding the new key-value pair. The `update` function updates an existing key-value pair in the cache by first retrieving the node using the `getNode` function, and then updating its value. If the key is not found in the cache, it adds a new key-value pair to the cache using the `add` function.

The `remove` function removes a key-value pair from the cache by first retrieving the node using the `getNode` function, and then removing it from the linked list and hash table. If the key is not found in the cache, it does nothing.

The `get` function retrieves the value for a given key from the cache by first retrieving the node using the `getNode` function, and then returning its value. If the key is not found in the cache, it returns -1.

