Here is a sample C function that dynamically manages memory for an array of floating-point numbers read from standard input:
```c
#include <stdio.h>
#include <stdlib.h>
#include <math.h>

// Function to calculate the mean and standard deviation of an array
void calculate_stats(float *arr, int size) {
    float sum = 0;
    for (int i = 0; i < size; i++) {
        sum += arr[i];
    }
    float mean = sum / size;

    float variance = 0;
    for (int i = 0; i < size; i++) {
        variance += pow(arr[i] - mean, 2);
    }
    variance /= size - 1;
    float stddev = sqrt(variance);

    printf("Mean: %f\nStandard Deviation: %f\n", mean, stddev);
}

// Function to read and manage memory for an array of floating-point numbers from standard input
void read_array(float **arr, int *size) {
    // Read the number of elements in the array from standard input
    scanf("%d", size);

    // Allocate memory for the array
    *arr = (float *)malloc(*size * sizeof(float));

    // Read each element of the array from standard input and store it in the allocated memory
    for (int i = 0; i < *size; i++) {
        scanf("%f", &((*arr)[i]));
    }
}

// Function to deallocate memory for an array of floating-point numbers
void deallocate_array(float **arr) {
    free(*arr);
}

int main() {
    // Declare variables to store the array and its size
    float *arr;
    int size;

    // Read the array from standard input using the read_array function
    read_array(&arr, &size);

    // Calculate the mean and standard deviation of the array using the calculate_stats function
    calculate_stats(arr, size);

    // Deallocate memory for the array using the deallocate_array function
    deallocate_array(&arr);

    return 0;
}
