// Define the record structure
typedef struct {
    double value;
    char *identifier;
    struct point *position;
} record;

// Define the pool of available identifiers
const char *identifiers[] = {"A", "B", "C", "D", "E"};

// Function to generate a random identifier from the pool
char *generate_identifier() {
    // Generate a random index between 0 and the length of the pool - 1
    int idx = rand() % (sizeof(identifiers) / sizeof(*identifiers));
    return strdup(identifiers[idx]);
}

// Function to allocate memory for an array of records
record *allocate_records(int num_records) {
    // Allocate memory for the array of records
    record *records = malloc(num_records * sizeof(*records));
    if (!records) {
        return NULL;
    }

    // Initialize each record with a random value and identifier
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 100.0;
        records[i].identifier = generate_identifier();
        records[i].position = malloc(sizeof(*records[i].position));
        if (!records[i].position) {
            free(records);
            return NULL;
        }
    }

    // Return the allocated array of records
    return records;
}

// Function to populate an array of records with random values and identifiers
record *populate_records(int num_records) {
    record *records = allocate_records(num_records);
    if (!records) {
        return NULL;
    }

    // Populate each record with a random value and identifier
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 100.0;
        records[i].identifier = generate_identifier();
        records[i].position->x = rand() % 100;
        records[i].position->y = rand() % 100;
    }

    // Return the populated array of records
    return records;
}

// Function to free memory allocated for an array of records
void free_records(record *records, int num_records) {
    if (!records) {
        return;
    }

    // Free each record's identifier and position
    for (int i = 0; i < num_records; i++) {
        free(records[i].identifier);
        free(records[i].position);
    }

    // Free the array of records
    free(records);
}
