char* processFile(const char* filename) {
    // Parse the input filename for relevant patterns
    const char* pattern = "\\d+_(\\w+)\\.(\\w+)";
    regex_t regex;
    regcomp(&regex, pattern, REG_EXTENDED);
    regmatch_t matches[3];
    if (regexec(&regex, filename, 3, matches, 0) == 0) {
        // Determine the number of digits and file type to append
        int numDigits = atoi(filename + matches[1].rm_so);
        char* fileType = filename + matches[2].rm_so;

        // Allocate memory for two arrays: one for storing long offset values and another for int keys
        size_t arraySize = numDigits * sizeof(long);
        long* offsets = malloc(arraySize);
        if (offsets == NULL) {
            return ""; // Memory allocation failed, handle error gracefully
        }
        size_t recordSize = sizeof(record);
        int numRecords = arraySize / recordSize;
        record* records = malloc(numRecords * recordSize);
        if (records == NULL) {
            free(offsets);
            return ""; // Memory allocation failed, handle error gracefully
        }

        // Initialize each record's int field to a random value within a specified range
        srand(time(NULL));
        for (int i = 0; i < numRecords; i++) {
            records[i].value = rand() % 100 + 1;
        }

        // Modify the extension of the provided filename by appending the determined number of digits and a specific file type
        char* modifiedFilename = malloc(strlen(filename) + numDigits + strlen(fileType) + 1);
        if (modifiedFilename == NULL) {
            free(offsets);
            free(records);
            return ""; // Memory allocation failed, handle error gracefully
        }
        sprintf(modifiedFilename, "%s_%d.%s", filename, numDigits, fileType);

        // Ensure that the memory allocation for all arrays and records is handled efficiently to minimize overhead and optimize performance
        free(offsets);
        free(records);
        return modifiedFilename;
    } else {
        return ""; // Memory allocation failed, handle error gracefully
    }
}
