    // Allocate memory for the offset array
    *offsets = (long *)malloc(sizeof(long) * 10);
    if (*offsets == NULL) {
        printf("Error: Failed to allocate memory for offset array\n");
        exit(1);
    }

    // Initialize the offset array with random values between 0 and 100
    for (int i = 0; i < 10; i++) {
        (*offsets)[i] = rand() % 100;
    }

    // Allocate memory for the key array
    *keys = (int *)malloc(sizeof(int) * 10);
    if (*keys == NULL) {
        printf("Error: Failed to allocate memory for key array\n");
        exit(1);
    }

    // Initialize the key array with random values between 0 and 100, ensuring unique keys
    for (int i = 0; i < 10; i++) {
        (*keys)[i] = rand() % 100;
        while (contains_key(*keys, i)) {
            (*keys)[i] = rand() % 100;
        }
    }
}

// Function to check if a key is already present in the array of keys
bool contains_key(int *keys, int key) {
    for (int i = 0; i < 10; i++) {
        if (keys[i] == key) {
            return true;
        }
    }
    return false;
}
