```python
import yaml
import subprocess
import logging

# Load configuration data from a YAML file
with open('config.yaml', 'r') as f:
    config = yaml.safe_load(f)

# Define environment variables and external configuration files
env_vars = {
    'ENVIRONMENT': config['environment'],
    'IMAGE_TAG': config['image_tag']
}
external_config = {
    'registry': config['registry'],
    'repository': config['repository'],
    'tag': config['tag']
}

# Define a function to execute shell commands through the subprocess module
def execute(command):
    try:
        output = subprocess.check_output(command, stderr=subprocess.STDOUT)
        logging.info('Command executed successfully')
        return output
    except subprocess.CalledProcessError as e:
        logging.error('Command failed with error code %d', e.returncode)
        raise

# Define a function to package, tag, and deploy the custom container image using Helm charts
def deploy_image(env_vars, external_config):
    # Package the custom container image using Docker
    command = ['docker', 'build', '-t', env_vars['IMAGE_TAG'], '.']
    execute(command)

    # Tag the packaged image with the registry and repository information
    command = ['docker', 'tag', env_vars['IMAGE_TAG'], f'{external_config["registry"]}/{external_config["repository"]}:{external_config["tag"]}']
    execute(command)

    # Deploy the tagged image to a Kubernetes cluster using Helm charts
    command = ['helm', 'upgrade', '-i', f'{env_vars["ENVIRONMENT"]}-image', '--set', f'image.repository={external_config["registry"]}/{external_config["repository"]}', '--set', f'image.tag={external_config["tag"]}']
    execute(command)

# Call the deploy_image function with the environment variables and external configuration files
deploy_image(env_vars, external_config)
```
