NetworkEvent* events = NULL;
size_t numEvents = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void populateEvents(time_t startTime, time_t endTime) {
    // Generate random timestamps within the specified time window
    srand((unsigned int)time(NULL));
    for (int i = 0; i < numEvents; i++) {
        events[i].timestamp = startTime + rand() % (endTime - startTime);
    }
}

void addEvent(NetworkEvent event) {
    // Lock the mutex to prevent concurrent access from multiple threads
    pthread_mutex_lock(&mutex);

    // Check if memory allocation failed
    if (!events) {
        perror("Memory allocation failed");
        return;
    }

    // Add the event to the array
    events[numEvents++] = event;

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

void removeEvent(time_t timestamp) {
    // Lock the mutex to prevent concurrent access from multiple threads
    pthread_mutex_lock(&mutex);

    // Find the event with the specified timestamp and remove it
    for (int i = 0; i < numEvents; i++) {
        if (events[i].timestamp == timestamp) {
            events[i] = events[--numEvents];
            break;
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

