// Define the record structure
typedef struct {
    int value;
} Record;

// Function to process a file and generate a new filename with random values
void processFile(const char* filename) {
    // Parse the input filename to determine the number of digits and file type to append
    const char* delimiters = " ._-";
    int numDigits = 0;
    bool isValid = false;
    for (int i = 0; i < strlen(filename); i++) {
        if (isdigit(filename[i])) {
            numDigits++;
        } else if (strchr(delimiters, filename[i]) != NULL) {
            isValid = true;
            break;
        }
    }
    if (!isValid) {
        printf("Invalid filename format\n");
        return;
    }

    // Dynamically allocate memory for two arrays: one for storing 'long' offset values and another for 'int' keys
    long* offsets = (long*)malloc(numDigits * sizeof(long));
    int* keys = (int*)malloc(numDigits * sizeof(int));
    if (offsets == NULL || keys == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    // Allocate memory for an array of 'record' structures, where each structure contains a single 'int' value
    int numRecords = 0;
    Record* records = (Record*)malloc(numDigits * sizeof(Record));
