#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Structure to store data points
typedef struct {
    double value;
    char *label;
    float timestamp;
} data_point;

// Linked list node for storing data points
typedef struct data_point_node {
    data_point *data_point;
    struct data_point_node *next;
} data_point_node;

// Custom hash table for quick key-based lookups
typedef struct {
    int size;
    int count;
    data_point_node **buckets;
} hash_table;

// Function to dynamically manage a collection of data points in real-time
void manage_data_points(hash_table *ht, data_point_node *head) {
    // Periodically check and release unused memory blocks
    if (ht->count > 0 && ht->size / ht->count < 2) {
        data_point_node *curr = head;
        while (curr != NULL) {
            if (curr->data_point->timestamp + 3600 < time(NULL)) {
                // Remove outdated entries
                data_point_node *tmp = curr;
                curr = curr->next;
                free(tmp);
            } else {
                curr = curr->next;
            }
        }
    }

    // Periodically prune old entries to balance between space and time complexity
    if (ht->count > 0 && ht->size / ht->count > 1.5) {
        data_point_node *curr = head;
        while (curr != NULL) {
            if (curr->data_point->timestamp + 3600 < time(NULL)) {
                // Remove outdated entries
                data_point_node *tmp = curr;
                curr = curr->next;
                free(tmp);
            } else {
                curr = curr->next;
            }
        }
    }

    // Handle concurrent access to shared resources safely and efficiently
    pthread_mutex_lock(&ht->mutex);
    data_point_node *curr = head;
    while (curr != NULL) {
        if (curr->data_point->timestamp + 3600 < time(NULL)) {
            // Remove outdated entries
            data_point_node *tmp = curr;
            curr = curr->next;
            free(tmp);
        } else {
            curr = curr->next;
        }
    }
    pthread_mutex_unlock(&ht->mutex);
}

// Function to insert a new data point into the linked list and hash table
void insert_data_point(hash_table *ht, data_point_node **head, data_point *dp) {
    // Create a new node for the data point
    data_point_node *new_node = malloc(sizeof(data_point_node));
    new_node->data_point = dp;
    new_node->next = NULL;

    // Insert the new node into the linked list and hash table
    pthread_mutex_lock(&ht->mutex);
    if (*head == NULL) {
        *head = new_node;
    } else {
        data_point_node *curr = *head;
        while (curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = new_node;
    }
    ht->size++;
    pthread_mutex_unlock(&ht->mutex);
}

// Function to delete a data point from the linked list and hash table
void delete_data_point(hash_table *ht, data_point_node **head, char *label) {
    // Find the node with the matching label in the linked list
    pthread_mutex_lock(&ht->mutex);
    data_point_node *curr = *head;
    while (curr != NULL && strcmp(curr->data_point->label, label) != 0) {
        curr = curr->next;
    }

    // Remove the node from the linked list and hash table
    if (curr != NULL) {
        data_point_node *tmp = curr;
        if (curr == *head) {
            *head = (*head)->next;
        } else {
            data_point_node *prev = *head;
            while (prev->next != tmp) {
                prev = prev->next;
            }
            prev->next = tmp->next;
        }
        ht->size--;
        free(tmp);
    }
    pthread_mutex_unlock(&ht->mutex);
}

// Function to lookup a data point in the hash table by label
data_point *lookup_data_point(hash_table *ht, char *label) {
    // Find the node with the matching label in the linked list
    pthread_mutex_lock(&ht->mutex);
    data_point_node *curr = ht->buckets[hash(label)];
    while (curr != NULL && strcmp(curr->data_point->label, label) != 0) {
        curr = curr->next;
    }

    // Return the data point if found, otherwise return NULL
    pthread_mutex_unlock(&ht->mutex);
    if (curr == NULL) {
        return NULL;
    } else {
        return curr->data_point;
    }
}

// Function to update a data point in the linked list and hash table
void update_data_point(hash_table *ht, data_point_node **head, char *label, double value) {
    // Find the node with the matching label in the linked list
    pthread_mutex_lock(&ht->mutex);
    data_point_node *curr = *head;
    while (curr != NULL && strcmp(curr->data_point->label, label) != 0) {
        curr = curr->next;
    }

    // Update the value of the data point if found, otherwise create a new node
    if (curr != NULL) {
        curr->data_point->value = value;
    } else {
        data_point *dp = malloc(sizeof(data_point));
        dp->label = label;
        dp->value = value;
        dp->timestamp = time(NULL);
        insert_data_point(ht, head, dp);
    }
    pthread_mutex_unlock(&ht->mutex);
}

// Function to delete all data points in the linked list and hash table
void clear_data_points(hash_table *ht, data_point_node **head) {
    // Remove all nodes from the linked list and hash table
    pthread_mutex_lock(&ht->mutex);
    while (*head != NULL) {
        data_point_node *tmp = *head;
        *head = (*head)->next;
        free(tmp);
    }
    ht->size = 0;
    pthread_mutex_unlock(&ht->mutex);
}

// Function to initialize the hash table and linked list
void init_data_points(hash_table *ht, data_point_node **head) {
    // Initialize the hash table with a default size of 1024 buckets
    ht->size = 0;
    ht->count = 0;
    ht->buckets = malloc(sizeof(data_point_node *) * 1024);
    for (int i = 0; i < 1024; i++) {
        ht->buckets[i] = NULL;
    }

    // Initialize the linked list with a default head node
    *head = malloc(sizeof(data_point_node));
    (*head)->next = NULL;
}

// Function to destroy the hash table and linked list
void destroy_data_points(hash_table *ht, data_point_node **head) {
    // Destroy all nodes in the linked list and hash table
    pthread_mutex_lock(&ht->mutex);
    while (*head != NULL) {
        data_point_node *tmp = *head;
        *head = (*head)->next;
        free(tmp);
    }
    ht->size = 0;
    pthread_mutex_unlock(&ht->mutex);
}
