// Custom hash table implementation for fast lookups based on unique user identifiers
struct UserHashTable {
    struct User *users; // Array of users
    int size; // Size of the hash table
};

// Balanced binary tree for ordered access and efficient range queries on age and location attributes
struct UserTree {
    struct User *root; // Root node of the tree
    int size; // Number of nodes in the tree
};

// User profile structure
struct User {
    char *id; // Unique identifier for the user
    char *name; // Name of the user
    char *location; // Location of the user
    int age; // Age of the user
    bool active; // Whether the user is active or not
};

// Function to create a new user hash table
struct UserHashTable *createUserHashTable(int size) {
    struct UserHashTable *table = malloc(sizeof(struct UserHashTable));
    if (!table) {
        perror("Failed to allocate memory for user hash table");
        return NULL;
    }
    table->users = calloc(size, sizeof(struct User));
    if (!table->users) {
        perror("Failed to allocate memory for user array");
        free(table);
        return NULL;
    }
    table->size = size;
    return table;
}

// Function to create a new user tree
struct UserTree *createUserTree() {
    struct UserTree *tree = malloc(sizeof(struct UserTree));
    if (!tree) {
        perror("Failed to allocate memory for user tree");
        return NULL;
    }
    tree->root = NULL;
    tree->size = 0;
    return tree;
}

// Function to add a new user to the hash table and tree
void addUser(struct UserHashTable *table, struct UserTree *tree, struct User *user) {
    // Add the user to the hash table
    int index = user->id % table->size;
    if (table->users[index].id != NULL) {
        perror("Failed to add user to hash table");
        return;
    }
    table->users[index] = *user;

    // Add the user to the tree
    struct UserTreeNode *node = malloc(sizeof(struct UserTreeNode));
    if (!node) {
        perror("Failed to allocate memory for user tree node");
        return;
    }
    node->user = user;
    node->left = NULL;
    node->right = NULL;
    if (tree->root == NULL) {
        tree->root = node;
    } else {
        struct UserTreeNode *current = tree->root;
        while (true) {
            if (user->age < current->user->age) {
                if (current->left == NULL) {
                    current->left = node;
                    break;
                } else {
                    current = current->left;
                }
            } else if (user->age > current->user->age) {
                if (current->right == NULL) {
                    current->right = node;
                    break;
                } else {
                    current = current->right;
                }
            } else {
                perror("Failed to add user to tree");
                return;
            }
        }
    }
    tree->size++;
}

// Function to retrieve a user from the hash table and tree
struct User *getUser(struct UserHashTable *table, struct UserTree *tree, char *id) {
    // Retrieve the user from the hash table
    int index = id % table->size;
    if (table->users[index].id == NULL || strcmp(table->users[index].id, id) != 0) {
        return NULL;
    }
    struct User *user = &table->users[index];

    // Retrieve the user from the tree
    if (tree->root == NULL) {
        return user;
    } else {
        struct UserTreeNode *current = tree->root;
        while (true) {
            if (strcmp(user->id, current->user->id) < 0) {
                if (current->left == NULL) {
                    break;
                } else {
                    current = current->left;
                }
            } else if (strcmp(user->id, current->user->id) > 0) {
                if (current->right == NULL) {
                    break;
                } else {
                    current = current->right;
                }
            } else {
                return user;
            }
        }
    }
    return NULL;
}

// Function to update a user in the hash table and tree
void updateUser(struct UserHashTable *table, struct UserTree *tree, struct User *user) {
    // Update the user in the hash table
    int index = user->id % table->size;
    if (table->users[index].id == NULL || strcmp(table->users[index].id, user->id) != 0) {
        perror("Failed to update user");
        return;
    }
    table->users[index] = *user;

    // Update the user in the tree
    if (tree->root == NULL) {
        return;
    } else {
        struct UserTreeNode *current = tree->root;
        while (true) {
            if (strcmp(user->id, current->user->id) < 0) {
                if (current->left == NULL) {
                    break;
                } else {
                    current = current->left;
                }
            } else if (strcmp(user->id, current->user->id) > 0) {
                if (current->right == NULL) {
                    break;
                } else {
                    current = current->right;
                }
            } else {
                current->user = user;
                return;
            }
        }
    }
}

// Function to remove a user from the hash table and tree
void removeUser(struct UserHashTable *table, struct UserTree *tree, char *id) {
    // Remove the user from the hash table
    int index = id % table->size;
    if (table->users[index].id == NULL || strcmp(table->users[index].id, id) != 0) {
        return;
    }
    table->users[index] = (struct User){NULL};

    // Remove the user from the tree
    if (tree->root == NULL) {
        return;
    } else {
        struct UserTreeNode *current = tree->root;
        while (true) {
            if (strcmp(id, current->user->id) < 0) {
                if (current->left == NULL) {
                    break;
                } else {
                    current = current->left;
                }
            } else if (strcmp(id, current->user->id) > 0) {
                if (current->right == NULL) {
                    break;
                } else {
                    current = current->right;
                }
            } else {
                if (current->left != NULL && current->right != NULL) {
                    struct UserTreeNode *successor = current->right;
                    while (successor->left != NULL) {
                        successor = successor->left;
                    }
                    current->user = successor->user;
                    current->right = removeUser(tree, successor);
                } else if (current->left == NULL && current->right == NULL) {
                    free(current);
                    tree->root = NULL;
                } else if (current->left != NULL && current->right == NULL) {
                    struct UserTreeNode *temp = current->left;
                    free(current);
                    tree->root = temp;
                } else if (current->left == NULL && current->right != NULL) {
                    struct UserTreeNode *temp = current->right;
                    free(current);
                    tree->root = temp;
                }
                return;
            }
        }
    }
}

// Function to search for users in the hash table and tree based on location
struct User *searchUsersByLocation(struct UserHashTable *table, struct UserTree *tree, char *location) {
    // Search for users in the hash table
    int index = 0;
    while (index < table->size) {
        if (table->users[index].id != NULL && strcmp(table->users[index].location, location) == 0) {
            return &table->users[index];
        }
        index++;
    }

    // Search for users in the tree
    if (tree->root == NULL) {
        return NULL;
    } else {
        struct UserTreeNode *current = tree->root;
        while (true) {
            if (strcmp(location, current->user->location) < 0) {
                if (current->left == NULL) {
                    break;
                } else {
                    current = current->left;
                }
            } else if (strcmp(location, current->user->location) > 0) {
                if (current->right == NULL) {
                    break;
                } else {
                    current = current->right;
                }
            } else {
                return current->user;
            }
        }
    }
    return NULL;
}

// Function to search for users in the hash table and tree based on age range
struct User *searchUsersByAgeRange(struct UserHashTable *table, struct UserTree *tree, int min_age, int max_age) {
    // Search for users in the hash table
    int index = 0;
    while (index < table->size) {
        if (table->users[index].id != NULL && table->users[index].age >= min_age && table->users[index].age <= max_age) {
            return &table->users[index];
        }
        index++;
    }

    // Search for users in the tree
    if (tree->root == NULL) {
        return NULL;
    } else {
        struct UserTreeNode *current = tree->root;
        while (true) {
            if (current->user->age < min_age) {
                if (current->left == NULL) {
                    break;
                } else {
                    current = current->left;
                }
            } else if (current->user->age > max_age) {
                if (current->right == NULL) {
                    break;
                } else {
                    current = current->right;
                }
            } else {
                return current->user;
            }
        }
    }
    return NULL;
}

// Function to search for users in the hash table and tree based on membership status
struct User *searchUsersByMembershipStatus(struct UserHashTable *table, struct UserTree *tree, bool active) {
    // Search for users in the hash table
    int index = 0;
    while (index < table->size) {
        if (table->users[index].id != NULL && table->users[index].active == active) {
            return &table->users[index];
        }
        index++;
    }

    // Search for users in the tree
    if (tree->root == NULL) {
        return NULL;
    } else {
        struct UserTreeNode *current = tree->root;
        while (true) {
            if (active && current->user->active) {
                return current->user;
            } else if (!active && !current->user->active) {
                return current->user;
            }
            if (current->left == NULL) {
                break;
            } else {
                current = current->left;
            }
        }
    }
    return NULL;
}

// Function to perform periodic user activity tracking and status updates
void trackUserActivity(struct UserHashTable *table, struct UserTree *tree) {
    // Update the user activity status in the hash table
    int index = 0;
    while (index < table->size) {
        if (table->users[index].id != NULL && table->users[index].active) {
            table->users[index].last_activity = time(NULL);
        }
        index++;
    }

    // Update the user activity status in the tree
    if (tree->root == NULL) {
        return;
    } else {
        struct UserTreeNode *current = tree->root;
        while (true) {
            if (current->user->active) {
                current->user->last_activity = time(NULL);
            }
            if (current->left == NULL) {
                break;
            } else {
                current = current->left;
            }
        }
    }
}

// Function to detect and report memory leaks by periodically checking for unused memory blocks
void checkForMemoryLeaks(struct UserHashTable *table, struct UserTree *tree) {
    // Check for memory leaks in the hash table
    int index = 0;
    while (index < table->size) {
        if (table->users[index].id != NULL && table->users[index].active) {
            free(table->users[index]);
        }
        index++;
    }

    // Check for memory leaks in the tree
    if (tree->root == NULL) {
        return;
    } else {
        struct UserTreeNode *current = tree->root;
        while (true) {
            if (current->user->active) {
                free(current->user);
            }
            if (current->left == NULL) {
                break;
            } else {
                current = current->left;
            }
        }
    }
}

// Function to export user data to a CSV file
void exportUserData(struct UserHashTable *table, struct UserTree *tree, char *filename) {
    // Open the output file
    FILE *output_file = fopen(filename, "w");
    if (output_file == NULL) {
        printf("Error: Unable to open output file.\n");
        return;
    }

    // Write the header row to the output file
    fprintf(output_file, "ID,Name,Email,Age,Location,Membership Status\n");

    // Iterate over the users in the hash table and tree and write their data to the output file
    int index = 0;
    while (index < table->size) {
        if (table->users[index].id != NULL && table->users[index].active) {
            fprintf(output_file, "%s,%s,%s,%d,%s,%s\n", table->users[index].id, table->users[index].name, table->users[index].email, table->users[index].age, table->users[index].location, table->users[index].active ? "Active" : "Inactive");
        }
        index++;
    }
    if (tree->root == NULL) {
        return;
    } else {
        struct UserTreeNode *current = tree->root;
        while (true) {
            if (current->user->id != NULL && current->user->active) {
                fprintf(output_file, "%s,%s,%s,%d,%s,%s\n", current->user->id, current->user->name, current->user->email, current->user->age, current->user->location, current->user->active ? "Active" : "Inactive");
            }
            if (current->left == NULL) {
                break;
            } else {
                current = current->left;
            }
        }
    }

    // Close the output file
    fclose(output_file);
}
