    // Lock the mutex
    pthread_mutex_lock(mutex);
}

// Define the function to ensure the system can handle concurrent access and modifications from multiple threads, leveraging appropriate synchronization mechanisms to maintain thread safety.
void* mutexUnlock(pthread_mutex_t* mutex) {
    // Unlock the mutex
    pthread_mutex_unlock(mutex);
}

// Define the function to handle robust error handling to manage memory allocation failures gracefully, ensuring partial allocations do not lead to data loss.
