    int count;
    Node **buckets;
} HashTable;

// Define the memory pool structure
typedef struct {
    int size;
    int count;
    void *memory;
} MemoryPool;

// Define the logging system
#define LOG_FILE "log.txt"
#define LOG(format, ...) fprintf(stderr, format "\n", __VA_ARGS__)

// Function to initialize and configure the linked list of records
void initRecords(Record **records, int size, int range) {
    // Allocate memory for the linked list nodes
    Node *head = NULL;
    Node *tail = NULL;
    for (int i = 0; i < size; i++) {
        Record *record = malloc(sizeof(Record));
        if (!record) {
            LOG("Error: Failed to allocate memory for record %d", i);
            continue;
        }
        record->offset = i;
        record->key = rand() % range + 1;
        record->value = rand() % range + 1;
        Node *node = malloc(sizeof(Node));
        if (!node) {
            LOG("Error: Failed to allocate memory for node %d", i);
            free(record);
            continue;
        }
        node->record = record;
        node->next = NULL;
        if (head == NULL) {
            head = node;
        } else {
            tail->next = node;
        }
        tail = node;
    }
    *records = head;
}

// Function to initialize and configure the hash table
void initHashTable(HashTable **hash_table, int size) {
    // Allocate memory for the hash table buckets
    HashTable *htable = malloc(sizeof(HashTable));
    if (!htable) {
        LOG("Error: Failed to allocate memory for hash table");
        return;
    }
    htable->size = size;
    htable->count = 0;
    htable->buckets = calloc(size, sizeof(Node *));
    if (!htable->buckets) {
        LOG("Error: Failed to allocate memory for hash table buckets");
        free(htable);
        return;
    }
    *hash_table = htable;
}

// Function to initialize and configure the memory pool
void initMemoryPool(MemoryPool **memory_pool, int size) {
    // Allocate memory for the memory pool
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (!pool) {
        LOG("Error: Failed to allocate memory for memory pool");
        return;
    }
    pool->size = size;
    pool->count = 0;
    pool->memory = calloc(size, sizeof(void *));
    if (!pool->memory) {
        LOG("Error: Failed to allocate memory for memory pool");
        free(pool);
        return;
    }
    *memory_pool = pool;
}

// Function to insert a record into the linked list and hash table
void insertRecord(Record **records, HashTable **hash_table, MemoryPool **memory_pool, int range) {
    // Allocate memory for the new record
    Record *record = malloc(sizeof(Record));
    if (!record) {
        LOG("Error: Failed to allocate memory for new record");
        return;
    }
    record->offset = (*records)->offset + 1;
    record->key = rand() % range + 1;
    record->value = rand() % range + 1;
    // Insert the new record into the linked list
    Node *node = malloc(sizeof(Node));
    if (!node) {
        LOG("Error: Failed to allocate memory for node");
        free(record);
        return;
    }
    node->record = record;
    node->next = (*records)->next;
    (*records)->next = node;
    // Insert the new record into the hash table
    int bucket_index = record->key % (*hash_table)->size;
    Node *bucket = (*hash_table)->buckets[bucket_index];
    if (bucket == NULL) {
        bucket = malloc(sizeof(Node));
        if (!bucket) {
            LOG("Error: Failed to allocate memory for hash table bucket");
            free(record);
            return;
        }
        bucket->next = NULL;
        (*hash_table)->buckets[bucket_index] = bucket;
    }
    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        LOG("Error: Failed to allocate memory for hash table node");
        free(record);
        return;
    }
    new_node->record = record;
    new_node->next = bucket->next;
    bucket->next = new_node;
    // Update the hash table count and log the insertion
    (*hash_table)->count++;
    LOG("Inserted record with key %d and value %d", record->key, record->value);
}

// Function to delete a record from the linked list and hash table
void deleteRecord(Record **records, HashTable **hash_table, MemoryPool **memory_pool) {
    // Find the node to be deleted in the linked list
    Node *node = (*records)->next;
    if (node == NULL) {
        LOG("Error: No record found to delete");
        return;
    }
    // Delete the node from the linked list
    (*records)->next = node->next;
    free(node);
    // Find the node to be deleted in the hash table
    int bucket_index = node->record->key % (*hash_table)->size;
    Node *bucket = (*hash_table)->buckets[bucket_index];
    if (bucket == NULL) {
        LOG("Error: No record found to delete");
        return;
    }
    // Delete the node from the hash table
    Node *prev = bucket;
    while (prev->next != NULL && prev->next->record != node->record) {
        prev = prev->next;
    }
    if (prev->next == NULL) {
        LOG("Error: No record found to delete");
        return;
    }
    prev->next = prev->next->next;
    free(node);
    // Update the hash table count and log the deletion
    (*hash_table)->count--;
    LOG("Deleted record with key %d and value %d", node->record->key, node->record->value);
}

// Function to traverse the linked list and print all records
void traverseRecords(Record **records) {
    // Traverse the linked list and print each record
    Node *node = (*records)->next;
    while (node != NULL) {
        Record *record = node->record;
        LOG("Record with key %d and value %d", record->key, record->value);
        node = node->next;
    }
}

// Function to release unused memory blocks in the linked list and hash table
void releaseMemory(Record **records, HashTable **hash_table, MemoryPool **memory_pool) {
    // Release unused memory blocks in the linked list
    Node *node = (*records)->next;
    while (node != NULL) {
        Record *record = node->record;
        if (record->value == 0) {
            free(record);
            Node *prev = node;
            node = node->next;
            prev->next = node->next;
            free(node);
        } else {
            node = node->next;
        }
    }
    // Release unused memory blocks in the hash table
    for (int i = 0; i < (*hash_table)->size; i++) {
        Node *bucket = (*hash_table)->buckets[i];
        while (bucket != NULL) {
            Record *record = bucket->record;
            if (record->value == 0) {
                free(record);
                Node *prev = bucket;
                bucket = bucket->next;
                prev->next = bucket->next;
                free(bucket);
            } else {
                bucket = bucket->next;
            }
        }
    }
}

// Function to periodically release unused memory blocks in the linked list and hash table
void periodicReleaseMemory(Record **records, HashTable **hash_table, MemoryPool **memory_pool) {
    // Release unused memory blocks in the linked list
    Node *node = (*records)->next;
    while (node != NULL) {
        Record *record = node->record;
        if (record->value == 0) {
            free(record);
            Node *prev = node;
            node = node->next;
            prev->next = node->next;
            free(node);
        } else {
            node = node->next;
        }
    }
    // Release unused memory blocks in the hash table
    for (int i = 0; i < (*hash_table)->size; i++) {
        Node *bucket = (*hash_table)->buckets[i];
        while (bucket != NULL) {
            Record *record = bucket->record;
            if (record->value == 0) {
                free(record);
                Node *prev = bucket;
                bucket = bucket->next;
                prev->next = bucket->next;
                free(bucket);
            } else {
                bucket = bucket->next;
            }
        }
    }
}

// Function to handle memory allocation failures gracefully
void handleMemoryAllocationFailure(Record **records, HashTable **hash_table, MemoryPool **memory_pool) {
    // Log the error and continue running
    LOG("Error: Failed to allocate memory");
}

