// Define the function to initialize the logging framework
LogFramework* init_logging(size_t initial_capacity, size_t max_capacity) {
    // Validate the configuration parameters
    if (initial_capacity <= 0 || max_capacity <= 0) {
        return NULL;
    }

    // Allocate memory for the circular buffer and initialize it with default values
    LogEntry* buffer = malloc(sizeof(LogEntry) * initial_capacity);
    if (buffer == NULL) {
        return NULL;
    }
    memset(buffer, 0, sizeof(LogEntry) * initial_capacity);

    // Allocate memory for the hash table and initialize it with default values
    size_t* keys = malloc(sizeof(size_t) * initial_capacity);
    if (keys == NULL) {
        free(buffer);
        return NULL;
