        records[i].value = rand() % max_capacity;
    }

    // Initialize the hash table with a custom resizing strategy
    HashTable* table = create_hash_table(initial_capacity, max_capacity);
    if (table == NULL) {
        free(buffer);
        free(keys);
        free(records);
        return NULL;
    }

    // Initialize the lock for concurrent access
    pthread_mutex_init(&lock, NULL);

    // Create a new logging framework structure and return it
    LogFramework* framework = malloc(sizeof(LogFramework));
    if (framework == NULL) {
        free(buffer);
        free(keys);
        free(records);
        destroy_hash_table(table);
        pthread_mutex_destroy(&lock);
        return NULL;
    }
    framework->buffer = buffer;
    framework->capacity = initial_capacity;
    framework->size = 0;
    framework->remaining = initial_capacity;
    framework->table = table;
    framework->lock = lock;

    return framework;
}

// Define the function to add a log entry to the logging framework
void add_log_entry(LogFramework* framework, time_t timestamp, int level, const char* message) {
    // Acquire the lock for concurrent access
    pthread_mutex_lock(&framework->lock);

    // Check if the buffer is full and needs to be resized
    if (framework->size == framework->capacity) {
        // Resize the buffer and hash table
        size_t new_capacity = framework->capacity * 2;
        LogEntry* new_buffer = realloc(framework->buffer, sizeof(LogEntry) * new_capacity);
        if (new_buffer == NULL) {
            pthread_mutex_unlock(&framework->lock);
            return;
        }
        framework->buffer = new_buffer;
        size_t* new_keys = realloc(framework->table, sizeof(size_t) * new_capacity);
        if (new_keys == NULL) {
            pthread_mutex_unlock(&framework->lock);
            return;
        }
        framework->table = new_keys;
        framework->capacity = new_capacity;
    }

    // Add the log entry to the buffer and hash table
    LogEntry* entry = &framework->buffer[framework->size];
    entry->timestamp = timestamp;
    entry->level = level;
    strncpy(entry->message, message, 256);
    size_t key = hash(timestamp) % framework->capacity;
    framework->table[key] = framework->size;
    framework->size++;
    framework->remaining--;

    // Release the lock for concurrent access
    pthread_mutex_unlock(&framework->lock);
}

// Define the function to retrieve a log entry from the logging framework
LogEntry* get_log_entry(LogFramework* framework, size_t index) {
    // Acquire the lock for concurrent access
    pthread_mutex_lock(&framework->lock);

    // Check if the index is valid and return NULL if not
    if (index >= framework->size || index < 0) {
        pthread_mutex_unlock(&framework->lock);
        return NULL;
    }

    // Return the log entry at the specified index
    LogEntry* entry = &framework->buffer[index];
    pthread_mutex_unlock(&framework->lock);
    return entry;
}

// Define the function to destroy the logging framework
void destroy_logging(LogFramework* framework) {
    // Acquire the lock for concurrent access
    pthread_mutex_lock(&framework->lock);

    // Free the memory allocated for the circular buffer and hash table
    free(framework->buffer);
    free(framework->table);

    // Destroy the lock for concurrent access
    pthread_mutex_destroy(&framework->lock);

    // Release the lock for concurrent access
    pthread_mutex_unlock(&framework->lock);
}
