// Define the structure for a record in the dataset
typedef struct {
    int key;
    float weight;
    double timestamp;
} Record;

// Define the data structure to hold the records
typedef struct {
    Record* records;
    size_t num_records;
    pthread_mutex_t mutex;
} Dataset;

// Function to insert a new record into the dataset
void insert(Dataset* dataset, int key, float weight, double timestamp) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&dataset->mutex);

    // Allocate memory for the new record
    Record* new_record = malloc(sizeof(Record));
    new_record->key = key;
    new_record->weight = weight;
    new_record->timestamp = timestamp;

    // Insert the new record into the dataset
    dataset->records[dataset->num_records++] = *new_record;

    // Unlock the mutex
    pthread_mutex_unlock(&dataset->mutex);
}

// Function to delete a record from the dataset
void delete(Dataset* dataset, int key) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&dataset->mutex);

    // Find the index of the record to be deleted
    size_t i;
    for (i = 0; i < dataset->num_records; i++) {
        if (dataset->records[i].key == key) {
            break;
        }
    }

    // If the record is found, delete it and shift the remaining records
    if (i < dataset->num_records) {
        for (size_t j = i; j < dataset->num_records - 1; j++) {
            dataset->records[j] = dataset->records[j + 1];
        }
        dataset->num_records--;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&dataset->mutex);
}

// Function to traverse the records in the dataset based on key criteria
void traverse_key(Dataset* dataset, int key) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&dataset->mutex);

    // Find the index of the record with the given key
    size_t i;
    for (i = 0; i < dataset->num_records; i++) {
        if (dataset->records[i].key == key) {
            break;
        }
    }

    // If the record is found, print its weight and timestamp
    if (i < dataset->num_records) {
        printf("Weight: %f\n", dataset->records[i].weight);
        printf("Timestamp: %lf\n", dataset->records[i].timestamp);
    } else {
        printf("Record not found.\n");
    }

    // Unlock the mutex
    pthread_mutex_unlock(&dataset->mutex);
}

// Function to traverse the records in the dataset based on timestamp criteria
void traverse_timestamp(Dataset* dataset, double timestamp) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&dataset->mutex);

    // Find the index of the record with the given timestamp
    size_t i;
    for (i = 0; i < dataset->num_records; i++) {
        if (dataset->records[i].timestamp == timestamp) {
            break;
        }
    }

    // If the record is found, print its weight and key
    if (i < dataset->num_records) {
        printf("Weight: %f\n", dataset->records[i].weight);
        printf("Key: %d\n", dataset->records[i].key);
    } else {
        printf("Record not found.\n");
    }

    // Unlock the mutex
    pthread_mutex_unlock(&dataset->mutex);
}

// Function to periodically check and release unused memory blocks
void check_and_release(Dataset* dataset) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&dataset->mutex);

    // Check if any records are unused
    size_t i;
    for (i = 0; i < dataset->num_records; i++) {
        if (dataset->records[i].key == -1) {
            break;
        }
    }

    // If any records are unused, release them and shift the remaining records
    if (i < dataset->num_records) {
        for (size_t j = i; j < dataset->num_records - 1; j++) {
            dataset->records[j] = dataset->records[j + 1];
        }
        dataset->num_records--;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&dataset->mutex);
}

// Function to serialize and deserialize the dataset to disk for persistence
void serialize(Dataset* dataset, FILE* file) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&dataset->mutex);

    // Write the number of records to the file
    fwrite(&dataset->num_records, sizeof(size_t), 1, file);

    // Write each record to the file
    for (size_t i = 0; i < dataset->num_records; i++) {
        Record* record = &dataset->records[i];
        fwrite(&record->key, sizeof(int), 1, file);
        fwrite(&record->weight, sizeof(float), 1, file);
        fwrite(&record->timestamp, sizeof(double), 1, file);
    }

    // Unlock the mutex
    pthread_mutex_unlock(&dataset->mutex);
}

void deserialize(Dataset* dataset, FILE* file) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&dataset->mutex);

    // Read the number of records from the file
    fread(&dataset->num_records, sizeof(size_t), 1, file);

    // Allocate memory for the records
    dataset->records = malloc(sizeof(Record) * dataset->num_records);

    // Read each record from the file and insert it into the dataset
    for (size_t i = 0; i < dataset->num_records; i++) {
        Record* record = &dataset->records[i];
        fread(&record->key, sizeof(int), 1, file);
        fread(&record->weight, sizeof(float), 1, file);
        fread(&record->timestamp, sizeof(double), 1, file);
        insert(dataset, record->key, record->weight, record->timestamp);
    }

    // Unlock the mutex
    pthread_mutex_unlock(&dataset->mutex);
}
