} MAC_FRAME_T;

// Define the configuration structure for the high-performance network interface
typedef struct {
    int num_threads;
    pthread_mutex_t *locks;
    pthread_cond_t *conds;
    pthread_t *threads;
    MAC_FRAME_T **frames;
} NETWORK_CONFIG_T;

// Define the function to initialize the configuration structure
void init_config(NETWORK_CONFIG_T *config) {
    // Initialize the number of threads to 0
    config->num_threads = 0;

    // Allocate memory for the locks, conditions, and threads
    config->locks = (pthread_mutex_t *)malloc(sizeof(pthread_mutex_t) * MAX_THREADS);
    config->conds = (pthread_cond_t *)malloc(sizeof(pthread_cond_t) * MAX_THREADS);
    config->threads = (pthread_t *)malloc(sizeof(pthread_t) * MAX_THREADS);

    // Initialize the locks and conditions
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_mutex_init(&config->locks[i], NULL);
        pthread_cond_init(&config->conds[i], NULL);
    }

    // Allocate memory for the frames
    config->frames = (MAC_FRAME_T **)malloc(sizeof(MAC_FRAME_T *) * MAX_FRAMES);

    // Initialize the frames to NULL
    for (int i = 0; i < MAX_FRAMES; i++) {
        config->frames[i] = NULL;
    }
}

// Define the function to add a new frame to the configuration structure
void add_frame(NETWORK_CONFIG_T *config, MAC_FRAME_T *frame) {
    // Acquire the lock for the current thread
    pthread_mutex_lock(&config->locks[pthread_self()]);

    // Check if there is space in the frame buffer
    if (config->num_frames < MAX_FRAMES) {
        // Add the new frame to the buffer
        config->frames[config->num_frames++] = frame;
    } else {
        // If the buffer is full, discard the oldest frame and add the new one
        MAC_FRAME_T *oldest_frame = config->frames[0];
        for (int i = 1; i < MAX_FRAMES; i++) {
            if (config->frames[i] != NULL) {
                oldest_frame = config->frames[i];
            }
        }
        free(oldest_frame);
        config->frames[0] = frame;
    }

    // Release the lock for the current thread
    pthread_mutex_unlock(&config->locks[pthread_self()]);
}

// Define the function to remove a frame from the configuration structure
void remove_frame(NETWORK_CONFIG_T *config, MAC_FRAME_T *frame) {
    // Acquire the lock for the current thread
    pthread_mutex_lock(&config->locks[pthread_self()]);

    // Check if the frame is in the buffer
    int index = 0;
    while (index < config->num_frames && config->frames[index] != frame) {
        index++;
    }

    // If the frame is found, remove it from the buffer
    if (index < config->num_frames) {
        for (int i = index; i < config->num_frames - 1; i++) {
            config->frames[i] = config->frames[i + 1];
        }
        config->frames[config->num_frames - 1] = NULL;
    }

    // Release the lock for the current thread
    pthread_mutex_unlock(&config->locks[pthread_self()]);
}

// Define the function to handle a new connection
void handle_new_connection(NETWORK_CONFIG_T *config) {
    // Acquire the lock for the current thread
    pthread_mutex_lock(&config->locks[pthread_self()]);

    // Check if there is space in the thread buffer
    if (config->num_threads < MAX_THREADS) {
        // Create a new thread and add it to the buffer
        pthread_t *new_thread = malloc(sizeof(pthread_t));
        pthread_create(new_thread, NULL, handle_frames, config);
        config->threads[config->num_threads++] = new_thread;
    } else {
        // If the buffer is full, wait for a thread to finish and then create a new one
        pthread_cond_wait(&config->conds[pthread_self()], &config->locks[pthread_self()]);
        pthread_t *new_thread = malloc(sizeof(pthread_t));
        pthread_create(new_thread, NULL, handle_frames, config);
        config->threads[0] = new_thread;
    }

    // Release the lock for the current thread
    pthread_mutex_unlock(&config->locks[pthread_self()]);
}

