    bst.buckets = malloc(sizeof(BST*) * bst.size);

    // Read each record in the hash table and binary search tree from the file
    for (int i = 0; i < hash_table.size; i++) {
        Record* record = malloc(sizeof(Record));
        fread(record, sizeof(Record), 1, file);
        hash_table.buckets[i] = record;
