// Define the structure to store log entries
typedef struct {
    long timestamp;
    int severity_level;
    char* message;
} logEntry;

// Define a linked list node to store log entries
typedef struct {
    logEntry entry;
    struct node* next;
} node;

// Define the head of the linked list
node* head = NULL;

// Function to add a new log entry
void addLogEntry(long timestamp, int severity_level, char* message) {
    // Create a new node for the log entry
    node* newNode = (node*)malloc(sizeof(node));
    if (!newNode) {
        printf("Error: Failed to allocate memory for new log entry\n");
        return;
    }

    // Initialize the fields of the new node
    newNode->entry.timestamp = timestamp;
    newNode->entry.severity_level = severity_level;
    newNode->entry.message = message;

    // Add the new node to the linked list
    if (head == NULL) {
        head = newNode;
    } else {
        node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
}

// Function to remove log entries by timestamp
void removeLogEntriesByTimestamp(long timestamp) {
    // Find the node with the matching timestamp
    node* current = head;
    while (current != NULL && current->entry.timestamp != timestamp) {
        current = current->next;
    }

    // If a match is found, remove the node from the linked list
    if (current != NULL) {
        node* previous = current->previous;
        if (previous == NULL) {
            head = current->next;
        } else {
            previous->next = current->next;
        }
        free(current);
    }
}

// Function to update the severity level of an existing log entry
void updateLogEntrySeverityLevel(long timestamp, int new_severity_level) {
    // Find the node with the matching timestamp
    node* current = head;
    while (current != NULL && current->entry.timestamp != timestamp) {
        current = current->next;
    }

    // If a match is found, update the severity level of the entry
    if (current != NULL) {
        current->entry.severity_level = new_severity_level;
    }
}

// Function to iterate over all log entries
void iterateLogEntries(void (*callback)(logEntry*)) {
    // Iterate over the linked list and call the callback function for each entry
    node* current = head;
    while (current != NULL) {
        callback(&current->entry);
        current = current->next;
    }
}
