    fd = open(filepath, O_WRONLY | O_TRUNC);
    if (fd == -1) {
        return ERROR_FILE_WRITE;
    }
    length = write(fd, buffer, chunk_size);
    close(fd);
    if (length == -1) {
        return ERROR_FILE_WRITE;
    }

    // Clean up and return success
    EVP_CIPHER_CTX_free(ctx);
    free(buffer);
    return 0;
