#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the entry structure
typedef struct {
    long timestamp;
    int priority_level;
    char* message;
} entry_t;

// Define the collection structure
typedef struct {
    entry_t** entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} collection_t;

// Initialize a new collection with a given capacity
collection_t* collection_init(size_t capacity) {
    collection_t* col = malloc(sizeof(collection_t));
    if (!col) {
        return NULL;
    }
    col->entries = calloc(capacity, sizeof(entry_t*));
    if (!col->entries) {
        free(col);
        return NULL;
    }
    col->capacity = capacity;
    col->count = 0;
    pthread_mutex_init(&col->mutex, NULL);
    return col;
}

// Add a new entry to the collection
int collection_add(collection_t* col, long timestamp, int priority_level, char* message) {
    if (!col || !message) {
        return -1;
    }
    pthread_mutex_lock(&col->mutex);
    // Check if the collection is full
    if (col->count == col->capacity) {
        pthread_mutex_unlock(&col->mutex);
        return -2;
    }
    // Allocate memory for the new entry
    entry_t* new_entry = malloc(sizeof(entry_t));
    if (!new_entry) {
        pthread_mutex_unlock(&col->mutex);
        return -3;
    }
    // Copy the timestamp, priority level, and message to the new entry
    new_entry->timestamp = timestamp;
    new_entry->priority_level = priority_level;
    new_entry->message = strdup(message);
    if (!new_entry->message) {
        free(new_entry);
        pthread_mutex_unlock(&col->mutex);
        return -4;
    }
    // Add the new entry to the collection
    col->entries[col->count++] = new_entry;
    pthread_mutex_unlock(&col->mutex);
    return 0;
}

// Remove an entry from the collection by timestamp
int collection_remove(collection_t* col, long timestamp) {
    if (!col) {
        return -1;
    }
    pthread_mutex_lock(&col->mutex);
    // Find the index of the entry to remove
    size_t i = 0;
    for (i = 0; i < col->count; i++) {
        if (col->entries[i]->timestamp == timestamp) {
            break;
        }
    }
    // Check if the entry was found
    if (i == col->count) {
        pthread_mutex_unlock(&col->mutex);
        return -2;
    }
    // Remove the entry from the collection
    free(col->entries[i]->message);
    free(col->entries[i]);
    for (size_t j = i; j < col->count - 1; j++) {
        col->entries[j] = col->entries[j + 1];
    }
    col->count--;
    pthread_mutex_unlock(&col->mutex);
    return 0;
}

// Update the priority level of an entry in the collection
int collection_update(collection_t* col, long timestamp, int new_priority_level) {
    if (!col) {
        return -1;
    }
    pthread_mutex_lock(&col->mutex);
    // Find the index of the entry to update
    size_t i = 0;
    for (i = 0; i < col->count; i++) {
        if (col->entries[i]->timestamp == timestamp) {
            break;
        }
    }
    // Check if the entry was found
    if (i == col->count) {
        pthread_mutex_unlock(&col->mutex);
        return -2;
    }
    // Update the priority level of the entry
    col->entries[i]->priority_level = new_priority_level;
    pthread_mutex_unlock(&col->mutex);
    return 0;
}

// Batch update the priority levels of entries within a specified time range
int collection_batch_update(collection_t* col, long start_timestamp, long end_timestamp, int new_priority_level) {
    if (!col) {
        return -1;
    }
    pthread_mutex_lock(&col->mutex);
    // Find the indices of the entries to update
    size_t start_index = 0;
    for (start_index = 0; start_index < col->count; start_index++) {
        if (col->entries[start_index]->timestamp >= start_timestamp) {
            break;
        }
    }
    size_t end_index = col->count - 1;
    for (end_index = col->count - 1; end_index > start_index; end_index--) {
        if (col->entries[end_index]->timestamp <= end_timestamp) {
            break;
        }
    }
    // Check if any entries were found within the specified time range
    if (start_index == col->count || end_index < start_index) {
        pthread_mutex_unlock(&col->mutex);
        return -2;
    }
    // Update the priority levels of the entries
    for (size_t i = start_index; i <= end_index; i++) {
        col->entries[i]->priority_level = new_priority_level;
    }
    pthread_mutex_unlock(&col->mutex);
    return 0;
}

// Iterate over all entries in the collection
void collection_iter(collection_t* col, void (*callback)(entry_t*)) {
    if (!col || !callback) {
        return;
    }
    pthread_mutex_lock(&col->mutex);
    for (size_t i = 0; i < col->count; i++) {
        callback(col->entries[i]);
    }
    pthread_mutex_unlock(&col->mutex);
}

// Free the memory allocated by the collection
void collection_free(collection_t* col) {
    if (!col) {
        return;
    }
    pthread_mutex_lock(&col->mutex);
    for (size_t i = 0; i < col->count; i++) {
        free(col->entries[i]->message);
        free(col->entries[i]);
    }
    free(col->entries);
    pthread_mutex_unlock(&col->mutex);
    pthread_mutex_destroy(&col->mutex);
    free(col);
}
