int init_aes_256_cbc(const unsigned char *password, const unsigned char *salt) {
    // Create a new EVP_CIPHER_CTX object
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        return -1;
    }

    // Set the cipher type and mode
    int rc = EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, password, salt);
    if (rc != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Generate a unique IV for each encryption context
    unsigned char iv[AES_BLOCK_SIZE];
    rc = RAND_bytes(iv, AES_BLOCK_SIZE);
    if (rc != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Store the cipher context and IV in a struct for later use
    Aes256CbcCipherContext *cipher_context = malloc(sizeof(Aes256CbcCipherContext));
    if (cipher_context == NULL) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    cipher_context->ctx = ctx;
    memcpy(cipher_context->iv, iv, AES_BLOCK_SIZE);

    // Return the struct containing the cipher context and IV
    return 0;
}

// Function to encrypt data using an initialized AES-256-CBC cipher
int aes_256_cbc_encrypt(const unsigned char *plaintext, const size_t plaintext_len, const Aes256CbcCipherContext *cipher_context) {
    // Check if the cipher context is valid
    if (cipher_context == NULL || cipher_context->ctx == NULL) {
        return -1;
    }

    // Set the IV for this encryption context
    int rc = EVP_EncryptInit_ex(cipher_context->ctx, NULL, NULL, NULL, cipher_context->iv);
    if (rc != 1) {
        return -1;
    }

    // Encrypt the plaintext using the AES-256-CBC algorithm
    unsigned char *ciphertext = malloc(plaintext_len + AES_BLOCK_SIZE);
    if (ciphertext == NULL) {
        return -1;
    }
    rc = EVP_EncryptUpdate(cipher_context->ctx, ciphertext, plaintext_len, plaintext, plaintext_len);
    if (rc != 1) {
        free(ciphertext);
        return -1;
    }
    rc = EVP_EncryptFinal_ex(cipher_context->ctx, ciphertext + plaintext_len, NULL);
    if (rc != 1) {
        free(ciphertext);
        return -1;
    }

    // Return the encrypted data
    return plaintext_len + AES_BLOCK_SIZE;
}

// Function to decrypt data using an initialized AES-256-CBC cipher
int aes_256_cbc_decrypt(const unsigned char *ciphertext, const size_t ciphertext_len, const Aes256CbcCipherContext *cipher_context) {
    // Check if the cipher context is valid
    if (cipher_context == NULL || cipher_context->ctx == NULL) {
        return -1;
    }

    // Set the IV for this encryption context
    int rc = EVP_DecryptInit_ex(cipher_context->ctx, NULL, NULL, NULL, cipher_context->iv);
    if (rc != 1) {
        return -1;
    }

    // Decrypt the ciphertext using the AES-256-CBC algorithm
    unsigned char *plaintext = malloc(ciphertext_len + AES_BLOCK_SIZE);
    if (plaintext == NULL) {
        return -1;
    }
    rc = EVP_DecryptUpdate(cipher_context->ctx, plaintext, ciphertext_len, ciphertext, ciphertext_len);
    if (rc != 1) {
        free(plaintext);
        return -1;
    }
    rc = EVP_DecryptFinal_ex(cipher_context->ctx, plaintext + ciphertext_len, NULL);
    if (rc != 1) {
        free(plaintext);
        return -1;
    }

    // Return the decrypted data
    return ciphertext_len + AES_BLOCK_SIZE;
}

// Function to clean up an initialized AES-256-CBC cipher context
void aes_256_cbc_cleanup(Aes256CbcCipherContext *cipher_context) {
    // Check if the cipher context is valid
    if (cipher_context == NULL || cipher_context->ctx == NULL) {
        return;
    }

    // Clean up the EVP_CIPHER_CTX object
    EVP_CIPHER_CTX_free(cipher_context->ctx);
    free(cipher_context);
}
