// Define the default theme directory and cache size
#define DEFAULT_THEME_DIR "themes"
#define CACHE_SIZE 1024

// Define the AES-256-CBC cipher parameters
#define AES_KEY_LEN 32
#define AES_BLOCK_LEN 16
#define IV_LEN AES_BLOCK_LEN

// Define the SHA-256 hash algorithm for key derivation
#define HASH_ALG EVP_sha256()

// Define the logging system
#define LOG(format, ...) printf("[%s] " format "\n", __func__, ##__VA_ARGS__)

// Define the theme cache structure
typedef struct {
  char* path;
  unsigned char* data;
  size_t len;
} ThemeCache;

// Initialize a new theme cache instance
ThemeCache* init_cache() {
  ThemeCache* cache = malloc(sizeof(ThemeCache));
  if (!cache) {
    LOG("Failed to allocate memory for theme cache");
    return NULL;
  }
  cache->path = NULL;
  cache->data = NULL;
  cache->len = 0;
  return cache;
}

// Free a theme cache instance
void free_cache(ThemeCache* cache) {
  if (cache) {
    free(cache->path);
    free(cache->data);
    free(cache);
  }
}

// Load a PNG file from the specified path and store it in the theme cache
int load_png(ThemeCache* cache, const char* path) {
  FILE* fp = fopen(path, "rb");
  if (!fp) {
    LOG("Failed to open PNG file: %s", path);
    return -1;
  }
  // Get the file size
  fseek(fp, 0, SEEK_END);
  long len = ftell(fp);
  rewind(fp);
  // Allocate memory for the PNG data
  unsigned char* data = malloc(len);
  if (!data) {
    LOG("Failed to allocate memory for PNG data");
    fclose(fp);
    return -1;
  }
  // Read the PNG data from the file
  size_t read = fread(data, len, 1, fp);
  if (read != 1) {
    LOG("Failed to read PNG data from file: %s", path);
    free(data);
    fclose(fp);
    return -1;
  }
  // Close the file
  fclose(fp);
  // Store the PNG data in the cache
  cache->path = strdup(path);
  cache->data = data;
  cache->len = len;
  return 0;
}

// Generate a unique identifier for a theme instance
char* generate_id(const char* path) {
  // Calculate the SHA-256 hash of the theme file path
  unsigned char hash[SHA256_DIGEST_LENGTH];
  SHA256_CTX ctx;
  SHA256_Init(&ctx);
  SHA256_Update(&ctx, path, strlen(path));
  SHA256_Final(hash, &ctx);
  // Convert the hash to a hexadecimal string
  char* id = malloc(SHA256_DIGEST_LENGTH * 2 + 1);
  if (!id) {
    LOG("Failed to allocate memory for theme ID");
    return NULL;
  }
  for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
    sprintf(id + i * 2, "%02x", hash[i]);
  }
  id[SHA256_DIGEST_LENGTH * 2] = '\0';
  return id;
}

// Initialize a new AES-256-CBC cipher with the given password and IV length
EVP_CIPHER_CTX* init_cipher(const char* password, int iv_len) {
  // Allocate memory for the cipher context
  EVP_CIPHER_CTX* ctx = malloc(sizeof(EVP_CIPHER_CTX));
  if (!ctx) {
    LOG("Failed to allocate memory for cipher context");
    return NULL;
  }
  // Initialize the cipher context with the given password and IV length
  EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, password, iv_len);
  if (!EVP_EncryptUpdate(ctx, NULL, NULL, NULL)) {
    LOG("Failed to initialize cipher context");
    free(ctx);
    return NULL;
  }
  return ctx;
}

// Clean up and disable the AES-256-CBC cipher
void cleanup_cipher(EVP_CIPHER_CTX* ctx) {
  if (ctx) {
    EVP_EncryptFinal_ex(ctx, NULL, NULL);
    EVP_CIPHER_CTX_free(ctx);
  }
}

// Initialize and validate a default theme directory
int init_theme_dir(const char* dir) {
  // Check if the directory exists
  struct stat st;
  if (stat(dir, &st) == -1 || !S_ISDIR(st.st_mode)) {
    LOG("Theme directory does not exist: %s", dir);
    return -1;
  }
  // Check if the directory is writable
  if (access(dir, W_OK) == -1) {
    LOG("Theme directory is not writable: %s", dir);
    return -1;
  }
  return 0;
}

// Initialize and validate a theme cache instance
int init_cache_instance(ThemeCache* cache, const char* path) {
  // Load the PNG file from the specified path
  if (load_png(cache, path) == -1) {
    LOG("Failed to load PNG file: %s", path);
    return -1;
  }
  // Generate a unique identifier for the theme instance
  cache->id = generate_id(path);
  return 0;
}

// Initialize and validate a theme directory and cache instance
int init_theme_instance(const char* dir, const char* path) {
  // Initialize and validate the default theme directory
  if (init_theme_dir(dir) == -1) {
    LOG("Failed to initialize theme directory: %s", dir);
    return -1;
  }
  // Initialize and validate a new theme cache instance
  ThemeCache* cache = init_cache();
  if (!cache) {
    LOG("Failed to allocate memory for theme cache");
    return -1;
  }
  if (init_cache_instance(cache, path) == -1) {
    free_cache(cache);
    return -1;
  }
  // Return the initialized theme cache instance
  return cache;
}

// Clean up and disable a theme cache instance
void cleanup_cache(ThemeCache* cache) {
  if (cache) {
    free(cache->path);
    free(cache->data);
    free(cache);
  }
}

// Initialize and validate a theme instance using the specified password
int init_theme(const char* dir, const char* path, const char* password) {
  // Calculate the key length required for AES-256
  int key_len = EVP_BytesToKey(HASH_ALG, EVP_aes_256_cbc(), NULL, password, strlen(password), 1, NULL, NULL);
  if (key_len <= 0) {
    LOG("Failed to calculate AES key length");
    return -1;
  }
  // Initialize a new AES-256-CBC cipher with the given password and IV length
  EVP_CIPHER_CTX* ctx = init_cipher(password, IV_LEN);
  if (!ctx) {
    LOG("Failed to initialize cipher context");
    return -1;
  }
  // Initialize and validate a new theme cache instance using the specified password
  ThemeCache* cache = init_cache();
  if (!cache) {
    cleanup_cipher(ctx);
    return -1;
  }
  if (init_cache_instance(cache, path) == -1) {
    cleanup_cache(cache);
    cleanup_cipher(ctx);
    return -1;
  }
  // Return the initialized theme cache instance and cipher context
  return cache;
}

// Clean up and disable a theme instance
void cleanup_theme(ThemeCache* cache, EVP_CIPHER_CTX* ctx) {
  if (cache) {
    cleanup_cache(cache);
  }
  if (ctx) {
    cleanup_cipher(ctx);
  }
}
