#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

// Define the structure for an account object
typedef struct {
    int id;
    double balance;
    int num_transactions;
    transaction_t *transactions;
} account_t;

// Define the structure for a transaction item
typedef struct {
    time_t timestamp;
    double amount;
    char category[10];
} transaction_t;

// Define the array of accounts
account_t *accounts = NULL;
int num_accounts = 0;

// Function to add a new account
void add_account(int id, double balance) {
    // Allocate memory for the new account object
    account_t *new_account = malloc(sizeof(account_t));
    if (new_account == NULL) {
        perror("Failed to allocate memory for new account");
        return;
    }

    // Initialize the new account object
    new_account->id = id;
    new_account->balance = balance;
    new_account->num_transactions = 0;
    new_account->transactions = NULL;

    // Add the new account to the array of accounts
    if (num_accounts == 0) {
        accounts = malloc(sizeof(account_t));
        if (accounts == NULL) {
            perror("Failed to allocate memory for accounts");
            return;
        }
    } else {
        accounts = realloc(accounts, sizeof(account_t) * (num_accounts + 1));
        if (accounts == NULL) {
            perror("Failed to reallocate memory for accounts");
            return;
        }
    }
    accounts[num_accounts] = new_account;
    num_accounts++;
}

// Function to add a transaction to an account
void add_transaction(int id, time_t timestamp, double amount, char category[]) {
    // Find the account object corresponding to the given ID
    int i;
    for (i = 0; i < num_accounts; i++) {
        if (accounts[i]->id == id) {
            break;
        }
    }
    if (i == num_accounts) {
        printf("Account with ID %d not found\n", id);
        return;
    }

    // Allocate memory for the new transaction item
    transaction_t *new_transaction = malloc(sizeof(transaction_t));
    if (new_transaction == NULL) {
        perror("Failed to allocate memory for new transaction");
        return;
    }

    // Initialize the new transaction item
    new_transaction->timestamp = timestamp;
    new_transaction->amount = amount;
    strcpy(new_transaction->category, category);

    // Add the new transaction to the account's transaction list
    if (accounts[i]->num_transactions == 0) {
        accounts[i]->transactions = malloc(sizeof(transaction_t));
        if (accounts[i]->transactions == NULL) {
            perror("Failed to allocate memory for transactions");
            return;
        }
    } else {
        accounts[i]->transactions = realloc(accounts[i]->transactions, sizeof(transaction_t) * (accounts[i]->num_transactions + 1));
        if (accounts[i]->transactions == NULL) {
            perror("Failed to reallocate memory for transactions");
            return;
        }
    }
    accounts[i]->transactions[accounts[i]->num_transactions] = new_transaction;
    accounts[i]->num_transactions++;
}

// Function to update the balance of an account
void update_balance(int id, double amount) {
    // Find the account object corresponding to the given ID
    int i;
    for (i = 0; i < num_accounts; i++) {
        if (accounts[i]->id == id) {
            break;
        }
    }
    if (i == num_accounts) {
        printf("Account with ID %d not found\n", id);
        return;
    }

    // Update the balance of the account
    accounts[i]->balance += amount;
}

// Function to print the balance of an account
void print_balance(int id) {
    // Find the account object corresponding to the given ID
    int i;
    for (i = 0; i < num_accounts; i++) {
        if (accounts[i]->id == id) {
            break;
        }
    }
    if (i == num_accounts) {
        printf("Account with ID %d not found\n", id);
        return;
    }

    // Print the balance of the account
    printf("Balance for account %d: %.2f\n", accounts[i]->id, accounts[i]->balance);
}

// Function to print all transactions for an account
void print_transactions(int id) {
    // Find the account object corresponding to the given ID
    int i;
    for (i = 0; i < num_accounts; i++) {
        if (accounts[i]->id == id) {
            break;
        }
    }
    if (i == num_accounts) {
        printf("Account with ID %d not found\n", id);
        return;
    }

    // Print all transactions for the account
    int j;
    for (j = 0; j < accounts[i]->num_transactions; j++) {
        transaction_t *transaction = &accounts[i]->transactions[j];
        printf("Transaction %d: %.2f on %s (%s)\n", j, transaction->amount, ctime(&transaction->timestamp), transaction->category);
    }
}

// Function to handle API timeouts gracefully
void handle_api_timeout(int api_status) {
    if (api_status == -1) {
        printf("API request timed out. Retrying...\n");
        sleep(5); // Sleep for 5 seconds before retrying the API request
    } else {
        perror("Failed to handle API timeout");
    }
}

// Function to log transactions to a persistent audit file
void log_transactions(int id, transaction_t *transaction) {
    // Open the audit file in append mode
    int fd = open("audit.log", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd == -1) {
        perror("Failed to open audit file");
        return;
    }

    // Write the transaction data to the audit file
    char buffer[256];
    sprintf(buffer, "%d %ld %.2f %s\n", id, transaction->timestamp, transaction->amount, transaction->category);
    write(fd, buffer, strlen(buffer));

    // Close the audit file
    close(fd);
}

// Function to handle disk I/O efficiency in transaction logging
void log_transactions_efficiently(int id, transaction_t *transaction) {
    // Open the audit file in append mode
    int fd = open("audit.log", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd == -1) {
        perror("Failed to open audit file");
        return;
    }

    // Write the transaction data to the audit file in batches of 100 transactions
    int i;
    for (i = 0; i < accounts[id]->num_transactions; i += 100) {
        char buffer[256];
        sprintf(buffer, "%d %ld %.2f %s\n", id, transaction->timestamp, transaction->amount, transaction->category);
        write(fd, buffer, strlen(buffer));
    }

    // Close the audit file
    close(fd);
}

// Function to handle potential memory leaks and excessive resource consumption
void manage_memory() {
    // Check for memory leaks using valgrind
    system("valgrind --leak-check=full ./trading_system");

    // Free any unused memory
    free(accounts);
}

// Function to handle unexpected failures, such as API errors or disk I/O issues
void handle_errors() {
    // Check for API errors using cURL
    system("curl -I http://example.com");

    // Check for disk I/O issues using df
    system("df -h");
}

