// Custom class for generating random integers within a specified range
class RandomInteger {
    private:
        int min;
        int max;

    public:
        // Constructor to initialize the minimum and maximum values
        RandomInteger(int min, int max) {
            this->min = min;
            this->max = max;
        }

        // Method to generate a random integer within the specified range
        int getRandomInt() {
            return rand() % (this->max - this->min + 1) + this->min;
        }

        // Method to generate a random floating-point number within the specified range
        float getRandomFloat() {
            return ((float)rand() / RAND_MAX) * (this->max - this->min) + this->min;
        }

        // Method to display the range of values
        void printRange() {
            printf("Minimum value: %d\n", this->min);
            printf("Maximum value: %d\n", this->max);
        }
};

