void manageDatabaseTable(int numRecords, int keySize, int offsetSize) {
    // Allocate memory for the database table
    Record* records = (Record*)malloc(numRecords * sizeof(Record));
    if (!records) {
        printf("Error: Memory allocation failed\n");
        return;
    }

    // Initialize the database table with random values
    RandomInteger randInt(0, 100);
    for (int i = 0; i < numRecords; i++) {
        records[i].key = randInt.getRandomInt();
        records[i].offset = randInt.getRandomInt() * offsetSize;
        records[i].value = randInt.getRandomFloat();
    }

    // Print the database table
    printf("Database Table:\n");
    for (int i = 0; i < numRecords; i++) {
        printf("%d | %d | %.2f\n", records[i].key, records[i].offset, records[i].value);
    }

    // Free the memory allocated for the database table
    free(records);
}

