} Node;

// Function to initialize and populate the linked list with nodes
void init_list(Node** head, int min_key, int max_key) {
    // Allocate memory for the first node in the list
    *head = malloc(sizeof(Node));
    assert(*head != NULL);

    // Initialize the first node and set it as the current node
    (*head)->key = min_key;
    Node* curr = *head;

    // Loop through the range of keys to populate the list
    for (int i = min_key + 1; i <= max_key; i++) {
        // Allocate memory for a new node and set its key value
        Node* new_node = malloc(sizeof(Node));
        assert(new_node != NULL);
        new_node->key = i;

        // Check if the key is a duplicate of an existing node in the list
        bool duplicate = false;
        for (Node* temp = *head; temp != NULL; temp = temp->next) {
            if (temp->key == i) {
                duplicate = true;
                break;
            }
        }

        // If the key is not a duplicate, add it to the list
        if (!duplicate) {
            curr->next = new_node;
            curr = curr->next;
        }
    }
}

// Function to traverse the linked list and print the keys in clockwise order starting from a given node
void traverse_list(Node* start) {
    // Set the current node as the starting node
    Node* curr = start;

    // Loop through the list until we reach the end
    while (curr != NULL) {
        // Print the key value of the current node
        printf("%d ", curr->key);

        // Move to the next node in the list
        curr = curr->next;
    }
}

// Function to free the memory allocated for the linked list
void free_list(Node* head) {
    // Loop through the list and free each node's memory
    while (head != NULL) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }
}
