// Define the entry structure
typedef struct {
    char* name;
    int age;
} Entry;

// Define the list structure
typedef struct {
    Entry** entries;
    size_t capacity;
    size_t count;
} List;

// Initialize a new list with a given capacity
List* list_init(size_t capacity) {
    List* list = malloc(sizeof(List));
    assert(list != NULL);

    list->entries = malloc(capacity * sizeof(Entry*));
    assert(list->entries != NULL);

    list->capacity = capacity;
    list->count = 0;

    return list;
}

// Add a new entry to the list
void list_add(List* list, char* name, int age) {
    assert(list != NULL);
    assert(name != NULL);

    // Check if the list is full
    if (list->count == list->capacity) {
        // Double the capacity of the list
        list->capacity *= 2;
        list->entries = realloc(list->entries, list->capacity * sizeof(Entry*));
        assert(list->entries != NULL);
    }

    // Create a new entry and add it to the list
    Entry* entry = malloc(sizeof(Entry));
    assert(entry != NULL);

    entry->name = strdup(name);
    entry->age = age;

    list->entries[list->count++] = entry;
}

// Update the age of an existing entry in the list by name
void list_update(List* list, char* name, int age) {
    assert(list != NULL);
    assert(name != NULL);

    // Find the index of the entry with the given name
    size_t i;
    for (i = 0; i < list->count; i++) {
        if (strcmp(list->entries[i]->name, name) == 0) {
            break;
        }
    }

    // Check if the entry was found
    if (i == list->count) {
        printf("Entry not found\n");
        return;
    }

    // Update the age of the entry
    list->entries[i]->age = age;
}

// Delete an entry from the list by name
void list_delete(List* list, char* name) {
    assert(list != NULL);
    assert(name != NULL);

    // Find the index of the entry with the given name
    size_t i;
    for (i = 0; i < list->count; i++) {
        if (strcmp(list->entries[i]->name, name) == 0) {
            break;
        }
    }

    // Check if the entry was found
    if (i == list->count) {
        printf("Entry not found\n");
        return;
    }

    // Shift all entries after the deleted entry one position to the left
    for (size_t j = i; j < list->count - 1; j++) {
        list->entries[j] = list->entries[j + 1];
    }

    // Decrement the count of entries in the list
    list->count--;
}

// Free the memory allocated for the list and its entries
void list_free(List* list) {
    assert(list != NULL);

    // Free the memory allocated for each entry
    for (size_t i = 0; i < list->count; i++) {
        free(list->entries[i]);
    }

    // Free the memory allocated for the list itself
    free(list->entries);
    free(list);
}
