// Define custom record structure
typedef struct {
    int value;
} record;

// Define memory pool for managing allocations
struct mem_pool {
    size_t size;
    void* data;
};

// Function to manage memory efficiently for multiple components under strict resource constraints and performance considerations
void manage_memory(size_t num_records, int key_range, struct mem_pool* pool) {
    // Allocate memory for offset array
    long* offsets = (long*)malloc(num_records * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offset array\n");
        return;
    }

    // Allocate memory for key array
    int* keys = (int*)malloc(num_records * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Failed to allocate memory for key array\n");
        free(offsets);
        return;
    }

    // Allocate memory for record structures
    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for record structures\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize offset array with random values within specified range
    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = rand() % key_range;
    }

    // Initialize key array with unique values
    for (size_t i = 0; i < num_records; ++i) {
        keys[i] = i + 1;
    }

    // Initialize record structures with random values within specified range
    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = rand() % key_range;
    }

    // Integrate with external logging system to track memory usage and initialization details
    printf("Memory usage: %lu bytes\n", sizeof(offsets) + sizeof(keys) + sizeof(records));
    printf("Initialization details:\n");
    for (size_t i = 0; i < num_records; ++i) {
        printf("\toffset[%zu] = %ld\n", i, offsets[i]);
        printf("\tkey[%zu] = %d\n", i, keys[i]);
        printf("\trecord[%zu].value = %d\n", i, records[i].value);
    }

    // Validate initialized record values to prevent overflow errors in subsequent operations
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i].value > key_range) {
            fprintf(stderr, "Validation failed: record value exceeds upper limit\n");
            free(offsets);
            free(keys);
            free(records);
            return;
        }
    }

    // Optimize memory usage and access patterns by using a memory pool to manage allocations effectively
    struct mem_pool* pool = (struct mem_pool*)malloc(sizeof(struct mem_pool));
    if (!pool) {
        fprintf(stderr, "Failed to allocate memory for memory pool\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }
    pool->size = num_records * sizeof(record);
    pool->data = records;

    // Ensure that all memory allocations and deallocations are meticulously recorded and handled gracefully in case of out-of-memory conditions
    atexit(free_pool);

    return;
}

// Function to free memory pool
void free_pool() {
    if (pool) {
        free(pool->data);
        free(pool);
    }
}
