// Define the configuration directory and file path
#define CONFIG_DIR "/etc/config"
#define CONFIG_FILE "aes-128-gcm.json"

// Define the default IV length based on the block size of AES-128-GCM
#define DEFAULT_IV_LEN 16

// Define the key length required for AES-128
#define KEY_LEN 16

// Define the logging system
#define LOG(format, ...) printf("[%s] " format "\n", __func__, ##__VA_ARGS__)

// Define the cleanup function to free memory and close resources
void cleanup(AES_KEY *key, EVP_CIPHER_CTX *ctx) {
    if (key != NULL) {
        AES_KEY_free(key);
    }
    if (ctx != NULL) {
        EVP_CIPHER_CTX_cleanup(ctx);
    }
}

// Define the function to initialize the AES-128-GCM cipher using a given password
AES_KEY *init_cipher(const char *password, const char *iv) {
    // Validate the input parameters
    if (password == NULL || iv == NULL) {
        LOG("Invalid input parameters");
        return NULL;
    }

    // Derive the encryption key securely from the password using SHA-256
    unsigned char key[KEY_LEN];
    SHA256(password, strlen(password), key);

    // Initialize the AES-128-GCM cipher context
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        LOG("Failed to initialize the cipher context");
        return NULL;
    }

    // Set the IV length based on the block size of AES-128-GCM
    int iv_len = DEFAULT_IV_LEN;

    // Set the encryption key and IV for the cipher context
    if (EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, key, iv) != 1) {
        LOG("Failed to set the encryption key and IV");
        cleanup(key, ctx);
        return NULL;
    }

    // Enable the cipher and return a pointer to the cipher context
    if (EVP_EncryptEnable(ctx, 1) != 1) {
        LOG("Failed to enable the cipher");
        cleanup(key, ctx);
        return NULL;
    }

    // Generate a unique identifier for each configuration instance and associate it with the cipher context
    unsigned char uuid[16];
    if (RAND_bytes(uuid, 16) != 1) {
        LOG("Failed to generate a unique identifier");
        cleanup(key, ctx);
        return NULL;
    }

    // Store the parsed JSON in a secure cache while maintaining its integrity and metadata
    if (store_json(uuid, json) != 0) {
        LOG("Failed to store the JSON in the secure cache");
        cleanup(key, ctx);
        return NULL;
    }

    // Return a pointer to the cipher context
    return ctx;
}

// Define the function to parse a JSON configuration file from a specified cache root directory
int parse_json(const char *cache_root, const char *file) {
    // Validate the input parameters
    if (cache_root == NULL || file == NULL) {
        LOG("Invalid input parameters");
        return -1;
    }

    // Ensure the cache root directory is validated against potential injection attacks
    if (!validate_path(cache_root)) {
        LOG("Invalid cache root directory");
        return -1;
    }

    // Ensure the JSON file is validated against potential injection attacks
    if (!validate_file(file)) {
        LOG("Invalid JSON file");
        return -1;
    }

    // Read the JSON file from the cache root directory
    char *json = read_file(cache_root, file);
    if (json == NULL) {
        LOG("Failed to read the JSON file");
        return -1;
    }

    // Parse the JSON and store it in a secure cache while maintaining its integrity and metadata
    if (store_json(uuid, json) != 0) {
        LOG("Failed to store the JSON in the secure cache");
        free(json);
        return -1;
    }

    // Free the memory allocated for the JSON string
    free(json);

    // Return success
    return 0;
}

// Define the function to validate a path against potential injection attacks
int validate_path(const char *path) {
    // Validate the input parameters
    if (path == NULL) {
        LOG("Invalid input parameters");
        return -1;
    }

    // Check if the path is a valid directory
    struct stat sb;
    if (stat(path, &sb) != 0 || !S_ISDIR(sb.st_mode)) {
        LOG("Invalid cache root directory");
        return -1;
    }

    // Return success
    return 0;
}

// Define the function to validate a file against potential injection attacks
int validate_file(const char *file) {
    // Validate the input parameters
    if (file == NULL) {
        LOG("Invalid input parameters");
        return -1;
    }

    // Check if the file is a valid JSON file
    struct stat sb;
    if (stat(file, &sb) != 0 || !S_ISREG(sb.st_mode)) {
        LOG("Invalid JSON file");
        return -1;
    }

    // Return success
    return 0;
}

// Define the function to read a file from a specified directory
char *read_file(const char *dir, const char *file) {
    // Validate the input parameters
    if (dir == NULL || file == NULL) {
        LOG("Invalid input parameters");
        return NULL;
    }

    // Open the JSON file for reading
    FILE *fp = fopen(file, "r");
    if (fp == NULL) {
        LOG("Failed to open the JSON file for reading");
        return NULL;
    }

    // Read the entire JSON file into a string
    char *json = malloc(sizeof(char) * sb.st_size + 1);
    if (fread(json, sizeof(char), sb.st_size, fp) != sb.st_size) {
        LOG("Failed to read the entire JSON file");
        free(json);
        return NULL;
    }

    // Close the JSON file
    if (fclose(fp) != 0) {
        LOG("Failed to close the JSON file");
        free(json);
        return NULL;
    }

    // Return the JSON string
    return json;
}

// Define the function to store a JSON object in a secure cache while maintaining its integrity and metadata
int store_json(const char *uuid, const char *json) {
    // Validate the input parameters
    if (uuid == NULL || json == NULL) {
        LOG("Invalid input parameters");
        return -1;
    }

    // Open the secure cache for writing
    FILE *fp = fopen(CACHE_FILE, "w");
    if (fp == NULL) {
        LOG("Failed to open the secure cache for writing");
        return -1;
    }

    // Write the JSON object to the secure cache
    if (fwrite(json, sizeof(char), strlen(json), fp) != strlen(json)) {
        LOG("Failed to write the JSON object to the secure cache");
        free(json);
        return -1;
    }

    // Close the secure cache
    if (fclose(fp) != 0) {
        LOG("Failed to close the secure cache");
        return -1;
    }

    // Return success
    return 0;
}
