            // Compute the average of the last three valid measurements for this file
            int num_elements = avgs[i].num_files < AVG_WINDOW_SIZE ? avgs[i].num_files : AVG_WINDOW_SIZE;
            float* elements = (float*)malloc(sizeof(float) * num_elements);
            for (int j = 0; j < num_elements; j++) {
                elements[j] = avgs[i].avgs[j];
            }
            float new_avg = compute_avg(num_elements, elements);
            free(elements);

            // Append the new average to the sequence for this file
            avgs[i].avgs[avgs[i].num_files++] = new_avg;
        }

        fclose(fp);
    }

    // Clean up resources and exit
