// Define the record structure
typedef struct {
    int key;
    double value;
    char name[16];
} Record;

// Define the container structure
typedef struct {
    Record* records;
    size_t capacity;
    size_t count;
} Container;

// Initialize the container with a given maximum memory limit and key range
void initContainer(Container* container, size_t maxMemoryLimit, int minKey, int maxKey) {
    // Allocate memory for the records array
    container->records = (Record*)malloc(maxMemoryLimit * sizeof(Record));
    if (!container->records) {
        fprintf(stderr, "Error: Failed to allocate memory for records\n");
        exit(1);
    }

    // Initialize the capacity and count variables
    container->capacity = maxMemoryLimit;
    container->count = 0;

    // Generate random keys within the specified range
    srand(time(NULL));
    for (int i = 0; i < container->capacity; i++) {
        int key = rand() % (maxKey - minKey + 1) + minKey;
        while (keyExists(container, key)) {
            // Retry with a new random key if the generated key already exists in the container
            key = rand() % (maxKey - minKey + 1) + minKey;
        }
        container->records[i].key = key;
    }
}

// Add a record to the container, returning true on success and false otherwise
bool addRecord(Container* container, int key, double value, char* name) {
    // Check if the memory limit has been reached
    if (container->count == container->capacity) {
        return false;
    }

    // Generate a random key within the specified range if none is provided
    if (key < 0) {
        srand(time(NULL));
        int newKey = rand() % (maxKey - minKey + 1) + minKey;
        while (keyExists(container, newKey)) {
            // Retry with a new random key if the generated key already exists in the container
            newKey = rand() % (maxKey - minKey + 1) + minKey;
        }
        key = newKey;
    }

    // Check if the key already exists in the container
    if (keyExists(container, key)) {
        return false;
    }

    // Add the record to the container
    container->records[container->count].key = key;
    container->records[container->count].value = value;
    strncpy(container->records[container->count].name, name, 16);
    container->count++;

    return true;
}

// Check if a key already exists in the container
bool keyExists(Container* container, int key) {
    for (int i = 0; i < container->count; i++) {
        if (container->records[i].key == key) {
            return true;
        }
    }
    return false;
}

// Free the memory allocated by the container
void freeContainer(Container* container) {
    free(container->records);
}
```
