#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

// Define the structure for an item in the collection
typedef struct {
    char buffer[10]; // Buffer to store the string representation of the identifier
    int id; // Unique identifier for each item
    double value; // Double value associated with each item
} Item;

// Define a linked list node to represent an item in the collection
typedef struct Node {
    Item *item; // Pointer to the item structure
    struct Node *next; // Pointer to the next node in the linked list
} Node;

// Define a global variable to store the head of the linked list
Node *head = NULL;

// Function to dynamically allocate memory for an item and initialize it with a unique identifier and string representation
Item* create_item(int id) {
    Item *item = (Item*) malloc(sizeof(Item));
    if (!item) {
        printf("Error: Failed to allocate memory for the item\n");
        return NULL;
    }
    item->id = id;
    sprintf(item->buffer, "%d", id); // Convert the integer identifier to a string and store it in the buffer
    item->value = 0.0; // Initialize the double value to 0.0
    return item;
}

// Function to add an item to the linked list
void add_item(Item *item) {
    Node *new_node = (Node*) malloc(sizeof(Node));
    if (!new_node) {
        printf("Error: Failed to allocate memory for the new node\n");
        return;
    }
    new_node->item = item;
    new_node->next = head;
    head = new_node;
}

// Function to safely free all allocated memory
void free_all() {
    Node *current = head;
    while (current != NULL) {
        Item *item = current->item;
        free(item);
        current = current->next;
    }
    head = NULL;
}

// Function to handle potential errors and maintain thread safety if used in a multi-threaded environment
void manage_collection() {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // Initialize the mutex variable
    pthread_mutex_lock(&mutex); // Lock the mutex to prevent race conditions and synchronization issues
    if (head == NULL) { // If the linked list is empty, create a new item with a unique identifier
        Item *item = create_item(1);
        add_item(item);
    } else { // Otherwise, find the last node in the linked list and increment its identifier by 1
        Node *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        Item *item = create_item(current->item->id + 1);
        add_item(item);
    }
    pthread_mutex_unlock(&mutex); // Unlock the mutex to allow other threads to access the linked list
