    // Find the index of the record with the given key
    size_t i = 0;
    while (i < container->count && container->records[i].key != key) {
        i++;
    }

    // If the record was found, remove it from the container
    if (i < container->count) {
        container->count--;
        for (size_t j = i; j < container->count; j++) {
            container->records[j] = container->records[j + 1];
