// Define session structure
typedef struct Session {
    int user_id;
    time_t start_time;
    char* ip_address;
    enum SessionState state;
} Session;

// Define session state enumeration
enum SessionState { ACTIVE, INACTIVE };

// Define session list data structure
typedef struct SessionList {
    int size;
    Session** sessions;
} SessionList;

// Define session cleanup function
void session_cleanup(SessionList* session_list) {
    // Iterate through sessions and remove inactive ones
    for (int i = 0; i < session_list->size; i++) {
        if (session_list->sessions[i]->state == INACTIVE) {
            free(session_list->sessions[i]);
            session_list->sessions[i] = NULL;
        }
    }
}

// Define session addition function
void add_session(SessionList* session_list, int user_id, time_t start_time, char* ip_address) {
    // Allocate memory for new session
    Session* new_session = (Session*)malloc(sizeof(Session));
    if (!new_session) {
        printf("Error: Failed to allocate memory for new session\n");
        return;
    }

    // Initialize session fields
    new_session->user_id = user_id;
    new_session->start_time = start_time;
    new_session->ip_address = ip_address;
    new_session->state = ACTIVE;

    // Add session to list
    session_list->sessions[session_list->size++] = new_session;
}

// Define session retrieval function
Session* get_session(SessionList* session_list, int user_id) {
    // Iterate through sessions and find matching user ID
    for (int i = 0; i < session_list->size; i++) {
        if (session_list->sessions[i]->user_id == user_id) {
            return session_list->sessions[i];
        }
    }

    // Return NULL if no matching session found
    return NULL;
}

// Define session deletion function
void delete_session(SessionList* session_list, int user_id) {
    // Find and remove session with matching user ID
    for (int i = 0; i < session_list->size; i++) {
        if (session_list->sessions[i]->user_id == user_id) {
            free(session_list->sessions[i]);
            session_list->sessions[i] = NULL;
            return;
        }
    }
}

// Define session state update function
void update_session_state(SessionList* session_list, int user_id, enum SessionState new_state) {
    // Find and update session with matching user ID
    for (int i = 0; i < session_list->size; i++) {
        if (session_list->sessions[i]->user_id == user_id) {
            session_list->sessions[i]->state = new_state;
            return;
        }
    }
}

// Define periodic session cleanup function
void periodic_cleanup(SessionList* session_list) {
    // Call session cleanup function every 10 minutes
    while (1) {
        sleep(600);
        session_cleanup(session_list);
    }
}

// Define main function for testing
int main() {
    // Initialize session list
    SessionList* session_list = (SessionList*)malloc(sizeof(SessionList));
    session_list->size = 0;
    session_list->sessions = NULL;

    // Start periodic cleanup thread
    pthread_t cleanup_thread;
    pthread_create(&cleanup_thread, NULL, &periodic_cleanup, (void*)session_list);

    // Add sessions to list
    add_session(session_list, 1234567890, time(NULL), "192.168.1.1");
    add_session(session_list, 9876543210, time(NULL), "192.168.1.2");

    // Retrieve and update sessions
    Session* session = get_session(session_list, 1234567890);
    if (session) {
        printf("Session found: %d\n", session->user_id);
        update_session_state(session_list, 1234567890, INACTIVE);
    } else {
        printf("No matching session found\n");
    }

    // Delete sessions from list
    delete_session(session_list, 9876543210);

    // Clean up resources and exit
    pthread_join(cleanup_thread, NULL);
    free(session_list->sessions);
    free(session_list);
    return 0;
}
