            insert_transaction(&filtered_head, current->transaction);
        }

        // Update the current node pointer
        current = current->next;
    }
}

// Define a function to remove outdated entries from the linked list
void prune_transactions(node_t **head) {
    // Initialize the pruned transaction list
    node_t *pruned_head = NULL;

