['```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

// Define the struct for the record
struct record {
    int value;
    char* key;
};

// Define the struct for the data point
struct data_point {
    long offset;
    int key;
    struct record* record;
};

// Define the hash table for quick lookups
struct hash_table {
    struct data_point** points;
    size_t capacity;
    size_t size;
};

// Initialize the hash table with a given capacity
void init_hash_table(struct hash_table* table, size_t capacity) {
    table->points = malloc(capacity * sizeof(struct data_point*));
    if (table->points == NULL) {
        printf("Error: Failed to allocate memory for the hash table\n");
        exit(1);
    }
    table->capacity = capacity;
    table->size = 0;
}

// Insert a new data point into the hash table
void insert_data_point(struct hash_table* table, long offset, int key, struct record* record) {
    // Check if the hash table is full
    if (table->size == table->capacity) {
        printf("Error: The hash table is full\n");
        exit(1);
    }

    // Allocate memory for the new data point
    struct data_point* new_point = malloc(sizeof(struct data_point));
    if (new_point == NULL) {
        printf("Error: Failed to allocate memory for the new data point\n");
        exit(1);
    }

    // Set the values of the new data point
    new_point->offset = offset;
    new_point->key = key;
    new_point->record = record;

    // Insert the new data point into the hash table
    size_t index = hash(new_point->key) % table->capacity;
    while (table->points[index] != NULL && table->points[index]->key != new_point->key) {
        index = (index + 1) % table->capacity;
    }
    table->points[index] = new_point;
    table->size++;
}

// Delete a data point from the hash table
void delete_data_point(struct hash_table* table, int key) {
    // Find the index of the data point to be deleted
    size_t index = hash(key) % table->capacity;
    while (table->points[index] != NULL && table->points[index]->key != key) {
        index = (index + 1) % table->capacity;
    }

    // Check if the data point was found
    if (table->points[index] == NULL) {
        printf("Error: The data point with key %d does not exist\n", key);
        exit(1);
    }

    // Delete the data point from the hash table
    free(table->points[index]);
    table->size--;
}

// Look up a data point in the hash table by its key
struct data_point* lookup_data_point(struct hash_table* table, int key) {
    // Find the index of the data point to be looked up
    size_t index = hash(key) % table->capacity;
    while (table->points[index] != NULL && table->points[index]->key != key) {
        index = (index + 1) % table->capacity;
    }

