void handle_sigint(int signum) {
    printf("Received SIGINT, terminating all child processes...\n");
    for (int i = 0; i < MAX_NUM_FILES; i++) {
        if (waitpid(-1, NULL, WNOHANG) > 0) {
            printf("Child process %d terminated successfully.\n", i);
        } else {
