        char *filename = strtok(commands[num_files].command, " ");
        if (filename == NULL) {
            printf("Error: invalid command format\n");
            continue;
        }
        strcpy(filenames[num_files], filename);
        num_files++;
    }

    // Parse the commands and file names to ensure they are valid
    for (int i = 0; i < num_files; i++) {
        char *command = commands[i].command;
        if (strlen(command) == 0 || strchr(command, ' ') == NULL) {
            printf("Error: invalid command format\n");
            continue;
        }
        char *filename = filenames[i];
        if (access(filename, R_OK) == -1) {
            printf("Error: file not found or permission denied\n");
            continue;
        }
    }

    // Start the child processes to execute the commands in parallel
    for (int i = 0; i < num_files; i++) {
        char *command = commands[i].command;
        char *filename = filenames[i];
        if (fork() == 0) {
            // Child process: execute the command and exit
            int status = system(command);
            printf("Child process %d exited with status %d\n", i, status);
            exit(status);
        } else {
            // Parent process: wait for the child process to terminate
            if (waitpid(-1, NULL, WNOHANG) > 0) {
                printf("Child process %d terminated successfully.\n", i);
            } else {
                printf("Error waiting for child process %d: %s\n", i, strerror(errno));
            }
        }
    }

    // Wait for all child processes to terminate before exiting
    for (int i = 0; i < num_files; i++) {
        if (waitpid(-1, NULL, WNOHANG) > 0) {
            printf("Child process %d terminated successfully.\n", i);
        } else {
            printf("Error waiting for child process %d: %s\n", i, strerror(errno));
        }
    }

    return 0;
}
