// Define the data structure for a record in the doubly linked list
typedef struct Record {
    double value;
    char *string;
    int identifier;
    unsigned long long timestamp;
    float precision_level;
} Record;

// Define the data structure for the doubly linked list
typedef struct ListNode {
    Record *record;
    struct ListNode *prev, *next;
} ListNode;

// Define the hash table for quick key-based lookups
typedef struct HashTable {
    int size;
    ListNode **buckets;
} HashTable;

// Define the data structure for the two arrays
typedef struct Array {
    int length;
    Record *records;
} Array;

// Define the function to initialize and manage the doubly linked list
void init_list(ListNode **head) {
    *head = NULL;
}

void insert_record(ListNode **head, Record *record) {
    ListNode *new_node = malloc(sizeof(ListNode));
    new_node->record = record;
    new_node->prev = NULL;
    new_node->next = *head;
    if (*head != NULL) {
        (*head)->prev = new_node;
    }
    *head = new_node;
}

void delete_record(ListNode **head, Record *record) {
    ListNode *current = *head;
    while (current != NULL && current->record != record) {
        current = current->next;
    }
    if (current == NULL) {
        return;
    }
    if (current->prev != NULL) {
        current->prev->next = current->next;
    } else {
        *head = current->next;
    }
    if (current->next != NULL) {
        current->next->prev = current->prev;
    }
    free(current);
}

void traverse_list(ListNode **head, void (*visit)(Record *)) {
    ListNode *current = *head;
    while (current != NULL) {
        visit(current->record);
        current = current->next;
    }
}

// Define the function to initialize and manage the hash table
void init_hash_table(HashTable **htable, int size) {
    *htable = malloc(sizeof(HashTable));
    (*htable)->size = size;
    (*htable)->buckets = calloc(size, sizeof(ListNode *));
}

void insert_into_hash_table(HashTable **htable, Record *record) {
    int index = record->identifier % (*htable)->size;
    ListNode *new_node = malloc(sizeof(ListNode));
    new_node->record = record;
    new_node->prev = NULL;
    new_node->next = (*htable)->buckets[index];
    if ((*htable)->buckets[index] != NULL) {
        (*htable)->buckets[index]->prev = new_node;
    }
    (*htable)->buckets[index] = new_node;
}

void delete_from_hash_table(HashTable **htable, Record *record) {
    int index = record->identifier % (*htable)->size;
    ListNode *current = (*htable)->buckets[index];
    while (current != NULL && current->record != record) {
        current = current->next;
    }
    if (current == NULL) {
        return;
    }
    if (current->prev != NULL) {
        current->prev->next = current->next;
    } else {
        (*htable)->buckets[index] = current->next;
    }
    if (current->next != NULL) {
        current->next->prev = current->prev;
    }
    free(current);
}

void traverse_hash_table(HashTable **htable, void (*visit)(Record *)) {
    for (int i = 0; i < (*htable)->size; i++) {
        ListNode *current = (*htable)->buckets[i];
        while (current != NULL) {
            visit(current->record);
            current = current->next;
        }
    }
}

// Define the function to initialize and manage the two arrays
void init_arrays(Array **array1, Array **array2) {
    *array1 = malloc(sizeof(Array));
    (*array1)->length = 0;
    (*array1)->records = NULL;
    *array2 = malloc(sizeof(Array));
    (*array2)->length = 0;
    (*array2)->records = NULL;
}

void insert_into_arrays(Array **array1, Array **array2, Record *record) {
    if ((*array1)->length == 0) {
        (*array1)->records = malloc(sizeof(Record));
        (*array1)->records[0] = record;
        (*array1)->length++;
    } else {
        (*array1)->records = realloc((*array1)->records, ((*array1)->length + 1) * sizeof(Record));
        (*array1)->records[(*array1)->length] = record;
        (*array1)->length++;
    }
    if ((*array2)->length == 0) {
        (*array2)->records = malloc(sizeof(Record));
        (*array2)->records[0] = record;
        (*array2)->length++;
    } else {
        (*array2)->records = realloc((*array2)->records, ((*array2)->length + 1) * sizeof(Record));
        (*array2)->records[(*array2)->length] = record;
        (*array2)->length++;
    }
}

void delete_from_arrays(Array **array1, Array **array2, Record *record) {
    int index1 = -1, index2 = -1;
    for (int i = 0; i < (*array1)->length; i++) {
        if ((*array1)->records[i] == record) {
            index1 = i;
            break;
        }
    }
    for (int i = 0; i < (*array2)->length; i++) {
        if ((*array2)->records[i] == record) {
            index2 = i;
            break;
        }
    }
    if (index1 != -1 && index2 != -1) {
        for (int i = index1 + 1; i < (*array1)->length; i++) {
            (*array1)->records[i - 1] = (*array1)->records[i];
        }
        (*array1)->length--;
        for (int i = index2 + 1; i < (*array2)->length; i++) {
            (*array2)->records[i - 1] = (*array2)->records[i];
        }
        (*array2)->length--;
    }
}

void traverse_arrays(Array **array1, Array **array2, void (*visit)(Record *)) {
    for (int i = 0; i < (*array1)->length; i++) {
        visit((*array1)->records[i]);
    }
    for (int i = 0; i < (*array2)->length; i++) {
        visit((*array2)->records[i]);
    }
}

