// Define the record structure
typedef struct {
    int key;
    double data;
    struct record *next;
} record_t;

// Define the hash table structure
typedef struct {
    int size;
    record_t **table;
} hash_table_t;

// Define the doubly-linked list structure
typedef struct {
    record_t *head;
    record_t *tail;
} dllist_t;

// Define the memory pool structure
typedef struct {
    int size;
    void **pool;
} mempool_t;

// Define the data structure for managing records
typedef struct {
    hash_table_t *htable;
    dllist_t *dlist;
    mempool_t *mpool;
} record_manager_t;

// Function to initialize a new record
record_t* init_record(int key, double data) {
    record_t *rec = malloc(sizeof(record_t));
    if (rec == NULL) {
        printf("Error: Failed to allocate memory for record\n");
        return NULL;
    }
    rec->key = key;
    rec->data = data;
    rec->next = NULL;
    return rec;
}

// Function to insert a new record into the doubly-linked list
void dllist_insert(dllist_t *list, record_t *rec) {
    if (list == NULL || rec == NULL) {
        printf("Error: Invalid arguments\n");
        return;
    }
    // Insert at head of list
    rec->next = list->head;
    if (list->head != NULL) {
        list->head->prev = rec;
    } else {
        list->tail = rec;
    }
    list->head = rec;
}

// Function to remove a record from the doubly-linked list
void dllist_remove(dllist_t *list, record_t *rec) {
    if (list == NULL || rec == NULL) {
        printf("Error: Invalid arguments\n");
        return;
    }
    // Remove from head of list
    if (list->head == rec) {
        list->head = rec->next;
        if (rec->next != NULL) {
            rec->next->prev = NULL;
        } else {
            list->tail = NULL;
        }
    } else {
        // Remove from middle of list
        record_t *cur = list->head;
        while (cur != NULL && cur->next != rec) {
            cur = cur->next;
        }
        if (cur == NULL) {
            printf("Error: Record not found in list\n");
            return;
        }
        cur->next = rec->next;
        if (rec->next != NULL) {
            rec->next->prev = cur;
        } else {
            list->tail = cur;
        }
    }
}

// Function to allocate a new memory block from the memory pool
void* mempool_alloc(mempool_t *mpool, size_t size) {
    if (mpool == NULL || size <= 0) {
        printf("Error: Invalid arguments\n");
        return NULL;
    }
    void *block = malloc(size);
    if (block == NULL) {
        printf("Error: Failed to allocate memory block from pool\n");
        return NULL;
    }
    mpool->pool[mpool->size++] = block;
    return block;
}

// Function to deallocate a memory block from the memory pool
void mempool_dealloc(mempool_t *mpool, void *block) {
    if (mpool == NULL || block == NULL) {
        printf("Error: Invalid arguments\n");
        return;
    }
    int i = 0;
    for (i = 0; i < mpool->size; i++) {
        if (mpool->pool[i] == block) {
            break;
        }
    }
    if (i >= mpool->size) {
        printf("Error: Block not found in pool\n");
        return;
    }
    mpool->pool[i] = NULL;
}

// Function to initialize a new hash table
hash_table_t* init_hash_table(int size) {
    if (size <= 0) {
        printf("Error: Invalid arguments\n");
        return NULL;
    }
    hash_table_t *htable = malloc(sizeof(hash_table_t));
    if (htable == NULL) {
        printf("Error: Failed to allocate memory for hash table\n");
        return NULL;
    }
    htable->size = size;
    htable->table = calloc(size, sizeof(record_t*));
    if (htable->table == NULL) {
