    return rmgr;
}

// Function to insert a new record into the record manager
void record_manager_insert(record_manager_t *rmgr, int key, double data) {
    if (rmgr == NULL || key < 0 || data < 0) {
        printf("Error: Invalid arguments\n");
        return;
    }
    // Generate a random integer and floating-point number within the specified range
    srand(time(NULL));
    int rand_key = rand() % 1000 + 1;
    double rand_data = (double)rand() / RAND_MAX * 100.0;
    // Create a new record and insert it into the doubly-linked list
    record_t *rec = init_record(rand_key, rand_data);
    if (rec == NULL) {
        printf("Error: Failed to allocate memory for record\n");
        return;
    }
    dllist_insert(rmgr->dlist, rec);
    // Insert the record into the hash table
    hash_table_insert(rmgr->htable, rand_key, rec);
}

// Function to remove a record from the record manager
void record_manager_remove(record_manager_t *rmgr, int key) {
    if (rmgr == NULL || key < 0) {
        printf("Error: Invalid arguments\n");
        return;
    }
    // Remove the record from the doubly-linked list and hash table
    dllist_remove(rmgr->dlist, rmgr->htable->table[key]);
    hash_table_remove(rmgr->htable, key);
}

// Function to periodically prune unused records from the record manager
void record_manager_prune(record_manager_t *rmgr) {
    if (rmgr == NULL) {
        printf("Error: Invalid arguments\n");
        return;
    }
    // Iterate through the doubly-linked list and hash table, removing unused records
    record_t *cur = rmgr->dlist->head;
    while (cur != NULL) {
        if (cur->next == NULL || cur->next->key != cur->key + 1) {
            // Remove the current record from the doubly-linked list and hash table
            dllist_remove(rmgr->dlist, cur);
            hash_table_remove(rmgr->htable, cur->key);
        } else {
            cur = cur->next;
        }
    }
}

// Function to serialize the record manager data structure to a file
void record_manager_serialize(record_manager_t *rmgr, FILE *file) {
    if (rmgr == NULL || file == NULL) {
        printf("Error: Invalid arguments\n");
        return;
    }
    // Write the size of the hash table and doubly-linked list to the file
    fwrite(&(rmgr->htable->size), sizeof(int), 1, file);
    fwrite(&(rmgr->dlist->size), sizeof(int), 1, file);
    // Write each record in the hash table and doubly-linked list to the file
    for (int i = 0; i < rmgr->htable->size; i++) {
        if (rmgr->htable->table[i] != NULL) {
            fwrite(&(rmgr->htable->table[i]->key), sizeof(int), 1, file);
            fwrite(&(rmgr->htable->table[i]->data), sizeof(double), 1, file);
        } else {
            int null_record = -1;
            fwrite(&null_record, sizeof(int), 1, file);
        }
    }
    for (int i = 0; i < rmgr->dlist->size; i++) {
        if (rmgr->dlist->head != NULL) {
            fwrite(&(rmgr->dlist->head->key), sizeof(int), 1, file);
            fwrite(&(rmgr->dlist->head->data), sizeof(double), 1, file);
        } else {
            int null_record = -1;
            fwrite(&null_record, sizeof(int), 1, file);
        }
    }
