    int priority;
    char *message;
    void *metadata;
} Event;

// Define the data structure for the event map
typedef struct EventMap {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    long size;
    long capacity;
    Event **events;
} EventMap;

// Initialize the event map with a given capacity
EventMap *event_map_init(long capacity) {
    EventMap *map = malloc(sizeof(EventMap));
    if (!map) {
        return NULL;
    }
    map->mutex = PTHREAD_MUTEX_INITIALIZER;
    map->cond = PTHREAD_COND_INITIALIZER;
    map->size = 0;
    map->capacity = capacity;
    map->events = malloc(sizeof(Event *) * capacity);
    if (!map->events) {
        free(map);
        return NULL;
    }
    return map;
}

// Insert an event into the event map
int event_map_insert(EventMap *map, Event *event) {
    pthread_mutex_lock(&map->mutex);
    while (map->size == map->capacity) {
        // Wait for space to become available
        pthread_cond_wait(&map->cond, &map->mutex);
    }
    map->events[map->size++] = event;
    pthread_mutex_unlock(&map->mutex);
    return 0;
}

// Remove an event from the event map
int event_map_remove(EventMap *map, long id) {
    pthread_mutex_lock(&map->mutex);
    for (long i = 0; i < map->size; i++) {
        if (map->events[i]->id == id) {
            // Swap the event with the last element and decrease size
            Event *tmp = map->events[i];
            map->events[i] = map->events[--map->size];
            free(tmp);
            pthread_cond_broadcast(&map->cond);
            pthread_mutex_unlock(&map->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&map->mutex);
    return -1;
}

// Get an event from the event map by ID
Event *event_map_get(EventMap *map, long id) {
    pthread_mutex_lock(&map->mutex);
    for (long i = 0; i < map->size; i++) {
        if (map->events[i]->id == id) {
            Event *event = malloc(sizeof(Event));
            memcpy(event, map->events[i], sizeof(Event));
            pthread_mutex_unlock(&map->mutex);
            return event;
        }
    }
    pthread_mutex_unlock(&map->mutex);
    return NULL;
}

// Get all events from the event map by priority level
Event **event_map_get_by_priority(EventMap *map, int priority) {
    pthread_mutex_lock(&map->mutex);
    long count = 0;
    for (long i = 0; i < map->size; i++) {
        if (map->events[i]->priority == priority) {
            count++;
        }
    }
    Event **events = malloc(sizeof(Event *) * count);
    long j = 0;
    for (long i = 0; i < map->size; i++) {
        if (map->events[i]->priority == priority) {
            events[j++] = malloc(sizeof(Event));
            memcpy(events[j-1], map->events[i], sizeof(Event));
        }
    }
    pthread_mutex_unlock(&map->mutex);
    return events;
}

// Free the event map and all its events
void event_map_free(EventMap *map) {
    for (long i = 0; i < map->size; i++) {
        free(map->events[i]);
    }
    pthread_mutex_destroy(&map->mutex);
    pthread_cond_destroy(&map->cond);
    free(map->events);
    free(map);
}
