// Define a struct for the node object
typedef struct Node {
    int key;
    char* value;
    struct Node* next;
    struct Node* prev;
    bool active;
} Node;

// Define a struct for the skip list
typedef struct SkipList {
    Node* head;
    Node* tail;
    int size;
} SkipList;

// Function to create a new node object
Node* create_node(int key, char* value) {
    Node* node = malloc(sizeof(Node));
    node->key = key;
    node->value = strdup(value);
    node->next = NULL;
    node->prev = NULL;
    node->active = true;
    return node;
}

// Function to insert a new node into the list
void insert_node(SkipList* list, int key, char* value) {
    Node* node = create_node(key, value);
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        Node* current = list->head;
        while (current != NULL && current->next != NULL) {
            current = current->next;
        }
        current->next = node;
        node->prev = current;
    }
    list->size++;
}

// Function to delete a node from the list
void delete_node(SkipList* list, int key) {
    Node* current = list->head;
    while (current != NULL && current->key != key) {
        current = current->next;
    }
    if (current == NULL) {
        return;
    }
    if (current == list->head) {
        list->head = current->next;
    } else {
        current->prev->next = current->next;
    }
    if (current == list->tail) {
        list->tail = current->prev;
    } else {
        current->next->prev = current->prev;
    }
    free(current);
    list->size--;
}

// Function to retrieve a node from the list by key
Node* get_node(SkipList* list, int key) {
    Node* current = list->head;
    while (current != NULL && current->key != key) {
        current = current->next;
    }
    return current;
}

// Function to mark a node as inactive after a specified period of inactivity
void mark_inactive(SkipList* list, int key) {
    Node* current = get_node(list, key);
    if (current == NULL) {
        return;
    }
    current->active = false;
}

// Function to reclaim unused memory blocks periodically
void reclaim_memory(SkipList* list) {
    Node* current = list->head;
    while (current != NULL) {
        if (!current->active) {
            Node* next = current->next;
            free(current);
            current = next;
        } else {
            current = current->next;
        }
    }
}

// Function to support fast prefix-based lookups based on the character strings within the nodes
void skip_list_lookup(SkipList* list, char* prefix) {
    Node* current = list->head;
    while (current != NULL && strncmp(prefix, current->value, strlen(prefix)) < 0) {
        current = current->next;
    }
    if (current == NULL) {
        return;
    }
    printf("%d: %s\n", current->key, current->value);
}

