#include <pthread.h>

// Define the structure for a record in the collection
typedef struct {
    int value;
    time_t timestamp;
    char* metadata;
} Record;

// Define the structure for the linked list of records
typedef struct {
    Record* head;
    Record* tail;
} LinkedList;

// Define the structure for the custom hash table
typedef struct {
    int size;
    int count;
    Record** buckets;
} HashTable;

// Function to allocate memory for a new record
Record* create_record(int value, time_t timestamp, char* metadata) {
    Record* new_record = (Record*) malloc(sizeof(Record));
    if (!new_record) {
        return NULL;
    }
    new_record->value = value;
    new_record->timestamp = timestamp;
    new_record->metadata = metadata;
    return new_record;
}

// Function to insert a record into the linked list
void insert_record(LinkedList* list, Record* record) {
    if (!list || !record) {
        return;
    }
    // Insert at the end of the list
    if (list->tail == NULL) {
        list->head = record;
        list->tail = record;
    } else {
        list->tail->next = record;
        list->tail = record;
    }
}

// Function to delete a record from the linked list
void delete_record(LinkedList* list, Record* record) {
    if (!list || !record) {
        return;
    }
    // If the record is at the head of the list
    if (list->head == record) {
        list->head = record->next;
    }
    // If the record is at the tail of the list
    if (list->tail == record) {
        list->tail = record->prev;
    }
    // If the record is in the middle of the list
    if (record->prev && record->next) {
        record->prev->next = record->next;
        record->next->prev = record->prev;
    }
}

// Function to traverse the linked list in reverse order
void traverse_list(LinkedList* list, void (*callback)(Record*)) {
    if (!list || !callback) {
        return;
    }
    Record* current = list->tail;
    while (current != NULL) {
        callback(current);
        current = current->prev;
    }
}

// Function to create a new hash table with the given size
HashTable* create_hash_table(int size) {
    HashTable* new_table = (HashTable*) malloc(sizeof(HashTable));
    if (!new_table) {
        return NULL;
    }
    new_table->size = size;
    new_table->count = 0;
    new_table->buckets = (Record**) calloc(size, sizeof(Record*));
    if (!new_table->buckets) {
        free(new_table);
        return NULL;
    }
    return new_table;
}

// Function to insert a record into the hash table
void insert_hash_table(HashTable* table, Record* record) {
    if (!table || !record) {
        return;
    }
    int index = record->value % table->size;
    // If the bucket is empty, simply assign the record to it
    if (table->buckets[index] == NULL) {
        table->buckets[index] = record;
        table->count++;
    } else {
        // If the bucket is not empty, insert the record at the end of the list
        Record* current = table->buckets[index];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = record;
    }
}

// Function to delete a record from the hash table
void delete_hash_table(HashTable* table, Record* record) {
    if (!table || !record) {
        return;
    }
    int index = record->value % table->size;
    // If the bucket is empty, simply return
    if (table->buckets[index] == NULL) {
        return;
    }
    // If the record is at the head of the list
    if (table->buckets[index] == record) {
        table->buckets[index] = record->next;
        table->count--;
    } else {
        // If the record is in the middle of the list
        Record* current = table->buckets[index];
        while (current->next != NULL && current->next != record) {
            current = current->next;
        }
        if (current->next == record) {
            current->next = record->next;
            table->count--;
        }
    }
}

// Function to search for a record in the hash table using a key
Record* search_hash_table(HashTable* table, int key) {
    if (!table) {
        return NULL;
    }
    int index = key % table->size;
    Record* current = table->buckets[index];
    while (current != NULL && current->value != key) {
        current = current->next;
    }
    return current;
}

// Function to resize the hash table when the load factor exceeds a certain threshold
void resize_hash_table(HashTable* table, int new_size) {
    if (!table || !new_size) {
        return;
    }
    HashTable* new_table = create_hash_table(new_size);
    if (!new_table) {
        return;
    }
    for (int i = 0; i < table->size; i++) {
        Record* current = table->buckets[i];
        while (current != NULL) {
            insert_hash_table(new_table, current);
            current = current->next;
        }
    }
    free(table->buckets);
    table->size = new_size;
}

// Function to manage the reference counts of records
void manage_reference_counts(Record* record) {
    if (!record) {
        return;
    }
    // If the record is not referenced, simply delete it
    if (record->ref_count == 0) {
        delete_hash_table(&table, record);
        free(record);
    } else {
        // If the record is referenced, decrement its reference count
        record->ref_count--;
    }
}

// Function to allocate memory for a new collection
Collection* create_collection() {
    Collection* new_collection = (Collection*) malloc(sizeof(Collection));
    if (!new_collection) {
        return NULL;
    }
    new_collection->linked_list = create_linked_list();
    new_collection->hash_table = create_hash_table(10);
    return new_collection;
}

// Function to insert a record into the collection
void insert_record(Collection* collection, Record* record) {
    if (!collection || !record) {
        return;
    }
    // Insert the record into the linked list and hash table
    insert_linked_list(&collection->linked_list, record);
    insert_hash_table(&collection->hash_table, record);
}

// Function to delete a record from the collection
void delete_record(Collection* collection, Record* record) {
    if (!collection || !record) {
        return;
    }
    // Delete the record from the linked list and hash table
    delete_linked_list(&collection->linked_list, record);
    delete_hash_table(&collection->hash_table, record);
}

// Function to traverse the collection in reverse order
void traverse_collection(Collection* collection, void (*callback)(Record*)) {
    if (!collection || !callback) {
        return;
    }
    // Traverse the linked list in reverse order
    traverse_list(&collection->linked_list, callback);
}

// Function to manage the memory of the collection
void manage_memory(Collection* collection) {
    if (!collection) {
        return;
    }
    // Release partially allocated resources and optimize memory usage
    free(collection->hash_table.buckets);
    free(collection->linked_list.head);
}

// Function to release the memory of the collection
void destroy_collection(Collection* collection) {
    if (!collection) {
        return;
    }
    // Release all allocated resources and prevent memory leaks
    manage_memory(collection);
    free(collection);
}
