// Define a struct for the records in the data structure
typedef struct {
    int value;
    long timestamp;
    int ref_count;
} record_t;

// Define a struct for the hash table
typedef struct {
    record_t** buckets;
    size_t num_buckets;
} hash_table_t;

// Define a struct for the memory pool
typedef struct {
    void* mem_pool;
    size_t mem_size;
} mem_pool_t;

// Define a struct for the doubly-linked list
typedef struct {
    record_t* head;
    record_t* tail;
} dlist_t;

// Define a struct for the data structure
typedef struct {
    hash_table_t* hash_table;
    mem_pool_t* mem_pool;
    dlist_t* dlist;
} data_structure_t;

// Function to initialize the data structure
data_structure_t* init_data_structure(size_t num_buckets, size_t mem_size) {
    // Allocate memory for the hash table and doubly-linked list
    hash_table_t* hash_table = (hash_table_t*)malloc(sizeof(hash_table_t));
    dlist_t* dlist = (dlist_t*)malloc(sizeof(dlist_t));

    // Initialize the hash table and doubly-linked list
    hash_table->buckets = (record_t**)calloc(num_buckets, sizeof(record_t*));
    dlist->head = NULL;
    dlist->tail = NULL;

    // Allocate memory for the memory pool
    mem_pool_t* mem_pool = (mem_pool_t*)malloc(sizeof(mem_pool_t));
    mem_pool->mem_size = mem_size;
    mem_pool->mem_pool = malloc(mem_size);

    // Initialize the data structure
    data_structure_t* ds = (data_structure_t*)malloc(sizeof(data_structure_t));
    ds->hash_table = hash_table;
    ds->mem_pool = mem_pool;
    ds->dlist = dlist;

    return ds;
}

// Function to insert a record into the data structure
void insert_record(data_structure_t* ds, int value, long timestamp) {
    // Allocate memory for the new record
    record_t* new_record = (record_t*)malloc(sizeof(record_t));
    new_record->value = value;
    new_record->timestamp = timestamp;
    new_record->ref_count = 0;

    // Insert the new record into the hash table and doubly-linked list
    size_t bucket_index = hash(value) % ds->hash_table->num_buckets;
    new_record->next = ds->hash_table->buckets[bucket_index];
    if (ds->hash_table->buckets[bucket_index] != NULL) {
        ds->hash_table->buckets[bucket_index]->prev = new_record;
    }
    ds->hash_table->buckets[bucket_index] = new_record;

    // Insert the new record into the doubly-linked list
    if (ds->dlist->head == NULL) {
        ds->dlist->head = new_record;
        ds->dlist->tail = new_record;
    } else {
        new_record->prev = ds->dlist->tail;
        ds->dlist->tail->next = new_record;
        ds->dlist->tail = new_record;
    }
}

// Function to delete a record from the data structure
void delete_record(data_structure_t* ds, int value) {
    // Find the record in the hash table and doubly-linked list
    size_t bucket_index = hash(value) % ds->hash_table->num_buckets;
    record_t* current = ds->hash_table->buckets[bucket_index];
    while (current != NULL && current->value != value) {
        current = current->next;
    }

    // If the record is found, delete it from the hash table and doubly-linked list
    if (current != NULL) {
        if (current == ds->hash_table->buckets[bucket_index]) {
            ds->hash_table->buckets[bucket_index] = current->next;
        }
        if (current->prev != NULL) {
            current->prev->next = current->next;
        }
        if (current->next != NULL) {
            current->next->prev = current->prev;
        }

        // Decrement the reference count of the record
        current->ref_count--;

        // Free the memory for the record
        free(current);
    }
}

// Function to retrieve a record from the data structure
record_t* get_record(data_structure_t* ds, int value) {
    // Find the record in the hash table and doubly-linked list
    size_t bucket_index = hash(value) % ds->hash_table->num_buckets;
    record_t* current = ds->hash_table->buckets[bucket_index];
    while (current != NULL && current->value != value) {
        current = current->next;
    }

    // If the record is found, increment its reference count and return it
    if (current != NULL) {
        current->ref_count++;
        return current;
    } else {
        return NULL;
    }
}

// Function to update a record in the data structure
void update_record(data_structure_t* ds, int value, long timestamp) {
    // Find the record in the hash table and doubly-linked list
    size_t bucket_index = hash(value) % ds->hash_table->num_buckets;
    record_t* current = ds->hash_table->buckets[bucket_index];
    while (current != NULL && current->value != value) {
        current = current->next;
    }

    // If the record is found, update its timestamp and return it
    if (current != NULL) {
        current->timestamp = timestamp;
        return current;
    } else {
        return NULL;
    }
}

// Function to release a record from the data structure
void release_record(data_structure_t* ds, int value) {
    // Find the record in the hash table and doubly-linked list
    size_t bucket_index = hash(value) % ds->hash_table->num_buckets;
    record_t* current = ds->hash_table->buckets[bucket_index];
    while (current != NULL && current->value != value) {
