// Function to free the memory for a data structure
void free_data_structure(data_structure_t* ds) {
    // Free the memory for the hash table and doubly-linked list
    free(ds->hash_table);
    free(ds->dlist);

    // Free the memory for the memory pool
    free(ds->mem_pool);
}
