public class UserProfileManager {
    private static final Logger logger = Logger.getLogger(UserProfileManager.class.getName());
    private static final int MAX_CONCURRENT_REQUESTS = 100;
    private static final int MIN_USER_ID = 1;
    private static final int MAX_USER_ID = 100000000;
    private static final int MIN_PROFILE_METADATA_LENGTH = 1;
    private static final int MAX_PROFILE_METADATA_LENGTH = 1024;
    private static final int MIN_ACCESS_LEVEL = 1;
    private static final int MAX_ACCESS_LEVEL = 3;

    private ConcurrentHashMap<Integer, UserProfile> profiles;
    private ExecutorService executor;

    public UserProfileManager() {
        this.profiles = new ConcurrentHashMap<>();
        this.executor = Executors.newFixedThreadPool(MAX_CONCURRENT_REQUESTS);
    }

    public void updateUserProfile(int userId, String profileMetadata, int accessLevel) throws InvalidInputException {
        if (!isValidUserId(userId)) {
            throw new InvalidInputException("Invalid user ID: " + userId);
        }
        if (!isValidProfileMetadataLength(profileMetadata.length())) {
            throw new InvalidInputException("Invalid profile metadata length: " + profileMetadata.length());
        }
        if (!isValidAccessLevel(accessLevel)) {
            throw new InvalidInputException("Invalid access level: " + accessLevel);
        }

        UserProfile profile = profiles.get(userId);
        if (profile == null) {
            profile = new UserProfile();
            profiles.put(userId, profile);
        }
        profile.setMetadata(profileMetadata);
        profile.setAccessLevel(accessLevel);
    }

    public UserProfile getUserProfile(int userId) throws InvalidInputException {
        if (!isValidUserId(userId)) {
            throw new InvalidInputException("Invalid user ID: " + userId);
        }

        return profiles.get(userId);
    }

    private boolean isValidUserId(int userId) {
        return userId >= MIN_USER_ID && userId <= MAX_USER_ID;
    }

    private boolean isValidProfileMetadataLength(int length) {
        return length >= MIN_PROFILE_METADATA_LENGTH && length <= MAX_PROFILE_METADATA_LENGTH;
    }

    private boolean isValidAccessLevel(int accessLevel) {
        return accessLevel >= MIN_ACCESS_LEVEL && accessLevel <= MAX_ACCESS_LEVEL;
    }

    public static class UserProfile {
        private String metadata;
        private int accessLevel;

        public void setMetadata(String metadata) {
            this.metadata = metadata;
        }

        public void setAccessLevel(int accessLevel) {
            this.accessLevel = accessLevel;
        }
    }

    public static class InvalidInputException extends Exception {
        private static final long serialVersionUID = 1L;

        public InvalidInputException(String message) {
            super(message);
        }
    }
}
