#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the log entry structure
struct log_entry {
    char* message;
    int level;
    unsigned long long timestamp;
    size_t record_size;
};

// Define the linked list node structure
struct node {
    struct log_entry* data;
    struct node* next;
};

// Define the logging system context
struct logging_system {
    // Arrays for storing log entries, log levels, timestamps, and record sizes
    char** messages;
    int* levels;
    unsigned long long* timestamps;
    size_t* record_sizes;

    // Linked list of log entries
    struct node* head;

    // Mutex for protecting the linked list
    pthread_mutex_t mutex;
};

// Initialize the logging system context
void init_logging_system(struct logging_system* sys) {
    // Allocate memory for the arrays
    sys->messages = (char**)malloc(sizeof(char*) * 1024);
    sys->levels = (int*)malloc(sizeof(int) * 1024);
    sys->timestamps = (unsigned long long*)malloc(sizeof(unsigned long long) * 1024);
    sys->record_sizes = (size_t*)malloc(sizeof(size_t) * 1024);

    // Initialize the linked list head
    sys->head = NULL;

    // Initialize the mutex
    pthread_mutex_init(&sys->mutex, NULL);
}

// Add a new log entry to the linked list
void add_log_entry(struct logging_system* sys, char* message, int level) {
    struct node* new_node = (struct node*)malloc(sizeof(struct node));
    new_node->data = (struct log_entry*)malloc(sizeof(struct log_entry));
    new_node->data->message = message;
    new_node->data->level = level;
    new_node->data->timestamp = time(NULL);
    new_node->data->record_size = strlen(message) + 1;
    new_node->next = NULL;

    // Lock the mutex
    pthread_mutex_lock(&sys->mutex);

    // Add the new node to the linked list
    if (sys->head == NULL) {
        sys->head = new_node;
    } else {
        struct node* current = sys->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&sys->mutex);
}

// Remove a log entry from the linked list
void remove_log_entry(struct logging_system* sys, char* message) {
    struct node* current = sys->head;
    while (current != NULL) {
        if (strcmp(current->data->message, message) == 0) {
            // Lock the mutex
            pthread_mutex_lock(&sys->mutex);

            // Remove the node from the linked list
            struct node* previous = current;
            current = current->next;
            free(previous);

            // Unlock the mutex
            pthread_mutex_unlock(&sys->mutex);
            break;
        } else {
            current = current->next;
        }
    }
}

// Traverse the linked list and print all log entries
void traverse_log_entries(struct logging_system* sys) {
    struct node* current = sys->head;
    while (current != NULL) {
        printf("%s: %d\n", current->data->message, current->data->level);
        current = current->next;
    }
}

// Release memory for the linked list and arrays
void release_logging_system(struct logging_system* sys) {
    // Lock the mutex
    pthread_mutex_lock(&sys->mutex);

    // Release memory for the linked list
    struct node* current = sys->head;
    while (current != NULL) {
        struct node* next = current->next;
        free(current);
        current = next;
    }

    // Release memory for the arrays
    free(sys->messages);
    free(sys->levels);
    free(sys->timestamps);
    free(sys->record_sizes);

    // Unlock the mutex
    pthread_mutex_unlock(&sys->mutex);
}
```
