// Define the memory reclamation strategy
#define MEMORY_RECLAMATION_STRATEGY "compact"

// Define the serialization failure handling strategy
#define SERIALIZATION_FAILURE_HANDLING_STRATEGY "abort"

// Define the hash table collision resolution strategy
