// Define the function to dynamically allocate memory for and initialize an array of 'long' offset values
void* allocateLongArray(size_t size) {
    // Allocate memory for the array using malloc()
    long* arr = (long*)malloc(sizeof(long) * size);
    if (!arr) {
        // Handle memory allocation failure gracefully
        printf("Memory allocation failed. Retrying...\n");
        return NULL;
    }

    // Initialize the array with default values
    for (size_t i = 0; i < size; i++) {
        arr[i] = 0;
    }

    return arr;
}

