}

// Define the function to dynamically allocate memory for and initialize an array of 'record' structures
void* allocateRecordArray(size_t size) {
    // Allocate memory for the array using malloc()
    Record* arr = (Record*)malloc(sizeof(Record) * size);
    if (!arr) {
        // Handle memory allocation failure gracefully
