}

// Define the function to dynamically allocate memory for and initialize a hash table
HashTable* allocateHashTable(size_t capacity) {
    // Allocate memory for the hash table using malloc()
    HashTable* ht = (HashTable*)malloc(sizeof(HashTable));
    if (!ht) {
        // Handle memory allocation failure gracefully
        printf("Memory allocation failed. Retrying...\n");
        return NULL;
    }

    // Initialize the hash table with default values
    ht->capacity = capacity;
    ht->size = 0;
    ht->buckets = (Record**)malloc(sizeof(Record*) * capacity);
    if (!ht->buckets) {
        // Handle memory allocation failure gracefully
        printf("Memory allocation failed. Retrying...\n");
        return NULL;
    }

    for (size_t i = 0; i < capacity; i++) {
        ht->buckets[i] = NULL;
    }

    return ht;
}

// Define the function to dynamically allocate memory for and initialize a memory pool
MemoryPool* allocateMemoryPool(size_t size) {
    // Allocate memory for the memory pool using malloc()
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!mp) {
        // Handle memory allocation failure gracefully
        printf("Memory allocation failed. Retrying...\n");
        return NULL;
    }

    // Initialize the memory pool with default values
    mp->size = size;
    mp->buffer = malloc(sizeof(char) * size);
    if (!mp->buffer) {
        // Handle memory allocation failure gracefully
        printf("Memory allocation failed. Retrying...\n");
        return NULL;
    }

    return mp;
}

// Define the function to insert a record into the hash table
bool insertRecord(HashTable* ht, int key, float data) {
    // Check if the hash table is full
    if (ht->size == ht->capacity) {
        // Handle hash table overflow gracefully
        printf("Hash table overflow. Retrying...\n");
        return false;
    }

    // Calculate the hash value for the key
    size_t hash = key % ht->capacity;

    // Check if there is a collision
    while (ht->buckets[hash] != NULL && ht->buckets[hash]->key != key) {
        // Handle collisions gracefully
        printf("Hash table collision. Retrying...\n");
        hash = (hash + 1) % ht->capacity;
    }

    // Insert the record into the hash table
    Record* newRecord = (Record*)malloc(sizeof(Record));
