// Define the data structure for a record in the hash table
typedef struct {
    int key;
    float data;
    struct record *next;
} record;

// Define the data structure for the complex data structure
typedef struct {
    int num_records;
    int max_records;
    record **records;
    pthread_mutex_t mutex;
} complex_data_structure;

// Function to initialize the hash table
void init_hash_table(complex_data_structure *ht) {
    ht->num_records = 0;
    ht->max_records = INITIAL_MAX_RECORDS;
    ht->records = (record **)malloc(sizeof(record *) * ht->max_records);
    for (int i = 0; i < ht->max_records; i++) {
        ht->records[i] = NULL;
    }
}

// Function to insert a record into the hash table
void insert(complex_data_structure *ht, int key, float data) {
    pthread_mutex_lock(&ht->mutex);
    // Check if the hash table needs to be resized
    if (ht->num_records >= ht->max_records) {
        resize(ht);
    }
    // Create a new record and insert it into the hash table
    record *new_record = (record *)malloc(sizeof(record));
    new_record->key = key;
    new_record->data = data;
    new_record->next = NULL;
    int index = get_index(ht, key);
    if (ht->records[index] == NULL) {
        ht->records[index] = new_record;
    } else {
        record *current = ht->records[index];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_record;
    }
    ht->num_records++;
    pthread_mutex_unlock(&ht->mutex);
}

// Function to delete a record from the hash table
void delete(complex_data_structure *ht, int key) {
    pthread_mutex_lock(&ht->mutex);
    // Find the index of the record to be deleted
    int index = get_index(ht, key);
    if (ht->records[index] == NULL) {
        printf("Record not found\n");
        pthread_mutex_unlock(&ht->mutex);
        return;
    }
    // Delete the record from the hash table
    record *current = ht->records[index];
    if (current->key == key) {
        ht->records[index] = current->next;
        free(current);
        ht->num_records--;
    } else {
        while (current->next != NULL && current->next->key != key) {
            current = current->next;
        }
        if (current->next == NULL) {
            printf("Record not found\n");
        } else {
            record *to_delete = current->next;
            current->next = to_delete->next;
            free(to_delete);
            ht->num_records--;
        }
    }
    pthread_mutex_unlock(&ht->mutex);
}

// Function to get the index of a record in the hash table
int get_index(complex_data_structure *ht, int key) {
    return key % ht->max_records;
}

// Function to resize the hash table when it needs to be resized
void resize(complex_data_structure *ht) {
    // Create a new array of records with twice the size of the current array
    int new_size = 2 * ht->max_records;
    record **new_records = (record **)malloc(sizeof(record *) * new_size);
    for (int i = 0; i < new_size; i++) {
        new_records[i] = NULL;
    }
    // Copy the records from the old array to the new array
    for (int i = 0; i < ht->max_records; i++) {
        record *current = ht->records[i];
        while (current != NULL) {
            int index = get_index(ht, current->key);
            if (new_records[index] == NULL) {
                new_records[index] = current;
            } else {
                record *next = new_records[index];
                while (next->next != NULL) {
                    next = next->next;
                }
                next->next = current;
            }
            current = current->next;
        }
    }
    // Free the old array of records and set the new array as the hash table's records
    free(ht->records);
    ht->records = new_records;
    ht->max_records = new_size;
}

// Function to serialize the complex data structure to disk
void serialize(complex_data_structure *ht, char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        printf("Error opening file\n");
        return;
    }
    // Write the number of records in the hash table to the file
    int num_records = ht->num_records;
    fwrite(&num_records, sizeof(int), 1, file);
    // Write each record in the hash table to the file
    for (int i = 0; i < ht->max_records; i++) {
        record *current = ht->records[i];
        while (current != NULL) {
            fwrite(&current->key, sizeof(int), 1, file);
            fwrite(&current->data, sizeof(float), 1, file);
            current = current->next;
        }
    }
    // Close the file
    fclose(file);
}

// Function to deserialize the complex data structure from disk
void deserialize(complex_data_structure *ht, char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Error opening file\n");
