    char *message;
} log_entry;

// Define the logging function
void log(int level, const char *format, ...) {
    va_list args;
    va_start(args, format);
    if (level <= LOG_LEVEL_DEBUG) {
        printf("[DEBUG] ");
    } else if (level == LOG_LEVEL_INFO) {
        printf("[INFO] ");
    } else if (level == LOG_LEVEL_WARN) {
        printf("[WARN] ");
    } else if (level == LOG_LEVEL_ERROR) {
        printf("[ERROR] ");
    }
    vprintf(format, args);
    va_end(args);
}

// Define the memory allocation function
void *allocate_memory(size_t size) {
    void *memory = malloc(size);
    if (memory == NULL) {
        log(LOG_LEVEL_ERROR, "Failed to allocate %d bytes of memory", size);
        return NULL;
    }
    return memory;
}

// Define the memory deallocation function
void free_memory(void *memory) {
    if (memory != NULL) {
        free(memory);
    }
}

// Define the priority queue insertion function
int insert_priority_queue(priority_queue *queue, sensor_data *data) {
    // Check if the queue is full
    if (queue->size == queue->capacity) {
        log(LOG_LEVEL_WARN, "Priority queue is full");
        return -1;
    }
    // Insert the data into the queue
    queue->data[queue->size++] = *data;
    // Sort the queue by timestamp
    qsort(queue->data, queue->size, sizeof(sensor_data), compare_timestamps);
    return 0;
}

// Define the priority queue removal function
int remove_priority_queue(priority_queue *queue, sensor_data *data) {
    // Check if the queue is empty
    if (queue->size == 0) {
        log(LOG_LEVEL_WARN, "Priority queue is empty");
        return -1;
    }
    // Remove the first element from the queue
    *data = queue->data[0];
    for (int i = 0; i < queue->size - 1; i++) {
        queue->data[i] = queue->data[i + 1];
    }
    queue->size--;
    return 0;
}

// Define the memory pool allocation function
void *allocate_memory_pool(int capacity) {
    void **memory = malloc(capacity * sizeof(void*));
    if (memory == NULL) {
        log(LOG_LEVEL_ERROR, "Failed to allocate %d bytes of memory", capacity);
        return NULL;
    }
    for (int i = 0; i < capacity; i++) {
