        if (memory[i] == NULL) {
            log(LOG_LEVEL_ERROR, "Failed to allocate %d bytes of memory", sizeof(sensor_data));
            return NULL;
        }
    }
    return memory;
}

// Define the memory pool deallocation function
void free_memory_pool(void *memory) {
    if (memory != NULL) {
        void **pool = (void**)memory;
        for (int i = 0; i < ((memory_pool*)pool)->capacity; i++) {
            free(((memory_pool*)pool)->memory[i]);
        }
        free(pool);
