// Define a struct to represent a task
typedef struct Task {
    int timestamp;
    int priority;
    char* description;
} Task;

// Define a linked list node to store tasks
typedef struct Node {
    Task task;
    struct Node* next;
} Node;

// Define a hash table to store tasks based on their descriptions
typedef struct HashTable {
    int size;
    int count;
    Node** nodes;
} HashTable;

// Initialize the linked list and hash table
void init(LinkedList* ll, HashTable* ht) {
    // Initialize the linked list head node
    ll->head = NULL;

    // Initialize the hash table with a default size of 1024
    ht->size = 1024;
    ht->count = 0;
    ht->nodes = (Node**)malloc(ht->size * sizeof(Node*));
}

// Insert a new task into the linked list and hash table
void insert(LinkedList* ll, HashTable* ht, Task task) {
    // Create a new node for the task
    Node* node = (Node*)malloc(sizeof(Node));
    node->task = task;

    // Insert the task into the linked list
    if (ll->head == NULL) {
        ll->head = node;
    } else {
        node->next = ll->head;
        ll->head = node;
    }

    // Insert the task into the hash table
    int index = hash(task.description);
    if (ht->nodes[index] == NULL) {
        ht->nodes[index] = node;
    } else {
        Node* current = ht->nodes[index];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }

    // Update the task's priority based on its position in the list
    int priority = ll->count - node->task.timestamp + 1;
    node->task.priority = priority;
}

// Delete a task from the linked list and hash table
void delete(LinkedList* ll, HashTable* ht, Task task) {
    // Find the node containing the task in the linked list
    Node* current = ll->head;
    while (current != NULL && current->task.description != task.description) {
        current = current->next;
    }

    // If the task is found, delete it from the linked list and hash table
    if (current != NULL) {
        // Delete the node from the linked list
        if (current == ll->head) {
            ll->head = current->next;
        } else {
            Node* previous = ll->head;
            while (previous->next != current) {
                previous = previous->next;
            }
            previous->next = current->next;
        }

        // Delete the node from the hash table
        int index = hash(task.description);
        Node* current = ht->nodes[index];
        while (current != NULL && current->task.description != task.description) {
            current = current->next;
        }
        if (current != NULL) {
            if (current == ht->nodes[index]) {
                ht->nodes[index] = current->next;
            } else {
                Node* previous = ht->nodes[index];
                while (previous->next != current) {
                    previous = previous->next;
                }
                previous->next = current->next;
            }
        }

        // Free the node memory
        free(current);
    }
}

// Traverse the linked list and hash table to retrieve tasks by their priority levels
void traverse(LinkedList* ll, HashTable* ht) {
    // Traverse the linked list from head to tail
    Node* current = ll->head;
    while (current != NULL) {
        printf("Task: %s\n", current->task.description);
        current = current->next;
    }

    // Traverse the hash table and retrieve tasks by their priority levels
    for (int i = 0; i < ht->size; i++) {
        Node* current = ht->nodes[i];
        while (current != NULL) {
            printf("Task: %s\n", current->task.description);
            current = current->next;
        }
    }
}

// Periodically check and release unused memory blocks to optimize resource usage
void release_memory() {
    // Check if any nodes are unused
    Node* current = ll->head;
    while (current != NULL) {
        if (current->next == NULL) {
            free(current);
            break;
        } else {
            current = current->next;
        }
    }

    // Check if any hash table nodes are unused
    for (int i = 0; i < ht->size; i++) {
        Node* current = ht->nodes[i];
        while (current != NULL) {
            if (current->next == NULL) {
                free(current);
                break;
            } else {
                current = current->next;
            }
        }
    }
}

