// Custom data structure for theme settings
typedef struct {
    char* name;
    int value;
} ThemeSetting;

// Function to read configuration files and initialize theme settings
void initThemeSettings(char* configFile) {
    // Open the configuration file
    FILE* fp = fopen(configFile, "r");
    if (fp == NULL) {
        printf("Error: unable to open configuration file\n");
        return;
    }

    // Read each line of the file and parse it as a key-value pair
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        // Skip empty lines or comments
        if (strlen(line) == 0 || line[0] == '#') {
            continue;
        }

        // Split the line into key and value
        char* delimiter = strchr(line, '=');
        if (delimiter == NULL) {
            printf("Error: unable to parse configuration file\n");
            return;
        }
        *delimiter = '\0';
        char* key = line;
        char* value = delimiter + 1;

        // Add the setting to the list of theme settings
        ThemeSetting* setting = malloc(sizeof(ThemeSetting));
        setting->name = strdup(key);
        setting->value = atoi(value);
        addThemeSetting(setting);
    }

    // Close the configuration file
    fclose(fp);
}

// Function to add a theme setting to the list of settings
void addThemeSetting(ThemeSetting* setting) {
    // Check if the setting already exists in the list
    ThemeSetting* existing = findThemeSetting(setting->name);
    if (existing != NULL) {
        // Update the value of the existing setting
        existing->value = setting->value;
    } else {
        // Add the new setting to the list
        addToList(&themeSettings, setting);
    }
}

// Function to find a theme setting by name
ThemeSetting* findThemeSetting(char* name) {
    for (int i = 0; i < numThemeSettings; i++) {
        if (strcmp(name, themeSettings[i].name) == 0) {
            return &themeSettings[i];
        }
    }
    return NULL;
}

