int generateRandomInteger(int min, int max) {
    // Generate a random number between the minimum and maximum values
    int random = rand() % (max - min + 1) + min;
    return random;
}

// Function to find the largest integer in an array of integers
int findLargestInteger(int* arr, int size) {
    // Initialize the largest integer to the first element in the array
    int largest = arr[0];

    // Iterate over the remaining elements and compare them to the current largest integer
    for (int i = 1; i < size; i++) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }

    return largest;
}

