#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the sensor reading structure
struct sensor_reading {
    int id;
    double value;
    char* string;
    time_t timestamp;
};

// Define the doubly linked list node
struct dll_node {
    struct sensor_reading* data;
    struct dll_node* next;
    struct dll_node* prev;
};

// Define the custom balanced binary tree node
struct bbt_node {
    int id;
    double value;
    char* string;
    time_t timestamp;
    struct bbt_node* left;
    struct bbt_node* right;
};

// Define the sensor data structure
struct sensor_data {
    struct dll_node* head;
    struct dll_node* tail;
    int size;
    pthread_mutex_t mutex;
};

// Define the function to dynamically manage the system of sensor data
void manage_sensor_data(struct sensor_data* data, struct sensor_reading* reading) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&data->mutex);

    // Insert the new reading into the doubly linked list
    struct dll_node* node = malloc(sizeof(struct dll_node));
    node->data = reading;
    node->next = NULL;
    node->prev = data->tail;
    if (data->tail != NULL) {
        data->tail->next = node;
    } else {
        data->head = node;
    }
    data->tail = node;
    data->size++;

    // Update the timestamp of the reading to the current system time
    reading->timestamp = time(NULL);

    // Insert the new reading into the custom balanced binary tree
    struct bbt_node* root = data->root;
    if (root == NULL) {
        root = malloc(sizeof(struct bbt_node));
        root->id = reading->id;
        root->value = reading->value;
        root->string = strdup(reading->string);
        root->timestamp = reading->timestamp;
        root->left = NULL;
        root->right = NULL;
    } else {
        struct bbt_node* current = root;
        while (current != NULL) {
            if (reading->id < current->id) {
                if (current->left == NULL) {
                    struct bbt_node* new_node = malloc(sizeof(struct bbt_node));
                    new_node->id = reading->id;
                    new_node->value = reading->value;
                    new_node->string = strdup(reading->string);
                    new_node->timestamp = reading->timestamp;
                    current->left = new_node;
                } else {
                    current = current->left;
                }
            } else if (reading->id > current->id) {
                if (current->right == NULL) {
                    struct bbt_node* new_node = malloc(sizeof(struct bbt_node));
                    new_node->id = reading->id;
                    new_node->value = reading->value;
                    new_node->string = strdup(reading->string);
                    new_node->timestamp = reading->timestamp;
                    current->right = new_node;
                } else {
                    current = current->right;
                }
            } else {
                // Update the value and timestamp of the existing node
                current->value = reading->value;
                current->string = strdup(reading->string);
                current->timestamp = reading->timestamp;
                break;
            }
        }
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&data->mutex);
}

// Define the function to efficiently manage memory allocation and deallocation
void manage_memory(struct sensor_data* data) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&data->mutex);

    // Prune outdated or unused entries from the doubly linked list
    struct dll_node* current = data->head;
    while (current != NULL) {
