#include <stdlib.h>
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <assert.h>

// Define the record structure
typedef struct {
    int key;
    long offset;
} Record;

// Define the memory pool structure
typedef struct {
    size_t capacity; // Total number of records in the pool
    size_t count; // Number of records currently used
    Record* records; // Array of records
} MemoryPool;

// Initialize a new memory pool with the specified capacity and random value range
MemoryPool* init_memory_pool(size_t capacity, int min_value, int max_value) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    assert(pool != NULL);

    // Allocate memory for the record array
    pool->records = malloc(capacity * sizeof(Record));
    assert(pool->records != NULL);

    // Initialize each record with a random value within the specified range
    for (size_t i = 0; i < capacity; i++) {
        pool->records[i].key = rand() % (max_value - min_value + 1) + min_value;
        pool->records[i].offset = 0;
    }

    // Set the initial count to zero
    pool->count = 0;

    return pool;
}

// Insert a new record into the memory pool
void insert_record(MemoryPool* pool, int key, long offset) {
    assert(pool != NULL);

    // Check if the pool is full
    if (pool->count == pool->capacity) {
        printf("Error: Memory pool is full\n");
        return;
    }

    // Find the first available slot in the record array
    size_t index = 0;
    while (index < pool->capacity && pool->records[index].key != 0) {
        index++;
    }

    // If no slots are available, reallocate the record array
    if (index == pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        Record* new_records = realloc(pool->records, new_capacity * sizeof(Record));
        assert(new_records != NULL);

        // Initialize the new slots with random values within the specified range
        for (size_t i = pool->count; i < new_capacity; i++) {
            new_records[i].key = rand() % (max_value - min_value + 1) + min_value;
            new_records[i].offset = 0;
        }

        pool->records = new_records;
        pool->capacity = new_capacity;
    }

    // Insert the record into the available slot
    pool->records[index].key = key;
    pool->records[index].offset = offset;
    pool->count++;
}

// Delete a record from the memory pool based on its integer key
void delete_record(MemoryPool* pool, int key) {
    assert(pool != NULL);

    // Find the index of the record to be deleted
    size_t index = 0;
    while (index < pool->count && pool->records[index].key != key) {
        index++;
    }

    // If the record is found, move the last record to its position and update the count
    if (index < pool->count) {
        Record* last_record = &pool->records[pool->count - 1];
        pool->records[index] = *last_record;
        pool->count--;
    }
}

// Set the integer value of a record in the memory pool based on its integer key
void set_record_value(MemoryPool* pool, int key, long offset) {
    assert(pool != NULL);

    // Find the index of the record to be updated
    size_t index = 0;
    while (index < pool->count && pool->records[index].key != key) {
        index++;
    }

    // If the record is found, update its offset value
    if (index < pool->count) {
        pool->records[index].offset = offset;
    }
}

// Get the integer value of a record in the memory pool based on its integer key
long get_record_value(MemoryPool* pool, int key) {
    assert(pool != NULL);

    // Find the index of the record to be retrieved
    size_t index = 0;
    while (index < pool->count && pool->records[index].key != key) {
        index++;
    }

    // If the record is found, return its offset value
    if (index < pool->count) {
        return pool->records[index].offset;
    } else {
        return -1;
    }
}

// Free the memory pool and all associated resources
void free_memory_pool(MemoryPool* pool) {
    assert(pool != NULL);

    // Free the record array
    free(pool->records);

    // Free the memory pool structure itself
    free(pool);
}
