#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <assert.h>

// Define the record structure
typedef struct {
    int key;
    long offset;
    void* metadata;
} Record;

// Define the memory pool structure
typedef struct {
    size_t capacity; // Maximum number of records in the pool
    size_t count; // Current number of records in the pool
    size_t size; // Total size of the memory pool (in bytes)
    Record* records; // Array of record structures
} MemoryPool;

// Initialize a new memory pool with the given capacity and random metadata value range
MemoryPool* init_memory_pool(size_t capacity, int min_metadata_value, int max_metadata_value) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (!pool) {
        return NULL;
    }
    pool->capacity = capacity;
    pool->count = 0;
    pool->size = capacity * sizeof(Record);
    pool->records = calloc(capacity, sizeof(Record));
    if (!pool->records) {
        free(pool);
        return NULL;
    }
    for (size_t i = 0; i < capacity; i++) {
        pool->records[i].key = rand() % (max_metadata_value - min_metadata_value + 1) + min_metadata_value;
        pool->records[i].offset = i * sizeof(Record);
        pool->records[i].metadata = malloc(sizeof(void*));
        if (!pool->records[i].metadata) {
            free(pool->records);
            free(pool);
            return NULL;
        }
    }
    return pool;
}

// Insert a new record into the memory pool, returning its index on success or -1 on failure
int insert_record(MemoryPool* pool, int key, long offset) {
    if (pool->count == pool->capacity) {
        // Memory pool is full, cannot insert any more records
        return -1;
    }
    for (size_t i = 0; i < pool->capacity; i++) {
        if (pool->records[i].key == key) {
            // Record with the given key already exists in the memory pool, cannot insert a duplicate
            return -1;
        }
    }
    size_t index = pool->count++;
    pool->records[index].key = key;
    pool->records[index].offset = offset;
    return (int)index;
}

// Delete a record from the memory pool, returning 0 on success or -1 on failure
int delete_record(MemoryPool* pool, int key) {
    for (size_t i = 0; i < pool->count; i++) {
        if (pool->records[i].key == key) {
            // Record with the given key exists in the memory pool, delete it
            free(pool->records[i].metadata);
            pool->records[i] = pool->records[--pool->count];
            return 0;
        }
    }
    // Record with the given key does not exist in the memory pool, cannot delete a non-existent record
    return -1;
}

// Update the metadata of a record in the memory pool, returning 0 on success or -1 on failure
int update_record(MemoryPool* pool, int key, void* metadata) {
    for (size_t i = 0; i < pool->count; i++) {
        if (pool->records[i].key == key) {
            // Record with the given key exists in the memory pool, update its metadata
            free(pool->records[i].metadata);
            pool->records[i].metadata = malloc(sizeof(void*));
            if (!pool->records[i].metadata) {
                return -1;
            }
            memcpy(pool->records[i].metadata, metadata, sizeof(void*));
            return 0;
        }
    }
    // Record with the given key does not exist in the memory pool, cannot update a non-existent record
    return -1;
}

// Retrieve the metadata of a record from the memory pool, returning NULL on failure or a pointer to the metadata structure on success
void* get_record(MemoryPool* pool, int key) {
    for (size_t i = 0; i < pool->count; i++) {
        if (pool->records[i].key == key) {
            // Record with the given key exists in the memory pool, return its metadata
            return pool->records[i].metadata;
        }
    }
    // Record with the given key does not exist in the memory pool, cannot retrieve a non-existent record
    return NULL;
}

// Free all resources associated with the memory pool, including records and metadata
void free_memory_pool(MemoryPool* pool) {
    for (size_t i = 0; i < pool->count; i++) {
        free(pool->records[i].metadata);
    }
    free(pool->records);
    free(pool);
}
