void init_record(Record* record) {
    record->value = rand() % 100; // Initialize the integer value with a random number within a specified range
    record->metadata = malloc(sizeof(void*) * 2); // Allocate memory for the metadata pointers
    record->external_data = malloc(sizeof(void*) * 3); // Allocate memory for the external data references
    record->transaction_log = malloc(sizeof(void*) * 4); // Allocate memory for the transaction log pointers
}

// Define a function to initialize the complex data structure with a specified number of records
void init_complex_data_structure(ComplexDataStructure* complex_data_structure, int num_records) {
    complex_data_structure->num_records = num_records; // Set the number of records in the data structure
    complex_data_structure->records = malloc(sizeof(Record) * num_records); // Allocate memory for the array of records
    for (int i = 0; i < num_records; i++) {
        init_record(&complex_data_structure->records[i]); // Initialize each record with a random integer value and metadata pointers
    }
}

// Define a function to insert a new record into the complex data structure
void insert_record(ComplexDataStructure* complex_data_structure, int value) {
    pthread_mutex_lock(&complex_data_structure->lock); // Acquire the lock on the data structure
    Record* new_record = malloc(sizeof(Record)); // Allocate memory for the new record
    init_record(new_record); // Initialize the new record with a random integer value and metadata pointers
    new_record->value = value; // Set the value of the new record
    complex_data_structure->records[complex_data_structure->num_records++] = new_record; // Add the new record to the end of the array of records
    pthread_mutex_unlock(&complex_data_structure->lock); // Release the lock on the data structure
}

// Define a function to delete a record from the complex data structure
void delete_record(ComplexDataStructure* complex_data_structure, int index) {
    pthread_mutex_lock(&complex_data_structure->lock); // Acquire the lock on the data structure
    Record* deleted_record = &complex_data_structure->records[index]; // Get a pointer to the record to be deleted
    for (int i = index; i < complex_data_structure->num_records - 1; i++) {
        complex_data_structure->records[i] = complex_data_structure->records[i + 1]; // Shift all records after the deleted record one position to the left
    }
    complex_data_structure->num_records--; // Decrement the number of records in the data structure
    free(deleted_record); // Free the memory allocated for the deleted record
    pthread_mutex_unlock(&complex_data_structure->lock); // Release the lock on the data structure
}

// Define a function to traverse all records in the complex data structure
void traverse_records(ComplexDataStructure* complex_data_structure) {
    for (int i = 0; i < complex_data_structure->num_records; i++) {
