// Define a function to search for a specific value in the complex data structure
int search_record(ComplexDataStructure* complex_data_structure, int value) {
    pthread_mutex_lock(&complex_data_structure->lock); // Acquire the lock on the data structure
    for (int i = 0; i < complex_data_structure->num_records; i++) {
        Record* record = &complex_data_structure->records[i]; // Get a pointer to the current record
        if (record->value == value) { // Check if the current record has the specified value
            pthread_mutex_unlock(&complex_data_structure->lock); // Release the lock on the data structure
            return i; // Return the index of the found record
        }
    }
    pthread_mutex_unlock(&complex_data_structure->lock); // Release the lock on the data structure
    return -1; // Return -1 if no record with the specified value is found
}

// Define a function to update a specific record in the complex data structure
void update_record(ComplexDataStructure* complex_data_structure, int index, int new_value) {
    pthread_mutex_lock(&complex_data_structure->lock); // Acquire the lock on the data structure
    Record* updated_record = &complex_data_structure->records[index]; // Get a pointer to the record to be updated
    updated_record->value = new_value; // Update the value of the record
    pthread_mutex_unlock(&complex_data_structure->lock); // Release the lock on the data structure
}

// Define a function to release all memory allocated for the complex data structure
void free_complex_data_structure(ComplexDataStructure* complex_data_structure) {
    pthread_mutex_lock(&complex_data_structure->lock); // Acquire the lock on the data structure
    for (int i = 0; i < complex_data_structure->num_records; i++) {
        Record* record = &complex_data_structure->records[i]; // Get a pointer to the current record
        free(record->metadata); // Free the memory allocated for the metadata pointers
        free(record->external_data); // Free the memory allocated for the external data references
        free(record->transaction_log); // Free the memory allocated for the transaction log pointers
    }
    free(complex_data_structure->records); // Free the memory allocated for the array of records
    pthread_mutex_unlock(&complex_data_structure->lock); // Release the lock on the data structure
}

