// sensor_event_manager.c
#include "sensor_event_manager.h"

void init_sensor_event_manager(sensor_event_manager_t *manager) {
    manager->capacity = 10;
    manager->size = 0;
    manager->events = (sensor_event_t *)malloc(sizeof(sensor_event_t) * manager->capacity);
}

void add_sensor_event(sensor_event_manager_t *manager, sensor_event_t *event) {
    if (manager->size == manager->capacity) {
        // resize the array if necessary
        manager->capacity *= 2;
        manager->events = (sensor_event_t *)realloc(manager->events, sizeof(sensor_event_t) * manager->capacity);
    }
    manager->events[manager->size++] = *event;
}

void remove_sensor_event(sensor_event_manager_t *manager, int id) {
    // find the event with the given ID and swap it with the last element in the array
    for (int i = 0; i < manager->size; i++) {
        if (manager->events[i].id == id) {
            sensor_event_t *tmp = &manager->events[i];
            manager->events[i] = manager->events[manager->size - 1];
            manager->events[manager->size - 1] = *tmp;
            break;
        }
    }
    // decrement the size of the array
    manager->size--;
}

sensor_event_t *get_sensor_event(sensor_event_manager_t *manager, int id) {
    for (int i = 0; i < manager->size; i++) {
        if (manager->events[i].id == id) {
            return &manager->events[i];
        }
    }
    return NULL;
}
