typedef struct {
    double value;
    char *label;
    float timestamp;
} data_point;

// Define hash table for quick key-based lookups
typedef struct {
    int size;
    int count;
    data_point **table;
} hash_table;

// Function to initialize the hash table
void init_hash_table(hash_table *ht) {
    ht->size = 1024; // Initial size of the hash table
    ht->count = 0;
    ht->table = (data_point **)malloc(sizeof(data_point *) * ht->size);
}

// Function to insert a new data point into the hash table
void insert_data_point(hash_table *ht, data_point *dp) {
    // Calculate the hash value for the key
    int hash = dp->label % ht->size;

    // Check if there is an existing entry with the same key
    while (ht->table[hash] != NULL && strcmp(ht->table[hash]->label, dp->label) == 0) {
        hash = (hash + 1) % ht->size;
    }

    // Insert the new data point into the hash table
    ht->table[hash] = dp;
    ht->count++;
}

// Function to delete a data point from the hash table
void delete_data_point(hash_table *ht, char *label) {
    // Calculate the hash value for the key
    int hash = label % ht->size;

    // Check if there is an existing entry with the same key
    while (ht->table[hash] != NULL && strcmp(ht->table[hash]->label, label) == 0) {
        data_point *dp = ht->table[hash];
        ht->table[hash] = NULL;
        free(dp);
        ht->count--;
    }
}

// Function to retrieve a data point from the hash table by its key
data_point *get_data_point(hash_table *ht, char *label) {
    // Calculate the hash value for the key
    int hash = label % ht->size;

    // Check if there is an existing entry with the same key
    while (ht->table[hash] != NULL && strcmp(ht->table[hash]->label, label) == 0) {
        return ht->table[hash];
    }

    return NULL;
}

// Function to update a data point in the hash table
void update_data_point(hash_table *ht, char *label, double value, float timestamp) {
    // Calculate the hash value for the key
    int hash = label % ht->size;

    // Check if there is an existing entry with the same key
    while (ht->table[hash] != NULL && strcmp(ht->table[hash]->label, label) == 0) {
        data_point *dp = ht->table[hash];
        dp->value = value;
        dp->timestamp = timestamp;
        return;
    }
}

// Function to traverse all data points in the hash table
void traverse_data_points(hash_table *ht, void (*callback)(data_point *)) {
    for (int i = 0; i < ht->size; i++) {
        if (ht->table[i] != NULL) {
            callback(ht->table[i]);
        }
    }
}

// Function to remove outdated entries from the hash table
void prune_data_points(hash_table *ht, float threshold) {
    for (int i = 0; i < ht->size; i++) {
        if (ht->table[i] != NULL && ht->table[i]->timestamp < threshold) {
            data_point *dp = ht->table[i];
            ht->table[i] = NULL;
            free(dp);
            ht->count--;
        }
    }
}

// Function to handle memory allocation failures
void handle_memory_allocation_failure() {
    printf("Memory allocation failure occurred. Please try again later.\n");
}

int main() {
