    insert_data_point(&ht, "data1", 1.0, 1.0);
    insert_data_point(&ht, "data2", 2.0, 2.0);
    insert_data_point(&ht, "data3", 3.0, 3.0);

    // Retrieve a data point from the hash table by its key
