    if (dp != NULL) {
        printf("Data point with label 'data1' has value %f and timestamp %f\n", dp->value, dp->timestamp);
    } else {
        printf("No data point found with label 'data1'\n");
    }

    // Update a data point in the hash table
    update_data_point(&ht, "data2", 4.0, 4.0);

    // Traverse all data points in the hash table
    traverse_data_points(&ht, (void (*)(data_point *))printf);

    // Remove outdated entries from the hash table
    prune_data_points(&ht, 2.0);

    return 0;
}
