typedef struct record_list {
    file_record_t** records; // Array of pointers to records
    size_t capacity; // Capacity of the array
    size_t count; // Number of records in the list
} record_list_t;

// Initialize a linked list with a specified initial capacity
void init_record_list(record_list_t* list, size_t initial_capacity) {
    assert(initial_capacity > 0);
    list->records = malloc(sizeof(file_record_t*) * initial_capacity);
    if (list->records == NULL) {
        fprintf(stderr, "Failed to allocate memory for record list\n");
        exit(1);
    }
    list->capacity = initial_capacity;
    list->count = 0;
}

// Add a new record to the linked list
void add_record(record_list_t* list, const char* path, int line_count, int value) {
    assert(path != NULL);
    assert(line_count > 0);
    assert(value >= 0);
    if (list->count == list->capacity) {
        // Resize the array to accommodate more records
        size_t new_capacity = list->capacity * 2;
        file_record_t** new_records = realloc(list->records, sizeof(file_record_t*) * new_capacity);
        if (new_records == NULL) {
            fprintf(stderr, "Failed to resize record list\n");
            exit(1);
        }
        list->records = new_records;
        list->capacity = new_capacity;
    }
    // Create a new record and add it to the list
    file_record_t* new_record = malloc(sizeof(file_record_t));
    if (new_record == NULL) {
        fprintf(stderr, "Failed to allocate memory for new record\n");
        exit(1);
    }
    new_record->path = strdup(path);
    new_record->line_count = line_count;
    new_record->value = value;
    list->records[list->count++] = new_record;
}

// Remove a record from the linked list by its index
void remove_record(record_list_t* list, size_t index) {
    assert(index < list->count);
    file_record_t* record = list->records[index];
    free(record->path);
    free(record);
    list->count--;
}

// Release all memory allocated for the linked list
void release_record_list(record_list_t* list) {
    for (size_t i = 0; i < list->count; i++) {
        file_record_t* record = list->records[i];
        free(record->path);
        free(record);
    }
    free(list->records);
}
