['```rust
use std::net::{TcpListener, TcpStream};
use std::io::prelude::*;
use std::thread;
use std::sync::mpsc::channel;
use std::time::Duration;

struct MediaStream {
    url: String,
    bitrate: u32,
}

impl MediaStream {
    fn new(url: &str) -> Self {
        Self {
            url: url.to_string(),
            bitrate: 0,
        }
    }

    fn set_bitrate(&mut self, bitrate: u32) {
        self.bitrate = bitrate;
    }
}

struct MediaPlayer {
    stream: MediaStream,
    buffer: Vec<u8>,
    buffer_size: usize,
    buffer_index: usize,
    is_playing: bool,
    is_paused: bool,
    is_stopped: bool,
}

impl MediaPlayer {
    fn new(stream: &MediaStream) -> Self {
        Self {
            stream: stream.clone(),
            buffer: Vec::new(),
            buffer_size: 0,
            buffer_index: 0,
            is_playing: false,
            is_paused: false,
            is_stopped: true,
        }
    }

    fn play(&mut self) {
        if !self.is_playing && !self.is_paused && !self.is_stopped {
            self.is_playing = true;
            thread::spawn(move || {
                let mut stream = TcpStream::connect(&self.stream.url).unwrap();
                loop {
                    if self.is_paused {
                        thread::sleep(Duration::from_secs(1));
                        continue;
                    }
                    if self.is_stopped {
                        break;
                    }
                    let mut buffer = [0u8; 4096];
                    match stream.read(&mut buffer) {
                        Ok(size) => {
                            if size > 0 {
                                self.buffer.extend_from_slice(&buffer[..size]);
                                self.buffer_index += size;
                            } else {
                                break;
                            }
                        }
                        Err(e) => {
                            println!("Error reading from stream: {}", e);
                            break;
                        }
                    }
                }
            });
        }
    }

    fn pause(&mut self) {
        if self.is_playing && !self.is_paused && !self.is_stopped {
            self.is_paused = true;
        }
    }

    fn stop(&mut self) {
        if self.is_playing || self.is_paused || !self.is_stopped {
            self.is_playing = false;
            self.is_paused = false;
            self.is_stopped = true;
        }
    }

    fn seek(&mut self, position: usize) {
        if self.buffer_index > position && !self.is_paused && !self.is_stopped {
            self.buffer_index = position;
        }
    }
}

fn main() {
    let stream = MediaStream::new("http://example.com/stream");
    let mut player = MediaPlayer::new(&stream);
    player.play();
    loop {
        if player.is_paused || player.is_stopped {
            break;
        }
        println!("Buffer size: {}", player.buffer_size);
        thread::sleep(Duration::from_secs(1));
    }
}
```
