#include <assert.h>

// Custom hash table implementation for fast lookups
struct HashTable {
    int size;
    struct Node** buckets;
};

struct Node {
    char* key;
    void* value;
    struct Node* next;
};

void initHashTable(struct HashTable* ht, int size) {
    ht->size = size;
    ht->buckets = (struct Node**)malloc(sizeof(struct Node*) * size);
    memset(ht->buckets, 0, sizeof(struct Node*) * size);
}

void insertHashTable(struct HashTable* ht, char* key, void* value) {
    int index = hashCode(key) % ht->size;
    struct Node* node = (struct Node*)malloc(sizeof(struct Node));
    node->key = key;
    node->value = value;
    node->next = ht->buckets[index];
    ht->buckets[index] = node;
}

void* searchHashTable(struct HashTable* ht, char* key) {
    int index = hashCode(key) % ht->size;
    struct Node* node = ht->buckets[index];
    while (node != NULL && strcmp(node->key, key) != 0) {
        node = node->next;
    }
    return node == NULL ? NULL : node->value;
}

void deleteHashTable(struct HashTable* ht, char* key) {
    int index = hashCode(key) % ht->size;
    struct Node** node = &ht->buckets[index];
    while (*node != NULL && strcmp((*node)->key, key) != 0) {
        node = &(*node)->next;
    }
    if (*node == NULL) return;
    *node = (*node)->next;
}

int hashCode(char* key) {
    int hash = 0;
    for (int i = 0; i < strlen(key); i++) {
        hash += key[i];
    }
    return hash % 1000000007;
}

