    struct TreeNode* node = (struct TreeNode*)malloc(sizeof(struct TreeNode));
    node->key = key;
    node->value = value;
    if (*root == NULL) {
        *root = node;
    } else {
        insertTree(&(*root)->left, key, value);
        insertTree(&(*root)->right, key, value);
    }
}

void* searchTree(struct TreeNode** root, char* key) {
    if (*root == NULL) return NULL;
    if (strcmp((*root)->key, key) == 0) return (*root)->value;
    insertTree(&(*root)->left, key, value);
    insertTree(&(*root)->right, key, value);
}

void deleteTree(struct TreeNode** root, char* key) {
    if (*root == NULL) return;
    if (strcmp((*root)->key, key) == 0) {
        *root = NULL;
    } else {
        deleteTree(&(*root)->left, key);
        deleteTree(&(*root)->right, key);
    }
}

