// Function to insert a new record into the collection
void insert_record(char *key, struct record *record) {
    // Check if the key already exists in the map
    if (get_record(key) != NULL) {
        return;
    }

    // Allocate memory for the new record and its associated string
    struct record *new_record = malloc(sizeof(struct record));
    char *new_string = malloc(strlen(record->string) + 1);
    strcpy(new_string, record->string);

    // Initialize the new record with the given information
    new_record->id = record->id;
    new_record->value = record->value;
    new_record->string = new_string;
    new_record->timestamp = time(NULL);

    // Add the new record to the map
    struct record_map *new_map = malloc(sizeof(struct record_map));
    new_map->key = key;
    new_map->record = new_record;
    pthread_mutex_lock(&map_mutex);
    map_insert(new_map);
    pthread_mutex_unlock(&map_mutex);
}

// Function to delete a record from the collection by its key
void delete_record(char *key) {
    // Check if the key exists in the map
    struct record_map *map = get_record(key);
    if (map == NULL) {
        return;
    }

    // Remove the record from the map and free its associated memory
    pthread_mutex_lock(&map_mutex);
    map_remove(map);
    free(map->record->string);
    free(map->record);
    free(map);
    pthread_mutex_unlock(&map_mutex);
}

// Function to retrieve a record from the collection by its key
