void concurrent_operation(char *key, struct record *new_record) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&map_mutex);

    // Check if the key exists in the map
    struct record_map *map = get_record_map(key);
    if (map == NULL) {
        // Insert a new record if it does not exist
        insert_record(key, new_record);
    } else {
        // Update an existing record if it exists
        update_record(key, new_record);
    }

    // Unlock the mutex to allow other threads to access the map
    pthread_mutex_unlock(&map_mutex);
}

