void optimize_memory_access(char *key, struct record *new_record) {
    // Check if the key exists in the map
    struct record_map *map = get_record_map(key);
    if (map == NULL) {
        // Insert a new record if it does not exist
        insert_record(key, new_record);
    } else {
        // Update an existing record if it exists
        update_record(key, new_record);
    }
}

