void periodic_data_pruning() {
    // Check if the data is outdated
    struct record_map *map = get_oldest_record();
    while (map != NULL && map->record->timestamp < time(NULL) - DATA_LIFETIME) {
        delete_record(map->key);
        map = get_oldest_record();
    }
}

