#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <assert.h>

// Custom data structure for storing records
typedef struct Record {
    int id;
    float value;
    char *name;
    time_t timestamp;
    void *metadata;
} Record;

// Custom indexing mechanism for efficient key-based lookups
typedef struct IndexNode {
    char *key;
    Record *record;
    struct IndexNode *next;
} IndexNode;

// Custom locking mechanism for concurrent access to the data store
typedef struct Lock {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} Lock;

// Global variables for managing the data store and indexing structure
static Record *records = NULL;
static IndexNode *index = NULL;
static int num_records = 0;
static int max_records = 0;
static Lock lock;

// Function to initialize the data store and indexing structure
void init(int max_records) {
    // Allocate memory for the records array
    records = (Record *)malloc(max_records * sizeof(Record));
    assert(records != NULL);

    // Initialize the locking mechanism
    pthread_mutex_init(&lock.mutex, NULL);
    pthread_cond_init(&lock.cond, NULL);

    // Initialize the indexing structure
    index = (IndexNode *)malloc(max_records * sizeof(IndexNode));
    assert(index != NULL);
}

// Function to add a new record to the data store
void add_record(int id, float value, char *name, time_t timestamp, void *metadata) {
    // Acquire the lock for writing to the data store
    pthread_mutex_lock(&lock.mutex);

    // Check if the data store is full
    if (num_records == max_records) {
        // If so, double the size of the records array and rebuild the indexing structure
        int new_max_records = max_records * 2;
        Record *new_records = (Record *)realloc(records, new_max_records * sizeof(Record));
        assert(new_records != NULL);
        records = new_records;
        IndexNode *new_index = (IndexNode *)realloc(index, new_max_records * sizeof(IndexNode));
        assert(new_index != NULL);
        index = new_index;
        max_records = new_max_records;
    }

    // Add the new record to the data store and indexing structure
    records[num_records].id = id;
    records[num_records].value = value;
    records[num_records].name = name;
    records[num_records].timestamp = timestamp;
    records[num_records].metadata = metadata;
    index[num_records].key = name;
    index[num_records].record = &records[num_records];
    num_records++;

    // Release the lock for writing to the data store
    pthread_mutex_unlock(&lock.mutex);
}

// Function to retrieve a record from the data store by its unique string identifier
Record *get_record(char *name) {
    // Acquire the lock for reading from the data store
    pthread_mutex_lock(&lock.mutex);

    // Search for the record in the indexing structure
    IndexNode *node = index;
    while (node != NULL && strcmp(node->key, name) != 0) {
        node = node->next;
    }

    // If the record is found, return it
    if (node != NULL) {
        Record *record = node->record;
        pthread_mutex_unlock(&lock.mutex);
        return record;
    }

    // Otherwise, return NULL
    pthread_mutex_unlock(&lock.mutex);
    return NULL;
}

// Function to update an existing record in the data store with new metadata
void update_record(char *name, void *metadata) {
    // Acquire the lock for writing to the data store
    pthread_mutex_lock(&lock.mutex);

    // Search for the record in the indexing structure
    IndexNode *node = index;
    while (node != NULL && strcmp(node->key, name) != 0) {
        node = node->next;
    }

    // If the record is found, update its metadata and release the lock
    if (node != NULL) {
        Record *record = node->record;
        record->metadata = metadata;
        pthread_mutex_unlock(&lock.mutex);
    }

    // Otherwise, do nothing
    else {
        pthread_mutex_unlock(&lock.mutex);
    }
}

// Function to remove outdated entries from the data store based on their timestamp
void prune(time_t timestamp) {
    // Acquire the lock for writing to the data store
    pthread_mutex_lock(&lock.mutex);

    // Iterate through the records and remove any that are older than the specified timestamp
    int i = 0;
    while (i < num_records) {
        if (records[i].timestamp < timestamp) {
            // Remove the record from the data store and indexing structure
            Record *record = &records[i];
            free(record->name);
            free(record->metadata);
            index[i] = index[num_records - 1];
            num_records--;
        } else {
            i++;
        }
    }

    // Release the lock for writing to the data store
    pthread_mutex_unlock(&lock.mutex);
}

// Function to handle memory allocation failures and optimize resource usage through periodic memory defragmentation
void *alloc(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        // Handle memory allocation failure by periodically defragmenting the data store
        pthread_mutex_lock(&lock.mutex);
        prune(time(NULL));
        ptr = realloc(records, max_records * sizeof(Record));
        assert(ptr != NULL);
        records = (Record *)ptr;
        index = (IndexNode *)realloc(index, max_records * sizeof(IndexNode));
        assert(index != NULL);
        pthread_mutex_unlock(&lock.mutex);
    }
    return ptr;
}

// Function to handle memory deallocation and ensure graceful shutdown of the data store
void free(void *ptr) {
    // Acquire the lock for writing to the data store
    pthread_mutex_lock(&lock.mutex);

    // Free the memory allocated for the record
    Record *record = (Record *)ptr;
    free(record->name);
    free(record->metadata);
    index[num_records] = index[num_records - 1];
    num_records--;

    // Release the lock for writing to the data store
    pthread_mutex_unlock(&lock.mutex);
}
```
