    float accuracy;
} data_point;

// Define a linked list node for storing data points
typedef struct data_point_node {
    data_point *data_point;
    struct data_point_node *next;
} data_point_node;

// Define a hash table to store the data points
typedef struct {
    int size;
    data_point_node **buckets;
} data_point_hash_table;

// Initialize the hash table with a given size
void init_data_point_hash_table(data_point_hash_table *ht, int size) {
    ht->size = size;
    ht->buckets = (data_point_node **)malloc(sizeof(data_point_node *) * size);
    for (int i = 0; i < size; i++) {
        ht->buckets[i] = NULL;
    }
}

// Insert a data point into the hash table
void insert_data_point(data_point_hash_table *ht, data_point *dp) {
    int bucket_index = dp->id % ht->size;
    data_point_node *new_node = (data_point_node *)malloc(sizeof(data_point_node));
    new_node->data_point = dp;
    new_node->next = ht->buckets[bucket_index];
    ht->buckets[bucket_index] = new_node;
}

// Delete a data point from the hash table
void delete_data_point(data_point_hash_table *ht, int id) {
    int bucket_index = id % ht->size;
    data_point_node **prev_ptr = &(ht->buckets[bucket_index]);
    while (*prev_ptr != NULL && (*prev_ptr)->data_point->id != id) {
        prev_ptr = &((*prev_ptr)->next);
    }
    if (*prev_ptr == NULL) {
        return;
    }
    data_point_node *to_delete = *prev_ptr;
    *prev_ptr = to_delete->next;
    free(to_delete);
}

// Retrieve a data point from the hash table by its ID
data_point *retrieve_data_point(data_point_hash_table *ht, int id) {
    int bucket_index = id % ht->size;
    data_point_node *curr_node = ht->buckets[bucket_index];
    while (curr_node != NULL && curr_node->data_point->id != id) {
        curr_node = curr_node->next;
    }
    if (curr_node == NULL) {
        return NULL;
    }
    return curr_node->data_point;
}

// Update the timestamp of a data point in the hash table
void update_timestamp(data_point_hash_table *ht, int id) {
    data_point *dp = retrieve_data_point(ht, id);
    if (dp == NULL) {
        return;
    }
    dp->timestamp = time(NULL);
}

// Prune unused data points from the hash table
void prune_unused_data_points(data_point_hash_table *ht, int threshold) {
    for (int i = 0; i < ht->size; i++) {
        data_point_node *curr_node = ht->buckets[i];
        while (curr_node != NULL && curr_node->data_point->accuracy <= threshold) {
            data_point_node *to_delete = curr_node;
            curr_node = curr_node->next;
            free(to_delete);
