// Define mutex for protecting concurrent access to the linked list
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define function for inserting a new data point into the linked list
void insert(data_point *data) {
    // Acquire lock on mutex
    pthread_mutex_lock(&mutex);

    // Create new node for storing data point
    node *new_node = malloc(sizeof(node));
    new_node->data = data;
    new_node->next = NULL;

    // If linked list is empty, set head to new node
    if (head == NULL) {
        head = new_node;
    } else {
        // Otherwise, append new node to end of linked list
        node *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    // Release lock on mutex
    pthread_mutex_unlock(&mutex);
}

// Define function for retrieving a data point from the linked list
data_point *retrieve(int index) {
    // Acquire lock on mutex
    pthread_mutex_lock(&mutex);

    // If linked list is empty, return NULL
    if (head == NULL) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Otherwise, traverse linked list to find data point at specified index
    node *current = head;
    for (int i = 0; i < index; i++) {
        if (current->next == NULL) {
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        current = current->next;
    }

    // Return data point at specified index
    data_point *data = current->data;
    pthread_mutex_unlock(&mutex);
    return data;
}

// Define function for deleting a data point from the linked list
void delete(int index) {
    // Acquire lock on mutex
    pthread_mutex_lock(&mutex);

    // If linked list is empty, do nothing
    if (head == NULL) {
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Otherwise, traverse linked list to find data point at specified index
    node *current = head;
    for (int i = 0; i < index; i++) {
        if (current->next == NULL) {
            pthread_mutex_unlock(&mutex);
            return;
        }
        current = current->next;
    }

    // Remove data point from linked list
    node *to_delete = current;
    current = current->next;
    free(to_delete);

    // If head is now NULL, set new head to next node in linked list
    if (head == to_delete) {
        head = current;
    }

    // Release lock on mutex
    pthread_mutex_unlock(&mutex);
}

// Define function for updating a data point in the linked list
void update(int index, data_point *data) {
    // Acquire lock on mutex
    pthread_mutex_lock(&mutex);

    // If linked list is empty, do nothing
    if (head == NULL) {
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Otherwise, traverse linked list to find data point at specified index
    node *current = head;
    for (int i = 0; i < index; i++) {
        if (current->next == NULL) {
            pthread_mutex_unlock(&mutex);
            return;
        }
        current = current->next;
    }

    // Update data point at specified index with new data
    current->data = data;

    // Release lock on mutex
    pthread_mutex_unlock(&mutex);
}

// Define function for clearing the linked list
void clear() {
    // Acquire lock on mutex
    pthread_mutex_lock(&mutex);

    // If linked list is empty, do nothing
    if (head == NULL) {
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Otherwise, traverse linked list and free each node
    node *current = head;
    while (current != NULL) {
        node *to_delete = current;
        current = current->next;
        free(to_delete);
    }

    // Set head to NULL
    head = NULL;

    // Release lock on mutex
    pthread_mutex_unlock(&mutex);
}

// Define function for retrieving the size of the linked list
int size() {
    // Acquire lock on mutex
    pthread_mutex_lock(&mutex);

    // If linked list is empty, return 0
    if (head == NULL) {
        pthread_mutex_unlock(&mutex);
        return 0;
    }

    // Otherwise, traverse linked list and count nodes
    int size = 0;
    node *current = head;
    while (current != NULL) {
        size++;
        current = current->next;
    }

    // Release lock on mutex
    pthread_mutex_unlock(&mutex);
    return size;
}

// Define function for retrieving the head of the linked list
node *get_head() {
    // Acquire lock on mutex
    pthread_mutex_lock(&mutex);

    // Return head of linked list
    node *head = this->head;

    // Release lock on mutex
    pthread_mutex_unlock(&mutex);
    return head;
}

// Define function for setting the head of the linked list
void set_head(node *new_head) {
    // Acquire lock on mutex
    pthread_mutex_lock(&mutex);

    // Set new head of linked list
    this->head = new_head;

    // Release lock on mutex
    pthread_mutex_unlock(&mutex);
}

// Define function for retrieving the next node in the linked list
node *get_next(int index) {
    // Acquire lock on mutex
    pthread_mutex_lock(&mutex);

    // If linked list is empty, return NULL
    if (head == NULL) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Otherwise, traverse linked list to find node at specified index
    node *current = head;
    for (int i = 0; i < index; i++) {
        if (current->next == NULL) {
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        current = current->next;
    }

    // Return next node in linked list
    node *next = current->next;

    // Release lock on mutex
    pthread_mutex_unlock(&mutex);
    return next;
}

// Define function for setting the next node in the linked list
void set_next(int index, node *new_next) {
    // Acquire lock on mutex
    pthread_mutex_lock(&mutex);

    // If linked list is empty, do nothing
    if (head == NULL) {
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Otherwise, traverse linked list to find node at specified index
    node *current = head;
    for (int i = 0; i < index; i++) {
        if (current->next == NULL) {
            pthread_mutex_unlock(&mutex);
            return;
        }
        current = current->next;
    }

    // Set next node in linked list to new value
    current->next = new_next;

    // Release lock on mutex
    pthread_mutex_unlock(&mutex);
}
