// Define the hash function for the keys
unsigned long hash(int key) {
    return key % 1000000007;
}

// Initialize the database with a specified maximum key limit and number of records
void init_database(Database *db, int max_key, int num_records) {
    db->max_key = max_key;
    db->num_records = num_records;
    db->keys = (int *)malloc(sizeof(int) * num_records);
    db->offsets = (Offset *)malloc(sizeof(Offset) * num_records);
    db->records = (Record *)malloc(sizeof(Record) * num_records);
}

// Populate the keys array with unique values between 1 and the specified maximum key limit
void populate_keys(Database *db) {
    int i;
    for (i = 0; i < db->num_records; i++) {
        db->keys[i] = rand() % db->max_key + 1;
    }
}

// Populate the records array with random integer values within a specified range
void populate_records(Database *db, int min_value, int max_value) {
    int i;
    for (i = 0; i < db->num_records; i++) {
        db->records[i].key = db->keys[i];
        db->records[i].offset = rand() % (max_value - min_value + 1) + min_value;
    }
}

// Implement a hash-based lookup mechanism to efficiently retrieve records based on their keys
Record *lookup(Database *db, int key) {
    unsigned long index = hash(key) % db->num_records;
    while (db->keys[index] != key && index < db->num_records) {
        index++;
    }
    if (index == db->num_records) {
        return NULL;
    } else {
        return &(db->records[index]);
    }
}

// Update or delete a record in the database
void update_record(Database *db, int key, int value) {
    Record *record = lookup(db, key);
    if (record != NULL) {
        record->offset = value;
    } else {
        // Insert a new record with the given key and value
        db->keys[db->num_records] = key;
        db->offsets[db->num_records] = value;
        db->num_records++;
    }
}

// Delete a record from the database
void delete_record(Database *db, int key) {
    Record *record = lookup(db, key);
    if (record != NULL) {
        // Shift all records after the deleted record to fill the gap
        for (int i = record->offset; i < db->num_records - 1; i++) {
            db->keys[i] = db->keys[i + 1];
            db->offsets[i] = db->offsets[i + 1];
        }
        // Decrement the number of records
        db->num_records--;
    }
}

// Clean up the database and free all allocated memory
void cleanup(Database *db) {
    free(db->keys);
    free(db->offsets);
    free(db->records);
}
