// Implement the custom balanced binary tree structure for quick key-based lookups
bst* create_bst() {
    bst* bst = malloc(sizeof(bst));
    if (!bst) {
        printf("Error: Failed to allocate memory for the BST\n");
        exit(1);
    }
    bst->nodes = malloc(sizeof(bst_node*) * INITIAL_CAPACITY);
    if (!bst->nodes) {
        printf("Error: Failed to allocate memory for the BST nodes\n");
        exit(1);
    }
    bst->capacity = INITIAL_CAPACITY;
    bst->count = 0;
    return bst;
}

void insert_bst(bst* bst, data_point* point) {
    if (bst->count == bst->capacity) {
        // Resize the BST if necessary
        bst->capacity *= 2;
        bst->nodes = realloc(bst->nodes, sizeof(bst_node*) * bst->capacity);
        if (!bst->nodes) {
            printf("Error: Failed to resize the BST\n");
            exit(1);
        }
    }
    // Insert the data point into the BST
    bst->nodes[bst->count++] = malloc(sizeof(bst_node));
    if (!bst->nodes[bst->count - 1]) {
        printf("Error: Failed to allocate memory for the BST node\n");
        exit(1);
    }
    bst->nodes[bst->count - 1]->id = point->i;
    bst->nodes[bst->count - 1]->point = point;
}

void traverse_bst(bst* bst) {
    for (size_t i = 0; i < bst->count; i++) {
        // Traverse the BST in-order
        if (i > 0 && bst->nodes[i]->id < bst->nodes[i - 1]->id) {
            printf("Error: The BST is not sorted correctly\n");
            exit(1);
        }
    }
}

// Implement the hash table for fast event type lookups
hash_table* create_hash_table() {
