#include <vector>
#include <unistd.h>
#include <sys/wait.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <signal.h>

using namespace std;

const int MAX_COMMANDS = 100; // maximum number of commands to execute
const int MAX_PROCESSES = 5; // maximum number of processes to run concurrently
const int MAX_ARGUMENTS = 20; // maximum number of arguments per command
const int MAX_INPUT_LENGTH = 1000; // maximum length of input string

struct Command {
    string name; // name of the command
    vector<string> args; // arguments for the command
};

vector<Command> commands; // list of commands to execute
int numCommands = 0; // number of commands in the list
int numProcesses = 0; // number of processes currently running
int numErrors = 0; // number of errors encountered during execution

void executeCommand(const Command& command) {
    if (numProcesses >= MAX_PROCESSES) {
        return;
    }

    pid_t pid = fork();
    if (pid == 0) {
        // child process
        int status = system(command.name.c_str());
        if (status != 0) {
            numErrors++;
        }
        exit(status);
    } else if (pid > 0) {
        // parent process
        numProcesses++;
    } else {
        perror("fork");
    }
}

void executeCommands() {
    for (int i = 0; i < numCommands; i++) {
        const Command& command = commands[i];
        if (command.name == "exit") {
            break;
        }
        executeCommand(command);
    }
}

void handleSignal(int signal) {
    // handle SIGINT and SIGTERM signals
    if (signal == SIGINT || signal == SIGTERM) {
        for (int i = 0; i < numProcesses; i++) {
            kill(commands[i].pid, signal);
        }
        exit(1);
    }
}

void cleanup() {
    // clean up resources and handle errors
    if (numErrors > 0) {
        cout << "Error: " << numErrors << " commands failed." << endl;
    }
    for (int i = 0; i < numProcesses; i++) {
        waitpid(commands[i].pid, NULL, WNOHANG);
    }
}

int main() {
    // initialize the list of commands and signal handlers
    commands.reserve(MAX_COMMANDS);
    for (int i = 0; i < MAX_PROCESSES; i++) {
        struct sigaction sa;
        sa.sa_handler = handleSignal;
        sigemptyset(&sa.sa_mask);
        sa.sa_flags = 0;
        if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
            perror("sigaction");
            exit(1);
        }
    }

    // read input from stdin and execute commands
    string line;
    while (getline(cin, line)) {
        if (line.empty()) {
            continue;
        }
        vector<string> args = split(line, ';');
        Command command;
        command.name = args[0];
        for (int i = 1; i < args.size(); i++) {
            command.args.push_back(args[i]);
        }
        commands.push_back(command);
        numCommands++;
    }

    // execute the commands and handle errors
    try {
        executeCommands();
    } catch (const exception& e) {
        cout << "Error: " << e.what() << endl;
    }

    // clean up resources and exit
    cleanup();
    return 0;
}
```
