// Custom hash table implementation
struct HashTable {
    int size;
    struct Node **table;
};

struct Node {
    int key;
    void *value;
    struct Node *next;
};

struct HashTable* createHashTable(int size) {
    struct HashTable *ht = malloc(sizeof(struct HashTable));
    ht->size = size;
    ht->table = calloc(size, sizeof(struct Node*));
    return ht;
}

void destroyHashTable(struct HashTable *ht) {
    for (int i = 0; i < ht->size; i++) {
        struct Node *node = ht->table[i];
        while (node != NULL) {
            struct Node *next = node->next;
            free(node);
            node = next;
        }
    }
    free(ht->table);
    free(ht);
}

void hashTableInsert(struct HashTable *ht, int key, void *value) {
    struct Node **nodePtr = &ht->table[key % ht->size];
    while (*nodePtr != NULL && (*nodePtr)->key != key) {
        nodePtr = &(*nodePtr)->next;
    }
    if (*nodePtr == NULL) {
        *nodePtr = malloc(sizeof(struct Node));
        (*nodePtr)->key = key;
        (*nodePtr)->value = value;
        (*nodePtr)->next = NULL;
    } else {
        (*nodePtr)->value = value;
    }
}

void* hashTableLookup(struct HashTable *ht, int key) {
    struct Node **nodePtr = &ht->table[key % ht->size];
    while (*nodePtr != NULL && (*nodePtr)->key != key) {
        nodePtr = &(*nodePtr)->next;
    }
    if (*nodePtr == NULL) {
        return NULL;
    } else {
        return (*nodePtr)->value;
    }
}

// Custom memory pool implementation
struct MemoryPool {
    int size;
    struct Node **freeList;
};

struct Node {
    void *data;
    struct Node *next;
};

struct MemoryPool* createMemoryPool(int size) {
    struct MemoryPool *mp = malloc(sizeof(struct MemoryPool));
    mp->size = size;
    mp->freeList = calloc(size, sizeof(struct Node*));
    return mp;
}

void destroyMemoryPool(struct MemoryPool *mp) {
    for (int i = 0; i < mp->size; i++) {
        struct Node *node = mp->freeList[i];
        while (node != NULL) {
            struct Node *next = node->next;
            free(node);
            node = next;
        }
    }
    free(mp->freeList);
    free(mp);
}

void* memoryPoolAllocate(struct MemoryPool *mp, int size) {
    struct Node **nodePtr = &mp->freeList[size];
    while (*nodePtr != NULL && (*nodePtr)->data == NULL) {
        nodePtr = &(*nodePtr)->next;
    }
    if (*nodePtr == NULL) {
        return NULL;
    } else {
        void *data = (*nodePtr)->data;
        struct Node *node = malloc(sizeof(struct Node));
        node->data = data;
        node->next = mp->freeList[size];
        mp->freeList[size] = node;
        return data;
    }
}

void memoryPoolDeallocate(struct MemoryPool *mp, void *data) {
    struct Node **nodePtr = &mp->freeList[0];
    while (*nodePtr != NULL && (*nodePtr)->data != data) {
        nodePtr = &(*nodePtr)->next;
    }
    if (*nodePtr == NULL) {
        return;
    } else {
        struct Node *node = malloc(sizeof(struct Node));
        node->data = data;
        node->next = mp->freeList[0];
        mp->freeList[0] = node;
    }
}

