    int strLen = strlen(str);
    if (strLen < sizeLimit) {
        // Append a slash to the end of the input string
        char *newStr = malloc((strLen + 1) * sizeof(char));
        memcpy(newStr, str, strLen);
        newStr[strLen] = '/';
        newStr[strLen + 1] = '\0';
        return newStr;
    } else {
        // Return NULL if the input string exceeds the size limit
