// Define a doubly-linked list node to store records
typedef struct Node {
    Record* record;
    struct Node* next;
    struct Node* prev;
} Node;

// Define a function to allocate and initialize memory for a new record
Record* create_record(int integer_value, double double_value, char* string_value) {
    // Allocate memory for the record
    Record* record = malloc(sizeof(Record));
    if (record == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for record\n");
        return NULL;
    }

    // Initialize the record fields
    record->integer_value = integer_value;
    record->double_value = double_value;
    record->string_value = string_value;

    return record;
}

// Define a function to allocate and initialize memory for a new node in the doubly-linked list
Node* create_node(Record* record) {
    // Allocate memory for the node
    Node* node = malloc(sizeof(Node));
    if (node == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for node\n");
        return NULL;
    }

    // Initialize the node fields
    node->record = record;
    node->next = NULL;
    node->prev = NULL;

    return node;
}

// Define a function to insert a new record into the doubly-linked list
void insert_record(Node** head, Record* record) {
    // Allocate memory for the new node
    Node* new_node = create_node(record);
    if (new_node == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for new node\n");
        return;
    }

    // Insert the new node at the beginning of the list
    new_node->next = *head;
    if (*head != NULL) {
        (*head)->prev = new_node;
    }
    *head = new_node;
}

// Define a function to delete a record from the doubly-linked list
void delete_record(Node** head, Record* record) {
    // Find the node containing the record
    Node* current = *head;
    while (current != NULL && current->record != record) {
        current = current->next;
    }

    // If the record was found, delete it from the list
    if (current != NULL) {
        // Remove the node from the list
        if (current == *head) {
            *head = (*head)->next;
        }
        if (current->prev != NULL) {
            current->prev->next = current->next;
        }
        if (current->next != NULL) {
            current->next->prev = current->prev;
        }

        // Free the node and its record
        free(current);
    }
}

// Define a function to traverse the doubly-linked list in both directions
void traverse_list(Node* head, void (*visit)(Record*)) {
    Node* current = head;
    while (current != NULL) {
        visit(current->record);
        current = current->next;
    }
}

// Define a function to export the records in the doubly-linked list to a binary file
void export_records(Node* head, FILE* file) {
    // Write the number of records to the file
    fwrite(&head, sizeof(int), 1, file);

    // Write each record to the file
    Node* current = head;
    while (current != NULL) {
        fwrite(current->record, sizeof(Record), 1, file);
        current = current->next;
    }
}

// Define a function to load records from a binary file into memory
void load_records(Node** head, FILE* file) {
    // Read the number of records from the file
    int num_records;
    fread(&num_records, sizeof(int), 1, file);

    // Allocate memory for the records and read them from the file
    Node* current = *head;
    while (current != NULL) {
        Record* record = malloc(sizeof(Record));
        if (record == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for record\n");
            return;
        }
        fread(record, sizeof(Record), 1, file);
        insert_record(&current, record);
    }
}

// Define a function to handle concurrent updates to the record list without data corruption
void update_records(Node** head, void (*update)(Record*)) {
    // Lock the list for writing
    pthread_mutex_lock(&list_mutex);

    // Update each record in the list
    Node* current = *head;
    while (current != NULL) {
        update(current->record);
        current = current->next;
    }

    // Unlock the list for writing
    pthread_mutex_unlock(&list_mutex);
}

// Define a function to handle concurrent updates to the record list without data corruption (parallel version)
void update_records_parallel(Node** head, void (*update)(Record*)) {
    // Lock the list for writing
    pthread_rwlock_wrlock(&list_rwlock);

    // Update each record in the list
    Node* current = *head;
    while (current != NULL) {
        update(current->record);
        current = current->next;
    }

    // Unlock the list for writing
    pthread_rwlock_unlock(&list_rwlock);
}

// Define a function to handle concurrent reads from the record list without data corruption
void read_records(Node* head, void (*read)(Record*)) {
    // Lock the list for reading
    pthread_mutex_lock(&list_mutex);

    // Read each record in the list
    Node* current = head;
    while (current != NULL) {
        read(current->record);
        current = current->next;
    }

    // Unlock the list for reading
