// Define the record structure
typedef struct {
    int value;
} Record;

// Define the function to allocate and initialize the arrays
void alloc_and_init(int size, int seed) {
    // Allocate memory for the offset array
    long* offset = (long*)aligned_alloc(CACHE_LINE_SIZE, sizeof(long) * size);
    assert(offset != NULL);

    // Initialize the offset array with consecutive integers starting from 0
    for (int i = 0; i < size; i++) {
        offset[i] = i;
    }

    // Allocate memory for the key array
    int* key = (int*)aligned_alloc(CACHE_LINE_SIZE, sizeof(int) * size);
    assert(key != NULL);

    // Initialize the key array with consecutive integers starting from 0
    for (int i = 0; i < size; i++) {
        key[i] = i;
    }

    // Allocate memory for the record array
    Record* record = (Record*)aligned_alloc(CACHE_LINE_SIZE, sizeof(Record) * size);
    assert(record != NULL);

    // Populate the record array with random integers within a specified range
    srand(seed);
    for (int i = 0; i < size; i++) {
        record[i].value = rand() % 100;
    }

    // Log allocation details for debugging purposes
    printf("Allocated memory for offset array: %p\n", offset);
    printf("Allocated memory for key array: %p\n", key);
    printf("Allocated memory for record array: %p\n", record);

    // Integrate with external configuration management service to fetch initial seed values for random number generation
    int config_seed = get_config_value(CONFIG_SEED);
    if (config_seed != -1) {
        srand(config_seed);
    }

    // Handle potential network delays or failures during configuration retrieval gracefully
    while (true) {
        try {
            config_seed = get_config_value(CONFIG_SEED);
            if (config_seed != -1) {
                srand(config_seed);
                break;
            }
        } catch (NetworkException e) {
            // Log the exception and retry after a delay
            printf("Caught NetworkException: %s\n", e.what());
            sleep(RETRY_DELAY);
        }
