// Define a function to initialize a new collection with a specified capacity
Collection* collection_init(size_t capacity) {
    Collection* coll = malloc(sizeof(Collection));
    if (!coll) {
        return NULL;
    }
    coll->entries = malloc(capacity * sizeof(Entry*));
    if (!coll->entries) {
        free(coll);
        return NULL;
    }
    coll->capacity = capacity;
    coll->count = 0;
    return coll;
}

// Define a function to add a new entry to the collection
void collection_add(Collection* coll, int value, char* string) {
    if (coll->count == coll->capacity) {
        // Resize the underlying array if necessary
        size_t new_capacity = coll->capacity * 2;
        Entry** new_entries = realloc(coll->entries, new_capacity * sizeof(Entry*));
        if (!new_entries) {
            return;
        }
        coll->entries = new_entries;
        coll->capacity = new_capacity;
