// Define a struct to represent a record with a single integer field
struct record {
    int value;
};

// Function to allocate memory for an array of records
struct record* allocate_records(int numRecords, int maxSum) {
    // Calculate the total size of the array in bytes
    size_t totalSize = sizeof(struct record) * numRecords;

    // Allocate memory for the array using malloc()
    struct record* records = (struct record*)malloc(totalSize);

    // Check if allocation failed
    if (!records) {
        return NULL;
    }

    // Initialize the value field of each record to a random integer between 0 and 1000 inclusive
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        records[i].value = rand() % 1000;
    }

    // Check if the sum of all values exceeds the maximum sum
    int currentSum = 0;
    for (int i = 0; i < numRecords; i++) {
        currentSum += records[i].value;
        if (currentSum > maxSum) {
            // Reallocate memory to reduce the number of records until the sum is within the limit
            int newNumRecords = numRecords - 1;
            totalSize = sizeof(struct record) * newNumRecords;
            struct record* newRecords = (struct record*)realloc(records, totalSize);
            if (!newRecords) {
                free(records);
                return NULL;
            }
            records = newRecords;
            numRecords = newNumRecords;
            currentSum -= records[i - 1].value;
        }
    }

    // Return a pointer to the allocated array
    return records;
}

// Function to free memory for an array of records
void free_records(struct record* records) {
    if (records) {
        free(records);
    }
}
