        return NULL;
    }

    // Set the string field to a random value
    sprintf(new_record->string, "%d", value);

    return new_record;
}

// Function to add a new record to the linked list
void add_record(record_node_t** head, int min, int max) {
    // Allocate memory for the new record node
    record_node_t* new_node = malloc(sizeof(record_node_t));
    if (!new_node) {
        printf("Error: Failed to allocate memory for new record node\n");
        return;
    }

    // Initialize the new record with a random integer value and string
    new_node->data = init_record(min, max);
    if (!new_node->data) {
        printf("Error: Failed to initialize new record\n");
        free(new_node);
        return;
    }

    // Add the new node to the linked list
    new_node->next = *head;
    *head = new_node;
}

// Function to update a record's integer value based on its index
void update_record(record_node_t** head, int index, int min, int max) {
    // Check if the index is valid
    if (index < 0 || index >= get_num_records(*head)) {
        printf("Error: Invalid record index\n");
        return;
    }

    // Get the record at the specified index
    record_node_t* current = *head;
    for (int i = 0; i < index; i++) {
        current = current->next;
    }

    // Update the record's integer value with a random value within the range
    int new_value = rand() % (max - min + 1) + min;
    current->data->value = new_value;
}

// Function to serialize the linked list of records into a binary format
void serialize(record_node_t* head, FILE* fp) {
    // Write the number of records to the file
    int num_records = get_num_records(head);
    fwrite(&num_records, sizeof(int), 1, fp);

    // Write each record's integer value and string field to the file
    while (head) {
        fwrite(&head->data->value, sizeof(int), 1, fp);
        fwrite(head->data->string, strlen(head->data->string), 1, fp);
        head = head->next;
    }
}

// Function to deserialize the linked list of records from a binary format
void deserialize(record_node_t** head, FILE* fp) {
    // Read the number of records from the file
    int num_records;
    fread(&num_records, sizeof(int), 1, fp);

    // Allocate memory for the linked list
    *head = malloc(sizeof(record_node_t));
    if (!*head) {
        printf("Error: Failed to allocate memory for record node\n");
        return;
    }

    // Read each record's integer value and string field from the file
    for (int i = 0; i < num_records; i++) {
        int value;
        fread(&value, sizeof(int), 1, fp);
        char* string = malloc(10 * sizeof(char));
        if (!string) {
            printf("Error: Failed to allocate memory for string\n");
            free(*head);
            return;
        }
        fread(string, strlen(string), 1, fp);
        add_record(head, value, string);
    }
}

// Function to export the linked list of records in binary format
void export_binary(record_node_t* head) {
    // Open a file for writing
