    if (!fp) {
        printf("Error: Failed to open file for writing\n");
        return;
    }

    // Write each record's integer value and string field to the file
    while (head) {
        fprintf(fp, "%d %s\n", head->data->value, head->data->string);
        head = head->next;
    }

    // Close the file
    fclose(fp);
}
