            records = (struct record*)realloc(records, sizeof(struct record) * numRecords);
            records[numRecords - 1].value = rand() % 1000;
            sum += records[numRecords - 1].value;
        }
    }

    // Resolve the DNS and get the IP address
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        printf("Error: DNS resolution failed\n");
        return NULL;
    }
    ip_address = (u_char*)malloc(sizeof(u_char) * res->ai_addrlen);
    memcpy(ip_address, res->ai_addr, res->ai_addrlen);

    // Clean up memory resources
    free(offsets);
    free(identifiers);
    free(records);
    freeaddrinfo(res);

    return ip_address;
}

