// Define a struct to represent a log entry
struct logEntry {
    double temperature;
    char* sensorName;
};

// Function to allocate memory for the log entries
struct logEntry* allocateLogEntries(int numReadings, int numEntries, double* initialTemperatures, double* finalTemperatures, double maxAverage) {
    // Check if the input parameters are valid
    if (numReadings <= 0 || numEntries <= 0 || initialTemperatures == NULL || finalTemperatures == NULL || maxAverage < 0.0) {
        return NULL;
    }

    // Calculate the total number of bytes needed for the log entries
    size_t totalBytes = sizeof(struct logEntry) * numEntries;

    // Allocate memory for the log entries
    struct logEntry* logEntries = (struct logEntry*)malloc(totalBytes);
    if (logEntries == NULL) {
        return NULL;
    }

    // Initialize the temperature and sensor name fields of each log entry
    for (int i = 0; i < numEntries; i++) {
        logEntries[i].temperature = interpolateTemperature(initialTemperatures, finalTemperatures, i);
        logEntries[i].sensorName = malloc(strlen("Sensor") + 1);
        strcpy(logEntries[i].sensorName, "Sensor");
    }

    // Check if the average temperature exceeds the maximum allowed value
    double averageTemperature = calculateAverageTemperature(logEntries, numEntries);
    while (averageTemperature > maxAverage) {
        // Reallocate memory to reduce the number of log entries
        totalBytes -= sizeof(struct logEntry);
        struct logEntry* newLogEntries = (struct logEntry*)realloc(logEntries, totalBytes);
        if (newLogEntries == NULL) {
            free(logEntries);
            return NULL;
        }
        logEntries = newLogEntries;

        // Recalculate the average temperature
        averageTemperature = calculateAverageTemperature(logEntries, numEntries - 1);
    }

    // Return a pointer to the allocated log entries
    return logEntries;
}

// Function to interpolate the temperature between two points
double interpolateTemperature(double* initialTemperatures, double* finalTemperatures, int index) {
    if (index < 0 || index >= numReadings) {
        return NAN;
    }

    // Calculate the interpolation factor
    double factor = (double)(numReadings - index - 1) / (numReadings - 1);

    // Interpolate the temperature
    return initialTemperatures[index] + factor * (finalTemperatures[index] - initialTemperatures[index]);
}

// Function to calculate the average temperature of a set of log entries
double calculateAverageTemperature(struct logEntry* logEntries, int numEntries) {
    double totalTemperature = 0.0;
    for (int i = 0; i < numEntries; i++) {
        totalTemperature += logEntries[i].temperature;
    }
    return totalTemperature / (double)numEntries;
}
