    struct Session *session = malloc(sizeof(struct Session));
    if (!session) {
        return NULL;
    }
    session->id = id;
    session->timestamp = timestamp;
    session->payload = payload;
    return session;
}

// Function to insert a new session into the hash table
int insertSession(struct HashTable *table, struct Session *session) {
    int index = hashCode(session->id);
    struct Node **node = &table->table[index];
    while (*node != NULL && strcmp((*node)->id, session->id) != 0) {
        node = &(*node)->next;
    }
    if (*node == NULL) {
        *node = malloc(sizeof(struct Node));
        if (!*node) {
            return -1;
        }
        (*node)->id = session->id;
        (*node)->timestamp = session->timestamp;
        (*node)->payload = session->payload;
        (*node)->next = NULL;
    } else {
        // Handle hash collision by chaining nodes together
        struct Node *newNode = malloc(sizeof(struct Node));
        if (!newNode) {
            return -1;
        }
        newNode->id = session->id;
        newNode->timestamp = session->timestamp;
        newNode->payload = session->payload;
        newNode->next = *node;
        *node = newNode;
    }
    return 0;
}

// Function to delete a session from the hash table
int deleteSession(struct HashTable *table, char *id) {
    int index = hashCode(id);
    struct Node **node = &table->table[index];
    while (*node != NULL && strcmp((*node)->id, id) != 0) {
        node = &(*node)->next;
    }
    if (*node == NULL) {
        return -1;
    } else {
