    struct Node **node = &table->table[index];
    while (*node != NULL && strcmp((*node)->id, id) != 0) {
        node = &(*node)->next;
    }
    if (*node == NULL) {
        return NULL;
    } else {
        return (struct Session *)(*node);
    }
}

// Function to serialize a session object to disk
int serializeSession(struct Session *session, char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        return -1;
