    struct HashTable *table = manager->table;
    for (int i = 0; i < table->size; i++) {
        struct Node *node = table->table[i];
        while (node != NULL) {
            serializeSession(node, node->id);
            node = node->next;
        }
    }
    return 0;
}

int recoverSessions(struct PersistenceManager *manager) {
