} Record;

// Define the hash table for key-based lookups
typedef struct {
    int size;
    int capacity;
    Record** records;
} HashTable;

// Define the linked list structure
typedef struct Node {
    Record* record;
    struct Node* next;
} ListNode;

// Define the function to dynamically manage memory for and initialize two arrays: one for 'long' offset values and another for 'int' keys.
void init_memory(HashTable* hash_table, int num_records) {
    // Allocate memory for the record array
    Record* records = (Record*)malloc(num_records * sizeof(Record));
    if (!records) {
        printf("Error: Failed to allocate memory for records.\n");
        return;
    }

    // Initialize the record array with random values within a specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % 100;
        records[i].offset = rand() % 1000000;
    }

    // Allocate memory for the hash table
    hash_table->size = num_records;
    hash_table->capacity = num_records * 2;
    hash_table->records = (Record**)malloc(hash_table->capacity * sizeof(Record*));
    if (!hash_table->records) {
        printf("Error: Failed to allocate memory for hash table.\n");
        return;
    }

    // Initialize the hash table with the record array
    for (int i = 0; i < num_records; i++) {
        hash_table->records[i] = &records[i];
    }
}

// Define the function to support efficient insertion, deletion, and traversal operations.
void insert(HashTable* hash_table, int key) {
    // Check if the key already exists in the hash table
    Record* record = find(hash_table, key);
    if (record != NULL) {
        printf("Error: Key %d already exists in the hash table.\n", key);
        return;
    }

    // Allocate memory for a new record and initialize it with the given key
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        printf("Error: Failed to allocate memory for new record.\n");
        return;
    }
    new_record->key = key;
    new_record->offset = 0;

    // Insert the new record into the hash table
    int index = hash(key, hash_table->capacity);
    ListNode* node = (ListNode*)malloc(sizeof(ListNode));
    if (!node) {
        printf("Error: Failed to allocate memory for list node.\n");
        return;
    }
    node->record = new_record;
    node->next = hash_table->records[index];
    hash_table->records[index] = node;
}

// Define the function to support efficient insertion, deletion, and traversal operations.
void delete(HashTable* hash_table, int key) {
    // Check if the key exists in the hash table
    Record* record = find(hash_table, key);
    if (record == NULL) {
        printf("Error: Key %d does not exist in the hash table.\n", key);
        return;
    }

    // Remove the record from the hash table
    int index = hash(key, hash_table->capacity);
    ListNode* node = hash_table->records[index];
    while (node != NULL && node->record != record) {
        node = node->next;
    }
    if (node == NULL) {
        printf("Error: Failed to find the record in the hash table.\n");
        return;
    }
    ListNode* prev_node = node->prev;
    if (prev_node != NULL) {
        prev_node->next = node->next;
    } else {
        hash_table->records[index] = node->next;
    }
    free(node);
}

// Define the function to support efficient insertion, deletion, and traversal operations.
void traverse(HashTable* hash_table) {
    // Traverse the linked list of records in the hash table
    for (int i = 0; i < hash_table->capacity; i++) {
        ListNode* node = hash_table->records[i];
        while (node != NULL) {
            printf("Key: %d, Offset: %ld\n", node->record->key, node->record->offset);
            node = node->next;
        }
    }
}

// Define the function to implement robust error handling to manage memory allocation failures gracefully.
void handle_error(HashTable* hash_table) {
    // Check if any memory allocation failed
    if (hash_table->records == NULL) {
        printf("Error: Failed to allocate memory for hash table.\n");
        return;
    }

    // Release the memory allocated for the record array and the linked list of records
    free(hash_table->records);
    hash_table->size = 0;
    hash_table->capacity = 0;
}

// Define the function to implement a custom hash table for key-based lookups within the record structures.
int hash(int key, int capacity) {
    return key % capacity;
}

// Define the function to implement a dynamic resizing strategy to handle varying loads efficiently.
void resize(HashTable* hash_table) {
    // Check if the load factor is above a certain threshold
    float load_factor = (float)hash_table->size / (float)hash_table->capacity;
    if (load_factor > 0.75) {
        // Double the capacity of the hash table
        int new_capacity = hash_table->capacity * 2;
        Record** new_records = (Record**)malloc(new_capacity * sizeof(Record*));
        if (!new_records) {
            printf("Error: Failed to allocate memory for new records.\n");
            return;
        }

        // Copy the old records to the new records
        for (int i = 0; i < hash_table->capacity; i++) {
            ListNode* node = hash_table->records[i];
            while (node != NULL) {
                Record* record = node->record;
                int index = hash(record->key, new_capacity);
                ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
                if (!new_node) {
                    printf("Error: Failed to allocate memory for new list node.\n");
                    return;
                }
                new_node->record = record;
                new_node->next = new_records[index];
                new_records[index] = new_node;
                node = node->next;
            }
        }

        // Release the memory allocated for the old records and hash table
        free(hash_table->records);
        hash_table->capacity = new_capacity;
        hash_table->records = new_records;
    }
}

// Define the function to handle out-of-memory situations gracefully.
void handle_oom(HashTable* hash_table) {
    // Check if any memory allocation failed
    if (hash_table->records == NULL) {
        printf("Error: Failed to allocate memory for hash table.\n");
        return;
    }

    // Release the memory allocated for the record array and the linked list of records
    free(hash_table->records);
    hash_table->size = 0;
    hash_table->capacity = 0;
}

// Define the function to periodically check and release unused memory blocks.
void check_and_release(HashTable* hash_table) {
    // Check if any memory block is unused
