int rand_range(int min, int max) {
    return min + (rand() % (max - min));
}

// Define a function to initialize the record list and allocate memory for records
void init_records(node** head, node** tail, int num_records) {
    // Allocate memory for the doubly-linked list
    *head = (node*)malloc(sizeof(node));
    *tail = (node*)malloc(sizeof(node));

    // Initialize the head and tail nodes
    (*head)->next = NULL;
    (*head)->prev = NULL;
    (*tail)->next = NULL;
    (*tail)->prev = NULL;

    // Allocate memory for the record array
    node* current = *head;
    for (int i = 0; i < num_records; i++) {
