        current->value = current->key * 1.5;
        current->aux_value = current->key * 2.5;
        current->string = (char*)malloc(sizeof(char) * 10);
        sprintf(current->string, "Record %d", i + 1);
        current->next = (node*)malloc(sizeof(node));
        current = current->next;
    }

    // Initialize the tail node
    (*tail)->next = NULL;

    // Allocate memory for the hash table
    hash_table* ht = (hash_table*)malloc(sizeof(hash_table));
    ht->size = num_records;
    ht->count = 0;
    ht->buckets = (node**)malloc(sizeof(node*) * num_records);

    // Initialize the hash table buckets
    for (int i = 0; i < num_records; i++) {
        ht->buckets[i] = NULL;
    }
