    new_record->key = key;
    new_record->value = value;
    new_record->aux_value = aux_value;
    new_record->string = string;

    // Insert the record into the doubly-linked list
    node* current = *head;
    while (current->next != NULL) {
        if (key < current->next->key) {
            break;
        }
        current = current->next;
    }
    new_record->prev = current;
    new_record->next = current->next;
    current->next->prev = new_record;
    current->next = new_record;

    // Insert the record into the hash table
    int bucket_index = key % ht->size;
    if (ht->buckets[bucket_index] == NULL) {
        ht->buckets[bucket_index] = new_record;
    } else {
        node* current = ht->buckets[bucket_index];
        while (current->next != NULL) {
            if (key < current->next->key) {
                break;
            }
            current = current->next;
        }
        new_record->prev = current;
        new_record->next = current->next;
        current->next->prev = new_record;
        current->next = new_record;
    }
}

// Define a function to delete a record from the doubly-linked list and hash table
void delete_record(node** head, node** tail, int key) {
    // Find the record in the doubly-linked list
    node* current = *head;
    while (current != NULL && current->key != key) {
        current = current->next;
    }

    // Delete the record from the doubly-linked list
    if (current == NULL) {
        return;
    }
    if (current->prev != NULL) {
        current->prev->next = current->next;
    } else {
        *head = current->next;
