        memmove(policy->table + index, policy->table + index + 1, sizeof(Session *) * (policy->count - index));
    }
}

void eviction_policy_update(EvictionPolicy *policy, Session *session) {
    // Remove the old session from the policy
    eviction_policy_remove(policy, session);

    // Add the new session to the policy
    eviction_policy_add(policy, session);
}

void synchronization_strategy_create(SynchronizationStrategy **strategy) {
    // Allocate memory for the strategy structure
    *strategy = malloc(sizeof(SynchronizationStrategy));

    // Initialize the mutex and condition variables
    pthread_mutex_init(&(*strategy)->mutex, NULL);
    pthread_cond_init(&(*strategy)->cond, NULL);
}

void synchronization_strategy_destroy(SynchronizationStrategy **strategy) {
    // Destroy the mutex and condition variables
    pthread_mutex_destroy(&(*strategy)->mutex);
    pthread_cond_destroy(&(*strategy)->cond);

    // Free the memory for the strategy structure
    free(*strategy);
    *strategy = NULL;
}

void synchronization_strategy_lock(SynchronizationStrategy *strategy) {
    // Lock the mutex
    pthread_mutex_lock(&strategy->mutex);
}

void synchronization_strategy_unlock(SynchronizationStrategy *strategy) {
    // Unlock the mutex
    pthread_mutex_unlock(&strategy->mutex);
}

void synchronization_strategy_wait(SynchronizationStrategy *strategy) {
    // Wait for a condition variable to be signaled
    pthread_cond_wait(&strategy->cond, &strategy->mutex);
}

void synchronization_strategy_signal(SynchronizationStrategy *strategy) {
    // Signal the condition variable
    pthread_cond_signal(&strategy->cond);
}

