void serialization_format_serialize(SerializedSession *session, Session *original_session) {
    // Serialize the session ID and timestamp
    session->session_id = strdup(original_session->session_id);
    session->timestamp = original_session->timestamp;

    // Serialize the payload
    if (original_session->payload != NULL) {
        session->payload = malloc(sizeof(void *) * (*session)->size);
        memcpy(session->payload, original_session->payload, sizeof(void *) * (*session)->count);
    } else {
        session->payload = NULL;
    }
}

void serialization_format_deserialize(SerializedSession *session, Session **original_session) {
    // Allocate memory for the original session structure
    *original_session = malloc(sizeof(Session));

    // Deserialize the session ID and timestamp
    (*original_session)->session_id = strdup(session->session_id);
    (*original_session)->timestamp = session->timestamp;

    // Deserialize the payload
    if (session->payload != NULL) {
        (*original_session)->payload = malloc(sizeof(void *) * (*original_session)->size);
        memcpy((*original_session)->payload, session->payload, sizeof(void *) * (*original_session)->count);
    } else {
        (*original_session)->payload = NULL;
    }
}

