# Read configuration data from a YAML file
with open("config.yaml", "r") as f:
    config = yaml.safe_load(f)

# Define the function to package, tag, and deploy the custom container image
def deploy_image():
    # Package the custom container image using Docker
    subprocess.run(["docker", "build", "-t", config["image_name"], "."])

    # Tag the custom container image with a specific version number
    subprocess.run(["docker", "tag", config["image_name"], f"{config['image_name']}:v{config['version']}"])

    # Deploy the custom container image to the Kubernetes cluster using Helm charts
    subprocess.run(["helm", "upgrade", "--install", "-f", "values.yaml", config["release_name"], f"{config['image_name']}:v{config['version']}"])

# Handle errors gracefully and provide detailed logging for each command executed
try:
    deploy_image()
except subprocess.CalledProcessError as e:
    print(f"Error: {e}")
