    // Create a fleet for each thread
    int num_threads = sysconf(_SC_NPROCESSORS_ONLN);
    struct fleet *fleets = malloc(num_threads * sizeof(struct fleet));
    for (int i = 0; i < num_threads; i++) {
        fleets[i].vehicles = NULL;
        fleets[i].num_vehicles = 0;
    }

    // Create threads to handle API requests and predictive maintenance
    pthread_t api_thread, pm_thread;
    pthread_create(&api_thread, NULL, handle_api_requests, NULL);
    pthread_create(&pm_thread, NULL, handle_predictive_maintenance, NULL);

    // Main loop to handle incoming requests and updates
    while (1) {
        sem_wait(&semaphore);
        struct vehicle *v = NULL;
        switch (request.type) {
            case ADD:
                v = add_vehicle(request.data);
                break;
            case REMOVE:
                remove_vehicle(request.data);
                break;
            case UPDATE:
                update_vehicle(request.data);
                break;
            case EXPORT:
                export_vehicles(request.data);
                break;
            case IMPORT:
                import_vehicles(request.data);
                break;
            case SYNC:
                sync_with_external_system();
                break;
        }
        pthread_mutex_unlock(&mutex);
    }

    // Clean up resources
    sem_destroy(&semaphore);
    pthread_mutex_destroy(&mutex);
    free(fleets);

    return 0;
}

void add_vehicle(struct vehicle *v) {
    // Add the vehicle to the fleet
    struct fleet *f = get_fleet();
    f->vehicles[f->num_vehicles++] = v;
}

void remove_vehicle(struct vehicle *v) {
    // Remove the vehicle from the fleet
    struct fleet *f = get_fleet();
    for (int i = 0; i < f->num_vehicles; i++) {
        if (f->vehicles[i] == v) {
            memmove(&f->vehicles[i], &f->vehicles[i + 1], sizeof(struct vehicle) * (f->num_vehicles - i));
            f->num_vehicles--;
            break;
        }
    }
}

void update_vehicle(struct vehicle *v) {
    // Update the vehicle in the fleet
    struct fleet *f = get_fleet();
    for (int i = 0; i < f->num_vehicles; i++) {
        if (f->vehicles[i] == v) {
            memcpy(&f->vehicles[i], v, sizeof(struct vehicle));
            break;
        }
    }
}

void export_vehicles(char *filename) {
    // Export the vehicles to a CSV file
    struct fleet *f = get_fleet();
    FILE *fp = fopen(filename, "w");
    for (int i = 0; i < f->num_vehicles; i++) {
        fprintf(fp, "%s,%s,%s,%d\n", f->vehicles[i].make, f->vehicles[i].model, f->vehicles[i].registration_number, f->vehicles[i].maintenance_date);
    }
    fclose(fp);
}

void import_vehicles(char *filename) {
    // Import the vehicles from a CSV file
    struct fleet *f = get_fleet();
    FILE *fp = fopen(filename, "r");
    while (!feof(fp)) {
        char line[1024];
        fgets(line, 1024, fp);
        char *token = strtok(line, ",");
        struct vehicle v;
        memset(&v, 0, sizeof(struct vehicle));
        while (token != NULL) {
            if (!strcmp(token, "make")) {
                token = strtok(NULL, ",");
                strncpy(v.make, token, 256);
            } else if (!strcmp(token, "model")) {
                token = strtok(NULL, ",");
                strncpy(v.model, token, 256);
            } else if (!strcmp(token, "registration_number")) {
                token = strtok(NULL, ",");
                strncpy(v.registration_number, token, 10);
            } else if (!strcmp(token, "maintenance_date")) {
                token = strtok(NULL, "\n");
                v.maintenance_date = atoi(token);
            }
            token = strtok(NULL, ",");
        }
        add_vehicle(&v);
    }
    fclose(fp);
}

void sync_with_external_system() {
    // Sync the fleet with an external system
    struct fleet *f = get_fleet();
    for (int i = 0; i < f->num_vehicles; i++) {
        // Send the vehicle data to the external system
        send_data(f->vehicles[i]);
    }
}

