use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;

struct DataPoint {
    value: f64,
    identifier: String,
    timestamp: f32,
}

struct TreeNode {
    data_point: Option<DataPoint>,
    children: HashMap<char, Arc<Mutex<TreeNode>>>,
}

impl TreeNode {
    fn new() -> Self {
        Self {
            data_point: None,
            children: HashMap::new(),
        }
    }

    fn insert(&mut self, identifier: char, data_point: DataPoint) {
        let mut child = Arc::new(Mutex::new(Self::new()));
        child.data_point = Some(data_point);
        self.children.insert(identifier, child);
    }

    fn delete(&mut self, identifier: char) -> Option<DataPoint> {
        if let Some(child) = self.children.remove(&identifier) {
            return child.data_point;
        }
        None
    }

    fn get(&self, identifier: char) -> Option<&Arc<Mutex<TreeNode>>> {
        self.children.get(&identifier)
    }
}

struct DataManager {
    tree: Arc<Mutex<TreeNode>>,
    prune_interval: Duration,
}

impl DataManager {
    fn new() -> Self {
        let tree = Arc::new(Mutex::new(Self::new()));
        Self {
            tree,
            prune_interval: Duration::from_secs(3600), // 1 hour
        }
    }

    fn insert(&self, identifier: char, data_point: DataPoint) {
        let mut tree = self.tree.lock().unwrap();
        tree.insert(identifier, data_point);
    }

    fn delete(&self, identifier: char) -> Option<DataPoint> {
        let mut tree = self.tree.lock().unwrap();
        tree.delete(identifier)
    }

    fn get(&self, identifier: char) -> Option<&Arc<Mutex<TreeNode>>> {
        let mut tree = self.tree.lock().unwrap();
        tree.get(identifier)
    }

    fn prune_outdated(&self) {
        let mut tree = self.tree.lock().unwrap();
        for (_, child) in &mut tree.children {
            if let Some(data_point) = child.data_point.as_ref() {
                if data_point.timestamp < Duration::from_secs(3600) {
                    child.data_point = None;
                }
            }
        }
    }
}

struct HttpClient {
    url: String,
    timeout: u64,
}

impl HttpClient {
    fn new(url: &str, timeout: u64) -> Self {
        Self {
            url: url.to_string(),
            timeout,
        }
    }

    fn get(&self, identifier: char) -> Option<DataPoint> {
        let mut tree = self.tree.lock().unwrap();
        if let Some(child) = tree.get(identifier) {
            return child.data_point;
        }
        None
    }

    fn post(&self, identifier: char, data_point: DataPoint) -> Option<DataPoint> {
        let mut tree = self.tree.lock().unwrap();
        if let Some(child) = tree.get(identifier) {
            child.data_point = Some(data_point);
            return Some(data_point);
        }
        None
    }
}
