    if (current_node == linked_list) {
        linked_list = current_node->next;
    } else {
        node *previous_node = linked_list;
        while (previous_node->next != current_node) {
            previous_node = previous_node->next;
        }
        previous_node->next = current_node->next;
    }

    int bucket_index = hash_table->count % hash_table->size;
    if (hash_table->buckets[bucket_index] == current_node) {
        hash_table->buckets[bucket_index] = current_node->next;
    } else {
        node *current_bucket = hash_table->buckets[bucket_index];
        while (current_bucket->next != current_node) {
            current_bucket = current_bucket->next;
        }
        current_bucket->next = current_node->next;
    }
    hash_table->count--;
}

