// Define the node structure
typedef struct Node {
    double value;
    struct Node* next;
} Node;

// Define the linked list data structure
typedef struct LinkedList {
    Node* head;
    int size;
} LinkedList;

// Define the binary search tree data structure
typedef struct BST {
    Node* root;
    int size;
} BST;

// Function to generate a random double value within a specified range
double generateRandomDouble(double min, double max) {
    return (min + ((max - min) * rand() / RAND_MAX));
}

// Function to insert a new node into the linked list
void insertNode(LinkedList* list, double value) {
    Node* newNode = malloc(sizeof(Node));
    newNode->value = value;
    newNode->next = NULL;

    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    list->size++;
}

// Function to delete a node from the linked list
void deleteNode(LinkedList* list, double value) {
    Node* current = list->head;
    Node* previous = NULL;

    while (current != NULL && current->value != value) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        return;
    }

    if (previous == NULL) {
        list->head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
    list->size--;
}

// Function to traverse the linked list
void traverseList(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        printf("%f ", current->value);
        current = current->next;
    }
    printf("\n");
}

// Function to search for a value in the linked list using binary search tree
void searchList(LinkedList* list, double value) {
    Node* current = list->head;
    while (current != NULL && current->value != value) {
        current = current->next;
    }

    if (current == NULL) {
        printf("Value not found\n");
    } else {
        printf("Value found at index %d\n", current->index);
    }
}

// Function to release unused memory blocks
void releaseMemory(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}

// Main function to demonstrate the use of the data structure
int main() {
    // Initialize the linked list and binary search tree
    LinkedList* list = malloc(sizeof(LinkedList));
    BST* bst = malloc(sizeof(BST));
    list->head = NULL;
    list->size = 0;
    bst->root = NULL;
    bst->size = 0;

    // Generate a random double value within the specified range
    double min = 1.0;
    double max = 10.0;
    double value = generateRandomDouble(min, max);

    // Insert the value into the linked list and binary search tree
    insertNode(list, value);
    insertNode(bst, value);

    // Traverse the linked list and print its contents
    traverseList(list);

    // Search for a value in the linked list using binary search tree
    double searchValue = 5.0;
    searchList(list, searchValue);

    // Release unused memory blocks
    releaseMemory(list);
    releaseMemory(bst);

    return 0;
}
