void insert_event_ll(ll_t *ll, void *value) {
    // Check if the linked list is full
    if (ll->count == ll->size) {
        // If it is full, double the size of the linked list
        ll->size *= 2;
        ll->values = (void **)realloc(ll->values, sizeof(void *) * ll->size);
    }
    // Insert the event into the linked list
    ll->values[ll->count] = value;
    ll->count++;
}

// Function to delete an event from the hash table
void delete_event_hash(hash_table_t *ht, int key) {
    // Find the index of the event in the hash table
    int i = 0;
    while (i < ht->count && ht->keys[i] != key) {
        i++;
    }
    // If the event is found, delete it from the hash table
    if (i < ht->count) {
        ht->count--;
        for (int j = i; j < ht->count; j++) {
            ht->keys[j] = ht->keys[j + 1];
            ht->values[j] = ht->values[j + 1];
        }
    }
}

// Function to delete an event from the binary search tree
void delete_event_bst(bst_t *bst, long key) {
    // Find the index of the event in the binary search tree
    int i = 0;
    while (i < bst->count && bst->keys[i] != key) {
        i++;
    }
    // If the event is found, delete it from the binary search tree
    if (i < bst->count) {
        bst->count--;
        for (int j = i; j < bst->count; j++) {
            bst->keys[j] = bst->keys[j + 1];
            bst->values[j] = bst->values[j + 1];
        }
    }
}

// Function to delete an event from the linked list
void delete_event_ll(ll_t *ll, void *value) {
    // Find the index of the event in the linked list
    int i = 0;
    while (i < ll->count && ll->values[i] != value) {
        i++;
    }
    // If the event is found, delete it from the linked list
    if (i < ll->count) {
        ll->count--;
        for (int j = i; j < ll->count; j++) {
            ll->values[j] = ll->values[j + 1];
        }
    }
}

// Function to retrieve an event from the hash table
custom_event_t *get_event_hash(hash_table_t *ht, int key) {
    // Find the index of the event in the hash table
    int i = 0;
    while (i < ht->count && ht->keys[i] != key) {
        i++;
    }
    // If the event is found, return it
    if (i < ht->count) {
        return ht->values[i];
    } else {
        return NULL;
