    // Allocate memory for the offsets array
    long* offsets = (long*)malloc(numRecords * sizeof(long));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offsets\n");
        return;
    }

    // Initialize the offsets array with random values between 0 and maxBufferSize
    srand(seed);
    for (int i = 0; i < numRecords; i++) {
        offsets[i] = rand() % maxBufferSize;
    }

    // Allocate memory for the records array
    Record* records = (Record*)malloc(numRecords * sizeof(Record));
    if (!records) {
        printf("Error: Failed to allocate memory for records\n");
        free(offsets);
        return;
    }

    // Initialize the records array with random values between 500 and 1500
    srand(seed);
    for (int i = 0; i < numRecords; i++) {
        records[i].value = rand() % 1000 + 500;
        records[i].offset = offsets[i];
        records[i].buffer = (char*)malloc(maxBufferSize * sizeof(char));
        if (!records[i].buffer) {
            printf("Error: Failed to allocate memory for record %d\n", i);
            free(offsets);
            free(records);
            return;
        }
    }

    // Update the integer values of each record to a new random value between 500 and 1500
    srand(seed);
    for (int i = 0; i < numRecords; i++) {
        records[i].value = rand() % 1000 + 500;
    }

    // Sort the records in descending order based on their corresponding integer values
    qsort(records, numRecords, sizeof(Record), compareValues);

    // Free the memory allocated for the offsets and records arrays
    free(offsets);
    for (int i = 0; i < numRecords; i++) {
        free(records[i].buffer);
    }
    free(records);
}

// Comparison function for sorting the records based on their integer values
int compareValues(const void* a, const void* b) {
    Record* recordA = (Record*)a;
    Record* recordB = (Record*)b;
    return recordA->value - recordB->value;
}
