Here is an example of how you could implement the `manage_records` function:
```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <assert.h>

struct Record {
    long* offset;
    int value;
    char processed;
};

void manage_records(long min_offset, long max_offset, int* keys, int key_count) {
    // Check if the input parameters are valid
    assert(min_offset <= max_offset);
    assert(key_count > 0);

    // Allocate memory for the offsets array
    long* offsets = (long*)malloc(sizeof(long) * key_count);
    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        return;
    }

    // Initialize the offsets array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < key_count; i++) {
        offsets[i] = rand() % (max_offset - min_offset + 1) + min_offset;
    }

    // Allocate memory for the keys array
    int* keys = (int*)malloc(sizeof(int) * key_count);
    if (!keys) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        free(offsets);
        return;
    }

    // Initialize the keys array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < key_count; i++) {
        keys[i] = rand() % (max_offset - min_offset + 1) + min_offset;
    }

    // Allocate memory for the records array
    struct Record* records = (struct Record*)malloc(sizeof(struct Record) * key_count);
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize the records array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < key_count; i++) {
        records[i].offset = &offsets[i];
        records[i].value = rand() % (max_offset - min_offset + 1) + min_offset;
        records[i].processed = false;
    }

    // Check if there are any duplicate offsets in the records array
    for (int i = 0; i < key_count; i++) {
        for (int j = i + 1; j < key_count; j++) {
            if (*records[i].offset == *records[j].offset) {
                fprintf(stderr, "Duplicate offset found in records array\n");
                free(offsets);
                free(keys);
                free(records);
                return;
            }
        }
    }

    // Check if there are any duplicate keys in the keys array
    for (int i = 0; i < key_count; i++) {
        for (int j = i + 1; j < key_count; j++) {
            if (keys[i] == keys[j]) {
                fprintf(stderr, "Duplicate key found in keys array\n");
                free(offsets);
                free(keys);
                free(records);
                return;
            }
        }
    }

    // Check if there are any duplicate offsets or keys in the records array
    for (int i = 0; i < key_count; i++) {
        for (int j = i + 1; j < key_count; j++) {
            if (*records[i].offset == *records[j].offset || keys[i] == keys[j]) {
                fprintf(stderr, "Duplicate offset or key found in records array\n");
                free(offsets);
                free(keys);
                free(records);
                return;
            }
        }
    }

    // Free the memory allocated for the offsets and keys arrays
    free(offsets);
    free(keys);

    // Return the records array
    return records;
}
```
