    // Update the integer value of each record to a new random value between 500 and 1500
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 1499 + 500;
    }

    // Free the memory allocated for the offsets and records arrays
    free(offsets);
    free(records);
}

// Comparison function for sorting the records based on their values in descending order
