    data_point->timestamp = (float)now;
}

// Define function to insert a new data point into the linked list
void insert_data_point(data_point_t *data_point, tree_node_t **tree, priority_queue_t **pq) {
    // Allocate memory for new data point
    data_point_t *new_data_point = allocate_memory(sizeof(data_point_t));
    // Initialize new data point's timestamp to the current system time
    init_data_point(new_data_point);
    // Copy values from input data point into new data point
    new_data_point->value = data_point->value;
    new_data_point->string = data_point->string;
    // Insert new data point into linked list
    new_data_point->next = *tree;
    *tree = new_data_point;
    // Insert new data point into priority queue
    priority_queue_t *new_pq = allocate_memory(sizeof(priority_queue_t));
    new_pq->timestamp = new_data_point->timestamp;
    new_pq->data_point = new_data_point;
    new_pq->next = *pq;
    *pq = new_pq;
}

// Define function to delete a data point from the linked list and priority queue
void delete_data_point(data_point_t *data_point, tree_node_t **tree, priority_queue_t **pq) {
    // Find data point in linked list
    data_point_t *current = *tree;
    while (current != NULL && current->next != data_point) {
        current = current->next;
    }
    if (current == NULL) {
        return;
    }
    // Remove data point from linked list
    current->next = data_point->next;
    // Remove data point from priority queue
    priority_queue_t *current_pq = *pq;
    while (current_pq != NULL && current_pq->data_point != data_point) {
        current_pq = current_pq->next;
    }
    if (current_pq == NULL) {
        return;
    }
    current_pq->next = current_pq->next->next;
}

