#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <assert.h>

// Define a struct to represent a point in 2D space
struct point {
    int x;
    int y;
};

// Define a struct to represent a record with an int value, double value, char string identifier, and a reference to a struct point
struct record {
    int value;
    double dvalue;
    char *identifier;
    struct point location;
};

// Define a custom hash table for key-based lookups of records
struct hash_table {
    struct record **records;
    size_t capacity;
    size_t size;
};

// Function to create a new hash table with the given capacity
struct hash_table *create_hash_table(size_t capacity) {
    struct hash_table *ht = malloc(sizeof(struct hash_table));
    ht->records = calloc(capacity, sizeof(struct record *));
    ht->capacity = capacity;
    ht->size = 0;
    return ht;
}

// Function to insert a new record into the hash table
void insert_record(struct hash_table *ht, struct record *rec) {
    // Calculate the hash value for the record's identifier
    size_t hash = strlen(rec->identifier) % ht->capacity;

    // Check if there is already a record with the same identifier in the table
    while (ht->records[hash] != NULL && strcmp(ht->records[hash]->identifier, rec->identifier) == 0) {
        hash = (hash + 1) % ht->capacity;
    }

    // Insert the record into the table at the calculated index
    ht->records[hash] = rec;
    ht->size++;
}

// Function to delete a record from the hash table
void delete_record(struct hash_table *ht, struct record *rec) {
    // Calculate the hash value for the record's identifier
    size_t hash = strlen(rec->identifier) % ht->capacity;

    // Check if there is a record with the same identifier in the table
    while (ht->records[hash] != NULL && strcmp(ht->records[hash]->identifier, rec->identifier) == 0) {
        // If the record is found, delete it from the table
        ht->records[hash] = NULL;
        ht->size--;
        break;
    }
}

// Function to retrieve a record from the hash table using its identifier
struct record *get_record(struct hash_table *ht, char *identifier) {
    // Calculate the hash value for the identifier
    size_t hash = strlen(identifier) % ht->capacity;

    // Check if there is a record with the same identifier in the table
    while (ht->records[hash] != NULL && strcmp(ht->records[hash]->identifier, identifier) == 0) {
        return ht->records[hash];
    }

    // If no record is found, return NULL
    return NULL;
}

// Function to traverse all records in the hash table and perform a callback function on each one
void traverse_records(struct hash_table *ht, void (*callback)(struct record *)) {
    for (size_t i = 0; i < ht->capacity; i++) {
        if (ht->records[i] != NULL) {
            callback(ht->records[i]);
        }
    }
}

// Function to handle memory allocation failures and periodic memory optimization
void manage_memory(struct hash_table *ht, size_t capacity) {
    // Check if the current capacity is less than half of the maximum capacity
    if (ht->capacity < capacity / 2) {
        // If so, reallocate the records array to a smaller size
        ht->records = realloc(ht->records, sizeof(struct record *) * capacity);
        ht->capacity = capacity;
    }

    // Check if there are any unused memory blocks in the table
    for (size_t i = 0; i < ht->capacity; i++) {
        if (ht->records[i] == NULL) {
            // If so, release them to free up memory
            ht->records[i] = realloc(ht->records[i], sizeof(struct record *));
        }
    }
}

// Function to handle the char string pool for efficient reuse and handling exhaustion gracefully
void manage_string_pool(struct hash_table *ht, size_t capacity) {
    // Define a struct to represent a char string pool with a fixed size
    struct string_pool {
        char **strings;
        size_t capacity;
        size_t size;
    };

    // Create a new string pool with the given capacity
    struct string_pool *sp = malloc(sizeof(struct string_pool));
    sp->strings = calloc(capacity, sizeof(char *));
    sp->capacity = capacity;
    sp->size = 0;

    // Function to insert a new char string into the pool
    void insert_string(struct string_pool *sp, char *str) {
        // Calculate the hash value for the string
        size_t hash = strlen(str) % sp->capacity;

        // Check if there is already a string with the same content in the pool
        while (sp->strings[hash] != NULL && strcmp(sp->strings[hash], str) == 0) {
            hash = (hash + 1) % sp->capacity;
        }

        // Insert the string into the pool at the calculated index
        sp->strings[hash] = str;
        sp->size++;
    }

    // Function to delete a char string from the pool
    void delete_string(struct string_pool *sp, char *str) {
        // Calculate the hash value for the string
        size_t hash = strlen(str) % sp->capacity;

        // Check if there is a string with the same content in the pool
        while (sp->strings[hash] != NULL && strcmp(sp->strings[hash], str) == 0) {
            // If the string is found, delete it from the pool
            sp->strings[hash] = NULL;
            sp->size--;
            break;
        }
    }

    // Function to retrieve a char string from the pool using its content
    char *get_string(struct string_pool *sp, char *str) {
        // Calculate the hash value for the string
        size_t hash = strlen(str) % sp->capacity;

        // Check if there is a string with the same content in the pool
        while (sp->strings[hash] != NULL && strcmp(sp->strings[hash], str) == 0) {
            return sp->strings[hash];
        }

        // If no string is found, return NULL
        return NULL;
    }
}
