void init_network_monitoring(size_t num_devices, size_t num_events, size_t num_statuses) {
    // Allocate memory for the device array and initialize each object with default values
    device *devices = (device *)malloc(num_devices * sizeof(device));
    if (!devices) {
        printf("Error: Failed to allocate memory for devices\n");
        return;
    }
    for (size_t i = 0; i < num_devices; i++) {
        strcpy(devices[i].id, "");
        devices[i].timestamp = 0;
        devices[i].events = NULL;
    }

    // Allocate memory for the event array and initialize each object with default values
    event_item *events = (event_item *)malloc(num_events * sizeof(event_item));
    if (!events) {
        printf("Error: Failed to allocate memory for events\n");
        free(devices);
        return;
    }
    for (size_t i = 0; i < num_events; i++) {
        events[i].timestamp = 0;
        events[i].severity = 0.0;
        strcpy(events[i].category, "");
    }

    // Allocate memory for the status array and initialize each object with default values
    status *statuses = (status *)malloc(num_statuses * sizeof(status));
    if (!statuses) {
        printf("Error: Failed to allocate memory for statuses\n");
        free(devices);
        free(events);
        return;
    }
    for (size_t i = 0; i < num_statuses; i++) {
        statuses[i].online = false;
        statuses[i].latency = 0.0;
    }

    // Allocate memory for the indices, weights, and status arrays
    size_t *indices = (size_t *)malloc(num_devices * sizeof(size_t));
    if (!indices) {
        printf("Error: Failed to allocate memory for indices\n");
        free(devices);
        free(events);
        free(statuses);
        return;
    }
    float *weights = (float *)malloc(num_devices * sizeof(float));
    if (!weights) {
        printf("Error: Failed to allocate memory for weights\n");
        free(indices);
        free(devices);
        free(events);
        free(statuses);
        return;
    }
    status *status_array = (status *)malloc(num_devices * sizeof(status));
    if (!status_array) {
        printf("Error: Failed to allocate memory for status array\n");
        free(indices);
        free(weights);
        free(devices);
        free(events);
        free(statuses);
        return;
    }

    // Initialize the indices, weights, and status arrays with default values
    for (size_t i = 0; i < num_devices; i++) {
        indices[i] = 0;
        weights[i] = 1.0;
        status_array[i].online = false;
        status_array[i].latency = 0.0;
    }

    // Log the start and end of the operation to a file named "resource_usage.log" in the current directory
    FILE *log_file = fopen("resource_usage.log", "a");
    if (!log_file) {
        printf("Error: Failed to open log file\n");
        free(indices);
        free(weights);
        free(status_array);
        return;
    }
    fprintf(log_file, "Starting network monitoring system with %zu devices, %zu events, and %zu statuses\n", num_devices, num_events, num_statuses);
    fclose(log_file);
}
