// Custom object structure
typedef struct {
    char* key;
    int value;
    float fvalue;
} custom_object_t;

// Hash table implementation for storing custom objects
typedef struct {
    custom_object_t** buckets;
    size_t num_buckets;
    size_t load_factor;
    pthread_mutex_t* mutexes;
} hash_table_t;

// Initialize a new hash table with the given number of buckets and load factor
hash_table_t* hash_table_init(size_t num_buckets, float load_factor) {
    // Allocate memory for the hash table structure and its mutexes
    hash_table_t* table = malloc(sizeof(hash_table_t));
    table->mutexes = calloc(num_buckets, sizeof(pthread_mutex_t));

    // Initialize the buckets array with NULL pointers
    table->buckets = calloc(num_buckets, sizeof(custom_object_t*));

    // Set the number of buckets and load factor
    table->num_buckets = num_buckets;
    table->load_factor = load_factor;

    return table;
}

// Insert a new custom object into the hash table
void hash_table_insert(hash_table_t* table, char* key, int value, float fvalue) {
    // Calculate the hash code for the given key
    size_t hash = hash_code(key);

    // Acquire a mutex for the corresponding bucket
    pthread_mutex_lock(&table->mutexes[hash % table->num_buckets]);

    // Check if there is already an object with the same key in the table
    custom_object_t* obj = hash_table_get(table, key);
    if (obj != NULL) {
        // If so, update its value and release the mutex
        obj->value = value;
        obj->fvalue = fvalue;
        pthread_mutex_unlock(&table->mutexes[hash % table->num_buckets]);
    } else {
        // Otherwise, create a new object and insert it into the table
        custom_object_t* new_obj = malloc(sizeof(custom_object_t));
        new_obj->key = key;
        new_obj->value = value;
        new_obj->fvalue = fvalue;
        table->buckets[hash % table->num_buckets] = new_obj;
        pthread_mutex_unlock(&table->mutexes[hash % table->num_buckets]);
    }
}

// Delete a custom object from the hash table using its key
void hash_table_delete(hash_table_t* table, char* key) {
    // Calculate the hash code for the given key
    size_t hash = hash_code(key);

    // Acquire a mutex for the corresponding bucket
    pthread_mutex_lock(&table->mutexes[hash % table->num_buckets]);

    // Check if there is an object with the same key in the table
    custom_object_t* obj = hash_table_get(table, key);
    if (obj != NULL) {
        // If so, delete it and release the mutex
        free(obj);
        table->buckets[hash % table->num_buckets] = NULL;
        pthread_mutex_unlock(&table->mutexes[hash % table->num_buckets]);
    } else {
        // Otherwise, release the mutex and do nothing
        pthread_mutex_unlock(&table->mutexes[hash % table->num_buckets]);
    }
}

// Retrieve a custom object from the hash table using its key
custom_object_t* hash_table_get(hash_table_t* table, char* key) {
    // Calculate the hash code for the given key
    size_t hash = hash_code(key);

    // Acquire a mutex for the corresponding bucket
    pthread_mutex_lock(&table->mutexes[hash % table->num_buckets]);

    // Check if there is an object with the same key in the table
    custom_object_t* obj = table->buckets[hash % table->num_buckets];
    if (obj != NULL && strcmp(obj->key, key) == 0) {
        // If so, return it and release the mutex
        pthread_mutex_unlock(&table->mutexes[hash % table->num_buckets]);
        return obj;
    } else {
        // Otherwise, release the mutex and return NULL
        pthread_mutex_unlock(&table->mutexes[hash % table->num_buckets]);
        return NULL;
    }
}

// Release memory for a hash table
void hash_table_destroy(hash_table_t* table) {
    // Free the buckets array and its mutexes
    free(table->buckets);
    free(table->mutexes);

    // Free the hash table structure itself
    free(table);
}
