    btree_node **nodes;
    int size;
} btree;

// Define a priority queue to prioritize data points for periodic data pruning
typedef struct {
    data_point *data;
    int size;
} priority_queue;

// Define a bloom filter to minimize false negatives when checking for the existence of a data point's string identifier
typedef struct {
    char *string;
    void *metadata;
} bloom_filter;

// Define a user-friendly interface for adding new data points and retrieving them by their unique string identifiers
void add_data_point(char *string, double value, float timestamp, void *metadata) {
    // Allocate memory for the new data point
    data_point *new_data = malloc(sizeof(data_point));
    new_data->value = value;
    new_data->string = string;
    new_data->timestamp = timestamp;
    new_data->metadata = metadata;

    // Insert the new data point into the linked list
    data_list *list = malloc(sizeof(data_list));
    list->size = 1;
    list->data = new_data;

    // Add the new data point to the B-tree and priority queue
    btree_node *new_btree_node = malloc(sizeof(btree_node));
    new_btree_node->key = string;
    new_btree_node->value = new_data;
    btree_insert(&list, new_btree_node);
    priority_queue_push(&list, new_data);

    // Add the new data point to the bloom filter
    bloom_filter *new_bloom_filter = malloc(sizeof(bloom_filter));
    new_bloom_filter->string = string;
    new_bloom_filter->metadata = metadata;
    bloom_filter_insert(&list, new_bloom_filter);
}

