    // Remove older entries from the priority queue and bloom filter first
    while (priority_queue->size > 0 && priority_queue->data[0]->timestamp < current_time - TIMEOUT) {
        data_point *oldest = priority_queue->data[0];
        priority_queue_pop(&list);
