    record->value = rand() % (max - min + 1) + min;
}

// Define the function to set the integer value of each record based on a provided callback function
void set_values(int size, Record* records, int (*callback)(Record*, int)) {
    // Iterate through the records and set the integer value for each one
    for (int i = 0; i < size; i++) {
        if (callback(&records[i], i) == 1) {
            init_random(&records[i]);
        }
    }
}

// Define the function to traverse the linked list and construct a string based on user-defined logic
void traverse(Node* node, char* buffer, int size) {
