    if (node == NULL || size <= 0) {
        return;
    }

    // Append the current record's string to the buffer
    strncat(buffer, node->record.string, size);

    // Recursively traverse the linked list
    traverse(node->next, buffer, size - strlen(buffer));
}

// Define the function to serialize the entire structure into a binary format
void serialize(Node* node, char* buffer) {
    // Check if the node is NULL or the buffer is full
    if (node == NULL || buffer == NULL) {
        return;
    }

    // Serialize the current record's integer value and string to the buffer
    int size = sizeof(int);
    memcpy(buffer, &node->record.value, size);
    size += strlen(node->record.string);
    memcpy(buffer + size, node->record.string, strlen(node->record.string));

    // Recursively serialize the linked list
    serialize(node->next, buffer + size);
}

// Define the function to deserialize the entire structure from a binary format
void deserialize(Node* node, char* buffer) {
    // Check if the node is NULL or the buffer is empty
    if (node == NULL || buffer == NULL) {
        return;
    }

    // Deserialize the current record's integer value and string from the buffer
    int size = sizeof(int);
    memcpy(&node->record.value, buffer, size);
    node->record.string = malloc(strlen(buffer) - size + 1);
    strncpy(node->record.string, buffer + size, strlen(buffer) - size);
    node->record.string[strlen(buffer) - size] = '\0';

    // Recursively deserialize the linked list
    deserialize(node->next, buffer + size);
}
