    // Check if the final output string length exceeds the size limit
    int output_length = get_output_length(data_points);
    if (output_length > sizeLimit) {
        return NULL;
    }

    // Allocate memory for the filtered output string
    char *output = malloc(sizeof(char) * (output_length + 1));
    int index = 0;

    // Iterate through the linked list of data points and add them to the output string
    for (data_point *current = data_points; current != NULL; current = current->next) {
        output[index++] = current->value;
    }

    // Add a null terminator at the end of the output string
    output[output_length] = '\0';

    return output;
}

// Function to add a data point to the linked list
data_point_list *add_data_point(data_point_list *list, data_point *new_data_point) {
    // If the linked list is empty, create a new node and set it as the head
    if (list == NULL) {
        list = malloc(sizeof(data_point_list));
        list->size = 1;
        list->data_points = new_data_point;
        return list;
    }

    // If the linked list is not empty, add a new node to the end of it
    data_point_list *current = list;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = malloc(sizeof(data_point_list));
    current->next->size = 1;
    current->next->data_points = new_data_point;
    return list;
}

// Function to get the length of the filtered output string
int get_output_length(data_point_list *list) {
    int length = 0;
    for (data_point_list *current = list; current != NULL; current = current->next) {
        length += current->size;
    }
    return length;
}
