    return rec;
}

// Function to insert a record into the linked list
void insert_record(Node **head, Record *rec) {
    Node *new_node = malloc(sizeof(Node));
    new_node->record = *rec;
    new_node->next = NULL;

    if (*head == NULL) {
        *head = new_node;
    } else {
        Node *curr = *head;
        while (curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = new_node;
    }
}

// Function to resize the memory block when needed
void resize_memory(Node **head, int size) {
    Node *new_head = malloc(size);
    Node *curr = *head;
    for (int i = 0; i < size; i++) {
        new_head[i].record = curr->record;
        new_head[i].next = NULL;
        if (curr->next == NULL) {
            break;
        } else {
            curr = curr->next;
        }
    }
    *head = new_head;
}

// Function to verify that all dynamically allocated strings are properly managed
void check_strings(Node **head) {
    Node *curr = *head;
    while (curr != NULL) {
        if (curr->record.str == NULL) {
            printf("Memory leak detected!\n");
            break;
        } else {
            curr = curr->next;
        }
    }
}

// Function to free the memory allocated for a record
