        free(rec->str);
    }
    free(rec);
}

// Function to free the memory allocated for the linked list
void free_list(Node **head) {
    Node *curr = *head;
    while (curr != NULL) {
        if (curr->record.str != NULL) {
            free(curr->record.str);
        }
        curr = curr->next;
    }
    free(*head);
}

