    if (!curl) {
        fprintf(stderr, "Failed to initialize curl\n");
        return -1;
    }

    // Set the URL and other options for the API call
    curl_easy_setopt(curl, CURLOPT_URL, api_endpoint);
    curl_easy_setopt(curl, CURLOPT_USERAGENT, "acquire_sensor_data/1.0");
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 3L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 3L);
    curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1L);
    curl_easy_setopt(curl, CURLOPT_FAILONERROR, 1L);
    curl_easy_setopt(curl, CURLOPT_ERRORBUFFER, error_buffer);

    // Set up the retry logic
    for (i = 0; i < max_retry_count; i++) {
        // Perform the API call and check for errors
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "API call failed: %s\n", error_buffer);
            if (i == max_retry_count - 1) {
                // If we've reached the maximum number of retries, return an error
                curl_easy_cleanup(curl);
                return -1;
            } else {
                // Otherwise, wait for a short period of time and try again
                sleep(5);
            }
        } else {
            break;
        }
    }

    // If we've reached this point, the API call was successful. Parse the response data
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &res);
    if (res != 200) {
        fprintf(stderr, "API returned error code %d\n", res);
        curl_easy_cleanup(curl);
        return -1;
    }

    // Allocate memory for the sensor data array
    data = malloc(sizeof(sensor_data) * 10);
    if (!data) {
        fprintf(stderr, "Failed to allocate memory for sensor data\n");
        curl_easy_cleanup(curl);
        return -1;
    }

    // Parse the response data and store it in the sensor data array
