    json_t* root = json_loads(api_response, 0, &error);
    if (!root) {
        fprintf(stderr, "Failed to parse JSON: %s\n", error.text);
        curl_easy_cleanup(curl);
        return -1;
    }
    json_t* data_array = json_object_get(root, "data");
    if (!data_array) {
        fprintf(stderr, "Failed to find 'data' array in JSON response\n");
        curl_easy_cleanup(curl);
        return -1;
    }
    size_t data_count = json_array_size(data_array);
    for (i = 0; i < data_count; i++) {
        json_t* sensor_object = json_array_get(data_array, i);
        if (!sensor_object) {
            fprintf(stderr, "Failed to find sensor object in JSON response\n");
            curl_easy_cleanup(curl);
            return -1;
        }
        json_t* temperature = json_object_get(sensor_object, "temperature");
        if (!temperature) {
            fprintf(stderr, "Failed to find 'temperature' field in JSON response\n");
            curl_easy_cleanup(curl);
            return -1;
        }
        json_t* humidity = json_object_get(sensor_object, "humidity");
        if (!humidity) {
            fprintf(stderr, "Failed to find 'humidity' field in JSON response\n");
            curl_easy_cleanup(curl);
            return -1;
        }
        json_t* battery_level = json_object_get(sensor_object, "battery_level");
        if (!battery_level) {
            fprintf(stderr, "Failed to find 'battery_level' field in JSON response\n");
            curl_easy_cleanup(curl);
            return -1;
        }
        data[i].temperature = json_number_value(temperature);
        data[i].humidity = json_number_value(humidity);
        data[i].battery_level = json_number_value(battery_level);
    }
    data_size = i;

    // Clean up the curl handle and return the sensor data array
    curl_easy_cleanup(curl);
    return data_size;
}

// Define a function to release all allocated resources when the data acquisition process is complete
void release_sensor_data(sensor_data* data, size_t data_size) {
    if (data) {
        free(data);
    }
}
