        return -1;
    }
}

// Define the function to update a record in the collection
void updateRecord(HashTable *ht, Record *record) {
    // Check if the key exists in the hash table
    if (keyExists(ht, record->key)) {
        // Update the existing record with the new offset value
        updateInList(ht, record);
    } else {
