void removeFromList(HashTable *ht, int key) {
    // Remove the record from the linked list and hash table
    Record *record = ht->records[key];
    ht->records[key] = NULL;
    ht->count--;
}

// Define the function to update a record in the linked list
void updateInList(HashTable *ht, Record *record) {
