void resize(HashTable *ht) {
    // Create a new hash table with twice the size of the current one
    HashTable *newHt = (HashTable*)malloc(sizeof(HashTable));
    newHt->size = ht->size * 2;
    newHt->count = 0;
    newHt->records = (Record**)malloc(newHt->size * sizeof(Record*));
    // Copy the records from the old hash table to the new one
    for (int i = 0; i < ht->size; i++) {
        if (ht->records[i] != NULL) {
            Record *record = ht->records[i];
            newHt->records[record->key] = record;
            newHt->count++;
        }
    }
    // Free the old hash table and linked list
    free(ht->records);
    free(ht);
    // Set the new hash table and linked list as the current ones
    ht = newHt;
}

