void verifyPointers() {
    // Check if there are any memory leaks
    if (ht->count > 0) {
        // Print an error message indicating that there is a memory leak
        printf("Memory leak detected!\n");
    } else {
        // Print a success message indicating that there are no memory leaks
        printf("No memory leaks detected.\n");
    }
}

// Define the function to generate periodic reports summarizing memory usage and performance metrics
void generateReports() {
    // Print a report summarizing the current memory usage and performance metrics
    printf("Memory usage: %d\n", ht->count);
    printf("Performance metrics: %f\n", getPerformanceMetrics());
}
