Task 1: Implementing a C function named `processString` that takes a null-terminated character array `inputStr`, an integer `sizeLimit`, and a function pointer `charFilter` as parameters. The function should implement a recursive traversal of `inputStr` using the `charFilter` function to decide which characters to include in the final output.
```c
#include <stdbool.h>
#include <string.h>

void* processString(const char* inputStr, int sizeLimit, bool (*charFilter)(char c, int index, int maxSize)) {
    // Check for null pointers and empty strings
    if (inputStr == NULL || strlen(inputStr) == 0) {
        return NULL;
    }

    // Initialize the output string
    char* outputStr = malloc(sizeLimit + 1);
    if (outputStr == NULL) {
        return NULL;
    }
    outputStr[0] = '\0';

    // Recursive traversal of input string using charFilter function
    int index = 0;
    while (index < strlen(inputStr)) {
        char c = inputStr[index];
        if (charFilter(c, index, sizeLimit) && strlen(outputStr) + 1 <= sizeLimit) {
            outputStr = realloc(outputStr, strlen(outputStr) + 2);
            if (outputStr == NULL) {
                return NULL;
            }
            outputStr[strlen(outputStr)] = c;
            outputStr[strlen(outputStr) + 1] = '\0';
        }
        index++;
    }

    // Return the final output string
    return outputStr;
}
