typedef struct {
    char* key;
    char* value;
} json_object_t;

// Define a struct to represent the data processing pipeline
typedef struct {
    int stage_count;
    json_object_t** stages;
} pipeline_t;

// Define a function to initialize the pipeline
pipeline_t* init_pipeline(int stage_count) {
    // Allocate memory for the pipeline structure
    pipeline_t* pipeline = malloc(sizeof(pipeline_t));
    if (pipeline == NULL) {
        return NULL;
    }

    // Initialize the stage count and allocate memory for the stages
    pipeline->stage_count = stage_count;
    pipeline->stages = malloc(sizeof(json_object_t*) * stage_count);
    if (pipeline->stages == NULL) {
        free(pipeline);
        return NULL;
    }

    // Initialize each stage with a null pointer
    for (int i = 0; i < stage_count; i++) {
        pipeline->stages[i] = NULL;
    }

    return pipeline;
}

// Define a function to add a new stage to the pipeline
bool add_stage(pipeline_t* pipeline, json_object_t* stage) {
    // Check for null pointers and overflows
    if (pipeline == NULL || stage == NULL || pipeline->stage_count >= INT_MAX) {
        return false;
    }

    // Allocate memory for the new stage
    json_object_t** new_stages = realloc(pipeline->stages, sizeof(json_object_t*) * (pipeline->stage_count + 1));
    if (new_stages == NULL) {
        return false;
    }

    // Add the new stage to the pipeline
    pipeline->stages = new_stages;
    pipeline->stages[pipeline->stage_count] = stage;
    pipeline->stage_count++;

    return true;
}

// Define a function to remove a stage from the pipeline
bool remove_stage(pipeline_t* pipeline, int index) {
    // Check for null pointers and invalid indices
    if (pipeline == NULL || index < 0 || index >= pipeline->stage_count) {
        return false;
    }

    // Shift the stages to the left of the removed stage
    for (int i = index; i < pipeline->stage_count - 1; i++) {
        pipeline->stages[i] = pipeline->stages[i + 1];
    }

    // Decrement the stage count and reallocate memory for the stages
    pipeline->stage_count--;
    json_object_t** new_stages = realloc(pipeline->stages, sizeof(json_object_t*) * pipeline->stage_count);
    if (new_stages == NULL) {
        return false;
    }

    // Update the stages pointer
    pipeline->stages = new_stages;

    return true;
}

// Define a function to process data through the pipeline
bool process_data(pipeline_t* pipeline, json_object_t* data) {
    // Check for null pointers and empty data
    if (pipeline == NULL || data == NULL) {
        return false;
    }

    // Process each stage in the pipeline
    for (int i = 0; i < pipeline->stage_count; i++) {
        json_object_t* output = pipeline->stages[i](data);
        if (output == NULL) {
            return false;
        }
        data = output;
    }

    return true;
}
