// Custom memory pool allocator for optimized memory usage
struct MemoryPool {
    struct Node {
        void* data;
        size_t size;
        struct Node* next;
    };

    struct Node* head;
    struct Node* tail;
    size_t totalSize;
};

// Doubly linked list for sorted record management
struct RecordList {
    struct RecordNode {
        long offset;
        int key;
        int value;
        struct RecordNode* next;
        struct RecordNode* prev;
    };

    struct RecordNode* head;
    struct RecordNode* tail;
};

// Custom hash table with separate chaining for fast key-based lookups
struct HashTable {
    struct Bucket {
        int size;
        struct RecordNode** nodes;
    };

    struct Bucket* buckets;
    int bucketCount;
};

// Thread-safe mutex for concurrent access control
struct Mutex {
    pthread_mutex_t lock;
};

// Implementation of the high-performance data structure
struct DataStructure {
    struct MemoryPool* memoryPool;
    struct RecordList* recordList;
    struct HashTable* hashTable;
    struct Mutex* mutex;
};

// Function to initialize the data structure
void initDataStructure(struct DataStructure* ds) {
    // Initialize memory pool allocator
    ds->memoryPool = createMemoryPool();

    // Initialize record list and hash table
    ds->recordList = createRecordList();
    ds->hashTable = createHashTable();

    // Initialize mutex for concurrent access control
    ds->mutex = createMutex();
}

// Function to insert a new record into the data structure
void insertRecord(struct DataStructure* ds, long offset, int key, int value) {
    // Acquire lock on mutex
    acquireLock(ds->mutex);

    // Allocate memory for the new record
    struct RecordNode* node = allocateMemory(ds->memoryPool, sizeof(struct RecordNode));
    node->offset = offset;
    node->key = key;
    node->value = value;

    // Insert the new record into the record list and hash table
    insertRecordIntoList(ds->recordList, node);
    insertRecordIntoHashTable(ds->hashTable, node);

    // Release lock on mutex
    releaseLock(ds->mutex);
}

// Function to delete a record from the data structure
void deleteRecord(struct DataStructure* ds, long offset) {
    // Acquire lock on mutex
    acquireLock(ds->mutex);

    // Find the record with the specified offset in the record list and hash table
    struct RecordNode* node = findRecordInList(ds->recordList, offset);
    if (node != NULL) {
        // Delete the record from the record list and hash table
        deleteRecordFromList(ds->recordList, node);
        deleteRecordFromHashTable(ds->hashTable, node);

        // Free the memory allocated for the record
        freeMemory(ds->memoryPool, node);
    }

    // Release lock on mutex
    releaseLock(ds->mutex);
}

// Function to traverse all records in the data structure
void traverseRecords(struct DataStructure* ds, void (*callback)(long offset, int key, int value)) {
    // Acquire lock on mutex
    acquireLock(ds->mutex);

    // Traverse all records in the record list and hash table
    struct RecordNode* node = ds->recordList->head;
    while (node != NULL) {
        callback(node->offset, node->key, node->value);
        node = node->next;
    }

    // Release lock on mutex
    releaseLock(ds->mutex);
}

// Function to find a record in the data structure by key
struct RecordNode* findRecordByKey(struct DataStructure* ds, int key) {
    // Acquire lock on mutex
    acquireLock(ds->mutex);

    // Find the record with the specified key in the hash table
    struct RecordNode* node = findRecordInHashTable(ds->hashTable, key);

    // Release lock on mutex
    releaseLock(ds->mutex);

    return node;
}

// Function to free all memory allocated by the data structure
void freeDataStructure(struct DataStructure* ds) {
    // Acquire lock on mutex
    acquireLock(ds->mutex);

    // Free all memory allocated for records in the record list and hash table
    struct RecordNode* node = ds->recordList->head;
    while (node != NULL) {
        freeMemory(ds->memoryPool, node);
        node = node->next;
    }

    // Release lock on mutex
    releaseLock(ds->mutex);
}

// Function to create a memory pool allocator
struct MemoryPool* createMemoryPool() {
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));
    if (pool == NULL) {
        return NULL;
    }

    // Initialize the memory pool with an empty list of free blocks
    pool->head = NULL;
    pool->tail = NULL;
    pool->totalSize = 0;

    return pool;
}

// Function to allocate memory from a memory pool allocator
void* allocateMemory(struct MemoryPool* pool, size_t size) {
    // Check if there are any free blocks in the memory pool
    struct Node* node = pool->head;
    while (node != NULL && node->size < size) {
        node = node->next;
    }

    // If a block of sufficient size is found, remove it from the list and return its data pointer
    if (node != NULL) {
        void* data = node->data;
        pool->totalSize -= node->size;
        if (pool->head == node) {
            pool->head = node->next;
        }
        if (pool->tail == node) {
            pool->tail = node->prev;
        }
        free(node);
        return data;
    }

    // If no block of sufficient size is found, allocate a new block and add it to the list
    void* data = malloc(size);
    if (data == NULL) {
        return NULL;
    }

    struct Node* newNode = malloc(sizeof(struct Node));
    if (newNode == NULL) {
        free(data);
        return NULL;
    }

    newNode->data = data;
    newNode->size = size;
    newNode->next = pool->head;
    newNode->prev = NULL;
    if (pool->head != NULL) {
        pool->head->prev = newNode;
    }
    pool->head = newNode;
    if (pool->tail == NULL) {
        pool->tail = newNode;
    }

    return data;
}

// Function to free memory allocated by a memory pool allocator
void freeMemory(struct MemoryPool* pool, void* data) {
    // Find the node containing the specified data pointer in the memory pool
    struct Node* node = pool->head;
    while (node != NULL && node->data != data) {
        node = node->next;
    }

    // If the node is found, remove it from the list and free its memory
    if (node != NULL) {
        pool->totalSize += node->size;
        if (pool->head == node) {
            pool->head = node->next;
        }
        if (pool->tail == node) {
            pool->tail = node->prev;
        }
        free(node);
    }
}

// Function to create a doubly linked list for sorted record management
struct RecordList* createRecordList() {
    struct RecordList* list = malloc(sizeof(struct RecordList));
    if (list == NULL) {
        return NULL;
    }

    // Initialize the list with an empty head and tail pointers
    list->head = NULL;
    list->tail = NULL;

    return list;
}

