// Define a structure to represent a chunk of data
typedef struct {
    char* data;
    size_t size;
} Chunk;

// Define a function pointer type for the data validator
typedef bool (*DataValidator)(const char*);

// Define a function to parse and aggregate data
Chunk* parseAndAggregateData(const char* inputData, int chunkSizeLimit, DataValidator dataValidator) {
    // Check if the input data is null or empty
    if (inputData == NULL || strlen(inputData) == 0) {
        return NULL;
    }

    // Initialize a list to store the chunks of data
    Chunk* chunkList = malloc(sizeof(Chunk));
    assert(chunkList != NULL);

    // Initialize a variable to keep track of the current position in the input data
    const char* currentPos = inputData;

    // Loop until we reach the end of the input data
    while (*currentPos != '\0') {
        // Calculate the size of the next chunk
        int chunkSize = (chunkSizeLimit > strlen(currentPos)) ? strlen(currentPos) : chunkSizeLimit;

        // Allocate memory for the chunk and copy the data into it
        Chunk* newChunk = malloc(sizeof(Chunk));
        assert(newChunk != NULL);
        newChunk->data = malloc(chunkSize + 1);
        assert(newChunk->data != NULL);
        memcpy(newChunk->data, currentPos, chunkSize);
        newChunk->size = chunkSize;

        // Add the new chunk to the list
        chunkList = realloc(chunkList, (sizeof(Chunk) * (listLength + 1)));
        assert(chunkList != NULL);
        chunkList[listLength++] = newChunk;

        // Update the current position in the input data
        currentPos += chunkSize;
    }

    // Validate each chunk using the provided function pointer
    for (int i = 0; i < listLength; i++) {
        if (!dataValidator(chunkList[i]->data)) {
            freeChunkList(chunkList);
            return NULL;
        }
    }

    // Return the aggregated data
    return chunkList;
}

// Define a function to free a list of chunks
void freeChunkList(Chunk* chunkList) {
    for (int i = 0; i < listLength; i++) {
        free(chunkList[i]->data);
        free(chunkList[i]);
    }
    free(chunkList);
}
