class Task {
public:
    int id;
    int priority;
    std::chrono::time_point<std::chrono::system_clock> scheduledTime;
    bool isCompleted;

    Task(int id, int priority, std::chrono::time_point<std::chrono::system_clock> scheduledTime) : id(id), priority(priority), scheduledTime(scheduledTime), isCompleted(false) {}

    void setNextScheduledTime(std::chrono::time_point<std::chrono::system_clock> nextScheduledTime) {
        this->scheduledTime = nextScheduledTime;
    }

    std::chrono::time_point<std::chrono::system_clock> getNextScheduledTime() const {
        return scheduledTime;
    }

    void setIsCompleted(bool isCompleted) {
        this->isCompleted = isCompleted;
    }

    bool getIsCompleted() const {
        return isCompleted;
    }

    int getPriority() const {
        return priority;
    }

    std::string toString() const {
        return "Task ID: " + std::to_string(id) + ", Priority: " + std::to_string(priority) + ", Scheduled Time: " + std::to_string(scheduledTime.time_since_epoch().count()) + ", Is Completed: " + (isCompleted ? "true" : "false");
    }
};

class TaskManager {
public:
    TaskManager() {}

    void addTask(int id, int priority, std::chrono::time_point<std::chrono::system_clock> scheduledTime) {
        tasks.push_back(Task(id, priority, scheduledTime));
    }

    void removeTask(int id) {
        for (auto it = tasks.begin(); it != tasks.end(); ++it) {
            if ((*it).getId() == id) {
                tasks.erase(it);
                break;
            }
        }
    }

    void updateTaskPriority(int id, int newPriority) {
        for (auto& task : tasks) {
            if (task.getId() == id) {
                task.setPriority(newPriority);
                break;
            }
        }
    }

    void updateTaskScheduledTime(int id, std::chrono::time_point<std::chrono::system_clock> newScheduledTime) {
        for (auto& task : tasks) {
            if (task.getId() == id) {
                task.setNextScheduledTime(newScheduledTime);
                break;
            }
        }
    }

    void updateTaskStatus(int id, bool isCompleted) {
        for (auto& task : tasks) {
            if (task.getId() == id) {
                task.setIsCompleted(isCompleted);
                break;
            }
        }
    }

    std::vector<Task> getTasks() const {
        return tasks;
    }

private:
    std::vector<Task> tasks;
};

int main() {
    TaskManager taskManager;

    // Add a new task with ID 1, priority 5, and scheduled time now + 10 seconds
    taskManager.addTask(1, 5, std::chrono::system_clock::now() + std::chrono::seconds(10));

    // Remove the task with ID 1
    taskManager.removeTask(1);

    // Update the priority of the task with ID 2 to 10
    taskManager.updateTaskPriority(2, 10);

    // Update the scheduled time of the task with ID 3 to now + 20 seconds
    taskManager.updateTaskScheduledTime(3, std::chrono::system_clock::now() + std::chrono::seconds(20));

    // Update the status of the task with ID 4 to completed
    taskManager.updateTaskStatus(4, true);

    // Get all tasks and print their details
    for (const auto& task : taskManager.getTasks()) {
        std::cout << task.toString() << std::endl;
    }

    return 0;
}
