            printf("\tData point %d: timestamp=%f, string=%s, value=%f\n", j, records[i].data_points[j].timestamp, records[i].data_points[j].string, records[i].data_points[j].value);
        }
    }
}

// Define a function to clean up the collection and release allocated resources
void cleanupCollection(Record *records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        free(records[i].data_points);
    }
    free(records);
}

// Define a function to validate the configuration structure and external data sources
void validateConfiguration(RandomConfig config, char *filename) {
    // Check that the minimum value is less than or equal to the maximum value
    if (config.min_value > config.max_value) {
        printf("Error: The minimum value must be less than or equal to the maximum value.\n");
        exit(1);
    }
    // Check that the step size is greater than zero
    if (config.step <= 0) {
        printf("Error: The step size must be greater than zero.\n");
        exit(1);
    }
    // Check that the file exists and can be read
    FILE *file = fopen(filename, "r");
    if (!file) {
        printf("Error: Could not open file %s for reading.\n", filename);
        exit(1);
    }
}

// Define a function to generate random values for timestamps using the custom random number generator
void generateTimestamps(RandomConfig config, DataPoint *data_points, int num_data_points) {
    // Generate a random value within the given range for each data point
    for (int i = 0; i < num_data_points; i++) {
        data_points[i].timestamp = generateRandomValue(config);
    }
}

// Define a function to add new data points and retrieve them by unique string identifier
void addDataPoint(Record *record, DataPoint *data_point) {
    // Insert the data point into the record's list of data points
    insertRecord(record, data_point);
}

void getDataPoint(Record *record, char *string_id, DataPoint *data_point) {
    // Find the index of the data point with the given string identifier
    int i;
    for (i = 0; i < record->num_data_points; i++) {
        if (!strcmp(record->data_points[i].string, string_id)) {
            break;
        }
    }
    // If the data point was found, copy it to the output parameter
    if (i < record->num_data_points) {
        memcpy(data_point, &record->data_points[i], sizeof(DataPoint));
    } else {
        printf("Error: Data point with string identifier %s not found.\n", string_id);
    }
}

int main() {
    // Define the configuration structure and external data source
    RandomConfig config = {10, 20, 5};
    char *filename = "data.csv";

    // Validate the configuration structure and external data source
    validateConfiguration(config, filename);

    // Initialize the collection of records
    Record *records = malloc(sizeof(Record) * 10);
    for (int i = 0; i < 10; i++) {
        records[i].key = i + 1;
        records[i].num_data_points = 0;
        records[i].data_points = NULL;
    }

    // Load the external data source into the collection of records
    FILE *file = fopen(filename, "r");
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        DataPoint data_point;
        sscanf(line, "%lf,%s,%f", &data_point.timestamp, data_point.string, &data_point.value);
        insertRecord(&records[data_point.key - 1], &data_point);
    }

    // Generate random values for timestamps using the custom random number generator
    generateTimestamps(config, records[0].data_points, records[0].num_data_points);

    // Add new data points and retrieve them by unique string identifier
    addDataPoint(&records[1], &(DataPoint){.timestamp = 10.5, .string = "test", .value = 20.5});
    DataPoint data_point;
    getDataPoint(&records[1], "test", &data_point);

    // Traverse the collection and print each record's data points
    traverseCollection(records, 10);

    // Clean up the collection and release allocated resources
    cleanupCollection(records, 10);

    return 0;
}
