    struct TreeNode* right;
};

void initTree(struct TreeNode** root) {
    *root = NULL;
}

void insertTree(struct TreeNode** root, int age, char* location) {
    if (*root == NULL) {
        *root = (struct TreeNode*)malloc(sizeof(struct TreeNode));
        (*root)->age = age;
        (*root)->location = location;
        (*root)->left = NULL;
        (*root)->right = NULL;
    } else if (age < (*root)->age) {
        insertTree(&(*root)->left, age, location);
    } else if (age > (*root)->age) {
        insertTree(&(*root)->right, age, location);
    }
}

void* getTree(struct TreeNode** root, int age, char* location) {
    if (*root == NULL) return NULL;
    if (age < (*root)->age) {
        return getTree(&(*root)->left, age, location);
    } else if (age > (*root)->age) {
        return getTree(&(*root)->right, age, location);
    } else if (strcmp((*root)->location, location) == 0) {
        return *root;
    }
}

void deleteTree(struct TreeNode** root) {
    if (*root == NULL) return;
    deleteTree(&(*root)->left);
    deleteTree(&(*root)->right);
    free(*root);
    *root = NULL;
}

