// Define data structure for a collection of data points
typedef struct {
    data_point **points;
    size_t num_points;
    pthread_mutex_t *lock;
} data_set;

// Define function to insert a new data point into the data set
void insert_data_point(data_set *ds, data_point *dp) {
    // Acquire lock on data set
    pthread_mutex_lock(&ds->lock);

    // Reallocate memory for data points if necessary
    if (ds->num_points == ds->points.size()) {
        ds->points = realloc(ds->points, (ds->num_points + 1) * sizeof(data_point *));
    }

    // Insert new data point into data set
    ds->points[ds->num_points++] = dp;

    // Release lock on data set
    pthread_mutex_unlock(&ds->lock);
}

// Define function to delete a data point from the data set
void delete_data_point(data_set *ds, size_t index) {
    // Acquire lock on data set
    pthread_mutex_lock(&ds->lock);

    // Shift remaining data points down one index
    for (size_t i = index; i < ds->num_points - 1; i++) {
        ds->points[i] = ds->points[i + 1];
    }

    // Decrement number of data points
    ds->num_points--;

    // Release lock on data set
    pthread_mutex_unlock(&ds->lock);
}

// Define function to traverse all data points in the data set
void traverse_data_set(data_set *ds, void (*callback)(data_point *)) {
    // Acquire lock on data set
    pthread_mutex_lock(&ds->lock);

    // Iterate over all data points and call callback function
    for (size_t i = 0; i < ds->num_points; i++) {
        callback(ds->points[i]);
    }

    // Release lock on data set
    pthread_mutex_unlock(&ds->lock);
}

// Define function to periodically prune outdated data points from the data set
void prune_data_set(data_set *ds) {
    // Acquire lock on data set
    pthread_mutex_lock(&ds->lock);

    // Iterate over all data points and check for outdated entries
    for (size_t i = 0; i < ds->num_points; i++) {
        if (is_outdated(ds->points[i])) {
            delete_data_point(ds, i);
            i--; // Decrement index to account for deleted data point
        }
    }

    // Release lock on data set
    pthread_mutex_unlock(&ds->lock);
}

