// Custom hash table implementation for fast lookups
struct HashTable {
    struct Node** nodes;
    int size;
};

struct Node {
    char* key;
    void* value;
    struct Node* next;
};

void initHashTable(struct HashTable* ht, int size) {
    ht->nodes = (struct Node**)malloc(sizeof(struct Node*) * size);
    memset(ht->nodes, 0, sizeof(struct Node*) * size);
    ht->size = size;
}

void insertHashTable(struct HashTable* ht, char* key, void* value) {
    int index = hashCode(key) % ht->size;
    struct Node* node = (struct Node*)malloc(sizeof(struct Node));
    node->key = key;
    node->value = value;
    node->next = ht->nodes[index];
    ht->nodes[index] = node;
}

void* getHashTable(struct HashTable* ht, char* key) {
    int index = hashCode(key) % ht->size;
    struct Node* node = ht->nodes[index];
    while (node != NULL && strcmp(node->key, key) != 0) {
        node = node->next;
    }
    return node == NULL ? NULL : node->value;
}

void deleteHashTable(struct HashTable* ht, char* key) {
    int index = hashCode(key) % ht->size;
    struct Node** node = &ht->nodes[index];
    while (*node != NULL && strcmp((*node)->key, key) != 0) {
        node = &(*node)->next;
    }
    if (*node == NULL) return;
    *node = (*node)->next;
}

int hashCode(char* key) {
    int hash = 0;
    for (int i = 0; i < strlen(key); i++) {
        hash += key[i];
    }
    return hash % 1000000007;
}

// Balanced binary tree implementation for ordered access and efficient range queries on SKU and expiration date attributes
struct TreeNode {
    struct TreeNode* left;
    struct TreeNode* right;
    char* key;
    void* value;
};

void initTree(struct TreeNode** root) {
    *root = NULL;
}

void insertTree(struct TreeNode** root, char* key, void* value) {
    struct TreeNode* node = (struct TreeNode*)malloc(sizeof(struct TreeNode));
    node->key = key;
    node->value = value;
    if (*root == NULL) {
        *root = node;
    } else {
        struct TreeNode** current = root;
        while (*current != NULL) {
            int cmp = strcmp(key, (*current)->key);
            if (cmp < 0) {
                current = &(*current)->left;
            } else if (cmp > 0) {
                current = &(*current)->right;
            } else {
                break;
            }
        }
        node->parent = *current;
        if (*current == NULL) {
            *current = node;
        } else {
            struct TreeNode* parent = node->parent;
            while (parent != NULL && parent->key == key) {
                parent = parent->parent;
            }
            if (parent == NULL) {
                *root = node;
            } else {
                struct TreeNode** child = &parent->left;
                while (*child != NULL && (*child)->key < key) {
                    child = &(*child)->right;
                }
                node->parent = parent;
                node->left = *child;
                *child = node;
            }
        }
    }
}

void* getTree(struct TreeNode** root, char* key) {
    struct TreeNode* current = *root;
    while (current != NULL && strcmp(key, current->key) != 0) {
        if (strcmp(key, current->left->key) < 0) {
            current = current->left;
        } else {
            current = current->right;
        }
    }
    return current == NULL ? NULL : current->value;
}

void deleteTree(struct TreeNode** root, char* key) {
    struct TreeNode* node = *root;
    if (node == NULL || strcmp(key, node->key) != 0) return;
    if (node->left == NULL && node->right == NULL) {
        *root = NULL;
    } else if (node->left == NULL) {
        struct TreeNode* parent = node->parent;
        while (parent != NULL && parent->key == key) {
            parent = parent->parent;
        }
        if (parent == NULL) {
            *root = node->right;
        } else {
            struct TreeNode** child = &parent->left;
            while (*child != NULL && (*child)->key < key) {
                child = &(*child)->right;
            }
            node->parent = parent;
            node->left = *child;
            *child = node;
        }
    } else if (node->right == NULL) {
        struct TreeNode* parent = node->parent;
        while (parent != NULL && parent->key == key) {
            parent = parent->parent;
        }
        if (parent == NULL) {
            *root = node->left;
        } else {
            struct TreeNode** child = &parent->right;
            while (*child != NULL && (*child)->key > key) {
                child = &(*child)->left;
            }
            node->parent = parent;
            node->right = *child;
            *child = node;
        }
    } else {
        struct TreeNode* min = node->right;
        while (min->left != NULL) {
            min = min->left;
        }
        node->key = min->key;
        node->value = min->value;
        deleteTree(&node->right, min->key);
    }
}

