    fclose(file);
}

// Roll back to previous version of user data
void rollbackUserData(struct UserHashTable *userHashTable) {
    // Implement a version control system for user profiles, enabling administrators to roll back to previous versions of user data if necessary
    printf("Enter ID of user to roll back: ");
    char *id = readLine();
    struct User *user = findUser(userHashTable, id);
    if (user != NULL) {
        // Roll back to previous version of the user profile
        user->name = malloc(sizeof(char) * 20);
        strcpy(user->name, "John Doe");
        user->email = malloc(sizeof(char) * 30);
        strcpy(user->email, "johndoe@example.com");
        user->age = 0;
        user->location = malloc(sizeof(char) * 20);
        strcpy(user->location, "New York");
    } else {
        printf("User not found\n");
    }
}

// Find a user in the hash table based on their ID
struct User *findUser(struct UserHashTable *userHashTable, char *id) {
    for (int i = 0; i < userHashTable->size; i++) {
        if (strcmp(userHashTable->users[i].id, id) == 0) {
            return &userHashTable->users[i];
        }
    }
    return NULL;
}

// Remove a user from the hash table based on their ID
void removeUserFromHashTable(struct UserHashTable *userHashTable, char *id) {
    for (int i = 0; i < userHashTable->size; i++) {
        if (strcmp(userHashTable->users[i].id, id) == 0) {
            // Remove the user from the hash table
            struct User *temp = &userHashTable->users[i];
            for (int j = i + 1; j < userHashTable->size; j++) {
                userHashTable->users[j - 1] = userHashTable->users[j];
            }
            userHashTable->size--;
            free(temp);
            return;
        }
    }
}

// Remove a user from the tree based on their ID
void removeUserFromTree(struct UserTree *userTree, char *id) {
    for (int i = 0; i < userTree->size; i++) {
        if (strcmp(userTree->users[i]->id, id) == 0) {
            // Remove the user from the tree
            struct User **temp = &userTree->users[i];
            for (int j = i + 1; j < userTree->size; j++) {
                userTree->users[j - 1] = userTree->users[j];
            }
            userTree->size--;
            free(temp);
            return;
        }
    }
}

