#include <pthread.h>

// Define a structure for an item in the list
typedef struct {
    char buffer[BUFFER_SIZE]; // A fixed-size buffer for storing strings
    int value;               // An integer value associated with each item
} Item;

// Define a linked list node to store items
typedef struct Node {
    Item *item;             // Pointer to the item stored in this node
    struct Node *next;      // Pointer to the next node in the list
} Node;

// Define a dynamic list data structure
typedef struct {
    int size;               // The current number of items in the list
    int capacity;           // The maximum number of items that can be stored in the list
    Node *head;             // Pointer to the head node of the list
    pthread_mutex_t mutex;  // A mutex for synchronizing access to the list from multiple threads
} List;

// Initialize a new dynamic list with a specified capacity and minimum buffer size
List* init_list(int capacity, int min_buffer_size) {
    List *list = malloc(sizeof(List));
    if (list == NULL) {
        return NULL;
    }

    // Allocate memory for the list's nodes and initialize their values
    Node *head = malloc(sizeof(Node));
    head->item = malloc(sizeof(Item));
    head->next = NULL;
    list->head = head;
    list->size = 0;
    list->capacity = capacity;

    // Initialize the item's buffer size and value
    Item *item = head->item;
    item->buffer_size = min_buffer_size;
    item->value = 0;

    return list;
}

// Add a new item to the end of the list
void add_item(List *list, char *str, int value) {
    pthread_mutex_lock(&list->mutex);

    // Allocate memory for the new item and copy the string into it
    Item *new_item = malloc(sizeof(Item));
    strcpy(new_item->buffer, str);
    new_item->value = value;

    // If the list is full, resize it to accommodate the new item
    if (list->size == list->capacity) {
        int new_capacity = list->capacity * 2;
        Node *new_head = malloc(sizeof(Node));
        new_head->item = malloc(sizeof(Item));
        new_head->next = list->head;
        list->head = new_head;
        list->capacity = new_capacity;
    }

    // Add the new item to the end of the list
    Node *current = list->head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = malloc(sizeof(Node));
    current->next->item = new_item;
    current->next->next = NULL;

    // Increment the list's size and unlock the mutex
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

// Remove an item from the end of the list
void remove_item(List *list) {
    pthread_mutex_lock(&list->mutex);

    // If the list is empty, do nothing
    if (list->size == 0) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    // Find the last node in the list and remove it
    Node *current = list->head;
    while (current->next != NULL) {
        current = current->next;
    }
    free(current->item);
    current->next = NULL;

    // Decrement the list's size and unlock the mutex
    list->size--;
    pthread_mutex_unlock(&list->mutex);
}

// Get an item from the list by its index
Item* get_item(List *list, int index) {
    if (index < 0 || index >= list->size) {
        return NULL;
    }

    pthread_mutex_lock(&list->mutex);

    // Find the node at the specified index and return its item
    Node *current = list->head;
    for (int i = 0; i < index; i++) {
        current = current->next;
    }
    Item *item = current->item;

    pthread_mutex_unlock(&list->mutex);

    return item;
}

// Free the memory allocated by the list
void free_list(List *list) {
    Node *current = list->head;
    while (current != NULL) {
        Item *item = current->item;
        free(item);
        current = current->next;
    }
    free(list);
}
