// Define a function to dynamically allocate memory for a new transaction
struct transaction* create_transaction(const char* description, int amount) {
    // Allocate memory for the transaction structure
    struct transaction* txn = malloc(sizeof(struct transaction));
    if (!txn) {
        fprintf(stderr, "Error: Failed to allocate memory for transaction\n");
        return NULL;
    }

    // Initialize the transaction fields
    txn->description = strdup(description);
    txn->amount = amount;
    txn->parent = NULL;

    // Return a pointer to the new transaction structure
    return txn;
}

// Define a function to create a nested structure of transactions based on user-defined parameters
struct transaction* create_nested_transactions(const char* description, int amount, int num_levels) {
    // Allocate memory for the root transaction structure
    struct transaction* root = create_transaction(description, amount);
    if (!root) {
        fprintf(stderr, "Error: Failed to allocate memory for root transaction\n");
        return NULL;
    }

    // Create a nested structure of transactions based on the user-defined parameters
    struct transaction* current = root;
    for (int i = 0; i < num_levels; i++) {
        // Allocate memory for a new transaction structure
        struct transaction* txn = create_transaction(description, amount);
        if (!txn) {
            fprintf(stderr, "Error: Failed to allocate memory for nested transaction\n");
            return NULL;
        }

        // Set the parent of the new transaction structure to the current transaction
        txn->parent = current;

        // Update the current transaction to point to the new transaction structure
        current = txn;
    }

    // Return a pointer to the root transaction structure
    return root;
}

// Define a function to release memory for a transaction and its nested structures
void free_transaction(struct transaction* txn) {
    // Release memory for the transaction structure
    free(txn);

    // Recursively release memory for any child transactions
    if (txn->parent) {
        free_transaction(txn->parent);
    }
}

// Define a function to handle errors during memory allocation and ensure resources are properly released in case of errors
void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Error: Failed to allocate memory\n");
        return NULL;
    }
    return ptr;
}

// Define a function to handle errors during memory deallocation and ensure resources are properly released in case of errors
void safe_free(void* ptr) {
    if (ptr) {
        free(ptr);
    }
}

// Define a function to track and log the creation of each transaction for debugging purposes, while minimizing the overhead during normal operation
