}

// Define a function to handle concurrent access from multiple threads, with appropriate synchronization mechanisms to prevent race conditions
void* thread_safe_malloc(size_t size) {
    pthread_mutex_lock(&mutex);
    void* ptr = safe_malloc(size);
    pthread_mutex_unlock(&mutex);
    return ptr;
}

// Define a function to handle concurrent access from multiple threads, with appropriate synchronization mechanisms to prevent race conditions
