#include <pthread.h>

// Define a structure to represent an item in the list
typedef struct {
    char buffer[BUFFER_SIZE]; // A fixed-size buffer for storing strings
    int value;               // An integer value associated with each item
} Item;

// Define a linked list data structure to store items
typedef struct Node {
    Item *item;             // Pointer to the item stored in this node
    struct Node *next;      // Pointer to the next node in the list
} Node;

// Define a global variable to keep track of the head and tail nodes of the list
Node *head = NULL, *tail = NULL;

// Define a mutex to synchronize access to the list
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the list with a fixed number of items
void init_list(int num_items) {
    // Allocate memory for the nodes and initialize them
    Node *node = malloc(sizeof(Node) * num_items);
    for (int i = 0; i < num_items; i++) {
        node[i].item = malloc(sizeof(Item));
        node[i].next = NULL;
    }

    // Set the head and tail pointers to the first and last nodes
    head = &node[0];
    tail = &node[num_items - 1];
}

// Function to add a new item to the list
void add_item(Item *new_item) {
    // Acquire the lock on the list
    pthread_mutex_lock(&list_lock);

    // Check if there is enough contiguous free memory available in the allocated block
    int num_free = tail - head + 1;
    if (num_free < BUFFER_SIZE) {
        // If not, resize the list to accommodate more items
        Node *new_node = realloc(head, sizeof(Node) * (num_items + BUFFER_SIZE));
        head = new_node;
        tail = &new_node[num_items - 1];
    }

    // Add the new item to the end of the list
    Node *new_node = malloc(sizeof(Node));
    new_node->item = new_item;
    new_node->next = NULL;
    tail->next = new_node;
    tail = new_node;

    // Release the lock on the list
    pthread_mutex_unlock(&list_lock);
}

// Function to retrieve the current size of the list
int get_size() {
    int size = 0;

    // Acquire the lock on the list
    pthread_mutex_lock(&list_lock);

    // Iterate over the nodes in the list and count the number of items
    Node *node = head;
    while (node != NULL) {
        size++;
        node = node->next;
    }

    // Release the lock on the list
    pthread_mutex_unlock(&list_lock);

    return size;
}

// Function to retrieve the total allocated memory size for the list
int get_allocated_size() {
    int size = 0;

    // Acquire the lock on the list
    pthread_mutex_lock(&list_lock);

    // Iterate over the nodes in the list and count the total allocated memory size
    Node *node = head;
    while (node != NULL) {
        size += sizeof(Node) + sizeof(Item);
        node = node->next;
    }

    // Release the lock on the list
    pthread_mutex_unlock(&list_lock);

    return size;
}

// Function to iterate over the items in the list and perform operations on each item
void iterate(void (*operation)(Item *item)) {
    // Acquire the lock on the list
    pthread_mutex_lock(&list_lock);

    // Iterate over the nodes in the list and perform the operation on each item
    Node *node = head;
    while (node != NULL) {
        operation(node->item);
        node = node->next;
    }

    // Release the lock on the list
    pthread_mutex_unlock(&list_lock);
}

// Function to safely remove an item from the list by index
void remove_item(int index) {
    // Acquire the lock on the list
    pthread_mutex_lock(&list_lock);

    // Check if the index is valid and there are enough items in the list
    int size = get_size();
    if (index < 0 || index >= size) {
        // If not, release the lock on the list and return
        pthread_mutex_unlock(&list_lock);
        return;
    }

    // Find the node at the specified index
    Node *node = head;
    for (int i = 0; i < index; i++) {
        node = node->next;
    }

    // Remove the node from the list by updating the pointers
    if (index == 0) {
        head = node->next;
    } else if (index == size - 1) {
        tail = node->prev;
    }
    Node *prev_node = node->prev;
    Node *next_node = node->next;
    prev_node->next = next_node;
    next_node->prev = prev_node;

    // Release the lock on the list and free the memory for the removed node
    pthread_mutex_unlock(&list_lock);
    free(node);
}
