// Define a hash table to map integer identifiers to sensor data points
typedef struct {
    SensorDataPoint **data;
    size_t capacity;
    size_t size;
} HashTable;

// Initialize the hash table with an initial capacity of 1024
void initHashTable(HashTable *ht) {
    ht->capacity = 1024;
    ht->size = 0;
    ht->data = (SensorDataPoint **)malloc(sizeof(SensorDataPoint *) * ht->capacity);
}

// Insert a new sensor data point into the hash table
void insertHashTable(HashTable *ht, SensorDataPoint *sdp) {
    // Check if the hash table needs to be resized
    if (ht->size >= ht->capacity) {
        resizeHashTable(ht);
    }

    // Insert the sensor data point into the hash table
    ht->data[ht->size++] = sdp;
}

// Delete a sensor data point from the hash table by its integer identifier
void deleteHashTable(HashTable *ht, int id) {
    // Find the index of the sensor data point to be deleted
    size_t i = 0;
    while (i < ht->size && ht->data[i]->id != id) {
        i++;
    }

    // If the sensor data point is found, delete it and shift the remaining elements
    if (i < ht->size) {
        for (size_t j = i; j < ht->size - 1; j++) {
            ht->data[j] = ht->data[j + 1];
        }
        ht->size--;
    }
}

// Retrieve a sensor data point from the hash table by its integer identifier
SensorDataPoint *getHashTable(HashTable *ht, int id) {
    // Find the index of the sensor data point to be retrieved
    size_t i = 0;
    while (i < ht->size && ht->data[i]->id != id) {
        i++;
    }

    // If the sensor data point is found, return it
    if (i < ht->size) {
        return ht->data[i];
    } else {
        return NULL;
    }
}

// Resize the hash table to double its capacity
void resizeHashTable(HashTable *ht) {
    // Create a new hash table with twice the current capacity
    HashTable new_ht;
    initHashTable(&new_ht);

    // Copy the elements from the old hash table to the new one
    for (size_t i = 0; i < ht->size; i++) {
        insertHashTable(&new_ht, ht->data[i]);
    }

    // Free the memory of the old hash table and replace it with the new one
    free(ht->data);
    *ht = new_ht;
}

