    // Check if any sensor data points are no longer needed
    for (size_t i = 0; i < ht->size; i++) {
        SensorDataPoint *sdp = ht->data[i];
        if (sdp->timestamp + TIMEOUT < time(NULL)) {
            deleteHashTable(ht, sdp->id);
        }
    }
}

