// Define the data types for each field in the data point structure
typedef struct {
    int id;
    double value;
} data_point_t;

// Define a custom balanced binary tree for fast key-based lookups
typedef struct {
    int id;
    void *data;
    struct node *left, *right;
} node_t;

// Define the function to dynamically manage and process multiple datasets
void process_datasets(int num_datasets, data_point_t **datasets) {
    // Create a balanced binary tree for each dataset
    node_t **trees = (node_t **)malloc(num_datasets * sizeof(node_t *));
    for (int i = 0; i < num_datasets; i++) {
        trees[i] = create_tree(datasets[i]);
    }

    // Process each dataset concurrently using a separate thread
    pthread_t *threads = (pthread_t *)malloc(num_datasets * sizeof(pthread_t));
    for (int i = 0; i < num_datasets; i++) {
        threads[i] = process_dataset(trees[i], datasets[i]);
    }

    // Wait for all threads to finish processing the datasets
    for (int i = 0; i < num_datasets; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free the memory used by the balanced binary trees and the threads
    for (int i = 0; i < num_datasets; i++) {
        free_tree(trees[i]);
    }
    free(trees);
    free(threads);
}

// Create a balanced binary tree for a given dataset
node_t *create_tree(data_point_t *dataset) {
    // Initialize the root node of the tree
    node_t *root = (node_t *)malloc(sizeof(node_t));
    root->id = 0;
    root->data = NULL;
    root->left = NULL;
    root->right = NULL;

    // Insert each data point into the tree
    for (int i = 0; i < dataset->length; i++) {
        insert_node(root, &dataset[i]);
    }

    return root;
}

// Insert a new node into the balanced binary tree
void insert_node(node_t *root, data_point_t *data) {
    // If the current node is NULL, create a new node and return
    if (root == NULL) {
        root = (node_t *)malloc(sizeof(node_t));
        root->id = data->id;
        root->data = data;
        root->left = NULL;
        root->right = NULL;
        return;
    }

    // If the current node's ID is less than the new node's ID, insert to the left
    if (root->id < data->id) {
        insert_node(root->left, data);
    } else if (root->id > data->id) {
        insert_node(root->right, data);
    }
}

// Free a balanced binary tree and all of its nodes
void free_tree(node_t *root) {
    // If the current node is NULL, return
    if (root == NULL) {
        return;
    }

    // Recursively free the left and right subtrees
    free_tree(root->left);
    free_tree(root->right);

    // Free the current node's data and return
    free(root->data);
    free(root);
}

// Process a single dataset concurrently using a separate thread
void *process_dataset(node_t *tree, data_point_t *dataset) {
    // Create a semaphore to synchronize access to the tree
    sem_t *sem = (sem_t *)malloc(sizeof(sem_t));
    sem_init(sem, 0, 1);

    // Create a new thread to process the dataset
    pthread_t thread;
    pthread_create(&thread, NULL, process_dataset_thread, tree);

    // Wait for the thread to finish processing the dataset
    pthread_join(thread, NULL);

    // Free the semaphore and return
    free(sem);
    return NULL;
}

// Process a single dataset in a separate thread
void *process_dataset_thread(node_t *tree) {
    // Lock the tree using the semaphore to prevent concurrent access
    sem_wait(sem);

    // Process each data point in the tree
    for (int i = 0; i < tree->length; i++) {
        process_data_point(tree, &tree[i]);
    }

    // Unlock the tree and return
    sem_post(sem);
    return NULL;
}

// Process a single data point in the balanced binary tree
void process_data_point(node_t *root, data_point_t *data) {
    // If the current node is NULL, create a new node and return
    if (root == NULL) {
        root = (node_t *)malloc(sizeof(node_t));
        root->id = data->id;
        root->data = data;
        root->left = NULL;
        root->right = NULL;
        return;
    }

    // If the current node's ID is less than the new node's ID, insert to the left
    if (root->id < data->id) {
        process_data_point(root->left, data);
    } else if (root->id > data->id) {
        process_data_point(root->right, data);
    }
}
```
