// Function to dynamically manage memory for and initialize three structures: float, char, and struct log_entry
void init_structures(float **f_ptr, char **c_ptr, struct log_entry **e_ptr) {
    // Allocate memory for the float structure
    *f_ptr = (float *)malloc(sizeof(float));
    if (*f_ptr == NULL) {
        printf("Error: Failed to allocate memory for float structure\n");
        return;
    }

    // Initialize the float structure
