    // Allocate memory for the struct log_entry structure
    *e_ptr = (struct log_entry *)malloc(sizeof(struct log_entry));
    if (*e_ptr == NULL) {
        printf("Error: Failed to allocate memory for struct log_entry structure\n");
        return;
    }

    // Initialize the struct log_entry structure
    **e_ptr = (struct log_entry){0};
}

// Function to add a new log entry to the linked list
void add_log_entry(struct log_entry *head, float f, char c, struct log_entry *new_entry) {
    // Set the timestamp of the new log entry to the current system time
    new_entry->timestamp = time(NULL);

    // Add the new log entry to the linked list
    new_entry->next = head;
    head = new_entry;
}

// Function to delete a log entry from the linked list
void delete_log_entry(struct log_entry *head, struct log_entry *entry) {
    // Find the previous node in the linked list
    struct log_entry *prev = NULL;
    while (head != NULL && head->next != entry) {
        prev = head;
        head = head->next;
    }

    // If the entry is found, delete it from the linked list
    if (head != NULL) {
        if (prev == NULL) {
            head = head->next;
        } else {
            prev->next = head->next;
        }
        free(entry);
    }
}

// Function to traverse the linked list chronologically based on the timestamp
void traverse_log_entries(struct log_entry *head) {
    // Traverse the linked list chronologically based on the timestamp
    while (head != NULL) {
        printf("Timestamp: %ld, Status Code: %c\n", head->timestamp, head->status_code);
        head = head->next;
    }
}

// Function to periodically release unused memory blocks to optimize resource usage
void release_memory(struct log_entry *head) {
    // Release the memory of the linked list
    free(head);
}
