    event_types = {}

    # Iterate over the log entries and count the frequency of each event type
    for entry in log_entries:
        if entry["status_code"] not in event_types:
            event_types[entry["status_code"]] = 1
        else:
            event_types[entry["status_code"]] += 1

    # Return the summary of the most frequent event types encountered in the log entries
    return {k: v for k, v in sorted(event_types.items(), key=lambda item: item[1], reverse=True)}
