typedef struct {
    int memory_usage;
    int data_point_count;
    int processing_latency;
} monitoring_dashboard_t;

// Define the function to manage the dynamic dataset of environmental monitoring data points
void manage_data_points(data_point_t *data_points, size_t num_data_points) {
    // Initialize the doubly linked list and hash table for quick lookups based on sensor ID
    node_t *head = NULL;
    hash_table_t *hash_table = (hash_table_t *)malloc(sizeof(hash_table_t));
    hash_table->size = 1024;
    hash_table->nodes = (node_t **)malloc(sizeof(node_t *) * hash_table->size);
    memset(hash_table->nodes, 0, sizeof(node_t *) * hash_table->size);

    // Initialize the memory pool allocator for managing memory efficiently under heavy load conditions
    memory_pool_allocator_t *memory_pool = (memory_pool_allocator_t *)malloc(sizeof(memory_pool_allocator_t));
    memory_pool->memory = malloc(1024 * 1024);
    memory_pool->size = 1024 * 1024;
    memory_pool->used = 0;

    // Initialize the data processing pipeline for applying real-time transformations and aggregations on the data
    data_processing_pipeline_t *data_processing_pipeline = (data_processing_pipeline_t *)malloc(sizeof(data_processing_pipeline_t));
    data_processing_pipeline->num_plugins = 0;

    // Initialize the monitoring dashboard for providing real-time insights into system performance metrics
    monitoring_dashboard_t *monitoring_dashboard = (monitoring_dashboard_t *)malloc(sizeof(monitoring_dashboard_t));
    monitoring_dashboard->memory_usage = 0;
    monitoring_dashboard->data_point_count = 0;
    monitoring_dashboard->processing_latency = 0;

    // Iterate over the data points and perform the necessary operations
    for (size_t i = 0; i < num_data_points; ++i) {
        // Check if the sensor ID is already present in the hash table, if not add a new node to the list and hash table
        int sensor_id = data_points[i].sensor_id;
        if (hash_table->nodes[sensor_id] == NULL) {
            // Allocate memory for the new node in the doubly linked list
            node_t *new_node = (node_t *)malloc(sizeof(node_t));
            new_node->data_point = &data_points[i];
            new_node->prev = NULL;
            new_node->next = head;
            if (head != NULL) {
                head->prev = new_node;
            }
            head = new_node;

            // Allocate memory for the new node in the hash table
            hash_table->nodes[sensor_id] = new_node;
        } else {
            // Update the existing node in the doubly linked list and hash table with the new data point
            node_t *existing_node = hash_table->nodes[sensor_id];
            existing_node->data_point = &data_points[i];
        }

        // Apply real-time transformations and aggregations on the data using the data processing pipeline
        for (int j = 0; j < data_processing_pipeline->num_plugins; ++j) {
            plugin_t *plugin = data_processing_pipeline->plugins[j];
            plugin->transform(data_points[i]);
            plugin->aggregate(data_points[i]);
        }

        // Update the monitoring dashboard with the latest system performance metrics
        monitoring_dashboard->memory_usage += sizeof(data_point_t);
        ++monitoring_dashboard->data_point_count;
    }

    // Free the memory allocated for the doubly linked list and hash table
    free(hash_table->nodes);
    free(hash_table);

    // Free the memory allocated for the data processing pipeline
    free(data_processing_pipeline);

    // Free the memory allocated for the monitoring dashboard
    free(monitoring_dashboard);
}
