import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.logging.Logger;

public class FileHasher {
    private static final Logger logger = Logger.getLogger(FileHasher.class.getName());

    public static List<HashResult> hashFiles(List<String> filePaths) throws Exception {
        // Initialize the thread pool with a configurable size
        ExecutorService executor = Executors.newFixedThreadPool(10);

        // Create a list to store the results of each file hash computation
        List<HashResult> results = new ArrayList<>();

        // Iterate over the input list of file paths and process them concurrently
        for (String filePath : filePaths) {
            executor.submit(() -> {
                try {
                    // Validate the existence of the file before computing its hash
                    File file = new File(filePath);
                    if (!file.exists()) {
                        throw new Exception("File not found: " + filePath);
                    }

                    // Compute the SHA-256 hash of the file
                    MessageDigest digest = MessageDigest.getInstance("SHA-256");
                    byte[] hash = digest.digest(Files.readAllBytes(file.toPath()));

                    // Create a new HashResult object and add it to the results list
                    results.add(new HashResult(filePath, hash));
                } catch (Exception e) {
                    logger.warning("Error computing hash for file: " + filePath);
                    logger.warning(e.getMessage());
                }
            });
        }

        // Shut down the thread pool after all tasks have been submitted
        executor.shutdown();

        // Wait for all tasks to complete and return the results list
        while (!executor.isTerminated()) {
            Thread.sleep(100);
        }
        return results;
    }

    public static class HashResult {
        private String filePath;
        private byte[] hash;

        public HashResult(String filePath, byte[] hash) {
            this.filePath = filePath;
            this.hash = hash;
        }

        public String getFilePath() {
            return filePath;
        }

        public byte[] getHash() {
            return hash;
        }
    }
}
