// Custom memory pool allocator for efficient memory allocation and deallocation
class MemoryPool {
public:
    MemoryPool(size_t size) : size_(size), used_(0) {}

    void* allocate(size_t size) {
        if (used_ + size > size_) {
            return nullptr;
        }
        void* ptr = &buffer_[used_];
        used_ += size;
        return ptr;
    }

