void add_profile(int id, char* name, char* email, int age, char** social_media_handles) {
    pthread_mutex_lock(&hash_table_lock);
    unsigned int index = hash(id);
    profile_t* new_profile = (profile_t*)malloc(sizeof(profile_t));
    new_profile->id = id;
    new_profile->name = name;
    new_profile->email = email;
    new_profile->age = age;
    new_profile->social_media_handles = social_media_handles;
    hash_table[index] = new_profile;
    pthread_mutex_unlock(&hash_table_lock);
