#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdio.h>
#include <stdbool.h>
#include <pthread.h>

// Define the data structure for a data point
typedef struct {
    double value;
    char *identifier;
    int id;
    float timestamp;
} data_point;

// Define the linked list node for storing data points
typedef struct node {
    data_point *data;
    struct node *next;
} node;

// Define the hash table for quick key-based lookups
typedef struct {
    int size;
    node **table;
} hash_table;

// Define the custom tree structure for quick key-based lookups
typedef struct {
    data_point *data;
    struct tree_node *left, *right;
} tree_node;

// Define the session variable to store the access token
char *access_token = NULL;

// Function to dynamically allocate memory for an array of data points
data_point* allocate_array(int size) {
    // Allocate memory for the array of data points
    data_point *arr = (data_point*)malloc(size * sizeof(data_point));
    if (!arr) {
        printf("Error: Failed to allocate memory for the array\n");
        return NULL;
    }

    // Initialize each data point in the array
    for (int i = 0; i < size; i++) {
        arr[i].value = 0.0;
        arr[i].identifier = NULL;
        arr[i].id = -1;
        arr[i].timestamp = 0.0;
    }

    return arr;
}

// Function to initialize a linked list of data points
node* init_list() {
    // Allocate memory for the head node
    node *head = (node*)malloc(sizeof(node));
    if (!head) {
        printf("Error: Failed to allocate memory for the head node\n");
        return NULL;
    }

    // Initialize the head node
    head->data = NULL;
    head->next = NULL;

    return head;
}

// Function to dynamically allocate memory for a hash table
hash_table* init_hash_table(int size) {
    // Allocate memory for the hash table
    hash_table *ht = (hash_table*)malloc(sizeof(hash_table));
    if (!ht) {
        printf("Error: Failed to allocate memory for the hash table\n");
        return NULL;
    }

    // Initialize the size of the hash table
    ht->size = size;

    // Allocate memory for the table
    ht->table = (node**)malloc(size * sizeof(node*));
    if (!ht->table) {
        printf("Error: Failed to allocate memory for the table\n");
        return NULL;
    }

    // Initialize each node in the table
    for (int i = 0; i < size; i++) {
        ht->table[i] = NULL;
    }

    return ht;
}

// Function to dynamically allocate memory for a custom tree structure
tree_node* init_tree() {
    // Allocate memory for the root node
    tree_node *root = (tree_node*)malloc(sizeof(tree_node));
    if (!root) {
        printf("Error: Failed to allocate memory for the root node\n");
        return NULL;
    }

    // Initialize the root node
    root->data = NULL;
    root->left = NULL;
    root->right = NULL;

    return root;
}

// Function to insert a data point into the linked list
void insert_list(node *head, data_point *data) {
    // Allocate memory for the new node
    node *new_node = (node*)malloc(sizeof(node));
    if (!new_node) {
        printf("Error: Failed to allocate memory for the new node\n");
        return;
    }

    // Initialize the new node
    new_node->data = data;
    new_node->next = NULL;

    // Insert the new node at the end of the linked list
    node *curr = head;
    while (curr->next != NULL) {
        curr = curr->next;
    }
    curr->next = new_node;
}

// Function to insert a data point into the hash table
void insert_hash(hash_table *ht, data_point *data) {
    // Calculate the hash value for the data point
    int hash_value = calculate_hash(data->identifier);

    // Insert the data point into the corresponding node in the hash table
    ht->table[hash_value]->data = data;
}

// Function to insert a data point into the custom tree structure
void insert_tree(tree_node *root, data_point *data) {
    // Calculate the hash value for the data point
    int hash_value = calculate_hash(data->identifier);

    // Insert the data point into the corresponding node in the tree
    root->left = insert_tree_recursive(root->left, data);
}

// Function to delete a data point from the linked list
void delete_list(node *head, char *identifier) {
    // Find the node containing the data point with the specified identifier
    node *curr = head;
    while (curr != NULL && strcmp(curr->data->identifier, identifier) != 0) {
        curr = curr->next;
    }

    // If the node is found, delete it from the linked list
    if (curr != NULL) {
        node *prev = head;
        while (prev->next != curr) {
            prev = prev->next;
        }
        prev->next = curr->next;
        free(curr);
    }
}

// Function to delete a data point from the hash table
void delete_hash(hash_table *ht, char *identifier) {
    // Calculate the hash value for the data point
    int hash_value = calculate_hash(identifier);

    // Delete the data point from the corresponding node in the hash table
    ht->table[hash_value]->data = NULL;
}

// Function to delete a data point from the custom tree structure
void delete_tree(tree_node *root, char *identifier) {
    // Calculate the hash value for the data point
    int hash_value = calculate_hash(identifier);

    // Delete the data point from the corresponding node in the tree
    root->left = delete_tree_recursive(root->left, identifier);
}

// Function to traverse the linked list and print each data point
void traverse_list(node *head) {
    // Traverse the linked list and print each data point
    node *curr = head;
    while (curr != NULL) {
        printf("%s\n", curr->data->identifier);
        curr = curr->next;
    }
}

// Function to traverse the hash table and print each data point
void traverse_hash(hash_table *ht) {
    // Traverse the hash table and print each data point
    for (int i = 0; i < ht->size; i++) {
        if (ht->table[i] != NULL) {
            printf("%s\n", ht->table[i]->data->identifier);
        }
    }
}

// Function to traverse the custom tree structure and print each data point
void traverse_tree(tree_node *root) {
    // Traverse the custom tree structure and print each data point
    if (root != NULL) {
        traverse_tree(root->left);
        printf("%s\n", root->data->identifier);
        traverse_tree(root->right);
    }
}

// Function to calculate the hash value for a given string
int calculate_hash(char *str) {
    // Calculate the hash value using the FNV-1a algorithm
    int hash = 2166136261;
    for (int i = 0; i < strlen(str); i++) {
        hash ^= str[i];
        hash *= 16777619;
    }
    return hash % ht->size;
}

// Function to insert a data point into the custom tree structure recursively
tree_node* insert_tree_recursive(tree_node *root, data_point *data) {
    // If the root node is NULL, create a new node for the data point
    if (root == NULL) {
        root = (tree_node*)malloc(sizeof(tree_node));
        root->data = data;
        root->left = NULL;
        root->right = NULL;
    } else {
        // Calculate the hash value for the data point
        int hash_value = calculate_hash(data->identifier);

        // Recursively insert the data point into the corresponding node in the tree
        if (hash_value < 0) {
            root->left = insert_tree_recursive(root->left, data);
        } else {
            root->right = insert_tree_recursive(root->right, data);
        }
    }

    return root;
}

// Function to delete a data point from the custom tree structure recursively
tree_node* delete_tree_recursive(tree_node *root, char *identifier) {
    // If the root node is NULL, return NULL
    if (root == NULL) {
        return NULL;
    } else {
        // Calculate the hash value for the data point
        int hash_value = calculate_hash(identifier);

        // Recursively delete the data point from the corresponding node in the tree
        if (hash_value < 0) {
            root->left = delete_tree_recursive(root->left, identifier);
        } else {
            root->right = delete_tree_recursive(root->right, identifier);
        }
    }

    return root;
}
