    long value;
};

struct key {
    short metadata;
    int key_value;
};

struct record {
    char status;
    long timestamp;
    double value;
    struct record* next;
};

struct nested_record {
    struct record* record;
};

// Define a function to manage dynamic memory allocation and initialization for flexible collections of records
void *manage_memory(int num_records, int num_fields, void **data) {
    // Allocate memory for the data structure
    void *memory = malloc(num_records * sizeof(struct record));
    if (!memory) {
        return NULL;
    }

    // Initialize the data structure
    struct record* current = (struct record*)memory;
    for (int i = 0; i < num_records; i++) {
        current->status = ' ';
        current->timestamp = 0;
        current->value = 0.0;
        current->next = NULL;
        if (num_fields > 1) {
            // Allocate memory for the nested records
            void *nested_memory = malloc(num_records * sizeof(struct nested_record));
            if (!nested_memory) {
                free(memory);
                return NULL;
            }
            current->next = (struct record*)nested_memory;
        }
        current = current->next;
    }

    // Initialize the data structure with default values
    for (int i = 0; i < num_records; i++) {
        struct record* current = (struct record*)data[i];
        if (current) {
            current->status = ' ';
            current->timestamp = 0;
            current->value = 0.0;
            if (num_fields > 1) {
                // Initialize the nested records with default values
                struct nested_record* nested_current = (struct nested_record*)current->next;
                for (int j = 0; j < num_records; j++) {
                    nested_current->record = NULL;
                    nested_current = nested_current->next;
                }
            }
        }
    }

    // Randomly initialize the data structure with user-defined ranges
    for (int i = 0; i < num_records; i++) {
        struct record* current = (struct record*)data[i];
        if (current) {
            current->status = ' ';
            current->timestamp = rand() % 1000000;
            current->value = (double)(rand() % 1000000) / 1000.0;
            if (num_fields > 1) {
                // Randomly initialize the nested records with user-defined ranges
                struct nested_record* nested_current = (struct nested_record*)current->next;
                for (int j = 0; j < num_records; j++) {
                    if (nested_current->record) {
                        nested_current->record->status = ' ';
                        nested_current->record->timestamp = rand() % 1000000;
                        nested_current->record->value = (double)(rand() % 1000000) / 1000.0;
                    }
                    nested_current = nested_current->next;
                }
            }
        }
    }

    // Return the allocated memory block
    return memory;
}

// Define a function to clean up resources and prevent memory leaks
void cleanup(void **data) {
    for (int i = 0; i < num_records; i++) {
        struct record* current = (struct record*)data[i];
        if (current) {
            free(current);
        }
    }
}
