// Custom data structure for maintaining sorted order of transactions based on timestamps
struct Transaction {
    long timestamp;
    float amount;
    char status[10];
};

struct TransactionList {
    struct Transaction* head;
    struct Transaction* tail;
    int size;
};

// Function to insert a new transaction into the list
void insertTransaction(struct TransactionList* list, long timestamp, float amount, char status[]) {
    // Create a new transaction object
    struct Transaction* newTransaction = (struct Transaction*)malloc(sizeof(struct Transaction));
    newTransaction->timestamp = timestamp;
    newTransaction->amount = amount;
    strcpy(newTransaction->status, status);

    // Insert the new transaction into the list
    if (list->head == NULL) {
        list->head = newTransaction;
        list->tail = newTransaction;
    } else {
        list->tail->next = newTransaction;
        list->tail = newTransaction;
    }

    // Increment the size of the list
    list->size++;
}

// Function to update a transaction in the list
void updateTransaction(struct TransactionList* list, long timestamp, float amount, char status[]) {
    struct Transaction* current = list->head;

    // Find the transaction to be updated
    while (current != NULL && current->timestamp < timestamp) {
        current = current->next;
    }

    if (current == NULL || current->timestamp > timestamp) {
        return;
    }

    // Update the transaction fields
    current->amount = amount;
    strcpy(current->status, status);
}

// Function to retrieve transactions within a specified time range
struct TransactionList* getTransactionsInRange(struct TransactionList* list, long startTimestamp, long endTimestamp) {
    struct TransactionList* result = (struct TransactionList*)malloc(sizeof(struct TransactionList));
    result->head = NULL;
    result->tail = NULL;
    result->size = 0;

    struct Transaction* current = list->head;

    // Iterate through the transactions and add those within the specified time range to the result list
    while (current != NULL && current->timestamp <= endTimestamp) {
        if (current->timestamp >= startTimestamp) {
            insertTransaction(result, current->timestamp, current->amount, current->status);
        }

        current = current->next;
    }

    return result;
}

// Function to filter transactions by status and amount
struct TransactionList* filterTransactions(struct TransactionList* list, char status[], float minAmount, float maxAmount) {
    struct TransactionList* result = (struct TransactionList*)malloc(sizeof(struct TransactionList));
    result->head = NULL;
    result->tail = NULL;
    result->size = 0;

    struct Transaction* current = list->head;

    // Iterate through the transactions and add those that match the specified criteria to the result list
    while (current != NULL) {
        if (strcmp(current->status, status) == 0 && current->amount >= minAmount && current->amount <= maxAmount) {
            insertTransaction(result, current->timestamp, current->amount, current->status);
        }

        current = current->next;
    }

    return result;
}

