            printf("Error: Failed to allocate memory for node\n");
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }
        node->record = &records[i];
        node->next = head;
        head = node;
    }

    // Create the hash table for quick key-based lookups
    HashTable *hashTable = malloc(sizeof(HashTable));
    if (!hashTable) {
        printf("Error: Failed to allocate memory for hash table\n");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }
    hashTable->size = numRecords;
    hashTable->buckets = malloc(numRecords * sizeof(Node *));
    if (!hashTable->buckets) {
        printf("Error: Failed to allocate memory for buckets\n");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }
    for (size_t i = 0; i < numRecords; i++) {
        hashTable->buckets[i] = head;
    }

    // Return the initialized arrays and hash table
    return hashTable;
}

// Function to manage a linked list of records, supporting efficient insertion, deletion, and traversal operations.
void manageRecords(HashTable *hashTable) {
    // Insert a new record into the linked list
    void insertRecord(int key, Record *record) {
        Node *node = malloc(sizeof(Node));
        if (!node) {
            printf("Error: Failed to allocate memory for node\n");
            return;
        }
        node->record = record;
        node->next = hashTable->buckets[key];
        hashTable->buckets[key] = node;
    }

    // Delete a record from the linked list
    void deleteRecord(int key, Record *record) {
        Node **nodePtr = &hashTable->buckets[key];
        while (*nodePtr != NULL && (*nodePtr)->record != record) {
            nodePtr = &(*nodePtr)->next;
        }
