// Function to allocate memory from the memory pool
void* memory_pool_allocate(MemoryPool *memory_pool, int size) {
    // If there is not enough space in the memory pool, expand it
    if (memory_pool->used + size > memory_pool->size) {
        memory_pool->size += 1024 * 1024;
        memory_pool->memory = realloc(memory_pool->memory, memory_pool->size);
        if (!memory_pool->memory) {
            fprintf(stderr, "Failed to expand memory pool\n");
            return NULL;
        }
    }

    // Find the first free block in the linked list that is large enough for the allocation
    Node *node = memory_pool->head;
    while (node && node->next && node->next->size < size) {
        node = node->next;
