        record->offset = node->next->offset;
        record->value = 0;
        node->next->used = true;
        memory_pool->used += size;
        return record;
    } else {
        // Otherwise, allocate a new block and add it to the linked list
        Node *new_node = malloc(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Failed to allocate memory for new node\n");
            return NULL;
        }
        new_node->size = size;
        new_node->used = true;
        new_node->next = node->next;
        node->next = new_node;
        memory_pool->used += size;
        return new_node->memory;
    }
}

// Function to free memory from the memory pool
void memory_pool_free(MemoryPool *memory_pool, int size) {
    // Find the first block in the linked list that is large enough for the allocation
    Node *node = memory_pool->head;
    while (node && node->next && node->next->size < size) {
        node = node->next;
    }

    // If a suitable block was found, free it and update the linked list
    if (node && node->next && node->next->size >= size) {
        Record *record = malloc(sizeof(Record));
        if (!record) {
            fprintf(stderr, "Failed to allocate memory for new record\n");
            return;
        }
        record->offset = node->next->offset;
        record->value = 0;
        node->next->used = false;
        memory_pool->used -= size;
    } else {
        // Otherwise, free the entire linked list and reset the memory pool
        Node *node = memory_pool->head;
        while (node) {
            Record *record = malloc(sizeof(Record));
            if (!record) {
                fprintf(stderr, "Failed to allocate memory for new record\n");
                return;
            }
            record->offset = node->next->offset;
            record->value = 0;
            node->next->used = false;
            memory_pool->used -= size;
            Node *next_node = node->next;
            free(node);
            node = next_node;
        }
        memory_pool->head = NULL;
    }
}
