use std::fs;
use std::path::PathBuf;
use std::time::{SystemTime, UNIX_EPOCH};
use std::sync::Mutex;
use std::thread;

struct DirectoryCreator {
    directory: PathBuf,
    lock: Mutex<()>,
}

impl DirectoryCreator {
    fn new(directory: &str) -> Self {
        let mut directory = PathBuf::from(directory);
        directory.push("_");
        directory.push(SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs());

        DirectoryCreator {
            directory,
            lock: Mutex::new(()),
        }
    }

    fn create(&self) -> Result<(), String> {
        let mut lock = self.lock.lock().unwrap();

        if !self.directory.exists() {
            fs::create_dir(self.directory.clone()).map_err(|e| e.to_string())?;
        } else {
            return Err("Directory already exists".to_string());
        }

        Ok(())
    }
}

fn main() {
    let directory = "my_app/logs";
    let creator = DirectoryCreator::new(directory);

    // Create the directory in a separate thread to avoid blocking the main thread
    thread::spawn(move || {
        creator.create().unwrap();
    });
}
```
