#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <set>
#include <algorithm>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>

using namespace std;

struct Book {
    string title;
    string author;
    int publicationYear;
    set<string> genres;
    bool available;
};

struct Borrower {
    string name;
    string email;
    string phoneNumber;
    vector<Book> borrowedBooks;
};

struct LendingHistory {
    Book book;
    Borrower borrower;
    chrono::time_point<chrono::system_clock> lendDate;
    chrono::time_point<chrono::system_clock> returnDate;
};

class LibraryCatalog {
private:
    map<string, Book> bookMap; // Map of books by title
    map<string, Borrower> borrowerMap; // Map of borrowers by email or phone number
    vector<LendingHistory> lendingHistory; // Vector of lending history entries
    mutex bookMutex; // Mutex for protecting access to the book map
    mutex borrowerMutex; // Mutex for protecting access to the borrower map
    condition_variable cv; // Condition variable for notifying threads of changes
    bool isRunning; // Flag indicating whether the catalog is running

public:
    LibraryCatalog() {
        isRunning = true;
    }

    ~LibraryCatalog() {
        isRunning = false;
    }

    void addBook(const Book& book) {
        lock_guard<mutex> lock(bookMutex);
        bookMap[book.title] = book;
    }

    void removeBook(const string& title) {
        lock_guard<mutex> lock(bookMutex);
        bookMap.erase(title);
    }

    void addBorrower(const Borrower& borrower) {
        lock_guard<mutex> lock(borrowerMutex);
        borrowerMap[borrower.email] = borrower;
    }

    void removeBorrower(const string& email) {
        lock_guard<mutex> lock(borrowerMutex);
        borrowerMap.erase(email);
    }

    void lendBook(const Book& book, const Borrower& borrower) {
        lock_guard<mutex> lock(bookMutex);
        if (bookMap.find(book.title) != bookMap.end()) {
            LendingHistory history;
            history.book = book;
            history.borrower = borrower;
            history.lendDate = chrono::system_clock::now();
            lendingHistory.push_back(history);
        }
    }

    void returnBook(const Book& book, const Borrower& borrower) {
        lock_guard<mutex> lock(bookMutex);
        if (lendingHistory.size() > 0) {
            auto it = find_if(lendingHistory.begin(), lendingHistory.end(), [&](const LendingHistory& history) {
                return history.book == book && history.borrower == borrower;
            });
            if (it != lendingHistory.end()) {
                it->returnDate = chrono::system_clock::now();
            }
        }
    }

    void searchBooks(const string& query) {
        lock_guard<mutex> lock(bookMutex);
        vector<Book> results;
        for (auto it = bookMap.begin(); it != bookMap.end(); ++it) {
            if (it->second.title.find(query) != string::npos || it->second.author.find(query) != string::npos) {
                results.push_back(it->second);
            }
        }
    }

    void filterBooks(const vector<string>& genres, const vector<int>& publicationYears) {
        lock_guard<mutex> lock(bookMutex);
        vector<Book> results;
        for (auto it = bookMap.begin(); it != bookMap.end(); ++it) {
            if (find(genres.begin(), genres.end(), it->second.genre) != genres.end() && find(publicationYears.begin(), publicationYears.end(), it->second.publicationYear) != publicationYears.end()) {
                results.push_back(it->second);
            }
        }
    }

    void updateBookAvailability(const string& title, bool available) {
        lock_guard<mutex> lock(bookMutex);
        if (bookMap.find(title) != bookMap.end()) {
            bookMap[title].available = available;
        }
    }

    void notifyOverdueReturns() {
        lock_guard<mutex> lock(borrowerMutex);
        for (auto it = lendingHistory.begin(); it != lendingHistory.end(); ++it) {
            if (chrono::system_clock::now() - it->returnDate > chrono::hours(24)) {
                Borrower borrower = borrowerMap[it->borrower.email];
                string message = "Your book \"" + it->book.title + "\" is overdue and needs to be returned.";
                if (borrower.phoneNumber != "") {
                    sendSMS(borrower.phoneNumber, message);
                } else {
                    sendEmail(borrower.email, message);
                }
            }
        }
    }

    void detectAndReportMemoryLeaks() {
        lock_guard<mutex> lock(bookMutex);
        for (auto it = bookMap.begin(); it != bookMap.end(); ++it) {
            if (it->second.available && chrono::system_clock::now() - it->second.lendDate > chrono::hours(24)) {
                cout << "Memory leak detected: Book \"" + it->first + "\" is overdue and not returned." << endl;
            }
        }
    }

    void aggregateData() {
        lock_guard<mutex> lock(bookMutex);
        for (auto it = bookMap.begin(); it != bookMap.end(); ++it) {
            if (it->second.available && chrono::system_clock::now() - it->second.lendDate > chrono::hours(24)) {
                cout << "Book \"" + it->first + "\" is overdue and not returned." << endl;
            }
        }
    }

    void recommendBooks() {
        lock_guard<mutex> lock(bookMutex);
        for (auto it = borrowerMap.begin(); it != borrowerMap.end(); ++it) {
            vector<string> recommendedBooks;
            for (auto book : it->second.borrowedBooks) {
                if (book.genres.find(it->second.preferredGenre) != book.genres.end()) {
                    recommendedBooks.push_back(book.title);
                }
            }
        }
    }
};
