#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    long offset;
    int key;
    float precision;
    char* metadata;
} Record;

// Define the doubly-linked list node structure
typedef struct Node {
    Record* record;
    struct Node* next;
    struct Node* prev;
} Node;

// Define the hash table structure
typedef struct {
    int size;
    int count;
    Node** nodes;
} HashTable;

// Define the function to dynamically manage memory for records
void manage_records(Record* record, int operation) {
    // Acquire a lock on the hash table
    pthread_mutex_lock(&hash_table.lock);

    // Perform the requested operation on the record
    switch (operation) {
        case INSERT:
            // Insert the record into the hash table
            insert_record(record);
            break;
        case DELETE:
            // Delete the record from the hash table
            delete_record(record);
            break;
        case UPDATE:
            // Update the record in the hash table
            update_record(record);
            break;
    }

    // Release the lock on the hash table
    pthread_mutex_unlock(&hash_table.lock);
}

// Define the function to insert a record into the hash table
void insert_record(Record* record) {
    // Calculate the hash value for the record
    int hash = calculate_hash(record->key);

    // Check if the hash table needs to be resized
    if (hash_table.count >= hash_table.size * LOAD_FACTOR) {
        resize_hash_table();
    }

    // Insert the record into the hash table
    Node* node = malloc(sizeof(Node));
    node->record = record;
    node->next = NULL;
    node->prev = NULL;
    hash_table.nodes[hash] = node;
    hash_table.count++;
}

// Define the function to delete a record from the hash table
void delete_record(Record* record) {
    // Calculate the hash value for the record
    int hash = calculate_hash(record->key);

    // Check if the record exists in the hash table
    Node* node = hash_table.nodes[hash];
    while (node != NULL && node->record != record) {
        node = node->next;
    }

    // If the record is found, delete it from the hash table
    if (node != NULL) {
        Node* prev = node->prev;
        Node* next = node->next;
        if (prev != NULL) {
            prev->next = next;
        } else {
            hash_table.nodes[hash] = next;
        }
        if (next != NULL) {
            next->prev = prev;
        }
        free(node);
        hash_table.count--;
    }
}

// Define the function to update a record in the hash table
void update_record(Record* record) {
    // Calculate the hash value for the record
    int hash = calculate_hash(record->key);

    // Check if the record exists in the hash table
    Node* node = hash_table.nodes[hash];
    while (node != NULL && node->record != record) {
        node = node->next;
    }

    // If the record is found, update it in the hash table
    if (node != NULL) {
        node->record = record;
    }
}

// Define the function to calculate the hash value for a record
int calculate_hash(int key) {
    return key % HASH_TABLE_SIZE;
}

// Define the function to resize the hash table
void resize_hash_table() {
    // Create a new hash table with twice the size of the current one
    HashTable* new_hash_table = malloc(sizeof(HashTable));
    new_hash_table->size = 2 * hash_table.size;
    new_hash_table->count = 0;
    new_hash_table->nodes = malloc(new_hash_table->size * sizeof(Node*));

    // Copy the records from the old hash table to the new one
    for (int i = 0; i < hash_table.size; i++) {
        Node* node = hash_table.nodes[i];
        while (node != NULL) {
            insert_record(node->record);
            node = node->next;
        }
    }

    // Free the old hash table and replace it with the new one
    free(hash_table.nodes);
    hash_table = *new_hash_table;
}
