        keys[i] = rand() % length;
    }

    // Allocate memory for the record array
    Record* records = (Record*)malloc(num_elements * sizeof(Record));
    if (!records) {
        printf("Error: Failed to allocate memory for record array\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize the records with random values
    for (int i = 0; i < num_elements; i++) {
        records[i].value = rand() % length;
    }

    // Serialize the data structure into a binary format
    size_t serialized_size = sizeof(offsets) + sizeof(keys) + sizeof(records);
    void* serialized_data = malloc(serialized_size);
    if (!serialized_data) {
        printf("Error: Failed to allocate memory for serialized data\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }
    memcpy(serialized_data, offsets, sizeof(offsets));
    memcpy((char*)serialized_data + sizeof(offsets), keys, sizeof(keys));
    memcpy((char*)serialized_data + sizeof(offsets) + sizeof(keys), records, sizeof(records));

    // Hash the password using a default hash function
