        printf("Error: Failed to hash password\n");
        free(serialized_data);
        free(hashed_password);
        return;
    }

    // Return the serialized data and hashed password as a tuple
    Tuple* result = (Tuple*)malloc(sizeof(Tuple));
    if (!result) {
        printf("Error: Failed to allocate memory for result\n");
        free(serialized_data);
        free(hashed_password);
        return;
