} entry_t;

// Define a function to initialize the data structures
void init_data_structures(int num_entries) {
    // Allocate memory for the offset array
    long *offsets = malloc(num_entries * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        exit(1);
    }

    // Initialize the offset array with sequential values starting from 0
    for (int i = 0; i < num_entries; i++) {
        offsets[i] = i * sizeof(entry_t);
    }

    // Allocate memory for the key array
    int *keys = malloc(num_entries * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        exit(1);
    }

    // Initialize the key array with random values between 0 and 1
    srand(time(NULL));
    for (int i = 0; i < num_entries; i++) {
        keys[i] = rand() % 10000;
    }

    // Allocate memory for the entry array
    entry_t *entries = malloc(num_entries * sizeof(entry_t));
    if (!entries) {
        perror("Failed to allocate memory for entries");
        exit(1);
    }

    // Initialize the timestamp and value fields of each entry
    time_t current_time = time(NULL);
    for (int i = 0; i < num_entries; i++) {
        entries[i].timestamp = current_time + i * 1000;
        entries[i].value = drand48();
