    // Store the pointers to the data structures in a global variable
    global_data_structures.offsets = offsets;
    global_data_structures.keys = keys;
    global_data_structures.entries = entries;
}

// Define a function to add an entry to the data structure
void add_entry(int key, double value) {
    // Check if the data structures have been initialized
    if (!global_data_structures.offsets || !global_data_structures.keys || !global_data_structures.entries) {
        init_data_structures(10000);
    }

    // Find the next available slot in the data structures
    int index = 0;
    while (index < global_data_structures.num_entries && global_data_structures.keys[index] != -1) {
        index++;
    }

    // If no slots are available, reallocate the data structures with a larger size
    if (index == global_data_structures.num_entries) {
        int new_size = global_data_structures.num_entries * 2;
        long *new_offsets = realloc(global_data_structures.offsets, new_size * sizeof(long));
        if (!new_offsets) {
            perror("Failed to reallocate memory for offsets");
            exit(1);
        }
        global_data_structures.offsets = new_offsets;

        int *new_keys = realloc(global_data_structures.keys, new_size * sizeof(int));
        if (!new_keys) {
            perror("Failed to reallocate memory for keys");
            exit(1);
        }
        global_data_structures.keys = new_keys;

        entry_t *new_entries = realloc(global_data_structures.entries, new_size * sizeof(entry_t));
        if (!new_entries) {
            perror("Failed to reallocate memory for entries");
            exit(1);
        }
        global_data_structures.entries = new_entries;

        global_data_structures.num_entries = new_size;
    }

    // Add the entry to the data structures
    global_data_structures.keys[index] = key;
    global_data_structures.offsets[index] = index * sizeof(entry_t);
    global_data_structures.entries[index].timestamp = time(NULL);
    global_data_structures.entries[index].value = value;
}

// Define a function to retrieve an entry from the data structure
void get_entry(int key, double *value) {
    // Check if the data structures have been initialized
    if (!global_data_structures.offsets || !global_data_structures.keys || !global_data_structures.entries) {
        init_data_structures(10000);
    }

    // Find the index of the entry with the given key
    int index = 0;
    while (index < global_data_structures.num_entries && global_data_structures.keys[index] != key) {
        index++;
    }

    // If the entry is not found, return a default value
    if (index == global_data_structures.num_entries) {
        *value = 0;
        return;
    }

    // Return the value of the entry
    *value = global_data_structures.entries[index].value;
}

// Define a function to delete an entry from the data structure
void delete_entry(int key) {
    // Check if the data structures have been initialized
    if (!global_data_structures.offsets || !global_data_structures.keys || !global_data_structures.entries) {
        init_data_structures(10000);
    }

    // Find the index of the entry with the given key
    int index = 0;
    while (index < global_data_structures.num_entries && global_data_structures.keys[index] != key) {
        index++;
    }

    // If the entry is not found, return
    if (index == global_data_structures.num_entries) {
        return;
    }

    // Shift all subsequent entries to fill the gap
    for (int i = index + 1; i < global_data_structures.num_entries; i++) {
        global_data_structures.keys[i - 1] = global_data_structures.keys[i];
        global_data_structures.offsets[i - 1] = global_data_structures.offsets[i];
        global_data_structures.entries[i - 1] = global_data_structures.entries[i];
    }

    // Decrement the number of entries and reallocate the data structures if necessary
    global_data_structures.num_entries--;
    if (global_data_structures.num_entries < 10000 / 2) {
        int new_size = global_data_structures.num_entries * 2;
        long *new_offsets = realloc(global_data_structures.offsets, new_size * sizeof(long));
        if (!new_offsets) {
