void resizeRecordArray(int numRecords, Record *records) {
    // Check if the input parameters are valid
    if (numRecords <= 0 || numRecords > MAX_RECORDS) {
        printf("Invalid number of records: %d\n", numRecords);
        return;
    }

    // Resize the record array to fit the new number of records
    size_t newRecordArraySize = RECORD_ARRAY_SIZE / numRecords;
    Record *newRecords = realloc(records, newRecordArraySize);

    // Check if memory allocation failed
