#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/ipc.h>
#include <sys/shm.h>
#include <sys/msg.h>

// Define the entry structure for storing data
struct entry {
    time_t timestamp;
    double value;
};

// Define the message queue structure for communication between threads
struct msg_queue {
    int qid;
    struct msqid_ds ds;
};

// Define the shared memory structure for storing data
struct shm_data {
    int shmid;
    struct entry *entries;
    size_t num_entries;
    pthread_mutex_t mutex;
};

// Define the thread-safe queue for storing messages
struct msg_queue_queue {
    semaphore_t sem;
    int qid;
    struct msqid_ds ds;
};

// Initialize the shared memory and message queues
void init_shm(int num_entries) {
    // Create a new shared memory segment
    shmid = shmget(IPC_PRIVATE, sizeof(struct shm_data), 0644);
    if (shmid < 0) {
        perror("shmget");
        exit(1);
    }

    // Attach the shared memory segment to the process's address space
    struct shm_data *shm = shmat(shmid, NULL, 0);
    if (shm == (void *)-1) {
        perror("shmat");
        exit(1);
    }

    // Initialize the shared memory structure
    shm->num_entries = num_entries;
    shm->entries = malloc(sizeof(struct entry) * num_entries);
    if (shm->entries == NULL) {
        perror("malloc");
        exit(1);
    }

    // Initialize the mutex for protecting the shared memory structure
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_setpshared(&attr, PTHREAD_PROCESS_SHARED);
    pthread_mutex_init(&shm->mutex, &attr);

    // Create a new message queue for communication between threads
    qid = msgget(IPC_PRIVATE, 0644);
    if (qid < 0) {
        perror("msgget");
        exit(1);
    }
}

// Initialize the thread-safe queue for storing messages
void init_queue() {
    // Create a new semaphore for protecting the message queue
    sem = sem_open("/sem", O_CREAT, 0644, 1);
    if (sem == SEM_FAILED) {
        perror("sem_open");
        exit(1);
    }

    // Create a new message queue for communication between threads
    qid = msgget(IPC_PRIVATE, 0644);
    if (qid < 0) {
        perror("msgget");
        exit(1);
    }
}

// Add an entry to the shared memory and message queue
void add_entry(struct entry *entry) {
    // Lock the mutex for protecting the shared memory structure
    pthread_mutex_lock(&shm->mutex);

    // Check if there is enough space in the shared memory segment
    if (shm->num_entries >= MAX_ENTRIES) {
        // If not, allocate a new shared memory segment and copy the data over
        int new_shmid = shmget(IPC_PRIVATE, sizeof(struct shm_data), 0644);
        if (new_shmid < 0) {
            perror("shmget");
            exit(1);
        }

        // Attach the new shared memory segment to the process's address space
        struct shm_data *new_shm = shmat(new_shmid, NULL, 0);
        if (new_shm == (void *)-1) {
            perror("shmat");
            exit(1);
        }

        // Copy the data from the old shared memory segment to the new one
        memcpy(new_shm->entries, shm->entries, sizeof(struct entry) * shm->num_entries);

        // Detach and destroy the old shared memory segment
        if (shmdt(shm->entries) < 0) {
            perror("shmdt");
            exit(1);
        }
        if (shmctl(shmid, IPC_RMID, NULL) < 0) {
            perror("shmctl");
            exit(1);
        }

        // Update the shared memory structure and mutex to use the new segment
        shm = new_shm;
        pthread_mutex_unlock(&shm->mutex);
    } else {
        // If there is enough space, add the entry to the shared memory segment
        memcpy(shm->entries + shm->num_entries, entry, sizeof(struct entry));
        shm->num_entries++;

        // Unlock the mutex and return
        pthread_mutex_unlock(&shm->mutex);
    }
}

// Remove an entry from the shared memory and message queue
void remove_entry(int index) {
    // Lock the mutex for protecting the shared memory structure
    pthread_mutex_lock(&shm->mutex);

    // Check if the index is valid
    if (index >= shm->num_entries || index < 0) {
        perror("Invalid index");
        exit(1);
    }

    // Remove the entry from the shared memory segment
    memmove(shm->entries + index, shm->entries + index + 1, sizeof(struct entry) * (shm->num_entries - index - 1));
    shm->num_entries--;

    // Unlock the mutex and return
    pthread_mutex_unlock(&shm->mutex);
}

// Get an entry from the shared memory and message queue
struct entry *get_entry(int index) {
    // Lock the mutex for protecting the shared memory structure
    pthread_mutex_lock(&shm->mutex);

    // Check if the index is valid
    if (index >= shm->num_entries || index < 0) {
        perror("Invalid index");
        exit(1);
    }

    // Return a copy of the entry from the shared memory segment
    struct entry *entry = malloc(sizeof(struct entry));
    memcpy(entry, shm->entries + index, sizeof(struct entry));

    // Unlock the mutex and return
    pthread_mutex_unlock(&shm->mutex);
    return entry;
}

// Get the number of entries in the shared memory and message queue
int get_num_entries() {
    // Lock the mutex for protecting the shared memory structure
    pthread_mutex_lock(&shm->mutex);

    // Return the number of entries in the shared memory segment
    int num_entries = shm->num_entries;

    // Unlock the mutex and return
    pthread_mutex_unlock(&shm->mutex);
    return num_entries;
}

// Send a message to the message queue
void send_msg(struct msg_queue *q, struct entry *entry) {
    // Lock the semaphore for protecting the message queue
    sem_wait(sem);

    // Check if there is enough space in the message queue
    if (q->ds.msg_qnum >= MAX_MSG_NUM) {
        // If not, wait until there is enough space
        while (q->ds.msg_qnum >= MAX_MSG_NUM) {
            sem_wait(sem);
        }
    }

    // Add the entry to the message queue
    memcpy(q->entries + q->ds.msg_cbytes, entry, sizeof(struct entry));
    q->ds.msg_cbytes += sizeof(struct entry);
    q->ds.msg_qnum++;

    // Unlock the semaphore and return
    sem_post(sem);
}

// Receive a message from the message queue
struct entry *recv_msg(struct msg_queue *q) {
    // Lock the semaphore for protecting the message queue
    sem_wait(sem);

    // Check if there are any messages in the message queue
    if (q->ds.msg_qnum <= 0) {
        // If not, wait until there is a message
        while (q->ds.msg_qnum <= 0) {
            sem_wait(sem);
        }
    }

    // Get the first entry from the message queue
    struct entry *entry = malloc(sizeof(struct entry));
    memcpy(entry, q->entries + q->ds.msg_rbytes, sizeof(struct entry));
    q->ds.msg_rbytes += sizeof(struct entry);
    q->ds.msg_qnum--;

    // Unlock the semaphore and return
    sem_post(sem);
    return entry;
}

// Main function for the data ingestion and processing pipeline
int main() {
    // Initialize the shared memory and message queues
    init_shm(MAX_ENTRIES);
    init_queue();

    // Create a new thread for each data source
    pthread_t threads[NUM_SOURCES];
    for (int i = 0; i < NUM_SOURCES; i++) {
        struct entry *entry = malloc(sizeof(struct entry));
        entry->timestamp = time(NULL);
        entry->value = drand48();
        send_msg(&q, entry);
    }

    // Create a new thread for each processing stage
    pthread_t stages[NUM_STAGES];
    for (int i = 0; i < NUM_STAGES; i++) {
        struct entry *entry = malloc(sizeof(struct entry));
        entry->timestamp = time(NULL);
        entry->value = drand48();
        send_msg(&q, entry);
    }

    // Create a new thread for each output stage
    pthread_t outputs[NUM_OUTPUTS];
    for (int i = 0; i < NUM_OUTPUTS; i++) {
        struct entry *entry = malloc(sizeof(struct entry));
        entry->timestamp = time(NULL);
        entry->value = drand48();
        send_msg(&q, entry);
    }

    // Start the threads for each data source, processing stage, and output stage
    for (int i = 0; i < NUM_SOURCES; i++) {
        pthread_create(&threads[i], NULL, process_data, &q);
    }
    for (int i = 0; i < NUM_STAGES; i++) {
        pthread_create(&stages[i], NULL, process_stage, &q);
    }
    for (int i = 0; i < NUM_OUTPUTS; i++) {
        pthread_create(&outputs[i], NULL, output_data, &q);
    }

    // Wait for the threads to finish
    for (int i = 0; i < NUM_SOURCES; i++) {
        pthread_join(threads[i], NULL);
    }
    for (int i = 0; i < NUM_STAGES; i++) {
        pthread_join(stages[i], NULL);
    }
    for (int i = 0; i < NUM_OUTPUTS; i++) {
        pthread_join(outputs[i], NULL);
    }

    // Clean up the shared memory and message queues
    shmdt(shm->entries);
    shmctl(shmid, IPC_RMID, NULL);
    msgctl(qid, IPC_RMID, NULL);

    return 0;
}

// Process data from the message queue and add it to the shared memory
void *process_data(void *arg) {
    struct msg_queue *q = (struct msg_queue *)arg;

    // Loop indefinitely until a signal is received
    while (1) {
        // Receive a message from the message queue
        struct entry *entry = recv_msg(q);

        // Add the entry to the shared memory
        add_entry(entry);

        // Free the memory allocated for the entry
        free(entry);
    }
}

// Process data from the shared memory and add it to the message queue
void *process_stage(void *arg) {
    struct msg_queue *q = (struct msg_queue *)arg;

    // Loop indefinitely until a signal is received
    while (1) {
        // Get an entry from the shared memory
        struct entry *entry = get_entry(0);

        // Add the entry to the message queue
        send_msg(q, entry);

        // Remove the entry from the shared memory
        remove_entry(0);
    }
}

// Output data from the message queue and add it to the shared memory
void *output_data(void *arg) {
    struct msg_queue *q = (struct msg_queue *)arg;

    // Loop indefinitely until a signal is received
    while (1) {
        // Receive a message from the message queue
        struct entry *entry = recv_msg(q);

        // Add the entry to the shared memory
