void traverse_records(DataStructure* ds, void (*callback)(Record*)) {
    assert(ds != NULL);
    assert(callback != NULL);

    // Iterate over the records in the data structure and call the callback function on each one
    for (int i = 0; i < ds->num_records; i++) {
        callback(&ds->records[i]);
    }
}

// Function to resize the data structure when it becomes full
void resize_data_structure(DataStructure* ds, size_t new_size) {
    assert(ds != NULL);
    assert(new_size > 0);

    // Create a new array of offset values with the given size
    long* new_offsets = malloc(sizeof(long) * new_size);
    if (new_offsets == NULL) {
        return;
    }

    // Copy the old offset values to the new array and free the old one
    memcpy(new_offsets, ds->offsets, sizeof(long) * ds->num_records);
    free(ds->offsets);
    ds->offsets = new_offsets;

    // Create a new array of keys with the given size
    int* new_keys = malloc(sizeof(int) * new_size);
    if (new_keys == NULL) {
        return;
    }

    // Copy the old key values to the new array and free the old one
    memcpy(new_keys, ds->keys, sizeof(int) * ds->num_records);
    free(ds->keys);
    ds->keys = new_keys;

    // Create a new array of record structures with the given size
    Record* new_records = malloc(sizeof(Record) * new_size);
    if (new_records == NULL) {
        return;
    }

    // Copy the old records to the new array and free the old one
    memcpy(new_records, ds->records, sizeof(Record) * ds->num_records);
    free(ds->records);
    ds->records = new_records;

    // Update the size of the data structure
    ds->offsets->size = new_size;
}

// Function to handle DNS resolution for a given hostname
int resolve_hostname(const char* hostname, u_char* ip) {
    assert(hostname != NULL);
    assert(ip != NULL);

    // Use the standard library functions to perform DNS resolution
    struct addrinfo hints;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = IPPROTO_TCP;

    struct addrinfo* result;
    int rc = getaddrinfo(hostname, NULL, &hints, &result);
    if (rc != 0) {
        return -1;
    }

    // Copy the IP address to the output parameter and free the memory allocated by getaddrinfo()
    memcpy(ip, result->ai_addr, sizeof(struct sockaddr));
    freeaddrinfo(result);

    return 0;
}
