    new_data->id = id;
    new_data->timestamp = get_timestamp();
    new_data->refcount = 1;

    pthread_mutex_lock(&repo->mutex);
    repo->data[repo->count++] = new_data;
    pthread_mutex_unlock(&repo->mutex);
}

