  void addBook(const Book& book) {
    books_.push_back(book);
  }

  // Remove a book entry from the catalog
  void removeBook(int bookId) {
    for (auto it = books_.begin(); it != books_.end(); ++it) {
      if (it->id == bookId) {
        books_.erase(it);
        break;
      }
    }
  }

