    vector<Book> results;
    for (auto it = books_.begin(); it != books_.end(); ++it) {
      if ((title.empty() || it->title == title) &&
          (author.empty() || it->author == author) &&
          (publicationYear == 0 || it->publicationYear == publicationYear) &&
          (genre.empty() || it->genre == genre)) {
        results.push_back(*it);
      }
    }
    return results;
  }

