      if (it->bookId == entry.bookId && it->borrowerId == entry.borrowerId) {
        *it = entry;
        break;
      }
    }
  }

  // Search for lending history entries based on various criteria
  vector<LendingHistoryEntry> searchLendingHistory(const string& title, const string& author, int publicationYear, const string& genre) {
    vector<LendingHistoryEntry> results;
    for (auto it = lendingHistory_.begin(); it != lendingHistory_.end(); ++it) {
      if ((title.empty() || it->bookId == title) &&
          (author.empty() || it->author == author) &&
          (publicationYear == 0 || it->publicationYear == publicationYear) &&
          (genre.empty() || it->genre == genre)) {
        results.push_back(*it);
      }
    }
    return results;
  }

  // Retrieve a lending history entry from the catalog by book ID and borrower ID
  LendingHistoryEntry getLendingHistoryEntry(int bookId, int borrowerId) {
    for (auto it = lendingHistory_.begin(); it != lendingHistory_.end(); ++it) {
      if (it->bookId == bookId && it->borrowerId == borrowerId) {
        return *it;
      }
    }
    throw runtime_error("Lending history entry not found");
  }

 private:
  // Vector of book entries
  vector<Book> books_;

  // Map of book IDs to book entries
  map<int, Book> bookIdMap_;

  // Vector of borrower information
  vector<Borrower> borrowers_;

  // Map of borrower IDs to borrower information
  map<int, Borrower> borrowerIdMap_;

  // Vector of lending history entries
  vector<LendingHistoryEntry> lendingHistory_;

  // Map of book IDs to lending history entries
  map<int, LendingHistoryEntry> bookIdToLendingHistoryMap_;

  // Map of borrower IDs to lending history entries
  map<int, LendingHistoryEntry> borrowerIdToLendingHistoryMap_;
};
