#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

// Define the structure for the hash table records
typedef struct {
    int key;
    long offset;
} record_t;

// Define the hash table data structure
typedef struct {
    record_t **records;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} hash_table_t;

// Function to initialize a new hash table
hash_table_t *init_hash_table(size_t capacity) {
    // Allocate memory for the hash table records and initialize them to NULL
    record_t **records = malloc(capacity * sizeof(record_t*));
    memset(records, 0, capacity * sizeof(record_t*));

    // Initialize the mutex for synchronizing access to the hash table
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    // Create a new hash table with the specified capacity and initialize it to empty
    hash_table_t *hash_table = malloc(sizeof(hash_table_t));
    hash_table->records = records;
    hash_table->capacity = capacity;
    hash_table->count = 0;
    hash_table->mutex = mutex;

    return hash_table;
}

// Function to insert a new record into the hash table
void insert(hash_table_t *hash_table, int key, long offset) {
    // Acquire the lock on the hash table
    pthread_mutex_lock(&hash_table->mutex);

    // Check if the hash table is full and needs to be resized
    if (hash_table->count == hash_table->capacity) {
        resize(hash_table);
    }

    // Allocate memory for the new record and initialize it
    record_t *new_record = malloc(sizeof(record_t));
    new_record->key = key;
    new_record->offset = offset;

    // Insert the new record into the hash table
    hash_table->records[hash_function(key)] = new_record;
    hash_table->count++;

    // Release the lock on the hash table
    pthread_mutex_unlock(&hash_table->mutex);
}

// Function to lookup a record in the hash table
record_t *lookup(hash_table_t *hash_table, int key) {
    // Acquire the lock on the hash table
    pthread_mutex_lock(&hash_table->mutex);

    // Compute the hash value for the given key
    size_t index = hash_function(key);

    // Search for the record in the hash table
    while (hash_table->records[index] != NULL && hash_table->records[index]->key != key) {
        index++;
        if (index == hash_table->capacity) {
            index = 0;
        }
    }

    // Return the record if found, or NULL if not found
    record_t *record = hash_table->records[index];
    pthread_mutex_unlock(&hash_table->mutex);
    return record;
}

// Function to delete a record from the hash table
void delete(hash_table_t *hash_table, int key) {
    // Acquire the lock on the hash table
    pthread_mutex_lock(&hash_table->mutex);

    // Compute the hash value for the given key
    size_t index = hash_function(key);

    // Search for the record in the hash table
    while (hash_table->records[index] != NULL && hash_table->records[index]->key != key) {
        index++;
        if (index == hash_table->capacity) {
            index = 0;
        }
    }

    // If the record is found, delete it from the hash table
    if (hash_table->records[index] != NULL) {
        free(hash_table->records[index]);
        hash_table->records[index] = NULL;
        hash_table->count--;
    }

    // Release the lock on the hash table
    pthread_mutex_unlock(&hash_table->mutex);
}

// Function to resize the hash table when it is full
void resize(hash_table_t *hash_table) {
    // Double the capacity of the hash table
    size_t new_capacity = hash_table->capacity * 2;

    // Allocate memory for the new records and initialize them to NULL
    record_t **new_records = malloc(new_capacity * sizeof(record_t*));
    memset(new_records, 0, new_capacity * sizeof(record_t*));

    // Copy the existing records from the old hash table to the new one
    for (size_t i = 0; i < hash_table->capacity; i++) {
        if (hash_table->records[i] != NULL) {
            record_t *record = hash_table->records[i];
            size_t new_index = hash_function(record->key);
            while (new_records[new_index] != NULL && new_records[new_index]->key != record->key) {
                new_index++;
                if (new_index == new_capacity) {
                    new_index = 0;
                }
            }
            new_records[new_index] = record;
        }
    }

    // Free the old records and update the hash table with the new ones
    free(hash_table->records);
    hash_table->records = new_records;
    hash_table->capacity = new_capacity;
}

// Function to compute the hash value for a given key
size_t hash_function(int key) {
    return key % hash_table->capacity;
}
