// Define data structures for long offset values, int keys, and record structures with embedded keys and offsets
typedef struct {
    long offset;
} LongOffset;

typedef struct {
    int key;
    LongOffset *offsets;
} IntKey;

typedef struct {
    IntKey *keys;
    size_t num_keys;
} Record;

// Function to allocate and manage memory for various data structures
void allocate_memory(Record **records, size_t num_records) {
    // Allocate memory for the records
    *records = (Record *)malloc(num_records * sizeof(Record));
    if (*records == NULL) {
        printf("Error: Failed to allocate memory for records\n");
        exit(1);
    }

    // Initialize each record with an integer value within a configurable range
    for (size_t i = 0; i < num_records; i++) {
        (*records)[i].keys = (IntKey *)malloc(sizeof(IntKey));
        if ((*records)[i].keys == NULL) {
            printf("Error: Failed to allocate memory for keys\n");
            exit(1);
        }
        (*records)[i].num_keys = 0;
    }
}

// Function to handle dynamic data generation and memory allocation
void generate_data(Record **records, size_t num_records) {
    // Generate random integer values within a configurable range for each record
    srand(time(NULL));
    for (size_t i = 0; i < num_records; i++) {
        (*records)[i].keys->key = rand() % 100 + 1;
        (*records)[i].num_keys++;
    }
}

// Function to handle memory deallocation and resource management
void free_memory(Record **records, size_t num_records) {
    // Free the memory allocated for each record
    for (size_t i = 0; i < num_records; i++) {
        if ((*records)[i].keys != NULL) {
            free((*records)[i].keys);
        }
    }
    // Free the memory allocated for the records array
    free(*records);
}
