#include <pthread.h>

// Define a struct to represent a data point
typedef struct DataPoint {
    double value;
    char *string;
    float timestamp;
    int id;
} DataPoint;

// Define a linked list node to store data points
typedef struct Node {
    DataPoint *data_point;
    struct Node *next;
} Node;

// Define a hash table to store data points based on their string keys
typedef struct HashTable {
    int size;
    Node **buckets;
} HashTable;

// Function to create a new linked list node for a data point
Node *create_node(DataPoint *data_point) {
    Node *node = malloc(sizeof(Node));
    node->data_point = data_point;
    node->next = NULL;
    return node;
}

// Function to create a new hash table with the given size
HashTable *create_hash_table(int size) {
    HashTable *hash_table = malloc(sizeof(HashTable));
    hash_table->size = size;
    hash_table->buckets = calloc(size, sizeof(Node*));
    return hash_table;
}

// Function to insert a data point into the linked list and hash table
void insert_data_point(HashTable *hash_table, DataPoint *data_point) {
    // Get the current system time in milliseconds
    long long timestamp = (long long)(time(NULL) * 1000);

    // Create a new linked list node for the data point
    Node *node = create_node(data_point);

    // Insert the node into the linked list and hash table
    pthread_mutex_lock(&hash_table->mutex);
    int index = hash_function(data_point->string) % hash_table->size;
    node->next = hash_table->buckets[index];
    hash_table->buckets[index] = node;
    pthread_mutex_unlock(&hash_table->mutex);

    // Update the timestamp of the data point
    data_point->timestamp = (float)timestamp;
}

// Function to retrieve a data point from the linked list and hash table
DataPoint *retrieve_data_point(HashTable *hash_table, char *string) {
    // Get the current system time in milliseconds
    long long timestamp = (long long)(time(NULL) * 1000);

    // Calculate the hash value for the given string
    int index = hash_function(string) % hash_table->size;

    // Search for the data point in the linked list and hash table
    Node *node = hash_table->buckets[index];
    while (node != NULL && strcmp(node->data_point->string, string) != 0) {
        node = node->next;
    }

    // If the data point is found, update its timestamp and return it
    if (node != NULL) {
        DataPoint *data_point = node->data_point;
        data_point->timestamp = (float)timestamp;
        return data_point;
    } else {
        // If the data point is not found, return NULL
        return NULL;
    }
}

// Function to modify a data point in the linked list and hash table
void modify_data_point(HashTable *hash_table, DataPoint *data_point) {
    // Get the current system time in milliseconds
    long long timestamp = (long long)(time(NULL) * 1000);

    // Calculate the hash value for the given string
    int index = hash_function(data_point->string) % hash_table->size;

    // Search for the data point in the linked list and hash table
    Node *node = hash_table->buckets[index];
    while (node != NULL && strcmp(node->data_point->string, data_point->string) != 0) {
        node = node->next;
    }

    // If the data point is found, update its value and timestamp
    if (node != NULL) {
        DataPoint *data_point = node->data_point;
        data_point->value = data_point->value;
        data_point->timestamp = (float)timestamp;
    } else {
        // If the data point is not found, insert it into the linked list and hash table
        insert_data_point(hash_table, data_point);
    }
}

// Function to delete a data point from the linked list and hash table
void delete_data_point(HashTable *hash_table, char *string) {
    // Calculate the hash value for the given string
    int index = hash_function(string) % hash_table->size;

    // Search for the data point in the linked list and hash table
    Node **node = &hash_table->buckets[index];
    while (*node != NULL && strcmp((*node)->data_point->string, string) != 0) {
        node = &(*node)->next;
    }

    // If the data point is found, delete it from the linked list and hash table
    if (*node != NULL) {
        DataPoint *data_point = (*node)->data_point;
        free(data_point);
        *node = (*node)->next;
    } else {
        // If the data point is not found, do nothing
    }
}

// Function to handle hash collisions by chaining nodes together
void handle_hash_collision(HashTable *hash_table, int index) {
    Node **node = &hash_table->buckets[index];
    while (*node != NULL && (*node)->next != NULL) {
        node = &(*node)->next;
    }
    if (*node == NULL) {
        *node = create_node(NULL);
    }
}

// Function to hash a string and return an index in the hash table
int hash_function(char *string) {
    int hash = 0;
    for (int i = 0; i < strlen(string); i++) {
        hash += string[i];
    }
    return hash % hash_table->size;
}

