#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    int key;
    double value;
    struct record *next;
} record;

// Define the doubly-linked list node structure
typedef struct {
    long offset;
    int key;
    double value;
    struct record *next;
    struct record *prev;
} node;

// Define the hash table structure
typedef struct {
    int size;
    int capacity;
    node **table;
} hash_table;

// Function to initialize the data structure
void init(hash_table *ht, int size) {
    // Allocate memory for the hash table and its nodes
    ht->size = 0;
    ht->capacity = size;
    ht->table = (node **)malloc(sizeof(node *) * size);
    if (!ht->table) {
        printf("Error: Failed to allocate memory for hash table\n");
        exit(1);
    }
}

// Function to insert a new record into the data structure
void insert(hash_table *ht, int key, double value) {
    // Generate a random integer and floating-point number within specified ranges
    srand(time(NULL));
    int rand_int = rand() % 100;
    double rand_double = (double)rand() / RAND_MAX;

    // Allocate memory for the new record
    node *new_node = (node *)malloc(sizeof(node));
    if (!new_node) {
        printf("Error: Failed to allocate memory for new record\n");
        exit(1);
    }

    // Initialize the new record with the generated values
    new_node->offset = rand_int;
    new_node->key = key;
    new_node->value = value;
    new_node->next = NULL;
    new_node->prev = NULL;

    // Insert the new record into the hash table
    int index = ht->size % ht->capacity;
    if (ht->table[index] == NULL) {
        ht->table[index] = new_node;
    } else {
        node *curr = ht->table[index];
        while (curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = new_node;
        new_node->prev = curr;
    }

    // Increment the size of the hash table
    ht->size++;
}

// Function to delete a record from the data structure
void delete(hash_table *ht, int key) {
    // Find the index of the record in the hash table
    int index = ht->size % ht->capacity;
    node *curr = ht->table[index];
    while (curr != NULL && curr->key != key) {
        curr = curr->next;
    }

    // If the record is found, delete it from the hash table
    if (curr != NULL) {
        if (curr == ht->table[index]) {
            ht->table[index] = curr->next;
        } else {
            curr->prev->next = curr->next;
        }
        free(curr);
        ht->size--;
    }
}

// Function to search for a record in the data structure
node *search(hash_table *ht, int key) {
    // Find the index of the record in the hash table
    int index = ht->size % ht->capacity;
    node *curr = ht->table[index];
    while (curr != NULL && curr->key != key) {
        curr = curr->next;
    }

    // If the record is found, return it
    if (curr != NULL) {
        return curr;
    } else {
        return NULL;
    }
}

// Function to traverse the data structure in forward order
void traverse_forward(hash_table *ht) {
    // Iterate through each node in the hash table
    for (int i = 0; i < ht->capacity; i++) {
        node *curr = ht->table[i];
        while (curr != NULL) {
            printf("%d: %d, %.2f\n", curr->offset, curr->key, curr->value);
            curr = curr->next;
        }
    }
}

// Function to traverse the data structure in backward order
void traverse_backward(hash_table *ht) {
    // Iterate through each node in the hash table
    for (int i = ht->capacity - 1; i >= 0; i--) {
        node *curr = ht->table[i];
        while (curr != NULL) {
            printf("%d: %d, %.2f\n", curr->offset, curr->key, curr->value);
            curr = curr->prev;
        }
    }
}

// Function to handle memory allocation failures gracefully
void handle_memory_allocation_failure(hash_table *ht) {
    // Log the error and exit the program
    printf("Error: Failed to allocate memory for hash table\n");
    exit(1);
}

// Function to handle parsing errors by logging them to a specified log file
void handle_parsing_error(hash_table *ht, char *log_file) {
    // Open the log file in append mode
    FILE *fp = fopen(log_file, "a");
    if (fp == NULL) {
        printf("Error: Failed to open log file\n");
        exit(1);
    }

    // Log the parsing error and close the log file
    fprintf(fp, "Parsing error: %s\n", strerror(errno));
    fclose(fp);
}

// Function to handle unexpected interruptions by managing resources promptly
void handle_interruption(hash_table *ht) {
    // Release all resources allocated by the hash table
    for (int i = 0; i < ht->capacity; i++) {
        node *curr = ht->table[i];
        while (curr != NULL) {
            node *next = curr->next;
            free(curr);
            curr = next;
        }
    }
    free(ht->table);
}

// Function to handle memory allocation failures gracefully in a multithreaded environment
void handle_memory_allocation_failure_mt(hash_table *ht) {
    // Log the error and exit the program
    printf("Error: Failed to allocate memory for hash table\n");
    exit(1);
}

// Function to handle parsing errors by logging them to a specified log file in a multithreaded environment
