// Define the function to dynamically manage the dataset of data points
void manage_dataset(data_point *data, int num_data) {
    // Initialize the linked list and hash table
    node *head = NULL;
    hash_table *htable = (hash_table *)malloc(sizeof(hash_table));
    htable->size = 1024;
    htable->buckets = (node **)malloc(htable->size * sizeof(node *));
    for (int i = 0; i < htable->size; i++) {
        htable->buckets[i] = NULL;
    }

    // Insert the data points into the linked list and hash table
    for (int i = 0; i < num_data; i++) {
