        node *bucket = htable->buckets[bucket_index];
        while (bucket != NULL && strcmp(bucket->data->label, data[i].label) != 0) {
            bucket = bucket->next;
        }
        if (bucket == NULL) {
            bucket = (node *)malloc(sizeof(node));
            bucket->data = data + i;
            bucket->next = htable->buckets[bucket_index];
            htable->buckets[bucket_index] = bucket;
        }
    }

    // Delete the data points from the linked list and hash table
    for (int i = 0; i < num_data; i++) {
