        }
        if (bucket == NULL) continue;
        if (bucket == head) {
            head = head->next;
        } else {
            prev->next = curr->next;
        }
    }

    // Prune the linked list and hash table periodically to remove outdated entries
    time_t current_time = time(NULL);
    node *curr = head;
    while (curr != NULL) {
        if (curr->data->timestamp < current_time - 3600) { // Prune data points older than one hour
