        int index = hash(node->data.identifier, hash_table->size);
        Node **bucket = &hash_table->table[index];
        while (*bucket != NULL && strcmp((*bucket)->data.identifier, node->data.identifier) != 0) {
            bucket = &(*bucket)->next;
        }
        if (*bucket == NULL) {
            *bucket = malloc(sizeof(Node));
            (*bucket)->data = node->data;
            (*bucket)->next = NULL;
        } else {
            // Update timestamp and counters for existing data point
            (*bucket)->data.timestamp = time(NULL);
            (*bucket)->data.counter1 += node->data.counter1;
            (*bucket)->data.counter2 += node->data.counter2;
            (*bucket)->data.counter3 += node->data.counter3;
        }
    }
    pthread_mutex_unlock(&hash_table->mutex);

    // Insert sensor readings into cache
    for (Node *node = head; node != NULL; node = node->next) {
        if (cache->size < cache->capacity) {
            cache->data[cache->size] = node->data;
            cache->size++;
        } else {
            // Evict oldest data point from cache
            int evicted_index = 0;
            for (int i = 1; i < cache->size; i++) {
                if (cache->data[i].timestamp < cache->data[evicted_index].timestamp) {
                    evicted_index = i;
                }
            }
            cache->data[evicted_index] = node->data;
        }
    }

    // Periodically prune stale entries from hash table and cache
    pthread_mutex_lock(&hash_table->mutex);
    for (int i = 0; i < hash_table->size; i++) {
        Node *node = hash_table->table[i];
        while (node != NULL) {
            if (time(NULL) - node->data.timestamp > 3600) {
                // Remove stale entry from hash table
                Node **bucket = &hash_table->table[i];
                while (*bucket != NULL && (*bucket)->next != node) {
                    bucket = &(*bucket)->next;
                }
                if (*bucket != NULL) {
                    *bucket = (*bucket)->next;
                }
            } else {
                // Move to next entry in hash table
                node = node->next;
            }
        }
    }
    pthread_mutex_unlock(&hash_table->mutex);

    for (int i = 0; i < cache->size; i++) {
        if (time(NULL) - cache->data[i].timestamp > 3600) {
            // Evict stale entry from cache
            cache->data[i] = cache->data[cache->size - 1];
            cache->size--;
        } else {
            // Move to next entry in cache
            i++;
        }
    }
}

// Define hash function for concurrent hash table
int hash(char *key, int size) {
    unsigned long hash = 5381;
    char c;
    while ((c = *key++) != '\0') {
        hash = ((hash << 5) + hash) + c;
    }
    return hash % size;
}

// Define caching mechanism for frequently accessed data points
void cache_data(SensorReading *data, int capacity) {
    // Add data point to cache if not already present
    if (cache->size < cache->capacity) {
        cache->data[cache->size] = *data;
        cache->size++;
    } else {
        // Evict oldest data point from cache
        int evicted_index = 0;
        for (int i = 1; i < cache->size; i++) {
            if (cache->data[i].timestamp < cache->data[evicted_index].timestamp) {
                evicted_index = i;
            }
        }
        cache->data[evicted_index] = *data;
    }
}

// Define periodic data pruning for stale entries in hash table and cache
void prune_stale_entries() {
    pthread_mutex_lock(&hash_table->mutex);
    for (int i = 0; i < hash_table->size; i++) {
        Node *node = hash_table->table[i];
        while (node != NULL) {
            if (time(NULL) - node->data.timestamp > 3600) {
                // Remove stale entry from hash table
                Node **bucket = &hash_table->table[i];
                while (*bucket != NULL && (*bucket)->next != node) {
                    bucket = &(*bucket)->next;
                }
                if (*bucket != NULL) {
                    *bucket = (*bucket)->next;
                }
            } else {
                // Move to next entry in hash table
                node = node->next;
            }
        }
    }
    pthread_mutex_unlock(&hash_table->mutex);

    for (int i = 0; i < cache->size; i++) {
        if (time(NULL) - cache->data[i].timestamp > 3600) {
            // Evict stale entry from cache
            cache->data[i] = cache->data[cache->size - 1];
            cache->size--;
        } else {
            // Move to next entry in cache
            i++;
        }
    }
}
