                exit(1);
            }
            strcpy((*data)[i].data, "");
        }
    }
}

// Define a function to free the memory allocated for an array of Data structures
void free_data(Data **data) {
    // Free each element in the array and then the array itself
    for (size_t i = 0; i < count; i++) {
