// Function to manage the dynamic identifier system
void manageIdentifiers(PrecisionValue *values, int numValues) {
    // Initialize a custom balanced binary search tree (BST) for quick lookups
    struct BSTNode *root = NULL;

    // Iterate through each precision value and timestamp in the given array
    for (int i = 0; i < numValues; i++) {
        PrecisionValue currentValue = values[i];

        // Check if the current precision value is already present in the BST
        struct BSTNode *currentNode = root;
        while (currentNode != NULL) {
            if (currentValue.precision == currentNode->value.precision) {
                break;
            } else if (currentValue.precision < currentNode->value.precision) {
                currentNode = currentNode->left;
            } else {
                currentNode = currentNode->right;
            }
        }

        // If the precision value is not present in the BST, insert it
        if (currentNode == NULL) {
            struct BSTNode *newNode = malloc(sizeof(struct BSTNode));
            newNode->value = currentValue;
            newNode->left = NULL;
            newNode->right = NULL;
            if (root == NULL) {
                root = newNode;
            } else {
                struct BSTNode *parentNode = findParent(root, newNode);
                if (newNode->value.precision < parentNode->value.precision) {
                    parentNode->left = newNode;
                } else {
                    parentNode->right = newNode;
                }
            }
        }
    }

    // Periodically check and release unused memory blocks to optimize resource usage
    struct BSTNode *currentNode = root;
    while (currentNode != NULL) {
        if (currentNode->left == NULL && currentNode->right == NULL) {
            free(currentNode);
            currentNode = root;
        } else {
            currentNode = currentNode->left ? currentNode->left : currentNode->right;
        }
    }
}

// Function to insert a new precision value and timestamp into the BST
void insertValue(struct BSTNode *root, PrecisionValue newValue) {
    // If the root node is NULL, create a new node with the given value
    if (root == NULL) {
        struct BSTNode *newNode = malloc(sizeof(struct BSTNode));
        newNode->value = newValue;
        newNode->left = NULL;
        newNode->right = NULL;
        root = newNode;
    } else {
        // If the value is already present in the BST, return
        if (newValue.precision == root->value.precision) {
            return;
        }

        // Recursively insert the value into the left or right subtree
        if (newValue.precision < root->value.precision) {
            insertValue(root->left, newValue);
        } else {
            insertValue(root->right, newValue);
        }
    }
}

// Function to delete a precision value and timestamp from the BST
void deleteValue(struct BSTNode *root, PrecisionValue value) {
    // If the root node is NULL or the value is not present in the BST, return
    if (root == NULL || value.precision != root->value.precision) {
        return;
    }

    // If the value is present in the left subtree, delete it from there
    if (value.precision < root->value.precision) {
        deleteValue(root->left, value);
    } else {
        // If the value is present in the right subtree, delete it from there
        if (value.precision > root->value.precision) {
            deleteValue(root->right, value);
        } else {
            // If the value is present in the current node, remove it and return
            struct BSTNode *parentNode = findParent(root, root);
            if (parentNode == NULL) {
                free(root);
                root = NULL;
            } else {
                if (root->value.precision < parentNode->value.precision) {
                    parentNode->left = NULL;
                } else {
                    parentNode->right = NULL;
                }
                free(root);
                root = parentNode;
            }
        }
    }
}

// Function to find the parent node of a given node in the BST
struct BSTNode *findParent(struct BSTNode *root, struct BSTNode *node) {
    // If the root node is NULL or the node is not present in the BST, return NULL
    if (root == NULL || node == NULL) {
        return NULL;
    }

    // Recursively search for the parent node
    struct BSTNode *currentNode = root;
    while (currentNode != NULL) {
        if (node->value.precision < currentNode->value.precision) {
            currentNode = currentNode->left;
        } else if (node->value.precision > currentNode->value.precision) {
            currentNode = currentNode->right;
        } else {
            return currentNode;
        }
    }

    // If the node is not present in the BST, return NULL
    return NULL;
}

// Function to traverse the BST and print all precision values and timestamps
void traverseBST(struct BSTNode *root) {
