    node->record = record;
    node->next = table->nodes[index];
    table->nodes[index] = node;
}

// Define the function to delete a record from the hash table
void deleteHashTable(HashTable *table, Record *record) {
    int index = record->key % table->capacity;
    Node *node = table->nodes[index];
    while (node != NULL && node->record != record) {
        node = node->next;
    }
    if (node == NULL) {
        printf("Record not found\n");
        exit(1);
    }
    table->nodes[index] = node->next;
    free(node);
}

// Define the function to search for a record in the hash table
void searchHashTable(HashTable *table, Record *record) {
    int index = record->key % table->capacity;
    Node *node = table->nodes[index];
    while (node != NULL && node->record != record) {
        node = node->next;
    }
    if (node == NULL) {
        printf("Record not found\n");
        exit(1);
    }
}

// Define the function to insert a record into the memory pool
void insertMemoryPool(MemoryPool *pool, void *block) {
    int index = block % pool->capacity;
    if (pool->blocks[index] == NULL) {
        pool->blocks[index] = block;
        pool->size++;
    } else {
        printf("Memory allocation failed\n");
        exit(1);
    }
}

// Define the function to delete a record from the memory pool
void deleteMemoryPool(MemoryPool *pool, void *block) {
    int index = block % pool->capacity;
    if (pool->blocks[index] == block) {
        pool->blocks[index] = NULL;
        pool->size--;
    } else {
        printf("Record not found\n");
        exit(1);
    }
}

// Define the function to search for a record in the memory pool
void searchMemoryPool(MemoryPool *pool, void *block) {
    int index = block % pool->capacity;
    if (pool->blocks[index] == block) {
        return;
    } else {
        printf("Record not found\n");
        exit(1);
    }
}

// Define the function to periodically check and release unused memory blocks
void garbageCollection(MemoryPool *pool) {
    for (int i = 0; i < pool->capacity; i++) {
        if (pool->blocks[i] == NULL) {
            continue;
        } else {
            free(pool->blocks[i]);
            pool->blocks[i] = NULL;
            pool->size--;
        }
    }
}

// Define the function to integrate with an external logging framework for tracking memory usage and performance metrics
void logMemoryUsage(MemoryPool *pool) {
    printf("Total number of allocations: %d\n", pool->capacity);
    printf("Total number of deallocations: %d\n", pool->size);
    printf("Number of memory blocks currently in use: %d\n", pool->size);
}

// Define the function to adhere to strict memory usage limits and release memory back to the operating system if a predefined threshold is exceeded
void checkMemoryUsage(MemoryPool *pool) {
    if (pool->size > pool->capacity / 2) {
        garbageCollection(pool);
    }
}

