NFAPI_L1_ENB_API_MSG* initialize_dynamic_array(int N) {
    // Allocate memory for the array of structures
    NFAPI_L1_ENB_API_MSG *arr = (NFAPI_L1_ENB_API_MSG*)malloc(sizeof(NFAPI_L1_ENB_API_MSG) * N);

    // Initialize each structure in the array
