}

// Function to dynamically adjust the number of worker threads based on real-time load and system resource availability, minimizing thread creation overhead and ensuring graceful degradation during peak loads
int scalable_network_interface_adjust_workers(SCALABLE_NETWORK_INTERFACE_CONFIG_T* config) {
    // Check if the input parameters are valid
    if (config == NULL) {
        return -1;
    }

    // Acquire the lock for protecting the configuration structure
    pthread_mutex_lock(&config->lock);

    // Calculate the current load and resource availability
    double load = 0.0;
    size_t num_workers = config->num_workers;
    for (size_t i = 0; i < num_workers; ++i) {
        load += pthread_mutex_lock(&config->workers[i].lock);
    }

    // Adjust the number of worker threads based on the current load and resource availability
    if (load > 1.0) {
        num_workers = (size_t)(num_workers * 0.5);
    } else if (load < 0.5) {
