    struct Deque* deque;
    struct BloomFilter* bloomFilter;
    pthread_mutex_t mutex;
    pthread_cond_t condVar;
};

// Initialize a new log buffer with the given capacity
struct LogBuffer* initLogBuffer(int capacity) {
    struct LogBuffer* buffer = malloc(sizeof(struct LogBuffer));
    buffer->deque = createDeque(capacity);
    buffer->bloomFilter = createBloomFilter(capacity);
    pthread_mutex_init(&buffer->mutex, NULL);
    pthread_cond_init(&buffer->condVar, NULL);
    return buffer;
}

// Append a new log entry to the buffer
void appendLogEntry(struct LogBuffer* buffer, struct LogEntry* entry) {
    pthread_mutex_lock(&buffer->mutex);
    while (buffer->deque->size == buffer->deque->capacity) {
        // Wait for space to become available in the deque
        pthread_cond_wait(&buffer->condVar, &buffer->mutex);
    }
    // Add the log entry to the deque and bloom filter
    addToDeque(buffer->deque, entry);
    addToBloomFilter(buffer->bloomFilter, entry);
    pthread_mutex_unlock(&buffer->mutex);
}

// Prepend a new log entry to the buffer
void prependLogEntry(struct LogBuffer* buffer, struct LogEntry* entry) {
    pthread_mutex_lock(&buffer->mutex);
    while (buffer->deque->size == buffer->deque->capacity) {
