    addToDeque(buffer->deque, entry);
    addToBloomFilter(buffer->bloomFilter, entry);
    pthread_mutex_unlock(&buffer->mutex);
}

// Remove a log entry from the buffer by its index
void removeLogEntry(struct LogBuffer* buffer, int index) {
    pthread_mutex_lock(&buffer->mutex);
    // Remove the log entry from the deque and bloom filter
    removeFromDeque(buffer->deque, index);
    removeFromBloomFilter(buffer->bloomFilter, index);
    pthread_cond_broadcast(&buffer->condVar);
    pthread_mutex_unlock(&buffer->mutex);
}

// Retrieve a log entry from the buffer by its index
