    deque->capacity = capacity;
    deque->elements = malloc(sizeof(void*) * capacity);
    return deque;
}

// Add a new element to the end of the deque
void addToDeque(struct Deque* deque, void* element) {
    // Check if the deque is full
    if (deque->size == deque->capacity) {
        // Double the capacity of the deque
        int newCapacity = deque->capacity * 2;
        void** newElements = malloc(sizeof(void*) * newCapacity);
        memcpy(newElements, deque->elements, sizeof(void*) * deque->size);
        free(deque->elements);
        deque->elements = newElements;
        deque->capacity = newCapacity;
    }
    // Add the element to the end of the deque
    deque->elements[deque->size++] = element;
}

// Remove an element from the end of the deque
void removeFromDeque(struct Deque* deque, int index) {
    // Check if the index is valid
    if (index < 0 || index >= deque->size) {
        return;
    }
    // Shift all elements after the specified index to the left
    for (int i = index + 1; i < deque->size; i++) {
        deque->elements[i - 1] = deque->elements[i];
    }
    // Decrement the size of the deque
    deque->size--;
}

// Get an element from the deque by its index
void* getFromDeque(struct Deque* deque, int index) {
    if (index < 0 || index >= deque->size) {
        return NULL;
    }
    return deque->elements[index];
}

// Free the memory allocated for the deque
void freeDeque(struct Deque* deque) {
    free(deque->elements);
    free(deque);
}

// Create a new bloom filter with the given capacity
struct BloomFilter* createBloomFilter(int capacity) {
    struct BloomFilter* bloomFilter = malloc(sizeof(struct BloomFilter));
    bloomFilter->size = 0;
    bloomFilter->capacity = capacity;
    bloomFilter->elements = malloc(sizeof(bool) * capacity);
    return bloomFilter;
}

// Add a new element to the bloom filter
void addToBloomFilter(struct BloomFilter* bloomFilter, void* element) {
    // Check if the bloom filter is full
    if (bloomFilter->size == bloomFilter->capacity) {
        // Double the capacity of the bloom filter
        int newCapacity = bloomFilter->capacity * 2;
        bool* newElements = malloc(sizeof(bool) * newCapacity);
        memcpy(newElements, bloomFilter->elements, sizeof(bool) * bloomFilter->size);
        free(bloomFilter->elements);
        bloomFilter->elements = newElements;
        bloomFilter->capacity = newCapacity;
    }
    // Add the element to the bloom filter
    bloomFilter->elements[bloomFilter->size++] = true;
}

// Remove an element from the bloom filter
void removeFromBloomFilter(struct BloomFilter* bloomFilter, int index) {
    // Check if the index is valid
    if (index < 0 || index >= bloomFilter->size) {
        return;
    }
    // Shift all elements after the specified index to the left
    for (int i = index + 1; i < bloomFilter->size; i++) {
        bloomFilter->elements[i - 1] = bloomFilter->elements[i];
    }
    // Decrement the size of the bloom filter
    bloomFilter->size--;
}

// Check if an element exists in the bloom filter
bool checkBloomFilter(struct BloomFilter* bloomFilter, void* element) {
    for (int i = 0; i < bloomFilter->size; i++) {
        if (bloomFilter->elements[i] == true) {
            return true;
        }
    }
    return false;
}

// Free the memory allocated for the bloom filter
void freeBloomFilter(struct BloomFilter* bloomFilter) {
    free(bloomFilter->elements);
    free(bloomFilter);
}

// Add an element to an array of elements
void addToArray(void*** array, void* element) {
    int size = 0;
    if (*array != NULL) {
        size = *array;
    }
    // Allocate memory for the new element
    void** newArray = malloc(sizeof(void*) * (size + 1));
    // Copy the existing elements to the new array
    memcpy(newArray, *array, sizeof(void*) * size);
    // Add the new element to the end of the array
    newArray[size] = element;
    // Free the old array and assign the new one
    free(*array);
    *array = newArray;
}
