    int key;
    long offset;
} record_t;

typedef struct {
    int category;
    int setting;
} config_t;

typedef struct {
    record_t *records;
    config_t **configs;
} config_struct_t;

// Function to initialize the complex data structure
config_struct_t* init_complex_data_structure() {
    // Allocate memory for the array of records and configs
    record_t *records = malloc(sizeof(record_t) * NUM_RECORDS);
    config_t **configs = malloc(sizeof(config_t *) * NUM_CONFIGURATIONS);
    if (records == NULL || configs == NULL) {
        // Handle memory allocation failure
        return NULL;
    }

    // Initialize the records and configs
    for (int i = 0; i < NUM_RECORDS; i++) {
        records[i].key = i + 1;
        records[i].offset = i * RECORD_SIZE;
    }
    for (int j = 0; j < NUM_CONFIGURATIONS; j++) {
        configs[j] = malloc(sizeof(config_t));
        if (configs[j] == NULL) {
            // Handle memory allocation failure
            return NULL;
        }
        configs[j]->category = j + 1;
        configs[j]->setting = RANDOM_SETTINGS[j];
    }

    // Create a hash table to check for duplicate keys during initialization
    pthread_mutex_t *key_locks = malloc(sizeof(pthread_mutex_t) * NUM_RECORDS);
    if (key_locks == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    for (int i = 0; i < NUM_RECORDS; i++) {
        pthread_mutex_init(&key_locks[i], NULL);
    }

    // Initialize the hash table with unique keys
    int *keys = malloc(sizeof(int) * NUM_RECORDS);
    if (keys == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    for (int i = 0; i < NUM_RECORDS; i++) {
        keys[i] = i + 1;
    }
    for (int i = 0; i < NUM_RECORDS; i++) {
        pthread_mutex_lock(&key_locks[i]);
        int *duplicate_key = bsearch(&keys[i], keys, NUM_RECORDS - i, sizeof(int), compare_keys);
        if (duplicate_key != NULL) {
            // Handle duplicate key error
            return NULL;
        }
        pthread_mutex_unlock(&key_locks[i]);
    }

    // Free the hash table and keys
    free(key_locks);
    free(keys);

    // Return a pointer to the first element of the records array
    return &records[0];
}

// Function to compare two integers for sorting
int compare_keys(const void *a, const void *b) {
    int key1 = *(int *)a;
    int key2 = *(int *)b;
    if (key1 < key2) {
        return -1;
    } else if (key1 > key2) {
        return 1;
    } else {
        return 0;
    }
}
