// Function to initialize a new record with default values
Record *init_record(int integer, char *string) {
    Record *new_record = malloc(sizeof(Record));
    if (new_record == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for new record\n");
        return NULL;
    }
    new_record->integer = integer;
    new_record->string = string;
    new_record->value = 0.0f;
    return new_record;
}

// Function to add a new record to the linked list
void add_record(Record **head, Record *new_record) {
    if (*head == NULL) {
        *head = new_record;
    } else {
        new_record->next = *head;
        *head = new_record;
    }
}

// Function to delete a record from the linked list
void delete_record(Record **head, Record *record) {
    if (*head == NULL || record == NULL) return;
    if (*head == record) {
        *head = (*head)->next;
    } else {
        Record *current = *head;
        while (current->next != record) current = current->next;
        current->next = record->next;
    }
}

// Function to traverse the linked list and print all records
void traverse_records(Record *head) {
    if (head == NULL) return;
    printf("Records:\n");
    while (head != NULL) {
        printf("%d, %s, %.2f\n", head->integer, head->string, head->value);
        head = head->next;
    }
}

// Function to search for a record by its string identifier
Record *search_record(HashTable *hash_table, char *identifier) {
    if (hash_table == NULL || identifier == NULL) return NULL;
    size_t index = hash_table->capacity - 1;
    while (index >= 0 && strcmp(hash_table->records[index]->string, identifier) != 0) index--;
    if (index < 0) return NULL;
    return hash_table->records[index];
}

