    size_t index = hash_table->capacity - 1;
    while (index >= 0 && strcmp(hash_table->records[index]->string, new_record->string) != 0) index--;
    if (index < 0) {
        // If the record is not found in the hash table, add it to the linked list and hash table
        add_record(&hash_table->records[index], new_record);
    } else {
        // If the record is already in the hash table, update its value
        hash_table->records[index]->value = new_record->value;
    }
}

// Function to delete a record from the linked list and hash table
void delete_record_from_hash_table(HashTable *hash_table, Record *record) {
    if (hash_table == NULL || record == NULL) return;
    size_t index = hash_table->capacity - 1;
    while (index >= 0 && strcmp(hash_table->records[index]->string, record->string) != 0) index--;
    if (index < 0) return;
    delete_record(&hash_table->records[index], record);
}

// Function to update the value of a record in the linked list and hash table
void update_record(HashTable *hash_table, Record *record) {
    if (hash_table == NULL || record == NULL) return;
    size_t index = hash_table->capacity - 1;
    while (index >= 0 && strcmp(hash_table->records[index]->string, record->string) != 0) index--;
    if (index < 0) return;
    hash_table->records[index]->value = record->value;
}

// Function to prune records that no longer meet specific business criteria
void prune_records(HashTable *hash_table, bool (*condition)(Record *)) {
