#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

// Define the struct for records
typedef struct record {
    int integer;
    char *string;
    float value;
} Record;

// Define the linked list node structure
typedef struct node {
    Record data;
    struct node *next;
} Node;

// Define the hash table for quick lookups based on string keys
typedef struct hash_table {
    int size;
    Node **buckets;
} HashTable;

// Function to initialize the linked list and hash table
void init(HashTable *ht, int seed) {
    // Initialize the linked list head pointer
    ht->head = NULL;

    // Initialize the hash table with a default size of 1024 buckets
    ht->size = 1024;
    ht->buckets = (Node **)malloc(ht->size * sizeof(Node *));
    assert(ht->buckets != NULL);

    // Initialize the hash table with a default seed value
    for (int i = 0; i < ht->size; i++) {
        ht->buckets[i] = NULL;
    }
}

// Function to insert a new record into the linked list and hash table
void insert(HashTable *ht, int integer, char *string, float value) {
    // Create a new node for the record
    Node *node = (Node *)malloc(sizeof(Node));
    assert(node != NULL);

    // Initialize the node data
    node->data.integer = integer;
    node->data.string = string;
    node->data.value = value;

    // Insert the node into the linked list
    if (ht->head == NULL) {
        ht->head = node;
    } else {
        Node *current = ht->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }

    // Insert the node into the hash table
    int index = hash(string);
    node->next = ht->buckets[index];
    ht->buckets[index] = node;
}

// Function to delete a record from the linked list and hash table
void delete(HashTable *ht, char *string) {
    // Find the node in the linked list with the given string key
    Node *current = ht->head;
    while (current != NULL && strcmp(current->data.string, string) != 0) {
        current = current->next;
    }

    // If the node is found, delete it from the linked list and hash table
    if (current != NULL) {
        Node *previous = current->prev;
        if (previous == NULL) {
            ht->head = current->next;
        } else {
            previous->next = current->next;
        }
        free(current);
    }
}

// Function to retrieve a record from the linked list and hash table by its string key
Record *get(HashTable *ht, char *string) {
    // Find the node in the linked list with the given string key
    Node *current = ht->head;
    while (current != NULL && strcmp(current->data.string, string) != 0) {
        current = current->next;
    }

    // If the node is found, return its data
    if (current != NULL) {
        return &current->data;
    } else {
        return NULL;
    }
}

// Function to update a record in the linked list and hash table by its string key
void update(HashTable *ht, char *string, int integer, float value) {
    // Find the node in the linked list with the given string key
    Node *current = ht->head;
    while (current != NULL && strcmp(current->data.string, string) != 0) {
        current = current->next;
    }

    // If the node is found, update its data
    if (current != NULL) {
        current->data.integer = integer;
        current->data.value = value;
    }
}

// Function to traverse the linked list and print all records
void traverse(HashTable *ht) {
    // Print the header for the table
    printf("| Integer | String | Value |\n");
    printf("| --- | --- | --- |\n");

    // Traverse the linked list and print each record
    Node *current = ht->head;
    while (current != NULL) {
        printf("| %d | %s | %f |\n", current->data.integer, current->data.string, current->data.value);
        current = current->next;
    }
}

// Function to release all memory allocated by the linked list and hash table
void destroy(HashTable *ht) {
    // Release the memory for the linked list nodes
    Node *current = ht->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current);
        current = next;
    }

    // Release the memory for the hash table buckets
    free(ht->buckets);
}

// Function to handle memory allocation failures gracefully
void handle_error() {
    printf("Memory allocation failed. Exiting...\n");
    exit(1);
}

// Function to calculate the hash value for a given string key
int hash(char *string) {
    int hash = 0;
    for (int i = 0; i < strlen(string); i++) {
        hash += string[i];
    }
    return hash % ht->size;
}
```
