import requests
from datetime import datetime
from typing import List, Dict

class Employee:
    def __init__(self, id: int, name: str, city: str, address: str, department: str, job_title: str, budget: float):
        self.id = id
        self.name = name
        self.city = city
        self.address = address
        self.department = department
        self.job_title = job_title
        self.budget = budget

class Manager:
    def __init__(self, id: int, name: str):
        self.id = id
        self.name = name

class HRClient:
    def __init__(self, api_url: str):
        self.api_url = api_url

    def get_employees(self, manager_id: int) -> List[Employee]:
        response = requests.get(f"{self.api_url}/employees?manager_id={manager_id}")
        employees = []
        for employee in response.json():
            employees.append(Employee(employee["id"], employee["name"], employee["city"], employee["address"], employee["department"], employee["job_title"], employee["budget"]))
        return employees

    def get_manager(self, manager_id: int) -> Manager:
        response = requests.get(f"{self.api_url}/managers/{manager_id}")
        return Manager(response.json()["id"], response.json()["name"])

class EmployeeService:
    def __init__(self, hr_client: HRClient):
        self.hr_client = hr_client

    def get_employees(self, manager_id: int) -> List[Employee]:
        employees = []
        for employee in self.hr_client.get_employees(manager_id):
            employees.append(employee)
        return employees

    def get_manager(self, manager_id: int) -> Manager:
        return self.hr_client.get_manager(manager_id)

class EmployeeCache:
    def __init__(self):
        self.cache = {}

    def get_employees(self, manager_id: int) -> List[Employee]:
        if manager_id in self.cache:
            return self.cache[manager_id]
        else:
            employees = []
            for employee in EmployeeService(HRClient("https://api.example.com")).get_employees(manager_id):
                employees.append(employee)
            self.cache[manager_id] = employees
            return employees

    def get_manager(self, manager_id: int) -> Manager:
        if manager_id in self.cache:
            return self.cache[manager_id]
        else:
            manager = EmployeeService(HRClient("https://api.example.com")).get_manager(manager_id)
            self.cache[manager_id] = manager
            return manager

class Pagination:
    def __init__(self, page_size: int):
        self.page_size = page_size
        self.current_page = 1
        self.total_pages = 0

    def get_employees(self, manager_id: int) -> List[Employee]:
        employees = []
        for employee in EmployeeCache().get_employees(manager_id):
            employees.append(employee)
        return employees[self.current_page * self.page_size - self.page_size:self.current_page * self.page_size]

    def get_total_pages(self, manager_id: int) -> int:
        total_pages = 0
        for employee in EmployeeCache().get_employees(manager_id):
            total_pages += 1
        return total_pages

class EmployeeReport:
    def __init__(self, employees: List[Employee], manager: Manager):
        self.employees = employees
        self.manager = manager

    def generate_report(self) -> str:
        report = f"Manager: {self.manager.name}\n"
        for employee in self.employees:
            report += f"{employee.id}: {employee.name}, {employee.city}, {employee.address}, {employee.department}, {employee.job_title}, {employee.budget}\n"
        return report

def get_report(manager_id: int) -> EmployeeReport:
    employees = Pagination(10).get_employees(manager_id)
    manager = EmployeeCache().get_manager(manager_id)
    return EmployeeReport(employees, manager)
