#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define a struct to represent a task
struct Task {
    int priority;
    struct tm due_date;
    char* description;
};

// Define a linked list node to store tasks
struct Node {
    struct Task task;
    struct Node* next;
};

// Define a hash table to store tasks and their indices
struct HashTable {
    int size;
    struct Node** nodes;
};

// Initialize the hash table with a given size
void init_hash_table(struct HashTable* ht, int size) {
    ht->size = size;
    ht->nodes = (struct Node**)malloc(sizeof(struct Node*) * size);
    for (int i = 0; i < size; i++) {
        ht->nodes[i] = NULL;
    }
}

// Insert a task into the hash table
void insert_task(struct HashTable* ht, struct Task task) {
    int index = task.priority % ht->size;
    if (ht->nodes[index] == NULL) {
        ht->nodes[index] = (struct Node*)malloc(sizeof(struct Node));
        ht->nodes[index]->task = task;
        ht->nodes[index]->next = NULL;
    } else {
        struct Node* current = ht->nodes[index];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = (struct Node*)malloc(sizeof(struct Node));
        current->next->task = task;
        current->next->next = NULL;
    }
}

// Search for a task in the hash table by priority
struct Task* search_task(struct HashTable* ht, int priority) {
    int index = priority % ht->size;
    struct Node* current = ht->nodes[index];
    while (current != NULL && current->task.priority != priority) {
        current = current->next;
    }
    if (current == NULL) {
        return NULL;
    } else {
        return &(current->task);
    }
}

// Remove a task from the hash table by priority
void remove_task(struct HashTable* ht, int priority) {
    int index = priority % ht->size;
    struct Node* current = ht->nodes[index];
    if (current == NULL) {
        return;
    } else if (current->task.priority == priority) {
        ht->nodes[index] = current->next;
        free(current);
    } else {
        while (current->next != NULL && current->next->task.priority != priority) {
            current = current->next;
        }
        if (current->next == NULL) {
            return;
        } else {
            struct Node* temp = current->next;
            current->next = temp->next;
            free(temp);
        }
    }
}

// Free the memory allocated to the hash table
void free_hash_table(struct HashTable* ht) {
    for (int i = 0; i < ht->size; i++) {
        struct Node* current = ht->nodes[i];
        while (current != NULL) {
            struct Node* temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(ht->nodes);
}

// Define a function to export tasks to a CSV file
void export_tasks(struct HashTable* ht, char* filename) {
    FILE* fp = fopen(filename, "w");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }
    for (int i = 0; i < ht->size; i++) {
        struct Node* current = ht->nodes[i];
        while (current != NULL) {
            fprintf(fp, "%d,%d,%s\n", current->task.priority, current->task.due_date.tm_year + 1900, current->task.description);
            current = current->next;
        }
    }
    fclose(fp);
}

// Define a function to import tasks from a CSV file
void import_tasks(struct HashTable* ht, char* filename) {
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }
    while (!feof(fp)) {
        int priority;
        struct tm due_date;
        char description[129];
        fscanf(fp, "%d,%d,%[^,\n]\n", &priority, &due_date.tm_year, description);
        if (strlen(description) > 128) {
            printf("Error: task description exceeds maximum length of 128 characters\n");
            continue;
        }
        struct Task task = {priority, due_date, description};
        insert_task(ht, task);
    }
    fclose(fp);
}

// Define a function to trigger notifications for tasks approaching their due dates
void notify_tasks(struct HashTable* ht) {
    time_t current_time = time(NULL);
    for (int i = 0; i < ht->size; i++) {
        struct Node* current = ht->nodes[i];
        while (current != NULL) {
            if (difftime(current->task.due_date, current_time) <= 24 * 60 * 60) {
                printf("Notification: task %d is due today\n", current->task.priority);
            } else if (difftime(current->task.due_date, current_time) <= 7 * 24 * 60 * 60) {
                printf("Notification: task %d is due this week\n", current->task.priority);
            }
            current = current->next;
        }
    }
}

// Define a function to handle concurrent access from multiple threads
void* thread_handler(void* arg) {
    struct HashTable* ht = (struct HashTable*)arg;
    while (1) {
        int priority;
        scanf("%d", &priority);
        if (priority == 0) {
            break;
        }
        pthread_mutex_lock(&(ht->mutex));
        struct Task* task = search_task(ht, priority);
        if (task != NULL) {
            printf("Task %d found\n", priority);
        } else {
            printf("Task %d not found\n", priority);
        }
        pthread_mutex_unlock(&(ht->mutex));
    }
    return NULL;
}

int main() {
    struct HashTable* ht = (struct HashTable*)malloc(sizeof(struct HashTable));
    init_hash_table(ht, 10000);
    pthread_mutex_init(&(ht->mutex), NULL);
    int n_threads = 5;
    pthread_t* threads = (pthread_t*)malloc(sizeof(pthread_t) * n_threads);
    for (int i = 0; i < n_threads; i++) {
        pthread_create(&(threads[i]), NULL, thread_handler, ht);
    }
    while (1) {
        int priority;
        scanf("%d", &priority);
        if (priority == 0) {
            break;
        }
        pthread_mutex_lock(&(ht->mutex));
        struct Task task = {priority, {0}, ""};
        insert_task(ht, task);
        pthread_mutex_unlock(&(ht->mutex));
    }
    for (int i = 0; i < n_threads; i++) {
        pthread_join(threads[i], NULL);
    }
    free_hash_table(ht);
    return 0;
}
