    node->task = task;
    node->next = NULL;
    pthread_mutex_lock(&taskList->mutex);
    if (taskList->size == 0) {
        taskList->head = node;
        taskList->tail = node;
    } else {
        taskList->tail->next = node;
        taskList->tail = node;
    }
    taskList->size++;
    pthread_mutex_unlock(&taskList->mutex);
}

