// Define the structure to store sensor records
typedef struct {
    char device_id[10]; // Device ID string of up to 10 characters
    int location; // Location tag (integer)
    bool active; // Active flag (boolean)
    time_t last_activity; // Last activity timestamp (time_t)
} sensor_record;

// Define the data structures for temperature, humidity, and status data
typedef struct {
    float temperature; // Temperature value (float)
    float humidity; // Humidity value (float)
    bool status; // Status flag (boolean)
} sensor_data;

// Define the function to manage the dynamic sensor network system
void manage_sensor_network(int num_sensors, int* device_ids, int* locations, bool* active_flags, time_t* last_activity_timestamps, float* temperatures, float* humidities, bool* statuses) {
    // Allocate memory for the sensor records
    sensor_record* sensor_records = (sensor_record*)malloc(num_sensors * sizeof(sensor_record));

    // Initialize the sensor records with the given data
    for (int i = 0; i < num_sensors; i++) {
        strcpy(sensor_records[i].device_id, device_ids[i]);
        sensor_records[i].location = locations[i];
        sensor_records[i].active = active_flags[i];
        sensor_records[i].last_activity = last_activity_timestamps[i];
    }

    // Allocate memory for the temperature, humidity, and status data structures
    sensor_data* temperature_data = (sensor_data*)malloc(num_sensors * sizeof(sensor_data));
    sensor_data* humidity_data = (sensor_data*)malloc(num_sensors * sizeof(sensor_data));
    bool* status_data = (bool*)malloc(num_sensors * sizeof(bool));

    // Initialize the temperature, humidity, and status data structures with the given data
    for (int i = 0; i < num_sensors; i++) {
        temperature_data[i].temperature = temperatures[i];
        humidity_data[i].humidity = humidities[i];
        status_data[i] = statuses[i];
    }

    // Define the timestamp-based random seed for simulating sensor data
    srand(time(NULL));

    // Periodically check the status of sensors offline for longer than a defined threshold, marking them as inactive
    int inactive_threshold = 30; // Define the inactive threshold (in seconds)
    for (int i = 0; i < num_sensors; i++) {
        if (sensor_records[i].last_activity + inactive_threshold <= time(NULL)) {
            sensor_records[i].active = false;
        }
    }

    // Logging system to track sensor record creations and updates
    FILE* log_file = fopen("sensor_log.txt", "a");
    for (int i = 0; i < num_sensors; i++) {
        if (sensor_records[i].active) {
            // Log the creation of a new sensor record
            fprintf(log_file, "%d: Created sensor record with device ID %s and location tag %d\n", i, sensor_records[i].device_id, sensor_records[i].location);
        } else {
            // Log the update of an existing sensor record
            fprintf(log_file, "%d: Updated sensor record with device ID %s and location tag %d\n", i, sensor_records[i].device_id, sensor_records[i].location);
        }
    }
    fclose(log_file);
}

// Function to validate and maintain unique device IDs, updating active flags for duplicates instead of overwriting
void validate_unique_device_ids(int num_sensors, char** device_ids) {
    // Create a hash table to store the unique device IDs
    int* unique_device_ids = (int*)malloc(num_sensors * sizeof(int));
    for (int i = 0; i < num_sensors; i++) {
        unique_device_ids[i] = -1;
    }

    // Iterate through the device IDs and update the hash table accordingly
    for (int i = 0; i < num_sensors; i++) {
        bool duplicate = false;
        for (int j = 0; j < i; j++) {
            if (strcmp(device_ids[i], device_ids[j]) == 0) {
                duplicate = true;
                break;
            }
        }
        if (!duplicate) {
            unique_device_ids[i] = i;
        } else {
            for (int j = 0; j < num_sensors; j++) {
                if (strcmp(device_ids[j], device_ids[i]) == 0) {
                    unique_device_ids[i] = j;
                    break;
                }
            }
        }
    }

    // Update the active flags for duplicate device IDs
    for (int i = 0; i < num_sensors; i++) {
        if (unique_device_ids[i] != -1) {
            sensor_records[i].active = true;
        } else {
            sensor_records[i].active = false;
        }
    }
}

// Function to simulate sensor data using a timestamp-based random seed
void simulate_sensor_data(int num_sensors, float* temperatures, float* humidities, bool* statuses) {
    // Define the range of values for simulating temperature and humidity data
    int temp_range = 10;
    int hum_range = 50;

    // Iterate through the sensors and simulate their data
    for (int i = 0; i < num_sensors; i++) {
        temperatures[i] = rand() % temp_range - temp_range / 2;
        humidities[i] = rand() % hum_range - hum_range / 2;
        statuses[i] = true;
    }
}
