        scanf("%s", file_path);
        int line_count = 0;
        while (line_count < max_capacity && fscanf(stdin, "%d", &line_count) == 1) {
            if (i >= num_file_paths) {
                break;
            }
            file_records[i].file_path = file_path;
            file_records[i].line_count = line_count;
            i++;
        }
    }

    // Provide thread-safe operations for the file record array to support concurrent read and write access by multiple threads
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Implement a memory optimization strategy to periodically compress the file record array, reclaiming unused space and improving overall performance and memory efficiency
    int num_compressions = 0;
    while (i < num_file_paths) {
        pthread_mutex_lock(&mutex);
        while (cond != PTHREAD_COND_SIGNALED) {
            pthread_cond_wait(&cond, &mutex);
        }
        cond = PTHREAD_COND_INITIALIZER;
        int j = 0;
        for (int k = 0; k < i; k++) {
            if (file_records[k].line_count == 0) {
                continue;
            }
            file_records[j] = file_records[k];
            j++;
        }
        num_compressions++;
        i = j;
        pthread_mutex_unlock(&mutex);
    }

    // Minimize memory overhead and ensure efficient data retrieval, especially under high-load conditions where the number of files and timestamps can be very large
    int num_threads = 4;
    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, thread_func, &file_records);
    }
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    // Return a structure containing pointers to the allocated arrays and their respective sizes, along with metadata about current usage and available space in the file record array
    struct memory_info {
        long* timestamps;
        int num_timestamps;
        char** file_paths;
        int num_file_paths;
        file_record* file_records;
        int num_file_records;
        int num_compressions;
    };
    struct memory_info info = {
        timestamps,
        num_timestamps,
        file_paths,
        num_file_paths,
        file_records,
        i,
        num_compressions
    };
    return info;
}

// Define the thread function to handle concurrent access to the file record array
void* thread_func(void* arg) {
    // Cast the argument to a pointer to an array of file records
    file_record** file_records = (file_record**)arg;

    // Loop until all threads have finished
