        new_hash_node->id = task->id;
        new_hash_node->task = *task;
        new_hash_node->next = hash_table[hash_key];
        hash_table[hash_key] = new_hash_node;
    }

    // Schedule notifications for tasks approaching their due dates
    scheduleNotifications(head);

