// Define the structure for the records
typedef struct {
    int value;
} record_t;

// Define the function to dynamically allocate memory for the arrays
void allocate_memory(int num_records, long** offset_array, int** key_array, record_t*** record_array) {
    // Allocate memory for the offset array
    *offset_array = (long*)malloc(num_records * sizeof(long));
    if (*offset_array == NULL) {
        printf("Error: Failed to allocate memory for the offset array\n");
        return;
    }

    // Allocate memory for the key array
    *key_array = (int*)malloc(num_records * sizeof(int));
    if (*key_array == NULL) {
        printf("Error: Failed to allocate memory for the key array\n");
        free(*offset_array);
        return;
    }

    // Allocate memory for the record array
    *record_array = (record_t**)malloc(num_records * sizeof(record_t*));
    if (*record_array == NULL) {
        printf("Error: Failed to allocate memory for the record array\n");
        free(*offset_array);
        free(*key_array);
        return;
    }

    // Initialize the records with random integers within a specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        (*offset_array)[i] = rand() % 1000;
        (*key_array)[i] = rand() % 1000;
        (*record_array)[i] = malloc(sizeof(record_t));
        if ((*record_array)[i] == NULL) {
            printf("Error: Failed to allocate memory for the record array\n");
            free(*offset_array);
            free(*key_array);
            free(*record_array);
            return;
        }
        (*record_array)[i]->value = rand() % 1000;
    }
}

// Define the function to release memory for the arrays
void release_memory(long* offset_array, int* key_array, record_t** record_array) {
    // Release memory for the offset array
    free(offset_array);

    // Release memory for the key array
    free(key_array);

    // Release memory for the record array
    for (int i = 0; i < num_records; i++) {
        free((*record_array)[i]);
    }
    free(record_array);
}
