// Define the method to create and execute a SQL command using parameterized queries
public static IDataReader ExecuteQuery(string connectionString, string query, List<object> values) {
    // Create a new SQL connection
    SqlConnection conn = new SqlConnection(connectionString);

    // Open the connection
    conn.Open();

    // Create a new SQL command with the specified query and parameters
    SqlCommand cmd = new SqlCommand(query, conn);
    foreach (object value in values) {
        cmd.Parameters.AddWithValue("@value", value);
    }

    // Execute the SQL command and return an IDataReader for the result set
    return cmd.ExecuteReader();
}
