use std::collections::HashMap;
use std::net::SocketAddr;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;

use futures::stream::StreamExt;
use tokio::net::TcpListener;
use tokio::select;
use tokio::sync::mpsc::channel;
use tokio::task::JoinHandle;

use crate::media_stream::MediaStream;
use crate::media_server::MediaServer;
use crate::subtitle_stream::SubtitleStream;

struct MediaStreamManager {
    media_servers: HashMap<SocketAddr, Arc<Mutex<MediaServer>>>,
}

impl MediaStreamManager {
    fn new() -> Self {
        Self {
            media_servers: HashMap::new(),
        }
    }

    fn add_media_server(&mut self, addr: SocketAddr, server: Arc<Mutex<MediaServer>>) {
        self.media_servers.insert(addr, server);
    }

    fn get_media_server(&self, addr: &SocketAddr) -> Option<Arc<Mutex<MediaServer>>> {
        self.media_servers.get(addr).cloned()
    }
}

struct MediaStreamHandler {
    media_stream: Arc<Mutex<MediaStream>>,
    subtitle_stream: Option<Arc<Mutex<SubtitleStream>>>,
}

impl MediaStreamHandler {
    fn new(media_stream: Arc<Mutex<MediaStream>>) -> Self {
        Self {
            media_stream,
            subtitle_stream: None,
        }
    }

    fn set_subtitle_stream(&mut self, subtitle_stream: Arc<Mutex<SubtitleStream>>) {
        self.subtitle_stream = Some(subtitle_stream);
    }
}

struct MediaServer {
    media_stream_manager: Arc<Mutex<MediaStreamManager>>,
    tcp_listener: TcpListener,
    buffer_size: usize,
    bitrate_adjustment_interval: Duration,
    seek_buffer_size: usize,
}

impl MediaServer {
    fn new(media_stream_manager: Arc<Mutex<MediaStreamManager>>) -> Self {
        let tcp_listener = TcpListener::bind("0.0.0.0:8080").unwrap();
        let buffer_size = 1024 * 1024; // 1 MB
        let bitrate_adjustment_interval = Duration::from_secs(5);
        let seek_buffer_size = 30 * 1024; // 30 KB

        Self {
            media_stream_manager,
            tcp_listener,
            buffer_size,
            bitrate_adjustment_interval,
            seek_buffer_size,
        }
    }

    fn run(&self) -> Result<(), Box<dyn std::error::Error>> {
        let mut incoming = self.tcp_listener.incoming();
        while let Some(stream) = incoming.next().await {
            let media_stream_manager = Arc::clone(&self.media_stream_manager);
            let stream = stream?;
            let handler = MediaStreamHandler::new(Arc::new(Mutex::new(MediaStream::new())));
            tokio::spawn(async move {
                let mut buffer = vec![0u8; self.buffer_size];
                loop {
                    match stream.read(&mut buffer).await {
                        Ok(n) => {
                            if n == 0 {
                                break;
                            }
                            handler.media_stream.lock().unwrap().write(&buffer[..n]);
                        }
                        Err(e) => {
                            eprintln!("Error reading from stream: {}", e);
                            break;
                        }
                    }
                }
            });
        }
    }
}

struct MediaStream {
    media_url: String,
    bitrate: usize,
    buffer: Vec<u8>,
    seek_buffer: Vec<u8>,
    buffer_size: usize,
    seek_buffer_size: usize,
    bitrate_adjustment_interval: Duration,
}

impl MediaStream {
    fn new() -> Self {
        Self {
            media_url: String::new(),
            bitrate: 0,
            buffer: Vec::new(),
            seek_buffer: Vec::new(),
            buffer_size: 1024 * 1024, // 1 MB
            seek_buffer_size: 30 * 1024, // 30 KB
            bitrate_adjustment_interval: Duration::from_secs(5),
        }
    }

    fn set_media_url(&mut self, media_url: &str) {
        self.media_url = String::from(media_url);
    }

    fn set_bitrate(&mut self, bitrate: usize) {
        self.bitrate = bitrate;
    }

    fn write(&mut self, data: &[u8]) {
        self.buffer.extend_from_slice(data);
    }

    fn read(&mut self, buffer: &mut [u8]) -> Result<usize, Box<dyn std::error::Error>> {
        let mut pos = 0;
        while pos < buffer.len() && !self.buffer.is_empty() {
            let n = std::cmp::min(buffer.len() - pos, self.buffer.len());
            buffer[pos..pos + n].copy_from_slice(&self.buffer[..n]);
            self.buffer.drain(0..n);
            pos += n;
        }
        Ok(pos)
    }
}

struct SubtitleStream {
    media_url: String,
    buffer: Vec<u8>,
    seek_buffer: Vec<u8>,
    buffer_size: usize,
    seek_buffer_size: usize,
}

impl SubtitleStream {
    fn new() -> Self {
        Self {
            media_url: String::new(),
            buffer: Vec::new(),
            seek_buffer: Vec::new(),
            buffer_size: 1024 * 1024, // 1 MB
            seek_buffer_size: 30 * 1024, // 30 KB
        }
    }

    fn set_media_url(&mut self, media_url: &str) {
        self.media_url = String::from(media_url);
    }

    fn write(&mut self, data: &[u8]) {
        self.buffer.extend_from_slice(data);
    }

    fn read(&mut self, buffer: &mut [u8]) -> Result<usize, Box<dyn std::error::Error>> {
        let mut pos = 0;
        while pos < buffer.len() && !self.buffer.is_empty() {
            let n = std::cmp::min(buffer.len() - pos, self.buffer.len());
            buffer[pos..pos + n].copy_from_slice(&self.buffer[..n]);
            self.buffer.drain(0..n);
            pos += n;
        }
        Ok(pos)
    }
}
