```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the structure to store transaction records
struct transaction {
    double amount;
    char *identifier;
    struct item *item;
    float timestamp;
};

// Define a custom tree structure for quick key-based lookups based on the 'char' string identifiers
struct identifier_tree {
    char *key;
    struct transaction *transaction;
    struct identifier_tree *left, *right;
};

// Function to add a new transaction
void add_transaction(struct transaction *transaction) {
    // Allocate memory for the transaction record
    transaction = malloc(sizeof(struct transaction));
    if (transaction == NULL) {
        printf("Error: Failed to allocate memory for transaction\n");
        return;
    }

    // Initialize the transaction fields
    transaction->amount = 0.0;
    transaction->identifier = "";
    transaction->item = NULL;
    transaction->timestamp = time(NULL);

    // Add the transaction to the identifier tree
    struct identifier_tree *node = malloc(sizeof(struct identifier_tree));
    node->key = transaction->identifier;
    node->transaction = transaction;
    node->left = NULL;
    node->right = NULL;

    // Insert the node into the identifier tree
    if (root == NULL) {
        root = node;
    } else {
        struct identifier_tree *current = root;
        while (current != NULL) {
            int cmp = strcmp(node->key, current->key);
            if (cmp < 0) {
                if (current->left == NULL) {
                    current->left = node;
                    break;
                } else {
                    current = current->left;
                }
            } else if (cmp > 0) {
                if (current->right == NULL) {
                    current->right = node;
                    break;
                } else {
                    current = current->right;
                }
            } else {
                // Duplicate identifier, ignore the transaction
                free(node);
                return;
            }
        }
    }
}

// Function to retrieve a transaction by identifier
struct transaction *get_transaction(char *identifier) {
    struct identifier_tree *node = root;
    while (node != NULL) {
        int cmp = strcmp(identifier, node->key);
        if (cmp == 0) {
            return node->transaction;
        } else if (cmp < 0) {
            node = node->left;
        } else {
            node = node->right;
        }
    }
    return NULL;
}

// Function to update the timestamp of a transaction
void update_timestamp(struct transaction *transaction, float new_timestamp) {
    transaction->timestamp = new_timestamp;
}

// Function to periodically clean up unused resources
void cleanup() {
    // Remove any transactions that have not been accessed in the last 30 minutes
    struct identifier_tree *node = root;
    while (node != NULL) {
        if (node->transaction->timestamp < time(NULL) - 30 * 60) {
            free(node->transaction);
            node->transaction = NULL;
        }
        node = node->left;
    }
}
```
