    db->numVertices = 0;
    db->numEdges = 0;
    return db;
}

// Function to add a vertex to the graph database API
void addVertex(struct GraphDatabase *db, int id) {
    if (db->numVertices >= ARRAY_SIZE) {
        printf("The graph database is full. Cannot add more vertices\n");
        return;
    }
    db->vertices[db->numVertices] = malloc(sizeof(struct Vertex));
    db->vertices[db->numVertices]->id = id;
