    for (int i = 0; i < db->numVertices; i++) {
        if (db->vertices[i]->id == id) {
            db->vertices[i]->properties[0] = property;
            return;
        }
    }
}

// Function to set a property on an edge in the graph database API
void setEdgeProperty(struct GraphDatabase *db, int sourceId, int targetId, char *property) {
    for (int i = 0; i < db->numEdges; i++) {
        if (db->edges[i]->sourceId == sourceId && db->edges[i]->targetId == targetId) {
            db->edges[i]->properties[0] = property;
            return;
        }
    }
}

// Function to serialize the graph database to disk
void serializeGraphDatabase(struct GraphDatabase *db, char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        printf("Error opening file %s\n", filename);
        return;
    }
    // Write the number of vertices and edges to the file
    fwrite(&db->numVertices, sizeof(int), 1, file);
    fwrite(&db->numEdges, sizeof(int), 1, file);
    // Write each vertex and edge to the file
    for (int i = 0; i < db->numVertices; i++) {
        struct Vertex *vertex = db->vertices[i];
        fwrite(&vertex->id, sizeof(int), 1, file);
        fwrite(vertex->properties, sizeof(char) * 10, 1, file);
    }
    for (int i = 0; i < db->numEdges; i++) {
        struct Edge *edge = db->edges[i];
        fwrite(&edge->sourceId, sizeof(int), 1, file);
        fwrite(&edge->targetId, sizeof(int), 1, file);
        fwrite(edge->properties, sizeof(char) * 10, 1, file);
    }
    fclose(file);
}

