#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <stdbool.h>

// Custom hash table implementation for efficient key-based lookups
struct HashTable {
    int size;
    struct Node **nodes;
};

struct Node {
    void *key;
    void *value;
    struct Node *next;
};

void hash_table_init(struct HashTable *ht) {
    ht->size = 1024; // initial size of the hash table
    ht->nodes = (struct Node **)malloc(sizeof(struct Node *) * ht->size);
    memset(ht->nodes, 0, sizeof(struct Node *) * ht->size);
}

void hash_table_insert(struct HashTable *ht, void *key, void *value) {
    int index = hash_function(key) % ht->size;
    struct Node **node = &ht->nodes[index];
    while (*node != NULL) {
        if (strcmp((char *)(*node)->key, (char *)key) == 0) {
            // update existing key-value pair
            (*node)->value = value;
            return;
        }
        node = &(*node)->next;
    }
    // insert new key-value pair
    struct Node *new_node = (struct Node *)malloc(sizeof(struct Node));
    new_node->key = key;
    new_node->value = value;
    new_node->next = NULL;
    *node = new_node;
}

void *hash_table_get(struct HashTable *ht, void *key) {
    int index = hash_function(key) % ht->size;
    struct Node **node = &ht->nodes[index];
    while (*node != NULL) {
        if (strcmp((char *)(*node)->key, (char *)key) == 0) {
            return (*node)->value;
        }
        node = &(*node)->next;
    }
    // key not found
    return NULL;
}

// Bloom filter implementation for approximate membership checks
struct BloomFilter {
    int size;
    int num_hashes;
    char *bits;
};

void bloom_filter_init(struct BloomFilter *bf, int size) {
    bf->size = size;
    bf->num_hashes = 3; // number of hash functions to use
    bf->bits = (char *)malloc(sizeof(char) * size);
    memset(bf->bits, 0, sizeof(char) * size);
}

void bloom_filter_insert(struct BloomFilter *bf, void *key) {
    int index = hash_function(key) % bf->size;
    for (int i = 0; i < bf->num_hashes; i++) {
        bf->bits[index] = 1;
        index = (index + 1) % bf->size;
    }
}

bool bloom_filter_contains(struct BloomFilter *bf, void *key) {
    int index = hash_function(key) % bf->size;
    for (int i = 0; i < bf->num_hashes; i++) {
        if (bf->bits[index] == 0) {
            return false;
        }
        index = (index + 1) % bf->size;
    }
    return true;
}

// Red-black tree implementation for ordered key access
struct RBTreeNode {
    void *key;
    void *value;
    struct RBTreeNode *left, *right, *parent;
};

void rb_tree_init(struct RBTreeNode **root) {
    *root = NULL;
}

void rb_tree_insert(struct RBTreeNode **root, void *key, void *value) {
    struct RBTreeNode *node = (struct RBTreeNode *)malloc(sizeof(struct RBTreeNode));
    node->key = key;
    node->value = value;
    node->left = NULL;
    node->right = NULL;
    node->parent = NULL;
    rb_tree_insert_node(root, node);
}

void rb_tree_insert_node(struct RBTreeNode **root, struct RBTreeNode *node) {
    if (*root == NULL) {
        // tree is empty, insert as root node
        *root = node;
        return;
    }
    struct RBTreeNode *parent = NULL;
    struct RBTreeNode *current = *root;
    while (true) {
        int cmp = compare_keys(node->key, current->key);
        if (cmp < 0) {
            // node is less than current node, go left
            if (current->left == NULL) {
                current->left = node;
                break;
            } else {
                parent = current;
                current = current->left;
            }
        } else if (cmp > 0) {
            // node is greater than current node, go right
            if (current->right == NULL) {
                current->right = node;
                break;
            } else {
                parent = current;
                current = current->right;
            }
        } else {
            // node is equal to current node, replace value
            free(current->value);
            current->value = node->value;
            free(node);
            break;
        }
    }
    if (parent != NULL) {
        // update parent node's child pointer
        if (parent->left == current) {
            parent->left = node;
        } else {
            parent->right = node;
        }
    }
}

void *rb_tree_get(struct RBTreeNode **root, void *key) {
    struct RBTreeNode *current = *root;
    while (true) {
        int cmp = compare_keys(key, current->key);
        if (cmp < 0) {
            // node is less than current node, go left
            if (current->left == NULL) {
                return NULL;
            } else {
                current = current->left;
            }
        } else if (cmp > 0) {
            // node is greater than current node, go right
            if (current->right == NULL) {
                return NULL;
            } else {
                current = current->right;
            }
        } else {
            // node is equal to current node, return value
            return current->value;
        }
    }
}

// Custom hash function for generating hash codes from keys
int hash_function(void *key) {
    int hash = 0;
    char *str = (char *)key;
    while (*str != '\0') {
        hash = (hash << 5) - hash + *str++;
    }
    return hash;
}

// Custom compare function for comparing keys
int compare_keys(void *key1, void *key2) {
    char *str1 = (char *)key1;
    char *str2 = (char *)key2;
    while (*str1 != '\0' && *str2 != '\0') {
        if (*str1 < *str2) {
            return -1;
        } else if (*str1 > *str2) {
            return 1;
        }
        str1++;
        str2++;
    }
    if (*str1 == '\0' && *str2 == '\0') {
        return 0;
    } else if (*str1 == '\0') {
        return -1;
    } else {
        return 1;
    }
}
