    for (int i = 0; i < log_buffer.size; i++) {
        if (log_buffer.entries[i]->timestamp == timestamp && log_buffer.entries[i]->level == level) {
            // Unlock the mutex and return the log entry
            pthread_mutex_unlock(&log_buffer.mutex);
            return log_buffer.entries[i];
