    if (initial_size <= 0 || initial_size > MAX_METADATA_LIMIT) {
        fprintf(stderr, "Invalid initial buffer size: %zu\n", initial_size);
        return NULL;
    }

    // Allocate memory for the file buffer
    file_metadata_t* buffer = (file_metadata_t*)malloc(initial_size * sizeof(file_metadata_t));
    if (!buffer) {
