// Define function to dynamically grow the file buffer as needed
file_metadata_t* grow_buffer(file_metadata_t* buffer, size_t current_size) {
    // Check if current size is valid and within system-defined bounds
    if (current_size <= 0 || current_size > MAX_METADATA_LIMIT) {
        fprintf(stderr, "Invalid current buffer size: %zu\n", current_size);
        return NULL;
    }

    // Calculate the new size for the buffer
    size_t new_size = current_size * 2;
    if (new_size > MAX_METADATA_LIMIT) {
