// Define function to compute the MD5 hash of a given file
void compute_md5(const char* filename, unsigned char* md5) {
    // Open the file for reading
    int fd = open(filename, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        return;
    }

    // Read the contents of the file into a buffer
    char* buffer = (char*)malloc(1024 * sizeof(char));
    if (!buffer) {
        fprintf(stderr, "Failed to allocate memory for file buffer: %s\n", strerror(errno));
        close(fd);
        return;
    }
    size_t read = 0;
    while ((read = read(fd, buffer, 1024)) > 0) {
        // Compute the MD5 hash of the file contents
        MD5_CTX ctx;
        MD5_Init(&ctx);
        MD5_Update(&ctx, buffer, read);
        MD5_Final(md5, &ctx);
    }

    // Close the file and free the buffer
    close(fd);
    free(buffer);
}

// Define function to manage concurrent access to the file buffer safely
void manage_concurrent_access(file_metadata_t* buffer, size_t current_size) {
