        buffer[current_size].filesize = filesize;
        buffer[current_size].lastmodified = lastmodified;
        buffer[current_size].version = version;
        current_size++;

        // Release the mutex lock and signal the condition variable
        pthread_mutex_unlock(&mutex);
        pthread_cond_signal(&cond);
    }
}

