    if (file != NULL) {
        fprintf(file, "%s\n", message);
        fclose(file);
    }
}

// Initialize the records array with a given capacity
void initRecordsArray(RecordsArray *array, int capacity) {
    assert(array != NULL);
    array->count = 0;
    array->records = (Record *)malloc(capacity * sizeof(Record));
}

// Add a new record to the records array
void addRecord(RecordsArray *array, long offset, int key, double measurement) {
    assert(array != NULL);
    if (array->count == 0 || array->count >= capacity) {
        // Reallocate memory for the records array if necessary
        array->records = (Record *)realloc(array->records, (capacity *= 2) * sizeof(Record));
    }
    array->records[array->count].offset = offset;
    array->records[array->count].key = key;
    array->records[array->count].measurement = measurement;
    array->count++;
}

// Update a record in the records array
void updateRecord(RecordsArray *array, int index, long offset, int key, double measurement) {
    assert(array != NULL);
    if (index < 0 || index >= array->count) {
        return;
    }
    array->records[index].offset = offset;
    array->records[index].key = key;
    array->records[index].measurement = measurement;
}

// Remove a record from the records array
void removeRecord(RecordsArray *array, int index) {
    assert(array != NULL);
    if (index < 0 || index >= array->count) {
        return;
    }
    for (int i = index; i < array->count - 1; i++) {
        array->records[i] = array->records[i + 1];
    }
    array->count--;
}

