class FileManager:
    def __init__(self, buffer_size=1024*1024, max_buffer_size=1024*1024*10):
        self.buffer_size = buffer_size
        self.max_buffer_size = max_buffer_size
        self.buffers = deque()
        self.metadata = {}

    def upload(self, filepath, metadata=None):
        if not os.path.exists(filepath):
            raise ValueError("File does not exist")

        with open(filepath, "rb") as f:
            buffer = f.read(self.buffer_size)
            while buffer:
                self.buffers.append(buffer)
                buffer = f.read(self.buffer_size)

        if metadata is not None:
            self.metadata[filepath] = metadata

    def process_metadata(self, metadata):
        for filepath in metadata:
            if filepath in self.buffers:
                buffer = self.buffers[filepath]
                md5 = hashlib.md5(buffer).hexdigest()
                self.metadata[filepath]["md5"] = md5

    def get_metadata(self, filepath):
        if filepath in self.metadata:
            return self.metadata[filepath]
        else:
            raise ValueError("File does not exist")

    def delete_metadata(self, filepath):
        if filepath in self.metadata:
            del self.metadata[filepath]

    def rotate_buffers(self):
