    void insert_transaction(transaction_list_t *transactions, item_pool_t *item_pool, float value, char *identifier, item_t *item_ptr, metadata_t metadata) {
        // Check if the transaction list is full
        if (transactions->size == transactions->capacity) {
            // Double the capacity of the transaction list
            transactions->capacity *= 2;
            transactions->transactions = (transaction_t *)realloc(transactions->transactions, sizeof(transaction_t) * transactions->capacity);
