        // Get the transaction to be deleted
        transaction_t *transaction = &transactions->transactions[index];

        // Decrement the reference count of the item pointer
        item_pool->items[transaction->item_ptr - item_pool->items]->ref_count--;

        // Remove the transaction from the list
        for (int i = index; i < transactions->size - 1; i++) {
            transactions->transactions[i] = transactions->transactions[i + 1];
