// Custom hash table implementation
struct HashTable {
    int size;
    struct Node **table;
};

struct Node {
    void *key;
    void *value;
    struct Node *next;
};

void hash_init(struct HashTable *ht) {
    ht->size = 1024;
    ht->table = (struct Node **)malloc(sizeof(struct Node *) * ht->size);
    memset(ht->table, 0, sizeof(struct Node *) * ht->size);
}

void hash_insert(struct HashTable *ht, void *key, void *value) {
    int index = hash_func(key) % ht->size;
    struct Node *node = (struct Node *)malloc(sizeof(struct Node));
    node->key = key;
    node->value = value;
    node->next = ht->table[index];
    ht->table[index] = node;
}

void *hash_lookup(struct HashTable *ht, void *key) {
    int index = hash_func(key) % ht->size;
    struct Node *node = ht->table[index];
    while (node != NULL && !equal(node->key, key)) {
        node = node->next;
    }
    return node == NULL ? NULL : node->value;
}

void hash_destroy(struct HashTable *ht) {
    for (int i = 0; i < ht->size; i++) {
        struct Node *node = ht->table[i];
        while (node != NULL) {
            struct Node *next = node->next;
            free(node);
            node = next;
        }
    }
    free(ht->table);
}

// Custom balanced binary tree implementation
struct TreeNode {
    void *key;
    void *value;
    struct TreeNode *left, *right;
};

void tree_init(struct TreeNode **root) {
    *root = NULL;
}

void tree_insert(struct TreeNode **root, void *key, void *value) {
    if (*root == NULL) {
        struct TreeNode *node = (struct TreeNode *)malloc(sizeof(struct TreeNode));
        node->key = key;
        node->value = value;
        node->left = NULL;
        node->right = NULL;
        *root = node;
    } else {
        struct TreeNode **node = root;
        while (*node != NULL) {
            if (compare(key, (*node)->key) < 0) {
                node = &(*node)->left;
            } else if (compare(key, (*node)->key) > 0) {
                node = &(*node)->right;
            } else {
                break;
            }
        }
        struct TreeNode *new_node = (struct TreeNode *)malloc(sizeof(struct TreeNode));
        new_node->key = key;
        new_node->value = value;
        new_node->left = NULL;
        new_node->right = NULL;
        *node = new_node;
    }
}

void *tree_lookup(struct TreeNode **root, void *key) {
    struct TreeNode **node = root;
    while (*node != NULL && compare(key, (*node)->key) < 0) {
        node = &(*node)->left;
    }
    if (*node == NULL || compare(key, (*node)->key) > 0) {
        return NULL;
    } else {
        return (*node)->value;
    }
}

void tree_destroy(struct TreeNode **root) {
    struct TreeNode *node = *root;
    while (node != NULL) {
        if (node->left != NULL) {
            tree_destroy(&node->left);
        }
        if (node->right != NULL) {
            tree_destroy(&node->right);
        }
        free(node);
        node = *root;
    }
}

