        new_tree_node->key = new_data->label;
        new_tree_node->value = new_data;
        root = insert(root, new_tree_node);
    }
}

// Define the function to delete a data point from the linked list and custom tree structure
void delete(tree_node *root, char *key) {
    // Check if the key exists in the custom tree structure
    if (root != NULL && root->key == key) {
        // Remove the data point from the linked list and custom tree structure
        node *prev = head;
        while (prev->next != NULL && prev->next->data->label != key) {
            prev = prev->next;
        }
        if (prev->next != NULL) {
            free(prev->next);
            prev->next = prev->next->next;
        }
    } else {
        // Recursively search for the data point in the custom tree structure
        root = delete(root, key);
    }
}

