// Define data structures for the flexible data management system
struct data_point {
    double value;
    char *string;
    int id;
    float timestamp;
};

struct data_node {
    struct data_point *data;
    struct data_node *next;
    struct data_node *prev;
};

struct data_list {
    struct data_node *head;
    struct data_node *tail;
    int size;
    pthread_mutex_t mutex;
};

struct data_tree {
    struct data_node *root;
    int size;
    pthread_mutex_t mutex;
};

struct data_hash {
    struct data_node **table;
    int size;
    pthread_mutex_t mutex;
};

// Define functions for managing the flexible data management system
void init_data_list(struct data_list *list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

void insert_data_node(struct data_list *list, struct data_point *data) {
    struct data_node *new_node = malloc(sizeof(struct data_node));
    new_node->data = data;
    new_node->next = NULL;
    new_node->prev = list->tail;
    if (list->tail != NULL) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    pthread_mutex_lock(&list->mutex);
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

void delete_data_node(struct data_list *list, struct data_point *data) {
    struct data_node *current = list->head;
    while (current != NULL && current->data != data) {
        current = current->next;
    }
    if (current == NULL) {
        return;
    }
    if (current == list->head) {
        list->head = current->next;
    }
    if (current == list->tail) {
        list->tail = current->prev;
    }
    if (current->prev != NULL) {
        current->prev->next = current->next;
    }
    if (current->next != NULL) {
        current->next->prev = current->prev;
    }
    pthread_mutex_lock(&list->mutex);
    list->size--;
    pthread_mutex_unlock(&list->mutex);
}

void traverse_data_list(struct data_list *list, void (*callback)(struct data_point *)) {
    struct data_node *current = list->head;
    while (current != NULL) {
        callback(current->data);
        current = current->next;
    }
}

void init_data_tree(struct data_tree *tree) {
    tree->root = NULL;
    tree->size = 0;
    pthread_mutex_init(&tree->mutex, NULL);
}

void insert_data_node_tree(struct data_tree *tree, struct data_point *data) {
    struct data_node *new_node = malloc(sizeof(struct data_node));
    new_node->data = data;
    new_node->next = NULL;
    if (tree->root == NULL) {
        tree->root = new_node;
    } else {
        struct data_node *current = tree->root;
        while (current != NULL && current->data->id < data->id) {
            current = current->next;
        }
        if (current == NULL) {
            current = tree->root;
        }
        new_node->prev = current->prev;
        current->prev = new_node;
    }
    pthread_mutex_lock(&tree->mutex);
    tree->size++;
    pthread_mutex_unlock(&tree->mutex);
}

void delete_data_node_tree(struct data_tree *tree, struct data_point *data) {
    struct data_node *current = tree->root;
    while (current != NULL && current->data != data) {
        current = current->next;
    }
    if (current == NULL) {
        return;
    }
    if (current == tree->root) {
        tree->root = current->next;
    }
    if (current->prev != NULL) {
        current->prev->next = current->next;
    }
    if (current->next != NULL) {
        current->next->prev = current->prev;
    }
    pthread_mutex_lock(&tree->mutex);
    tree->size--;
    pthread_mutex_unlock(&tree->mutex);
}

void traverse_data_tree(struct data_tree *tree, void (*callback)(struct data_point *)) {
    struct data_node *current = tree->root;
    while (current != NULL) {
        callback(current->data);
        current = current->next;
    }
}

void init_data_hash(struct data_hash *hash, int size) {
    hash->table = malloc(sizeof(struct data_node *) * size);
    hash->size = 0;
    pthread_mutex_init(&hash->mutex, NULL);
}

void insert_data_node_hash(struct data_hash *hash, struct data_point *data) {
    int index = data->id % hash->size;
    struct data_node *new_node = malloc(sizeof(struct data_node));
    new_node->data = data;
    new_node->next = NULL;
    if (hash->table[index] == NULL) {
        hash->table[index] = new_node;
    } else {
        struct data_node *current = hash->table[index];
        while (current != NULL && current->data->id < data->id) {
            current = current->next;
        }
        if (current == NULL) {
            current = hash->table[index];
        }
        new_node->prev = current->prev;
        current->prev = new_node;
    }
    pthread_mutex_lock(&hash->mutex);
    hash->size++;
    pthread_mutex_unlock(&hash->mutex);
}

void delete_data_node_hash(struct data_hash *hash, struct data_point *data) {
    int index = data->id % hash->size;
    struct data_node *current = hash->table[index];
    while (current != NULL && current->data != data) {
        current = current->next;
    }
    if (current == NULL) {
        return;
    }
    if (current == hash->table[index]) {
        hash->table[index] = current->next;
    }
    if (current->prev != NULL) {
        current->prev->next = current->next;
    }
    if (current->next != NULL) {
        current->next->prev = current->prev;
    }
    pthread_mutex_lock(&hash->mutex);
    hash->size--;
    pthread_mutex_unlock(&hash->mutex);
}

void traverse_data_hash(struct data_hash *hash, void (*callback)(struct data_point *)) {
    for (int i = 0; i < hash->size; i++) {
        struct data_node *current = hash->table[i];
        while (current != NULL) {
            callback(current->data);
            current = current->next;
        }
    }
}

// Define functions for managing the logging mechanism
void init_logging(struct logging *log, char *filename) {
    log->file = fopen(filename, "a");
    if (log->file == NULL) {
        printf("Error opening file %s\n", filename);
        exit(1);
    }
}

void log_operation(struct logging *log, char *operation, struct data_point *data) {
    fprintf(log->file, "%s: %d, %f, %s, %d\n", operation, data->value, data->string, data->id, data->timestamp);
}

