    prune->threshold = threshold;
}

void prune_data_list(struct data_list *list, struct pruning *prune) {
    struct data_node *current = list->head;
    while (current != NULL && current->data->timestamp < prune->threshold) {
        delete_data_node(list, current->data);
        current = list->head;
    }
}

void prune_data_tree(struct data_tree *tree, struct pruning *prune) {
    struct data_node *current = tree->root;
    while (current != NULL && current->data->timestamp < prune->threshold) {
        delete_data_node_tree(tree, current->data);
        current = tree->root;
    }
}

void prune_data_hash(struct data_hash *hash, struct pruning *prune) {
    for (int i = 0; i < hash->size; i++) {
        struct data_node *current = hash->table[i];
        while (current != NULL && current->data->timestamp < prune->threshold) {
            delete_data_node_hash(hash, current->data);
            current = hash->table[i];
        }
    }
}

// Define functions for managing the external configuration mechanism
void init_config(struct config *cfg, char *filename) {
    cfg->file = fopen(filename, "r");
    if (cfg->file == NULL) {
        printf("Error opening file %s\n", filename);
        exit(1);
    }
}

void read_config(struct config *cfg, struct flexible_data_management_system *sys) {
    char line[256];
    while (fgets(line, sizeof(line), cfg->file)) {
        if (strncmp(line, "memory_threshold", 15) == 0) {
            int threshold;
            sscanf(line, "%*s %d", &threshold);
            sys->prune.threshold = threshold;
        } else if (strncmp(line, "logging_interval", 16) == 0) {
            int interval;
            sscanf(line, "%*s %d", &interval);
            sys->log.interval = interval;
        } else if (strncmp(line, "data_source", 10) == 0) {
            char source[256];
            sscanf(line, "%*s %s", source);
            strcpy(sys->data_source.name, source);
        } else if (strncmp(line, "data_format", 11) == 0) {
            char format[256];
            sscanf(line, "%*s %s", format);
            strcpy(sys->data_source.format, format);
        } else if (strncmp(line, "data_rate", 9) == 0) {
            int rate;
            sscanf(line, "%*s %d", &rate);
            sys->data_source.rate = rate;
        }
    }
}

void close_config(struct config *cfg) {
    fclose(cfg->file);
}

// Define the flexible data management system
