// Function to dynamically allocate and manage complex data structure
complex_data_t *allocate_complex_data(int num_double, int num_char, int num_int, int num_data_points) {
    // Allocate memory for the complex data structure
    complex_data_t *complex_data = malloc(sizeof(complex_data_t));
    if (complex_data == NULL) {
        return NULL;
    }

    // Allocate memory for arrays of double, char, int, and data points
    complex_data->double_array = malloc(num_double * sizeof(double));
    complex_data->char_strings = malloc(num_char * sizeof(char*));
    complex_data->int_identifiers = malloc(num_int * sizeof(int));
    complex_data->data_points = malloc(num_data_points * sizeof(data_point_t));

