}

// Function to insert new data points into the complex data structure
void insert_data_point(complex_data_t *complex_data, int index, double double_value, char *char_string, int int_value, float float_value) {
    // Acquire lock on mutex for thread safety
    pthread_mutex_lock(&mutex);

    // Update timestamp for new data point
    complex_data->data_points[index].timestamp = time(NULL);

    // Insert new data point into doubly-linked list
    node_t *new_node = malloc(sizeof(node_t));
    new_node->data_point = &complex_data->data_points[index];
    new_node->prev = NULL;
    new_node->next = complex_data->head;
    if (complex_data->head != NULL) {
        complex_data->head->prev = new_node;
    }
    complex_data->head = new_node;

    // Insert new data point into custom tree structure based on char string
    tree_node_t *new_tree_node = malloc(sizeof(tree_node_t));
    new_tree_node->key = strdup(char_string);
    new_tree_node->data_point = &complex_data->data_points[index];
    new_tree_node->left = NULL;
    new_tree_node->right = NULL;
    if (complex_data->root == NULL) {
        complex_data->root = new_tree_node;
    } else {
        tree_node_t *current_node = complex_data->root;
        while (1) {
            int cmp = strcmp(new_tree_node->key, current_node->key);
            if (cmp < 0) {
                if (current_node->left == NULL) {
                    current_node->left = new_tree_node;
                    break;
                } else {
                    current_node = current_node->left;
                }
            } else if (cmp > 0) {
                if (current_node->right == NULL) {
                    current_node->right = new_tree_node;
                    break;
                } else {
                    current_node = current_node->right;
                }
            } else {
                // Duplicate key found, do not insert
                free(new_tree_node);
                break;
            }
        }
    }

    // Release lock on mutex for thread safety
    pthread_mutex_unlock(&mutex);
