struct HashTable *allocateHashTable(struct DataStructure *dataStructure) {
    struct MemoryPool *memoryPool = dataStructure->memoryPool;
    size_t blockSize = memoryPool->blockSize;
    size_t numBlocks = memoryPool->numBlocks;
    if (numBlocks == 0 || memoryPool->blocks->freeBytes < sizeof(struct HashTable)) {
        allocateBlock(memoryPool);
    }
    struct Block *block = memoryPool->blocks;
    block->freeBytes -= sizeof(struct HashTable);
    struct HashTable *table = (struct HashTable *)((char *)block + block->freeBytes - sizeof(struct HashTable));
    table->size = 0;
    table->capacity = 0;
    table->entries = NULL;
    return table;
}

// Function to deallocate a hash table in the data structure
void deallocateHashTable(struct DataStructure *dataStructure, struct HashTable *table) {
    struct MemoryPool *memoryPool = dataStructure->memoryPool;
    size_t blockSize = memoryPool->blockSize;
    size_t numBlocks = memoryPool->numBlocks;
    struct Block *block = (struct Block *)((char *)table - ((char *)table - (char *)block));
    block->freeBytes += sizeof(struct HashTable);
}

// Function to allocate a new data structure
struct DataStructure *allocateDataStructure() {
    struct MemoryPool *memoryPool = malloc(sizeof(struct MemoryPool));
    if (memoryPool == NULL) {
        return NULL;
    }
    memoryPool->blocks = NULL;
    memoryPool->blockSize = 0;
    memoryPool->numBlocks = 0;
    struct DataStructure *dataStructure = malloc(sizeof(struct DataStructure));
    if (dataStructure == NULL) {
        free(memoryPool);
        return NULL;
    }
    dataStructure->memoryPool = memoryPool;
    dataStructure->hashTable = allocateHashTable(dataStructure);
    dataStructure->linkedList = allocateLinkedList(dataStructure);
    return dataStructure;
}

// Function to deallocate a data structure
void deallocateDataStructure(struct DataStructure *dataStructure) {
    struct MemoryPool *memoryPool = dataStructure->memoryPool;
    size_t blockSize = memoryPool->blockSize;
    size_t numBlocks = memoryPool->numBlocks;
    for (size_t i = 0; i < numBlocks; i++) {
        struct Block *block = memoryPool->blocks;
        memoryPool->blocks = block->next;
        free(block);
    }
    free(memoryPool);
}

// Function to insert a record into the data structure
void insertRecord(struct DataStructure *dataStructure, int key, void *value) {
    struct HashTableEntry *entry = allocateHashTableEntry(dataStructure);
    entry->record = allocateRecord(dataStructure);
    entry->record->key = key;
    entry->record->value = value;
    dataStructure->hashTable->size++;
    if (dataStructure->hashTable->size > dataStructure->hashTable->capacity) {
        resizeHashTable(dataStructure);
    }
}

// Function to delete a record from the data structure
void deleteRecord(struct DataStructure *dataStructure, int key) {
    struct HashTableEntry *entry = findHashTableEntry(dataStructure, key);
    if (entry != NULL) {
        deallocateRecord(dataStructure, entry->record);
        deallocateHashTableEntry(dataStructure, entry);
        dataStructure->hashTable->size--;
    }
}

// Function to find a record in the data structure
struct Record *findRecord(struct DataStructure *dataStructure, int key) {
    struct HashTableEntry *entry = findHashTableEntry(dataStructure, key);
    if (entry != NULL) {
        return entry->record;
    } else {
        return NULL;
    }
}

// Function to resize the hash table
void resizeHashTable(struct DataStructure *dataStructure) {
    struct HashTable *table = dataStructure->hashTable;
    size_t newCapacity = table->capacity == 0 ? 1 : table->capacity * 2;
    struct HashTableEntry **newEntries = malloc(sizeof(struct HashTableEntry *) * newCapacity);
    if (newEntries == NULL) {
        return;
    }
    for (size_t i = 0; i < table->capacity; i++) {
        struct HashTableEntry *entry = table->entries[i];
        while (entry != NULL) {
            size_t index = entry->record->key % newCapacity;
            entry->next = newEntries[index];
            newEntries[index] = entry;
            entry = entry->next;
        }
    }
    free(table->entries);
    table->capacity = newCapacity;
    table->entries = newEntries;
}

// Function to monitor the memory pool's usage statistics
void monitorMemoryPoolUsage(struct DataStructure *dataStructure) {
    struct MemoryPool *memoryPool = dataStructure->memoryPool;
    size_t totalAllocatedBytes = 0;
    size_t currentlyFreeBytes = 0;
    size_t averageBlockSize = 0;
    for (size_t i = 0; i < memoryPool->numBlocks; i++) {
        struct Block *block = memoryPool->blocks;
        totalAllocatedBytes += block->freeBytes;
        currentlyFreeBytes += block->freeBytes;
        averageBlockSize += block->freeBytes / (i + 1);
    }
    printf("Total allocated bytes: %zu\n", totalAllocatedBytes);
    printf("Currently free bytes: %zu\n", currentlyFreeBytes);
    printf("Average block size: %zu\n", averageBlockSize);
}

// Function to serialize the data structure to a file
void serializeDataStructure(struct DataStructure *dataStructure, FILE *file) {
    struct HashTable *table = dataStructure->hashTable;
    fwrite(&table->size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < table->capacity; i++) {
        struct HashTableEntry *entry = table->entries[i];
        while (entry != NULL) {
            fwrite(&entry->record->key, sizeof(int), 1, file);
            fwrite(&entry->record->value, sizeof(void *), 1, file);
            entry = entry->next;
        }
    }
}

// Function to deserialize the data structure from a file
struct DataStructure *deserializeDataStructure(FILE *file) {
    struct MemoryPool *memoryPool = malloc(sizeof(struct MemoryPool));
    if (memoryPool == NULL) {
        return NULL;
    }
    memoryPool->blocks = NULL;
    memoryPool->blockSize = 0;
    memoryPool->numBlocks = 0;
    struct DataStructure *dataStructure = malloc(sizeof(struct DataStructure));
    if (dataStructure == NULL) {
        free(memoryPool);
        return NULL;
    }
    dataStructure->memoryPool = memoryPool;
    size_t size;
    fread(&size, sizeof(size_t), 1, file);
    struct HashTable *table = allocateHashTable(dataStructure);
    table->capacity = size;
    table->entries = malloc(sizeof(struct HashTableEntry *) * size);
    for (size_t i = 0; i < size; i++) {
        table->entries[i] = NULL;
    }
    for (size_t i = 0; i < size; i++) {
        int key;
        fread(&key, sizeof(int), 1, file);
        void *value;
        fread(&value, sizeof(void *), 1, file);
        struct HashTableEntry *entry = allocateHashTableEntry(dataStructure);
        entry->record = allocateRecord(dataStructure);
        entry->record->key = key;
        entry->record->value = value;
        size_t index = key % table->capacity;
        entry->next = table->entries[index];
        table->entries[index] = entry;
    }
    return dataStructure;
}
