// Custom memory pool allocator
struct MemoryPool {
    size_t block_size; // Size of each block in bytes
    size_t num_blocks; // Number of blocks in the pool
    size_t free_blocks; // Number of free blocks
    void* blocks; // Pointer to the start of the memory pool
};

// Initialize a new memory pool with the given number of blocks and block size
struct MemoryPool* init_memory_pool(size_t num_blocks, size_t block_size) {
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));
    if (!pool) {
        return NULL;
    }
    pool->num_blocks = num_blocks;
    pool->free_blocks = num_blocks;
    pool->block_size = block_size;
    pool->blocks = mmap(NULL, num_blocks * block_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (pool->blocks == MAP_FAILED) {
        free(pool);
        return NULL;
    }
    return pool;
}

// Allocate a new block from the memory pool
void* allocate_block(struct MemoryPool* pool) {
    if (!pool || !pool->free_blocks) {
        return NULL;
    }
    void* block = pool->blocks + (--pool->free_blocks * pool->block_size);
    return block;
}

// Free a block back to the memory pool
void free_block(struct MemoryPool* pool, void* block) {
    if (!pool || !block) {
        return;
    }
    size_t index = (char*)block - (char*)pool->blocks;
    index /= pool->block_size;
    pool->free_blocks += 1;
}

// Custom doubly linked list for managing records
struct Record {
    int value; // Integer value of the record
    void* metadata; // Pointer to metadata associated with the record
    void* data; // Pointer to external data referenced by the record
    struct Record* next; // Next record in the list
    struct Record* prev; // Previous record in the list
};

// Initialize a new doubly linked list
struct Record* init_list() {
    struct Record* head = malloc(sizeof(struct Record));
    if (!head) {
        return NULL;
    }
    head->next = NULL;
    head->prev = NULL;
    return head;
}

// Insert a new record into the list at the given position
void insert_record(struct Record* head, struct Record* record, size_t pos) {
    if (!head || !record) {
        return;
    }
    // Find the previous and next records in the list
    struct Record* prev = NULL;
    struct Record* next = head;
    while (next && pos--) {
        prev = next;
        next = next->next;
    }
    // Insert the new record between the previous and next records
    if (prev) {
        prev->next = record;
    } else {
        head = record;
    }
    if (next) {
        next->prev = record;
    }
    record->next = next;
    record->prev = prev;
}

// Delete a record from the list at the given position
void delete_record(struct Record* head, size_t pos) {
    if (!head) {
        return;
    }
    // Find the previous and next records in the list
    struct Record* prev = NULL;
    struct Record* next = head;
    while (next && pos--) {
        prev = next;
        next = next->next;
    }
    // Remove the record from the list
    if (prev) {
        prev->next = next->next;
    } else {
        head = next->next;
    }
    if (next->next) {
        next->next->prev = prev;
    }
    free(next);
}

// Traverse the list and perform a callback function on each record
void traverse_list(struct Record* head, void (*callback)(struct Record*)) {
    if (!head || !callback) {
        return;
    }
    struct Record* current = head;
    while (current) {
        callback(current);
        current = current->next;
    }
}

// Custom hash table for fast key-based lookups
struct HashTable {
