// Initialize a new hash table with the given number of buckets
struct HashTable* init_hash_table(size_t num_buckets) {
    struct HashTable* table = malloc(sizeof(struct HashTable));
    if (!table) {
        return NULL;
    }
    table->num_buckets = num_buckets;
    table->buckets = calloc(num_buckets, sizeof(struct Record*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }
    return table;
}

// Insert a new record into the hash table with the given key
void insert_record_hash(struct HashTable* table, struct Record* record, size_t key) {
    if (!table || !record) {
        return;
    }
    // Calculate the bucket index for the key
    size_t index = key % table->num_buckets;
    // Insert the record into the bucket
    struct Record** bucket = &(table->buckets[index]);
    while (*bucket) {
        if ((*bucket)->key == key) {
            break;
        }
        bucket = &((*bucket)->next);
    }
    record->next = *bucket;
    *bucket = record;
}

// Lookup a record in the hash table with the given key
struct Record* lookup_record_hash(struct HashTable* table, size_t key) {
    if (!table) {
        return NULL;
    }
    // Calculate the bucket index for the key
    size_t index = key % table->num_buckets;
    // Search the bucket for a matching record
    struct Record* current = table->buckets[index];
    while (current) {
        if (current->key == key) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

