    if (!filter) {
        return NULL;
    }
    filter->num_bits = num_bits;
    filter->num_hashes = num_hashes;
    filter->bits = calloc(num_bits, sizeof(uint64_t));
    if (!filter->bits) {
        free(filter);
        return NULL;
    }
    return filter;
}

// Insert a new element into the bloom filter
void insert_element_bloom(struct BloomFilter* filter, void* element) {
    if (!filter || !element) {
        return;
    }
    // Calculate the hash values for the element
    uint64_t hashes[filter->num_hashes];
    for (size_t i = 0; i < filter->num_hashes; ++i) {
        hashes[i] = hash(element, i);
    }
    // Set the corresponding bits in the filter
    for (size_t i = 0; i < filter->num_bits; ++i) {
        if (filter->bits[i]) {
            continue;
        }
        bool set = false;
        for (size_t j = 0; j < filter->num_hashes; ++j) {
            size_t index = hashes[j] % filter->num_bits;
            if (!filter->bits[index]) {
                filter->bits[index] = true;
                set = true;
                break;
            }
        }
        if (set) {
            break;
        }
    }
}

// Check if an element is a member of the bloom filter
bool check_element_bloom(struct BloomFilter* filter, void* element) {
    if (!filter || !element) {
        return false;
    }
    // Calculate the hash values for the element
    uint64_t hashes[filter->num_hashes];
    for (size_t i = 0; i < filter->num_hashes; ++i) {
        hashes[i] = hash(element, i);
    }
    // Check the corresponding bits in the filter
    for (size_t i = 0; i < filter->num_bits; ++i) {
        if (!filter->bits[i]) {
            continue;
        }
        bool found = false;
        for (size_t j = 0; j < filter->num_hashes; ++j) {
            size_t index = hashes[j] % filter->num_bits;
            if (filter->bits[index]) {
                found = true;
                break;
            }
        }
        if (found) {
            return true;
        }
    }
    return false;
}

