// Calculate the memory pool's usage statistics
struct MemoryPoolStats calculate_memory_pool_stats(struct MemoryPool* pool) {
    struct MemoryPoolStats stats = {0, 0, 0};
    if (!pool) {
        return stats;
    }
    // Calculate the total number of bytes allocated in the pool
    size_t total_allocated = pool->num_blocks * pool->block_size;
    // Calculate the current number of free bytes in the pool
    size_t current_free = 0;
    for (size_t i = 0; i < pool->num_blocks; ++i) {
        if (!pool->blocks[i].used) {
            current_free += pool->block_size;
        }
    }
    // Calculate the average block size in the pool
    double average_block_size = 0;
    for (size_t i = 0; i < pool->num_blocks; ++i) {
        if (!pool->blocks[i].used) {
            continue;
        }
        average_block_size += pool->block_size;
    }
    stats.total_allocated = total_allocated;
    stats.current_free = current_free;
    stats.average_block_size = average_block_size / (pool->num_blocks - current_free);
    return stats;
}

// Print the memory pool's usage statistics
void print_memory_pool_stats(struct MemoryPool* pool) {
    struct MemoryPoolStats stats = calculate_memory_pool_stats(pool);
    printf("Memory Pool Stats:\n");
    printf("\tTotal Allocated: %zu bytes\n", stats.total_allocated);
    printf("\tCurrent Free: %zu bytes\n", stats.current_free);
    printf("\tAverage Block Size: %.2f bytes\n", stats.average_block_size);
}

