    new_node->next = ht->buckets[index];
    ht->buckets[index] = new_node;
    pthread_mutex_unlock(&mutex);
}

void* find(HashTable* ht, int key) {
    pthread_mutex_lock(&mutex);
    int index = hash(key);
    Node* node = ht->buckets[index];
    while (node != NULL && node->record->key != key) {
        node = node->next;
    }
    if (node == NULL) {
        return NULL;
    } else {
        node->record->ref_count++;
        pthread_mutex_unlock(&mutex);
        return node->record->node;
    }
}

void delete(HashTable* ht, int key) {
    pthread_mutex_lock(&mutex);
    int index = hash(key);
    Node* node = ht->buckets[index];
    while (node != NULL && node->record->key != key) {
        node = node->next;
    }
    if (node == NULL) {
        pthread_mutex_unlock(&mutex);
        return;
    } else {
        node->record->ref_count--;
        if (node->record->ref_count == 0) {
            free_wrapper(node->record->node);
            free_wrapper(node->record);
            Node* temp = node;
            node = node->next;
            ht->buckets[index] = node;
            free_wrapper(temp);
        } else {
            pthread_mutex_unlock(&mutex);
        }
    }
}

// Define functions for linked list operations
void* create_node(int value) {
    Node* new_node = malloc_wrapper(sizeof(Node));
    new_node->record = malloc_wrapper(sizeof(Record));
    new_node->record->key = value;
    new_node->record->node = NULL;
    new_node->record->ref_count = 0;
    new_node->next = NULL;
    return new_node;
}

void insert_node(Node* node, void* data) {
    Node* new_node = create_node(data);
    new_node->next = node->next;
    node->next = new_node;
}

void delete_node(Node* node) {
    free_wrapper(node->record->node);
    free_wrapper(node->record);
    Node* temp = node;
    node = node->next;
    free_wrapper(temp);
