    FILE* file = fopen("records.bin", "wb");
    if (file == NULL) {
        printf("Error: unable to open file for serialization\n");
        return;
    }
    LinkedListNode* node = ds->linked_list->head;
    while (node != NULL) {
        fwrite(node, sizeof(Record), 1, file);
        node = node->next;
    }
    fclose(file);
}

void deserialize(FlexibleDataStructure* ds) {
    // Deserialize the records from a file
    FILE* file = fopen("records.bin", "rb");
    if (file == NULL) {
        printf("Error: unable to open file for deserialization\n");
        return;
    }
