    while (fread(&record, sizeof(Record), 1, file) > 0) {
        insert(ds, record.key, record.value);
    }
    fclose(file);
}

void* hash_function(void* key) {
    // Define the hash function to map the keys to indices in the hash table
    int index = 0;
    char* str = (char*)key;
    for (int i = 0; i < strlen(str); i++) {
        index += str[i];
    }
    return index % ds->hash_table->size;
}

void* memory_allocator(int size) {
    // Define the memory allocator to allocate and deallocate memory from the pool
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->buffer = malloc(size);
    pool->used += size;
    return pool->buffer;
}

void memory_deallocator(void* buffer) {
    // Define the memory deallocator to free the memory from the pool
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->used -= size;
    free(pool->buffer);
}

