    init(&ds);
    insert(&ds, "key1", "value1");
    insert(&ds, "key2", "value2");
    insert(&ds, "key3", "value3");
    retrieve(&ds, "key1");
    delete(&ds, "key2");
    serialize(&ds);
    deserialize(&ds);
    return 0;
}
