// Define the different record types
typedef struct {
    int integer;
} IntegerRecord;

typedef struct {
    float float_value;
} FloatRecord;

typedef struct {
    char *string;
} StringRecord;

typedef struct {
    time_t timestamp;
} TimestampRecord;

// Define the record type enum
enum RecordType {
    INTEGER,
    FLOAT,
    STRING,
    TIMESTAMP
};

// Define the record structure
struct Record {
    enum RecordType type;
    union {
        IntegerRecord integer_record;
        FloatRecord float_record;
        StringRecord string_record;
        TimestampRecord timestamp_record;
    } data;
};

// Define the resource bundle structure
struct ResourceBundle {
    int num_records;
    struct Record *records;
};

// Function to load a resource bundle from a specified directory
int load_resource_bundle(const char *directory, struct ResourceBundle *bundle) {
    // Open the directory and read its contents
    DIR *dir = opendir(directory);
    if (dir == NULL) {
        printf("Error opening directory: %s\n", strerror(errno));
        return -1;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip over non-file entries
        if (entry->d_type != DT_REG) {
            continue;
        }

        // Open the file and read its contents
        int fd = open(entry->d_name, O_RDONLY);
        if (fd == -1) {
            printf("Error opening file: %s\n", strerror(errno));
            continue;
        }

        // Read the file contents into a buffer
        char *buffer = malloc(entry->d_size + 1);
        read(fd, buffer, entry->d_size);
        close(fd);

        // Parse the file contents and add the records to the bundle
        struct Record record;
        int num_records = parse_file_contents(buffer, &record);
        for (int i = 0; i < num_records; i++) {
            add_record(&bundle->records[i], &record);
        }
    }

    // Close the directory and return the number of records in the bundle
    closedir(dir);
    return bundle->num_records;
}

// Function to parse a file contents and add the records to the bundle
int parse_file_contents(char *buffer, struct Record *record) {
    // Initialize the record type and data
    record->type = INTEGER;
    record->data.integer_record.integer = 0;

    // Parse the file contents and update the record type and data accordingly
    char *token = strtok(buffer, " ");
    while (token != NULL) {
        if (strcmp(token, "INTEGER") == 0) {
            record->type = INTEGER;
            token = strtok(NULL, " ");
            record->data.integer_record.integer = atoi(token);
        } else if (strcmp(token, "FLOAT") == 0) {
            record->type = FLOAT;
            token = strtok(NULL, " ");
            record->data.float_record.float_value = atof(token);
        } else if (strcmp(token, "STRING") == 0) {
            record->type = STRING;
            token = strtok(NULL, " ");
            record->data.string_record.string = malloc(strlen(token) + 1);
            strcpy(record->data.string_record.string, token);
        } else if (strcmp(token, "TIMESTAMP") == 0) {
            record->type = TIMESTAMP;
            token = strtok(NULL, " ");
            record->data.timestamp_record.timestamp = atof(token);
        }
    }

    // Return the number of records in the bundle
    return 1;
}

// Function to add a record to the resource bundle
void add_record(struct Record *record, struct Record *new_record) {
    // Check if there is enough space in the bundle for the new record
    if (bundle->num_records == bundle->capacity) {
        // Reallocate the memory for the records
        int new_capacity = bundle->capacity * 2;
        struct Record *new_records = realloc(bundle->records, new_capacity);
        if (new_records == NULL) {
            printf("Error reallocating memory for records\n");
            return;
        }

        // Update the capacity and records pointers
        bundle->capacity = new_capacity;
        bundle->records = new_records;
    }

    // Add the new record to the bundle
    memcpy(&bundle->records[bundle->num_records], new_record, sizeof(struct Record));
    bundle->num_records++;
}
