    pthread_mutex_unlock(&system->mutex);
}

// Delete an event from the priority queue and maps
void delete_event(struct EventManagementSystem* system, long timestamp) {
    // Acquire mutex for thread-safe access to the event management system
    pthread_mutex_lock(&system->mutex);

    // Find the event with the specified timestamp in the priority queue and maps
    int index = -1;
    for (int i = 0; i < system->priority_queue->size; i++) {
        if (system->events_by_timestamp[i][timestamp] != NULL) {
