// Retrieve an event from the priority queue and maps based on priority
Event* retrieve_event_by_priority(struct EventManagementSystem* system, int priority) {
    // Acquire mutex for thread-safe access to the event management system
    pthread_mutex_lock(&system->mutex);

    // Find the event with the specified priority in the priority queue and maps
    int index = -1;
    for (int i = 0; i < system->priority_queue->size; i++) {
