    Event* event = system->priority_queue->events[index];

    // Release mutex for thread-safe access to the event management system
    pthread_mutex_unlock(&system->mutex);

    return event;
}

// Filter events by priority and logging level
void filter_events(struct EventManagementSystem* system, int priority, int logging_level) {
    // Acquire mutex for thread-safe access to the event management system
    pthread_mutex_lock(&system->mutex);

    // Iterate over the events in the priority queue and maps
    for (int i = 0; i < system->priority_queue->size; i++) {
        Event* event = system->priority_queue->events[i];
        if (event != NULL && event->priority >= priority && event->logging_level >= logging_level) {
            // Remove the event from the priority queue and maps
            system->priority_queue->events[i] = NULL;
            system->events_by_timestamp[event->priority][event->timestamp] = NULL;
            system->events_by_priority[event->priority][event->timestamp] = NULL;
            system->priority_queue->size--;
        }
    }

    // Release mutex for thread-safe access to the event management system
    pthread_mutex_unlock(&system->mutex);
}

// Log events by priority and logging level
void log_events(struct EventManagementSystem* system, int priority, int logging_level) {
