    int value;
} record;

// Define the function to manage memory allocation and initialization
record* allocate_records(size_t num_records) {
    // Calculate the size of the offsets array
    size_t offset_size = 16;
    while (offset_size < num_records) {
        offset_size *= 2;
    }

    // Allocate memory for the offsets and keys arrays
    long* offsets = malloc(sizeof(long) * offset_size);
    int* keys = malloc(sizeof(int) * (offset_size / 2));

    // Initialize the offsets array with random values between -100 and 100
    srand(time(NULL));
    for (size_t i = 0; i < offset_size; i++) {
        offsets[i] = rand() % 200 - 100;
    }

    // Initialize the keys array with unique values from the offsets array
    for (size_t i = 0; i < offset_size / 2; i++) {
        int key = offsets[i];
        while (key == offsets[i] || key == offsets[i + 1]) {
            key = rand() % 200 - 100;
        }
        keys[i] = key;
    }

    // Allocate memory for the records array and initialize each record with a random value between -100 and 100
    record* records = malloc(sizeof(record) * num_records);
    for (size_t i = 0; i < num_records; i++) {
        int key = keys[i];
        long* value_ptr = &offsets[key];
        int value = rand() % 200 - 100;
        records[i] = (record){value_ptr, value};
    }

    // Free the offsets and keys arrays if memory allocation fails
    if (!records) {
        free(offsets);
        free(keys);
    }

    return records;
}
