// Define a custom data structure for storing raw sensor readings and their corresponding keys
typedef struct {
    short key;
    double reading;
} data_point;

// Define a function to dynamically allocate memory for the dataset
void allocate_dataset(data_point **dataset, int size) {
    // Allocate memory for the dataset
    *dataset = (data_point *)malloc(size * sizeof(data_point));

    // Initialize each data point in the dataset with a key and reading value
    for (int i = 0; i < size; i++) {
        (*dataset)[i].key = i;
        (*dataset)[i].reading = 0.0;
    }
}

// Define a function to deallocate memory for the dataset
void deallocate_dataset(data_point **dataset) {
    // Free the memory allocated for the dataset
    free(*dataset);
}

// Define a function to update a data point in the dataset
void update_data_point(data_point *data, double reading) {
    // Update the reading value of the data point
    data->reading = reading;
}

// Define a function to linearly interpolate between two adjacent data points
float interpolate(data_point *data1, data_point *data2) {
    // Calculate the difference in keys between the two data points
    int diff = abs(data1->key - data2->key);

    // Calculate the fractional part of the key difference
    float frac = (float)(diff % 1000) / 1000;

    // Interpolate between the two readings using the fractional part of the key difference
    return data1->reading + ((data2->reading - data1->reading) * frac);
}

// Define a function to handle missing or corrupted data points
void handle_missing_data(data_point *data, double reading) {
    // If the data point is NULL, set its reading value to the provided reading
    if (data == NULL) {
        data->reading = reading;
    }
}

// Define a function to gracefully degrade performance under stress
void degrade_performance(data_point *data, double reading) {
    // If the data point is NULL or has a reading value of 0.0, set its reading value to the provided reading
    if (data == NULL || data->reading == 0.0) {
        data->reading = reading;
    }
}

// Define a function to handle concurrent updates to the dataset
void update_dataset(data_point **dataset, int size, double reading) {
    // Lock the dataset for writing
    pthread_mutex_lock(&dataset_mutex);

    // Update each data point in the dataset with the provided reading value
    for (int i = 0; i < size; i++) {
        update_data_point(&(*dataset)[i], reading);
    }

    // Unlock the dataset for writing
    pthread_mutex_unlock(&dataset_mutex);
}

// Define a function to handle potential memory leaks and ensure that all allocated memory is properly freed upon function exit
void cleanup(data_point **dataset) {
    // Free the memory allocated for the dataset
    deallocate_dataset(dataset);
}
