// Define the Node structure for the linked list
typedef struct Node {
    char* data_ptr;
    int weight;
    struct Node* next;
} Node;

// Define a function to allocate and initialize memory for a new node
Node* create_node(const char* data) {
    // Allocate memory for the node structure
    Node* new_node = malloc(sizeof(Node));
    if (new_node == NULL) {
        return NULL;
    }

    // Initialize the node's data pointer and weight
    new_node->data_ptr = strdup(data);
    new_node->weight = rand() % 100 + 1;

    // Set the next pointer to NULL
    new_node->next = NULL;

    return new_node;
}

// Define a function to add a node to the linked list
void add_node(Node** head, const char* data) {
    Node* new_node = create_node(data);
    if (new_node == NULL) {
        // Handle memory allocation failure
        return;
    }

    // Add the node to the linked list
    new_node->next = *head;
    *head = new_node;
}

// Define a function to remove a node from the linked list
void remove_node(Node** head, const char* data) {
    Node* current = *head;
    Node* previous = NULL;

    // Find the node to be removed
    while (current != NULL && strcmp(current->data_ptr, data) != 0) {
        previous = current;
        current = current->next;
    }

    // Remove the node from the linked list
    if (current != NULL) {
        if (previous == NULL) {
            *head = current->next;
        } else {
            previous->next = current->next;
        }

        free(current);
    }
}

// Define a function to free memory for the linked list
void free_list(Node** head) {
    Node* current = *head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}

// Define a function to handle memory allocation failures
