    // Handle the stale data appropriately, e.g., by ignoring it or updating the cache
}

int main() {
    Node* head = NULL;

    // Add nodes to the linked list
    add_node(&head, "data1");
    add_node(&head, "data2");
    add_node(&head, "data3");

    // Remove a node from the linked list
    remove_node(&head, "data2");

    // Free memory for the linked list
    free_list(&head);

    return 0;
}
