    Record* record = (Record*)malloc(sizeof(Record));
    record->key = key;
    record->value = value;
    return record;
}

// Function to insert a record into the hash table
void insert_record(HashTable* hash_table, int key, int value) {
    // Check if the hash table is full
    if (hash_table->size == hash_table->capacity) {
        // Double the capacity of the hash table
        hash_table->capacity *= 2;
        Record** new_records = (Record**)malloc(sizeof(Record*) * hash_table->capacity);
        for (int i = 0; i < hash_table->size; i++) {
            new_records[i] = hash_table->records[i];
        }
        free(hash_table->records);
        hash_table->records = new_records;
    }
    // Insert the record into the hash table
    int index = key % hash_table->capacity;
    while (hash_table->records[index] != NULL) {
        index++;
        if (index == hash_table->capacity) {
            index = 0;
        }
    }
    Record* record = create_record(key, value);
    hash_table->records[index] = record;
    hash_table->size++;
}

// Function to delete a record from the hash table
void delete_record(HashTable* hash_table, int key) {
    // Find the index of the record in the hash table
    int index = key % hash_table->capacity;
    while (hash_table->records[index] != NULL && hash_table->records[index]->key != key) {
        index++;
        if (index == hash_table->capacity) {
            index = 0;
        }
    }
    // If the record is found, delete it from the hash table
    if (hash_table->records[index] != NULL) {
        Record* record = hash_table->records[index];
        hash_table->records[index] = NULL;
        free(record);
        hash_table->size--;
    }
}

// Function to search for a record in the hash table
Record* search_record(HashTable* hash_table, int key) {
    // Find the index of the record in the hash table
    int index = key % hash_table->capacity;
    while (hash_table->records[index] != NULL && hash_table->records[index]->key != key) {
        index++;
        if (index == hash_table->capacity) {
            index = 0;
        }
    }
    // If the record is found, return it
    if (hash_table->records[index] != NULL) {
        return hash_table->records[index];
    } else {
        return NULL;
    }
}

// Function to traverse all records in the hash table
void traverse_records(HashTable* hash_table, void (*callback)(Record*)) {
    for (int i = 0; i < hash_table->capacity; i++) {
        if (hash_table->records[i] != NULL) {
            callback(hash_table->records[i]);
        }
    }
}

