// Define the structure for each record in the dataset
typedef struct {
    int id;
    float value;
    char *str;
    time_t timestamp;
} Record;

// Define a custom data structure to support efficient insertion, deletion, and lookup operations
typedef struct {
    Record **records; // Array of pointers to records
    int size; // Current size of the array
    int capacity; // Maximum capacity of the array
} DataStructure;

// Define a function to initialize the data structure
void initDataStructure(DataStructure *ds) {
    ds->records = malloc(sizeof(Record *) * 10);
    ds->size = 0;
    ds->capacity = 10;
}

// Define a function to insert a new record into the data structure
void insertRecord(DataStructure *ds, Record *record) {
    // Check if the array is full and needs to be resized
    if (ds->size == ds->capacity) {
        ds->records = realloc(ds->records, sizeof(Record *) * (ds->capacity + 10));
        ds->capacity += 10;
    }

    // Insert the new record into the array
    ds->records[ds->size++] = record;
}

// Define a function to delete a record from the data structure
void deleteRecord(DataStructure *ds, int id) {
    // Find the index of the record to be deleted
    int i;
    for (i = 0; i < ds->size; i++) {
        if (ds->records[i]->id == id) {
            break;
        }
    }

    // Check if the record was found and delete it
    if (i < ds->size) {
        for (int j = i; j < ds->size - 1; j++) {
            ds->records[j] = ds->records[j + 1];
        }
        ds->size--;
    }
}

// Define a function to update a record in the data structure
void updateRecord(DataStructure *ds, Record *record) {
    // Find the index of the record to be updated
    int i;
    for (i = 0; i < ds->size; i++) {
        if (ds->records[i]->id == record->id) {
            break;
        }
    }

    // Check if the record was found and update it
    if (i < ds->size) {
        ds->records[i] = record;
    }
}

// Define a function to retrieve a record from the data structure
Record *getRecord(DataStructure *ds, int id) {
    // Find the index of the record to be retrieved
    int i;
    for (i = 0; i < ds->size; i++) {
        if (ds->records[i]->id == id) {
            break;
        }
    }

    // Check if the record was found and return it
    if (i < ds->size) {
        return ds->records[i];
    } else {
        return NULL;
    }
}

// Define a function to periodically prune outdated records
void pruneRecords(DataStructure *ds, time_t duration) {
    // Iterate through the records and delete any that are older than the specified duration
    for (int i = 0; i < ds->size; i++) {
        if (ds->records[i]->timestamp < time(NULL) - duration) {
            deleteRecord(ds, ds->records[i]->id);
        }
    }
}

// Define a function to periodically check and release unused memory blocks
void checkMemoryUsage(DataStructure *ds) {
    // Check if the array is more than half full and needs to be resized
