void prune_data_points(int retention_policy) {
    // Remove the oldest data points from the linked list, hash table, and custom B-tree based on the specified retention policy
    LinkedListNode **head = &linked_list.head;
    while (*head != NULL) {
        if (retention_policy == 1) {
            // Remove the oldest data point from the linked list, hash table, and custom B-tree
            LinkedListNode *node = *head;
            *head = node->next;
            free(node);
        } else if (retention_policy == 2) {
            // Remove the least recently used data point from the linked list, hash table, and custom B-tree
            LinkedListNode *node = *head;
