    user_profile* p = (user_profile*)malloc(sizeof(user_profile));
    if (!p) {
        // Handle allocation failure gracefully by resetting status flags and releasing all previously allocated memory
        printf("Failed to allocate memory for new profile\n");
        return -1;
    }
    strcpy(p->name, name);
    p->birthdate = birthdate;
    p->balance = balance;
    p->log = (activity_log_entry*)malloc(sizeof(activity_log_entry));
    if (!p->log) {
        // Handle allocation failure gracefully by resetting status flags and releasing all previously allocated memory
        printf("Failed to allocate memory for new profile\n");
        free(p);
        return -1;
    }
    d->profiles = (user_profile*)realloc(d->profiles, sizeof(user_profile) * (d->num_profiles + 1));
    if (!d->profiles) {
        // Handle allocation failure gracefully by resetting status flags and releasing all previously allocated memory
        printf("Failed to reallocate memory for dataset %d\n", d->id);
        free(p->log);
        free(p);
        return -1;
    }
    d->profiles[d->num_profiles++] = *p;
    return 0;
}

// Define a function to remove an inactive user profile from a dataset
int remove_profile(dataset* d, int index) {
    if (!d || index < 0 || index >= d->num_profiles) {
        // Handle invalid input gracefully by returning an error code
        return -1;
    }
    user_profile* p = &d->profiles[index];
    free(p->log);
    free(p);
    d->num_profiles--;
    if (index < d->num_profiles) {
        memmove(&d->profiles[index], &d->profiles[index + 1], sizeof(user_profile) * (d->num_profiles - index));
    }
    return 0;
}

// Define a function to update an existing user profile in a dataset
int update_profile(dataset* d, int index, char* name, struct date birthdate, float balance) {
    if (!d || index < 0 || index >= d->num_profiles || !name || !birthdate || !balance) {
        // Handle invalid input gracefully by returning an error code
        return -1;
    }
    user_profile* p = &d->profiles[index];
    strcpy(p->name, name);
    p->birthdate = birthdate;
    p->balance = balance;
    return 0;
}

// Define a function to retrieve an existing user profile from a dataset
user_profile* get_profile(dataset* d, int index) {
    if (!d || index < 0 || index >= d->num_profiles) {
        // Handle invalid input gracefully by returning NULL
        return NULL;
    }
    return &d->profiles[index];
}

// Define a function to retrieve the number of user profiles in a dataset
int get_num_profiles(dataset* d) {
    if (!d) {
        // Handle invalid input gracefully by returning -1
        return -1;
    }
    return d->num_profiles;
}
