#include <pthread.h>

// Define data structures for log entries, events, and user profiles
typedef struct {
    int id;
    float value;
    time_t timestamp;
} log_entry;

typedef struct {
    char name[256];
    int age;
    struct preferences {
        // nested preferences
    } preferences;
} user_profile;

typedef struct {
