// Structure to represent a node in the list
typedef struct Node {
    int value;
    Metadata metadata;
    struct Node* next;
    struct Node* prev;
} Node;

// Structure to represent metadata for each node
typedef struct Metadata {
    time_t timestamp;
    int refCount;
} Metadata;

// Function to insert a new node in ascending order based on its integer value
void insertNode(int value) {
    // Create a new node with the given value and metadata
    Node* newNode = malloc(sizeof(Node));
    newNode->value = value;
    newNode->metadata.timestamp = time(NULL);
    newNode->metadata.refCount = 1;

    // Find the position where the new node should be inserted
    Node* current = head;
    while (current != NULL && current->value < value) {
        current = current->next;
    }

    // Insert the new node in the list
    if (current == NULL) {
        // The new node is the first element in the list
        newNode->prev = NULL;
        newNode->next = head;
        head = newNode;
    } else {
        // The new node should be inserted before the current node
        newNode->prev = current->prev;
        newNode->next = current;
        current->prev = newNode;
    }
}

// Function to update the reference count upon insertion
void updateRefCount(int value) {
    // Find the node with the given value and increment its reference count
    Node* current = head;
    while (current != NULL && current->value < value) {
        current = current->next;
    }
    if (current != NULL && current->value == value) {
        current->metadata.refCount++;
    }
}

// Function to delete nodes with a reference count of zero
void deleteNodes() {
    // Find the first node with a reference count of zero
    Node* current = head;
    while (current != NULL && current->metadata.refCount > 0) {
        current = current->next;
    }

    // Delete nodes until we reach the end of the list or find a node with a non-zero reference count
    while (current != NULL && current->metadata.refCount == 0) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}

// Function to traverse the list and print both integer values and metadata timestamps
void traverseList() {
    // Start at the beginning of the list
    Node* current = head;

    // Traverse the list until we reach the end
    while (current != NULL) {
        printf("%d, %ld\n", current->value, current->metadata.timestamp);
        current = current->next;
    }
}
