    void insert(const std::string& key, int value) {
        Node* new_node = new Node();
        new_node->key = key;
        new_node->value = value;
        new_node->timestamp = 0;
        new_node->ref_count = 1;
        new_node->locked = false;

        // Insert the node into the tree
        insert_node(new_node);
    }

    // Update the reference count of a node with the given key
    void update_ref_count(const std::string& key) {
        Node* node = find_node(key);
        if (node != nullptr) {
            node->ref_count++;
        }
    }

    // Delete a node with the given key if its reference count is zero
    void delete_if_unused(const std::string& key) {
        Node* node = find_node(key);
        if (node != nullptr && node->ref_count == 0) {
            delete_node(node);
        }
    }

