        if (root_ == nullptr) {
            root_ = node;
        } else {
            Node* current = root_;
            while (current != nullptr) {
                if (node->key < current->key) {
                    if (current->left == nullptr) {
                        current->left = node;
                        break;
                    } else {
                        current = current->left;
                    }
                } else if (node->key > current->key) {
                    if (current->right == nullptr) {
                        current->right = node;
                        break;
                    } else {
                        current = current->right;
                    }
                } else {
                    // Duplicate key, do nothing
                    delete node;
                    return;
                }
            }
        }
    }

    // Find a node with the given key in the tree
    Node* find_node(const std::string& key) {
        if (root_ == nullptr) {
            return nullptr;
        } else {
            Node* current = root_;
            while (current != nullptr) {
                if (key < current->key) {
                    current = current->left;
                } else if (key > current->key) {
                    current = current->right;
                } else {
                    return current;
                }
            }
        }
        return nullptr;
    }

