        if (root_ == nullptr) {
            return;
        } else {
            Node* current = root_;
            while (current != nullptr) {
                if (node->key < current->key) {
                    current = current->left;
                } else if (node->key > current->key) {
                    current = current->right;
                } else {
                    // Found the node to delete, remove it from the tree
                    if (current == root_) {
                        root_ = nullptr;
                    } else {
                        Node* parent = find_parent(node);
                        if (parent->left == current) {
                            parent->left = nullptr;
                        } else {
                            parent->right = nullptr;
                        }
                    }
                    delete node;
                    return;
                }
            }
        }
    }

    // Find the parent of a node in the tree
    Node* find_parent(Node* node) {
        if (root_ == nullptr) {
            return nullptr;
        } else {
            Node* current = root_;
            while (current != nullptr) {
                if (node->key < current->key) {
                    current = current->left;
                } else if (node->key > current->key) {
                    current = current->right;
                } else {
                    return current;
                }
            }
        }
        return nullptr;
    }

