    void traverse_tree(std::vector<Node*>* nodes) {
        if (root_ == nullptr) {
            return;
        } else {
            Node* current = root_;
            while (current != nullptr) {
                nodes->push_back(current);
                traverse_tree(&nodes, current->left);
                traverse_tree(&nodes, current->right);
            }
        }
    }

    // The root node of the tree
    Node* root_;
};
