// Define a thread-safe lock for concurrent access to the data structure
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the custom hash table
void init_custom_hash_table(CustomHashTable* table) {
    table->keys = malloc(sizeof(Key*) * 1024);
    table->records = malloc(sizeof(Record*) * 1024);
    table->capacity = 1024;
    table->size = 0;
}

// Function to insert a new key-value pair into the custom hash table
void insert_into_custom_hash_table(CustomHashTable* table, Key* key, Record* record) {
    pthread_mutex_lock(&mutex);
    if (table->size == table->capacity) {
        // Resize the hash table if it is full
        table->keys = realloc(table->keys, sizeof(Key*) * 2 * table->capacity);
        table->records = realloc(table->records, sizeof(Record*) * 2 * table->capacity);
        table->capacity *= 2;
    }
    table->keys[table->size] = key;
    table->records[table->size] = record;
    table->size++;
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve a value from the custom hash table using a key
Record* get_from_custom_hash_table(CustomHashTable* table, Key* key) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < table->size; i++) {
        if (key == table->keys[i]) {
            Record* record = table->records[i];
            pthread_mutex_unlock(&mutex);
            return record;
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

// Function to delete a key-value pair from the custom hash table using a key
void delete_from_custom_hash_table(CustomHashTable* table, Key* key) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < table->size; i++) {
        if (key == table->keys[i]) {
            // Shift all subsequent elements to the left
            for (int j = i + 1; j < table->size; j++) {
                table->keys[j - 1] = table->keys[j];
                table->records[j - 1] = table->records[j];
            }
            // Decrement the size of the hash table
            table->size--;
            pthread_mutex_unlock(&mutex);
            return;
        }
    }
    pthread_mutex_unlock(&mutex);
}

// Function to traverse all key-value pairs in the custom hash table
void traverse_custom_hash_table(CustomHashTable* table, void (*callback)(Key*, Record*)) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < table->size; i++) {
        callback(table->keys[i], table->records[i]);
    }
    pthread_mutex_unlock(&mutex);
