  // Function to insert a new book into the hash table
  void insert(const Book& book) {
    lock_guard<mutex> lock(mutex_);
    map_.insert({book.isbn, book});
  }

  // Function to remove a book from the hash table
  void remove(const string& isbn) {
    lock_guard<mutex> lock(mutex_);
    map_.erase(isbn);
  }

  // Function to find a book in the hash table by ISBN
  Book* find(const string& isbn) {
    lock_guard<mutex> lock(mutex_);
    auto it = map_.find(isbn);
    if (it != map_.end()) {
      return &it->second;
    } else {
      return nullptr;
    }
  }

 private:
  // Map to store the books in the hash table
  unordered_map<string, Book> map_;

  // Mutex to protect the map from concurrent access
  mutex mutex_;
};

// Define a linked list for reservation queues
class ReservationQueue {
 public:
  // Constructor to initialize the linked list with an empty head node
  ReservationQueue() : head_(nullptr) {}

  // Function to insert a new reservation request into the linked list
  void insert(const ReservationRequest& request) {
    lock_guard<mutex> lock(mutex_);
    auto node = make_shared<ReservationNode>(request);
    if (head_ == nullptr) {
      head_ = node;
    } else {
      tail_->next = node;
    }
    tail_ = node;
  }

  // Function to remove a reservation request from the linked list
  void remove(const string& isbn, const string& borrower_id) {
    lock_guard<mutex> lock(mutex_);
    auto it = head_;
    while (it != nullptr) {
      if (it->request.isbn == isbn && it->request.borrower_id == borrower_id) {
        if (it == head_) {
          head_ = it->next;
        } else {
          tail_->next = it->next;
        }
        break;
      }
      it = it->next;
    }
  }

  // Function to find a reservation request in the linked list by ISBN and borrower ID
  ReservationRequest* find(const string& isbn, const string& borrower_id) {
    lock_guard<mutex> lock(mutex_);
    auto it = head_;
    while (it != nullptr) {
      if (it->request.isbn == isbn && it->request.borrower_id == borrower_id) {
        return &it->request;
      }
      it = it->next;
    }
    return nullptr;
  }

 private:
  // Node struct for the linked list of reservation requests
  struct ReservationNode {
    ReservationRequest request;
    shared_ptr<ReservationNode> next;
  };

  // Head node of the linked list
  shared_ptr<ReservationNode> head_;

  // Tail node of the linked list
  shared_ptr<ReservationNode> tail_;

  // Mutex to protect the linked list from concurrent access
  mutex mutex_;
};

