  LibraryManager() : catalog_(), borrowers_(), reservation_queue_() {}

  // Function to insert a new book into the catalog
  void insert(const Book& book) {
    lock_guard<mutex> lock(mutex_);
    catalog_.insert(book);
  }

  // Function to remove a book from the catalog
  void remove(const string& isbn) {
    lock_guard<mutex> lock(mutex_);
    catalog_.remove(isbn);
  }

  // Function to find a book in the catalog by ISBN
  Book* find(const string& isbn) {
    lock_guard<mutex> lock(mutex_);
    return catalog_.find(isbn);
  }

  // Function to insert a new borrower into the borrower records
  void insert_borrower(const Borrower& borrower) {
    lock_guard<mutex> lock(mutex_);
    borrowers_.insert({borrower.id, borrower});
  }

  // Function to remove a borrower from the borrower records
  void remove_borrower(const string& id) {
    lock_guard<mutex> lock(mutex_);
    borrowers_.erase(id);
  }

  // Function to find a borrower in the borrower records by ID
  Borrower* find_borrower(const string& id) {
    lock_guard<mutex> lock(mutex_);
    auto it = borrowers_.find(id);
    if (it != borrowers_.end()) {
      return &it->second;
    } else {
      return nullptr;
    }
  }

  // Function to insert a new reservation request into the reservation queue
  void insert_reservation(const ReservationRequest& request) {
    lock_guard<mutex> lock(mutex_);
    reservation_queue_.insert(request);
  }

  // Function to remove a reservation request from the reservation queue
  void remove_reservation(const string& isbn, const string& borrower_id) {
    lock_guard<mutex> lock(mutex_);
    reservation_queue_.remove(isbn, borrower_id);
  }

  // Function to find a reservation request in the reservation queue by ISBN and borrower ID
  ReservationRequest* find_reservation(const string& isbn, const string& borrower_id) {
    lock_guard<mutex> lock(mutex_);
    return reservation_queue_.find(isbn, borrower_id);
  }

 private:
  // Custom hash table for fast lookups based on ISBN and borrower ID
  CustomHashTable catalog_;

  // Map to store the borrower records
  unordered_map<string, Borrower> borrowers_;

  // Linked list for reservation queues
  ReservationQueue reservation_queue_;

  // Mutex to protect the library manager from concurrent access
  mutex mutex_;
};
