    if (g_data_points == NULL) {
        return -2;
    }

    // Open the log file and set the file descriptor
    g_log_file_fd = open(config->log_file_path, O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (g_log_file_fd == -1) {
        return -3;
    }

    // Set the global configuration and initialize the mutex and semaphore
    g_config = config;
    pthread_mutex_init(&g_lock, NULL);
    semaphore_init(&g_semaphore, 0, 1);

    return 0;
}

// Function to add a new data point to the logging system
int add_data_point(short key, float value, double* reading) {
    // Check if the data point is valid
    if (key < 0 || value < 0 || reading == NULL) {
        return -1;
    }

    // Acquire the lock and increment the number of data points
    pthread_mutex_lock(&g_lock);
    g_num_data_points++;

    // Add the new data point to the array
    g_data_points[g_num_data_points - 1] = (data_point){key, value, reading};

    // Release the lock and signal the semaphore
    pthread_mutex_unlock(&g_lock);
    semaphore_signal(&g_semaphore);

    return 0;
}

// Function to retrieve a data point from the logging system
data_point* get_data_point(short key) {
    // Check if the key is valid
    if (key < 0) {
        return NULL;
    }

    // Acquire the lock and search for the data point
    pthread_mutex_lock(&g_lock);
    for (size_t i = 0; i < g_num_data_points; i++) {
        if (g_data_points[i].key == key) {
            // Return a copy of the data point
            data_point* result = malloc(sizeof(data_point));
            memcpy(result, &g_data_points[i], sizeof(data_point));
            pthread_mutex_unlock(&g_lock);
            return result;
        }
    }

    // Release the lock and return NULL if not found
    pthread_mutex_unlock(&g_lock);
    return NULL;
}

// Function to filter data points based on a specific criteria
void filter_data_points(int (*filter)(const void*)) {
    // Acquire the lock and iterate over the data points
    pthread_mutex_lock(&g_lock);
    for (size_t i = 0; i < g_num_data_points; i++) {
        if (!filter(&g_data_points[i])) {
            // Remove the data point from the array
            memmove(&g_data_points[i], &g_data_points[i + 1], (g_num_data_points - i) * sizeof(data_point));
            g_num_data_points--;
        }
    }

    // Release the lock and signal the semaphore
    pthread_mutex_unlock(&g_lock);
    semaphore_signal(&g_semaphore);
}

// Function to update a data point in the logging system
int update_data_point(short key, float value, double* reading) {
    // Check if the data point is valid
    if (key < 0 || value < 0 || reading == NULL) {
        return -1;
    }

    // Acquire the lock and search for the data point
    pthread_mutex_lock(&g_lock);
    for (size_t i = 0; i < g_num_data_points; i++) {
        if (g_data_points[i].key == key) {
            // Update the data point and release the lock
            g_data_points[i].value = value;
            memcpy(g_data_points[i].reading, reading, sizeof(double));
            pthread_mutex_unlock(&g_lock);
            return 0;
        }
    }

    // Release the lock and return an error if not found
    pthread_mutex_unlock(&g_lock);
    return -2;
}

// Function to remove a data point from the logging system
int remove_data_point(short key) {
    // Check if the key is valid
    if (key < 0) {
        return -1;
    }

    // Acquire the lock and search for the data point
    pthread_mutex_lock(&g_lock);
    for (size_t i = 0; i < g_num_data_points; i++) {
        if (g_data_points[i].key == key) {
            // Remove the data point from the array and release the lock
            memmove(&g_data_points[i], &g_data_points[i + 1], (g_num_data_points - i) * sizeof(data_point));
            g_num_data_points--;
            pthread_mutex_unlock(&g_lock);
            return 0;
        }
    }

    // Release the lock and return an error if not found
    pthread_mutex_unlock(&g_lock);
    return -2;
}

// Function to close the logging system
void close_logging() {
    // Acquire the lock and release all resources
    pthread_mutex_lock(&g_lock);
    free(g_data_points);
    g_data_points = NULL;
    g_num_data_points = 0;
    close(g_log_file_fd);
    g_log_file_fd = -1;
    pthread_mutex_unlock(&g_lock);
}
