void init_log_buffer(LogBuffer* buffer, size_t initial_size) {
    if (initial_size < MIN_BUFFER_SIZE || initial_size > MAX_BUFFER_SIZE) {
        fprintf(stderr, "Invalid initial log buffer size: %zu\n", initial_size);
        exit(1);
    }
    buffer->capacity = initial_size;
    buffer->count = 0;
    buffer->buffer = (LogEntry**)malloc(sizeof(LogEntry*) * buffer->capacity);
    if (!buffer->buffer) {
        fprintf(stderr, "Failed to allocate log buffer memory\n");
        exit(1);
    }
    pthread_mutex_init(&buffer->mutex, NULL);
}

void destroy_log_buffer(LogBuffer* buffer) {
    for (size_t i = 0; i < buffer->count; ++i) {
        free(buffer->buffer[i]->message);
        free(buffer->buffer[i]);
    }
    free(buffer->buffer);
    pthread_mutex_destroy(&buffer->mutex);
}

void log_entry(LogBuffer* buffer, const char* message, int severity_level) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    if (!entry) {
        fprintf(stderr, "Failed to allocate log entry memory\n");
        exit(1);
    }
    entry->message = strdup(message);
    entry->severity_level = severity_level;
    entry->timestamp = time(NULL);
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->count == buffer->capacity) {
        // Buffer is full, need to resize
        size_t new_size = buffer->capacity * 2;
        if (new_size > MAX_BUFFER_SIZE) {
            fprintf(stderr, "Log buffer exceeded maximum size: %zu\n", new_size);
            exit(1);
        }
        LogEntry** new_buffer = (LogEntry**)realloc(buffer->buffer, sizeof(LogEntry*) * new_size);
        if (!new_buffer) {
            fprintf(stderr, "Failed to resize log buffer\n");
            exit(1);
        }
        buffer->buffer = new_buffer;
        buffer->capacity = new_size;
    }
    buffer->buffer[buffer->count++] = entry;
    pthread_mutex_unlock(&buffer->mutex);
}

void log(const char* message, int severity_level) {
    LogBuffer* buffer = (LogBuffer*)malloc(sizeof(LogBuffer));
    if (!buffer) {
        fprintf(stderr, "Failed to allocate log buffer\n");
        exit(1);
    }
    init_log_buffer(buffer, DEFAULT_BUFFER_SIZE);
    while (true) {
        char input[MAX_MESSAGE_LENGTH];
        if (fgets(input, MAX_MESSAGE_LENGTH, stdin)) {
            log_entry(buffer, input, severity_level);
        } else {
            break;
        }
    }
    destroy_log_buffer(buffer);
}
