// Log level priority array
int log_level_priority[10] = { 5, 4, 3, 2, 1, 0, -1, -2, -3, -4 };

// Log entry structure
struct log_entry {
    time_t timestamp;
    int level;
    char *message;
    void *metadata;
    unsigned long trace_id;
};

// Log data structure
struct log_data {
    struct log_entry **entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
};

// Initialize log data structure
void init_log_data(struct log_data *data) {
    // Allocate memory for the log entries array
    data->entries = (struct log_entry **)malloc(sizeof(struct log_entry *) * 1000);
    if (!data->entries) {
        perror("Failed to allocate memory for log entries");
        exit(EXIT_FAILURE);
    }

    // Initialize the capacity and count of the log data structure
    data->capacity = 1000;
    data->count = 0;

    // Initialize the mutex lock for thread-safe access to the log data structure
    pthread_mutex_init(&data->lock, NULL);
}

// Add a new log entry to the log data structure
void add_log_entry(struct log_data *data, struct log_entry *entry) {
    // Acquire the mutex lock for thread-safe access to the log data structure
    pthread_mutex_lock(&data->lock);

    // Check if the log data structure is full
    if (data->count == data->capacity) {
        // Double the capacity of the log data structure
        data->capacity *= 2;

        // Reallocate memory for the log entries array
        struct log_entry **new_entries = (struct log_entry **)realloc(data->entries, sizeof(struct log_entry *) * data->capacity);
        if (!new_entries) {
            perror("Failed to reallocate memory for log entries");
            exit(EXIT_FAILURE);
        }
        data->entries = new_entries;
    }

    // Add the new log entry to the end of the log data structure
    data->entries[data->count++] = entry;

    // Release the mutex lock for thread-safe access to the log data structure
    pthread_mutex_unlock(&data->lock);
}

// Retrieve a log entry from the log data structure by trace ID
struct log_entry *get_log_entry(struct log_data *data, unsigned long trace_id) {
    // Acquire the mutex lock for thread-safe access to the log data structure
    pthread_mutex_lock(&data->lock);

    // Iterate over the log entries in the log data structure
    for (size_t i = 0; i < data->count; i++) {
        struct log_entry *entry = data->entries[i];
        if (entry->trace_id == trace_id) {
            // Release the mutex lock for thread-safe access to the log data structure
            pthread_mutex_unlock(&data->lock);

            // Return the retrieved log entry
            return entry;
        }
    }

    // Release the mutex lock for thread-safe access to the log data structure
    pthread_mutex_unlock(&data->lock);

    // Return NULL if no log entry with the specified trace ID is found
    return NULL;
}

// Filter and sort logs based on priority levels
void filter_and_sort(struct log_data *data, int min_level) {
    // Acquire the mutex lock for thread-safe access to the log data structure
    pthread_mutex_lock(&data->lock);

    // Iterate over the log entries in the log data structure
    for (size_t i = 0; i < data->count; i++) {
        struct log_entry *entry = data->entries[i];

        // Check if the log level is greater than or equal to the minimum priority level
        if (log_level_priority[entry->level] >= min_level) {
            // Swap the current log entry with the last log entry in the array
            struct log_entry *last_entry = data->entries[data->count - 1];
            data->entries[i] = last_entry;
            data->entries[data->count - 1] = entry;

            // Decrement the count of the log data structure
            data->count--;
        }
    }

    // Release the mutex lock for thread-safe access to the log data structure
    pthread_mutex_unlock(&data->lock);
}

// Free memory allocated for the log data structure
void free_log_data(struct log_data *data) {
    // Acquire the mutex lock for thread-safe access to the log data structure
    pthread_mutex_lock(&data->lock);

    // Release the memory allocated for the log entries array
    free(data->entries);

    // Release the mutex lock for thread-safe access to the log data structure
    pthread_mutex_unlock(&data->lock);
}
