#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define data structures for each type of data point
typedef struct {
    double value;
    char *string;
    float timestamp;
} data_point;

// Define a linked list structure for each type of data point
typedef struct node {
    void *data;
    struct node *next;
} node;

// Define a custom hash table for quick key-based lookups
typedef struct {
    int size;
    node **buckets;
} hash_table;

// Initialize the linked lists and custom hash table
void init(hash_table *ht) {
    // Initialize the linked lists for each type of data point
    ht->double_list = NULL;
    ht->char_list = NULL;
    ht->data_point_list = NULL;

    // Initialize the custom hash table with a default size
    ht->size = 1024;
    ht->buckets = (node **)malloc(ht->size * sizeof(node *));
    for (int i = 0; i < ht->size; i++) {
        ht->buckets[i] = NULL;
    }
}

// Insert a data point into the linked lists and custom hash table
void insert(hash_table *ht, void *data) {
    // Get the type of data point
    int type = get_type(data);

    // Insert the data point into the appropriate linked list
    switch (type) {
        case 0: // double
            ht->double_list = insert_node(ht->double_list, data);
            break;
        case 1: // char
            ht->char_list = insert_node(ht->char_list, data);
            break;
        case 2: // data_point
            ht->data_point_list = insert_node(ht->data_point_list, data);
            break;
    }

    // Insert the data point into the custom hash table
    int index = get_hash(data);
    ht->buckets[index] = insert_node(ht->buckets[index], data);
}

// Delete a data point from the linked lists and custom hash table
void delete(hash_table *ht, void *data) {
    // Get the type of data point
    int type = get_type(data);

    // Delete the data point from the appropriate linked list
    switch (type) {
        case 0: // double
            ht->double_list = delete_node(ht->double_list, data);
            break;
        case 1: // char
            ht->char_list = delete_node(ht->char_list, data);
            break;
        case 2: // data_point
            ht->data_point_list = delete_node(ht->data_point_list, data);
            break;
    }

    // Delete the data point from the custom hash table
    int index = get_hash(data);
    ht->buckets[index] = delete_node(ht->buckets[index], data);
}

// Traverse the linked lists and custom hash table
void traverse(hash_table *ht) {
    // Traverse the double linked list
    node *current = ht->double_list;
    while (current != NULL) {
        printf("%f\n", current->data);
        current = current->next;
    }

    // Traverse the char linked list
    current = ht->char_list;
    while (current != NULL) {
        printf("%s\n", current->data);
        current = current->next;
    }

    // Traverse the data point linked list
    current = ht->data_point_list;
    while (current != NULL) {
        data_point *dp = (data_point *)current->data;
        printf("%f %s %f\n", dp->value, dp->string, dp->timestamp);
        current = current->next;
    }
}

// Get the type of a data point
int get_type(void *data) {
    if (strcmp((char *)data, "double") == 0) {
        return 0;
    } else if (strcmp((char *)data, "char") == 0) {
        return 1;
    } else {
        return 2;
    }
}

// Get the hash of a data point
int get_hash(void *data) {
    char *key = (char *)data;
    int hash = 0;
    for (int i = 0; i < strlen(key); i++) {
        hash += key[i];
    }
    return hash % ht->size;
}

// Insert a node into a linked list
node *insert_node(node *list, void *data) {
    node *new_node = (node *)malloc(sizeof(node));
    new_node->data = data;
    new_node->next = list;
    return new_node;
}

// Delete a node from a linked list
node *delete_node(node *list, void *data) {
    if (list == NULL) {
        return NULL;
    } else if (list->data == data) {
        node *temp = list;
        list = list->next;
        free(temp);
        return list;
    } else {
        list->next = delete_node(list->next, data);
        return list;
    }
}
