#include <pthread.h>

// Define the session structure
typedef struct {
    int id;
    time_t start_timestamp;
    time_t end_timestamp;
    struct event *events;
} session_t;

// Define the event structure
typedef struct {
    int type;
    time_t timestamp;
    char *message;
} event_t;

// Define the hash table for quick key-based lookups based on session IDs
#define HASH_TABLE_SIZE 1024
struct hash_table {
    session_t **buckets[HASH_TABLE_SIZE];
};

// Function to initialize a new session
session_t *init_session(int id) {
    session_t *new_session = malloc(sizeof(session_t));
    if (!new_session) {
        perror("Failed to allocate memory for new session");
        return NULL;
    }
    new_session->id = id;
    new_session->start_timestamp = time(NULL);
    new_session->end_timestamp = NULL;
    new_session->events = NULL;
    return new_session;
}

// Function to add a new event to a session
void add_event(session_t *session, int type, char *message) {
    // Allocate memory for the new event node
    event_t *new_event = malloc(sizeof(event_t));
    if (!new_event) {
        perror("Failed to allocate memory for new event");
        return;
    }
    new_event->type = type;
    new_event->timestamp = time(NULL);
    new_event->message = message;

    // Add the new event node to the end of the linked list
    if (session->events == NULL) {
        session->events = new_event;
    } else {
        event_t *current_event = session->events;
        while (current_event->next != NULL) {
            current_event = current_event->next;
        }
        current_event->next = new_event;
    }
}

// Function to update the end timestamp of a session
void update_end_timestamp(session_t *session) {
    session->end_timestamp = time(NULL);
}

// Function to prune expired sessions based on configurable retention policies
void prune_sessions(struct hash_table *hash_table, int retention_policy) {
    // Iterate over the hash table and remove any sessions that have expired
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        session_t **current_session = hash_table->buckets[i];
        while (*current_session != NULL) {
            if ((*current_session)->end_timestamp == NULL ||
                time(NULL) - (*current_session)->end_timestamp > retention_policy) {
                session_t *to_remove = *current_session;
                *current_session = to_remove->next;
                free(to_remove);
            } else {
                current_session = &(*current_session)->next;
            }
        }
    }
}

// Function to log session details and events
void log_session(session_t *session) {
    // Log the session ID, start timestamp, end timestamp, and event list
    printf("Session %d: Started at %s, ended at %s\n", session->id, ctime(&session->start_timestamp), ctime(&session->end_timestamp));
    if (session->events != NULL) {
        event_t *current_event = session->events;
        while (current_event != NULL) {
            printf("Event %d: Type %d, timestamp %s, message '%s'\n", current_event->type, current_event->timestamp, ctime(&current_event->timestamp), current_event->message);
            current_event = current_event->next;
        }
    }
}

// Function to add a new session and event to the hash table
void add_session(struct hash_table *hash_table, int id, int type, char *message) {
    // Allocate memory for the new session node
    session_t *new_session = init_session(id);
    if (!new_session) {
        perror("Failed to allocate memory for new session");
        return;
    }

    // Add the new session node to the hash table
    int index = id % HASH_TABLE_SIZE;
    new_session->next = hash_table->buckets[index];
    hash_table->buckets[index] = new_session;

    // Add a new event to the session
    add_event(new_session, type, message);
}

// Function to retrieve a session by ID from the hash table
session_t *get_session(struct hash_table *hash_table, int id) {
    int index = id % HASH_TABLE_SIZE;
