    while (*current_session != NULL && (*current_session)->id != id) {
        current_session = &(*current_session)->next;
    }
    return *current_session;
}

// Function to update the end timestamp of a session and prune expired sessions based on configurable retention policies
void update_end_timestamp_and_prune(struct hash_table *hash_table, int retention_policy) {
    // Update the end timestamp of each session in the hash table
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        session_t **current_session = &hash_table->buckets[i];
        while (*current_session != NULL) {
            update_end_timestamp(*current_session);
            current_session = &(*current_session)->next;
        }
    }

    // Prune expired sessions based on configurable retention policies
