// Define a struct to represent a profile
typedef struct {
    char* name;
    int age;
    char* email;
    char** interests;
    time_t last_accessed;
} Profile;

// Define a hash table for storing profiles
typedef struct {
    Profile** buckets;
    size_t num_buckets;
    size_t num_profiles;
} ProfileHashTable;

// Initialize the hash table with a given number of buckets
void profile_hash_table_init(ProfileHashTable* table, size_t num_buckets) {
    table->num_buckets = num_buckets;
    table->num_profiles = 0;
    table->buckets = (Profile**)malloc(sizeof(Profile*) * num_buckets);
    for (size_t i = 0; i < num_buckets; i++) {
        table->buckets[i] = NULL;
    }
}

// Insert a new profile into the hash table
void profile_hash_table_insert(ProfileHashTable* table, Profile* profile) {
    size_t bucket_index = profile->email % table->num_buckets;
    if (table->buckets[bucket_index] == NULL) {
        // Create a new bucket if it doesn't exist yet
        table->buckets[bucket_index] = (Profile*)malloc(sizeof(Profile));
        memcpy(table->buckets[bucket_index], profile, sizeof(Profile));
    } else {
        // Collision resolution: chain the profiles together
        Profile* current = table->buckets[bucket_index];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = (Profile*)malloc(sizeof(Profile));
        memcpy(current->next, profile, sizeof(Profile));
    }
    table->num_profiles++;
}

// Delete a profile from the hash table
void profile_hash_table_delete(ProfileHashTable* table, Profile* profile) {
    size_t bucket_index = profile->email % table->num_buckets;
    if (table->buckets[bucket_index] == NULL) {
        // The profile doesn't exist in the hash table
        return;
    } else if (table->buckets[bucket_index] == profile) {
        // The profile is at the head of the bucket chain
        table->buckets[bucket_index] = profile->next;
    } else {
        // Find the previous node in the bucket chain
        Profile* current = table->buckets[bucket_index];
        while (current->next != NULL && current->next != profile) {
            current = current->next;
        }
        if (current->next == profile) {
            // The profile is in the middle or at the end of the bucket chain
            current->next = profile->next;
        } else {
            // The profile doesn't exist in the hash table
            return;
        }
    }
    table->num_profiles--;
}

// Retrieve a profile from the hash table by user ID
Profile* profile_hash_table_get(ProfileHashTable* table, int user_id) {
    size_t bucket_index = user_id % table->num_buckets;
    if (table->buckets[bucket_index] == NULL) {
        // The profile doesn't exist in the hash table
        return NULL;
    } else {
        Profile* current = table->buckets[bucket_index];
        while (current != NULL && current->user_id != user_id) {
            current = current->next;
        }
        if (current == NULL) {
            // The profile doesn't exist in the hash table
            return NULL;
        } else {
            // Return the retrieved profile
            return current;
        }
    }
}

// Retrieve a profile from the hash table by email address
Profile* profile_hash_table_get_by_email(ProfileHashTable* table, const char* email) {
    size_t bucket_index = strlen(email) % table->num_buckets;
    if (table->buckets[bucket_index] == NULL) {
        // The profile doesn't exist in the hash table
        return NULL;
    } else {
        Profile* current = table->buckets[bucket_index];
        while (current != NULL && strcmp(current->email, email) != 0) {
            current = current->next;
        }
        if (current == NULL) {
            // The profile doesn't exist in the hash table
            return NULL;
        } else {
            // Return the retrieved profile
            return current;
        }
    }
}

// Update a profile in the hash table
void profile_hash_table_update(ProfileHashTable* table, Profile* profile) {
    size_t bucket_index = profile->email % table->num_buckets;
    if (table->buckets[bucket_index] == NULL) {
        // The profile doesn't exist in the hash table
        return;
    } else if (table->buckets[bucket_index] == profile) {
        // The profile is at the head of the bucket chain
        memcpy(table->buckets[bucket_index], profile, sizeof(Profile));
    } else {
        // Find the previous node in the bucket chain
        Profile* current = table->buckets[bucket_index];
        while (current->next != NULL && current->next != profile) {
            current = current->next;
        }
        if (current->next == profile) {
            // The profile is in the middle or at the end of the bucket chain
            memcpy(current->next, profile, sizeof(Profile));
        } else {
            // The profile doesn't exist in the hash table
            return;
        }
    }
}

// Prune inactive profiles from the hash table
void profile_hash_table_prune(ProfileHashTable* table) {
    time_t current_time = time(NULL);
    for (size_t i = 0; i < table->num_buckets; i++) {
        Profile* current = table->buckets[i];
        while (current != NULL) {
            if (current->last_accessed + table->prune_threshold <= current_time) {
                // The profile is inactive and should be pruned
                Profile* next = current->next;
                free(current);
                table->num_profiles--;
                current = next;
            } else {
                // The profile is active, update its last access time
                current->last_accessed = current_time;
                current = current->next;
            }
        }
    }
}

// Clean up the hash table and free all memory
void profile_hash_table_destroy(ProfileHashTable* table) {
    for (size_t i = 0; i < table->num_buckets; i++) {
        Profile* current = table->buckets[i];
        while (current != NULL) {
            Profile* next = current->next;
            free(current);
            current = next;
        }
    }
    free(table->buckets);
}
