// Define a structure to hold the user profiles and additional data structures
typedef struct {
    char* email;
    int age;
    char** interests;
    long timestamp;
} profile_t;

// Define a hash table to store the user profiles
typedef struct {
    profile_t** profiles;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} profile_hash_table_t;

// Define a function to initialize the hash table
void init_profile_hash_table(profile_hash_table_t* table) {
    // Allocate memory for the hash table and its contents
    table->profiles = (profile_t**)malloc(sizeof(profile_t*) * 10);
    memset(table->profiles, 0, sizeof(profile_t*) * 10);
    table->capacity = 10;
    table->size = 0;
    pthread_mutex_init(&table->mutex, NULL);
}

// Define a function to insert a new profile into the hash table
void insert_profile(profile_hash_table_t* table, char* email, int age, char** interests) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&table->mutex);

    // Check if the profile already exists in the hash table
    for (int i = 0; i < table->size; i++) {
        if (strcmp(email, table->profiles[i]->email) == 0) {
            // Update the existing profile with the new information
            table->profiles[i]->age = age;
            table->profiles[i]->interests = interests;
            table->profiles[i]->timestamp = time(NULL);
            pthread_mutex_unlock(&table->mutex);
            return;
        }
    }

    // If the profile does not exist, create a new one and insert it into the hash table
    profile_t* new_profile = (profile_t*)malloc(sizeof(profile_t));
    new_profile->email = email;
    new_profile->age = age;
    new_profile->interests = interests;
    new_profile->timestamp = time(NULL);
    table->profiles[table->size++] = new_profile;

    // If the hash table is full, double its capacity and rehash all the profiles
    if (table->size == table->capacity) {
        profile_t** new_profiles = (profile_t**)malloc(sizeof(profile_t*) * 2 * table->capacity);
        memset(new_profiles, 0, sizeof(profile_t*) * 2 * table->capacity);
        for (int i = 0; i < table->size; i++) {
            new_profiles[i] = table->profiles[i];
        }
        free(table->profiles);
        table->profiles = new_profiles;
        table->capacity *= 2;
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&table->mutex);
}

// Define a function to delete a profile from the hash table
void delete_profile(profile_hash_table_t* table, char* email) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&table->mutex);

    // Find the profile with the given email address and remove it from the hash table
    for (int i = 0; i < table->size; i++) {
        if (strcmp(email, table->profiles[i]->email) == 0) {
            free(table->profiles[i]);
            table->profiles[i] = NULL;
            table->size--;
            break;
        }
    }

    // If the hash table is less than half full, shrink its capacity and rehash all the profiles
    if (table->size < table->capacity / 2) {
        profile_t** new_profiles = (profile_t**)malloc(sizeof(profile_t*) * table->capacity / 2);
        memset(new_profiles, 0, sizeof(profile_t*) * table->capacity / 2);
        for (int i = 0; i < table->size; i++) {
            new_profiles[i] = table->profiles[i];
        }
        free(table->profiles);
        table->profiles = new_profiles;
        table->capacity /= 2;
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&table->mutex);
}

