#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>

// Define the session structure
typedef struct {
    int id;
    time_t start_time;
    time_t end_time;
    struct event *events;
} session_t;

// Define the event structure
typedef struct {
    int type;
    time_t timestamp;
    char *message;
} event_t;

// Define the hash table for quick key-based lookups
#define HASH_TABLE_SIZE 1024
struct hash_table {
    session_t **buckets;
};

// Function to initialize a new session
session_t *init_session(int id) {
    session_t *new_session = malloc(sizeof(session_t));
    if (!new_session) {
        // Handle memory allocation failure gracefully
        return NULL;
    }
    new_session->id = id;
    new_session->start_time = time(NULL);
    new_session->end_time = NULL;
    new_session->events = NULL;
    return new_session;
}

// Function to add a new event to a session
void add_event(session_t *session, int type, char *message) {
    // Allocate memory for the new event node
    event_t *new_event = malloc(sizeof(event_t));
    if (!new_event) {
        // Handle memory allocation failure gracefully
        return;
    }
    new_event->type = type;
    new_event->timestamp = time(NULL);
    new_event->message = message;

    // Add the new event to the session's linked list of events
    if (session->events == NULL) {
        session->events = new_event;
    } else {
        event_t *current_event = session->events;
        while (current_event->next != NULL) {
            current_event = current_event->next;
        }
        current_event->next = new_event;
    }
}

// Function to retrieve a session by ID
session_t *get_session(int id) {
    // Use the hash table to quickly look up the session by ID
    struct hash_table *hash_table = get_hash_table();
    int bucket_index = id % HASH_TABLE_SIZE;
    if (hash_table->buckets[bucket_index] == NULL) {
        return NULL;
    } else {
        session_t *current_session = hash_table->buckets[bucket_index];
        while (current_session != NULL && current_session->id != id) {
            current_session = current_session->next;
        }
        return current_session;
    }
}

// Function to update the session end time when an event is added
void update_end_time(session_t *session) {
    // Update the session's end time to the current system time
    session->end_time = time(NULL);
}

// Function to calculate and print the mean and standard deviation of an array of floating-point numbers
void calculate_mean_stddev(float *array, int size) {
    // Calculate the mean and standard deviation of the array
    float sum = 0;
    for (int i = 0; i < size; i++) {
        sum += array[i];
    }
    float mean = sum / size;
    float variance = 0;
    for (int i = 0; i < size; i++) {
        variance += pow(array[i] - mean, 2);
    }
    variance /= size - 1;
    float stddev = sqrt(variance);

    // Print the results
    printf("Mean: %f\n", mean);
    printf("Standard Deviation: %f\n", stddev);
}

// Function to deallocate all resources upon completion
void cleanup() {
    // Free the hash table and all of its buckets
    struct hash_table *hash_table = get_hash_table();
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        session_t *current_session = hash_table->buckets[i];
        while (current_session != NULL) {
            event_t *current_event = current_session->events;
            while (current_event != NULL) {
                free(current_event);
                current_event = current_event->next;
            }
            free(current_session);
            current_session = hash_table->buckets[i];
        }
    }
    free(hash_table);
}
