        printf("Error: Could not initialize cipher context\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Allocate memory for the decrypted plaintext and set its length to the ciphertext's length
    unsigned char *plaintext = (unsigned char *)malloc(strlen(ciphertext) + 1);
    len = strlen(ciphertext);

    // Decrypt the ciphertext using AES-CBC and return the decrypted plaintext as a byte array
    if (EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, strlen(ciphertext)) <= 0) {
        printf("Error: Could not decrypt ciphertext\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    if (EVP_DecryptFinal_ex(ctx, plaintext + len, &len) <= 0) {
        printf("Error: Could not finalize decryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    EVP_CIPHER_CTX_free(ctx);
    return plaintext;
}
