// Define the balanced binary tree for ordered access and efficient range queries on SKU and expiration date attributes
typedef struct {
    Product *products;
    size_t capacity;
    size_t count;
} BalancedBinaryTree;

// Define the inventory system structure
typedef struct {
    HashTable *hash_table;
    BalancedBinaryTree *balanced_binary_tree;
    int num_warehouses;
    int current_warehouse;
} InventorySystem;

// Initialize the inventory system
void init_inventory_system(InventorySystem *inv) {
    inv->hash_table = (HashTable *)malloc(sizeof(HashTable));
    inv->balanced_binary_tree = (BalancedBinaryTree *)malloc(sizeof(BalancedBinaryTree));
    inv->num_warehouses = 0;
    inv->current_warehouse = -1;
}

// Add a product to the inventory system
void add_product(InventorySystem *inv, Product *product) {
    // Check if the product already exists in the hash table
    HashTable *hash_table = inv->hash_table;
    size_t index = hash_table->capacity - 1;
    while (index >= 0 && strcmp(hash_table->products[index].sku, product->sku) != 0) {
        index--;
    }
    if (index < 0) {
        // Product does not exist in the hash table, add it
        size_t new_index = hash_table->count++;
        strcpy(hash_table->products[new_index].sku, product->sku);
        strcpy(hash_table->products[new_index].category, product->category);
        strcpy(hash_table->products[new_index].manufacturer, product->manufacturer);
        hash_table->products[new_index].expiration_date = product->expiration_date;
        hash_table->products[new_index].stock_level = product->stock_level;
    } else {
        // Product already exists in the hash table, update its stock level
        hash_table->products[index].stock_level += product->stock_level;
    }
}

// Retrieve a product from the inventory system
Product *get_product(InventorySystem *inv, char *sku) {
    // Check if the product exists in the hash table
    HashTable *hash_table = inv->hash_table;
    size_t index = hash_table->capacity - 1;
    while (index >= 0 && strcmp(hash_table->products[index].sku, sku) != 0) {
        index--;
    }
    if (index < 0) {
        // Product does not exist in the hash table, return NULL
        return NULL;
    } else {
        // Product exists in the hash table, return its pointer
        return &hash_table->products[index];
    }
}

// Update a product's stock level in the inventory system
void update_stock_level(InventorySystem *inv, char *sku, int new_stock_level) {
    // Check if the product exists in the hash table
    HashTable *hash_table = inv->hash_table;
    size_t index = hash_table->capacity - 1;
    while (index >= 0 && strcmp(hash_table->products[index].sku, sku) != 0) {
        index--;
    }
    if (index < 0) {
        // Product does not exist in the hash table, return NULL
        return;
    } else {
        // Product exists in the hash table, update its stock level
        hash_table->products[index].stock_level = new_stock_level;
    }
}

