#include <errno.h>

// Structure to store network configuration parameters
typedef struct {
    char *ip_address;
    char *subnet_mask;
    char *gateway;
    char *dns_server;
    int dhcp_enabled;
    int ipv6_preferred;
} NetworkConfig;

// Function to configure network settings for a distributed system with multiple network interfaces
void configureNetworkSettings(NetworkConfig config) {
    // Initialize hash tables for storing IP addresses, subnet masks, and gateway/DNS server mappings
    struct hash_table *ip_addresses = create_hash_table();
    struct hash_table *subnet_masks = create_hash_table();
    struct hash_table *gateway_dns_servers = create_hash_table();

    // Allocate memory for the hash tables and populate them with random values
    allocate_memory(ip_addresses, subnet_masks, gateway_dns_servers);

    // Serialize access to shared resources to prevent concurrent modification issues
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // Handle potential memory allocation failures gracefully
    if (ip_addresses == NULL || subnet_masks == NULL || gateway_dns_servers == NULL) {
        printf("Memory allocation failed. Using default network settings.\n");
        return;
    }

    // Initialize network interfaces and configure IP addresses, subnet masks, and gateway/DNS servers
    for (int i = 0; i < config.num_interfaces; i++) {
        struct ifreq interface;
        strcpy(interface.ifr_name, "eth0"); // Replace with actual interface name
        ioctl(interface.ifr_name, SIOCGIFADDR, &interface);
        ioctl(interface.ifr_name, SIOCGIFNETMASK, &interface);
        ioctl(interface.ifr_name, SIOCGIFDSTADDR, &interface);

        // Set IP address, subnet mask, and gateway/DNS server based on configuration parameters
        if (config.ipv6_preferred) {
            struct in6_addr *ipv6_address = (struct in6_addr *)&interface.ifr_addr;
            char ipv6_address_str[INET6_ADDRSTRLEN];
            inet_ntop(AF_INET6, ipv6_address, ipv6_address_str, INET6_ADDRSTRLEN);
            printf("IPv6 address: %s\n", ipv6_address_str);
        } else {
            struct in_addr *ipv4_address = (struct in_addr *)&interface.ifr_addr;
            char ipv4_address_str[INET_ADDRSTRLEN];
            inet_ntop(AF_INET, ipv4_address, ipv4_address_str, INET_ADDRSTRLEN);
            printf("IPv4 address: %s\n", ipv4_address_str);
        }

        // Set subnet mask based on configuration parameters
        struct in_addr *subnet_mask = (struct in_addr *)&interface.ifr_netmask;
        char subnet_mask_str[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, subnet_mask, subnet_mask_str, INET_ADDRSTRLEN);
        printf("Subnet mask: %s\n", subnet_mask_str);

        // Set gateway and DNS server based on configuration parameters
        struct in_addr *gateway = (struct in_addr *)&interface.ifr_dstaddr;
        char gateway_str[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, gateway, gateway_str, INET_ADDRSTRLEN);
