    for (int i = 0; i < subnet_masks->size; i++) {
        struct bucket *bucket = &subnet_masks->buckets[i];
        bucket->key = malloc(sizeof(struct in_addr));
        if (bucket->key == NULL) {
            free(bucket);
            continue;
        }
        memset(bucket->key, 0, sizeof(struct in_addr));
        bucket->value = malloc(sizeof(struct in_addr));
        if (bucket->value == NULL) {
            free(bucket->key);
            free(bucket);
            continue;
        }
        memset(bucket->value, 0, sizeof(struct in_addr));
    }

    for (int i = 0; i < gateway_dns_servers->size; i++) {
        struct bucket *bucket = &gateway_dns_servers->buckets[i];
        bucket->key = malloc(sizeof(struct in_addr));
        if (bucket->key == NULL) {
