['```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

// Define the data container structure
typedef struct {
    int *offsets;
    char **keys;
    int *records;
} DataContainer;

// Define the memory pool structure
typedef struct {
    void *memory_pool;
    size_t memory_size;
    size_t used_memory;
    pthread_mutex_t lock;
} MemoryPool;

// Define the Union-Find data structure
typedef struct {
    int *parent;
    int *rank;
} UnionFind;

// Initialize the memory pool
void init_memory_pool(MemoryPool *pool) {
    pool->memory_pool = mmap(NULL, pool->memory_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (pool->memory_pool == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    pool->used_memory = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

// Allocate memory from the memory pool
void *allocate_memory(MemoryPool *pool, size_t size) {
    void *ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_lock(&pool->lock);
    pool->used_memory += size;
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

// Release memory from the memory pool
void release_memory(MemoryPool *pool, void *ptr) {
    munmap(ptr, 0);
    pthread_mutex_lock(&pool->lock);
    pool->used_memory -= size;
    pthread_mutex_unlock(&pool->lock);
}

// Initialize the data container
void initialize_data_container(DataContainer *container, int num_keys, int num_records, char **keys, int *records) {
    // Allocate memory for the offsets array
    size_t offset_size = sizeof(int) * (num_keys + 1);
    container->offsets = allocate_memory(offset_size);

    // Initialize the offsets array
    int i;
    for (i = 0; i < num_keys + 1; i++) {
        container->offsets[i] = i * sizeof(int);
    }

    // Allocate memory for the keys array
    size_t key_size = sizeof(char *) * num_keys;
    container->keys = allocate_memory(key_size);

    // Initialize the keys array
    for (i = 0; i < num_keys; i++) {
        container->keys[i] = strdup(keys[i]);
    }

    // Allocate memory for the records array
    size_t record_size = sizeof(int) * num_records;
    container->records = allocate_memory(record_size);

    // Initialize the records array with random integer values within a specified range
    srand(time(NULL));
    for (i = 0; i < num_records; i++) {
        container->records[i] = rand() % 100;
    }
}

// Initialize the Union-Find data structure
void initialize_union_find(UnionFind *uf, int num_keys) {
    // Allocate memory for the parent and rank arrays
    size_t parent_size = sizeof(int) * num_keys;
    uf->parent = allocate_memory(parent_size);
    size_t rank_size = sizeof(int) * num_keys;
    uf->rank = allocate_memory(rank_size);

    // Initialize the parent and rank arrays
    int i;
    for (i = 0; i < num_keys; i++) {
        uf->parent[i] = i;
        uf->rank[i] = 1;
    }
}

// Check if two keys are disjoint
int is_disjoint(UnionFind *uf, int key1, int key2) {
    return uf->parent[key1] != uf->parent[key2];
}

// Union two keys
void union_keys(UnionFind *uf, int key1, int key2) {
    // Find the roots of the two keys
    int root1 = find_root(uf, key1);
    int root2 = find_root(uf, key2);

    // If the two keys are already disjoint, return
    if (root1 == root2) {
        return;
    }

    // Make the rank of the smaller tree larger than the rank of the larger tree
    if (uf->rank[root1] < uf->rank[root2]) {
        uf->parent[root1] = root2;
    } else {
        uf->parent[root2] = root1;
        if (uf->rank[root1] == uf->rank[root2]) {
            uf->rank[root1]++;
        }
    }
}

// Find the root of a key
int find_root(UnionFind *uf, int key) {
    // If the key is already the root, return it
    if (uf->parent[key] == key) {
        return key;
    }

    // Recursively find the root of the parent
    uf->parent[key] = find_root(uf, uf->parent[key]);
    return uf->parent[key];
}

// Free the memory allocated for the data container and Union-Find data structure
void free_memory(DataContainer *container) {
    // Release the memory allocated for the offsets array
    release_memory(&container->offsets);

    // Release the memory allocated for the keys array
    int i;
