output_container* process_and_filter_data(const char* filepath, const double min_value, const double max_value, const time_t min_timestamp, const time_t max_timestamp, const bool zero_initialize_timestamps, const bool randomize_values) {
    // Check if the file path is valid
    if (filepath == NULL || strlen(filepath) == 0) {
        return NULL;
    }

    // Open the file and check for errors
    FILE* fp = fopen(filepath, "r");
    if (fp == NULL) {
        perror("Error opening file");
        return NULL;
    }

    // Read the number of records in the file
    int num_records = 0;
    while (!feof(fp)) {
        data_record record;
        if (fread(&record, sizeof(data_record), 1, fp) != 1) {
            break;
        }
        num_records++;
    }

    // Allocate memory for the output container
    output_container* output = malloc(sizeof(output_container));
    if (output == NULL) {
        perror("Error allocating memory for output container");
        fclose(fp);
        return NULL;
    }

    // Allocate memory for the IDs, timestamps, and filtered records arrays
    int* ids = malloc(num_records * sizeof(int));
    time_t* timestamps = malloc(num_records * sizeof(time_t));
    data_record* filtered_records = malloc(num_records * sizeof(data_record));
    if (ids == NULL || timestamps == NULL || filtered_records == NULL) {
        perror("Error allocating memory for arrays");
        free(output);
        fclose(fp);
        return NULL;
    }

    // Initialize the output container with the allocated memory
    output->ids = ids;
    output->timestamps = timestamps;
    output->filtered_records = filtered_records;

    // Read the records from the file and filter them based on the criteria
    int num_filtered_records = 0;
    rewind(fp);
    while (!feof(fp)) {
        data_record record;
        if (fread(&record, sizeof(data_record), 1, fp) != 1) {
            break;
        }

        // Check if the record is within the specified time range and value threshold
        if (record.timestamp >= min_timestamp && record.timestamp <= max_timestamp && record.value >= min_value && record.value <= max_value) {
            // Add the record to the filtered records array
            output->filtered_records[num_filtered_records] = record;

            // Add the ID and timestamp to the corresponding arrays
            output->ids[num_filtered_records] = record.id;
            output->timestamps[num_filtered_records] = record.timestamp;

            num_filtered_records++;
        }
    }

    // Close the file and free any allocated memory if an error occurred
    fclose(fp);
    if (output == NULL) {
        free(ids);
        free(timestamps);
        free(filtered_records);
    }

    return output;
}
