import java.security.MessageDigest;
import java.util.concurrent.ConcurrentHashMap;

public class MD5Hash {
    private static final ConcurrentHashMap<String, String> hashes = new ConcurrentHashMap<>();

    public static String getMD5Hash(String input) {
        // Check if the hash is already computed and stored in the map
        String hash = hashes.get(input);
        if (hash != null) {
            return hash;
        }

        // Compute the hash using MessageDigest
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] bytes = input.getBytes();
            md.update(bytes, 0, bytes.length);
            hash = new String(md.digest());
        } catch (NoSuchAlgorithmException e) {
            // Handle the exception
        }

        // Store the hash in the map for future use
        hashes.put(input, hash);

        return hash;
    }
}
