// Structure to represent a record with an offset and key
typedef struct {
    long *offset;
    int *key;
    int refCount;
} Record;

// Function to dynamically allocate memory for the arrays
Record* initArrays(int numOffsets, int numKeys) {
    // Allocate memory for the offset and key arrays
    long *offsets = malloc(numOffsets * sizeof(long));
    int *keys = malloc(numKeys * sizeof(int));

    // Initialize the reference counters to zero
    Record *records = malloc(numOffsets * numKeys * sizeof(Record));
    for (int i = 0; i < numOffsets * numKeys; i++) {
        records[i].refCount = 0;
    }

    // Read the configuration file and populate the arrays
    FILE *file = fopen("config.txt", "r");
    if (file == NULL) {
        printf("Error: unable to open config file\n");
        return NULL;
    }

    int i = 0, j = 0;
    while (fscanf(file, "%ld %d", &offsets[i], &keys[j]) == 2) {
        records[i * numKeys + j].offset = offsets + i;
        records[i * numKeys + j].key = keys + j;
        records[i * numKeys + j].refCount++;
        i++;
        if (i >= numOffsets) {
            break;
        }
        j++;
    }

    // Close the file and free memory
    fclose(file);
    free(offsets);
    free(keys);

    return records;
}

// Function to set a random value within a given range for each record's int field
void setRandomValues(Record *records, int numRecords, int minValue, int maxValue) {
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        records[i].key = rand() % (maxValue - minValue + 1) + minValue;
    }
}

// Function to clean up allocated memory
void freeArrays(Record *records, int numOffsets, int numKeys) {
    free(records);
}
```
This code defines a `Record` structure that contains a pointer to a `long` integer (`offset`) and a pointer to an `int` integer (`key`), as well as a reference counter (`refCount`). The `initArrays` function dynamically allocates memory for the arrays of offsets and keys, initializes the reference counters to zero, reads the configuration file and populates the arrays with the values read from it, and returns a pointer to the dynamically allocated `Record` array.

The `setRandomValues` function sets a random value within a given range for each record's `int` field using the `rand()` function and the `time()` function to generate a seed. The `freeArrays` function frees the memory allocated by the `initArrays` function.

Note that this code assumes that the configuration file is in the same directory as the executable, and that it contains pairs of long and int values separated by a space on each line. If the file does not exist or cannot be opened, the function will handle this gracefully by logging an error message and returning `NULL`.']

