char *process_string(char *string, int limit) {
    // Check if the string is longer than the limit
    if (strlen(string) > limit) {
        return NULL;
    }

    // Append a slash to the end of the string
    char *processed = malloc(sizeof(char) * (limit + 1));
    strcpy(processed, string);
    processed[strlen(string)] = '/';
    processed[strlen(string) + 1] = '\0';

    return processed;
}

