    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
    pthread_create(&mutex, &cond);
    pthread_join(mutex, &cond);

    return records;
}

// Function to update the reference counters for each record
void updateRefCounts(Record *records, int numRecords) {
    // Acquire a lock on the mutex before updating the reference counters
    pthread_mutex_lock(&mutex);

    // Increment the reference counter for each record that is accessed
    for (int i = 0; i < numRecords; i++) {
        records[i].refCount++;
    }

    // Release the lock on the mutex after updating the reference counters
    pthread_mutex_unlock(&mutex);
}

// Function to query the current state of the offsets, keys, and record arrays
void queryState(Record *records, int numRecords) {
    // Acquire a lock on the mutex before accessing the records
    pthread_mutex_lock(&mutex);

    // Print the most recent access times for each record
    for (int i = 0; i < numRecords; i++) {
        printf("Record %d: Accessed at %s\n", i, ctime(&records[i].refCount));
    }

    // Release the lock on the mutex after accessing the records
    pthread_mutex_unlock(&mutex);
}

// Function to periodically check for changes in the configuration file and update the offsets and keys arrays accordingly
void backgroundProcess(Record *records, int numRecords) {
    // Acquire a lock on the mutex before updating the records
    pthread_mutex_lock(&mutex);

    // Check if the configuration file has changed since the last update
    FILE *configFile = fopen("config.txt", "r");
