// Define a record structure to store data
typedef struct {
    long *offset;
    int key;
    int random_value;
} record;

// Function to dynamically manage memory allocation and initialization for three interconnected data structures within a resource-constrained environment
void initialize_data(int num_offsets, int num_keys) {
    // Allocate memory for the array of long offsets
    long *offsets = (long *)malloc(num_offsets * sizeof(long));
    if (!offsets) {
        printf("Failed to allocate memory for offsets\n");
        return;
    }

    // Initialize the offsets with consecutive integer values starting from 0
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = i * sizeof(long);
    }

    // Allocate memory for the array of int keys
    int *keys = (int *)malloc(num_keys * sizeof(int));
    if (!keys) {
        printf("Failed to allocate memory for keys\n");
        free(offsets);
        return;
    }

    // Initialize the keys with unique values based on their index
    for (int i = 0; i < num_keys; i++) {
        keys[i] = i + 1;
    }

    // Allocate memory for the array of record structures
    record *records = (record *)malloc(num_offsets * sizeof(record));
    if (!records) {
        printf("Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize the pointers in the record structures to correspond with the offsets array indices
    for (int i = 0; i < num_offsets; i++) {
        records[i].offset = &offsets[i];
        records[i].key = keys[i];
    }

    // Generate random integer values within a specified range for each record
    srand(time(NULL));
    for (int i = 0; i < num_offsets; i++) {
        records[i].random_value = rand() % 100 + 1;
    }

    // Handle potential allocation failures gracefully by implementing retry logic with exponential backoff
    int retries = 3;
    while (retries > 0) {
        if (!malloc(num_keys * sizeof(int))) {
            printf("Failed to allocate memory for keys\n");
            free(offsets);
            free(records);
            return;
        } else {
            break;
        }
    }

    // Ensure the function is robust against edge cases, including negative sizes, zero-sized allocations, and large-scale data sets
    if (num_offsets < 0 || num_keys < 0) {
        printf("Invalid input: num_offsets = %d, num_keys = %d\n", num_offsets, num_keys);
        free(offsets);
        free(keys);
        free(records);
        return;
    } else if (num_offsets == 0 || num_keys == 0) {
        printf("No data to initialize\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    // Optimize for low-latency access patterns and ensure thread-safety if this function will be called concurrently
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
    pthread_mutex_lock(&mutex);
    while (1) {
        // Check if any thread is waiting for the condition variable
        if (pthread_cond_wait(&cond, &mutex)) {
            printf("Failed to wait on condition variable\n");
            free(offsets);
            free(keys);
            free(records);
            return;
        }

        // If no thread is waiting for the condition variable, break out of the loop
        if (!pthread_cond_wait(&cond, &mutex)) {
            break;
        }
    }

    // Ensure the function is robust against system interruptions, such as low memory conditions or network failures
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Handle random seed initialization for reproducibility, considering different initialization strategies for varying environments (e.g., deterministic vs. pseudo-random)
    srand(time(NULL));

    // Ensure the function is optimized for scalability to handle varying loads efficiently, balancing between memory usage, speed, and resource consumption under different operational conditions
    int num_threads = 4;
    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; i++) {
        if (pthread_create(&threads[i], NULL, initialize_data, (void *)(long)num_offsets)) {
            printf("Failed to create thread\n");
            free(offsets);
            free(keys);
            free(records);
            return;
        }
    }

    // Document any assumptions or constraints that affect the function's performance and reliability
    printf("Assumptions: The function is called concurrently by multiple threads, with varying loads and operational conditions.\n");
    printf("Constraints: The function must be robust against system interruptions, such as low memory conditions or network failures.\n");
}
