#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

// Define a structure to represent a transaction
typedef struct {
    long timestamp;
    double amount;
    char currency[3];
} transaction_t;

// Function to dynamically allocate memory for an array of transactions
transaction_t* allocate_transactions(int num_transactions) {
    // Allocate memory for the array of transactions
    transaction_t* transactions = (transaction_t*)malloc(num_transactions * sizeof(transaction_t));
    if (!transactions) {
        fprintf(stderr, "Error: Failed to allocate memory for %d transactions\n", num_transactions);
        return NULL;
    }

    // Initialize each transaction in the array
    for (int i = 0; i < num_transactions; i++) {
        transactions[i].timestamp = 0;
        transactions[i].amount = 0.0;
        strcpy(transactions[i].currency, "");
    }

    return transactions;
}

// Function to read transactions from a local file
int read_local_file(const char* filename, transaction_t** transactions) {
    // Open the file for reading
    FILE* fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open file %s\n", filename);
        return -1;
    }

    // Read the number of transactions in the file
    int num_transactions = 0;
    if (fscanf(fp, "%d", &num_transactions) != 1) {
        fprintf(stderr, "Error: Failed to read number of transactions from %s\n", filename);
        return -1;
    }

    // Allocate memory for the array of transactions
    *transactions = allocate_transactions(num_transactions);
    if (!*transactions) {
        fprintf(stderr, "Error: Failed to allocate memory for %d transactions\n", num_transactions);
        return -1;
    }

    // Read each transaction from the file and validate it
    for (int i = 0; i < num_transactions; i++) {
        if (fscanf(fp, "%ld %lf %s", &(*transactions)[i].timestamp, &(*transactions)[i].amount, (*transactions)[i].currency) != 3) {
            fprintf(stderr, "Error: Failed to read transaction %d from %s\n", i + 1, filename);
            return -1;
        }

        // Validate the transaction by checking its format and business rules
        if ((*transactions)[i].timestamp < 0 || (*transactions)[i].amount <= 0.0 || strlen((*transactions)[i].currency) != 3) {
            fprintf(stderr, "Error: Invalid transaction %d in file %s\n", i + 1, filename);
            return -1;
        }
    }

    // Close the file
    fclose(fp);

    return num_transactions;
}

// Function to read transactions from a network stream
int read_network_stream(const char* hostname, int port, transaction_t** transactions) {
    // Open a connection to the server
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        fprintf(stderr, "Error: Failed to resolve hostname %s\n", hostname);
        return -1;
    }

    // Connect to the server
    int sock = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (connect(sock, res->ai_addr, res->ai_addrlen) != 0) {
        fprintf(stderr, "Error: Failed to connect to %s:%d\n", hostname, port);
        return -1;
    }

    // Read the number of transactions from the server
    int num_transactions = 0;
    if (recv(sock, &num_transactions, sizeof(int), MSG_WAITALL) != sizeof(int)) {
        fprintf(stderr, "Error: Failed to read number of transactions from %s:%d\n", hostname, port);
        return -1;
    }

    // Allocate memory for the array of transactions
    *transactions = allocate_transactions(num_transactions);
    if (!*transactions) {
        fprintf(stderr, "Error: Failed to allocate memory for %d transactions\n", num_transactions);
        return -1;
    }

    // Read each transaction from the server and validate it
    for (int i = 0; i < num_transactions; i++) {
        if (recv(sock, &(*transactions)[i].timestamp, sizeof(long), MSG_WAITALL) != sizeof(long)) {
            fprintf(stderr, "Error: Failed to read transaction %d from %s:%d\n", i + 1, hostname, port);
            return -1;
        }
        if (recv(sock, &(*transactions)[i].amount, sizeof(double), MSG_WAITALL) != sizeof(double)) {
            fprintf(stderr, "Error: Failed to read transaction %d from %s:%d\n", i + 1, hostname, port);
            return -1;
        }
        if (recv(sock, (*transactions)[i].currency, sizeof((*transactions)[i].currency), MSG_WAITALL) != sizeof((*transactions)[i].currency)) {
            fprintf(stderr, "Error: Failed to read transaction %d from %s:%d\n", i + 1, hostname, port);
            return -1;
        }

        // Validate the transaction by checking its format and business rules
        if ((*transactions)[i].timestamp < 0 || (*transactions)[i].amount <= 0.0 || strlen((*transactions)[i].currency) != 3) {
            fprintf(stderr, "Error: Invalid transaction %d from %s:%d\n", i + 1, hostname, port);
            return -1;
        }
    }

    // Close the connection to the server
    close(sock);

    return num_transactions;
}

// Function to read transactions from an in-memory data buffer
int read_in_memory_buffer(const char* buffer, transaction_t** transactions) {
    // Allocate memory for the array of transactions
    *transactions = allocate_transactions(10);
    if (!*transactions) {
        fprintf(stderr, "Error: Failed to allocate memory for 10 transactions\n");
        return -1;
    }

    // Read each transaction from the buffer and validate it
    int num_transactions = 0;
    while (num_transactions < 10) {
        if (sscanf(buffer, "%ld %lf %s", &(*transactions)[num_transactions].timestamp, &(*transactions)[num_transactions].amount, (*transactions)[num_transactions].currency) != 3) {
            fprintf(stderr, "Error: Failed to read transaction %d from buffer\n", num_transactions + 1);
            return -1;
        }

        // Validate the transaction by checking its format and business rules
        if ((*transactions)[num_transactions].timestamp < 0 || (*transactions)[num_transactions].amount <= 0.0 || strlen((*transactions)[num_transactions].currency) != 3) {
            fprintf(stderr, "Error: Invalid transaction %d from buffer\n", num_transactions + 1);
            return -1;
        }

        // Increment the number of transactions and move to the next one in the buffer
        num_transactions++;
        while (*buffer != '\0' && *buffer != '\n') {
            buffer++;
        }
        if (*buffer == '\0') {
            break;
        }
        buffer++;
    }

    return num_transactions;
}

// Function to process transactions and calculate statistics
void process_transactions(transaction_t* transactions, int num_transactions) {
    // Calculate the total amount processed
    double total_amount = 0.0;
    for (int i = 0; i < num_transactions; i++) {
        total_amount += transactions[i].amount;
    }

    // Calculate the average amount processed
    double average_amount = total_amount / num_transactions;

    // Print the statistics
    printf("Total amount processed: %.2f\n", total_amount);
    printf("Average amount processed: %.2f\n", average_amount);
}

int main() {
    // Read transactions from a local file
    transaction_t* transactions = NULL;
    int num_transactions = read_local_file("transactions.txt", &transactions);
    if (num_transactions < 0) {
        fprintf(stderr, "Error: Failed to read transactions from file\n");
        return -1;
    }

    // Read transactions from a network stream
    num_transactions = read_network_stream("localhost", 8080, &transactions);
    if (num_transactions < 0) {
        fprintf(stderr, "Error: Failed to read transactions from network stream\n");
        return -1;
    }

    // Read transactions from an in-memory data buffer
    num_transactions = read_in_memory_buffer("1234567890 10.5 USD\n1234567890 20.5 USD\n", &transactions);
    if (num_transactions < 0) {
        fprintf(stderr, "Error: Failed to read transactions from in-memory buffer\n");
        return -1;
    }

    // Process the transactions and calculate statistics
    process_transactions(transactions, num_transactions);

    // Free the memory allocated for the array of transactions
    free(transactions);

    return 0;
}
