    (*records)[*size - 1].key = 1;
    (*records)[*size - 1].value = 20;

    // Resolve the collision by adding a new record with a unique key and value
    resolve_collisions(records, capacity, size);
    (*records)[*size - 1].key = 2;
    (*records)[*size - 1].value = 30;
}
