// Define balanced binary tree for quick key-based lookups
typedef struct node {
    int key;
    data_point *value;
    struct node *left, *right;
} node;

// Function to dynamically manage collection of data points
void manage_data_points(node **root) {
    // Insert new data point into balanced binary tree
    void insert_data_point(node **root, int key, data_point *value) {
        if (*root == NULL) {
            *root = malloc(sizeof(node));
            (*root)->key = key;
            (*root)->value = value;
            (*root)->left = NULL;
            (*root)->right = NULL;
        } else if (key < (*root)->key) {
            insert_data_point(&(*root)->left, key, value);
        } else if (key > (*root)->key) {
            insert_data_point(&(*root)->right, key, value);
        }
    }

    // Delete data point from balanced binary tree
    void delete_data_point(node **root, int key) {
        if (*root == NULL) return;
        else if (key < (*root)->key) delete_data_point(&(*root)->left, key);
        else if (key > (*root)->key) delete_data_point(&(*root)->right, key);
        else {
            node *temp = *root;
            *root = NULL;
            free(temp);
        }
    }

