            traverse_data_points(&(*root)->right);
        }
    }

    // Periodically prune outdated entries from balanced binary tree
    void prune_outdated_entries(node **root) {
        if (*root == NULL) return;
        else if ((*root)->value->timestamp < time(NULL)) {
            delete_data_point(root, (*root)->key);
            prune_outdated_entries(root);
        } else {
            prune_outdated_entries(&(*root)->left);
            prune_outdated_entries(&(*root)->right);
        }
    }

    // Export data points to file in specified format
    void export_data_points(node **root, char *file_name, int export_format) {
        if (export_format == 0) { // Binary export
            FILE *fp = fopen(file_name, "wb");
            if (fp == NULL) {
                printf("Error: Could not open file for writing.\n");
                return;
            }
            traverse_data_points(root);
            fclose(fp);
        } else if (export_format == 1) { // Text export
            FILE *fp = fopen(file_name, "w");
            if (fp == NULL) {
                printf("Error: Could not open file for writing.\n");
                return;
            }
            traverse_data_points(root);
            fclose(fp);
        } else {
            printf("Error: Invalid export format specified.\n");
            return;
        }
    }
}

