    strcpy(value->location, location);
    value->identifier = identifier;
    value->timestamp = timestamp;
    value->accuracy = accuracy;
    insert_data_point(root, key, value);
}

void get_data_point(node **root, int key) {
    if (*root == NULL) {
        printf("Error: Data point with key %d does not exist.\n", key);
        return;
