        printf("%d: %f, %s, %d, %llu, %f\n", (*root)->key, (*root)->value->temperature, (*root)->value->location, (*root)->value->identifier, (*root)->value->timestamp, (*root)->value->accuracy);
    } else if (key < (*root)->key) {
        get_data_point(&(*root)->left, key);
    } else if (key > (*root)->key) {
        get_data_point(&(*root)->right, key);
    }
}

// Mechanisms for periodic memory management to optimize resource usage and prevent fragmentation
void manage_memory(node **root) {
