            left_right_rotate(root);
        } else if (balance < 0) {
            right_left_rotate(root);
        }
    }
}

// Get balance factor of balanced binary tree
int get_balance(node **root) {
    if (*root == NULL) return 0;
    else return height((*root)->right) - height((*root)->left);
}

// Left rotation of balanced binary tree
void left_rotate(node **root) {
    node *temp = (*root)->right;
    (*root)->right = temp->left;
    temp->left = *root;
    *root = temp;
}

// Right rotation of balanced binary tree
void right_rotate(node **root) {
    node *temp = (*root)->left;
    (*root)->left = temp->right;
    temp->right = *root;
    *root = temp;
}

// Left-right rotation of balanced binary tree
void left_right_rotate(node **root) {
    right_rotate(&(*root)->left);
    left_rotate(root);
}

// Right-left rotation of balanced binary tree
void right_left_rotate(node **root) {
    left_rotate(&(*root)->right);
    right_rotate(root);
}

