// Define a linked list node for storing transactions
struct TransactionNode {
    struct Transaction *transaction;
    struct TransactionNode *next;
};

// Define a hash table to store transactions by ID
struct HashTable {
    int size;
    struct TransactionNode **buckets;
};

// Function to create a new transaction node
struct TransactionNode* createTransactionNode(struct Transaction *transaction) {
    struct TransactionNode *node = malloc(sizeof(struct TransactionNode));
    if (node == NULL) {
        printf("Error: Failed to allocate memory for transaction node\n");
        return NULL;
    }
    node->transaction = transaction;
    node->next = NULL;
    return node;
}

// Function to create a new hash table with the given size
struct HashTable* createHashTable(int size) {
    struct HashTable *hash_table = malloc(sizeof(struct HashTable));
    if (hash_table == NULL) {
        printf("Error: Failed to allocate memory for hash table\n");
        return NULL;
    }
    hash_table->size = size;
    hash_table->buckets = calloc(size, sizeof(struct TransactionNode*));
    if (hash_table->buckets == NULL) {
        printf("Error: Failed to allocate memory for hash table buckets\n");
        free(hash_table);
        return NULL;
    }
    return hash_table;
}

// Function to insert a transaction into the hash table
int insertTransaction(struct HashTable *hash_table, struct Transaction *transaction) {
    int index = transaction->id % hash_table->size;
    struct TransactionNode *node = createTransactionNode(transaction);
    if (node == NULL) {
        return -1;
    }
    node->next = hash_table->buckets[index];
    hash_table->buckets[index] = node;
    return 0;
}

// Function to delete a transaction from the hash table
int deleteTransaction(struct HashTable *hash_table, long id) {
    int index = id % hash_table->size;
    struct TransactionNode **node = &hash_table->buckets[index];
    while (*node != NULL && (*node)->transaction->id != id) {
        node = &(*node)->next;
    }
    if (*node == NULL) {
        return -1;
    }
    struct TransactionNode *tmp = *node;
    *node = tmp->next;
    free(tmp);
    return 0;
}

// Function to retrieve a transaction from the hash table by ID
struct Transaction* getTransactionById(struct HashTable *hash_table, long id) {
    int index = id % hash_table->size;
    struct TransactionNode *node = hash_table->buckets[index];
    while (node != NULL && node->transaction->id != id) {
        node = node->next;
    }
    if (node == NULL) {
        return NULL;
    }
    return node->transaction;
}

