HashTable* init_hash_table(size_t size, float load_factor) {
    // Allocate memory for the hash table
    HashTable* table = malloc(sizeof(HashTable));
    if (!table) {
        return NULL;
    }

    // Initialize the hash table fields
    table->size = size;
    table->count = 0;
    table->nodes = calloc(size, sizeof(Node*));
    if (!table->nodes) {
