        return -1;
    }

    // Calculate the hash value for the string key
    size_t hash = hash_string(key);

    // Find the first available node in the bucket
    Node* node = table->nodes[hash];
    while (node && node->object) {
        if (!strcmp(node->object->string, key)) {
