    node->next = table->nodes[hash];
    table->nodes[hash] = node;

    // Increment the count of objects in the hash table
    table->count++;

    return 0;
}

// Delete an object from the hash table with the given string key
int delete_object(HashTable* table, const char* key) {
    // Calculate the hash value for the string key
