    // Find the first available node in the bucket
    Node* node = table->nodes[hash];
    while (node && node->object) {
        if (!strcmp(node->object->string, key)) {
            break;
        }
        node = node->next;
    }

    // Check if the object was found in the hash table
    if (!node || !node->object) {
        return -1;
    }

    // Remove the object from the hash table
    Node* prev_node = NULL;
    while (node && node->object) {
        if (!strcmp(node->object->string, key)) {
            break;
        }
        prev_node = node;
        node = node->next;
    }

    // Check if the object was found in the hash table
    if (!node || !node->object) {
        return -2;
    }

    // Remove the object from the linked list
    if (prev_node) {
        prev_node->next = node->next;
    } else {
        table->nodes[hash] = node->next;
    }

    // Free the memory for the object
    free(node->object);
    free(node);

    // Decrement the count of objects in the hash table
    table->count--;

    return 0;
}

// Retrieve an object from the hash table with the given string key
Object* retrieve_object(HashTable* table, const char* key) {
    // Calculate the hash value for the string key
    size_t hash = hash_string(key);

    // Find the first available node in the bucket
    Node* node = table->nodes[hash];
    while (node && node->object) {
