    }

    // Check if the object was found in the hash table
    if (!node || !node->object) {
        return -1;
    }

    // Update the integer and floating-point values for the object
    node->object->integer = integer;
    node->object->floating_point = floating_point;

    return 0;
}

// Free all memory allocated by the hash table
void free_hash_table(HashTable* table) {
    // Iterate over each bucket in the hash table
    for (size_t i = 0; i < table->size; i++) {
        Node* node = table->nodes[i];
        while (node) {
            // Free the memory for the object
            free(node->object);

            // Move to the next node in the linked list
            Node* next_node = node->next;
            free(node);
            node = next_node;
