// Define the metadata structure for each file
struct FileMetadata {
    int file_id;
    time_t creation_timestamp;
    char owner[256];
    struct AccessControlList *acl;
};

// Define the access control list structure
struct AccessControlList {
    char user[256];
    char permission[10];
};

// Define the file versioning and deduplication data structures
struct FileVersion {
    int file_id;
    time_t creation_timestamp;
    char owner[256];
    struct AccessControlList *acl;
    char *file_data;
};

// Define the cache structure for metadata and file versions
struct Cache {
    struct FileMetadata *metadata;
    struct FileVersion *versions;
};

// Define the node structure for the distributed system
struct Node {
    int id;
    struct Cache *cache;
    pthread_mutex_t cache_lock;
    sem_t *semaphore;
};

// Define the client structure for interacting with the system
struct Client {
    int node_id;
    struct Node *node;
    pthread_mutex_t client_lock;
    sem_t *semaphore;
};

// Function to initialize the cache and node structures
