    // Initialize the metadata and file version data structures
    cache->metadata = (struct FileMetadata *)malloc(sizeof(struct FileMetadata));
    cache->versions = (struct FileVersion *)malloc(sizeof(struct FileVersion));
}

// Function to initialize the node structure
void init_node(struct Node *node) {
    // Initialize the cache and semaphore for the node
    node->cache = (struct Cache *)malloc(sizeof(struct Cache));
    node->semaphore = sem_open("node_sem", O_CREAT, 0644, 1);
}

// Function to initialize the client structure
void init_client(struct Client *client) {
    // Initialize the node and semaphore for the client
