    pthread_mutex_lock(&client->node->cache_lock);

    // Check if the file already exists in the cache
    struct FileMetadata *metadata = find_file(client->node->cache, client->file_id);
    if (metadata != NULL) {
        // If the file exists, update its metadata and version
        update_file_metadata(metadata, client->file_data);
        add_file_version(metadata, client->file_data);
    } else {
        // If the file does not exist, create a new entry in the cache
        struct FileMetadata *new_metadata = (struct FileMetadata *)malloc(sizeof(struct FileMetadata));
        new_metadata->file_id = client->file_id;
        new_metadata->creation_timestamp = time(NULL);
        strcpy(new_metadata->owner, client->user);
        new_metadata->acl = (struct AccessControlList *)malloc(sizeof(struct AccessControlList));
        strcpy(new_metadata->acl->user, client->user);
        strcpy(new_metadata->acl->permission, "rw");
        add_file_version(new_metadata, client->file_data);
