void *manageMemory(void *args) {
    // Get the arguments passed to the function
    struct args *a = (struct args *)args;

    // Initialize the metadata structure
    Metadata metadata = {0};

    // Loop until the end of the list is reached
    while (a->node_list != NULL) {
        // Get the current node in the list
        NodeData *current_node = a->node_list;

        // Check if the node has been updated since the last check
        if (current_node->updated) {
            // Update the metadata structure with the new data
            metadata.num_nodes++;
            metadata.num_alerts[current_node->priority]++;
            metadata.avg_alert_time += current_node->timestamp - metadata.max_alert_time;
            metadata.max_alert_time = current_node->timestamp;
        }

        // Move to the next node in the list
        a->node_list = current_node->next;
    }

    // Return the metadata structure
    return &metadata;
}

