}

// Define the function to handle real-time and offline analysis of alerts
void *handleAlertAnalysis(void *args) {
    // Get the arguments passed to the function
    struct args *a = (struct args *)args;

    // Loop until the end of the list is reached
    while (a->node_list != NULL) {
        // Get the current node in the list
        NodeData *current_node = a->node_list;

        // Check if the node has been updated since the last check
        if (current_node->updated) {
            // Analyze the alert and update the metadata structure accordingly
            analyzeAlert(current_node);
        }

        // Move to the next node in the list
        a->node_list = current_node->next;
    }

    // Return NULL to indicate success
    return NULL;
}

// Define the function to handle memory deallocation for the data structure
void *handleMemoryDeallocation(void *args) {
    // Get the arguments passed to the function
    struct args *a = (struct args *)args;

    // Loop until the end of the list is reached
    while (a->node_list != NULL) {
