// Initialize a stage
void init_stage(Stage *stage) {
    stage->id = 0;
    pthread_mutex_init(&stage->lock, NULL);
    pthread_cond_init(&stage->cond, NULL);
    stage->running = true;
    stage->paused = false;
    stage->failed = false;
    stage->records = NULL;
    stage->num_records = 0;
}

// Destroy a stage
void destroy_stage(Stage *stage) {
    pthread_mutex_destroy(&stage->lock);
    pthread_cond_destroy(&stage->cond);
    free(stage->records);
}

// Initialize a pipeline
void init_pipeline(Pipeline *pipeline) {
    for (int i = 0; i < MAX_STAGES; i++) {
        init_stage(&pipeline->stages[i]);
    }
}

// Destroy a pipeline
void destroy_pipeline(Pipeline *pipeline) {
    for (int i = 0; i < MAX_STAGES; i++) {
