    }

    // Unlock the stage
    pthread_mutex_unlock(&stage->lock);
}

// Process records in a thread
void *process_records_thread(void *arg) {
    Stage *stage = (Stage *)arg;
    Record *records = NULL;
    size_t num_records = 0;

    // Loop until the stage is paused or failed
    while (!stage->paused && !stage->failed) {
        // Lock the stage to prevent concurrent access
        pthread_mutex_lock(&stage->lock);

        // Check if there are any records available for processing
        if (stage->num_records > 0) {
            // Allocate memory for the records
            records = malloc(sizeof(Record) * stage->num_records);
            memcpy(records, stage->records, sizeof(Record) * stage->num_records);
            num_records = stage->num_records;

            // Clear the records from the stage
            stage->num_records = 0;
        }

        // Unlock the stage
        pthread_mutex_unlock(&stage->lock);

        // Process the records if there are any
