// Define the configuration cache directory and file name
#define CONFIG_CACHE_DIR "/var/cache/config"
#define CONFIG_FILE "config.json"

// Define the default configuration directory and file name
#define DEFAULT_CONFIG_DIR "/etc/config"
#define DEFAULT_CONFIG_FILE "default.json"

// Define the maximum size of the configuration cache
#define MAX_CACHE_SIZE 1024 * 1024 * 1024 // 1GB

// Define the minimum password length
#define MIN_PASSWORD_LEN 8

// Define the maximum password length
#define MAX_PASSWORD_LEN 64

// Define the default IV length for AES-128-GCM
#define DEFAULT_IV_LEN 96

// Define the default key length for AES-128
#define DEFAULT_KEY_LEN 128

// Define the SHA-256 hash algorithm
#define HASH_ALGORITHM EVP_sha256()

// Define the GCM cipher mode
#define CIPHER_MODE EVP_aes_128_gcm()

// Define the AES block size
#define BLOCK_SIZE 16

// Define the maximum number of threads for concurrent access to the configuration cache
#define MAX_THREADS 32

// Define the logging levels
#define LOGGING_LEVEL_DEBUG 0
#define LOGGING_LEVEL_INFO 1
#define LOGGING_LEVEL_WARN 2
#define LOGGING_LEVEL_ERROR 3

// Define the performance monitoring thresholds
