struct Configuration {
    uint8_t iv[DEFAULT_IV_LEN];
    uint8_t key[DEFAULT_KEY_LEN];
};

struct CipherContext {
    struct Configuration configuration;
    EVP_CIPHER_CTX *ctx;
};

// Function to initialize the GCM cipher with a given password using the OpenSSL library
CipherContext* init_cipher(const char *password) {
    // Validate the password length
    if (strlen(password) < MIN_PASSWORD_LEN || strlen(password) > MAX_PASSWORD_LEN) {
        printf("Invalid password length\n");
        return NULL;
    }

    // Derive the encryption key from the password using SHA-256
    uint8_t key[DEFAULT_KEY_LEN];
    SHA256(password, strlen(password), key);

    // Initialize the GCM cipher context
    CipherContext *ctx = malloc(sizeof(CipherContext));
    ctx->configuration.iv = malloc(DEFAULT_IV_LEN);
    ctx->configuration.key = malloc(DEFAULT_KEY_LEN);
    memcpy(ctx->configuration.iv, key, DEFAULT_IV_LEN);
    memcpy(ctx->configuration.key, key + DEFAULT_IV_LEN, DEFAULT_KEY_LEN - DEFAULT_IV_LEN);
    ctx->ctx = EVP_CIPHER_CTX_new();
    if (EVP_EncryptInit_ex(ctx->ctx, CIPHER_MODE, NULL, key, ctx->configuration.iv) != 1) {
        printf("Failed to initialize cipher context\n");
        return NULL;
    }

    // Set the IV length based on the block size of AES-128-GCM
    int iv_len = EVP_CIPHER_CTX_iv_length(ctx->ctx);
    if (iv_len != DEFAULT_IV_LEN) {
        printf("Invalid IV length\n");
        return NULL;
    }

    // Set the key length required for AES-128
    int key_len = EVP_CIPHER_CTX_key_length(ctx->ctx);
    if (key_len != DEFAULT_KEY_LEN) {
        printf("Invalid key length\n");
        return NULL;
    }

    // Set the logging level for the cipher context
    EVP_CIPHER_CTX_set_logging(ctx->ctx, LOGGING_LEVEL_INFO);

    // Return the initialized cipher context
    return ctx;
}

// Function to clean up and disable the cipher when no longer needed
void cleanup_cipher(CipherContext *ctx) {
    if (ctx != NULL) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx->configuration.iv);
        free(ctx->configuration.key);
        free(ctx);
    }
}

