// Define data structures for the complex data model
typedef struct {
    double value;
    char *label;
    int id;
    uint64_t timestamp;
    int refcount;
    enum status_code status;
} data_point;

typedef struct node {
    data_point *data;
    struct node *next, *prev;
} node;

// Define a doubly linked list to manage the data points
node *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the data structure and update timestamps
void init(data_point **data, int size) {
    // Allocate memory for the data points
    *data = (data_point *)malloc(size * sizeof(data_point));

    // Initialize each data point's timestamp to the current system time
    for (int i = 0; i < size; i++) {
        (*data)[i].timestamp = time(NULL);
    }
}

// Function to add a new data point to the list
void add_data_point(data_point *new_data) {
    // Acquire the lock on the list
    pthread_mutex_lock(&lock);

    // Create a new node for the data point
    node *new_node = (node *)malloc(sizeof(node));
    new_node->data = new_data;
    new_node->next = NULL;
    new_node->prev = head;

    // Update the head of the list if necessary
    if (head != NULL) {
        head->next = new_node;
    }

    // Update the tail of the list
    head = new_node;

    // Release the lock on the list
    pthread_mutex_unlock(&lock);
}

// Function to retrieve a data point from the list by unique integer identifier
data_point *get_data_point(int id) {
    // Acquire the lock on the list
    pthread_mutex_lock(&lock);

    // Search for the data point with the given ID
    node *current = head;
    while (current != NULL && current->data->id != id) {
        current = current->next;
    }

    // Return the data point if found, otherwise return NULL
    pthread_mutex_unlock(&lock);
    return (current == NULL) ? NULL : current->data;
}

// Function to update an existing data point in the list
void update_data_point(int id, double value, char *label) {
    // Acquire the lock on the list
    pthread_mutex_lock(&lock);

    // Search for the data point with the given ID
    node *current = head;
    while (current != NULL && current->data->id != id) {
        current = current->next;
    }

    // Update the data point if found, otherwise do nothing
    if (current != NULL) {
        current->data->value = value;
        current->data->label = label;
    }

    // Release the lock on the list
    pthread_mutex_unlock(&lock);
}

// Function to delete a data point from the list by unique integer identifier
void delete_data_point(int id) {
    // Acquire the lock on the list
    pthread_mutex_lock(&lock);

    // Search for the data point with the given ID
    node *current = head;
    while (current != NULL && current->data->id != id) {
        current = current->next;
    }

    // Delete the data point if found, otherwise do nothing
    if (current != NULL) {
        // Update the references to the deleted node
        if (current == head) {
            head = current->next;
        } else {
            current->prev->next = current->next;
        }
        if (current->next != NULL) {
            current->next->prev = current->prev;
        }

        // Free the memory for the deleted node
        free(current);
    }

    // Release the lock on the list
    pthread_mutex_unlock(&lock);
}

// Function to merge incoming data points from an external stream
void merge_data_points(data_point *new_data, int size) {
    // Acquire the lock on the list
    pthread_mutex_lock(&lock);

    // Iterate over each new data point and update or add it to the list
    for (int i = 0; i < size; i++) {
        // Search for the data point with the given ID in the list
        node *current = head;
        while (current != NULL && current->data->id != new_data[i].id) {
            current = current->next;
        }

        // Update the existing data point if found, otherwise add a new one
        if (current != NULL) {
            current->data->value = new_data[i].value;
            current->data->label = new_data[i].label;
        } else {
            add_data_point(&new_data[i]);
        }
    }

    // Release the lock on the list
    pthread_mutex_unlock(&lock);
}

// Function to release unused memory blocks periodically
void release_memory() {
    // Acquire the lock on the list
    pthread_mutex_lock(&lock);

    // Iterate over each node in the list and release its data point if it has a reference count of 0
    node *current = head;
    while (current != NULL) {
        if (current->data->refcount == 0) {
            free(current->data);
            current->next->prev = current->prev;
            current->prev->next = current->next;
            free(current);
            current = head;
        } else {
            current = current->next;
        }
    }

    // Release the lock on the list
    pthread_mutex_unlock(&lock);
}
