function fetchMatchingElements(rootElement, selector, callback, transformation) {
  if (!rootElement || !selector) {
    return [];
  }

  const matchingElements = [];

  // Recursively traverse the DOM tree starting from the root element
  function traverseDOMTree(element) {
    // Check if the current element matches the selector
    if (matchesSelector(element, selector)) {
      // Add the element to the result array
      matchingElements.push(element);
    }

    // Recursively traverse the child elements of the current element
    for (const childElement of element.children) {
      traverseDOMTree(childElement);
    }
  }

  // Start traversing the DOM tree from the root element
  traverseDOMTree(rootElement);

  // Apply any additional filtering or transformation to the matching elements
  if (callback) {
    matchingElements.filter(element => callback(element));
  }
  if (transformation) {
    matchingElements.map(element => transformation(element));
  }

  return matchingElements;
}
