void manage_items(Node **head, int op, double value, int id, char *description) {
    // Check if the operation is valid
    assert(op == 0 || op == 1 || op == 2);

    // Allocate memory for a new item
    Item *new_item = malloc(sizeof(Item));
    if (new_item == NULL) {
        printf("Error: Failed to allocate memory for the new item\n");
        return;
    }

    // Initialize the fields of the new item
    new_item->value = value;
    new_item->id = id;
    strcpy(new_item->description, description);

    // Insert the new item into the list
