        node->item = new_item;
        node->next = NULL;

        if (*head == NULL) {
            *head = node;
        } else {
            Node *current = *head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = node;
        }
    }

    // Delete an item from the list
    if (op == 1) {
        Node *node = *head;
        while (node != NULL && node->item->value != value) {
            node = node->next;
        }
        if (node != NULL) {
            // Remove the item from the list
            Node *previous = node;
            previous->next = node->next;
            free(node);
        } else {
            printf("Error: Item not found in the list\n");
        }
    }

    // Retrieve an item from the list
    if (op == 2) {
        Node *node = *head;
        while (node != NULL && node->item->value != value) {
            node = node->next;
        }
        if (node != NULL) {
            // Return the item from the list
            return node->item;
        } else {
            printf("Error: Item not found in the list\n");
            return NULL;
        }
    }
}

// Free all allocated memory at the end of the function
void free_items(Node **head) {
    Node *node = *head;
    while (node != NULL) {
        Node *next = node->next;
        free(node);
        node = next;
    }
}
