// Custom hash map implementation
struct HashMap {
    int size;
    int capacity;
    struct Entry *entries;
};

struct Entry {
    int key;
    long offset;
    char *string;
};

void initHashMap(struct HashMap *map, int initialCapacity) {
    map->size = 0;
    map->capacity = initialCapacity;
    map->entries = malloc(sizeof(struct Entry) * initialCapacity);
}

bool insertIntoHashMap(struct HashMap *map, int key, long offset, char *string) {
    if (map->size == map->capacity) {
        // Resize the hash map if it's full
        map->capacity *= 2;
        map->entries = realloc(map->entries, sizeof(struct Entry) * map->capacity);
    }

    struct Entry *entry = &map->entries[map->size++];
    entry->key = key;
    entry->offset = offset;
    entry->string = string;

    return true;
}

bool getFromHashMap(struct HashMap *map, int key, long *offset, char **string) {
    for (int i = 0; i < map->size; i++) {
        if (map->entries[i].key == key) {
            *offset = map->entries[i].offset;
            *string = map->entries[i].string;
            return true;
        }
    }

    return false;
}

void freeHashMap(struct HashMap *map) {
    for (int i = 0; i < map->size; i++) {
        free(map->entries[i].string);
    }
    free(map->entries);
}

// Function to dynamically allocate memory for and initialize the data structures
void initDataStructures(long *offsets, int *keys, struct Record **records, int numRecords) {
    // Allocate memory for the arrays of offsets, keys, and records
    offsets = malloc(sizeof(long) * numRecords);
    keys = malloc(sizeof(int) * numRecords);
    records = malloc(sizeof(struct Record *) * numRecords);

    // Initialize the hash map for efficient record retrieval by key
    struct HashMap map;
    initHashMap(&map, 1024);

    // Iterate over the input data and insert each record into the hash map
    for (int i = 0; i < numRecords; i++) {
        long offset = offsets[i];
        int key = keys[i];
        char *string = malloc(sizeof(char) * 16); // Use a fixed size for simplicity
        sprintf(string, "%d_%ld", key, offset);

        if (!insertIntoHashMap(&map, key, offset, string)) {
            // Handle allocation failure gracefully
            free(string);
            continue;
        }

        struct Record *record = malloc(sizeof(struct Record));
        record->key = key;
        record->offset = offset;
        record->string = string;
        records[i] = record;
    }

    // Free the hash map when it's no longer needed
    freeHashMap(&map);
}

// Function to deallocate memory for the data structures
void freeDataStructures(long *offsets, int *keys, struct Record **records) {
    // Deallocate memory for the arrays of offsets, keys, and records
    free(offsets);
    free(keys);
    for (int i = 0; i < numRecords; i++) {
        free(records[i]->string);
        free(records[i]);
    }
    free(records);
}
