    Item *item;
    struct Node *next;
} Node;

// Define a function to add an item to the list
void addItem(Node **head, int id, double value, char *description) {
    // Create a new node for the item
    Node *new_node = malloc(sizeof(Node));
    if (new_node == NULL) {
        printf("Error: Failed to allocate memory for new node\n");
        return;
    }

    // Initialize the new node with the given data
    new_node->item = malloc(sizeof(Item));
    if (new_node->item == NULL) {
        printf("Error: Failed to allocate memory for item\n");
        free(new_node);
        return;
    }
    new_node->item->id = id;
    new_node->item->value = value;
    strncpy(new_node->item->description, description, 100);

    // Add the new node to the list
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

// Define a function to retrieve an item from the list by id
Item* getItemById(Node **head, int id) {
    // Iterate through the list until we find the matching id
    Node *current = *head;
    while (current != NULL && current->item->id != id) {
        current = current->next;
    }

    // Return the item if found, or NULL if not found
    return (current == NULL) ? NULL : current->item;
}

// Define a function to remove an item from the list by id
void removeItemById(Node **head, int id) {
    // Iterate through the list until we find the matching id
    Node *current = *head;
    while (current != NULL && current->item->id != id) {
        current = current->next;
    }

    // Remove the item if found, or do nothing if not found
    if (current != NULL) {
        Node *previous = current->prev;
        previous->next = current->next;
        free(current);
    }
}

// Define a function to sort the list of items by value in ascending order
void sortItemsByValue(Node **head) {
    // Create an array of pointers to the items in the list
    Item **items = malloc(sizeof(Item *) * countNodes(*head));
    if (items == NULL) {
        printf("Error: Failed to allocate memory for item array\n");
        return;
    }
    int i = 0;
    Node *current = *head;
    while (current != NULL) {
        items[i++] = current->item;
        current = current->next;
    }

    // Sort the array of pointers using a stable sorting algorithm
    qsort(items, i, sizeof(Item *), compareItemsByValue);

    // Update the list with the sorted items
    i = 0;
    current = *head;
    while (current != NULL) {
        current->item = items[i++];
        current = current->next;
    }

    // Free the array of pointers
    free(items);
}

// Define a function to merge two lists of items into one, preserving order
void mergeItems(Node **head1, Node **head2) {
    // Create a new list for the merged items
    Node *merged_list = NULL;

    // Iterate through both lists and add each item to the merged list
    while (*head1 != NULL && *head2 != NULL) {
        if ((*head1)->item->value < (*head2)->item->value) {
            addItem(&merged_list, (*head1)->item->id, (*head1)->item->value, (*head1)->item->description);
            head1 = &(*head1)->next;
        } else {
            addItem(&merged_list, (*head2)->item->id, (*head2)->item->value, (*head2)->item->description);
            head2 = &(*head2)->next;
        }
    }

    // Add any remaining items from the first list
    while (*head1 != NULL) {
        addItem(&merged_list, (*head1)->item->id, (*head1)->item->value, (*head1)->item->description);
        head1 = &(*head1)->next;
    }

    // Add any remaining items from the second list
    while (*head2 != NULL) {
        addItem(&merged_list, (*head2)->item->id, (*head2)->item->value, (*head2)->item->description);
        head2 = &(*head2)->next;
    }

    // Update the list with the merged items
    *head1 = merged_list;
}

// Define a function to free all allocated memory at the end of the function
void freeAllMemory(Node **head) {
    Node *current = *head;
    while (current != NULL) {
        Node *next = current->next;
        free(current);
        current = next;
    }
}

// Define a comparison function for sorting items by value in ascending order
int compareItemsByValue(const void *item1, const void *item2) {
    return (*(Item **)item1)->value - (*(Item **)item2)->value;
}
