struct Items {
    items: Vec<Item>,
    descriptions: HashMap<i32, String>,
    values: HashMap<i32, f64>,
}

impl Items {
    fn new() -> Self {
        Self {
            items: vec![],
            descriptions: HashMap::new(),
            values: HashMap::new(),
        }
    }

    fn insert(&mut self, item: Item) {
        let id = item.id;
        let value = item.value;
        let description = item.description;

        // Check if the item already exists in the list
        if self.items.iter().any(|x| x.id == id) {
            return;
        }

        // Insert the new item into the list
        self.items.push(item);

        // Update the descriptions and values maps
        self.descriptions.insert(id, description);
        self.values.insert(id, value);
    }

    fn delete(&mut self, id: i32) {
        let index = self.items.iter().position(|x| x.id == id).unwrap();
        self.items.remove(index);
        self.descriptions.remove(&id);
        self.values.remove(&id);
    }

    fn get(&self, id: i32) -> Option<&Item> {
        self.items.iter().find(|x| x.id == id)
    }

    fn sort_by_value(&mut self) {
        self.items.sort_by(|a, b| a.value.partial_cmp(&b.value).unwrap());
    }

