    struct bucket* bucket = find_bucket(dht, hash);
    if (bucket == NULL) {
        printf("Error: failed to insert data point\n");
        return;
    }
    bucket->points[bucket->num_points++] = point;
}

void delete_data_point(struct dht* dht, struct data_point* point) {
    // Calculate the hash value of the data point
    long hash = calculate_hash(point);

    // Delete the data point from the DHT
    struct bucket* bucket = find_bucket(dht, hash);
    if (bucket == NULL) {
        printf("Error: failed to delete data point\n");
        return;
    }
    for (int i = 0; i < bucket->num_points; i++) {
        struct data_point* current = bucket->points[i];
        if (current == point) {
            free(bucket->points[i]);
            bucket->points[i] = NULL;
            break;
        }
    }
}
