// Function to process a transaction and update the metric
void process_transaction(Transaction *transaction) {
    // Calculate the weighted sum of the transaction value using a moving average over the last 10 seconds
    double weighted_sum = 0;
    for (int i = 0; i < TRANSACTIONS_SIZE; i++) {
        if (transactions[i].timestamp > time(NULL) - 10) {
            weighted_sum += transactions[i].value;
        }
    }

    // Update the metric with the new weighted sum and highest transaction ID
    Metric *metric = &metrics[time(NULL) % METRICS_SIZE];
    metric->weighted_sum = weighted_sum / TRANSACTIONS_SIZE;
    if (transaction->transaction_id > metric->highest_transaction_id) {
        metric->highest_transaction_id = transaction->transaction_id;
    }
}

// Function to handle a single transaction and update the metrics
void handle_transaction(Transaction *transaction) {
    // Check if the transaction is within the age limit (60 seconds)
    if (time(NULL) - transaction->timestamp < 60) {
        // Check if the number of transactions in the last 3-second window exceeds the limit (50)
        int count = 0;
        for (int i = 0; i < TRANSACTIONS_SIZE; i++) {
            if (transactions[i].timestamp > time(NULL) - 3 && transactions[i].transaction_id == transaction->transaction_id) {
                count++;
