        if (count <= 50) {
            // Add the transaction to the fixed-size data structure for transactions
            transactions[time(NULL) % TRANSACTIONS_SIZE] = *transaction;
            process_transaction(transaction);
        }
    }
}

// Function to handle a batch of transactions and update the metrics
void handle_batch(Transaction *transactions, int count) {
