        handle_transaction(&transactions[i]);
    }
}

// Main function that handles incoming transactions and updates the metrics
void main() {
    // Initialize the fixed-size data structures for transactions and metrics
    memset(transactions, 0, sizeof(Transaction) * TRANSACTIONS_SIZE);
    memset(metrics, 0, sizeof(Metric) * METRICS_SIZE);

    // Loop indefinitely to handle incoming transactions
    while (1) {
        // Handle a batch of transactions and update the metrics
