flexible_data_structure *init_flexible_data_structure(size_t initial_capacity) {
    flexible_data_structure *fd = malloc(sizeof(flexible_data_structure));
    fd->offset_array = calloc(initial_capacity, sizeof(long));
    fd->key_array = calloc(initial_capacity, sizeof(int));
    fd->record_array = calloc(initial_capacity, sizeof(record *));
    fd->capacity = initial_capacity;
    fd->size = 0;
    return fd;
}

// Insert a new record into the data structure
void insert_record(flexible_data_structure *fd, int key, int value) {
    // Check if the data structure needs to be resized
    if (fd->size == fd->capacity) {
        fd->capacity *= 2;
        fd->offset_array = realloc(fd->offset_array, fd->capacity * sizeof(long));
        fd->key_array = realloc(fd->key_array, fd->capacity * sizeof(int));
        fd->record_array = realloc(fd->record_array, fd->capacity * sizeof(record *));
    }

    // Insert the new record at the end of the data structure
    long offset = (long) &(fd->record_array[fd->size]) - (long) fd->record_array;
    fd->offset_array[fd->size] = offset;
    fd->key_array[fd->size] = key;
    fd->record_array[fd->size]->value = value;
    fd->size++;
