        if (fd->key_array[i] == key) {
            break;
        }
    }

    // Check if the record was found
    if (i == fd->size) {
        return;
    }

    // Shift all records after the deleted record to fill the gap
    for (size_t j = i + 1; j < fd->size; j++) {
        fd->offset_array[j - 1] = fd->offset_array[j];
        fd->key_array[j - 1] = fd->key_array[j];
        fd->record_array[j - 1] = fd->record_array[j];
