// Define the record structure
typedef struct {
    int key;
    long offset;
} Record;

// Define the hash table for quick key-based lookups
typedef struct {
    int size;
    Record** records;
} HashTable;

// Define the linked list node structure
typedef struct Node {
    Record* record;
    struct Node* next;
} Node;

// Define the linked list structure
typedef struct {
    Node* head;
    Node* tail;
} LinkedList;

// Define the function to dynamically manage memory for records
void manageMemory(Record** records, int numRecords) {
    // Check if there are any unused memory blocks and release them periodically
    for (int i = 0; i < numRecords; i++) {
        if (records[i] == NULL) {
            free(records[i]);
            records[i] = NULL;
        }
    }
}

// Define the function to insert a record into the linked list
void insertRecord(LinkedList* list, Record* record) {
    // Create a new node for the record
    Node* node = malloc(sizeof(Node));
    node->record = record;
    node->next = NULL;

    // Insert the node into the linked list
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        list->tail = node;
    }
}

// Define the function to delete a record from the linked list
void deleteRecord(LinkedList* list, Record* record) {
    // Find the node containing the record
    Node* current = list->head;
    while (current != NULL && current->record != record) {
        current = current->next;
    }

    // If the node is found, delete it from the linked list
    if (current != NULL) {
        Node* previous = current->previous;
        Node* next = current->next;
        if (previous == NULL) {
            list->head = next;
        } else {
            previous->next = next;
        }
        free(current);
    }
}

// Define the function to traverse the linked list and perform an operation on each record
void traverseRecords(LinkedList* list, void (*operation)(Record*)) {
    // Traverse the linked list and perform the operation on each record
    Node* current = list->head;
    while (current != NULL) {
        operation(current->record);
        current = current->next;
    }
}

// Define the function to insert a record into the hash table
void insertRecordIntoHashTable(HashTable* table, Record* record) {
    // Calculate the hash value for the key
    int hashValue = record->key % table->size;

    // Insert the record into the hash table
    if (table->records[hashValue] == NULL) {
        table->records[hashValue] = record;
    } else {
        Record* current = table->records[hashValue];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = record;
    }
}

// Define the function to delete a record from the hash table
void deleteRecordFromHashTable(HashTable* table, Record* record) {
    // Calculate the hash value for the key
    int hashValue = record->key % table->size;

    // Find the node containing the record in the hash table
    Node* current = table->records[hashValue];
    while (current != NULL && current->record != record) {
        current = current->next;
    }

    // If the node is found, delete it from the hash table
    if (current != NULL) {
        Node* previous = current->previous;
        Node* next = current->next;
        if (previous == NULL) {
            table->records[hashValue] = next;
        } else {
            previous->next = next;
        }
        free(current);
    }
}

// Define the function to perform an operation on a record in the hash table
void operateOnRecordInHashTable(HashTable* table, int key, void (*operation)(Record*)) {
    // Calculate the hash value for the key
    int hashValue = key % table->size;

    // Find the node containing the record in the hash table
    Node* current = table->records[hashValue];
    while (current != NULL && current->record->key != key) {
        current = current->next;
    }

    // If the node is found, perform the operation on the record
    if (current != NULL) {
        operation(current->record);
    }
}

// Define the function to insert a record into the linked list and hash table
void insertRecordIntoListAndHashTable(LinkedList* list, HashTable* table, Record* record) {
    // Insert the record into the linked list
    insertRecord(list, record);

    // Insert the record into the hash table
    insertRecordIntoHashTable(table, record);
