// Structure to represent an entry in the list
typedef struct {
    char* name;
    int age;
} Entry;

// Structure to represent the list of entries
typedef struct {
    Entry** entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} EntryList;

// Function to initialize an empty entry list
EntryList* init_entry_list() {
    EntryList* list = malloc(sizeof(EntryList));
    if (list == NULL) {
        return NULL;
    }
    list->entries = malloc(sizeof(Entry*) * 10);
    if (list->entries == NULL) {
        free(list);
        return NULL;
    }
    list->capacity = 10;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

// Function to add an entry to the list
int add_entry(EntryList* list, const char* name, int age) {
    if (list == NULL || name == NULL) {
        return -1;
    }
    pthread_mutex_lock(&list->mutex);
    // Check if the list needs to be resized
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        Entry** new_entries = realloc(list->entries, sizeof(Entry*) * new_capacity);
        if (new_entries == NULL) {
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
        list->entries = new_entries;
        list->capacity = new_capacity;
    }
    // Create a new entry and add it to the list
    Entry* new_entry = malloc(sizeof(Entry));
    if (new_entry == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    new_entry->name = strdup(name);
    new_entry->age = age;
    list->entries[list->count++] = new_entry;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Function to delete an entry from the list by name
int delete_entry(EntryList* list, const char* name) {
    if (list == NULL || name == NULL) {
        return -1;
    }
    pthread_mutex_lock(&list->mutex);
    // Find the entry to be deleted and remove it from the list
    for (size_t i = 0; i < list->count; i++) {
        if (strcmp(list->entries[i]->name, name) == 0) {
            free(list->entries[i]);
            memmove(&list->entries[i], &list->entries[i + 1], sizeof(Entry*) * (list->count - i));
            list->count--;
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
    }
    // If the entry is not found, return an error
    pthread_mutex_unlock(&list->mutex);
    return -1;
}

// Function to update an entry in the list by name
int update_entry(EntryList* list, const char* name, int age) {
    if (list == NULL || name == NULL) {
        return -1;
    }
    pthread_mutex_lock(&list->mutex);
    // Find the entry to be updated and update its age
    for (size_t i = 0; i < list->count; i++) {
        if (strcmp(list->entries[i]->name, name) == 0) {
            list->entries[i]->age = age;
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
    }
    // If the entry is not found, return an error
    pthread_mutex_unlock(&list->mutex);
    return -1;
}

// Function to free the memory allocated for the list
void free_entry_list(EntryList* list) {
    if (list == NULL) {
        return;
    }
    pthread_mutex_lock(&list->mutex);
    // Free the memory allocated for each entry in the list
    for (size_t i = 0; i < list->count; i++) {
        free(list->entries[i]);
    }
    // Free the memory allocated for the list itself
    free(list->entries);
    pthread_mutex_unlock(&list->mutex);
    free(list);
}
```
