void delete_dependency(struct database* db, int id) {
    // Check if the dependency exists in the database
    struct dependency* existing_dependency = get_dependency(db, id);
    if (existing_dependency != NULL) {
        // Remove the dependency from the array of dependencies
        for (int i = 0; i < db->num_dependencies; i++) {
            if (db->dependencies[i]->id == id) {
                // Shift all subsequent dependencies to fill the gap
                memmove(db->dependencies + i, db->dependencies + i + 1, sizeof(struct dependency*) * (db->num_dependencies - i));
                break;
            }
        }
        db->num_dependencies--;
    }
}

