// Define the function to encrypt data using AES-256 in CBC mode
void aes_encrypt(unsigned char* plaintext, unsigned char* ciphertext, int length) {
    // Initialize the AES context with the encryption key and IV
    AES_KEY enc_key;
    AES_set_encrypt_key(plaintext, 256, &enc_key);
    unsigned char iv[16];
    memset(iv, 0x00, sizeof(iv));
    AES_cbc_encrypt(plaintext, ciphertext, length, &enc_key, iv, AES_ENCRYPT);
}

// Define the function to decrypt data using AES-256 in CBC mode
void aes_decrypt(unsigned char* ciphertext, unsigned char* plaintext, int length) {
    // Initialize the AES context with the decryption key and IV
    AES_KEY dec_key;
    AES_set_decrypt_key(ciphertext, 256, &dec_key);
    unsigned char iv[16];
    memset(iv, 0x00, sizeof(iv));
    AES_cbc_encrypt(ciphertext, plaintext, length, &dec_key, iv, AES_DECRYPT);
}

// Define the function to encrypt data using RSA-2048 in OAEP mode
void rsa_encrypt(unsigned char* plaintext, unsigned char* ciphertext, int length) {
    // Initialize the RSA context with the encryption key and padding
    RSA_KEY enc_key;
    RSA_set_encrypt_key(plaintext, 2048, &enc_key);
    RSA_OAEP_ENCODE(plaintext, ciphertext, length, &enc_key);
}

