    FILE *file; // File pointer for writing logs
    char *filename; // Filename for the log file
    int size; // Size of the log file
    int count; // Number of lines written to the log file
};

// Function to initialize a hash table with a given size and load factor
struct HashTable *initHashTable(int size, float loadFactor) {
    struct HashTable *ht = malloc(sizeof(struct HashTable));
    ht->size = size;
    ht->count = 0;
    ht->loadFactor = loadFactor;
    ht->table = calloc(size, sizeof(struct Node *));
    return ht;
}

// Function to insert a record into the hash table
void insertRecord(struct HashTable *ht, long offset, int key, struct Record *record) {
    // Calculate the index of the bucket for the given key
    int index = key % ht->size;

    // Create a new node with the given record and add it to the linked list
    struct Node *node = malloc(sizeof(struct Node));
    node->offset = offset;
    node->key = key;
    node->record = record;
    node->next = ht->table[index];
    ht->table[index] = node;

    // Increment the count of elements in the hash table
    ht->count++;
}

// Function to delete a record from the hash table
void deleteRecord(struct HashTable *ht, int key) {
    // Calculate the index of the bucket for the given key
    int index = key % ht->size;

    // Find the node with the given key in the linked list
    struct Node **nodePtr = &ht->table[index];
    while (*nodePtr != NULL && (*nodePtr)->key != key) {
        nodePtr = &(*nodePtr)->next;
    }

    // If the node is found, remove it from the linked list and free its memory
    if (*nodePtr != NULL) {
        struct Node *node = *nodePtr;
        *nodePtr = node->next;
        free(node);
        ht->count--;
    }
}

// Function to lookup a record in the hash table by its key
struct Record *lookupRecord(struct HashTable *ht, int key) {
    // Calculate the index of the bucket for the given key
    int index = key % ht->size;

    // Find the node with the given key in the linked list
    struct Node **nodePtr = &ht->table[index];
    while (*nodePtr != NULL && (*nodePtr)->key != key) {
        nodePtr = &(*nodePtr)->next;
    }

    // If the node is found, return its record
    if (*nodePtr != NULL) {
        struct Node *node = *nodePtr;
        return node->record;
    } else {
        return NULL;
    }
}

// Function to update a record in the hash table by its key
void updateRecord(struct HashTable *ht, int key, struct Record *record) {
    // Calculate the index of the bucket for the given key
    int index = key % ht->size;

    // Find the node with the given key in the linked list
    struct Node **nodePtr = &ht->table[index];
    while (*nodePtr != NULL && (*nodePtr)->key != key) {
        nodePtr = &(*nodePtr)->next;
    }

    // If the node is found, update its record and return
    if (*nodePtr != NULL) {
        struct Node *node = *nodePtr;
        node->record = record;
    } else {
        insertRecord(ht, 0, key, record);
    }
}

// Function to resize the hash table when the load factor exceeds a configurable threshold
void resizeHashTable(struct HashTable *ht) {
    // Calculate the new size of the hash table based on the current size and load factor
    int newSize = ht->size * 2;

    // Create a new hash table with the new size
    struct HashTable *newHt = initHashTable(newSize, ht->loadFactor);

    // Iterate over each bucket in the old hash table and transfer its elements to the new hash table
    for (int i = 0; i < ht->size; i++) {
        struct Node *node = ht->table[i];
        while (node != NULL) {
            insertRecord(newHt, node->offset, node->key, node->record);
            node = node->next;
        }
    }

    // Free the old hash table and replace it with the new one
    free(ht->table);
    ht->size = newSize;
    ht->table = newHt->table;
}

// Function to handle memory allocation failures gracefully
void *handleMemoryAllocationFailure(struct MemoryPool *mp, void *(*function)(void *), void *args) {
    // If the memory pool is full, try reallocating in smaller chunks until a successful allocation is made
    while (mp->count == mp->size) {
        struct Block **blockPtr = &mp->blocks;
        while (*blockPtr != NULL && (*blockPtr)->next != NULL) {
            blockPtr = &(*blockPtr)->next;
        }
        if (*blockPtr != NULL) {
            struct Block *block = *blockPtr;
            block->size /= 2;
            void *data = realloc(block->data, block->size);
            if (data == NULL) {
                break;
            } else {
                block->data = data;
            }
        } else {
            break;
        }
    }

    // If a successful allocation is made, call the given function with the arguments and return its result
    if (mp->count < mp->size) {
        struct Block *block = malloc(sizeof(struct Block));
        block->data = function(args);
        block->size = mp->size;
        block->next = NULL;
        mp->count++;
        return block->data;
    } else {
        return NULL;
    }
}

// Function to initialize a memory pool with a given size and load factor
struct MemoryPool *initMemoryPool(int size, float loadFactor) {
    struct MemoryPool *mp = malloc(sizeof(struct MemoryPool));
    mp->size = size;
    mp->count = 0;
    mp->blocks = NULL;
    return mp;
}

// Function to allocate memory from the memory pool
void *allocateMemory(struct MemoryPool *mp, int size) {
    // If the memory pool is full, try reallocating in smaller chunks until a successful allocation is made
    while (mp->count == mp->size) {
        struct Block **blockPtr = &mp->blocks;
        while (*blockPtr != NULL && (*blockPtr)->next != NULL) {
            blockPtr = &(*blockPtr)->next;
        }
        if (*blockPtr != NULL) {
            struct Block *block = *blockPtr;
            block->size /= 2;
            void *data = realloc(block->data, block->size);
            if (data == NULL) {
                break;
            } else {
                block->data = data;
            }
        } else {
            break;
        }
    }

    // If a successful allocation is made, return the allocated memory and increment the count of active blocks
    if (mp->count < mp->size) {
        struct Block *block = malloc(sizeof(struct Block));
        block->data = malloc(size);
        block->size = size;
        block->next = NULL;
        mp->count++;
        return block->data;
    } else {
        return NULL;
    }
}

// Function to free memory from the memory pool
void freeMemory(struct MemoryPool *mp, void *ptr) {
    // Find the block that contains the given pointer and remove it from the linked list
    struct Block **blockPtr = &mp->blocks;
    while (*blockPtr != NULL && (*blockPtr)->data != ptr) {
        blockPtr = &(*blockPtr)->next;
    }
    if (*blockPtr != NULL) {
        struct Block *block = *blockPtr;
        *blockPtr = block->next;
        free(block);
        mp->count--;
    }
}

// Function to initialize a thread pool with a given size and load factor
struct ThreadPool *initThreadPool(int size, float loadFactor) {
    struct ThreadPool *tp = malloc(sizeof(struct ThreadPool));
    tp->size = size;
    tp->count = 0;
    tp->threads = calloc(size, sizeof(pthread_t));
    tp->queue = initQueue();
    return tp;
}

// Function to initialize a queue for managing tasks in the thread pool
struct Queue *initQueue() {
    struct Queue *q = malloc(sizeof(struct Queue));
    q->size = 0;
    q->front = 0;
    q->rear = -1;
    return q;
}

// Function to enqueue a task in the thread pool queue
void enqueueTask(struct ThreadPool *tp, void *(*function)(void *), void *args) {
    // If the queue is full, resize it by doubling its size
    if (tp->queue->size == tp->queue->rear + 1) {
        struct Queue **qPtr = &tp->queue;
        while (*qPtr != NULL && (*qPtr)->size == (*qPtr)->rear + 1) {
            qPtr = &(*qPtr)->next;
        }
        if (*qPtr != NULL) {
            struct Queue *q = *qPtr;
            q->size *= 2;
            q->front = 0;
            q->rear = q->size - 1;
        } else {
            break;
        }
    }

    // If a slot is available in the queue, add the task and increment the count of active threads
    if (tp->queue->size > tp->queue->rear + 1) {
        struct Task *task = malloc(sizeof(struct Task));
        task->function = function;
        task->args = args;
        tp->queue->rear++;
        tp->count++;
    } else {
        return NULL;
    }
}

// Function to dequeue a task from the thread pool queue
void *dequeueTask(struct ThreadPool *tp) {
    // If the queue is empty, return NULL
    if (tp->queue->front > tp->queue->rear) {
        return NULL;
    }

    // Remove the first task from the queue and decrement the count of active threads
    struct Task *task = tp->queue->tasks[tp->queue->front];
    tp->queue->tasks[tp->queue->front] = NULL;
    tp->queue->front++;
    tp->count--;
    return task;
}

