// Define a function to dynamically allocate memory for and initialize an array of 'record' structures
Record *allocate_records(int num_records, int record_size) {
    // Validate the configuration file for correctness and completeness
    if (num_records <= 0 || record_size <= 0) {
        fprintf(stderr, "Invalid number of records or record size\n");
        return NULL;
    }

    // Allocate memory for the array of 'record' structures
    Record *records = (Record *)malloc(num_records * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        return NULL;
    }

    // Initialize the array of 'record' structures with random values within a specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % INT_MAX;
    }

    // Return the initialized array of 'record' structures
    return records;
}

