// Define a function to manage memory allocation and deallocation for the 'record' structures
void manage_records(Record *records, int num_records) {
    // Allocate memory for the linked list of records
    Node *head = (Node *)malloc(sizeof(Node));
    if (!head) {
        handle_memory_allocation_failure("Failed to allocate memory for linked list");
    }

    // Initialize the linked list of records
    head->record = records;
    head->next = NULL;

    // Allocate memory for the hash table
    HashTable *hash_table = (HashTable *)malloc(sizeof(HashTable));
    if (!hash_table) {
        handle_memory_allocation_failure("Failed to allocate memory for hash table");
    }

    // Initialize the hash table with a default size and capacity
    hash_table->size = 10;
    hash_table->capacity = 20;
    hash_table->buckets = (Node **)malloc(hash_table->size * sizeof(Node *));
    if (!hash_table->buckets) {
        handle_memory_allocation_failure("Failed to allocate memory for hash table buckets");
    }

    // Insert the records into the linked list and hash table
    Node *current = head;
    while (current != NULL) {
        int key = current->record->value;
        int index = key % hash_table->size;
        if (!hash_table->buckets[index]) {
            hash_table->buckets[index] = current;
        } else {
            Node *previous = hash_table->buckets[index];
            while (previous->next != NULL) {
                previous = previous->next;
            }
            previous->next = current;
        }
        current = current->next;
    }

    // Deallocate memory for the linked list and hash table when they are no longer needed
    free(head);
    free(hash_table->buckets);
    free(hash_table);
}

