// Define a function to handle concurrent access to the 'record' structures
void handle_concurrent_access(Record *records, int num_records) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Lock the mutex before accessing the 'record' structures
    pthread_mutex_lock(&mutex);

    // Perform concurrent read operations on the 'record' structures
    while (1) {
        // Check if there are any records to process
        if (!records || !num_records) {
            break;
        }

        // Process the next record
        Record *current = records[0];
        int key = current->value;
        int index = key % hash_table->size;
        Node *previous = NULL;
        Node *current = hash_table->buckets[index];
        while (current != NULL) {
            if (current->record->value == key) {
                break;
            }
            previous = current;
            current = current->next;
        }

        // If the record was found, update its value and unlock the mutex
        if (current != NULL) {
            current->record->value++;
            pthread_mutex_unlock(&mutex);
        } else {
            // If the record was not found, wait for a signal to continue processing
            pthread_cond_wait(&cond, &mutex);
        }
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}

