// Define the structure to store log entries
typedef struct {
    long timestamp;
    int severity_level;
    char* message;
} logEntry;

// Define a record array to store log entries
typedef struct {
    size_t capacity;
    size_t count;
    logEntry** records;
} recordArray;

// Define a custom hash table for storing log entries
