// Custom memory pool for managing memory allocations
struct MemoryPool {
    void* data;
    size_t size;
};

// Function to allocate memory from the custom memory pool
void* mempool_alloc(size_t size) {
    // Check if there is enough space in the memory pool
    if (size > MEMORY_POOL_SIZE - used_memory) {
        return NULL;
    }

    // Allocate memory from the memory pool
    void* data = mempool + used_memory;
    used_memory += size;

    return data;
}

// Function to free memory in the custom memory pool
void mempool_free(void* data, size_t size) {
    // Check if the memory is within the memory pool
    if (data < mempool || data >= mempool + MEMORY_POOL_SIZE) {
        return;
    }

    // Free the memory in the memory pool
    used_memory -= size;
}

// Function to initialize the custom memory pool
void init_mempool() {
    // Allocate memory for the memory pool
    mempool = malloc(MEMORY_POOL_SIZE);
    if (!mempool) {
        printf("Error: Failed to allocate memory for the memory pool\n");
        exit(1);
    }

    // Initialize the used memory counter
    used_memory = 0;
}

// Function to deinitialize the custom memory pool
void deinit_mempool() {
    // Free the memory pool
    free(mempool);
