// Custom binary search tree for efficient insertion, deletion, and traversal operations on the records
struct BST {
    struct Node* root;
};

// Function to create a new node in the binary search tree
struct Node* bst_create_node(int value) {
    // Allocate memory for the new node
    struct Node* node = malloc(sizeof(struct Node));
    if (!node) {
        printf("Error: Failed to allocate memory for a new node in the binary search tree\n");
        exit(1);
    }

    // Initialize the node's value and child pointers
    node->value = value;
    node->left = NULL;
    node->right = NULL;

    return node;
}

// Function to insert a new record into the binary search tree
void bst_insert(struct BST* bst, int value) {
    // Create a new node for the record
    struct Node* node = bst_create_node(value);

    // Insert the new node into the binary search tree
    if (bst->root == NULL) {
        bst->root = node;
    } else {
        struct Node* current = bst->root;
        while (1) {
            if (value < current->value) {
