        }
    }
}

// Function to traverse the binary search tree in order
void bst_traverse(struct BST* bst, void (*visit)(int)) {
    // Traverse the binary search tree in order
    struct Node* current = bst->root;
    while (current != NULL) {
        visit(current->value);
        if (current->left != NULL) {
            current = current->left;
        } else if (current->right != NULL) {
            current = current->right;
        } else {
            // No more children, move to the parent node
            while (1) {
                if (current == bst->root) {
                    break;
                }
                if (current->parent->left == current) {
                    current = current->parent;
                    break;
                } else if (current->parent->right == current) {
                    current = current->parent;
                    break;
                } else {
                    // No more children, move to the parent node
                    current = current->parent;
                }
            }
        }
    }
}

// Function to search for a record in the binary search tree
struct Node* bst_search(struct BST* bst, int value) {
    // Find the node with the given value in the binary search tree
    struct Node* current = bst->root;
    while (1) {
        if (value < current->value) {
            if (current->left == NULL) {
                break;
            }
            current = current->left;
        } else if (value > current->value) {
            if (current->right == NULL) {
                break;
            }
            current = current->right;
        } else {
            // Found the node, return it
            return current;
        }
    }
    return NULL;
}

// Function to update a record in the binary search tree
void bst_update(struct BST* bst, int old_value, int new_value) {
    // Find the node with the given value in the binary search tree
    struct Node* current = bst->root;
    while (1) {
        if (old_value < current->value) {
            if (current->left == NULL) {
                break;
            }
            current = current->left;
        } else if (old_value > current->value) {
            if (current->right == NULL) {
                break;
            }
            current = current->right;
        } else {
            // Found the node, update its value and return
            current->value = new_value;
            return;
        }
    }
}

// Function to delete a record from the binary search tree and free its memory
void bst_delete_and_free(struct BST* bst, int value) {
    // Find the node with the given value in the binary search tree
    struct Node* current = bst->root;
    while (1) {
        if (value < current->value) {
            if (current->left == NULL) {
                break;
            }
            current = current->left;
        } else if (value > current->value) {
            if (current->right == NULL) {
                break;
            }
            current = current->right;
        } else {
            // Found the node, delete it and free its memory
            struct Node* parent = current->parent;
            if (current->left != NULL && current->right != NULL) {
                // Node has two children, replace with smallest value in right subtree
                struct Node* smallest = current->right;
                while (smallest->left != NULL) {
                    smallest = smallest->left;
                }
                current->value = smallest->value;
                current = smallest;
            } else if (current->left == NULL && current->right == NULL) {
                // Node has no children, simply remove it
                if (parent->left == current) {
                    parent->left = NULL;
                } else {
                    parent->right = NULL;
                }
            } else if (current->left != NULL && current->right == NULL) {
                // Node has only one child, replace with that child
                if (parent->left == current) {
                    parent->left = current->left;
                } else {
                    parent->right = current->left;
                }
            } else if (current->left == NULL && current->right != NULL) {
                // Node has only one child, replace with that child
                if (parent->left == current) {
                    parent->left = current->right;
                } else {
                    parent->right = current->right;
                }
            }
            free(current);
            break;
        }
    }
