// Define the global variables for the linked list
LIST_NODE *head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
semaphore_t semaphore = SEMAPHORE_INITIALIZER;

// Function to add a new node to the linked list
void addNode(NFAPI_CRC_INDICATION_PDU_T *data) {
    // Create a new node and allocate memory for it
    LIST_NODE *new_node = (LIST_NODE *)malloc(sizeof(LIST_NODE));
    if (!new_node) {
        printf("Error: Failed to allocate memory for the new node\n");
        return;
    }

    // Set the data field of the new node
    new_node->data = data;

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the list is empty
    if (!head) {
        head = new_node;
    } else {
        // Find the last node in the list and add the new node after it
        LIST_NODE *last_node = head;
        while (last_node->next != NULL) {
            last_node = last_node->next;
        }
        last_node->next = new_node;
    }

    // Unlock the mutex and signal the semaphore to release the waiting thread
    pthread_mutex_unlock(&mutex);
    semaphore_signal(&semaphore);
}

// Function to remove a node from the linked list
void removeNode(NFAPI_CRC_INDICATION_PDU_T *data) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Find the node with the matching data field and remove it from the list
    LIST_NODE *node = head;
    while (node != NULL && node->data != data) {
        node = node->next;
    }
    if (node == NULL) {
        printf("Error: Node not found in the linked list\n");
        return;
    }
    if (node == head) {
        head = node->next;
    } else {
        LIST_NODE *prev_node = head;
        while (prev_node->next != node) {
            prev_node = prev_node->next;
        }
        prev_node->next = node->next;
    }

    // Free the memory of the removed node
    free(node);

    // Unlock the mutex and signal the semaphore to release the waiting thread
    pthread_mutex_unlock(&mutex);
    semaphore_signal(&semaphore);
}

// Function to retrieve a node from the linked list
NFAPI_CRC_INDICATION_PDU_T *getNode(RX_UE_INFORMATION_TAG rx_ue_information, RNTI rnti) {
