        return NULL;
    }

    // Unlock the mutex and signal the semaphore to release the waiting thread
    pthread_mutex_unlock(&mutex);
    semaphore_signal(&semaphore);

    return node->data;
}

// Function to validate the integrity of the linked list
void validateList() {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check for cyclic dependencies and prevent circular references
    LIST_NODE *node = head;
    while (node != NULL) {
        if (node->data->rx_ue_information == node->next->data->rx_ue_information && node->data->rnti == node->next->data->rnti) {
            printf("Error: Cyclic dependency found in the linked list\n");
            return;
        }
        node = node->next;
