    pthread_mutex_unlock(&mutex);
    semaphore_signal(&semaphore);
}

// Function to deserialize the linked list from a file in a specified format
void deserializeList(FILE *file) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Read the data of each node from the file and add it to the linked list
    NFAPI_CRC_INDICATION_PDU_T *data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
