#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <limits.h>
#include <errno.h>

// Define the record structure
typedef struct {
    int value;
} Record;

// Define the function to dynamically manage memory for the system
void dynamic_memory_management(int num_vertices, int num_edges) {
    // Allocate memory for the offset and key arrays
    long *offset_array = malloc(num_vertices * sizeof(long));
    int *key_array = malloc(num_edges * sizeof(int));

    // Initialize the offset and key arrays
    for (int i = 0; i < num_vertices; i++) {
        offset_array[i] = 0;
    }
    for (int j = 0; j < num_edges; j++) {
        key_array[j] = 0;
    }

    // Allocate memory for the record structures
    Record *record_array = malloc(num_vertices * sizeof(Record));

    // Initialize the record structures
    for (int i = 0; i < num_vertices; i++) {
        record_array[i].value = 0;
    }

    // Define a linked list to store the records
    struct RecordNode {
        Record *record;
        struct RecordNode *next;
    };
    struct RecordNode *head = NULL;
    struct RecordNode *tail = NULL;

    // Define a custom hash table for quick key-based lookups
    struct HashTableNode {
        int key;
        struct RecordNode *record_node;
        struct HashTableNode *next;
    };
    struct HashTableNode *hash_table[100];

    // Define a function to add a vertex and edge to the graph database
    void add_vertex(int offset, int key) {
        // Check if the offset is within bounds
        if (offset < 0 || offset >= num_vertices) {
            printf("Error: Offset %d is out of bounds\n", offset);
            return;
        }

        // Check if the key is within bounds
        if (key < 0 || key >= num_edges) {
            printf("Error: Key %d is out of bounds\n", key);
            return;
        }

        // Add the vertex and edge to the graph database
        offset_array[offset]++;
        key_array[key]++;

        // Create a new record structure and add it to the linked list
        Record *new_record = malloc(sizeof(Record));
        struct RecordNode *new_node = malloc(sizeof(struct RecordNode));
        new_node->record = new_record;
        new_node->next = NULL;
        if (head == NULL) {
            head = tail = new_node;
        } else {
            tail->next = new_node;
            tail = new_node;
        }

        // Add the vertex and edge to the custom hash table
        struct HashTableNode *new_hash_table_node = malloc(sizeof(struct HashTableNode));
        new_hash_table_node->key = key;
        new_hash_table_node->record_node = new_node;
        new_hash_table_node->next = hash_table[key % 100];
        hash_table[key % 100] = new_hash_table_node;
    }

    // Define a function to remove a vertex and edge from the graph database
    void remove_vertex(int offset, int key) {
        // Check if the offset is within bounds
        if (offset < 0 || offset >= num_vertices) {
            printf("Error: Offset %d is out of bounds\n", offset);
            return;
        }

        // Check if the key is within bounds
        if (key < 0 || key >= num_edges) {
            printf("Error: Key %d is out of bounds\n", key);
            return;
        }

        // Remove the vertex and edge from the graph database
        offset_array[offset]--;
        key_array[key]--;

        // Find the record structure in the linked list
        struct RecordNode *record_node = hash_table[key % 100];
        while (record_node != NULL && record_node->record->value != offset) {
            record_node = record_node->next;
        }

        // Remove the record structure from the linked list and free its memory
        if (record_node == NULL) {
            printf("Error: Record structure for vertex %d not found\n", offset);
            return;
        } else {
            struct RecordNode *prev = record_node->next;
            free(record_node->record);
            free(record_node);
            if (head == tail) {
                head = tail = NULL;
            } else {
                head = prev;
            }
        }

        // Remove the vertex and edge from the custom hash table
        struct HashTableNode *hash_table_node = hash_table[key % 100];
        while (hash_table_node != NULL && hash_table_node->record_node->record->value != offset) {
            hash_table_node = hash_table_node->next;
        }

        // Remove the record structure from the custom hash table and free its memory
        if (hash_table_node == NULL) {
            printf("Error: Record structure for vertex %d not found\n", offset);
            return;
        } else {
            struct HashTableNode *prev = hash_table_node->next;
            free(hash_table_node->record_node->record);
            free(hash_table_node->record_node);
            if (head == tail) {
                head = tail = NULL;
            } else {
                head = prev;
            }
        }
    }

    // Define a function to update the properties of a vertex in the graph database
    void update_properties(int offset, int key, int value) {
        // Check if the offset is within bounds
        if (offset < 0 || offset >= num_vertices) {
            printf("Error: Offset %d is out of bounds\n", offset);
            return;
        }

        // Check if the key is within bounds
        if (key < 0 || key >= num_edges) {
            printf("Error: Key %d is out of bounds\n", key);
            return;
        }

        // Update the properties of the vertex in the graph database
        offset_array[offset] = value;
        key_array[key] = value;

        // Find the record structure in the linked list
        struct RecordNode *record_node = hash_table[key % 100];
        while (record_node != NULL && record_node->record->value != offset) {
            record_node = record_node->next;
        }

        // Update the properties of the record structure and free its memory if it is no longer needed
        if (record_node == NULL) {
            printf("Error: Record structure for vertex %d not found\n", offset);
            return;
        } else {
            record_node->record->value = value;
            if (offset_array[offset] == 0 && key_array[key] == 0) {
                struct RecordNode *prev = record_node->next;
                free(record_node->record);
                free(record_node);
                if (head == tail) {
                    head = tail = NULL;
                } else {
                    head = prev;
                }
            }
        }
    }
}
