// Define the record structure
typedef struct {
    int key;
    float weight;
    char status;
} Record;

// Define the hash table structure
typedef struct {
    int size;
    int capacity;
    Record** records;
} HashTable;

// Define the doubly linked list structure
typedef struct Node {
    Record* record;
    struct Node* next;
    struct Node* prev;
} Node;

// Define the custom thread pool structure
typedef struct {
    int size;
    pthread_t* threads;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} ThreadPool;

// Define the memory cache structure
typedef struct {
    Record** records;
    int capacity;
    int size;
