    ht->capacity = size;
    ht->records = (Record**)calloc(size, sizeof(Record*));
    if (!ht->records) {
        free(ht);
        return NULL;
    }
    return ht;
}

// Function to initialize the doubly linked list
Node* init_doubly_linked_list() {
    Node* head = (Node*)malloc(sizeof(Node));
    if (!head) {
        return NULL;
    }
    head->record = NULL;
    head->next = NULL;
    head->prev = NULL;
    return head;
}

// Function to initialize the custom thread pool
ThreadPool* init_thread_pool(int size) {
    ThreadPool* tp = (ThreadPool*)malloc(sizeof(ThreadPool));
    if (!tp) {
        return NULL;
