    pthread_cond_init(&tp->cond, NULL);
    return tp;
}

// Function to initialize the memory cache
MemoryCache* init_memory_cache(int capacity) {
    MemoryCache* mc = (MemoryCache*)malloc(sizeof(MemoryCache));
    if (!mc) {
        return NULL;
    }
    mc->capacity = capacity;
    mc->size = 0;
    mc->records = (Record**)calloc(capacity, sizeof(Record*));
    if (!mc->records) {
        free(mc);
        return NULL;
    }
    return mc;
}

// Function to insert a record into the hash table and doubly linked list
int insert_record(HashTable* ht, Node* head, Record* record) {
    // Check if the hash table is full
    if (ht->size == ht->capacity) {
        return -1;
    }
    // Insert the record into the hash table
    int index = record->key % ht->capacity;
    while (ht->records[index] != NULL && ht->records[index]->key != record->key) {
        index++;
        if (index == ht->capacity) {
            index = 0;
        }
    }
    if (ht->records[index] == NULL) {
        ht->records[index] = record;
        ht->size++;
    } else {
        return -2;
    }
    // Insert the record into the doubly linked list
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        return -3;
    }
    node->record = record;
    node->next = head->next;
    node->prev = head;
    head->next->prev = node;
    head->next = node;
    return 0;
}

// Function to delete a record from the hash table and doubly linked list
int delete_record(HashTable* ht, Node* head, int key) {
    // Check if the hash table is empty
    if (ht->size == 0) {
        return -1;
    }
    // Find the record in the hash table
    int index = key % ht->capacity;
    while (ht->records[index] != NULL && ht->records[index]->key != key) {
