    ht->records[index] = record;
    // Update the record in the doubly linked list
    Node* node = head->next;
    while (node != head && node->record->key != record->key) {
        node = node->next;
    }
    if (node == head) {
        return -3;
    }
    node->record = record;
    return 0;
}

// Function to traverse the doubly linked list in forward direction
void traverse_forward(Node* head, void (*visit)(Record*)) {
    Node* node = head->next;
    while (node != head) {
        visit(node->record);
        node = node->next;
    }
}

// Function to traverse the doubly linked list in backward direction
void traverse_backward(Node* head, void (*visit)(Record*)) {
    Node* node = head->prev;
    while (node != head) {
        visit(node->record);
        node = node->prev;
    }
}

// Function to resize the hash table and doubly linked list
void resize_hash_table(HashTable* ht, Node* head, int new_size) {
    // Create a new hash table with the new size
    HashTable* new_ht = init_hash_table(new_size);
    if (!new_ht) {
        return;
    }
    // Copy the records from the old hash table to the new one
    for (int i = 0; i < ht->capacity; i++) {
        Record* record = ht->records[i];
        if (record != NULL) {
            insert_record(new_ht, head, record);
        }
    }
    // Free the old hash table and doubly linked list
    free(ht->records);
    free(ht);
    ht = new_ht;
}

// Function to resize the memory cache
void resize_memory_cache(MemoryCache* mc, int new_capacity) {
    // Create a new memory cache with the new capacity
    MemoryCache* new_mc = init_memory_cache(new_capacity);
    if (!new_mc) {
        return;
    }
    // Copy the records from the old memory cache to the new one
    for (int i = 0; i < mc->size; i++) {
        Record* record = mc->records[i];
        if (record != NULL) {
            insert_record(new_mc, head, record);
        }
    }
    // Free the old memory cache
    free(mc->records);
    free(mc);
    mc = new_mc;
}

// Function to check and release unused memory blocks
void check_and_release_memory() {
    // Check if there are any unused memory blocks
    if (ht->size == 0) {
        return;
    }
    // Release the unused memory blocks
    for (int i = 0; i < ht->capacity; i++) {
        Record* record = ht->records[i];
        if (record != NULL && record->status == 'U') {
            free(record);
            ht->records[i] = NULL;
        }
    }
}

