#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <net/if.h>
#include <errno.h>

// Custom routing table for fast route lookups based on destination IP addresses
struct route_table {
    struct in_addr dest;
    struct in_addr gateway;
};

// Linked list of network interfaces with their configurations
struct network_interface {
    char *ip_address;
    char *subnet_mask;
    char *dns_server;
    int mtu;
    bool dns_enabled;
    bool flow_control_enabled;
    struct network_interface *next;
};

// Function to configure a network interface with the given IP address and subnet mask
int configure_network_adapter(char *ip_address, char *subnet_mask) {
    // Check if the input parameters are valid
    if (ip_address == NULL || subnet_mask == NULL) {
        printf("Invalid input parameters\n");
        return -1;
    }

    // Convert the IP address and subnet mask to binary format
    struct in_addr ip, subnet;
    if (inet_pton(AF_INET, ip_address, &ip) != 1 || inet_pton(AF_INET, subnet_mask, &subnet) != 1) {
        printf("Invalid IP address or subnet mask\n");
        return -1;
    }

    // Get the interface index for the given IP address
    int ifindex = if_nametoindex(ip_address);
    if (ifindex == 0) {
        printf("Failed to get interface index for %s\n", ip_address);
        return -1;
    }

    // Get the current network configuration for the interface
    struct ifreq ifr;
    memset(&ifr, 0, sizeof(struct ifreq));
    strncpy(ifr.ifr_name, ip_address, IFNAMSIZ-1);
    if (ioctl(sockfd, SIOCGIFADDR, &ifr) < 0) {
        printf("Failed to get current network configuration for %s\n", ip_address);
        return -1;
    }

    // Update the IP address and subnet mask in the interface configuration
    struct sockaddr_in *sin = (struct sockaddr_in *)&ifr.ifr_addr;
    sin->sin_family = AF_INET;
    sin->sin_addr.s_addr = ip.s_addr;
    sin->sin_mask = subnet.s_addr;

    // Enable DNS resolution if requested
    if (dns_enabled) {
        struct in_addr dns_server;
        if (inet_pton(AF_INET, dns_server, &dns_server) != 1) {
            printf("Invalid DNS server address\n");
            return -1;
        }
        sin->sin_dns = dns_server.s_addr;
    } else {
        sin->sin_dns = 0;
    }

    // Enable flow control if requested
    if (flow_control_enabled) {
        struct in_addr flow_control_address;
        if (inet_pton(AF_INET, flow_control_address, &flow_control_address) != 1) {
            printf("Invalid flow control address\n");
            return -1;
        }
        sin->sin_flow = flow_control_address.s_addr;
    } else {
        sin->sin_flow = 0;
    }

    // Set the MTU if requested
    if (mtu > 0) {
        struct in_addr mtu_address;
        if (inet_pton(AF_INET, mtu_address, &mtu_address) != 1) {
            printf("Invalid MTU address\n");
            return -1;
        }
        sin->sin_mtu = mtu_address.s_addr;
    } else {
        sin->sin_mtu = 0;
    }

    // Apply the new network configuration to the interface
    if (ioctl(sockfd, SIOCSIFADDR, &ifr) < 0) {
        printf("Failed to apply new network configuration for %s\n", ip_address);
        return -1;
    }

    // Update the routing table with the new gateway
    struct route_table *rt = (struct route_table *)malloc(sizeof(struct route_table));
    rt->dest = ip;
    rt->gateway = subnet;
    add_route(rt);

    return 0;
}

// Function to add a new network interface with the given configuration
int add_network_interface(char *ip_address, char *subnet_mask) {
    // Check if the input parameters are valid
    if (ip_address == NULL || subnet_mask == NULL) {
        printf("Invalid input parameters\n");
        return -1;
    }

    // Create a new network interface with the given configuration
    struct network_interface *ni = (struct network_interface *)malloc(sizeof(struct network_interface));
    ni->ip_address = ip_address;
    ni->subnet_mask = subnet_mask;
    ni->dns_enabled = false;
    ni->flow_control_enabled = false;
    ni->mtu = 0;
    ni->next = NULL;

    // Add the new network interface to the linked list of interfaces
    if (interfaces == NULL) {
        interfaces = ni;
    } else {
        struct network_interface *tmp = interfaces;
        while (tmp->next != NULL) {
            tmp = tmp->next;
        }
        tmp->next = ni;
    }

    return 0;
}

// Function to remove a network interface with the given IP address
int remove_network_interface(char *ip_address) {
    // Check if the input parameters are valid
    if (ip_address == NULL) {
        printf("Invalid input parameters\n");
        return -1;
    }

    // Find the network interface with the given IP address in the linked list of interfaces
    struct network_interface *tmp = interfaces;
    while (tmp != NULL && strcmp(tmp->ip_address, ip_address) != 0) {
        tmp = tmp->next;
    }

    // Remove the network interface from the linked list of interfaces
    if (tmp == NULL) {
        printf("Network interface not found\n");
        return -1;
    } else {
        struct network_interface *prev = NULL;
        while (tmp != NULL && strcmp(tmp->ip_address, ip_address) == 0) {
            prev = tmp;
            tmp = tmp->next;
        }
        if (prev == NULL) {
            interfaces = tmp;
        } else {
            prev->next = tmp;
        }
    }

    return 0;
}

// Function to iterate over the linked list of network interfaces and apply the given configuration
int configure_network_interfaces(char *ip_address, char *subnet_mask) {
    // Check if the input parameters are valid
    if (ip_address == NULL || subnet_mask == NULL) {
        printf("Invalid input parameters\n");
        return -1;
    }

    // Convert the IP address and subnet mask to binary format
    struct in_addr ip, subnet;
    if (inet_pton(AF_INET, ip_address, &ip) != 1 || inet_pton(AF_INET, subnet_mask, &subnet) != 1) {
        printf("Invalid IP address or subnet mask\n");
        return -1;
    }

    // Iterate over the linked list of network interfaces and apply the given configuration
    struct network_interface *tmp = interfaces;
    while (tmp != NULL) {
        if (strcmp(tmp->ip_address, ip_address) == 0) {
            tmp->subnet_mask = subnet_mask;
            break;
        }
        tmp = tmp->next;
    }

    return 0;
}

// Function to handle edge cases such as invalid IP formats, unsupported MTU values, and null pointers
int handle_edge_cases(char *ip_address, char *subnet_mask) {
    // Check if the input parameters are valid
    if (ip_address == NULL || subnet_mask == NULL) {
        printf("Invalid input parameters\n");
        return -1;
    }

    // Convert the IP address and subnet mask to binary format
    struct in_addr ip, subnet;
    if (inet_pton(AF_INET, ip_address, &ip) != 1 || inet_pton(AF_INET, subnet_mask, &subnet) != 1) {
        printf("Invalid IP address or subnet mask\n");
        return -1;
    }

    // Check if the MTU value is supported by the system
    int mtu = atoi(mtu_address);
    if (mtu < 0 || mtu > 65535) {
        printf("Unsupported MTU value\n");
        return -1;
    }

    // Check if the input parameters are null pointers
    if (ip_address == NULL || subnet_mask == NULL) {
        printf("Invalid input parameters\n");
        return -1;
    }

    return 0;
}
