    int value;
} data_item;

data_item* process_and_transform_data(data_item* data, size_t num_items, bool case_insensitive, bool sort_descending, int min_value, int max_value) {
    // Check for invalid input
    if (data == NULL || num_items == 0) {
        return NULL;
    }

    // Allocate memory for the transformed data
    size_t transformed_size = num_items * sizeof(data_item);
    data_item* transformed_data = malloc(transformed_size);
    if (transformed_data == NULL) {
        free(data);
        return NULL;
    }

    // Sort the data in ascending order based on the numeric value
    qsort(data, num_items, sizeof(data_item), compare_data_items);

    // Filter out items whose numeric values fall outside the specified range
    size_t filtered_size = 0;
    for (size_t i = 0; i < num_items; ++i) {
        if (data[i].value >= min_value && data[i].value <= max_value) {
            transformed_data[filtered_size++] = data[i];
        }
    }

    // Transform the text in each item to be either lowercase or uppercase based on user preference
    for (size_t i = 0; i < filtered_size; ++i) {
        if (case_insensitive) {
            transformed_data[i].text = strdup(transformed_data[i].text);
            transformed_data[i].text = strtolower(transformed_data[i].text);
        } else {
            transformed_data[i].text = strdup(transformed_data[i].text);
            transformed_data[i].text = strupper(transformed_data[i].text);
        }
    }

    // Free the original data and return the transformed data
    free(data);
    return transformed_data;
}

// Custom compare function for sorting data items based on numeric value
int compare_data_items(const void* a, const void* b) {
    const data_item* item1 = (const data_item*)a;
    const data_item* item2 = (const data_item*)b;
    return item1->value - item2->value;
}
