        memoryPool = malloc(sizeof(struct MemoryPool));
        memoryPool->memory = malloc(INITIAL_SIZE);
        memoryPool->size = INITIAL_SIZE;
        memoryPool->used = 0;
    } else if (hashTable->size == memoryPool->size) {
        // Reallocate memory pool for records
        memoryPool->memory = realloc(memoryPool->memory, memoryPool->size * 2);
        memoryPool->size *= 2;
    }

    // Deletion
    if (hashTable->size > 0) {
        // Free unused memory blocks in memory pool
        for (int i = 0; i < hashTable->size; i++) {
            if (hashTable->nodes[i] == NULL) {
                free(memoryPool->memory + i * sizeof(struct Node));
            }
        }
    }

    // Traversal
