    if (memory == NULL) {
        return NULL;
    }

    // Update used memory in memory pool
    memoryPool->used += sizeof(struct Node);

    return memory;
}

// Custom hash table implementation for quick key-based lookups
void insertRecord(struct HashTable* hashTable, int key, long offset) {
    // Calculate hash value for key
    int hashValue = key % hashTable->size;

    // Check if record already exists in hash table
    struct Node* node = hashTable->nodes[hashValue];
    while (node != NULL && node->key != key) {
        node = node->next;
    }

    // Insert new record into hash table
    if (node == NULL) {
        node = allocateMemory(memoryPool);
        node->offset = offset;
        node->key = key;
        node->value = malloc(sizeof(int));
        *(int*)node->value = 0;
        node->next = hashTable->nodes[hashValue];
        hashTable->nodes[hashValue] = node;
    } else {
        // Update existing record in hash table
        node->offset = offset;
    }
}

