    // Release unused memory blocks in memory pool
    for (int i = 0; i < hashTable->size; i++) {
        if (hashTable->nodes[i] == NULL) {
            freeMemory(memoryPool, memoryPool->memory + i * sizeof(struct Node));
        }
    }
