    // Calculate hash value for key
    int hashValue = key % hashTable->size;

    // Check if record exists in hash table
    struct Node* node = hashTable->nodes[hashValue];
    while (node != NULL && node->key != key) {
        node = node->next;
    }

    // Return record from hash table
    return node == NULL ? NULL : node->value;
}

