void* reallocateMemory(struct MemoryPool* memoryPool, size_t newSize) {
    // Reallocate memory pool for records
    void* newMemory = malloc(newSize);
    if (newMemory == NULL) {
        return NULL;
    }

    // Copy data from old memory pool to new memory pool
    memcpy(newMemory, memoryPool->memory, memoryPool->used);

    // Free old memory pool
    free(memoryPool->memory);

    // Update memory pool with new memory and size
    memoryPool->memory = newMemory;
    memoryPool->size = newSize;

    return newMemory;
}
