HashTable* create_hash_table(int size) {
    HashTable* ht = malloc(sizeof(HashTable));
    assert(ht != NULL);
    ht->size = size;
    ht->count = 0;
    ht->keys = calloc(size, sizeof(char*));
    assert(ht->keys != NULL);
    ht->values = calloc(size, sizeof(void*));
    assert(ht->values != NULL);
    return ht;
}

// Function to insert a new node into the hash table
int insert_node(HashTable* ht, Node* node) {
    int index = get_hash_index(node->str);
    if (ht->count == ht->size) {
