        resize_hash_table(ht);
    }
    ht->keys[index] = node->str;
    ht->values[index] = node;
    ht->count++;
    return 0;
}

// Function to delete a node from the hash table
int delete_node(HashTable* ht, Node* node) {
    int index = get_hash_index(node->str);
    if (ht->values[index] == NULL) {
        return -1; // Node not found
    }
    ht->keys[index] = NULL;
    ht->values[index] = NULL;
    ht->count--;
    return 0;
}

