    return ht->values[index];
}

// Function to resize the hash table when it's full
void resize_hash_table(HashTable* ht) {
    int new_size = ht->size * 2;
    HashTable* new_ht = create_hash_table(new_size);
    for (int i = 0; i < ht->count; i++) {
        char* key = ht->keys[i];
        Node* value = ht->values[i];
        insert_node(new_ht, value);
    }
    free(ht->keys);
    free(ht->values);
    ht->size = new_size;
    ht->count = new_ht->count;
    ht->keys = new_ht->keys;
    ht->values = new_ht->values;
}

// Function to get the hash index for a given string identifier
int get_hash_index(char* str) {
    int hash = 0;
    for (int i = 0; i < strlen(str); i++) {
        hash += str[i];
    }
    return hash % ht->size;
}

// Function to create a new node with a given double precision floating-point value and string identifier
