    Node* current = head;
    while (current != NULL) {
        printf("%d\n", current->record.value);
        current = current->next;
    }
}

// Define functions for managing memory allocation and deallocation
void* allocate(size_t size) {
    // Allocate memory from the custom memory pool
    MemoryPool* memory_pool = get_memory_pool();
    void* memory = malloc(size);
    if (memory == NULL) {
        return NULL;
    }
    memory_pool->memory = memory;
    memory_pool->size += size;
    return memory;
}

void deallocate(void* memory) {
    // Deallocate memory from the custom memory pool
    MemoryPool* memory_pool = get_memory_pool();
    free(memory);
    memory_pool->size -= sizeof(Node);
}

// Define functions for managing checkpointing to a persistent storage medium
void checkpoint() {
    // Write the linked list and hash table to disk asynchronously
    Node* current = head;
    while (current != NULL) {
        write_to_disk(current->record.value);
        current = current->next;
    }
}

void restore() {
    // Read the linked list and hash table from disk asynchronously
    Node* current = head;
    while (current != NULL) {
        read_from_disk(&(current->record.value));
        current = current->next;
    }
}

// Define functions for managing memory fragmentation
void defragment() {
    // Implement a custom memory pool to manage memory allocation and deallocation
    MemoryPool* memory_pool = get_memory_pool();
    void* memory = malloc(sizeof(Node));
    if (memory == NULL) {
        return;
    }
    memory_pool->memory = memory;
    memory_pool->size += sizeof(Node);
}

