#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Custom hash table implementation for fast lookups and ordered access
struct hash_table {
    int size;
    struct entry **entries;
};

struct entry {
    char *key;
    void *value;
};

void init_hash_table(struct hash_table *ht, int size) {
    ht->size = size;
    ht->entries = malloc(sizeof(struct entry *) * size);
}

void insert_entry(struct hash_table *ht, char *key, void *value) {
    struct entry *e = malloc(sizeof(struct entry));
    e->key = key;
    e->value = value;
    int index = hash(key) % ht->size;
    ht->entries[index] = e;
}

void *lookup_entry(struct hash_table *ht, char *key) {
    int index = hash(key) % ht->size;
    struct entry *e = ht->entries[index];
    while (e != NULL && strcmp(e->key, key) != 0) {
        e = e->next;
    }
    return e ? e->value : NULL;
}

// Custom binary tree implementation for efficient range queries on registration number and maintenance date attributes
struct node {
    struct node *left;
    struct node *right;
    void *data;
};

void init_tree(struct node **root) {
    *root = NULL;
}

void insert_node(struct node **root, void *data) {
    if (*root == NULL) {
        *root = malloc(sizeof(struct node));
        (*root)->left = NULL;
        (*root)->right = NULL;
        (*root)->data = data;
    } else {
        struct node **current = root;
        while (*current != NULL) {
            if (compare_data((*current)->data, data) > 0) {
                current = &(*current)->left;
            } else {
                current = &(*current)->right;
            }
        }
        *current = malloc(sizeof(struct node));
        (*current)->left = NULL;
        (*current)->right = NULL;
        (*current)->data = data;
    }
}

void *search_node(struct node **root, void *data) {
    if (*root == NULL) {
        return NULL;
    } else {
        struct node **current = root;
        while (*current != NULL && compare_data((*current)->data, data) != 0) {
            if (compare_data((*current)->data, data) > 0) {
                current = &(*current)->left;
            } else {
                current = &(*current)->right;
            }
        }
        return *current ? (*current)->data : NULL;
    }
}

