    if (!arr) {
        printf("Error: unable to allocate memory for array\n");
        return NULL;
    }
    return arr;
}

// Define a function to calculate and print the mean and standard deviation of an array of floating-point numbers
void calculate_statistics(float* arr, int n) {
    float sum = 0.0f;
    for (int i = 0; i < n; i++) {
        sum += arr[i];
    }
    float mean = sum / n;
    float variance = 0.0f;
    for (int i = 0; i < n; i++) {
        variance += pow(arr[i] - mean, 2);
    }
    variance /= n - 1;
    float stddev = sqrt(variance);
    printf("Mean: %f\n", mean);
    printf("Standard Deviation: %f\n", stddev);
}

