use std::fs;
use std::path::PathBuf;
use std::time::{SystemTime, UNIX_EPOCH};
use std::sync::Mutex;
use std::collections::HashMap;

struct DirectoryCreator {
    whitelist: Vec<char>,
    separator: char,
    default_separator: char,
    timestamp_format: &'static str,
    lock_manager: Mutex<()>,
    directory_map: HashMap<PathBuf, u64>,
}

impl DirectoryCreator {
    fn new(whitelist: Vec<char>, separator: char, default_separator: char, timestamp_format: &'static str) -> Self {
        Self {
            whitelist,
            separator,
            default_separator,
            timestamp_format,
            lock_manager: Mutex::new(()),
            directory_map: HashMap::new(),
        }
    }

    fn create_directory(&self, path: &PathBuf) -> Result<(), String> {
        let mut locked = self.lock_manager.lock().unwrap();
        if !path.exists() {
            // Check if the parent directory exists and create it if necessary
            if let Some(parent) = path.parent() {
                if !parent.exists() {
                    fs::create_dir_all(parent).map_err(|e| format!("Failed to create parent directory: {}", e))?;
                }
            }

            // Sanitize the directory name and append a default separator if necessary
            let mut sanitized_name = String::new();
            for c in path.file_name().unwrap().to_str().unwrap().chars() {
                if self.whitelist.contains(&c) {
                    sanitized_name.push(c);
                } else {
                    sanitized_name.push(self.default_separator);
                }
            }

            // Append a timestamp to ensure uniqueness if the directory already exists
            let mut timestamp = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
            while self.directory_map.contains_key(&PathBuf::from(format!("{}{}", sanitized_name, self.separator))) {
                sanitized_name.push_str(&self.timestamp_format.replace("{}", &timestamp.as_millis().to_string()));
                timestamp += Duration::from_millis(1);
            }

            // Create the directory and log its creation status
            let result = fs::create_dir(path).map_err(|e| format!("Failed to create directory: {}", e))?;
            self.directory_map.insert(path.clone(), timestamp.as_millis());
            if result {
                info!("Created directory {}", path.display());
            } else {
                warn!("Failed to create directory {}", path.display());
            }
        }

        Ok(())
    }
}
```
