// Define the record structure
typedef struct {
    long offset;
    int key;
    double value;
    char name[16];
} Record;

// Define the memory container for records
typedef struct {
    size_t capacity; // Maximum number of records that can be stored
    size_t count; // Current number of records stored
    Record* records; // Array of record structures
} MemoryContainer;

// Function to generate a unique composite key for a record
int generateKey(Record* record) {
    int key = 0;
    while (key == 0 || key > INT_MAX) {
        key = rand() % INT_MAX; // Generate a random integer between 1 and INT_MAX
    }
    return key;
}

// Function to add a new record to the memory container
void addRecord(MemoryContainer* container, Record* record) {
    if (container->count == container->capacity) { // Check if the container is full
        printf("Error: Memory container is full. Cannot add new record.\n");
        return;
    }
    int key = generateKey(record); // Generate a unique composite key for the record
    while (keyExists(container, key)) { // Check if the generated key already exists in the container
        key = generateKey(record); // Retry generating a new key until successful
    }
    record->key = key; // Set the record's key to the generated key
    container->records[container->count++] = *record; // Add the record to the container
}

// Function to check if a key already exists in the memory container
int keyExists(MemoryContainer* container, int key) {
    for (size_t i = 0; i < container->count; i++) {
        if (container->records[i].key == key) { // Check if the key already exists in the container
            return 1;
        }
    }
    return 0;
}

// Function to remove a record from the memory container
void removeRecord(MemoryContainer* container, int key) {
    for (size_t i = 0; i < container->count; i++) {
        if (container->records[i].key == key) { // Find the index of the record to be removed
            container->count--; // Decrement the number of records stored in the container
            for (size_t j = i; j < container->count; j++) { // Shift all records after the removed record to fill the gap
                container->records[j] = container->records[j + 1];
            }
            break;
        }
    }
}

// Function to retrieve a record from the memory container by key
Record* getRecord(MemoryContainer* container, int key) {
    for (size_t i = 0; i < container->count; i++) {
        if (container->records[i].key == key) { // Find the index of the record to be retrieved
            return &container->records[i]; // Return a pointer to the record
        }
    }
    return NULL; // If the record is not found, return NULL
}

// Function to modify a record in the memory container by key
void modifyRecord(MemoryContainer* container, int key, Record* new_record) {
    for (size_t i = 0; i < container->count; i++) {
        if (container->records[i].key == key) { // Find the index of the record to be modified
            container->records[i] = *new_record; // Replace the old record with the new one
            break;
        }
    }
}

// Function to free all memory allocated by the memory container
void freeMemoryContainer(MemoryContainer* container) {
    for (size_t i = 0; i < container->count; i++) {
        free(container->records[i].name); // Free the name array of each record
    }
    free(container->records); // Free the array of records
}

// Function to handle memory allocation failures gracefully
void handleMemoryAllocationFailure() {
    printf("Error: Memory allocation failed. Exiting.\n");
    exit(1);
}

// Main function for testing the memory container
int main() {
    // Initialize the memory container with a capacity of 10 records
    MemoryContainer* container = (MemoryContainer*) malloc(sizeof(MemoryContainer));
    if (!container) {
        handleMemoryAllocationFailure();
    }
    container->capacity = 10;
    container->count = 0;
    container->records = (Record*) malloc(container->capacity * sizeof(Record));
    if (!container->records) {
        handleMemoryAllocationFailure();
    }

    // Add some records to the memory container
    Record record1 = {0, 1, 2.3, "record1"};
    addRecord(container, &record1);
    Record record2 = {0, 4, 5.6, "record2"};
    addRecord(container, &record2);
    Record record3 = {0, 7, 8.9, "record3"};
    addRecord(container, &record3);

    // Retrieve and modify a record in the memory container
    Record* retrieved_record = getRecord(container, 1);
    if (retrieved_record) {
        retrieved_record->value += 1.0;
        modifyRecord(container, 1, retrieved_record);
    }

    // Remove a record from the memory container
    removeRecord(container, 4);

    // Free all memory allocated by the memory container
    freeMemoryContainer(container);

    return 0;
}
```
This code defines a `MemoryContainer` structure that stores an array of `Record` structures. The `addRecord` function adds a new record to the container, while the `removeRecord` function removes a record by its key. The `getRecord` function retrieves a record from the container by its key, and the `modifyRecord` function modifies a record in the container by replacing it with a new one.

The `generateKey` function generates a unique composite key for a record using the `int`, `double`, and `char` components of the record. The function uses a random number generator to generate a random integer between 1 and `INT_MAX`, which is then used as the key. If the generated key already exists in the container, the function retries generating a new key until successful.

The `keyExists` function checks if a key already exists in the container by iterating through all records and checking if their keys match the given key. The function returns 1 if the key is found, or 0 otherwise.

The `freeMemoryContainer` function frees all memory allocated by the memory container by freeing each record's name array and then freeing the array of records itself.

The `handleMemoryAllocationFailure` function handles memory allocation failures by printing an error message and exiting the program with a non-zero status code.

The main function tests the memory container by adding, retrieving, modifying, and removing records, and then freeing all memory allocated by the container.']

