// Define the structure for a record in the data management system
typedef struct {
    int id;
    float value;
    char *str;
    time_t timestamp;
} Record;

// Define the hash table for efficient key-based lookups
typedef struct {
    int size;
    int count;
    Record **records;
} HashTable;

// Define the linked list to maintain insertion order
typedef struct {
    Record *record;
    struct Node *next;
} LinkedList;

// Define the custom balanced tree structure for quick key-based searches on the character string field
typedef struct {
    int size;
    int count;
    char **keys;
    Record **records;
} BalancedTree;

// Function to initialize a dynamic array of records using a hash table and linked list
void init_records(HashTable *hash_table, LinkedList *linked_list) {
    // Initialize the hash table with an initial size of 1024
    hash_table->size = 1024;
    hash_table->count = 0;
    hash_table->records = (Record **)malloc(hash_table->size * sizeof(Record *));
    memset(hash_table->records, 0, hash_table->size * sizeof(Record *));

    // Initialize the linked list with an initial size of 1024
    linked_list->size = 1024;
    linked_list->count = 0;
    linked_list->next = (LinkedList *)malloc(linked_list->size * sizeof(LinkedList));
    memset(linked_list->next, 0, linked_list->size * sizeof(LinkedList));
}

// Function to add a record to the data management system
void add_record(HashTable *hash_table, LinkedList *linked_list, Record *record) {
    // Check if the hash table is full and needs to be resized
    if (hash_table->count == hash_table->size) {
        resize_hash_table(hash_table);
    }

    // Add the record to the hash table
    int index = hash_function(record->id);
    hash_table->records[index] = record;
    hash_table->count++;

    // Add the record to the linked list
    LinkedList *node = (LinkedList *)malloc(sizeof(LinkedList));
    node->record = record;
    node->next = linked_list->next;
    linked_list->next = node;
    linked_list->count++;
}

// Function to update a record in the data management system
void update_record(HashTable *hash_table, LinkedList *linked_list, Record *record) {
    // Check if the hash table is full and needs to be resized
    if (hash_table->count == hash_table->size) {
        resize_hash_table(hash_table);
    }

    // Update the record in the hash table
    int index = hash_function(record->id);
    hash_table->records[index] = record;

    // Update the record in the linked list
    LinkedList *node = linked_list->next;
    while (node != NULL) {
        if (node->record->id == record->id) {
            node->record = record;
            break;
        }
        node = node->next;
    }
}

// Function to retrieve a record from the data management system
Record *get_record(HashTable *hash_table, LinkedList *linked_list, int id) {
    // Check if the hash table is empty
    if (hash_table->count == 0) {
        return NULL;
    }

    // Retrieve the record from the hash table
    int index = hash_function(id);
    Record *record = hash_table->records[index];
    if (record != NULL && record->id == id) {
        return record;
    }

    // Retrieve the record from the linked list
    LinkedList *node = linked_list->next;
    while (node != NULL) {
        if (node->record->id == id) {
            return node->record;
        }
        node = node->next;
    }

    // Return NULL if the record is not found
    return NULL;
}

// Function to remove a record from the data management system
void remove_record(HashTable *hash_table, LinkedList *linked_list, int id) {
    // Check if the hash table is empty
    if (hash_table->count == 0) {
        return;
    }

    // Remove the record from the hash table
    int index = hash_function(id);
    Record *record = hash_table->records[index];
    if (record != NULL && record->id == id) {
        hash_table->count--;
        hash_table->records[index] = NULL;
    }

    // Remove the record from the linked list
    LinkedList *node = linked_list->next;
    while (node != NULL) {
        if (node->record->id == id) {
            node->next = node->next->next;
            break;
        }
        node = node->next;
    }
}

// Function to resize the hash table when it is full
void resize_hash_table(HashTable *hash_table) {
    // Double the size of the hash table
    int new_size = hash_table->size * 2;
    Record **new_records = (Record **)malloc(new_size * sizeof(Record *));
    memset(new_records, 0, new_size * sizeof(Record *));

    // Copy the records from the old hash table to the new one
    for (int i = 0; i < hash_table->size; i++) {
        Record *record = hash_table->records[i];
        if (record != NULL) {
            int index = hash_function(record->id);
            new_records[index] = record;
        }
    }

    // Update the hash table with the new records and size
    free(hash_table->records);
    hash_table->size = new_size;
    hash_table->records = new_records;
}

// Function to balance the memory usage of the custom balanced tree structure
void balance_tree(BalancedTree *tree) {
    // Check if the tree is empty
    if (tree->count == 0) {
        return;
    }

    // Balance the tree by removing unused keys and records
    int new_size = tree->size / 2;
    char **new_keys = (char **)malloc(new_size * sizeof(char *));
    memset(new_keys, 0, new_size * sizeof(char *));
    Record **new_records = (Record **)malloc(new_size * sizeof(Record *));
    memset(new_records, 0, new_size * sizeof(Record *));

    // Copy the keys and records from the old tree to the new one
    for (int i = 0; i < tree->size; i++) {
        char *key = tree->keys[i];
        Record *record = tree->records[i];
        if (key != NULL && record != NULL) {
            int index = hash_function(key);
            new_keys[index] = key;
            new_records[index] = record;
        }
    }

    // Update the tree with the new keys and records
    free(tree->keys);
    free(tree->records);
    tree->size = new_size;
    tree->keys = new_keys;
    tree->records = new_records;
