#include <stdlib.h>
#include <stdio.h>
#include <math.h>

// Define a struct for representing points with x and y coordinates
struct point {
    int x;
    int y;
};

// Define a struct for representing colors with RGB components
struct color {
    unsigned char r;
    unsigned char g;
    unsigned char b;
};

// Function to calculate the Euclidean distance from the origin (0, 0) for a given point
double euclidean_distance(struct point p) {
    return sqrt((p.x * p.x) + (p.y * p.y));
}

// Function to dynamically allocate memory for and initialize three arrays: one for 'double' precision floating-point numbers, another for 'char' data, and a third for 'struct point' objects
void* init_arrays(int num_points) {
    // Calculate the total size of the memory block needed to store the arrays
    int total_size = (num_points * sizeof(double)) + (num_points * sizeof(char)) + (num_points * sizeof(struct point));

    // Allocate the memory block using malloc()
    void* mem_block = malloc(total_size);

    // Initialize the floating-point array with values representing the Euclidean distance from the origin (0, 0) for each 'struct point' object
    double* dist_array = (double*)mem_block;
    for (int i = 0; i < num_points; i++) {
        struct point p = {i, i};
        dist_array[i] = euclidean_distance(p);
    }

    // Initialize the char array with random values
    char* char_array = (char*)((double*)mem_block + num_points);
