    // Allocate memory for the point array and initialize it with zeros
    struct point *points = calloc(num_points, sizeof(struct point));

    // Read the identifiers from standard input
    int i;
    for (i = 0; i < num_points; i++) {
        int id;
        if (scanf("%d", &id) != 1 || id < 0 || id > UINT16_MAX) {
