// Define data structures for double, char string, and data point
typedef struct {
    double value;
    char *str;
    float timestamp;
} data_point;

// Define a linked list node structure for storing data points
typedef struct node {
    data_point *data;
    struct node *next;
} node;

// Define a custom memory pool for managing memory allocation
typedef struct {
    void **memory;
    size_t size;
    size_t used;
} memory_pool;

// Define a data structure for storing configuration parameters
typedef struct {
    int memory_pool_size;
    int data_pruning_interval;
    int thread_pool_size;
} config;

// Define a function for initializing the data structures and memory pool
void init(config *cfg) {
    // Initialize the linked list head pointer
    node *head = NULL;

    // Initialize the custom memory pool with the specified size
    memory_pool *mem_pool = malloc(sizeof(memory_pool));
    mem_pool->size = cfg->memory_pool_size;
    mem_pool->used = 0;
    mem_pool->memory = calloc(cfg->memory_pool_size, sizeof(void*));

    // Initialize the data pruning interval and thread pool size
    int data_pruning_interval = cfg->data_pruning_interval;
    int thread_pool_size = cfg->thread_pool_size;

    return head;
}

// Define a function for adding new data points to the linked list and memory pool
void add(node *head, data_point *data) {
    // Allocate memory for the new data point in the custom memory pool
    void *mem = malloc(sizeof(data_point));
    memcpy(mem, data, sizeof(data_point));

    // Update the timestamp of the new data point to the current system time
    ((data_point*)mem)->timestamp = (float)time(NULL);

    // Insert the new data point into the linked list
    node *new_node = malloc(sizeof(node));
    new_node->data = mem;
    new_node->next = head;
    head = new_node;

    return head;
}

// Define a function for retrieving data points from the linked list by their unique string identifier
void get(node *head, char *str) {
    // Iterate through the linked list until the desired data point is found
    while (head != NULL) {
        if (strcmp(((data_point*)head->data)->str, str) == 0) {
            return head->data;
        }
        head = head->next;
    }

    // If the desired data point is not found, return NULL
    return NULL;
}

// Define a function for removing outdated entries from the linked list and memory pool
void prune(node *head) {
    // Iterate through the linked list until an outdated entry is found
    while (head != NULL) {
        if (((data_point*)head->data)->timestamp < time(NULL) - cfg->data_pruning_interval) {
            node *to_delete = head;
            head = head->next;
            free(to_delete);
        } else {
            head = head->next;
        }
    }
}

