// Define a function for periodically checking and releasing unused memory blocks
void check_and_release() {
    // Check if any memory blocks are unused and release them if necessary
    for (int i = 0; i < mem_pool->size; i++) {
        if (mem_pool->memory[i] == NULL) {
            continue;
        } else {
            free(mem_pool->memory[i]);
            mem_pool->used--;
        }
    }
}

