    int size;
    struct record **records;
};

// Function to initialize the hash table, linked list, and balanced tree
void init(struct record_hash_table *ht, struct log_linked_list *ll, struct record_balanced_tree *bt) {
    // Initialize the hash table with a default size of 1024
    ht->size = 1024;
    ht->records = malloc(sizeof(struct record *) * ht->size);
    memset(ht->records, 0, sizeof(struct record *) * ht->size);

    // Initialize the linked list with a default size of 1024
    ll->head = NULL;
    ll->tail = NULL;

    // Initialize the balanced tree with a default size of 1024
