        if (tmp == NULL) {
            return;
        }
        tmp->next = r;
    }
}

// Function to retrieve a record from the hash table, linked list, and balanced tree by its identifier
struct record *get_record(struct record_hash_table *ht, struct log_linked_list *ll, struct record_balanced_tree *bt, int id) {
    // Retrieve the record from the hash table
    int index = id % ht->size;
    if (ht->records[index] == NULL) {
