#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the entry struct to hold the timestamp, severity level, and message
typedef struct {
    long timestamp;
    int severity_level;
    char* message;
} entry;

// Define a linked list node for storing entries
typedef struct {
    entry* data;
    struct node* next;
} node;

// Define the head of the linked list
node* head = NULL;

// Define the mutex for protecting the linked list from concurrent access
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new entry to the linked list
void add_entry(long timestamp, int severity_level, char* message) {
    // Lock the mutex before modifying the linked list
    pthread_mutex_lock(&mutex);

    // Create a new node for the entry
    node* new_node = malloc(sizeof(node));
    new_node->data = malloc(sizeof(entry));
    new_node->data->timestamp = timestamp;
    new_node->data->severity_level = severity_level;
    new_node->data->message = strdup(message);

    // Add the new node to the end of the linked list
    if (head == NULL) {
        head = new_node;
    } else {
        node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    // Unlock the mutex after modifying the linked list
    pthread_mutex_unlock(&mutex);
}

// Function to remove an entry from the linked list by timestamp
void remove_entry(long timestamp) {
    // Lock the mutex before modifying the linked list
    pthread_mutex_lock(&mutex);

    // Find the node with the matching timestamp
    node* current = head;
    while (current != NULL && current->data->timestamp != timestamp) {
        current = current->next;
    }

    // If the node is found, remove it from the linked list
    if (current != NULL) {
        // Remove the node from the linked list
        if (current == head) {
            head = current->next;
        } else {
            node* previous = head;
            while (previous->next != current) {
                previous = previous->next;
            }
            previous->next = current->next;
        }

        // Free the memory allocated for the entry and the node
        free(current->data);
        free(current);
    }

    // Unlock the mutex after modifying the linked list
    pthread_mutex_unlock(&mutex);
}

// Function to update the severity level of an existing entry in the linked list
void update_severity_level(long timestamp, int new_severity_level) {
    // Lock the mutex before modifying the linked list
    pthread_mutex_lock(&mutex);

    // Find the node with the matching timestamp
    node* current = head;
    while (current != NULL && current->data->timestamp != timestamp) {
        current = current->next;
    }

    // If the node is found, update its severity level
    if (current != NULL) {
        current->data->severity_level = new_severity_level;
    }

    // Unlock the mutex after modifying the linked list
    pthread_mutex_unlock(&mutex);
}

// Function to iterate over all entries in the linked list
void iterate_entries(void (*callback)(entry*)) {
    // Lock the mutex before iterating over the linked list
    pthread_mutex_lock(&mutex);

    // Iterate over all nodes in the linked list and call the callback function for each entry
    node* current = head;
    while (current != NULL) {
        callback(current->data);
        current = current->next;
    }

    // Unlock the mutex after iterating over the linked list
    pthread_mutex_unlock(&mutex);
}
