// Struct for storing data
struct data {
    int value;
    char* str;
    double dbl;
};

// Function to dynamically allocate memory for an array of structs
void allocate_array(struct data** arr, size_t n) {
    *arr = (struct data*)malloc(n * sizeof(struct data));
    if (*arr == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }
}

// Function to populate an array of structs with random values
void populate_array(struct data* arr, size_t n) {
    for (size_t i = 0; i < n; i++) {
        arr[i].value = rand() % 100;
        arr[i].str = (char*)malloc(10 * sizeof(char));
        if (arr[i].str == NULL) {
            printf("Memory allocation failed\n");
            exit(1);
        }
        sprintf(arr[i].str, "String %d", i);
        arr[i].dbl = rand() / (double)RAND_MAX;
    }
}

// Function to deallocate memory for an array of structs
void deallocate_array(struct data* arr, size_t n) {
    for (size_t i = 0; i < n; i++) {
        free(arr[i].str);
    }
    free(arr);
}

// Function to load initial data from an external CSV file
void load_data(struct data** arr, size_t* n) {
    FILE* fp = fopen("data.csv", "r");
    if (fp == NULL) {
        printf("Error opening file\n");
        exit(1);
    }
    // Read the number of lines in the file
    *n = 0;
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        (*n)++;
    }
    rewind(fp);
    allocate_array(arr, *n);
    for (size_t i = 0; i < *n; i++) {
        // Read the values from each line and populate the structs
        fscanf(fp, "%d,%[^,],%lf", &arr[i].value, arr[i].str, &arr[i].dbl);
    }
    fclose(fp);
}

// Function to handle memory allocation failures gracefully
void handle_failure() {
    printf("Memory allocation failed\n");
    exit(1);
}

int main() {
    struct data* arr;
    size_t n = 0;
    load_data(&arr, &n);
    populate_array(arr, n);
    deallocate_array(arr, n);
    return 0;
}
