#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define custom data structures and enums for log entries and data points
struct data {
    int id;
    char* name;
    double value;
};

enum severity_level {
    INFO, WARNING, ERROR
};

struct log_entry {
    time_t timestamp;
    char* message;
    enum severity_level level;
};

// Define a concurrent-safe data structure for managing memory and storing data points
typedef struct {
    int size;
    int capacity;
    void** data;
} data_store_t;

// Define a custom memory management strategy for char* pointers to minimize memory leaks and fragmentation
void free_char_ptr(void* ptr) {
    if (ptr != NULL) {
        free((char*)ptr);
    }
}

// Load initial data from two external CSV files into the data store
void load_data(data_store_t* store, const char* file1, const char* file2) {
    // Open and read the first file
    FILE* fp = fopen(file1, "r");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", file1);
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Parse the line and create a new data point
        int id = atoi(strtok(line, ","));
        char* name = strdup(strtok(NULL, ","));
        double value = atof(strtok(NULL, ","));
        struct data* data_point = malloc(sizeof(struct data));
        data_point->id = id;
        data_point->name = name;
        data_point->value = value;

        // Add the new data point to the store
        if (store->size == store->capacity) {
            store->capacity *= 2;
            store->data = realloc(store->data, store->capacity * sizeof(void*));
        }
        store->data[store->size++] = data_point;
    }

    // Close the file and free any memory allocated for reading it
    fclose(fp);
    free(line);

    // Open and read the second file
    fp = fopen(file2, "r");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", file2);
        return;
    }

    while (fgets(line, sizeof(line), fp)) {
        // Parse the line and create a new log entry
        time_t timestamp = atol(strtok(line, ","));
        char* message = strdup(strtok(NULL, ","));
        enum severity_level level = (enum severity_level)atoi(strtok(NULL, ","));
        struct log_entry* log_entry = malloc(sizeof(struct log_entry));
        log_entry->timestamp = timestamp;
        log_entry->message = message;
        log_entry->level = level;

        // Add the new log entry to the store
        if (store->size == store->capacity) {
            store->capacity *= 2;
            store->data = realloc(store->data, store->capacity * sizeof(void*));
        }
        store->data[store->size++] = log_entry;
    }

    // Close the file and free any memory allocated for reading it
    fclose(fp);
    free(line);
}

// Free all memory allocated by the data store
void free_data_store(data_store_t* store) {
    for (int i = 0; i < store->size; i++) {
        void* ptr = store->data[i];
        if (ptr != NULL) {
            if (ptr->type == DATA_POINT) {
                struct data* data_point = (struct data*)ptr;
                free(data_point->name);
                free(data_point);
            } else if (ptr->type == LOG_ENTRY) {
                struct log_entry* log_entry = (struct log_entry*)ptr;
                free(log_entry->message);
                free(log_entry);
            }
        }
    }
    free(store->data);
}

// Implement a concurrent-safe design to ensure that the function can handle multiple invocations simultaneously without data corruption
void* data_store_lock = NULL;
void lock_data_store() {
    if (data_store_lock == NULL) {
        data_store_lock = malloc(sizeof(pthread_mutex_t));
        pthread_mutex_init(data_store_lock, NULL);
    }
    pthread_mutex_lock(data_store_lock);
}

void unlock_data_store() {
    if (data_store_lock != NULL) {
        pthread_mutex_unlock(data_store_lock);
    }
}

// Implement a caching strategy to reduce redundant file reads
typedef struct {
    int size;
    char* filename;
    time_t timestamp;
    void* data;
} cache_entry_t;

int cache_size = 0;
cache_entry_t* cache = NULL;

void add_to_cache(const char* filename, time_t timestamp, void* data) {
    if (cache == NULL) {
        cache = malloc(sizeof(cache_entry_t));
        cache->size = 1;
        cache->filename = strdup(filename);
        cache->timestamp = timestamp;
        cache->data = data;
    } else {
        for (int i = 0; i < cache_size; i++) {
            if (strcmp(cache[i].filename, filename) == 0 && cache[i].timestamp == timestamp) {
                // Update the existing entry in the cache
                cache[i].data = data;
                return;
            }
        }
        // Add a new entry to the cache
        cache_size++;
        cache = realloc(cache, cache_size * sizeof(cache_entry_t));
        cache[cache_size - 1].filename = strdup(filename);
        cache[cache_size - 1].timestamp = timestamp;
        cache[cache_size - 1].data = data;
    }
}

void* get_from_cache(const char* filename, time_t timestamp) {
    if (cache == NULL) {
        return NULL;
    }
    for (int i = 0; i < cache_size; i++) {
        if (strcmp(cache[i].filename, filename) == 0 && cache[i].timestamp == timestamp) {
            // Return the data from the cache
            return cache[i].data;
        }
    }
    return NULL;
}

// Optimize for both memory efficiency and I/O performance by exploring caching strategies to reduce redundant file reads
void* load_data_from_file(const char* filename, time_t timestamp) {
    // Check if the data is already in the cache
    void* data = get_from_cache(filename, timestamp);
    if (data != NULL) {
        return data;
    }

    // Load the data from the file and add it to the cache
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return NULL;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Parse the line and create a new data point
        int id = atoi(strtok(line, ","));
        char* name = strdup(strtok(NULL, ","));
        double value = atof(strtok(NULL, ","));
        struct data* data_point = malloc(sizeof(struct data));
        data_point->id = id;
        data_point->name = name;
        data_point->value = value;

        // Add the new data point to the cache
        add_to_cache(filename, timestamp, data_point);
    }

    // Close the file and free any memory allocated for reading it
    fclose(fp);
    free(line);

    return data;
}
