// Custom allocator for managing memory pools
class MemoryPool {
public:
    MemoryPool(size_t size) : size_(size), used_(0) {}

    void* allocate(size_t size) {
        if (used_ + size > size_) {
            return nullptr;
        }
        void* ptr = &data_[used_];
        used_ += size;
        return ptr;
    }

private:
    std::vector<char> data_;
    size_t size_;
    size_t used_;
};

// Custom allocator for managing memory pools
class MemoryPoolAllocator {
public:
    MemoryPoolAllocator(size_t size) : pool_(new MemoryPool(size)) {}

    void* allocate(size_t size) {
        return pool_->allocate(size);
    }

private:
    std::unique_ptr<MemoryPool> pool_;
};

// Custom lock-free data structure for managing frame distribution
class FrameDistribution {
public:
    FrameDistribution() : frames_(new std::unordered_map<int, int>) {}

    void addFrame(int frame) {
        std::lock_guard<std::mutex> lock(mutex_);
        frames_->insert({frame, 0});
    }

    void removeFrame(int frame) {
        std::lock_guard<std::mutex> lock(mutex_);
        frames_->erase(frame);
    }

    int getNextFrame() {
        std::lock_guard<std::mutex> lock(mutex_);
        if (frames_->empty()) {
            return -1;
        }
        auto it = frames_->begin();
        int frame = it->first;
        it->second++;
        return frame;
    }

