#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>
#include <errno.h>
#include <limits.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdbool.h>

#define MAX_COMMAND_LENGTH 4096
#define MAX_PROCESSES 1024
#define MAX_FILES 1024
#define MAX_MEASUREMENTS 1024
#define MAX_FILENAME_LENGTH 256
#define MAX_ERROR_MESSAGE_LENGTH 1024
#define RESTART_DELAY 30 // seconds
#define CPU_THRESHOLD 80 // percentage
#define MEMORY_THRESHOLD 90 // percentage

// Command structure
typedef struct {
    char *command;
    int pid;
} command_t;

// File structure
typedef struct {
    char filename[MAX_FILENAME_LENGTH];
    int measurements[MAX_MEASUREMENTS];
    int num_measurements;
} file_t;

// Global variables
command_t commands[MAX_PROCESSES];
file_t files[MAX_FILES];
int num_commands = 0;
int num_files = 0;
bool running = true;
sem_t *semaphore;

// Function declarations
void handle_signal(int signal);
void execute_command(char *command, int pid);
void process_file(char *filename);
void monitor_health();
void restart_program();

int main() {
    // Initialize semaphore
    semaphore = sem_open("/semaphore", O_CREAT, 0644, 1);
    if (semaphore == SEM_FAILED) {
        perror("Failed to create semaphore");
        return 1;
    }

    // Set up signal handling
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set up signal handling");
        return 1;
    }

    // Start monitoring health
    pthread_t monitor_thread;
    if (pthread_create(&monitor_thread, NULL, monitor_health, NULL)) {
        perror("Failed to create monitor thread");
        return 1;
    }

    while (running) {
        // Wait for semaphore
        if (sem_wait(semaphore) == -1) {
            perror("Failed to wait for semaphore");
            break;
        }

        // Execute commands and process files
        int i;
        for (i = 0; i < num_commands; i++) {
            execute_command(commands[i].command, commands[i].pid);
        }
        for (i = 0; i < num_files; i++) {
            process_file(files[i].filename);
        }
    }

    // Clean up
    sem_close(semaphore);
    pthread_join(monitor_thread, NULL);

    return 0;
}

void handle_signal(int signal) {
    if (signal == SIGINT) {
        running = false;
    }
}

void execute_command(char *command, int pid) {
    // Create new process group for command
    setpgid(0, 0);

    // Execute command
    char *args[3];
    args[0] = "sh";
    args[1] = "-c";
    args[2] = command;
    if (execvp("sh", args) == -1) {
        perror("Failed to execute command");
    }
}

void process_file(char *filename) {
    // Open file and read measurements
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Failed to open file");
        return;
    }
    int i = 0;
    while (fscanf(fp, "%d", &files[num_files].measurements[i]) != EOF && i < MAX_MEASUREMENTS) {
        i++;
    }
    files[num_files].num_measurements = i;
    fclose(fp);

    // Process measurements
    for (int j = 0; j < files[num_files].num_measurements; j++) {
        // TODO: process measurements here
    }
}

void monitor_health() {
    while (running) {
        // Check CPU and memory usage
        struct rusage usage;
        getrusage(RUSAGE_SELF, &usage);
        if (usage.ru_utime.tv_sec > RESTART_DELAY || usage.ru_stime.tv_sec > RESTART_DELAY) {
            restart_program();
        } else if (usage.ru_maxrss / 1024 > CPU_THRESHOLD || usage.ru_ixrss / 1024 > MEMORY_THRESHOLD) {
            sem_post(semaphore); // signal to restart program
        }
    }
}

