// Define the DNS resolution function
int dns_resolve(const char* hostname, struct in_addr* addr) {
  // Initialize the DNS resolver context
  struct __res_state res;
  memset(&res, 0, sizeof(struct __res_state));

  // Set the DNS resolution timeout
  res.retrans = DNS_RESOLUTION_TIMEOUT;

  // Perform the DNS resolution
  int status = res_nquery(&res, hostname, C_IN, T_A, &addr->s_addr, sizeof(struct in_addr));

