// Define a structure to hold the 'record' data
typedef struct {
    int value;
    int* key;
    long* offset;
} record_t;

// Function to manage memory for three separate arrays: one for 'long' offset values, one for 'int' keys, and another for 'record' structures
void manage_memory(size_t num_records, int min_value, int max_value, unsigned seed) {
    // Initialize the random number generator with a seed value
    srand(seed);

    // Allocate memory for the offset array
    long* offsets = (long*)malloc(num_records * sizeof(long));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offset array\n");
        return;
    }

    // Allocate memory for the key array
    int* keys = (int*)malloc(num_records * sizeof(int));
    if (!keys) {
        printf("Error: Failed to allocate memory for key array\n");
        free(offsets);
        return;
    }

    // Allocate memory for the record structures
    record_t* records = (record_t*)malloc(num_records * sizeof(record_t));
    if (!records) {
        printf("Error: Failed to allocate memory for record structures\n");
        free(offsets);
        free(keys);
        return;
    }

    // Set the value of each record's 'int' field to a random value within the specified range
    for (size_t i = 0; i < num_records; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        records[i].key = &keys[i];
        records[i].offset = &offsets[i];
    }

    // Print the value of each 'int' field and ensure all allocated memory is properly freed before returning
    for (size_t i = 0; i < num_records; i++) {
        printf("Record %zu: value=%d, key=%d, offset=%ld\n", i, records[i].value, *(records[i].key), *(records[i].offset));
    }

    free(offsets);
    free(keys);
    free(records);
}
```
